//! translate_rust.backend.zig.lower — Lowering engine from RustIr to ZigAST.
//!
//! Transforms target-agnostic semantic IR (RustIr) into a structured Zig package AST
//! (ast.Package). Handles module-to-file mapping, item translation, method hoisting
//! (injecting inherent and trait impl methods into struct/enum bodies), type mapping
//! via pluggable LoweringStrategy, and full expression/statement/pattern lowering.

const std = @import("std");
const ir = @import("translate_rust.ir");
const ast = @import("ast.zig");
const documentation = @import("documentation.zig");
const strategy = @import("../strategy.zig");
const default_strat = @import("strategies/default.zig");

/// Lower a complete Rust semantic model (RustIr) into a target-language Zig package.
/// Use an arena allocator. The package and lowering scratch share its lifetime;
/// release the arena only after all package consumers finish.
pub fn lowerRustIr(
    allocator: std.mem.Allocator,
    rust_ir: *const ir.RustIr,
    custom_strat: ?*const strategy.LoweringStrategy,
) !ast.Package {
    var lowerer = Lowerer.init(allocator, rust_ir, custom_strat);
    const package = try lowerer.lowerPackage();
    return package;
}

const OwnedCollectionPlan = struct {
    range_id: ir.exprs.NodeId,
    source_id: ir.exprs.NodeId,
    item_name: []const u8,
};
const OwnedTemporaryPlan = struct {
    return_type: ir.types.Type,
};
const ValueCaptureScope = struct {
    names: []const []const u8,
    value_name: ?[]const u8,
};
const ShadowScope = struct {
    names: []const []const u8,
    parent: ?*const ShadowScope,
};
/// One `match` arm's lowered body and guard, both lowered under the shadow
/// scope of the bindings its own pattern introduces.
const LoweredMatchArm = struct {
    value: ast.Expr,
    guard: ?*const ast.Expr,
};
/// One `match` arm's lowered selectors plus the reference capture it needs.
const LoweredMatchSelectors = struct {
    patterns: []ast.Pattern,
    capture: ?ast.Capture,
};
/// The local an optional scrutinee is bound to before its arms dispatch.
///
/// `by_place` says the local holds the ADDRESS of the scrutinee rather than a
/// copy of it. A copy is right for every arm that reads the payload by value,
/// but `Some(ref mut slot)` names the storage the caller's own optional holds,
/// and a pointer taken into a copy lands in this frame instead. Rust admits a
/// reference binding only over a place — the temporary a call makes is dropped
/// before the arms run — so the address form needs a scrutinee whose own place
/// exists, and every other optional match keeps the copy.
const OptionalMatchSubject = struct {
    /// The name the match lowering binds the scrutinee to.
    name: []const u8,
    /// Whether that local holds the scrutinee's address rather than a copy.
    by_place: bool = false,
};
/// The mutable alias a `match` arm's owned payload is released through.
///
/// The emitter writes a by-value payload capture as `|name|`, so Zig makes that
/// binding `const` and nothing this lowering emits can make it mutable. The
/// alias is the arm's own mutable owner of the same storage, and the arm body
/// is lowered to read the alias: a helper that transfers the payload in place
/// then receives the `*T` it needs, and the release finds an alias the
/// transfer already emptied.
const OwnedCaptureAlias = struct {
    /// The source name of the payload binding, which is the key
    /// `activeClosureCaptureOverride` resolves.
    source_name: []const u8,
    /// The name the emitter gives the capture, which the alias is built from.
    capture_name: []const u8,
    /// The mutable alias the arm body reads and the release frees.
    alias_name: []const u8,
    /// The payload's own Rust type, which is what the runtime transfer is
    /// instantiated with.
    payload_type: ir.types.Type,
};
/// A source parameter and the arguments of its individual call site.
const DeclaredParameterSite = struct {
    def: ir.spine.EntityId,
    param_index: usize,
    param_args: []const ir.exprs.NodeId,
    explicit: []const ir.types.Type,
    expr_id: ir.exprs.NodeId,
    declared: ir.types.Type,
};

const CallInstantiation = struct {
    names: []const []const u8,
    args: []const ir.types.Type,
};

fn typeParameterIsBound(
    name: []const u8,
    inherited: []const []const u8,
    own: []const []const u8,
) bool {
    for (inherited) |candidate| {
        if (std.mem.eql(u8, candidate, name)) return true;
    }
    for (own) |candidate| {
        if (std.mem.eql(u8, candidate, name)) return true;
    }
    return false;
}
/// An owned payload alias together with the reads of it that hand the
/// payload on rather than borrow it.
const OwnedCaptureMove = struct {
    alias: OwnedCaptureAlias,
    /// Expression ids whose VALUE IS the payload, so reading one transfers
    /// the owner and has to empty the alias to do it.
    sites: std.AutoHashMapUnmanaged(ir.exprs.NodeId, void),
};
/// Captured owners and their by-value reads in one lowered body.
const OwnedCaptureMoveSet = struct {
    entries: []const OwnedCaptureMove,

    fn aliasAtSite(self: OwnedCaptureMoveSet, expr_id: ir.exprs.NodeId) ?OwnedCaptureAlias {
        for (self.entries) |entry| {
            if (entry.sites.contains(expr_id)) return entry.alias;
        }
        return null;
    }
};
/// One lexical scope's owner binding: the mutable handle its release runs on,
/// and the reads of that handle which hand the owner ON rather than borrow it.
///
/// This is deliberately the same shape a match arm's payload uses, because the
/// two are the same mechanism: the release is unconditional and every move
/// empties the handle in place, which is exactly what makes one defer correct
/// on the path that moved and on the path that did not.
///
/// It differs in two ways. The handle is the BINDING ITSELF rather than an
/// alias copied out of a `const` capture, because a binding this pass declares
/// owns mutable storage already and copying it would leave two names for one
/// allocation. And it is keyed by the binding's `EntityId` rather than by its
/// source name, because two bindings may share a name across nested scopes and
/// are then two different values owing two different releases — a name-keyed
/// table would conflate them and either free one allocation twice or free
/// neither.
const OwnedScopeBinding = struct {
    /// The binding entity this owner IS. This is what tells two bindings of the
    /// same source name apart.
    def: ir.spine.EntityId,
    /// The alias fields, reused unchanged: for a lexical owner both
    /// `alias_name` and `capture_name` are the binding's own emitted name.
    alias: OwnedCaptureAlias,
    /// Expression ids that read the binding in a hand-off position.
    sites: std.AutoHashMapUnmanaged(ir.exprs.NodeId, void),
};
/// One arm of the ordered chain a guarded `match` lowers to.
///
/// The arm is lowered before the chain's label exists, because whether any arm
/// carries a result is what says whether the chain needs a label at all, and
/// that cannot be known until every arm is in hand.
const GuardChainArm = struct {
    patterns: []ast.Pattern,
    capture: ?ast.Capture,
    /// Field bindings, and the optional payload read-back, that must run
    /// before the guard reads a name the arm's own pattern introduced.
    prelude: []const ast.Stmt,
    guard: ?*const ast.Expr,
    value: ast.Expr,
    /// A refutable payload pattern nested inside this arm's selector, which
    /// becomes one more ordered dispatch instead of one unconditional read.
    nested: ?*const NestedPayloadDispatch,
};

/// Bound recursive payload-pattern traversal before building dispatch nodes.
const nested_pattern_depth_limit: usize = 32;

/// A payload pattern the arm's OWN dispatch cannot express.
///
/// Zig's switch prong writes the tag of a struct pattern and drops its fields,
/// and the emitter has no place to put a second test. `Err(IoError(e))` names
/// a variant INSIDE the payload of `Err`, so the arm needs the outer tag and
/// then the inner one — and the binding is only valid once the inner tag
/// matches, because reading a union field that is not active is what Zig
/// refuses.
///
/// It becomes one more ordered dispatch rather than one unconditional read: a
/// payload of another variant falls out of the prong and reaches the arms Rust
/// lists after this one, exactly as an arm whose guard failed does.
const NestedPayloadDispatch = struct {
    /// The selected payload from the enclosing prong.
    subject: *const ast.Expr,
    /// Selectors for the nested payload — the inner tag and its own binding.
    selectors: []ast.Pattern,
    /// The nested pattern's OWN field bindings, read out of its payload.
    bindings: []const ast.Stmt,
    /// A deeper dispatch, when this payload's pattern names a payload too.
    inner: ?*const NestedPayloadDispatch,
};
const LocalClosureCaptureSnapshot = struct {
    source_name: []const u8,
    snapshot_name: []const u8,
    payload_type: ?ir.types.Type,
};
const IteratorStructuralState = struct {
    enumerate_indices: []const []const u8,
    enumerate_items: []const []const u8,
    zip_indices: []const []const u8,
    zip_rights: []const []const u8,
    zip_items: []const []const u8,
    zip_right_by_ref: []const bool,
};
/// One `for` input that is a runtime iterator rather than a value a Zig
/// `for` can walk. The loop header cannot list it, so the iterator is
/// hoisted into a `var` and pulled with `next`.
const RuntimeIteratorInput = struct {
    /// Name of the hoisted `var` that holds the iterator.
    binding: []const u8,
    /// `binding.next()`: the call that yields this input's next item.
    step: *const ast.Expr,
    /// The `while` capture name when this input drives the loop.
    capture: ?[]const u8,
};
const IteratorRangeDirection = enum {
    forward,
    reverse,
};

fn nameInList(names: []const []const u8, candidate: []const u8) bool {
    for (names) |name| {
        if (std.mem.eql(u8, name, candidate)) return true;
    }
    return false;
}

/// Identifiers Zig reserves at container scope. A module named `error` is
/// ordinary Rust, but `error.FromHexError` then reads as an error *value*
/// rather than the imported type, and `const error = ...` does not compile at
/// all — the emitter can only escape the declaration as `@"error"`, which
/// leaves every reference pointing at the built-in. An import alias must
/// therefore avoid these names.
fn isReservedZigIdentifier(name: []const u8) bool {
    const reserved = [_][]const u8{
        "addrspace",    "align",       "allowzero", "and",            "anyerror",
        "anyframe",     "anyopaque",   "anytype",   "asm",            "async",
        "await",        "break",       "callconv",  "c_int",          "c_long",
        "c_longdouble", "c_longlong",  "c_short",   "c_uint",         "c_ulong",
        "c_ulonglong",  "c_ushort",    "catch",     "comptime",       "comptime_float",
        "comptime_int", "const",       "continue",  "defer",          "else",
        "enum",         "errdefer",    "error",     "export",         "extern",
        "f128",         "f16",         "f32",       "f64",            "f80",
        "false",        "fn",          "for",       "i128",           "i16",
        "i32",          "i64",         "i8",        "if",             "inline",
        "isize",        "linksection", "noalias",   "noinline",       "noreturn",
        "nosuspend",    "null",        "opaque",    "or",             "orelse",
        "packed",       "pub",         "resume",    "return",         "struct",
        "suspend",      "switch",      "test",      "threadlocal",    "true",
        "try",          "type",        "u128",      "u16",            "u32",
        "u64",          "u8",          "usize",     "usingnamespace", "var",
        "void",         "volatile",    "while",     "undefined",
    };
    for (reserved) |word| {
        if (std.mem.eql(u8, name, word)) return true;
    }
    return false;
}

const IteratorRangeTail = struct {
    id: ir.exprs.NodeId,
};
const LoweredIteratorRange = struct {
    start: ast.Expr,
    end: ast.Expr,
    item_type: ast.Type,
    inclusive: bool,
};
const IteratorRangeLoop = struct {
    direction: IteratorRangeDirection,
    inclusive: bool,
    start_name: []const u8,
    end_name: []const u8,
    cursor_name: []const u8,
    done_name: ?[]const u8,
    item: ast.Expr,
};

const LocalBindingNames = struct {
    callable_id: ?ir.spine.EntityId = null,
    local_defs: []const ir.spine.EntityId = &.{},
    local_claimed: []bool = &.{},
    emitted_by_entity: std.AutoHashMapUnmanaged(ir.spine.EntityId, []const u8) = .empty,
    emitted_by_pattern: std.AutoHashMapUnmanaged(ir.exprs.NodeId, []const u8) = .empty,
    /// The binding entity each pattern claimed, beside the name it was emitted
    /// under. Two bindings can share a source name in nested scopes, and only
    /// the entity tells them apart — which is what lets the owner release key
    /// on identity instead of on spelling.
    def_by_pattern: std.AutoHashMapUnmanaged(ir.exprs.NodeId, ir.spine.EntityId) = .empty,
    used_names: std.StringHashMapUnmanaged(void) = .empty,

    fn deinit(self: *LocalBindingNames, allocator: std.mem.Allocator) void {
        if (self.local_defs.len > 0) allocator.free(self.local_defs);
        if (self.local_claimed.len > 0) allocator.free(self.local_claimed);
        self.emitted_by_entity.deinit(allocator);
        self.emitted_by_pattern.deinit(allocator);
        self.def_by_pattern.deinit(allocator);
        self.used_names.deinit(allocator);
        self.* = undefined;
    }

    fn claimLocal(self: *LocalBindingNames, symbol_table: *const ir.spine.SymbolTable, name: []const u8) ?ir.spine.EntityId {
        for (self.local_defs, 0..) |def, index| {
            if (self.local_claimed[index]) continue;
            const entity = symbol_table.get(def) orelse continue;
            if (!std.mem.eql(u8, entity.name, name)) continue;
            self.local_claimed[index] = true;
            return def;
        }
        return null;
    }

    fn claimLocalName(
        self: *LocalBindingNames,
        symbol_table: *const ir.spine.SymbolTable,
        name: []const u8,
    ) []const u8 {
        const def = self.claimLocal(symbol_table, name);
        return if (def) |d|
            self.emitted_by_entity.get(d) orelse name
        else
            name;
    }

    fn claimPatternName(
        self: *LocalBindingNames,
        allocator: std.mem.Allocator,
        symbol_table: *const ir.spine.SymbolTable,
        pat_id: ir.exprs.NodeId,
        name: []const u8,
    ) ![]const u8 {
        return self.claimPatternAlias(allocator, symbol_table, pat_id, name, null);
    }

    fn claimPatternAlias(
        self: *LocalBindingNames,
        allocator: std.mem.Allocator,
        symbol_table: *const ir.spine.SymbolTable,
        pat_id: ir.exprs.NodeId,
        name: []const u8,
        canonical: ?[]const u8,
    ) ![]const u8 {
        if (self.emitted_by_pattern.get(pat_id)) |existing| {
            return existing;
        }
        const def = self.claimLocal(symbol_table, name);
        const emitted = canonical orelse if (def) |d|
            self.emitted_by_entity.get(d) orelse name
        else
            name;
        if (canonical != null) {
            if (def) |d| try self.emitted_by_entity.put(allocator, d, emitted);
        }
        try self.emitted_by_pattern.put(allocator, pat_id, emitted);
        if (def) |claimed| try self.def_by_pattern.put(allocator, pat_id, claimed);
        return emitted;
    }
};
const TraitDescriptorRequest = struct {
    trait_id: ir.spine.EntityId,
    owner_module_id: ir.spine.EntityId,
    name: []const u8,
};

const HashWalkRequest = struct {
    owner_module_id: ir.spine.EntityId,
    value_name: []const u8,
    slice_name: []const u8,
    is_allocating: bool = false,
    is_fallible: bool = false,
};

/// Moves a loop's SOURCE label off its body block and onto the loop.
///
/// The IR records the label where the parser puts it, on the block that holds
/// the loop's body, but a label belongs to the loop: Zig can only label a loop
/// from outside it, and a labelled exit names the loop rather than any block
/// inside it. Leaving the label on the body would make the emitter label the
/// body, which stops `continue 'label` from reaching the loop at all.
///
/// Only a label the source wrote is taken. A body block whose label arrived by
/// adopting a flattened tail's — the ordered chain a guarded `match` lowers to,
/// which `lowerBlock` flattens into the block that holds it — names the value
/// that block's own statements hand out through `break :<label>`. The loop
/// must not claim it: a guarded match that is a loop's whole body keeps the
/// chain's exits inside the chain, which is what lets the loop be emitted
/// around a block rather than around a chain of its own.
fn takeLoopLabel(source_label: ?[]const u8, body: *ast.Block) ?[]const u8 {
    if (source_label == null) return null;
    const label = body.label;
    body.label = null;
    return label;
}

/// Move a loop body's tail expression into its statement list.
///
/// A Rust `for`, `while` and `loop` body is `()`: whatever its last
/// expression evaluates to, the iteration performs it and throws the value
/// away. Zig would instead read that tail as the loop BODY BLOCK's value,
/// which is a different thing — it makes the body a labelled block whose
/// `break` carries an expression no one asked for — and every loop shape that
/// rebuilds the body as a statement list (the runtime-iterator `while`, the
/// typed range loop, the iterator adapter sink) drops it entirely. The
/// statement is what the source means, so it is made once here, on the one
/// path every loop lowering takes, and it runs exactly once per iteration.
fn takeLoopTailAsStatement(
    allocator: std.mem.Allocator,
    body: *ast.Block,
) std.mem.Allocator.Error!void {
    const tail = body.expr orelse return;
    body.expr = null;
    const statements = try allocator.alloc(ast.Stmt, body.stmts.len + 1);
    @memcpy(statements[0..body.stmts.len], body.stmts);
    statements[body.stmts.len] = .{ .expr_stmt = tail };
    body.stmts = statements;
}

fn allocationAssertionCondition(
    reason: []const u8,
    node_id: ir.exprs.NodeId,
    expr_count: usize,
) ?ir.exprs.NodeId {
    const prefix = "assertion:";
    if (!std.mem.startsWith(u8, reason, prefix)) return null;
    const suffix = reason[prefix.len..];
    if (suffix.len == 0) return null;
    for (suffix) |character| {
        if (character < '0' or character > '9') return null;
    }
    const condition = std.fmt.parseInt(ir.exprs.NodeId, suffix, 10) catch return null;
    if (condition >= expr_count or condition == node_id) return null;
    return condition;
}

/// Whether an external nominal path is the one a second path names, however
/// the source spelled either of them (`std` versus `core`, and so on).
fn externalPathEqual(path: []const []const u8, expected: []const []const u8) bool {
    if (path.len != expected.len) return false;
    for (path, expected) |actual, wanted| {
        if (!std.mem.eql(u8, actual, wanted)) return false;
    }
    return true;
}

/// Cargo treats `-` and `_` as one character in a package name, so a manifest
/// may spell the same package either way. Deliberate twin of the frontend's
/// `normalizedCrateNameEqual` (src/frontend/ts_ext.zig): the backend does not
/// import the frontend, so the two must be changed together.
fn normalizedPackageNameEqual(left: []const u8, right: []const u8) bool {
    if (left.len != right.len) return false;
    for (left, right) |a, b| {
        if ((if (a == '-') @as(u8, '_') else a) !=
            (if (b == '-') @as(u8, '_') else b)) return false;
    }
    return true;
}

/// Whether a declared dependency needs source, is runtime-bound, or is unavailable.
const DependencyDisposition = enum {
    /// A path dependency emits an import and a zon entry.
    source_needed,
    /// All reachable items are bound or erased; no module alias is emitted.
    runtime_bound,
    /// Neither readable source nor a complete runtime binding is available.
    unavailable,
};

/// Borrowed Cargo key and package name with their shared disposition.
const DependencyEntry = struct {
    local_alias: []const u8,
    extern_name: []const u8,
    disposition: DependencyDisposition,
};

/// `rand_core` 0.5's used surface is bound before dependencies are emitted:
/// `impls::fill_bytes_via_next` becomes the RNG core call, source trait bounds
/// are erased, `Self::Seed` is resolved by the frontend, and `Error` maps to
/// `r2z.random.Error`. Unbound types and calls retain their typed refusals.
/// Package identity comes from `extern_name`, not a renamed dependency key.
fn dependencyDisposition(dependency: ir.graph.CrateDep) DependencyDisposition {
    // Readable path dependencies keep their existing package imports.
    if (dependency.path != null) return .source_needed;
    // This pipeline does not vendor git checkouts.
    if (dependency.git != null) return .unavailable;
    // The frontend filters inactive dependencies; optional ones are not erased here.
    if (dependency.optional) return .unavailable;
    if (!normalizedPackageNameEqual(dependency.extern_name, "rand_core")) return .unavailable;
    // Bind only the supported version requirement; never infer a registry version.
    const version = dependency.version orelse return .unavailable;
    if (!std.mem.eql(u8, version, "0.5") and !std.mem.eql(u8, version, "0.5.1")) {
        return .unavailable;
    }
    // Require the complete, known-empty feature closure before omitting source.
    if (dependency.default_features == false or !dependency.resolved_features_known_empty) return .unavailable;
    return .runtime_bound;
}

/// The Zig error set a standard error type lowers to, or null when it lowers
/// to an ordinary runtime type.
///
/// This is the one answer to "is this error a set", shared by the type
/// lowering that spells the union and by every constructor, `?` and match that
/// has to decide whether the error lives bare or in a tagged `Result`.
fn externalErrorSetName(ty: ir.types.Type) ?[]const u8 {
    const external = switch (ty) {
        .external_nominal => |value| value,
        else => return null,
    };
    if (external.args.len != 0) return null;
    if (!externalPathEqual(external.path, &.{ "core", "fmt", "Error" }) and
        !externalPathEqual(external.path, &.{ "std", "fmt", "Error" }))
    {
        return null;
    }
    return "std.Io.Writer.Error";
}

/// The `Result` shape a type names, whatever carrier the IR used to spell it.
///
/// `std::fmt::Result` IS `Result<(), std::fmt::Error>`; the type lowering
/// writes that alias straight to an error union instead of through a
/// descriptor, so a caller that wants the ok/err pair `Ok`/`Err` and `?` read
/// has to be told the same thing here. Everything else is the descriptor the
/// frontend recorded.
fn resultDescriptorOf(ty: ir.types.Type) ?ir.types.Result {
    return switch (ty) {
        .result => |descriptor| descriptor.*,
        .external_nominal => |external| blk: {
            if (external.args.len != 0) break :blk null;
            if (!externalPathEqual(external.path, &.{ "core", "fmt", "Result" }) and
                !externalPathEqual(external.path, &.{ "std", "fmt", "Result" }))
            {
                break :blk null;
            }
            break :blk .{
                .ok = .{ .tuple = &.{} },
                .err = .{ .external_nominal = .{
                    .path = &.{ "std", "fmt", "Error" },
                    .args = &.{},
                } },
                .is_error_unionable = true,
            };
        },
        else => null,
    };
}

/// The type declaration an entity's `impl` methods belong to, or null when its
/// parent names no type.
///
/// An inherent `impl Target` and a trait `impl Trait for Target` are both
/// parented to `Target`, so `collectHoistedMethods` and the struct-body
/// question answer through this one rule. Any other parent — a block-local
/// helper, whose parent is a function — hoists nothing, and an `impl` with no
/// parent at all is the one shape that is not "no target": it is refused by
/// the caller rather than skipped.
fn hoistTargetFor(parent_ent: ir.spine.Entity) ?ir.spine.EntityId {
    return switch (parent_ent.kind) {
        .struct_, .enum_, .union_ => parent_ent.id,
        .impl_ => parent_ent.parent,
        else => null,
    };
}

/// Whether a hoist target is a type this crate DECLARES, so its methods can
/// live inside it as Zig struct members.
///
/// `hoistTargetFor` answers with the impl's own parent, which for a top-level
/// `impl Trait for ForeignType` is the enclosing MODULE. A module is not a
/// type, so the declarations collected under it are module-scope free
/// functions, and a call site has to name them rather than reach for a member
/// the receiver's own type never had.
fn isDeclaredTypeTarget(ent: ir.spine.Entity) bool {
    return switch (ent.kind) {
        .struct_, .enum_, .union_ => true,
        else => false,
    };
}

/// The declaration id of a method that was hoisted to MODULE scope, or null
/// when it stayed a member of a type this crate declares.
///
/// `impl From<PercentDecode> for Cow<[u8]>` has no struct to collect its
/// `from` into: the self type is an external type, so the function is emitted
/// at module scope under a name of its own and takes the converted value as
/// its first declared parameter. The same is true of any two impl blocks that
/// declare the same method name for different self types — the later one is a
/// different function and gets its own name — so this is a property of the
/// hoist, never of the spelling.
fn moduleHoistedImplMethod(
    self: *const Lowerer,
    method: ir.spine.EntityId,
) ?ir.spine.EntityId {
    const entity = self.ir.graph.symbol_table.get(method) orelse return null;
    if (entity.kind != .fn_) return null;
    const impl_id = entity.parent orelse return null;
    const impl_entity = self.ir.graph.symbol_table.get(impl_id) orelse return null;
    if (impl_entity.kind != .impl_) return null;
    const target_id = hoistTargetFor(impl_entity) orelse return null;
    const target = self.ir.graph.symbol_table.get(target_id) orelse return null;
    if (isDeclaredTypeTarget(target)) return null;
    if (self.hoisted_method_names.get(method) == null) return null;
    return method;
}

/// Whether a hoisted module-scope function takes its self value by address.
///
/// A `fn method(&self, ..)` declares a pointer parameter, so a free-function
/// call site has to hand over the address a member call would have taken
/// implicitly; a `fn method(self, ..)` declares the value itself and is handed
/// it as is. Only the impl's own self type answers, so an ordinary first
/// parameter is never mistaken for the receiver.
fn hoistedSelfParameterIsBorrow(
    self: *const Lowerer,
    method: ir.spine.EntityId,
) bool {
    if (method >= self.ir.bodies.bodies.len) return false;
    const function = switch (self.ir.bodies.bodies[method]) {
        .fn_ => |body| body,
        else => return false,
    };
    if (function.params.len == 0) return false;
    const entity = self.ir.graph.symbol_table.get(method) orelse return false;
    const impl_id = entity.parent orelse return false;
    const impl_entity = self.ir.graph.symbol_table.get(impl_id) orelse return false;
    const impl_body = implBodyFor(self.ir.bodies.bodies, impl_entity) orelse return false;
    return switch (function.params[0].ty) {
        .reference => |reference| Lowerer.typeEquals(reference.pointee, impl_body.self_ty),
        .raw_ptr => |pointer| Lowerer.typeEquals(pointer.pointee, impl_body.self_ty),
        else => false,
    };
}

/// The body of an `impl` block, or null when `ent` is not one.
fn implBodyFor(bodies: []const ir.bodies.BodyKind, ent: ir.spine.Entity) ?ir.bodies.ImplBody {
    if (ent.kind != .impl_) return null;
    if (ent.id >= bodies.len) return null;
    return switch (bodies[ent.id]) {
        .impl_ => |body| body,
        else => null,
    };
}

/// Whether `ty` is the runtime's OWNED `String` — the one conversion target
/// whose construction takes the enclosing callable's allocator, because it
/// copies the bytes it borrows. `str`, `&str` and every non-allocation type
/// are not it, and a `From` into one of those allocates nothing at all.
fn isOwnedStringType(ty: ir.types.Type) bool {
    return switch (ty) {
        .external_nominal => |external| external.args.len == 0 and
            (externalPathEqual(external.path, &.{ "alloc", "string", "String" }) or
                externalPathEqual(external.path, &.{ "std", "string", "String" })),
        else => false,
    };
}

/// Whether `ty` is Rust's `str` primitive or a BORROW of it.
///
/// `&str` reaches the backend as `.reference{ .pointee = str_type }`: the
/// frontend preserves the borrow rather than erasing it to the pointee, and
/// only `lowerType` collapses the pair back into one `[]const u8`. Every
/// reader that asks "is this the `str` primitive?" has to answer for the
/// borrow too, or a method the source called on a `&str` is refused for
/// wanting a type it does have. `&[u8]` is a DIFFERENT IR type that happens
/// to share the Zig ABI, and `&mut str` is still `str`, so neither is
/// confused with the other here.
fn canonicalBorrowedStr(ty: ir.types.Type) bool {
    if (ir.types.isStr(ty)) return true;
    return switch (ty) {
        .reference => |reference| ir.types.isStr(reference.pointee),
        else => false,
    };
}

/// Whether `lowerType` renders a borrow of `pointee` AS the borrow itself.
///
/// Rust's `&str` and `&[T]` borrow a fat pointer, and Zig spells both as a
/// slice, so there is no pointee behind them to read out of. A `&T` for a
/// sized `T` lowers to `*const T` and does have one.
fn isSliceShapedBorrow(pointee: ir.types.Type) bool {
    return switch (pointee) {
        .external_nominal => ir.types.isStr(pointee),
        .slice => true,
        else => false,
    };
}

/// The name a type spells when it is a bare generic PARAMETER: one UNRESOLVED
/// path segment, because the frontend resolves every name this crate declares.
///
/// Spelled out at file scope rather than delegated to
/// `Lowerer.isTypeParameterPath`, which lives on the struct.
fn hashParameterName(ty: ir.types.Type) ?[]const u8 {
    const path = switch (ty) {
        .path => |value| value,
        else => return null,
    };
    if (path.segments.len != 1) return null;
    const segment = path.segments[0];
    if (segment.id != null or segment.name.len == 0) return null;
    return segment.name;
}

/// Whether `ty` is a BORROW of an array, so the array itself is reached
/// through an address rather than held.
///
/// `&[T; N]` is a thin pointer to sized storage, so `lowerType` keeps it as
/// `*const [N] T` — the address the source's `&'static` promised, and the
/// only way a hoisted `static` still names the same bytes every time. An
/// index into it therefore reads through the pointer rather than out of the
/// pointer. A raw pointer is left alone: Zig already indexes a `[*] T` by
/// itself, and it is a different carrier with its own rules.
fn borrowPointsAtArray(ty: ?ir.types.Type) bool {
    const concrete = ty orelse return false;
    return switch (concrete) {
        .reference => |reference| reference.pointee == .array,
        else => false,
    };
}

/// Whether `path` is a fully written-out EXTERNAL path for exactly the trait
/// at `wanted`.
///
/// Every segment must carry no entity id, and that is the whole proof: the
/// frontend resolves every name this crate declares to an entity, so a path
/// with no ids at all reaches outside the crate and its spelling is its
/// identity. A crate's own `Read` is written `Read` and resolves, so it can
/// never answer here, and no comparison is made on a bare leaf name. The
/// root segment answers for `std` and `core` alike because std re-exports
/// core, which is the substitution `boundPathMatches` makes at index zero.
fn externalBoundPathIs(path: ir.types.Path, wanted: []const []const u8) bool {
    if (path.segments.len != wanted.len) return false;
    for (path.segments, wanted, 0..) |segment, expected, index| {
        if (segment.id != null) return false;
        if (index == 0 and
            (std.mem.eql(u8, expected, "std") or std.mem.eql(u8, expected, "core")) and
            (std.mem.eql(u8, segment.name, "std") or std.mem.eql(u8, segment.name, "core")))
        {
            continue;
        }
        if (!std.mem.eql(u8, segment.name, expected)) return false;
    }
    return true;
}

const hasher_write_primitives = [_][]const u8{
    "u8", "u16", "u32", "u64", "u128", "usize",
    "i8", "i16", "i32", "i64", "i128", "isize",
};

const CanonicalHashSourceMethod = struct {
    id: ir.spine.EntityId,
    name: []const u8,
};

const HashDispatch = union(enum) {
    none,
    source_method: ir.spine.EntityId,
    hash_walk,
    write,
    write_u8,
    write_u16,
    write_u32,
    write_u64,
    write_u128,
    write_usize,
    write_i8,
    write_i16,
    write_i32,
    write_i64,
    write_i128,
    write_isize,

    fn forPrimitive(primitive: ir.types.Prim) HashDispatch {
        inline for (hasher_write_primitives) |suffix| {
            if (primitive == @field(ir.types.Prim, suffix)) return @unionInit(HashDispatch, "write_" ++ suffix, {});
        }
        return .none;
    }

    fn isNone(self: HashDispatch) bool {
        return switch (self) {
            .none => true,
            else => false,
        };
    }

    fn writeMethodName(self: HashDispatch) []const u8 {
        return switch (self) {
            .none, .source_method, .hash_walk => "",
            .write => "write",
            .write_u8 => "write_u8",
            .write_u16 => "write_u16",
            .write_u32 => "write_u32",
            .write_u64 => "write_u64",
            .write_u128 => "write_u128",
            .write_usize => "write_usize",
            .write_i8 => "write_i8",
            .write_i16 => "write_i16",
            .write_i32 => "write_i32",
            .write_i64 => "write_i64",
            .write_i128 => "write_i128",
            .write_isize => "write_isize",
        };
    }

    fn reachesName(self: HashDispatch, source_name: []const u8) bool {
        return switch (self) {
            .none, .source_method => false,
            .hash_walk => true,
            .write => std.mem.eql(u8, source_name, "write"),
            .write_u8,
            .write_u16,
            .write_u32,
            .write_u64,
            .write_u128,
            .write_usize,
            .write_i8,
            .write_i16,
            .write_i32,
            .write_i64,
            .write_i128,
            .write_isize,
            => std.mem.eql(u8, source_name, self.writeMethodName()) or
                std.mem.eql(u8, source_name, "write"),
        };
    }
};
/// Whether an external path names Rust's own growable `Vec`.
///
/// `std::vec::Vec` is a re-export of `alloc::vec::Vec`, so both spellings name
/// the ONE type — the same equivalence `isOwnedStringType` already allows for
/// `String`, and the same one `isAllocStringPath` and `isCowPath` already allow
/// for their types. Matching `alloc` alone was an admission in one place and a
/// refusal in every other: `test/crates/generic-owner-transfer` spells both of
/// its containers `std::…`, and its `use std::vec::Vec;` fell past every arm of
/// `isRuntimeTypeImport` to `error.UnsupportedExternalUse` — a refusal over a
/// type this file already lowers to `std.ArrayListUnmanaged` for the `alloc`
/// spelling. `ownedRuntimeContainerIsRuntimeMovable`, `ownerReleasesElements`
/// and `coreCallAllocates` each spelled the `alloc` path inline and so each
/// missed the `std` one: a `Vec` named the second way imported as a type and
/// then owned nothing, so no release was ever armed for it.
///
/// This is deliberately the WIDE answer, and it is deliberately ONE function
/// rather than four. Every caller asks the same question — is this path `Vec` —
/// about whether a type imports at all, whether it lowers to
/// `std.ArrayListUnmanaged`, whether indexing projects through `items`, whether
/// `push`/`len`/`extend` are its own, whether its elements have to be walked
/// before the slab, and whether a `From` conversion into it allocates. A `std`
/// spelling of the same type has to answer yes to all of those together, or the
/// crate that spells it that way imports a type nothing else can name and then
/// leaks it.
fn isAllocVecPath(path: []const []const u8) bool {
    if (path.len != 3) return false;
    return (std.mem.eql(u8, path[0], "alloc") or std.mem.eql(u8, path[0], "std")) and
        std.mem.eql(u8, path[1], "vec") and
        std.mem.eql(u8, path[2], "Vec");
}

/// Whether an external path names a `HashMap` or a `HashSet`, under any of the
/// three roots Rust re-exports `collections` from.
///
/// A map is a TABLE the runtime owns and an element walk it must never perform:
/// `r2z.collections.HashMap` is a bare `std.HashMap`, `put` copies the key
/// descriptor and ALIASES the slab, and `dropTemporary` on a map frees the
/// table and walks no entry — the entries are borrowed slabs the map does not
/// own. So a map is released by its own `deinit(allocator)` and by nothing
/// else, which is a DIFFERENT mechanism from releasing a `Vec`'s elements, and
/// the two are kept apart here rather than folded into one predicate.
fn isRuntimeMapPath(path: []const []const u8) bool {
    if (path.len != 3) return false;
    if (!std.mem.eql(u8, path[0], "core") and
        !std.mem.eql(u8, path[0], "std") and
        !std.mem.eql(u8, path[0], "alloc")) return false;
    if (!std.mem.eql(u8, path[1], "collections")) return false;
    return std.mem.eql(u8, path[2], "HashMap") or
        std.mem.eql(u8, path[2], "HashSet");
}

/// Whether a core call allocates.
///
/// `String::from(..)` and `Vec::from(..)` both arrive as `convert_from` with an
/// owned container target, and the backend builds each with the matching
/// runtime copy helper and the call site's allocator. An effect scan that
/// misses either declares no allocator where the body asks for one, and every
/// call to that function is then emitted one argument short — with no `try` for
/// an error union the declaration does not have either. So the scan and the
/// lowering have to agree on the same set of targets, or the scan widens.
fn coreCallAllocates(call: ir.exprs.CoreCall) bool {
    if (call.function == .string_from_utf8_lossy) return true;
    if (call.function != .convert_from) return false;
    if (call.generic_args.len != 1) return false;
    const target = call.generic_args[0];
    if (isOwnedStringType(target)) return true;
    const external = switch (target) {
        .external_nominal => |value| value,
        else => return false,
    };
    return external.args.len == 1 and isAllocVecPath(external.path);
}

/// Analyze allocation effects in the source body graph without lowering it.
/// The call graph is resolved in the IR, so direct free, associated, and
/// method calls can be followed before declaration order becomes observable.
const AllocationEffectScanner = struct {
    exprs: []const ir.exprs.Expr,
    stmts: []const ir.exprs.Statement,
    effects: []const bool,
    /// Comparisons that bind an owned operand, indexed by `ir.exprs.NodeId`.
    /// `bindComparisonOperand` releases each one through
    /// `r2z.alloc.dropTemporary(allocator, ..)`, which names the enclosing
    /// allocator. Nothing in the call graph records that, and it is decided
    /// while the declaration is lowered — long after every call site has
    /// already been settled from `effects`. Empty when not computed.
    comparison_temporaries: []const bool,
    /// `let` bindings whose type is a known runtime owner, indexed by
    /// `ir.exprs.NodeId` into the STATEMENT table.
    ///
    /// Declaring an owner is what makes the enclosing callable release it, and
    /// that release names the allocator — so the callable needs one. The IR
    /// records nothing about the cleanup that lowering will emit, exactly as it
    /// records nothing about the `dropTemporary` in `comparison_temporaries`
    /// above, and for the same reason: the decision is made while the
    /// declaration is lowered, long after every call site was settled. Seeding
    /// it here is what lets the CALLER pass the allocator the callee ends up
    /// declaring. Empty when not computed.
    owner_cleanups: []const bool,
    pattern_cleanups: []const bool,
    hash_dispatches: []const HashDispatch,
    hash_source_methods: []const CanonicalHashSourceMethod,

    fn exprAllocates(self: *const AllocationEffectScanner, node_id: ir.exprs.NodeId) bool {
        if (@as(usize, node_id) >= self.exprs.len) return false;
        return switch (self.exprs[node_id].kind) {
            .literal, .path, .unit, .continue_, .panic_ => false,
            .array => |array| self.nodeListAllocates(array.elements),
            // A `vec!` literal always allocates: it appends into a fresh
            // `ArrayListUnmanaged` and hands the buffer back through
            // `deinit(allocator)`, so the enclosing callable needs the
            // allocator threaded in even when every element is a literal.
            // Scanning only the elements, as an array literal is scanned,
            // let `vec![1, 2, 3]` emit `append(allocator, ..)` into a
            // function that had no allocator binding at all.
            .vec_lit => true,
            .range => |range| self.exprAllocates(range.start) or
                (if (range.end) |end| self.exprAllocates(end) else false),
            .block => |block| self.blockAllocates(block),
            .if_else => |if_expr| self.exprAllocates(if_expr.cond) or
                self.blockAllocates(if_expr.then_) or
                self.elseAllocates(if_expr.@"else"),
            .if_let => |if_let| self.patternCleanupsReaches(node_id) or self.exprAllocates(if_let.scrutinee) or
                self.blockAllocates(if_let.then_) or
                self.elseAllocates(if_let.@"else"),
            .match => |match_expr| self.matchAllocates(match_expr),
            .loop_ => |loop_expr| self.blockAllocates(loop_expr.body),
            .while_ => |while_expr| self.exprAllocates(while_expr.cond) or
                self.blockAllocates(while_expr.body),
            .for_ => |for_expr| self.patternCleanupsReaches(node_id) or self.exprAllocates(for_expr.iterable) or
                self.blockAllocates(for_expr.body) or
                self.iterKindAllocates(for_expr.iter_kind),
            .break_ => |break_expr| if (break_expr.value) |value|
                self.exprAllocates(value)
            else
                false,
            .call => |call| self.callTargetAllocates(call.call_kind) or
                self.nodeListAllocates(call.args),
            .core_call => |call| self.hashDispatchReaches(node_id) or
                coreCallAllocates(call) or self.nodeListAllocates(call.args),
            .core_function => false,
            .external_variant => |variant| blk: {
                if (self.nodeListAllocates(variant.tuple_fields)) break :blk true;
                for (variant.named_fields) |field| {
                    if (self.exprAllocates(field.value)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |method_call| self.methodTargetAllocates(method_call.method) or
                self.hashDispatchReaches(node_id) or
                self.exprAllocates(method_call.receiver) or
                self.nodeListAllocates(method_call.args),
            .struct_lit => |literal| self.structLiteralAllocates(literal),
            .enum_variant => |variant| self.enumVariantAllocates(variant),
            .format_write => |format| self.exprAllocates(format.writer) or
                self.nodeListAllocates(format.args),
            .field => |field| self.exprAllocates(field.base),
            .index => |index| self.exprAllocates(index.base) or self.exprAllocates(index.index),
            .cast => |cast| self.exprAllocates(cast.operand),
            // An `==`/`!=` between owned rvalues binds each operand and
            // releases it with `r2z.alloc.dropTemporary`, which names the
            // enclosing allocator. The call graph records nothing about
            // that, so the scan reads the verdict the lowering itself
            // reaches rather than deciding ownership a second time.
            .binary => |binary| self.comparisonOwnsTemporary(node_id) or
                self.exprAllocates(binary.lhs) or self.exprAllocates(binary.rhs),
            .unary => |unary| self.exprAllocates(unary.operand),
            .assign => |assign| self.exprAllocates(assign.target) or self.exprAllocates(assign.value),
            .try_ => |try_expr| self.exprAllocates(try_expr.inner),
            .return_ => |return_expr| if (return_expr.value) |value|
                self.exprAllocates(value)
            else
                false,
            .closure => |closure| self.blockAllocates(closure.body),
            .iterator_chain => |chain| self.iteratorChainAllocates(chain),
            .unsupported => |unsupported| if (allocationAssertionCondition(
                unsupported.reason,
                node_id,
                self.exprs.len,
            )) |condition|
                self.exprAllocates(condition)
            else
                false,
        };
    }

    fn nodeListAllocates(
        self: *const AllocationEffectScanner,
        node_ids: []const ir.exprs.NodeId,
    ) bool {
        for (node_ids) |node_id| {
            if (self.exprAllocates(node_id)) return true;
        }
        return false;
    }

    fn blockAllocates(self: *const AllocationEffectScanner, block: ir.exprs.BlockExpr) bool {
        for (block.statements) |statement_id| {
            if (@as(usize, statement_id) >= self.stmts.len) continue;
            if (self.statementAllocates(statement_id, self.stmts[statement_id])) return true;
        }
        if (block.tail) |tail| return self.exprAllocates(tail);
        return false;
    }

    /// `node_id` is the statement's own index, which is what the
    /// `owner_cleanups` mask is keyed by; the statement is passed beside it so
    /// the switch below still reads the kind rather than an index.
    fn statementAllocates(
        self: *const AllocationEffectScanner,
        node_id: ir.exprs.NodeId,
        statement: ir.exprs.Statement,
    ) bool {
        return switch (statement.kind) {
            .let => |let_statement| self.statementOwnsCleanup(node_id) or
                (if (let_statement.init) |init| self.exprAllocates(init) else false),
            .let_else => |let_else| self.exprAllocates(let_else.init) or
                self.blockAllocates(let_else.else_block),
            .expr => |expression| self.exprAllocates(expression),
            .item => false,
        };
    }

    /// Whether the `let` at `node_id` declares a known runtime owner, so the
    /// callable that lowers it will have to release that owner.
    fn statementOwnsCleanup(self: *const AllocationEffectScanner, node_id: ir.exprs.NodeId) bool {
        if ((@as(usize, node_id)) >= self.owner_cleanups.len) return false;
        return self.owner_cleanups[node_id];
    }
    fn patternCleanupsReaches(self: *const AllocationEffectScanner, node_id: ir.exprs.NodeId) bool {
        return node_id < self.pattern_cleanups.len and self.pattern_cleanups[node_id];
    }

    fn elseAllocates(self: *const AllocationEffectScanner, branch: ir.exprs.ElseBranch) bool {
        return switch (branch) {
            .none => false,
            .block => |block| self.blockAllocates(block),
            .chain => |chain| self.exprAllocates(chain),
        };
    }

    fn matchAllocates(self: *const AllocationEffectScanner, match_expr: ir.exprs.MatchExpr) bool {
        if (self.exprAllocates(match_expr.scrutinee)) return true;
        for (match_expr.arms) |arm| {
            if (arm.guard) |guard| {
                if (self.exprAllocates(guard)) return true;
            }
            if (self.exprAllocates(arm.body)) return true;
        }
        return false;
    }

    fn structLiteralAllocates(
        self: *const AllocationEffectScanner,
        literal: ir.exprs.StructLit,
    ) bool {
        for (literal.fields) |field| {
            if (self.exprAllocates(field.value)) return true;
        }
        if (literal.base) |base| return self.exprAllocates(base);
        return false;
    }

    fn enumVariantAllocates(
        self: *const AllocationEffectScanner,
        variant: ir.exprs.EnumVariant,
    ) bool {
        if (self.nodeListAllocates(variant.tuple_fields)) return true;
        for (variant.named_fields) |field| {
            if (self.exprAllocates(field.value)) return true;
        }
        return false;
    }

    fn iterKindAllocates(
        self: *const AllocationEffectScanner,
        iter_kind: ir.exprs.IterKind,
    ) bool {
        return switch (iter_kind) {
            .range, .slice, .enumerate => false,
            .multi => |nodes| self.nodeListAllocates(nodes),
            .adapter => |chain| self.iteratorChainAllocates(chain),
        };
    }

    fn iteratorChainAllocates(
        self: *const AllocationEffectScanner,
        chain: ir.exprs.IteratorChainExpr,
    ) bool {
        if (chain.terminal == .collect_vec) return true;
        if (self.exprAllocates(chain.source)) return true;
        for (chain.adapters) |adapter| {
            if (self.adapterAllocates(adapter)) return true;
        }
        return false;
    }

    fn adapterAllocates(
        self: *const AllocationEffectScanner,
        adapter: ir.exprs.IteratorAdapter,
    ) bool {
        return switch (adapter) {
            .map => |map| self.blockAllocates(map.closure.body),
            .filter => |filter| self.blockAllocates(filter.closure.body),
            .flat_map => |closure| self.blockAllocates(closure.body),
            .enumerate, .range_rev, .other => false,
            .zip => |zip| self.exprAllocates(zip.other),
        };
    }

    fn callTargetAllocates(
        self: *const AllocationEffectScanner,
        call_kind: ir.exprs.CallKind,
    ) bool {
        return switch (call_kind) {
            .free => |target| self.bodyAllocates(target),
            .associated => |target| self.bodyAllocates(target),
            .constructor => false,
        };
    }

    fn methodTargetAllocates(
        self: *const AllocationEffectScanner,
        target: ir.exprs.DefId,
    ) bool {
        return self.bodyAllocates(target);
    }

    fn bodyAllocates(self: *const AllocationEffectScanner, target: ir.spine.EntityId) bool {
        if (@as(usize, target) >= self.effects.len) return false;
        return self.effects[target];
    }
    fn hashDispatchReaches(
        self: *const AllocationEffectScanner,
        node_id: ir.exprs.NodeId,
    ) bool {
        if (@as(usize, node_id) >= self.hash_dispatches.len) return false;
        const dispatch = self.hash_dispatches[node_id];
        switch (dispatch) {
            .none => return false,
            .source_method => |target| return self.bodyAllocates(target),
            .hash_walk,
            .write,
            .write_u8,
            .write_u16,
            .write_u32,
            .write_u64,
            .write_u128,
            .write_usize,
            .write_i8,
            .write_i16,
            .write_i32,
            .write_i64,
            .write_i128,
            .write_isize,
            => {},
        }
        for (self.hash_source_methods) |source| {
            if (!dispatch.reachesName(source.name)) continue;
            if (self.bodyAllocates(source.id)) return true;
        }
        return false;
    }

    /// Whether the comparison at `node_id` binds an owned operand, so
    /// lowering it releases that operand with `dropTemporary` and names the
    /// allocator the enclosing callable therefore declares.
    fn comparisonOwnsTemporary(
        self: *const AllocationEffectScanner,
        node_id: ir.exprs.NodeId,
    ) bool {
        if (@as(usize, node_id) >= self.comparison_temporaries.len) return false;
        return self.comparison_temporaries[node_id];
    }
};

const ModuleImportKey = struct {
    importing: ir.spine.EntityId,
    target: ir.spine.EntityId,
};

/// A relative `@import` a generated file names, under whichever spelling it
/// ended up with. A private `mod` keeps an `ast.Import`; a `pub mod` is
/// promoted to a `pub const name = @import("./name.zig")` decl before any
/// later pass sees the file, so both name the same edge and both have to be
/// readable.
const ReachableModuleRef = struct {
    local_name: []const u8,
    module_or_path: []const u8,
};
const StdImportDemand = struct {
    const Error = error{ CyclicZigAst, ZigAstTraversalDepthExceeded };
    const NodeKind = enum { expression, type_, pattern, declaration };
    const ActiveNode = struct { address: usize, kind: NodeKind };

    // Track ancestors, not every visited node: sharing a finite subtree is
    // valid, but reaching an ancestor again is a malformed target AST.
    active: [ir.types.traversal_depth_max]ActiveNode = undefined,
    depth: usize = 0,
    requires_std: bool = false,

    fn enter(self: *StdImportDemand, pointer: *const anyopaque, kind: NodeKind) Error!void {
        const address = @intFromPtr(pointer);
        for (self.active[0..self.depth]) |ancestor| {
            if (ancestor.address == address and ancestor.kind == kind) return error.CyclicZigAst;
        }
        if (self.depth == self.active.len) return error.ZigAstTraversalDepthExceeded;
        self.active[self.depth] = .{ .address = address, .kind = kind };
        self.depth += 1;
    }

    fn isQualifiedStdName(name: []const u8) bool {
        return name.len > "std.".len and std.mem.startsWith(u8, name, "std.");
    }

    fn nameRequiresStd(self: *StdImportDemand, name: []const u8) void {
        if (isQualifiedStdName(name)) self.requires_std = true;
    }

    fn typeRequiresStd(self: *StdImportDemand, ty: *const ast.Type) Error!void {
        try self.enter(ty, .type_);
        defer self.depth -= 1;
        switch (ty.*) {
            .prim, .any_opaque, .void_type => {},
            .named => |name| self.nameRequiresStd(name),
            .expr => |expression| try self.exprRequiresStd(expression),
            .ptr => |ptr| try self.typeRequiresStd(ptr.elem),
            .slice => |slice| try self.typeRequiresStd(slice.elem),
            .opt => |inner| try self.typeRequiresStd(inner),
            .err_union => |err_union| {
                if (err_union.err_set) |err_set| self.nameRequiresStd(err_set);
                try self.typeRequiresStd(err_union.payload);
            },
            .projected => |projected| try self.typeRequiresStd(projected.receiver),
            .generic => |generic| {
                self.nameRequiresStd(generic.name);
                try self.typesRequireStd(generic.params);
            },
            .array => |array| try self.typeRequiresStd(array.elem),
            .array_expr => |array| {
                try self.typeRequiresStd(array.elem);
                try self.exprRequiresStd(array.len);
            },
            .tuple => |tuple| try self.typesRequireStd(tuple),
            .fn_ptr => |function| {
                try self.typesRequireStd(function.params);
                try self.typeRequiresStd(function.ret);
            },
            .anon_struct => |anon| {
                for (anon.fields) |*field| {
                    try self.typeRequiresStd(&field.ty);
                    if (field.default_val) |value| try self.exprRequiresStd(value);
                }
            },
        }
    }

    fn typesRequireStd(self: *StdImportDemand, types: []const ast.Type) Error!void {
        for (types) |*ty| try self.typeRequiresStd(ty);
    }

    fn patternRequiresStd(self: *StdImportDemand, pattern: *const ast.Pattern) Error!void {
        try self.enter(pattern, .pattern);
        defer self.depth -= 1;
        switch (pattern.*) {
            .wildcard, .binding, .lit, .range_pat => {},
            .enum_literal => |name| self.nameRequiresStd(name),
            .tuple => |patterns| try self.patternsRequireStd(patterns),
            .struct_pat => |struct_pat| {
                if (struct_pat.name) |name| self.nameRequiresStd(name);
                for (struct_pat.fields) |*field| try self.patternRequiresStd(&field.pat);
            },
        }
    }

    fn patternsRequireStd(self: *StdImportDemand, patterns: []const ast.Pattern) Error!void {
        for (patterns) |*pattern| try self.patternRequiresStd(pattern);
    }

    fn stmtRequiresStd(self: *StdImportDemand, stmt: *const ast.Stmt) Error!void {
        switch (stmt.*) {
            .let_stmt => |*let_stmt| {
                if (let_stmt.ty) |*ty| try self.typeRequiresStd(ty);
                try self.exprRequiresStd(&let_stmt.init);
            },
            .assign => |*assign| {
                try self.exprRequiresStd(&assign.target);
                try self.exprRequiresStd(&assign.val);
            },
            .defer_stmt => |*defer_stmt| try self.exprRequiresStd(&defer_stmt.expr),
            .expr_stmt => |expr| try self.exprRequiresStd(expr),
        }
    }

    fn blockRequiresStd(self: *StdImportDemand, block: *const ast.Block) Error!void {
        for (block.stmts) |*stmt| try self.stmtRequiresStd(stmt);
        if (block.expr) |expr| try self.exprRequiresStd(expr);
    }

    fn exprRequiresStd(self: *StdImportDemand, expr: *const ast.Expr) Error!void {
        try self.enter(expr, .expression);
        defer self.depth -= 1;
        switch (expr.*) {
            .lit, .unit, .unsupported, .panic_, .continue_expr, .unreachable_ => {},
            .ident => |name| self.nameRequiresStd(name),
            .type_value => |*ty| try self.typeRequiresStd(ty),
            .field_access => |field_access| {
                // A bare `std` identifier needs the import when it is the
                // namespace root of a field access, not as a local value.
                if (field_access.target.* == .ident and
                    std.mem.eql(u8, field_access.target.ident, "std")) self.requires_std = true;
                try self.exprRequiresStd(field_access.target);
            },
            .call => |call| {
                try self.exprRequiresStd(call.callee);
                try self.typesRequireStd(call.generic_args);
                try self.exprsRequireStd(call.args);
            },
            .block => |*block| try self.blockRequiresStd(block),
            .match_expr => |match| {
                try self.exprRequiresStd(match.target);
                for (match.arms) |*arm| {
                    try self.patternsRequireStd(arm.patterns);
                    try self.exprRequiresStd(&arm.body);
                }
            },
            .bin_op => |bin_op| {
                try self.exprRequiresStd(bin_op.lhs);
                try self.exprRequiresStd(bin_op.rhs);
            },
            .unary_op => |unary_op| try self.exprRequiresStd(unary_op.operand),
            .cast => |*cast| {
                try self.typeRequiresStd(&cast.target);
                try self.exprRequiresStd(cast.operand);
            },
            .struct_init => |*struct_init| {
                if (struct_init.type_name) |*type_name| try self.typeRequiresStd(type_name);
                for (struct_init.fields) |*field| try self.exprRequiresStd(&field.expr);
            },
            .array_init => |*array_init| {
                if (array_init.type_name) |*type_name| try self.typeRequiresStd(type_name);
                try self.exprsRequireStd(array_init.elements);
            },
            .repeat => |*repeat| {
                if (repeat.type_name) |*type_name| try self.typeRequiresStd(type_name);
                try self.exprRequiresStd(repeat.elem);
            },
            .multi_array => |*multi_array| {
                if (multi_array.type_name) |*type_name| try self.typeRequiresStd(type_name);
                try self.exprsRequireStd(multi_array.elements);
            },
            .tuple => |elements| try self.exprsRequireStd(elements),
            .builtin => |builtin| {
                self.nameRequiresStd(builtin.name);
                try self.exprsRequireStd(builtin.args);
            },
            .if_expr => |if_expr| {
                try self.exprRequiresStd(if_expr.cond);
                try self.exprRequiresStd(if_expr.then_body);
                if (if_expr.else_body) |else_body| try self.exprRequiresStd(else_body);
            },
            .while_expr => |*while_expr| {
                try self.exprRequiresStd(while_expr.cond);
                if (while_expr.continue_expr) |continue_expr| try self.exprRequiresStd(continue_expr);
                try self.blockRequiresStd(&while_expr.body);
                if (while_expr.else_body) |else_body| try self.exprRequiresStd(else_body);
            },
            .for_expr => |*for_expr| {
                try self.exprsRequireStd(for_expr.inputs);
                try self.blockRequiresStd(&for_expr.body);
                if (for_expr.else_body) |else_body| try self.exprRequiresStd(else_body);
            },
            .range => |range| {
                try self.exprRequiresStd(range.start);
                if (range.end) |end| try self.exprRequiresStd(end);
            },
            .return_expr => |value| {
                if (value) |expr_value| try self.exprRequiresStd(expr_value);
            },
            .break_expr => |break_expr| {
                if (break_expr.value) |expr_value| try self.exprRequiresStd(expr_value);
            },
        }
    }

    fn exprsRequireStd(self: *StdImportDemand, exprs: []const ast.Expr) Error!void {
        for (exprs) |*expr| try self.exprRequiresStd(expr);
    }

    fn genericParamsRequireStd(self: *StdImportDemand, params: []const ast.GenericParam) Error!void {
        for (params) |*param| {
            if (param.ty) |*ty| try self.typeRequiresStd(ty);
        }
    }

    fn declRequiresStd(self: *StdImportDemand, decl: *const ast.Decl) Error!void {
        try self.enter(decl, .declaration);
        defer self.depth -= 1;
        switch (decl.*) {
            .trait_descriptor => |descriptor| {
                for (descriptor.cases) |*descriptor_case| {
                    try self.typeRequiresStd(&descriptor_case.receiver);
                    for (descriptor_case.members) |*member| {
                        switch (member.*) {
                            .type_ => |*type_member| try self.typeRequiresStd(&type_member.ty),
                            .const_ => |*const_member| try self.exprRequiresStd(&const_member.value),
                        }
                    }
                }
            },
            .comment => {},
            .struct_decl => |struct_decl| {
                for (struct_decl.fields) |*field| {
                    try self.typeRequiresStd(&field.ty);
                    if (field.default_val) |value| try self.exprRequiresStd(value);
                }
                try self.genericParamsRequireStd(struct_decl.generic_params);
                try self.declsRequireStd(struct_decl.decls);
            },
            .enum_decl => |*enum_decl| {
                if (enum_decl.tag_type) |*tag_type| try self.typeRequiresStd(tag_type);
                for (enum_decl.variants) |variant| {
                    if (variant.value) |value| try self.exprRequiresStd(value);
                }
                try self.declsRequireStd(enum_decl.decls);
            },
            .union_decl => |*union_decl| {
                if (union_decl.tag_type) |*tag_type| try self.typeRequiresStd(tag_type);
                for (union_decl.fields) |*field| try self.typeRequiresStd(&field.ty);
                try self.declsRequireStd(union_decl.decls);
            },
            .fn_decl => |*fn_decl| {
                try self.typeRequiresStd(&fn_decl.ret_type);
                try self.genericParamsRequireStd(fn_decl.generic_params);
                for (fn_decl.params) |*param| try self.typeRequiresStd(&param.ty);
                if (fn_decl.body) |*body| try self.blockRequiresStd(body);
            },
            .const_decl => |*const_decl| {
                if (const_decl.ty) |*ty| try self.typeRequiresStd(ty);
                try self.exprRequiresStd(&const_decl.init);
            },
            .var_decl => |*var_decl| {
                if (var_decl.ty) |*ty| try self.typeRequiresStd(ty);
                try self.exprRequiresStd(&var_decl.init);
            },
        }
    }

    fn declsRequireStd(self: *StdImportDemand, decls: []const ast.Decl) Error!void {
        for (decls) |*decl| try self.declRequiresStd(decl);
    }

    fn fileRequiresStd(decls: []const ast.Decl, tests: []const ast.TestDecl) Error!bool {
        var demand: StdImportDemand = .{};
        // Do not short-circuit once a std name is found: malformed nodes in
        // another branch must be refused before the emitter traverses them.
        try demand.declsRequireStd(decls);
        for (tests) |*test_decl| try demand.blockRequiresStd(&test_decl.body);
        // The emitter binds expectEqual through std.testing for every test file.
        return demand.requires_std or tests.len > 0;
    }
};

test "std demand detects qualified error-set names" {
    var payload: ast.Type = .{ .prim = .u32 };
    const std_error_union: ast.Type = .{ .err_union = .{
        .err_set = "std.SomeError",
        .payload = &payload,
    } };
    var demand: StdImportDemand = .{};
    try demand.typeRequiresStd(&std_error_union);
    try std.testing.expect(demand.requires_std);

    const local_error_union: ast.Type = .{ .err_union = .{
        .err_set = "SomeError",
        .payload = &payload,
    } };
    demand = .{};
    try demand.typeRequiresStd(&local_error_union);
    try std.testing.expect(!demand.requires_std);
}

test "std demand rejects cyclic selection after finding a std name" {
    const condition: ast.Expr = .{ .ident = "std.math" };
    const selected: ast.Expr = .{ .lit = .{ .int = 1 } };
    var selection: ast.Expr = undefined;
    selection = .{ .if_expr = .{
        .cond = &condition,
        .then_body = &selected,
        .else_body = &selection,
    } };
    const decls = [_]ast.Decl{.{ .fn_decl = .{
        .name = "limit",
        .ret_type = .{ .prim = .u8 },
        .body = .{ .stmts = &.{}, .expr = &selection },
    } }};
    try std.testing.expectError(error.CyclicZigAst, StdImportDemand.fileRequiresStd(&decls, &.{}));
}

test "std demand rejects type expression and declaration cycles" {
    var ty: ast.Type = undefined;
    var type_expression: ast.Expr = undefined;
    ty = .{ .expr = &type_expression };
    type_expression = .{ .type_value = ty };
    const typed_decls = [_]ast.Decl{.{ .const_decl = .{
        .name = "Type",
        .init = .{ .type_value = ty },
    } }};
    try std.testing.expectError(error.CyclicZigAst, StdImportDemand.fileRequiresStd(&typed_decls, &.{}));

    var nested_decls: [1]ast.Decl = undefined;
    nested_decls[0] = .{ .struct_decl = .{
        .name = "Recursive",
        .decls = &nested_decls,
    } };
    try std.testing.expectError(error.CyclicZigAst, StdImportDemand.fileRequiresStd(&nested_decls, &.{}));
}

test "std demand permits shared finite expressions and detects namespace fields" {
    const shared: ast.Expr = .{ .ident = "value" };
    const local_decls = [_]ast.Decl{.{ .const_decl = .{
        .name = "sum",
        .init = .{ .bin_op = .{ .op = .add, .lhs = &shared, .rhs = &shared } },
    } }};
    try std.testing.expect(!try StdImportDemand.fileRequiresStd(&local_decls, &.{}));

    const namespace: ast.Expr = .{ .ident = "std" };
    const qualified: ast.Expr = .{ .field_access = .{ .target = &namespace, .field_name = "math" } };
    const std_decls = [_]ast.Decl{.{ .const_decl = .{
        .name = "limits",
        .init = .{ .bin_op = .{ .op = .equal, .lhs = &qualified, .rhs = &qualified } },
    } }};
    try std.testing.expect(try StdImportDemand.fileRequiresStd(&std_decls, &.{}));
}

test "std demand refuses traversal beyond the shared depth limit" {
    var expressions: [ir.types.traversal_depth_max + 1]ast.Expr = undefined;
    expressions[expressions.len - 1] = .{ .ident = "std.math" };
    for (expressions[0 .. expressions.len - 1], 0..) |*expression, index| {
        expression.* = .{ .unary_op = .{ .op = .negate, .operand = &expressions[index + 1] } };
    }
    const decls = [_]ast.Decl{.{ .fn_decl = .{
        .name = "deep",
        .ret_type = .{ .prim = .u8 },
        .body = .{ .stmts = &.{}, .expr = &expressions[0] },
    } }};
    try std.testing.expectError(error.ZigAstTraversalDepthExceeded, StdImportDemand.fileRequiresStd(&decls, &.{}));
}

/// The two standard methods whose recognition reads a trait bound off a type
/// parameter, and so needs the callable that declares it in scope.
///
/// `genericBound` walks up from one `fn`, `impl` or `trait`, which is what keeps
/// a `W` in one function from answering for a receiver another one declares.
/// These are exactly the names `lookupRecognizedStdMethod` answers that way, so
/// the effect pass that needs a callable asks about these two and nothing else.
fn isTraitBoundIoMethodName(name: []const u8) bool {
    return std.mem.eql(u8, name, "read_exact") or std.mem.eql(u8, name, "write_all");
}

/// Whether a declared return that OWNS runtime storage obliges its callable to
/// declare an allocator — and every call to that callable to hand one over.
///
/// `ownedRuntimeContainerType` draws the line the source drew: a `String` or a
/// `Vec` the callee returns is a value it BUILT, and building one needs the
/// allocator that released it. A borrowed return — `&[u8]`, `&str`, anything
/// behind a reference — names storage the caller still owns, builds nothing,
/// and obliges nobody.
fn returnTypeNeedsAllocator(ret: ir.types.Type) bool {
    return Lowerer.ownsRuntimeTableOrContainer(ret);
}

// `allow_parameter` is a decision, so it is pinned where the decision is made
// rather than only described in prose.
//
// A `Vec<T>`'s ELEMENT walk has to be emitted for whatever `T` turns out to be
// at comptime, so `vecElementMayOwnRuntimeStorage` asks with the parameter
// allowed. The general predicate cannot: whether `T` owns anything is a
// question only the instantiation can answer, and the answers differ in
// SPELLING, not in care.
//
//   - an owner RELEASE for a `T` is `T.deinit(allocator)`:
//     `ownerReleasesElements` answers false for a path, and `u32` has no
//     `deinit`;
//   - an owner MOVE for a `T` is a bare `takeOwned(T, ..)`:
//     `ownedMoveHasUnknownLength` answers false for a path, so no
//     `comptime supportsOwnedMove` guard is put in front of it, and
//     `takeOwned` refuses every type it does not own.
//
// So a generic that DROPS its own `T` parameter arms no release and leaks it.
// The fix is `dropTemporary` plus that guard on both, and either one changes
// the signature of every generic that takes `T` by value — `paramsOwnRuntimeContainer`
// is the single gate that decides the allocator parameter, so the whole call
// graph moves with it. These assertions are the gate that change opens.
test "a type parameter is storage an element walk may own and an owner is not" {
    const parameter_segments = [_]ir.types.PathSegment{.{ .name = "T", .id = null }};
    const parameter_type: ir.types.Type = .{ .path = .{ .segments = &parameter_segments } };
    const parameter_args = [_]ir.types.Type{parameter_type};
    const byte_args = [_]ir.types.Type{.{ .prim = .u8 }};

    try std.testing.expect(Lowerer.isTypeParameterPath(parameter_type));
    try std.testing.expect(!Lowerer.ownedRuntimeStorageAt(parameter_type, 0, false));
    try std.testing.expect(Lowerer.ownedRuntimeStorageAt(parameter_type, 0, true));

    // What BOTH parameter-owner loops ask, in a free function and in a method.
    try std.testing.expect(!Lowerer.ownedRuntimeContainerType(parameter_type));
    // The one caller allowed the parameter, and only because the `Vec` around
    // the element already owns.
    try std.testing.expect(Lowerer.vecElementMayOwnRuntimeStorage(parameter_type));

    // The companions a widening has to bring with it.
    try std.testing.expect(!Lowerer.ownerReleasesElements(parameter_type));
    try std.testing.expect(!Lowerer.ownedMoveHasUnknownLength(parameter_type, 0));
    try std.testing.expect(!Lowerer.ownedMoveHasUnsupportedGenericArray(parameter_type, 0));

    // One walk, decided from the element the instantiation supplies: `Vec<T>`
    // walks its elements, `Vec<u8>` has none to walk and frees the slab alone.
    try std.testing.expect(Lowerer.ownerReleasesElements(.{ .external_nominal = .{
        .path = &.{ "alloc", "vec", "Vec" },
        .args = &parameter_args,
    } }));
    try std.testing.expect(!Lowerer.ownerReleasesElements(.{ .external_nominal = .{
        .path = &.{ "alloc", "vec", "Vec" },
        .args = &byte_args,
    } }));
}

// `std::vec::Vec` and `alloc::vec::Vec` are ONE type: Rust re-exports the
// `alloc` one into `std`. Every other container this file recognises is
// already spelled both ways — `isOwnedStringType` lists `std::string::String`
// beside `alloc::string::String`, `isAllocStringPath` takes both roots,
// `isCowPath` takes both, and `isCollectionsPath` takes three roots — and `Vec`
// was the one left matching `alloc` alone, in FOUR places at once:
// `isAllocVecPath`, `coreCallAllocates`, `ownerReleasesElements` and
// `ownedRuntimeContainerIsRuntimeMovable`.
//
// The four disagreeing answers are one defect, not four, and each of them
// leaks rather than refuses:
//
//   - the import: `use std::vec::Vec;` fell past every arm of
//     `isRuntimeTypeImport` to `error.UnsupportedExternalUse`, refusing
//     `test/crates/generic-owner-transfer` over a type this file lowers to
//     `std.ArrayListUnmanaged` for the other spelling;
//   - the type: `std::vec::Vec<T>` reached no `lowerExternalNominal` arm, so a
//     binding of it named nothing;
//   - ownership: `ownedRuntimeContainerType` answered false, so
//     `paramsOwnRuntimeContainer` declared no allocator and no scope release
//     was ever armed — the allocation leaked;
//   - the element walk: `ownerReleasesElements` answered false, so a
//     `Vec<String>` would have freed its slab and stranded every element.
//
// So the equivalence is asserted here across the WHOLE chain at once, for the
// element types the corpus actually spells: a `String` element (which needs the
// walk) and a `u8` element (which does not), each through both roots. A
// widening that reaches only one of the four re-fails this test.
test "std and alloc spell one Vec, through the import, the owner and the walk" {
    const byte_args = [_]ir.types.Type{.{ .prim = .u8 }};
    const string_args = [_]ir.types.Type{.{ .external_nominal = .{
        .path = &.{ "alloc", "string", "String" },
        .args = &.{},
    } }};
    const param_span: ir.spine.Span = .{
        .start_line = 1,
        .start_col = 1,
        .end_line = 1,
        .end_col = 1,
    };

    // Every container spelling the corpus imports, paired with the `alloc`
    // spelling of the same type. The corpus writes `std::string::String` and
    // `std::vec::Vec` (`test/crates/generic-owner-transfer:19-20`),
    // `alloc::string::String` and `alloc::vec::Vec`
    // (`test/crates/hex/src/lib.rs:43`), `std::borrow::Cow` and
    // `alloc::borrow::Cow`.
    const spellings = [_][2][]const []const u8{
        .{ &.{ "alloc", "vec", "Vec" }, &.{ "std", "vec", "Vec" } },
        .{ &.{ "alloc", "string", "String" }, &.{ "std", "string", "String" } },
        .{ &.{ "alloc", "string", "FromUtf8Error" }, &.{ "std", "string", "FromUtf8Error" } },
        .{ &.{ "alloc", "borrow", "Cow" }, &.{ "std", "borrow", "Cow" } },
        .{ &.{ "alloc", "collections", "HashMap" }, &.{ "std", "collections", "HashMap" } },
        .{ &.{ "alloc", "collections", "HashSet" }, &.{ "std", "collections", "HashSet" } },
        .{ &.{ "core", "collections", "HashMap" }, &.{ "std", "collections", "HashMap" } },
        .{ &.{ "core", "hash", "BuildHasherDefault" }, &.{ "std", "hash", "BuildHasherDefault" } },
    };
    // `Vec` is the one container this file used to spell `alloc`-only, so its
    // two spellings are the pair the widening is about.
    try std.testing.expect(isAllocVecPath(&.{ "alloc", "vec", "Vec" }));
    try std.testing.expect(isAllocVecPath(&.{ "std", "vec", "Vec" }));
    try std.testing.expect(!isAllocVecPath(&.{ "std", "vec" }));
    try std.testing.expect(!isAllocVecPath(&.{ "core", "vec", "Vec" }));
    try std.testing.expect(!isAllocVecPath(&.{ "alloc", "collections", "Vec" }));

    for (spellings) |pair| {
        // The import is the arm the defect refused on. `isRuntimeTypeImport` is
        // a `Lowerer` method with no receiver state, so it is reachable here.
        try std.testing.expectEqual(
            Lowerer.isRuntimeTypeImport(pair[0]),
            Lowerer.isRuntimeTypeImport(pair[1]),
        );
        // And every pair must import at all: a `std` spelling that is admitted
        // only because its `alloc` twin is would answer true to the equality
        // above and still refuse the crate.
        try std.testing.expect(Lowerer.isRuntimeTypeImport(pair[0]));
        try std.testing.expect(Lowerer.isRuntimeTypeImport(pair[1]));
    }

    // The owner decision, and the element walk, are the two that LEAK rather
    // than refuse, so they are asserted per element type.
    for ([_][]const u8{ "alloc", "std" }) |root| {
        const owned_vec: ir.types.Type = .{ .external_nominal = .{
            .path = &.{ root, "vec", "Vec" },
            .args = &byte_args,
        } };
        const string_vec: ir.types.Type = .{ .external_nominal = .{
            .path = &.{ root, "vec", "Vec" },
            .args = &string_args,
        } };

        try std.testing.expect(Lowerer.ownedRuntimeContainerType(owned_vec));
        try std.testing.expect(Lowerer.ownedRuntimeContainerType(string_vec));
        // The allocator parameter is what `paramsOwnRuntimeContainer` gates, and
        // that gate is what decides whether the whole call graph passes one.
        try std.testing.expect(Lowerer.paramsOwnRuntimeContainer(
            &.{.{ .name = "list", .ty = owned_vec, .span = param_span }},
        ));
        try std.testing.expect(Lowerer.paramsOwnRuntimeContainer(
            &.{.{ .name = "list", .ty = string_vec, .span = param_span }},
        ));

        // `Vec<u8)` has nothing to walk; `Vec<String>` has a `String` per
        // element and the walk is what frees them.
        try std.testing.expect(!Lowerer.ownerReleasesElements(owned_vec));
        try std.testing.expect(Lowerer.ownerReleasesElements(string_vec));

        // `Vec::from(..)` allocates, so the effect scan has to say so for both
        // spellings — a scan that misses it declares no allocator and every
        // call to the function is emitted one argument short.
        try std.testing.expect(coreCallAllocates(.{ .function = .convert_from, .generic_args = &.{owned_vec} }));
        try std.testing.expect(coreCallAllocates(.{ .function = .convert_from, .generic_args = &.{string_vec} }));
    }

    // `std::vec` on its own is the MODULE, not the type, and admits nothing:
    // `syn/src/punctuated.rs` imports it and the corpus has no lowering for it.
    // That is a different question from the type's, and it must keep refusing
    // rather than be swept in by the widening above.
    try std.testing.expect(!Lowerer.isRuntimeTypeImport(&.{ "std", "vec" }));
}

// A `HashMap`/`HashSet` is a mapped type whose TABLE the lowering owns, and it
// is released by exactly one mechanism. The runtime's contract says three things
// about it and each one lands in a different place here, so all three are pinned
// together — separating them is how the element walk would end up freeing
// borrowed slabs.
//
// 1. THE TABLE IS FREED BY AN EXPLICIT `deinit`. `r2z.alloc`'s `dropTemporary`
//    is a no-op on a map (`ownsTemporaryStorage` refuses every foreign named
//    struct), so nothing else would ever free the table: a `let mut table =
//    HashMap::..` binding had no release armed at all and leaked it. The release
//    that is right is a bare `handle.deinit(allocator)`, which is what
//    `ownerReleaseStatement` emits when `ownerReleasesElements` is false.
//
// 2. THE ENTRIES ARE NOT THE MAP'S TO FREE. `put` copies the key descriptor and
//    ALIASES the slab, so `dropTemporary`'s element walk would free a borrow.
//    `ownerReleasesElements` therefore keeps answering FALSE for a map, and that
//    is what keeps the release a `deinit` rather than a walk. This is the
//    separability the arming rule asks about: the owner decision and the
//    element walk are two different predicates, and only the first one names a
//    map.
//
// 3. A MAP IS NOT A MOVEABLE OWNER. `r2z.alloc.takeOwned` refuses one —
//    `supportsOwnedMove` reaches only the five runtime containers — so
//    `ownedRuntimeContainerType` must keep answering false. It is
//    `ownsRuntimeTableOrContainer` that adds the map, and only the release and
//    allocator gates read that.
//
// What is STILL missing is the method rewrite: `insert`, `contains_key` and
// `entry` are emitted verbatim against a bare `std.HashMap` that has `put`,
// `get`, `contains`, `getPtr`, `remove` and `deinit`. The absence of any map
// member from the recognised vocabulary below is asserted for that reason, so
// the eventual rewrite has to re-fail this test rather than land silently.
test "a HashMap owns its table, owes no element walk, and is not a moveable owner" {
    const map_path = [_][]const u8{ "std", "collections", "HashMap" };
    const set_path = [_][]const u8{ "std", "collections", "HashSet" };

    // The TYPE is recognised — it lowers to `r2z.collections.HashMap` with the
    // builder the source named — so this is not an unknown type being refused.
    try std.testing.expect(isRuntimeMapPath(&map_path));
    try std.testing.expect(isRuntimeMapPath(&set_path));
    try std.testing.expect(isRuntimeMapPath(&.{ "core", "collections", "HashMap" }));
    try std.testing.expect(isRuntimeMapPath(&.{ "alloc", "collections", "HashSet" }));
    try std.testing.expect(isRuntimeMapPath(&map_path));
    try std.testing.expect(isRuntimeMapPath(&set_path));

    const owned_key: ir.types.Type = .{ .external_nominal = .{
        .path = &.{ "alloc", "string", "String" },
        .args = &.{},
    } };
    for ([_][]const []const u8{ &map_path, &set_path }) |path| {
        const container: ir.types.Type = .{
            .external_nominal = .{
                .path = path,
                // `HashMap<K, V, S>` is three arguments and `HashSet<T, S>` is two;
                // the arity is what the type lowering validates, not these gates.
                .args = &.{ owned_key, .{ .prim = .u64 } },
            },
        };
        // (1) A `deinit(allocator)` is armed, and the allocator that takes it is
        // declared on any callable a map is passed to or returned from.
        try std.testing.expect(Lowerer.ownsRuntimeTableOrContainer(container));
        try std.testing.expect(returnTypeNeedsAllocator(container));
        try std.testing.expect(Lowerer.paramsOwnRuntimeContainer(
            &.{.{ .name = "table", .ty = container, .span = .{
                .start_line = 1,
                .start_col = 1,
                .end_line = 1,
                .end_col = 1,
            } }},
        ));

        // (2) No element walk. The key here OWNS storage, so an answer of true
        // would free a slab the map only aliases.
        try std.testing.expect(Lowerer.ownedRuntimeContainerType(owned_key));
        try std.testing.expect(!Lowerer.ownerReleasesElements(container));

        // (3) No moveable owner: `takeOwned` refuses a map.
        try std.testing.expect(!Lowerer.ownedRuntimeStorageAt(container, 0, false));
        try std.testing.expect(!Lowerer.ownedRuntimeContainerType(container));
    }

    // The vectors and strings beside it ARE recognised owners, and they DO walk
    // their elements — so the two answers above are decisions, not accidents.
    const string_vec: ir.types.Type = .{ .external_nominal = .{
        .path = &.{ "alloc", "vec", "Vec" },
        .args = &.{owned_key},
    } };
    try std.testing.expect(Lowerer.ownsRuntimeTableOrContainer(string_vec));
    try std.testing.expect(Lowerer.ownerReleasesElements(string_vec));

    // (4) And nothing rewrites a map's method names yet: the vocabulary
    // `r2z-core` publishes for every other receiver has no map member in it.
    //
    // Every tag in that enum is `<receiver>_<method>`, so a map member is one
    // spelled `map_<method>` — a PREFIX, not a substring. A substring search
    // for `map` cannot tell that from `option_map` or `result_map_err`, which
    // are the Option and Result combinators: they end in the same three
    // letters and say nothing at all about a container walk, so matching them
    // would fail on recognised methods this enum has legitimately claimed.
    for (std.meta.tags(Lowerer.RecognizedStdMethod)) |tag| {
        const name = @tagName(tag);
        try std.testing.expect(!std.mem.startsWith(u8, name, "map"));
        for ([_][]const u8{ "insert", "contains_key", "entry" }) |member| {
            try std.testing.expect(std.mem.indexOf(u8, name, member) == null);
        }
    }
}

// A named struct is not an owner type, and `r2z.alloc` agrees.
//
// `dropTemporary` on a `Bag` frees nothing, because `ownsTemporaryStorage`
// refuses a struct that is not a tuple, and `takeOwned` on one is a compile
// error rather than a leak, because `supportsOwnedMove` reaches only the
// containers the runtime owns and the finite wrappers over them. So the only
// move the runtime can spell today is the per-FIELD transfer
// `emitDestructureBinding` already emits, and the lowering emits exactly that.
//
// The direction that would bite is the other one. Arming a scope release on
// the struct is INERT today — that release frees nothing — so the moved
// field's own release fires once. The day the runtime learns to walk a
// foreign named struct, the SAME release starts freeing the field the
// transfer already emptied in place. The struct-level release and the
// field-level transfer have to arrive together, and the struct-level one
// cannot arrive first.
test "a named struct is not an owner type, and the runtime agrees" {
    const struct_segments = [_]ir.types.PathSegment{.{ .name = "Bag", .id = 7 }};
    const named_struct: ir.types.Type = .{ .path = .{ .segments = &struct_segments } };

    // A declared path is not a type-parameter path, so `allow_parameter` cannot
    // reach it either.
    try std.testing.expect(!Lowerer.isTypeParameterPath(named_struct));

    // No scope release, no parameter release, and no owned-move transfer.
    try std.testing.expect(!Lowerer.ownedRuntimeStorageAt(named_struct, 0, false));
    try std.testing.expect(!Lowerer.ownedRuntimeStorageAt(named_struct, 0, true));
    try std.testing.expect(!Lowerer.ownedRuntimeContainerType(named_struct));
    try std.testing.expect(!Lowerer.ownerReleasesElements(named_struct));

    // The runtime container the same pipeline does release, spelled beside it
    // so the two answers are read as one decision rather than two accidents.
    try std.testing.expect(Lowerer.ownedRuntimeContainerType(.{ .external_nominal = .{
        .path = &.{ "alloc", "string", "String" },
        .args = &.{},
    } }));
    try std.testing.expect(!Lowerer.ownerReleasesElements(.{ .external_nominal = .{
        .path = &.{ "alloc", "string", "String" },
        .args = &.{},
    } }));
}

/// How far the rule follows a body's own blocks, and the calls inside them,
/// before it stops asking. Every link is one the source wrote, so a chain this
/// long is a cycle rather than a program, and a cycle has no answer to give.
const allocator_rule_depth_limit = 64;

/// Whether the BODY answers the question its declared return asks, which is
/// what stops the declared return from obliging a parameter on its own.
///
/// The declared type says what the callee hands back; only the body says
/// whether the callee BUILT it. `pub fn borrowed_bytes(input: &[u8]) -> Cow<[u8]>`
/// returns a `Cow`, which owns storage whenever it is the `Owned` arm, and its
/// body writes the `Borrowed` one — the value the caller handed in, renamed.
/// The same holds for `pub fn user_error() -> Result<String, UserError>`: the
/// `ok` arm owns a `String`, and the body writes `Err(UserError { .. })`, so
/// the `String` the signature declares is storage nothing in the body ever
/// builds. Declaring an allocator for either is a parameter the body never
/// reads, and Zig rejects that as an unused function parameter.
///
/// An aggregate the body CONSTRUCTS over expressions the effect scan has
/// already read is the shape that answers. `Cow::Borrowed(slice)` and
/// `Err(IoError { .. })` are both this, and so are `Cow::Owned(owner)` and
/// `Ok(built)`: the payload is a sub-expression, so a payload that allocated
/// is one the scan found, and `effects` already carries that answer.
///
/// A DIRECT CALL is the one dispatch that answers too, because the callee has
/// an answer of its own and asking for it is asking `callPassesAllocator`
/// again. That is what keeps the two directions of the same forwarding pair
/// apart: `fn use(data) -> String { encode(data) }` carries the allocator
/// `encode` declares and passes it on, while `fn use(data) -> Cow<[u8]> {
/// borrowed_bytes(data) }` declares none, because the callee it forwards to
/// declares none and the call site hands over nothing for it to forward.
///
/// Everything else is a DISPATCH the rule cannot follow: a method call, a core
/// call, or another expression that chooses among values. There the effect
/// table has had its turn and found nothing, and the declared return is the
/// one piece of evidence left. That is what
/// `pub fn encode<T: AsRef<[u8]>>(data: T) -> String` in hex/src/lib.rs:259
/// needs: `data.encode_hex()` dispatches through a type parameter the table
/// cannot follow.
///
/// A body that hands back nothing at all answers nothing: a block with no
/// tail, a `return` with no value, and the `()` a body with no tail lowers to
/// are one shape, and it is the state a recovered declaration is read in. The
/// declared return stands in for those, exactly as it did before.
fn bodyAnswersOwnReturn(self: *const Lowerer, body: ir.exprs.NodeId, depth: usize) bool {
    if (depth >= allocator_rule_depth_limit) return false;
    if (body >= self.ir.bodies.exprs.len) return false;
    return switch (self.ir.bodies.exprs[body].kind) {
        .block => |value| if (value.tail) |tail|
            bodyAnswersOwnReturn(self, tail, depth + 1)
        else
            false,
        .return_ => |value| if (value.value) |returned|
            bodyAnswersOwnReturn(self, returned, depth + 1)
        else
            false,
        .unit => false,
        .struct_lit, .enum_variant, .external_variant => true,
        .call => |call| switch (call.call_kind) {
            .constructor => true,
            .free, .associated => |callee| !self.callPassesAllocatorAt(callee, depth + 1),
        },
        else => false,
    };
}

/// The same question read off the two shapes a declaration can have. `depth` is
/// how many direct calls led here, which is what bounds the chain a body that
/// forwards to another one forms.
fn fnBodyTakesAllocator(self: *const Lowerer, body: ir.bodies.FnBody, depth: usize) bool {
    if (body.is_allocating) return true;
    if (!returnTypeNeedsAllocator(body.ret)) return false;
    return !bodyAnswersOwnReturn(self, body.body, depth);
}

fn structMethodTakesAllocator(
    self: *const Lowerer,
    method: ir.bodies.StructMethod,
    depth: usize,
) bool {
    if (method.is_allocating) return true;
    if (!returnTypeNeedsAllocator(method.ret)) return false;
    return !bodyAnswersOwnReturn(self, method.body, depth);
}

const Lowerer = struct {
    alloc: std.mem.Allocator,
    ir: *const ir.RustIr,
    strat: strategy.LoweringStrategy,
    def_strat_inst: default_strat.DefaultStrategy = .{},
    current_module_id: ?ir.spine.EntityId = null,
    /// True while the crate root module is lowered into `src/root.zig`.
    current_file_is_root: bool = false,
    current_imports: ?*std.ArrayListUnmanaged(ast.Import) = null,
    pending_module_imports: std.AutoHashMapUnmanaged(ModuleImportKey, []const u8) = .empty,
    runtime_import_modules: std.AutoHashMapUnmanaged(ir.spine.EntityId, void) = .empty,
    /// One row per declared dependency, borrowed from the graph: both root
    /// spellings a source may use, and the single disposition they resolve to.
    /// Built once before the first file is lowered and read by the import, zon,
    /// alias-reservation and root-classifier consumers, so none of them
    /// re-derives it.
    dependency_dispositions: []const DependencyEntry = &.{},
    /// The inherent struct/enum/union whose method body is being lowered.
    current_struct_id: ?ir.spine.EntityId = null,
    /// Return type of the function currently being lowered.
    current_return_type: ?ir.types.Type = null,
    /// Stable allocator requirements, including cleanup-only paths.
    allocation_effects: ?[]bool = null,
    /// Extra native allocation failures, separate from source Result errors.
    fallibility_effects: ?[]bool = null,
    /// Comparisons that bind an owned operand, indexed by `ir.exprs.NodeId`.
    /// Decided from the same `comparisonTemporaryType` the lowering asks, so
    /// a callable the scan called allocating and the caller that threads the
    /// allocator to it cannot disagree.
    comparison_temporaries: ?[]const bool = null,
    /// `let` bindings that declare a known runtime owner, indexed by statement
    /// node id. Each one obliges its callable to release that owner, which
    /// names the allocator, so the callable needs one before any call site is
    /// settled. Empty when not computed.
    owner_cleanups: ?[]const bool = null,
    pattern_cleanups: ?[]const bool = null,
    /// Allocation effect accumulated while lowering the current callable.
    current_callable_is_allocating: bool = false,
    /// How deep the current chain of "what type does this name hold" answers
    /// runs. Valid Rust cannot build a cycle here — a binding is never read
    /// before its own `let` — but the walk follows initialisers, so the depth
    /// is bounded rather than trusted.
    value_entity_depth: usize = 0,
    /// Type parameters an enclosing `impl` binds that a module-hoisted method
    /// has to declare itself. A blanket `impl<T: Bound> Trait for T` has no
    /// declaration body for its self type, so its methods land at module scope
    /// where nothing else binds `T` — yet the receiver still spells `&T`.
    hoisted_impl_generic_params: []const []const u8 = &.{},
    /// Module-scope entities a DIFFERENT module names. Rust's `private` means
    /// "this module and its descendants", and every Rust `mod` becomes its own
    /// Zig file, so a private item a descendant uses has to be `pub` in the
    /// emitted file or the child cannot reach it. Collected before any
    /// declaration is lowered, because the reference is recorded while the
    /// referring module is lowered and a root declaration is already built.
    cross_module_refs: std.AutoHashMapUnmanaged(ir.spine.EntityId, void) = .empty,
    /// Direct call expression currently lowered by an explicit source `try`.
    explicit_try_expr: ?ir.exprs.NodeId = null,
    /// An explicit floating-point function result supplies the expected type
    /// for nested arithmetic whose operands lack inferred type metadata.
    float_context: bool = false,
    /// Expected source parameter type for the active direct-call argument.
    expected_argument_type: ?ir.types.Type = null,
    /// Source expression node receiving the active expected argument type.
    expected_argument_expr_id: ?ir.exprs.NodeId = null,
    /// The next `lowerBlock` call lowers a FUNCTION BODY. Zig spells a
    /// function body as `{ … }` with no label in front of it, so a scope that
    /// cannot declare one has to be known while the body lowers rather than
    /// after: the ordered chain a guarded `match` lowers to is a labelled block
    /// whose arms leave it through `break :<label> <value>`, and moving its
    /// statements into a body cannot take the label with them.
    ///
    /// `lowerBlock` reads this once, on entry, so a nested block reached from
    /// the body sees it cleared: a block in expression position is emitted with
    /// its label, and only the body is not.
    callable_body_block: bool = false,
    /// Rust type the surrounding expression requires of the value currently
    /// being lowered, for a node the frontend left untyped. Zig spells a
    /// literal with its type name (`[_]u8{...}`, `.{ a, b }`) and a Rust
    /// array or tuple literal the frontend did not annotate has no way to
    /// supply one on its own. Wherever the lowerer has already worked out
    /// what a value is — the element type of a `Vec<T>` it is building, the
    /// arm of a `Result` it is filling, the self type of a blanket impl it
    /// is about to call — that answer is recorded here and read back by
    /// `nodeType`, which prefers the node's own annotation and falls back
    /// here.
    expected_value_type: ?ir.types.Type = null,
    /// The `collect` whose adapter chain is being lowered, when that collect
    /// builds a `Result`. A `?` inside an adapter body — inside the `map`
    /// closure Rust inlines into the loop — is an ordinary Rust error the
    /// collection reports, so it has to leave the collection rather than
    /// return from the enclosing function: a `collect` in let or argument
    /// position has no function to leave, and a `return` there would take the
    /// wrong one. Set only while the adapters are lowered, because a `?` in
    /// the source expression is a function-level propagation in Rust too.
    current_collector: ?Collector = null,
    /// Statement-local owner acquisitions emitted before the current statement.
    current_owner_prelude: ?*std.ArrayListUnmanaged(ast.Stmt) = null,
    /// Names reserved while lowering the current statement.
    current_owner_reserved: ?*std.ArrayListUnmanaged([]const u8) = null,
    /// The statement slices that are OWNER PRELUDES — the bindings a call had
    /// to declare before the value it produces existed, wrapped in a block so
    /// the value could still be handed back.
    ///
    /// Keyed by the slice's own address rather than by the statements' SHAPE.
    /// A prelude is spelled `let` then `defer`, and an ordinary Rust block that
    /// declares an owner and drops it at the end of its scope is spelled
    /// exactly the same way — which is every lexical owner this pass now
    /// releases. Detecting the shape cannot tell the two apart, and hoisting
    /// an ordinary block's statements out of it moves a release out of the
    /// scope that owns it. The address is the prelude's own identity: it is
    /// allocated exactly once, by the call that produced it, and lives as long
    /// as the AST it is part of.
    owner_prelude_stmts: std.AutoHashMapUnmanaged(usize, usize) = .empty,
    /// Parameter bindings visible while lowering the current callable body.
    current_parameter_names: []const ast.FnParam = &.{},
    /// Parameters the current callable passed as an immutable copy, beside
    /// the body bindings those copies feed. Empty unless the callable's body
    /// needed mutable storage for one of its parameters.
    current_mutable_copies: []const MutableCopyBinding = &.{},
    /// Declaration name visible while lowering the current callable body.
    current_callable_name: ?[]const u8 = null,
    /// EntityId of the function or method currently being lowered.
    current_callable_id: ?ir.spine.EntityId = null,
    /// Loop capture names visible while lowering the current loop body.
    current_capture_names: []const []const u8 = &.{},
    /// Value-capture bindings visible while lowering the current loop body.
    current_value_capture_scopes: []const ValueCaptureScope = &.{},
    /// Lexical local bindings that shadow loop captures.
    current_shadow_scope: ?*const ShadowScope = null,
    /// Emitted names for source bindings in the active callable.
    current_local_binding_names: ?*LocalBindingNames = null,
    /// Reused across callable cleanup scans; never walk unrelated functions.
    scope_drop_walker: ?ir.exprs.NodeWalker = null,
    /// Local closure definitions lowered inline at each call site.
    local_closures: std.StringHashMapUnmanaged(ir.exprs.ClosureExpr) = .empty,
    /// By-value captures copied when each local closure is defined.
    local_closure_snapshots: std.StringHashMapUnmanaged([]const LocalClosureCaptureSnapshot) = .empty,
    /// Capture prelude receiving by-value iterator snapshots.
    current_iterator_capture_prelude: ?*std.ArrayListUnmanaged(ast.Stmt) = null,
    /// Monotonic suffix for iterator capture snapshot names.
    next_iterator_capture_id: usize = 0,
    /// Capture names currently resolved to a local closure snapshot.
    active_closure_capture_overrides: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Owner snapshots and their move sites in the current arm or closure.
    active_owned_capture_move: ?OwnedCaptureMoveSet = null,
    /// Owner bindings of the lexical scopes currently being lowered, innermost
    /// last. An entry stays for the whole block that declared it, which is what
    /// scopes its release, and a nested binding that shadows an outer one pushes
    /// its own entry beside it rather than replacing it — the two are different
    /// values with different releases.
    ///
    /// Arm and closure snapshots shadow lexical owners while their bodies lower.
    /// Their releases remain in the scope that created their storage.
    owned_scope_bindings: std.ArrayListUnmanaged(OwnedScopeBinding) = .empty,
    /// Stable module-level names for function-local `static` items.
    local_static_names: std.AutoHashMapUnmanaged(ir.spine.EntityId, []const u8) = .empty,

    /// True only while lowering a translated test body.
    lowering_test_entity: bool = false,

    /// Map from target struct/enum EntityId to hoisted method declarations
    hoisted_by_id: std.AutoHashMapUnmanaged(ir.spine.EntityId, std.ArrayListUnmanaged(ast.Decl)) = .empty,
    /// Emitted name for every hoisted method EntityId. A method reaches the
    /// output under a name that is not always its source name, so a call site
    /// resolves through this map rather than through `renamed_to`.
    hoisted_method_names: std.AutoHashMapUnmanaged(ir.spine.EntityId, []const u8) = .empty,
    /// Target EntityId → emitted method name → the identity of the impl that
    /// claimed it there. Two impl blocks that declare the SAME function — the
    /// same self type and the same trait instantiation — collapse onto one
    /// declaration; two that declare the same method name for DIFFERENT
    /// reasons are different functions, and each is emitted under a name of
    /// its own.
    hoisted_self_type_keys: std.AutoHashMapUnmanaged(ir.spine.EntityId, std.StringHashMapUnmanaged([]const u8)) = .empty,
    /// Struct EntityId → source field name → emitted field name. Only a field
    /// that collides with a method on the same struct appears; Zig has one
    /// namespace for both, so the method keeps the source name (the iterator
    /// protocol is called by name) and the field takes a fresh one.
    renamed_struct_fields: std.AutoHashMapUnmanaged(ir.spine.EntityId, std.StringHashMapUnmanaged([]const u8)) = .empty,
    /// Generic trait projections request one descriptor declaration per trait.
    trait_descriptor_requests: std.ArrayListUnmanaged(TraitDescriptorRequest) = .empty,
    /// One private, source-aware Hash walk pair per owning module.
    hash_walk_requests: std.ArrayListUnmanaged(HashWalkRequest) = .empty,
    hash_source_methods: ?[]const CanonicalHashSourceMethod = null,
    hash_dispatches: ?[]const HashDispatch = null,

    fn init(
        allocator: std.mem.Allocator,
        rust_ir: *const ir.RustIr,
        custom_strat: ?*const strategy.LoweringStrategy,
    ) Lowerer {
        var lowerer: Lowerer = .{
            .alloc = allocator,
            .ir = rust_ir,
            .strat = undefined,
        };

        if (custom_strat) |cs| {
            lowerer.strat = cs.*;
        } else {
            lowerer.strat = .{
                .ptr = &lowerer.def_strat_inst,
                .vtable = &.{
                    .lowerType = default_strat.DefaultStrategy.lowerType,
                    .lowerStdGeneric = default_strat.DefaultStrategy.lowerStdGeneric,
                },
            };
        }

        return lowerer;
    }
    fn methodEntityForDefinition(
        self: *const Lowerer,
        owner_id: ir.spine.EntityId,
        method: ir.bodies.StructMethod,
    ) ?ir.spine.EntityId {
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .fn_) continue;
            if (!std.mem.eql(u8, entity.name, method.name)) continue;
            if (entity.id >= self.ir.bodies.bodies.len) continue;
            const body = switch (self.ir.bodies.bodies[entity.id]) {
                .fn_ => |function| function,
                else => continue,
            };
            if (body.body != method.body) continue;

            var parent_id = entity.parent;
            while (parent_id) |id| {
                if (id == owner_id) return entity.id;
                const parent = self.ir.graph.symbol_table.get(id) orelse break;
                parent_id = parent.parent;
            }
        }
        return null;
    }

    /// THE rule for the leading `allocator` argument, asked from both ends of a
    /// call. `lowerFnEntity` and `lowerStructMethod` declare the parameter it
    /// names, and every call site hands one over — a free call, an associated
    /// call, a method call, a blanket impl's hoisted method. Both sides read
    /// this and nothing else, which is the whole contract: a declaration that
    /// carries an allocator its call sites never pass is emitted one argument
    /// short and Zig rejects the call.
    ///
    /// Three things put that parameter on a declaration. What the BODY does,
    /// which `computeAllocationEffects` records over the flat tables before any
    /// declaration lowers. What the DECLARATION itself records: `is_allocating`,
    /// on a `fn` body or on a struct method. And what the declared return says.
    ///
    /// The third is not a shortcut around the table, but it is not the table's
    /// answer either. It stands in only where the table has nothing: the table
    /// follows the RESOLVED call graph, and a body that reaches a blanket
    /// trait's method through a type parameter — `data.encode_hex()` in
    /// `pub fn encode<T: AsRef<[u8]>>(data: T) -> String` — resolves outside
    /// it. Such a declaration learns the obligation while its OWN body lowers,
    /// which is after every call site has been settled: the declaration
    /// emitted `encode(comptime T: type, allocator: std.mem.Allocator, data: T)`
    /// and every call reached it as `encode([]const u8, "foobar")`.
    ///
    /// A body that BUILDS nothing is the other end of the same line, and the
    /// declared return must not overrule it. `bodyAnswersOwnReturn` is what
    /// tells the two apart: a body that constructs its answer out of
    /// expressions the scan already read — or that forwards to a callee that
    /// answers the same way — has had its turn, and a `Cow<[u8]>` or a
    /// `Result<String, _>` it hands back is storage somebody else owns. Both
    /// ends read this one function, so a declaration and its call sites cannot
    /// disagree about a parameter only one of them has a use for.
    fn callPassesAllocator(self: *const Lowerer, def: ir.spine.EntityId) bool {
        return self.callPassesAllocatorAt(def, 0);
    }

    /// The same rule one link along a chain of bodies that forward to each
    /// other, so the chain terminates instead of asking a cycle for an answer
    /// it does not have.
    fn callPassesAllocatorAt(self: *const Lowerer, def: ir.spine.EntityId, depth: usize) bool {
        if (self.allocation_effects) |effects| {
            if (def < effects.len and effects[def]) return true;
        }
        if (self.structMethodForDef(def)) |method| {
            if (structMethodTakesAllocator(self, method, depth)) return true;
        }
        if (def >= self.ir.bodies.bodies.len) return false;
        return switch (self.ir.bodies.bodies[def]) {
            .fn_ => |function| fnBodyTakesAllocator(self, function, depth),
            else => false,
        };
    }

    fn callableFallible(self: *const Lowerer, entity_id: ir.spine.EntityId) bool {
        const effects = self.fallibility_effects orelse return false;
        return entity_id < effects.len and effects[entity_id];
    }

    /// Comparisons that bind an owned operand, indexed by `ir.exprs.NodeId`.
    ///
    /// `bindComparisonOperand` releases a comparison's temporaries with
    /// `r2z.alloc.dropTemporary(allocator, ..)` while the declaration is
    /// lowered, but every call site was settled from `allocation_effects`
    /// before that happened. A callee whose declaration takes an allocator
    /// its callers never pass is emitted one argument short, with no `try`
    /// for the error union the declaration does have: the body compiles to
    /// `temporary_user_error_equal(allocator) !bool` and its `#[test]` calls
    /// `temporary_user_error_equal()`.
    ///
    /// Only `==` and `!=` are considered. `lowerBorrowedComparison` hands
    /// every other operator straight to the runtime without binding an
    /// operand, and an operand that needs a temporary drop is a container —
    /// never a primitive — so `requiresRuntimeComparison` is already true
    /// wherever one is owned. A borrowed named owner and a scalar answer
    /// `null` in `comparisonTemporaryType` and ask for nothing here.
    ///
    /// The expression table is flat and dense, so every comparison is
    /// reachable by walking it once; no body needs traversing twice.
    ///
    /// This runs once, over the flat table, with no callable in scope:
    /// `current_callable_id`, `expected_value_type` and every other ambient
    /// input `lowerBorrowedComparison` will have is still null. The verdict
    /// therefore has to come out of the expression graph alone, or the mask
    /// and the declaration disagree and the allocator the declaration
    /// declares reaches no call site. `declaredBindingType` is what keeps it
    /// honest — a parameter is read from the body that declares it, not from
    /// whichever callable happens to be lowering.
    fn computeComparisonTemporaries(self: *Lowerer) ![]const bool {
        const owned = try self.alloc.alloc(bool, self.ir.bodies.exprs.len);
        errdefer self.alloc.free(owned);
        @memset(owned, false);
        for (self.ir.bodies.exprs, 0..) |expr, node_id| {
            const binary = switch (expr.kind) {
                .binary => |value| value,
                else => continue,
            };
            if (binary.op != .eq and binary.op != .ne) continue;
            if ((try self.comparisonTemporaryType(binary.lhs)) != null or
                (try self.comparisonTemporaryType(binary.rhs)) != null)
            {
                owned[node_id] = true;
            }
        }
        return owned;
    }

    /// `let` statements that declare a known runtime owner, over the flat
    /// statement table.
    ///
    /// Declaring an owner is what obliges the enclosing callable to release it,
    /// and that release names the allocator. Nothing in the call graph records
    /// it — the cleanup is emitted while the declaration lowers, long after
    /// every call site was settled — so the effect has to be discovered here or
    /// not at all, and a callable reached only through this would be emitted
    /// one argument short.
    ///
    /// The statement table is flat and dense, so every binding is reachable by
    /// walking it once; no body needs traversing twice.
    fn computeOwnerCleanups(self: *Lowerer) ![]const bool {
        const owned = try self.alloc.alloc(bool, self.ir.bodies.stmts.len);
        errdefer self.alloc.free(owned);
        @memset(owned, false);
        for (self.ir.bodies.stmts, 0..) |stmt, node_id| {
            const let_statement = switch (stmt.kind) {
                .let => |value| value,
                else => continue,
            };
            const init_id = let_statement.init orelse continue;
            if (let_statement.pattern >= self.ir.bodies.pats.len) continue;
            const pattern = self.ir.bodies.pats[let_statement.pattern];
            if (pattern.kind == .tuple or pattern.kind == .reference) {
                const source_type = try self.destructureSourceType(let_statement.pattern, init_id) orelse continue;
                if (ownsRuntimeTableOrContainer(source_type)) owned[node_id] = true;
                continue;
            }
            const type_id = pattern.ty orelse self.ir.bodies.exprs[init_id].ty orelse continue;
            if (ownsRuntimeTableOrContainer(try self.typeById(type_id))) owned[node_id] = true;
        }
        return owned;
    }
    fn computePatternCleanups(self: *Lowerer) ![]const bool {
        const owned = try self.alloc.alloc(bool, self.ir.bodies.exprs.len);
        errdefer self.alloc.free(owned);
        @memset(owned, false);
        for (self.ir.bodies.exprs, 0..) |expr, node_id| {
            owned[node_id] = switch (expr.kind) {
                .for_ => |for_expr| try self.forExprReleasesPatternPayload(for_expr),
                .if_let => |if_let| try self.ifLetEmitsOwnedRelease(if_let),
                else => false,
            };
        }
        return owned;
    }

    fn forExprReleasesPatternPayload(
        self: *Lowerer,
        for_expr: ir.exprs.ForExpr,
    ) anyerror!bool {
        switch (for_expr.iter_kind) {
            .slice => {
                if (for_expr.pattern >= self.ir.bodies.pats.len) return false;
                return self.forInputReleasesPatternPayload(
                    for_expr.iterable,
                    for_expr.pattern,
                );
            },
            .enumerate => {
                if (for_expr.pattern >= self.ir.bodies.pats.len) return false;
                const pat = self.ir.bodies.pats[for_expr.pattern];
                if (pat.kind != .tuple) return false;
                if (pat.kind.tuple.elements.len != 2) return false;
                return self.forInputReleasesPatternPayload(
                    for_expr.iterable,
                    pat.kind.tuple.elements[1],
                );
            },
            .multi => |ids| {
                if (for_expr.pattern >= self.ir.bodies.pats.len) return false;
                const pat = self.ir.bodies.pats[for_expr.pattern];
                if (pat.kind != .tuple) return false;
                if (pat.kind.tuple.elements.len != ids.len) return false;
                for (ids, 0..) |mid, mi| {
                    if (try self.forInputReleasesPatternPayload(mid, pat.kind.tuple.elements[mi])) {
                        return true;
                    }
                }
                return false;
            },
            .adapter => return false,
            .range => return false,
        }
    }

    fn forInputReleasesPatternPayload(
        self: *Lowerer,
        mid: ir.exprs.NodeId,
        element: ir.exprs.NodeId,
    ) anyerror!bool {
        if (try self.isRuntimeIteratorInput(mid)) {
            return self.iteratorPayloadReleases(mid, element);
        }
        const by_ref = try self.patternCapturesByReference(element) or
            try self.iteratorSourceByReference(mid);
        return (try self.forInputDrain(mid, element, by_ref)) != .untouched;
    }
    fn computeHashDispatches(self: *Lowerer) ![]const HashDispatch {
        if ((try self.canonicalHashSourceMethods()).len == 0) return &.{};
        const nodes = try self.alloc.alloc(HashDispatch, self.ir.bodies.exprs.len);
        errdefer self.alloc.free(nodes);
        @memset(nodes, .none);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.id >= self.ir.bodies.bodies.len) continue;
            switch (self.ir.bodies.bodies[entity.id]) {
                .fn_ => |function| try self.markHashDispatchNodes(entity.id, function.body, nodes),
                .struct_ => |structure| for (structure.methods) |method| {
                    const method_id = self.methodEntityForDefinition(entity.id, method) orelse continue;
                    try self.markHashDispatchNodes(method_id, method.body, nodes);
                },
                else => {},
            }
        }
        return nodes;
    }

    fn markHashDispatchNodes(
        self: *Lowerer,
        owner: ir.spine.EntityId,
        root: ir.exprs.NodeId,
        nodes: []HashDispatch,
    ) !void {
        if (self.scope_drop_walker == null) {
            self.scope_drop_walker = try ir.exprs.NodeWalker.init(
                self.alloc,
                self.ir.bodies.exprs,
                self.ir.bodies.stmts,
                self.ir.bodies.pats,
                self.ir.bodies.types,
            );
        }
        const walker = &self.scope_drop_walker.?;
        const previous_callable_id = self.current_callable_id;
        self.current_callable_id = owner;
        defer self.current_callable_id = previous_callable_id;
        const previous_module_id = self.current_module_id;
        self.current_module_id = (try self.owningModuleEntity(owner)) orelse previous_module_id;
        defer self.current_module_id = previous_module_id;
        const previous_struct_id = self.current_struct_id;
        self.current_struct_id = (try self.inherentStructForEntity(owner)) orelse previous_struct_id;
        defer self.current_struct_id = previous_struct_id;
        walker.reset(root) catch |failure| return walkerErrorAsLowererError(failure);
        while (walker.next() catch |failure| return walkerErrorAsLowererError(failure)) |node| {
            const expr_id = switch (node) {
                .expression => |id| id,
                else => continue,
            };
            if (expr_id >= self.ir.bodies.exprs.len) continue;
            if (!nodes[expr_id].isNone()) continue;
            nodes[expr_id] = try self.hashDispatchNodeOf(expr_id);
        }
    }

    fn hashDispatchNodeOf(self: *Lowerer, node_id: ir.exprs.NodeId) anyerror!HashDispatch {
        switch (self.ir.bodies.exprs[node_id].kind) {
            .core_call => |call| return self.coreCallHashDispatch(call),
            .method_call => |method_call| {
                const method = self.ir.graph.symbol_table.get(method_call.method) orelse return .none;
                if (method.kind != .method_ref) return .none;
                if (method.parent) |parent| {
                    const parent_entity = self.ir.graph.symbol_table.get(parent);
                    if (parent_entity != null and parent_entity.?.kind == .trait_) return .none;
                }
                const owner_id = self.current_callable_id orelse return .none;
                const receiver_type = (try self.exprType(method_call.receiver)) orelse return .none;
                if (!isTypeParameterPath(peelReceiverType(receiver_type))) return .none;
                if (ir.bodies.genericBound(
                    &self.ir.graph,
                    &self.ir.bodies,
                    owner_id,
                    receiver_type,
                    &.{ "core", "hash", "Hasher" },
                ) != null) {
                    if (std.mem.eql(u8, method.name, "write")) return .{ .write = {} };
                    if (hasherPrimitiveType(method.name)) |written| {
                        switch (written) {
                            .prim => |primitive| return HashDispatch.forPrimitive(primitive),
                            else => {},
                        }
                    }
                    return .none;
                }
                if (std.mem.eql(u8, method.name, "hash") and
                    ir.bodies.genericBound(
                        &self.ir.graph,
                        &self.ir.bodies,
                        owner_id,
                        receiver_type,
                        &.{ "core", "hash", "Hash" },
                    ) != null)
                {
                    return .hash_walk;
                }
                return .none;
            },
            else => return .none,
        }
    }

    fn coreCallHashDispatch(self: *Lowerer, call: ir.exprs.CoreCall) anyerror!HashDispatch {
        if (call.function != .hash_write_primitive) return .none;
        if (call.generic_args.len != 1 or call.args.len == 0) return .none;
        const primitive = switch (call.generic_args[0]) {
            .prim => |tag| tag,
            else => return .none,
        };
        const dispatch = HashDispatch.forPrimitive(primitive);
        if (dispatch.isNone()) return .none;
        const receiver_type = (try self.exprType(call.args[0])) orelse return .none;
        const hasher_type = peelReceiverType(receiver_type);
        if (isTypeParameterPath(hasher_type)) return .none;
        const writes = (try self.sourceHasherWrites(hasher_type, dispatch.writeMethodName())) orelse return .none;
        const target = writes.primitive_write orelse writes.byte_write orelse return .none;
        return .{ .source_method = target };
    }

    fn computeAllocationEffects(self: *Lowerer) !void {
        if (self.allocation_effects != null) return;
        const comparison_temporaries = try self.computeComparisonTemporaries();
        errdefer self.alloc.free(comparison_temporaries);
        const owner_cleanups = try self.computeOwnerCleanups();
        errdefer self.alloc.free(owner_cleanups);
        const pattern_cleanups = try self.computePatternCleanups();
        errdefer self.alloc.free(pattern_cleanups);
        const hash_source_methods = try self.canonicalHashSourceMethods();
        const hash_dispatches = try self.computeHashDispatches();
        errdefer self.alloc.free(hash_dispatches);
        const allocators = try self.computeCallableEffects(.allocator, comparison_temporaries, owner_cleanups, pattern_cleanups, hash_source_methods, hash_dispatches);
        errdefer self.alloc.free(allocators);
        // An owner release is CLEANUP, never an allocation failure: `deinit`
        // returns `void` and frees what is already there, so it invents no
        // error union and the failure table is settled without it. Passing an
        // empty mask is how that separation is stated, and it is the same one
        // the comparison temporaries keep.
        const failures = try self.computeCallableEffects(.allocation_failure, &.{}, &.{}, &.{}, hash_source_methods, hash_dispatches);
        self.allocation_effects = allocators;
        self.fallibility_effects = failures;
        self.comparison_temporaries = comparison_temporaries;
        self.owner_cleanups = owner_cleanups;
        self.pattern_cleanups = pattern_cleanups;
        self.hash_dispatches = hash_dispatches;
    }

    const CallableEffectKind = enum { allocator, allocation_failure };

    fn computeCallableEffects(
        self: *Lowerer,
        comptime kind: CallableEffectKind,
        comparison_temporaries: []const bool,
        owner_cleanups: []const bool,
        pattern_cleanups: []const bool,
        hash_source_methods: []const CanonicalHashSourceMethod,
        hash_dispatches: []const HashDispatch,
    ) ![]bool {
        const effect_count = @max(
            self.ir.graph.symbol_table.count(),
            self.ir.bodies.bodies.len,
        );
        const effects = try self.alloc.alloc(bool, effect_count);
        errdefer self.alloc.free(effects);
        @memset(effects, false);

        // A recognised standard method has no declaration body to scan, so the
        // fixed point below can never discover it: both its seeding loop and
        // its propagation loop only ever SET effects for `.fn_` entities, while
        // `methodTargetAllocates` reads `effects[target]` for whatever a call
        // names. `String::push` may reallocate the buffer it appends to, so its
        // method reference is marked here — which is what every call site of it
        // reads when it decides whether the callee takes an allocator.
        for (self.ir.bodies.exprs) |expression| {
            const method_call = switch (expression.kind) {
                .method_call => |value| value,
                else => continue,
            };
            if (method_call.method >= effects.len) continue;
            if (try self.stdMethodCallAllocates(kind, method_call)) {
                effects[method_call.method] = true;
            }
        }

        const direct_scanner: AllocationEffectScanner = .{
            .exprs = self.ir.bodies.exprs,
            .stmts = self.ir.bodies.stmts,
            .effects = &.{},
            .comparison_temporaries = comparison_temporaries,
            .owner_cleanups = owner_cleanups,
            .pattern_cleanups = pattern_cleanups,
            .hash_dispatches = hash_dispatches,
            .hash_source_methods = hash_source_methods,
        };

        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.id >= effects.len) continue;
            if (entity.kind != .fn_) continue;
            if (entity.id >= self.ir.bodies.bodies.len) continue;
            const body = switch (self.ir.bodies.bodies[entity.id]) {
                .fn_ => |function| function,
                else => continue,
            };
            // A by-value owner parameter is an owner this callable OWNS: Rust
            // hands it over, so the callee releases it and that release names
            // the allocator. A borrowed parameter is not one — it is a
            // `.reference`, which `ownedRuntimeContainerType` does not match —
            // so the split comes from the declared type rather than a flag.
            if ((kind == .allocator and
                (body.is_allocating or paramsOwnRuntimeContainer(body.params))) or
                direct_scanner.exprAllocates(body.body))
            {
                effects[entity.id] = true;
            }
            if (self.structMethodForDef(entity.id)) |method| {
                if (kind == .allocator and method.is_allocating) effects[entity.id] = true;
            }
        }

        // Some recovered fixtures retain method metadata only on StructBody.
        // Bind those effects to the resolved method entity before propagation.
        for (self.ir.graph.symbol_table.entities.items) |owner| {
            if (owner.kind != .struct_ and owner.kind != .enum_ and owner.kind != .union_) {
                continue;
            }
            if (owner.id >= self.ir.bodies.bodies.len) continue;
            const structure = switch (self.ir.bodies.bodies[owner.id]) {
                .struct_ => |body| body,
                else => continue,
            };
            for (structure.methods) |method| {
                if (!(kind == .allocator and
                    (method.is_allocating or paramsOwnRuntimeContainer(method.params))) and
                    !direct_scanner.exprAllocates(method.body) and
                    !try self.bodyConvertsErrorThroughAllocatingFrom(
                        method.body,
                        method.ret,
                        effects,
                    ))
                {
                    continue;
                }
                if (self.methodEntityForDefinition(owner.id, method)) |method_id| {
                    if (method_id < effects.len) effects[method_id] = true;
                }
            }
        }

        // Two recognitions read a trait bound off a type parameter, and
        // `genericBound` can only read that bound inside the callable that
        // declares the parameter — so the flat loop above, which runs with no
        // callable in scope, can never classify either of them.
        // `write::unsigned` reached `write_all`, kept a plain `Result` in its
        // declaration, and emitted a `try` on a helper that reports
        // `error.OutOfMemory`: nowhere for it to go. The pass below asks the
        // same question with the owning callable in scope, which is what the
        // declaration lowering has when it reaches that same call.
        //
        // Nothing to look for unless the crate names one of them somewhere:
        // a walk per body would reach IR the declaration lowering never touches,
        // and report a malformed reference in a body that lowers perfectly well
        // today. That is a crate with no `read_exact` and no `write_all` at all
        // — which is every fixture but `leb128`.
        if (self.crateCallsTraitBoundIoMethod()) {
            for (self.ir.graph.symbol_table.entities.items) |entity| {
                if (entity.id >= self.ir.bodies.bodies.len) continue;
                const root = switch (self.ir.bodies.bodies[entity.id]) {
                    .fn_ => |function| function.body,
                    else => continue,
                };
                try self.seedScopedTraitMethodEffects(kind, entity.id, root, effects);
            }
            for (self.ir.graph.symbol_table.entities.items) |owner| {
                if (owner.kind != .struct_ and owner.kind != .enum_ and owner.kind != .union_) {
                    continue;
                }
                if (owner.id >= self.ir.bodies.bodies.len) continue;
                const structure = switch (self.ir.bodies.bodies[owner.id]) {
                    .struct_ => |body| body,
                    else => continue,
                };
                for (structure.methods) |method| {
                    const method_id = self.methodEntityForDefinition(owner.id, method) orelse continue;
                    try self.seedScopedTraitMethodEffects(kind, method_id, method.body, effects);
                }
            }
        }

        const scanner: AllocationEffectScanner = .{
            .exprs = self.ir.bodies.exprs,
            .stmts = self.ir.bodies.stmts,
            .effects = effects,
            .comparison_temporaries = comparison_temporaries,
            .owner_cleanups = owner_cleanups,
            .pattern_cleanups = pattern_cleanups,
            .hash_dispatches = hash_dispatches,
            .hash_source_methods = hash_source_methods,
        };

        // A blanket trait's method call names the trait's `.method_ref` while
        // its effect belongs to the impl's `fn` behind it, so the scan reads an
        // entry nothing ever writes. Each edge is the resolution the
        // declaration lowering itself performs, and propagating it is what puts
        // a caller such as `fn encode<T: AsRef<[u8]>>(data: T) -> String` back
        // in the tables the calls in its own body put it in.
        const blanket_edges = try self.blanketDispatchEdges();
        defer self.alloc.free(blanket_edges);

        // Each round can turn at least one callable from false to true. The
        // number of rounds is therefore bounded by the finite effect table.
        var round: usize = 0;
        while (round < effect_count) : (round += 1) {
            var changed = false;
            for (self.ir.graph.symbol_table.entities.items) |entity| {
                if (entity.kind != .fn_) continue;
                if (entity.id >= effects.len or entity.id >= self.ir.bodies.bodies.len) continue;
                const body = switch (self.ir.bodies.bodies[entity.id]) {
                    .fn_ => |function| function,
                    else => continue,
                };
                if (effects[entity.id]) continue;
                if (scanner.exprAllocates(body.body) or
                    try self.bodyConvertsErrorThroughAllocatingFrom(body.body, body.ret, effects))
                {
                    effects[entity.id] = true;
                    changed = true;
                }
            }
            for (blanket_edges) |edge| {
                if (edge.target >= effects.len or edge.reference >= effects.len) continue;
                if (!effects[edge.target] or effects[edge.reference]) continue;
                effects[edge.reference] = true;
                changed = true;
            }
            if (!changed) break;
        }

        return effects;
    }

    /// Whether a recognised standard method lowers to a runtime helper that
    /// takes the enclosing allocator.
    ///
    /// These are exactly the `lowerStdMethodCall` arms that hand an
    /// `allocator` on: each may grow or build owned storage, so a callable
    /// that reaches one declares an allocator and every callable that calls
    /// it passes one. `clone` is the one receiver-dependent name, and
    /// `stdMethodCallAllocates` is what asks the receiver-dependent question.
    fn takesAllocator(method: RecognizedStdMethod) bool {
        return switch (method) {
            .borrowed_to_owned,
            .cow_to_owned,
            .string_push,
            .string_push_str,
            .vec_push,
            .vec_extend,
            .io_write_all,
            .iterator_collect,
            .error_union_expect_err,
            .result_unwrap,
            .result_unwrap_err,
            .result_expect,
            .result_expect_err,
            .result_ok,
            .result_err,
            .to_string,
            => true,
            else => false,
        };
    }

    /// Whether this crate calls either trait-bound standard method at all.
    ///
    /// One flat pass over the expression table, and its answer decides whether
    /// the per-callable pass runs at all. A crate that never names either has
    /// nothing for that pass to classify, and walking every body anyway would
    /// read IR the declaration lowering never reaches — reporting a malformed
    /// reference in a body that lowers perfectly well today.
    fn crateCallsTraitBoundIoMethod(self: *const Lowerer) bool {
        for (self.ir.bodies.exprs) |expression| {
            const method_call = switch (expression.kind) {
                .method_call => |value| value,
                else => continue,
            };
            const method = self.ir.graph.symbol_table.get(method_call.method) orelse continue;
            if (isTraitBoundIoMethodName(method.name)) return true;
        }
        return false;
    }

    /// The lowering's own name for a reference the walk found out of range.
    ///
    /// A `NodeWalker` says which TABLE an id fell outside; the lowering has
    /// always reported the same defect by what it is MISSING, and a caller
    /// cannot tell the two apart. Every body this pass reads is a body the
    /// declaration lowering reads too, so the pass reports the error the
    /// lowering would have reported rather than renaming it.
    ///
    /// Nothing is swallowed: each walk failure returns, translated. An
    /// allocation failure is not a walk failure — the walker is allocated once
    /// and reused — so it never reaches here and propagates untouched.
    fn walkerErrorAsLowererError(failure: ir.exprs.NodeWalkError) anyerror {
        return switch (failure) {
            error.InvalidExprRef => error.MissingExpressionNode,
            error.InvalidStatementRef => error.MissingStatementNode,
            error.InvalidPatternRef => error.MissingPatternNode,
            error.InvalidTypeRef => error.MissingTypeId,
            error.InvalidTypeTraversal => error.InvalidTypeTraversal,
        };
    }

    /// Seed the effect of a trait-bound standard method reached from one
    /// callable's body, with that callable in scope.
    ///
    /// `owner` is what `genericBound` walks up from, so a `W` declared in one
    /// function answers only for a receiver that function declares — never for
    /// one of the same name in another. `root` is the body the walk starts at,
    /// and the walker is the one the owned-scope scan already reuses: one
    /// allocation for the whole pass, reset per body.
    ///
    /// Only `read_exact` and `write_all` are asked about. Every other
    /// recognition reads nothing from the callable, so the flat pass has
    /// already answered it and a second opinion here could only disagree.
    fn seedScopedTraitMethodEffects(
        self: *Lowerer,
        comptime kind: CallableEffectKind,
        owner: ir.spine.EntityId,
        root: ir.exprs.NodeId,
        effects: []bool,
    ) !void {
        if (self.scope_drop_walker == null) {
            self.scope_drop_walker = try ir.exprs.NodeWalker.init(
                self.alloc,
                self.ir.bodies.exprs,
                self.ir.bodies.stmts,
                self.ir.bodies.pats,
                self.ir.bodies.types,
            );
        }
        const walker = &self.scope_drop_walker.?;
        const previous_callable_id = self.current_callable_id;
        self.current_callable_id = owner;
        defer self.current_callable_id = previous_callable_id;
        walker.reset(root) catch |failure| return walkerErrorAsLowererError(failure);
        while (walker.next() catch |failure| return walkerErrorAsLowererError(failure)) |node| {
            const expr_id = switch (node) {
                .expression => |id| id,
                else => continue,
            };
            if (expr_id >= self.ir.bodies.exprs.len) continue;
            const method_call = switch (self.ir.bodies.exprs[expr_id].kind) {
                .method_call => |value| value,
                else => continue,
            };
            if (method_call.method >= effects.len) continue;
            if (effects[method_call.method]) continue;
            const method = self.ir.graph.symbol_table.get(method_call.method) orelse continue;
            if (!isTraitBoundIoMethodName(method.name)) continue;
            if (try self.stdMethodCallAllocates(kind, method_call)) {
                effects[method_call.method] = true;
            }
        }
    }

    /// Whether this method call reaches an allocating standard helper.
    ///
    /// `Clone` is in the canonical set for the receiver that owns storage
    /// and for no other: the runtime's deep copy allocates, while a plain
    /// copy of a value that owns nothing duplicates no allocation.
    fn stdMethodCallAllocates(
        self: *Lowerer,
        comptime kind: CallableEffectKind,
        method_call: ir.exprs.MethodCall,
    ) !bool {
        const method = self.ir.graph.symbol_table.get(method_call.method) orelse return false;
        const recognized = try self.lookupRecognizedStdMethod(method_call.receiver, method.name) orelse
            return false;
        if (recognized == .clone) return self.isCowReceiver(method_call.receiver);
        if (kind == .allocation_failure) switch (recognized) {
            .error_union_expect_err, .result_unwrap, .result_unwrap_err, .result_expect, .result_expect_err, .result_ok, .result_err => return false,
            else => {},
        };
        return takesAllocator(recognized);
    }

    /// Whether a callable's `?` reaches a `From` conversion that allocates.
    ///
    /// The conversion is a call this backend invents, not one the IR carries:
    /// Rust wrote `?` and the crate wrote the `impl From<..> for ..`, and
    /// nothing in the expression tree names the `fn from`. So the effect pass
    /// asks the question the source asks — which conversion would this `?`
    /// run, and does that declaration allocate — because a callable's header
    /// decides its allocator parameter from this table, before any body is
    /// lowered. Without it the emitted conversion would name an `allocator`
    /// the declaration never took.
    ///
    /// `effects` is the table as it stands, so the question is asked again in
    /// every round: a `from` that only becomes allocating later still reaches
    /// its caller once the fixed point gets there.
    fn bodyConvertsErrorThroughAllocatingFrom(
        self: *Lowerer,
        body: ir.exprs.NodeId,
        ret: ir.types.Type,
        effects: []const bool,
    ) anyerror!bool {
        const ret_result = switch (ret) {
            .result => |value| value.*,
            else => return false,
        };
        var walker = try ir.exprs.NodeWalker.init(
            self.alloc,
            self.ir.bodies.exprs,
            self.ir.bodies.stmts,
            self.ir.bodies.pats,
            self.ir.bodies.types,
        );
        defer walker.deinit();
        walker.reset(body) catch return false;
        while (walker.next() catch null) |node| {
            const expr_id = switch (node) {
                .expression => |id| id,
                else => continue,
            };
            if (expr_id >= self.ir.bodies.exprs.len) continue;
            const inner = switch (self.ir.bodies.exprs[expr_id].kind) {
                .try_ => |value| value.inner,
                else => continue,
            };
            const operand_type = (try self.exprType(inner)) orelse continue;
            const operand_result = switch (operand_type) {
                .result => |value| value.*,
                else => continue,
            };
            // The same error type is Rust's identity conversion: no call runs,
            // so no allocator is needed.
            if (typeEquals(operand_result.err, ret_result.err)) continue;
            const from_id = self.userFromConversion(operand_result.err, ret_result.err) orelse
                continue;
            if (from_id < effects.len and effects[from_id]) return true;
        }
        return false;
    }

    fn allocType(self: *Lowerer, t: ast.Type) !*const ast.Type {
        const ptr = try self.alloc.create(ast.Type);
        ptr.* = t;
        return ptr;
    }

    fn allocExpr(self: *Lowerer, e: ast.Expr) !*const ast.Expr {
        const ptr = try self.alloc.create(ast.Expr);
        ptr.* = e;
        return ptr;
    }

    /// Cache dispositions before package imports or dependency aliases are emitted.
    fn classifyCrateDependencies(self: *Lowerer) !void {
        var count: usize = 0;
        for (self.ir.graph.crates.items) |entry| count += entry.deps.len;
        if (count == 0) return;
        const table = try self.alloc.alloc(DependencyEntry, count);
        errdefer self.alloc.free(table);
        var index: usize = 0;
        for (self.ir.graph.crates.items) |entry| {
            for (entry.deps) |dependency| {
                // The graph owns both spellings; allocate only the cache rows.
                table[index] = .{
                    .local_alias = dependency.local_alias,
                    .extern_name = dependency.extern_name,
                    .disposition = dependencyDisposition(dependency),
                };
                index += 1;
            }
        }
        self.dependency_dispositions = table;
    }

    /// Compare Cargo root spellings without allocating a normalized string.
    fn dependencyDispositionOf(
        self: *const Lowerer,
        root: []const u8,
    ) ?DependencyDisposition {
        for (self.dependency_dispositions) |entry| {
            if (normalizedPackageNameEqual(entry.local_alias, root) or
                normalizedPackageNameEqual(entry.extern_name, root))
            {
                return entry.disposition;
            }
        }
        return null;
    }

    /// Runtime-bound roots emit no dependency module or alias.
    fn rootIsRuntimeBound(self: *const Lowerer, root: []const u8) bool {
        const disposition = self.dependencyDispositionOf(root) orelse return false;
        return disposition == .runtime_bound;
    }

    fn appendCrateDependencyImports(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
    ) !void {
        if (self.ir.graph.crates.items.len == 0) return;
        for (self.ir.graph.crates.items[0].deps) |dependency| {
            // The runtime binding leaves no dependency-rooted reference to import.
            if (self.rootIsRuntimeBound(dependency.local_alias)) continue;
            const module_name = try std.fmt.allocPrint(self.alloc, "r2z-{s}", .{dependency.extern_name});
            defer self.alloc.free(module_name);
            try self.appendImport(imports, dependency.local_alias, module_name, false);
        }
    }

    fn lowerZonDeps(self: *Lowerer) ![]const ast.ZonDep {
        if (self.ir.graph.crates.items.len == 0) return &.{};
        const dependencies = self.ir.graph.crates.items[0].deps;
        if (dependencies.len == 0) return &.{};
        var list: std.ArrayListUnmanaged(ast.ZonDep) = .empty;
        errdefer list.deinit(self.alloc);
        for (dependencies) |dependency| {
            // Skip proven runtime bindings before the mandatory source-path check.
            if (self.rootIsRuntimeBound(dependency.local_alias)) continue;
            const name = try std.fmt.allocPrint(self.alloc, "r2z-{s}", .{dependency.extern_name});
            errdefer self.alloc.free(name);
            const path = if (dependency.path) |value| try self.alloc.dupe(u8, value) else null;
            errdefer if (path) |value| self.alloc.free(value);
            if (path == null) return error.DependencySourceUnavailable;
            try list.append(self.alloc, .{ .name = name, .path = path });
        }
        return list.toOwnedSlice(self.alloc);
    }

    fn traitDescriptorNameTaken(
        self: *const Lowerer,
        owner_module_id: ir.spine.EntityId,
        name: []const u8,
    ) bool {
        if (self.moduleForEntity(owner_module_id)) |module| {
            for (module.items) |item_id| {
                if (self.ir.graph.symbol_table.get(item_id)) |entity| {
                    const entity_name = entity.renamed_to orelse entity.name;
                    if (std.mem.eql(u8, entity_name, name)) return true;
                }
            }
        }
        for (self.trait_descriptor_requests.items) |request| {
            if (request.owner_module_id == owner_module_id and
                std.mem.eql(u8, request.name, name))
            {
                return true;
            }
        }
        for (self.hash_walk_requests.items) |request| {
            if (request.owner_module_id == owner_module_id and
                (std.mem.eql(u8, request.value_name, name) or
                    std.mem.eql(u8, request.slice_name, name))) return true;
        }
        return false;
    }

    fn generatedTraitDescriptorName(
        self: *Lowerer,
        trait_id: ir.spine.EntityId,
        owner_module_id: ir.spine.EntityId,
    ) ![]const u8 {
        var candidate = try std.fmt.allocPrint(
            self.alloc,
            "__r2z_trait_descriptor_{d}",
            .{trait_id},
        );
        var suffix: usize = 1;
        errdefer self.alloc.free(candidate);
        while (self.traitDescriptorNameTaken(owner_module_id, candidate)) : (suffix += 1) {
            const next = try std.fmt.allocPrint(
                self.alloc,
                "__r2z_trait_descriptor_{d}_{d}",
                .{ trait_id, suffix },
            );
            self.alloc.free(candidate);
            candidate = next;
        }
        return candidate;
    }

    fn projectedDescriptorName(
        self: *Lowerer,
        owner_module_id: ir.spine.EntityId,
        name: []const u8,
    ) ![]const u8 {
        const current_module_id = self.current_module_id orelse owner_module_id;
        if (current_module_id == owner_module_id) {
            return self.alloc.dupe(u8, name);
        }
        const module_alias = try self.ensureModuleImport(owner_module_id);
        return std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ module_alias, name });
    }

    fn ensureTraitDescriptor(
        self: *Lowerer,
        trait_id: ir.spine.EntityId,
    ) ![]const u8 {
        const trait_entity = self.ir.graph.symbol_table.get(trait_id) orelse {
            return error.MissingDefinition;
        };
        if (trait_entity.kind != .trait_) return error.InvalidTypeDefinition;

        for (self.trait_descriptor_requests.items) |request| {
            if (request.trait_id == trait_id) {
                return self.projectedDescriptorName(request.owner_module_id, request.name);
            }
        }

        const owner_module_id = (try self.owningModuleEntity(trait_id)) orelse 0;
        const name = try self.generatedTraitDescriptorName(trait_id, owner_module_id);
        errdefer self.alloc.free(name);
        try self.trait_descriptor_requests.append(self.alloc, .{
            .trait_id = trait_id,
            .owner_module_id = owner_module_id,
            .name = name,
        });
        return self.projectedDescriptorName(owner_module_id, name);
    }

    fn generatedHashWalkName(
        self: *Lowerer,
        owner_module_id: ir.spine.EntityId,
        base: []const u8,
        reserved: ?[]const u8,
    ) ![]const u8 {
        var candidate = try self.alloc.dupe(u8, base);
        errdefer self.alloc.free(candidate);
        var suffix: usize = 1;
        while (self.traitDescriptorNameTaken(owner_module_id, candidate) or
            (reserved != null and std.mem.eql(u8, candidate, reserved.?))) : (suffix += 1)
        {
            const next = try std.fmt.allocPrint(self.alloc, "{s}_{d}", .{ base, suffix });
            self.alloc.free(candidate);
            candidate = next;
        }
        return candidate;
    }

    fn ensureHashWalk(self: *Lowerer) !struct {
        value: []const u8,
        slice: []const u8,
        is_allocating: bool,
        is_fallible: bool,
    } {
        const owner_module_id = self.current_module_id orelse 0;
        for (self.hash_walk_requests.items) |request| {
            if (request.owner_module_id == owner_module_id) return .{
                .value = try self.projectedDescriptorName(owner_module_id, request.value_name),
                .slice = try self.projectedDescriptorName(owner_module_id, request.slice_name),
                .is_allocating = request.is_allocating,
                .is_fallible = request.is_fallible,
            };
        }
        const value_name = try self.generatedHashWalkName(owner_module_id, "__r2z_hash_value", null);
        errdefer self.alloc.free(value_name);
        const slice_name = try self.generatedHashWalkName(owner_module_id, "__r2z_hash_slice", value_name);
        errdefer self.alloc.free(slice_name);
        const effects = try self.hashWalkSourceEffects();
        try self.hash_walk_requests.append(self.alloc, .{
            .owner_module_id = owner_module_id,
            .value_name = value_name,
            .slice_name = slice_name,
            .is_allocating = effects.is_allocating,
            .is_fallible = effects.is_fallible,
        });
        return .{
            .value = try self.projectedDescriptorName(owner_module_id, value_name),
            .slice = try self.projectedDescriptorName(owner_module_id, slice_name),
            .is_allocating = effects.is_allocating,
            .is_fallible = effects.is_fallible,
        };
    }

    fn canonicalHashSourceMethods(self: *Lowerer) ![]const CanonicalHashSourceMethod {
        if (self.hash_source_methods) |methods| return methods;
        var found: std.ArrayListUnmanaged(CanonicalHashSourceMethod) = .empty;
        errdefer found.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |method| {
            if (method.kind != .fn_) continue;
            const hash_method = std.mem.eql(u8, method.name, "hash") or
                std.mem.eql(u8, method.name, "hash_slice");
            const hasher_method = std.mem.eql(u8, method.name, "write") or
                std.mem.eql(u8, method.name, "write_str") or
                std.mem.eql(u8, method.name, "write_length_prefix") or
                hasherPrimitiveType(method.name) != null;
            if (!hash_method and !hasher_method) continue;
            const impl_id = method.parent orelse continue;
            if (impl_id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
                .impl_ => |body| body,
                else => continue,
            };
            if (!self.descriptorTypeIsConcrete(impl_body.self_ty)) continue;
            const trait_path = impl_body.trait_path orelse continue;
            const canonical = (hash_method and ir.bodies.boundPathMatches(
                &self.ir.graph,
                impl_id,
                trait_path,
                &.{ "core", "hash", "Hash" },
            )) or (hasher_method and ir.bodies.boundPathMatches(
                &self.ir.graph,
                impl_id,
                trait_path,
                &.{ "core", "hash", "Hasher" },
            ));
            if (!canonical) continue;
            try found.append(self.alloc, .{ .id = method.id, .name = method.name });
        }
        self.hash_source_methods = try found.toOwnedSlice(self.alloc);
        return self.hash_source_methods.?;
    }
    fn hashWalkSourceEffects(self: *Lowerer) !struct {
        is_allocating: bool = false,
        is_fallible: bool = false,
    } {
        var is_allocating = false;
        var is_fallible = false;
        for (try self.canonicalHashSourceMethods()) |source| {
            is_allocating = is_allocating or self.hoistedMethodTakesAllocator(source.id);
            is_fallible = is_fallible or self.callableFallible(source.id);
        }
        return .{ .is_allocating = is_allocating, .is_fallible = is_fallible };
    }

    fn traitPathMatches(
        path: ir.types.Path,
        trait_id: ir.spine.EntityId,
    ) bool {
        const terminal = lastPathSegment(path.segments) orelse return false;
        return terminal.id != null and terminal.id.? == trait_id;
    }

    fn descriptorTypeIsConcrete(self: *const Lowerer, ty: ir.types.Type) bool {
        return switch (ty) {
            .path => |path| {
                if (path.segments.len == 0) return false;
                for (path.segments) |segment| {
                    if (segment.id == null) return false;
                }
                return true;
            },
            .external_nominal => |external| {
                if (external.path.len == 0) return false;
                for (external.args) |arg| {
                    if (!self.descriptorTypeIsConcrete(arg)) return false;
                }
                return true;
            },
            .prim => true,
            .reference => |reference| self.descriptorTypeIsConcrete(reference.pointee),
            .raw_ptr => |raw_ptr| self.descriptorTypeIsConcrete(raw_ptr.pointee),
            .slice => |slice| self.descriptorTypeIsConcrete(slice.elem),
            .array => |array| self.descriptorTypeIsConcrete(array.elem),
            .tuple => |tuple| {
                for (tuple) |item| {
                    if (!self.descriptorTypeIsConcrete(item)) return false;
                }
                return true;
            },
            .fn_ptr => |function| {
                for (function.params) |param| {
                    if (!self.descriptorTypeIsConcrete(param)) return false;
                }
                return self.descriptorTypeIsConcrete(function.ret);
            },
            .generic_inst => |inst| {
                if (inst.decl == std.math.maxInt(ir.spine.EntityId)) return false;
                for (inst.args.params) |arg| {
                    if (!self.descriptorTypeIsConcrete(arg)) return false;
                }
                return true;
            },
            .option => |inner| self.descriptorTypeIsConcrete(inner.*),
            .result => |result| self.descriptorTypeIsConcrete(result.ok) and
                self.descriptorTypeIsConcrete(result.err),
            .boxed => |inner| self.descriptorTypeIsConcrete(inner.*),
            .@"opaque" => |opaque_type| if (opaque_type.concrete) |concrete|
                self.descriptorTypeIsConcrete(concrete.*)
            else
                false,
            .dyn_trait => |bounds| self.descriptorBoundsAreConcrete(bounds),
            .unsupported => false,
        };
    }

    fn descriptorBoundsAreConcrete(self: *const Lowerer, bounds: []const ir.types.Bound) bool {
        for (bounds) |bound| {
            for (bound.args) |arg| {
                if (!self.descriptorTypeIsConcrete(arg)) return false;
            }
            for (bound.associated_types) |binding| {
                if (!self.descriptorTypeIsConcrete(binding.ty)) return false;
            }
        }
        return true;
    }

    fn implAssociatedEntity(
        self: *const Lowerer,
        impl_body: ir.bodies.ImplBody,
        name: []const u8,
        kind: ir.spine.EntityKind,
    ) ?ir.spine.EntityId {
        for (impl_body.assoc_items) |assoc_id| {
            const entity = self.ir.graph.symbol_table.get(assoc_id) orelse continue;
            if (entity.kind == kind and std.mem.eql(u8, entity.name, name)) {
                return assoc_id;
            }
        }
        return null;
    }

    fn traitHasAssociatedMember(
        self: *const Lowerer,
        trait_id: ir.spine.EntityId,
        name: []const u8,
    ) bool {
        if (trait_id >= self.ir.bodies.bodies.len) return false;
        const trait_body = switch (self.ir.bodies.bodies[trait_id]) {
            .trait_ => |body| body,
            else => return false,
        };
        for (trait_body.assoc_types) |assoc| {
            if (std.mem.eql(u8, assoc.name, name)) return true;
        }
        for (trait_body.assoc_consts) |assoc| {
            if (std.mem.eql(u8, assoc.name, name)) return true;
        }
        return false;
    }

    fn lowerTraitDescriptor(
        self: *Lowerer,
        request: TraitDescriptorRequest,
    ) !ast.Decl {
        if (request.trait_id >= self.ir.bodies.bodies.len) {
            return error.MissingBodyId;
        }
        const trait_body = switch (self.ir.bodies.bodies[request.trait_id]) {
            .trait_ => |body| body,
            else => return error.DeclarationBodyMismatch,
        };
        if (trait_body.assoc_types.len == 0 and trait_body.assoc_consts.len == 0) {
            return error.UnsupportedAssociatedTypeProjection;
        }

        var cases_list: std.ArrayListUnmanaged(ast.TraitDescriptorCase) = .empty;
        var receiver_types: std.ArrayListUnmanaged(ir.types.Type) = .empty;
        errdefer {
            cases_list.deinit(self.alloc);
            receiver_types.deinit(self.alloc);
        }

        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            if (!traitPathMatches(trait_path, request.trait_id)) continue;
            if (impl_body.generics != null or
                !self.descriptorTypeIsConcrete(impl_body.self_ty))
            {
                return error.UnsupportedGenericTraitImpl;
            }

            for (receiver_types.items) |receiver_type| {
                if (typeEquals(receiver_type, impl_body.self_ty)) {
                    return error.AmbiguousTraitImplMatch;
                }
            }
            try receiver_types.append(self.alloc, impl_body.self_ty);

            const receiver = try self.lowerType(impl_body.self_ty);
            var members_list: std.ArrayListUnmanaged(ast.TraitDescriptorMember) = .empty;
            errdefer members_list.deinit(self.alloc);

            for (trait_body.assoc_types) |assoc| {
                const assoc_id = self.implAssociatedEntity(
                    impl_body,
                    assoc.name,
                    .type_alias,
                );
                const target_ir = if (assoc_id) |id| blk: {
                    if (id >= self.ir.bodies.bodies.len) return error.MissingBodyId;
                    const alias = switch (self.ir.bodies.bodies[id]) {
                        .type_alias => |body| body,
                        else => return error.DeclarationBodyMismatch,
                    };
                    if (!self.descriptorTypeIsConcrete(alias.target)) {
                        return error.UnsupportedGenericTraitAlias;
                    }
                    break :blk alias.target;
                } else blk: {
                    const default_ty = assoc.default orelse {
                        return error.MissingAssociatedItem;
                    };
                    if (!self.descriptorTypeIsConcrete(default_ty)) {
                        return error.UnsupportedGenericTraitAlias;
                    }
                    break :blk default_ty;
                };
                const name = try self.alloc.dupe(u8, assoc.name);
                errdefer self.alloc.free(name);
                const ty = try self.lowerType(target_ir);
                try members_list.append(self.alloc, .{ .type_ = .{
                    .name = name,
                    .ty = ty,
                } });
            }

            for (trait_body.assoc_consts) |assoc| {
                const assoc_id = self.implAssociatedEntity(
                    impl_body,
                    assoc.name,
                    .const_,
                );
                const value = if (assoc_id) |id| blk: {
                    if (id >= self.ir.bodies.bodies.len) return error.MissingBodyId;
                    const body = switch (self.ir.bodies.bodies[id]) {
                        .const_ => |const_body| const_body,
                        else => return error.DeclarationBodyMismatch,
                    };
                    break :blk try self.lowerExpr(body.init);
                } else blk: {
                    const default_id = assoc.default orelse {
                        return error.MissingAssociatedItem;
                    };
                    break :blk try self.lowerExpr(default_id);
                };
                try members_list.append(self.alloc, .{ .const_ = .{
                    .name = try self.alloc.dupe(u8, assoc.name),
                    .value = value,
                } });
            }

            if (members_list.items.len == 0) return error.MissingAssociatedItem;
            try cases_list.append(self.alloc, .{
                .receiver = receiver,
                .members = try members_list.toOwnedSlice(self.alloc),
            });
        }

        if (cases_list.items.len == 0) return error.UnsupportedAssociatedTypeProjection;
        receiver_types.deinit(self.alloc);
        return .{ .trait_descriptor = .{
            .name = request.name,
            .is_pub = true,
            .cases = try cases_list.toOwnedSlice(self.alloc),
        } };
    }

    fn moduleFileIndex(
        self: *const Lowerer,
        files: []const ast.File,
        module_id: ir.spine.EntityId,
    ) ?usize {
        if (self.ir.graph.modules.items.len == 0) {
            return if (module_id == 0 and files.len == 1) 0 else null;
        }
        var file_index: usize = 0;
        for (self.ir.graph.modules.items) |module| {
            if (module.is_extern) continue;
            const entity_id = self.moduleEntityId(module) orelse module.id;
            if (entity_id == module_id and file_index < files.len) return file_index;
            file_index += 1;
        }
        return null;
    }

    fn appendTraitDescriptorDecl(
        self: *Lowerer,
        file: *ast.File,
        decl: ast.Decl,
    ) !void {
        const old_decls = file.decls;
        const merged = try self.alloc.alloc(ast.Decl, old_decls.len + 1);
        merged[0] = decl;
        @memcpy(merged[1..], old_decls);
        if (old_decls.len > 0) self.alloc.free(old_decls);
        file.decls = merged;
    }

    fn refreshFileImports(
        self: *Lowerer,
        file: *ast.File,
        module_id: ir.spine.EntityId,
    ) !void {
        var imports: std.ArrayListUnmanaged(ast.Import) = .empty;
        errdefer imports.deinit(self.alloc);
        try imports.appendSlice(self.alloc, file.imports);
        const previous_module_id = self.current_module_id;
        const previous_imports = self.current_imports;
        self.current_module_id = module_id;
        self.current_imports = &imports;
        defer {
            self.current_module_id = previous_module_id;
            self.current_imports = previous_imports;
        }
        try self.appendRuntimeImport(&imports, module_id);
        try self.appendStdImportIfNeeded(&imports, file.decls, file.tests);
        const owned_imports = try imports.toOwnedSlice(self.alloc);
        if (file.imports.len > 0) self.alloc.free(file.imports);
        file.imports = owned_imports;
    }

    fn materializeTraitDescriptors(
        self: *Lowerer,
        files: *std.ArrayListUnmanaged(ast.File),
    ) !void {
        var request_index: usize = 0;
        while (request_index < self.trait_descriptor_requests.items.len) : (request_index += 1) {
            const request = self.trait_descriptor_requests.items[request_index];
            const file_index = self.moduleFileIndex(files.items, request.owner_module_id) orelse {
                return error.MissingModule;
            };
            var imports: std.ArrayListUnmanaged(ast.Import) = .empty;
            errdefer imports.deinit(self.alloc);
            try imports.appendSlice(self.alloc, files.items[file_index].imports);
            const previous_module_id = self.current_module_id;
            const previous_imports = self.current_imports;
            self.current_module_id = request.owner_module_id;
            self.current_imports = &imports;
            const descriptor = self.lowerTraitDescriptor(request) catch |err| {
                self.current_module_id = previous_module_id;
                self.current_imports = previous_imports;
                return err;
            };
            self.current_module_id = previous_module_id;
            self.current_imports = previous_imports;
            const owned_imports = try imports.toOwnedSlice(self.alloc);
            if (files.items[file_index].imports.len > 0) {
                self.alloc.free(files.items[file_index].imports);
            }
            files.items[file_index].imports = owned_imports;
            try self.appendTraitDescriptorDecl(&files.items[file_index], descriptor);
        }

        var file_index: usize = 0;
        for (self.ir.graph.modules.items) |module| {
            if (module.is_extern) continue;
            if (file_index >= files.items.len) break;
            const module_id = self.moduleEntityId(module) orelse module.id;
            try self.refreshFileImports(&files.items[file_index], module_id);
            file_index += 1;
        }
        if (self.ir.graph.modules.items.len == 0 and files.items.len == 1) {
            try self.refreshFileImports(&files.items[0], 0);
        }
    }

    fn materializeHashWalks(
        self: *Lowerer,
        files: *std.ArrayListUnmanaged(ast.File),
    ) !void {
        for (self.hash_walk_requests.items) |request| {
            const file_index = self.moduleFileIndex(files.items, request.owner_module_id) orelse
                return error.MissingModule;
            var imports: std.ArrayListUnmanaged(ast.Import) = .empty;
            errdefer imports.deinit(self.alloc);
            try imports.appendSlice(self.alloc, files.items[file_index].imports);
            const previous_module_id = self.current_module_id;
            const previous_imports = self.current_imports;
            self.current_module_id = request.owner_module_id;
            self.current_imports = &imports;
            const declarations = blk: {
                defer {
                    self.current_module_id = previous_module_id;
                    self.current_imports = previous_imports;
                }
                break :blk .{
                    try self.lowerHashSliceDecl(request),
                    try self.lowerHashValueDecl(request),
                };
            };
            const owned_imports = try imports.toOwnedSlice(self.alloc);
            if (files.items[file_index].imports.len > 0)
                self.alloc.free(files.items[file_index].imports);
            files.items[file_index].imports = owned_imports;
            inline for (declarations) |declaration|
                try self.appendTraitDescriptorDecl(&files.items[file_index], declaration);
        }
        var file_index: usize = 0;
        for (self.ir.graph.modules.items) |module| {
            if (module.is_extern) continue;
            if (file_index >= files.items.len) break;
            const module_id = self.moduleEntityId(module) orelse module.id;
            try self.refreshFileImports(&files.items[file_index], module_id);
            file_index += 1;
        }
        if (self.ir.graph.modules.items.len == 0 and files.items.len == 1)
            try self.refreshFileImports(&files.items[0], 0);
    }

    /// Zig collects `test` blocks only from files it analyzes, and a
    /// container-level `@import` is analyzed only when something references
    /// it. A translated test module that nothing uses therefore compiles away,
    /// and `zig build test` reports success over zero assertions. Emit one
    /// synthetic test per file import that reaches a test block, so the whole
    /// test graph is analyzed from the package root.
    fn appendTestReachabilityRefs(self: *Lowerer, files: *std.ArrayListUnmanaged(ast.File)) !void {
        if (files.items.len < 2) return;

        var path_index: std.StringHashMapUnmanaged(usize) = .empty;
        defer path_index.deinit(self.alloc);
        for (files.items, 0..) |file, index| {
            try path_index.put(self.alloc, file.path, index);
        }

        // One list of relative imports per file, collected before anything is
        // derived from it so the edge graph and the emitted references cannot
        // disagree about what a file imports.
        var module_refs = try self.alloc.alloc([]ReachableModuleRef, files.items.len);
        defer {
            for (module_refs) |refs| self.alloc.free(refs);
            self.alloc.free(module_refs);
        }
        for (files.items, 0..) |file, index| {
            var refs: std.ArrayListUnmanaged(ReachableModuleRef) = .empty;
            defer refs.deinit(self.alloc);
            try self.appendReachableModuleRefs(file, &refs);
            module_refs[index] = try refs.toOwnedSlice(self.alloc);
        }

        // Resolve each file's relative imports to package file indices.
        var edges = try self.alloc.alloc([]usize, files.items.len);
        defer {
            for (edges) |edge| self.alloc.free(edge);
            self.alloc.free(edges);
        }
        for (files.items, 0..) |file, index| {
            var targets: std.ArrayListUnmanaged(usize) = .empty;
            defer targets.deinit(self.alloc);
            for (module_refs[index]) |ref| {
                if (!std.mem.endsWith(u8, ref.module_or_path, ".zig")) continue;
                const dir = std.fs.path.dirname(file.path) orelse continue;
                const resolved = try std.fs.path.resolve(
                    self.alloc,
                    &.{ dir, ref.module_or_path },
                );
                defer self.alloc.free(resolved);
                const target = path_index.get(resolved) orelse continue;
                var duplicate = false;
                for (targets.items) |existing| {
                    if (existing == target) {
                        duplicate = true;
                        break;
                    }
                }
                if (!duplicate) try targets.append(self.alloc, target);
            }
            edges[index] = try targets.toOwnedSlice(self.alloc);
        }

        // reaches[i] is true when file i transitively holds a test block.
        var reaches = try self.alloc.alloc(bool, files.items.len);
        defer self.alloc.free(reaches);
        @memset(reaches, false);
        var changed = true;
        while (changed) {
            changed = false;
            for (files.items, 0..) |file, index| {
                if (reaches[index]) continue;
                if (file.tests.len > 0) {
                    reaches[index] = true;
                    changed = true;
                    continue;
                }
                for (edges[index]) |target| {
                    if (!reaches[target]) continue;
                    reaches[index] = true;
                    changed = true;
                    break;
                }
            }
        }

        for (files.items, 0..) |*file, index| {
            var refs: std.ArrayListUnmanaged(ast.TestDecl) = .empty;
            defer refs.deinit(self.alloc);
            var seen: std.AutoHashMapUnmanaged(usize, void) = .empty;
            defer seen.deinit(self.alloc);
            for (module_refs[index]) |ref| {
                if (!std.mem.endsWith(u8, ref.module_or_path, ".zig")) continue;
                const dir = std.fs.path.dirname(file.path) orelse continue;
                const resolved = try std.fs.path.resolve(
                    self.alloc,
                    &.{ dir, ref.module_or_path },
                );
                defer self.alloc.free(resolved);
                const target = path_index.get(resolved) orelse continue;
                if (!reaches[target]) continue;
                // A file may import the same target more than once; one
                // reference is enough to make Zig analyze it.
                const entry = try seen.getOrPut(self.alloc, target);
                if (entry.found_existing) continue;

                const name = try std.fmt.allocPrint(
                    self.alloc,
                    "translated tests reachable through {s}",
                    .{ref.module_or_path},
                );
                const operand = try self.alloc.create(ast.Expr);
                operand.* = .{ .ident = ref.local_name };
                const discard = try self.alloc.create(ast.Expr);
                discard.* = .{ .ident = "_" };
                const stmts = try self.alloc.alloc(ast.Stmt, 1);
                stmts[0] = .{ .assign = .{
                    .target = discard.*,
                    .val = operand.*,
                } };
                try refs.append(self.alloc, .{
                    .name = name,
                    .body = .{ .stmts = stmts },
                });
            }
            if (refs.items.len == 0) continue;

            // A file with test decls is validated as needing `std`, and the
            // synthetic reachability test itself uses none. Supply the import
            // so the file keeps passing that check.
            var imports = file.imports;
            var needs_std = true;
            for (imports) |import| {
                if (std.mem.eql(u8, import.local_name, "std")) {
                    needs_std = false;
                    break;
                }
            }
            if (needs_std) {
                const with_std = try self.alloc.alloc(ast.Import, imports.len + 1);
                with_std[0] = .{ .local_name = "std", .module_or_path = "std" };
                @memcpy(with_std[1..], imports);
                imports = with_std;
                file.imports = imports;
            }

            const combined = try self.alloc.alloc(
                ast.TestDecl,
                file.tests.len + refs.items.len,
            );
            @memcpy(combined[0..file.tests.len], file.tests);
            @memcpy(combined[file.tests.len..], refs.items);
            file.tests = combined;
        }
    }

    /// Collect every relative `@import` a generated file names, whether it
    /// ended up in the import list or as a promoted re-export decl.
    ///
    /// `promotePublicModuleImportsToReExports` runs while the file is being
    /// lowered, which is before `appendTestReachabilityRefs`, and it moves
    /// every `pub mod` out of `file.imports` and into a `pub const name =
    /// @import("./name.zig")` decl. Reading the import list alone therefore
    /// loses exactly the public submodules, and with them the one reference
    /// that made Zig analyze those files: a top-level `const` is not analyzed
    /// until something uses it, so a submodule that no other file names would
    /// compile away and take its tests with it.
    fn appendReachableModuleRefs(
        self: *Lowerer,
        file: ast.File,
        out: *std.ArrayListUnmanaged(ReachableModuleRef),
    ) !void {
        for (file.imports) |import| {
            try out.append(self.alloc, .{
                .local_name = import.local_name,
                .module_or_path = import.module_or_path,
            });
        }
        for (file.decls) |decl| {
            const binding = switch (decl) {
                .const_decl => |value| value,
                else => continue,
            };
            const call = switch (binding.init) {
                .builtin => |value| value,
                else => continue,
            };
            if (!std.mem.eql(u8, call.name, "import")) continue;
            if (call.args.len != 1) continue;
            const path = switch (call.args[0]) {
                .lit => |lit| switch (lit) {
                    .str => |value| value,
                    else => continue,
                },
                else => continue,
            };
            try out.append(self.alloc, .{
                .local_name = binding.name,
                .module_or_path = path,
            });
        }
    }

    pub fn lowerPackage(self: *Lowerer) !ast.Package {
        defer self.local_static_names.deinit(self.alloc);
        // Before anything reads it: the import, alias-reservation and
        // root-classifier consumers all run while the files are still being
        // built, so this is the last point at which the answer is decidable.
        defer self.alloc.free(self.dependency_dispositions);
        try self.classifyCrateDependencies();
        try self.prepareLocalStaticNames();
        defer self.trait_descriptor_requests.deinit(self.alloc);
        defer self.hash_walk_requests.deinit(self.alloc);
        defer self.local_closures.deinit(self.alloc);
        defer self.deinitLocalClosureSnapshots();
        defer self.active_closure_capture_overrides.deinit(self.alloc);
        defer self.owned_scope_bindings.deinit(self.alloc);
        defer self.owner_prelude_stmts.deinit(self.alloc);
        defer self.runtime_import_modules.deinit(self.alloc);
        defer self.pending_module_imports.deinit(self.alloc);
        defer if (self.scope_drop_walker) |*walker| walker.deinit();
        defer if (self.hash_dispatches) |owned| self.alloc.free(owned);
        defer if (self.hash_source_methods) |owned| self.alloc.free(owned);
        try self.computeAllocationEffects();
        defer if (self.allocation_effects) |effects| self.alloc.free(effects);
        defer if (self.fallibility_effects) |effects| self.alloc.free(effects);
        defer if (self.comparison_temporaries) |owned| self.alloc.free(owned);
        defer if (self.owner_cleanups) |owned| self.alloc.free(owned);
        defer if (self.pattern_cleanups) |owned| self.alloc.free(owned);
        try self.collectCrossModuleRefs();
        try self.collectHoistedMethods();
        // Hoisting decides which method names land on each struct, so the
        // field/method collision pass has to read the finished lists.
        try self.prepareStructFieldNames();

        var files_list: std.ArrayListUnmanaged(ast.File) = .empty;

        if (self.ir.graph.modules.items.len == 0) {
            // No explicit module graph: synthesize a root file from all entities
            const root_file = try self.lowerRootFileFromSymbolTable();
            try files_list.append(self.alloc, root_file);
        } else {
            // Lower each module into a corresponding file
            for (self.ir.graph.modules.items) |mod| {
                if (mod.is_extern) continue;
                const file = try self.lowerModule(mod);
                try files_list.append(self.alloc, file);
            }
        }

        try self.materializeTraitDescriptors(&files_list);
        try self.materializeHashWalks(&files_list);
        try self.appendTestReachabilityRefs(&files_list);
        const pkg_name = try self.alloc.dupe(u8, self.ir.crate_name);
        errdefer self.alloc.free(pkg_name);
        const files = try files_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(files);
        const zon_deps = try self.lowerZonDeps();

        return .{
            .name = pkg_name,
            .version = "0.0.0",
            .fingerprint = null,
            .files = files,
            .zon_deps = zon_deps,
        };
    }

    fn collectHoistedMethods(self: *Lowerer) !void {
        // Native formatting hooks must keep their protocol names even when
        // an inherent Rust method happens to use the same Zig spelling.
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            const name = self.formattingMethodName(entity) orelse continue;
            const parent = self.ir.graph.symbol_table.get(entity.parent.?) orelse
                return error.MissingParentId;
            const target = hoistTargetFor(parent) orelse continue;
            _ = try self.claimHoistedName(target, name, parent);
        }
        try self.claimStructRenderedMethodNames();

        // Settle every name before lowering any body. A forward call must use
        // the same collision-resolved identity as a call to an earlier method.
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .fn_ or entity.parent == null) continue;
            const parent = self.ir.graph.symbol_table.get(entity.parent.?) orelse
                return error.MissingParentId;
            if (parent.kind == .impl_ and parent.parent == null) return error.MissingParentId;
            const target = hoistTargetFor(parent) orelse continue;
            _ = self.ir.graph.symbol_table.get(target) orelse return error.MissingDefinition;
            try self.validateMethodTopology(entity);
            if (self.hoisted_method_names.contains(entity.id)) continue;
            const source_name = self.formattingMethodName(entity) orelse entity.name;
            const emitted_name = try self.hoistedMethodName(target, parent, source_name);
            try self.hoisted_method_names.put(self.alloc, entity.id, emitted_name);
        }

        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .fn_ or entity.parent == null) continue;
            const parent = self.ir.graph.symbol_table.get(entity.parent.?) orelse
                return error.MissingParentId;
            const target = hoistTargetFor(parent) orelse continue;
            if (self.structBodyRendersMethod(target, entity.id, entity.name)) continue;
            const emitted_name = self.hoisted_method_names.get(entity.id) orelse
                return error.MissingDefinitionName;
            if (self.isHoistedMethodRegistered(target, emitted_name)) continue;
            const previous_generics = self.hoisted_impl_generic_params;
            self.hoisted_impl_generic_params = self.moduleHoistGenericParams(parent, target);
            defer self.hoisted_impl_generic_params = previous_generics;
            var function = try self.lowerFnEntity(entity.id, entity);
            function.name = emitted_name;
            var methods = self.hoisted_by_id.get(target) orelse
                std.ArrayListUnmanaged(ast.Decl).empty;
            try methods.append(self.alloc, .{ .fn_decl = function });
            try self.hoisted_by_id.put(self.alloc, target, methods);
        }
    }

    fn formattingMethodName(self: *const Lowerer, entity: ir.spine.Entity) ?[]const u8 {
        if (entity.kind != .fn_ or !std.mem.eql(u8, entity.name, "fmt")) return null;
        const parent_id = entity.parent orelse return null;
        const parent = self.ir.graph.symbol_table.get(parent_id) orelse return null;
        const implementation = implBodyFor(self.ir.bodies.bodies, parent) orelse return null;
        const trait_path = implementation.trait_path orelse return null;
        const segment = lastPathSegment(trait_path.segments) orelse return null;
        // A crate-local trait named Display is not the standard protocol.
        if (segment.id) |id| {
            const declaration = self.ir.graph.symbol_table.get(id) orelse return null;
            if (declaration.kind == .trait_) return null;
        }
        if (std.mem.eql(u8, segment.name, "Display")) return "format";
        if (std.mem.eql(u8, segment.name, "Debug")) return "formatDebug";
        return null;
    }

    /// Claim the source name of every method a struct body renders, before any
    /// impl method is hoisted.
    ///
    /// `collectHoistedMethods` visits entities in symbol-table order, and the
    /// declaration a struct renders is the one its entry RECORDS — which is
    /// whichever impl block had its body extracted last, not the first to
    /// declare the name. Claiming on the visit instead would let an earlier
    /// impl block take the plain source name for itself, and the struct's own
    /// method would then be emitted beside a hoisted one under the same name.
    /// Claiming up front means every impl method that is not the recorded owner
    /// already sees the name as taken and takes a name of its own.
    fn claimStructRenderedMethodNames(self: *Lowerer) !void {
        const entity_count = self.ir.graph.symbol_table.count();
        for (0..self.ir.bodies.bodies.len) |index| {
            if (index >= entity_count) break;
            const target_id: ir.spine.EntityId = @intCast(index);
            const struct_body = switch (self.ir.bodies.bodies[target_id]) {
                .struct_ => |sb| sb,
                else => continue,
            };
            for (struct_body.methods) |method| {
                const owner = self.recordedMethodOwner(target_id, method.name, method.body) orelse
                    continue;
                const owner_entity = self.ir.graph.symbol_table.get(owner) orelse continue;
                const impl_id = owner_entity.parent orelse continue;
                const impl_entity = self.ir.graph.symbol_table.get(impl_id) orelse continue;
                const source_name = self.formattingMethodName(owner_entity) orelse method.name;
                const emitted_name = try self.hoistedMethodName(target_id, impl_entity, source_name);
                try self.hoisted_method_names.put(self.alloc, owner, emitted_name);
            }
        }
    }

    /// Errors the cross-module scan can raise: allocation, plus the two IR
    /// lookups `owningModuleEntity` performs. Spelled out because the walker
    /// is mutually recursive, and two inferred error sets that call each other
    /// are a dependency loop the compiler cannot resolve.
    const CrossModuleScanError = error{
        OutOfMemory,
        ModuleHierarchyCycle,
        MissingEntityId,
    };
    /// Record every entity a module names that belongs to a DIFFERENT module.
    ///
    /// Rust visibility is a property of the module tree, not of the file: a
    /// `private` item is reachable from its module and every descendant. The
    /// emitter gives each `mod` its own file, and a Zig file is a hard module
    /// boundary, so a `mod test` calling a private `fn generate_iter` in the
    /// crate root is legal Rust and an illegal `root.generate_iter(5)` unless
    /// that declaration is `pub`.
    ///
    /// The scan runs over the whole expression table once, keyed by the module
    /// that owns each node, and it must run before ANY declaration is lowered:
    /// the reference is only seen while the referring module is lowered, and
    /// the crate root — which owns the item — is lowered first.
    fn collectCrossModuleRefs(self: *Lowerer) CrossModuleScanError!void {
        const visited = try self.alloc.alloc(bool, self.ir.bodies.exprs.len);
        defer self.alloc.free(visited);
        @memset(visited, false);
        const count = self.ir.graph.symbol_table.count();
        for (0..count) |idx| {
            const entity_id: ir.spine.EntityId = @intCast(idx);
            if (entity_id >= self.ir.bodies.bodies.len) continue;
            const owner = (try self.owningModuleEntity(entity_id)) orelse continue;
            switch (self.ir.bodies.bodies[entity_id]) {
                .fn_ => |fn_body| try self.recordCrossModuleRefs(fn_body.body, owner, visited),
                .const_ => |const_body| try self.recordCrossModuleRefs(const_body.init, owner, visited),
                else => {},
            }
        }
    }

    fn isCrossModuleRef(self: *const Lowerer, entity_id: ir.spine.EntityId) bool {
        return self.cross_module_refs.contains(entity_id);
    }

    /// Whether a Rust-`private` module-scope item has to be `pub` in Zig.
    ///
    /// Rust's `private` means "this module and its descendants", and every
    /// Rust `mod` becomes its own Zig file, so a descendant cannot see a
    /// non-`pub` declaration. Outside the crate root the emitter already
    /// publishes everything, since a child file may reach for any of it. At
    /// the root that is only true of an item another module actually names,
    /// which `cross_module_refs` records: `mod test` calling a private
    /// `generate_iter` makes it `pub`, while a private helper nothing else
    /// mentions stays private and does not widen the generated package's API.
    fn privateItemIsPublished(self: *const Lowerer, entity_id: ir.spine.EntityId) bool {
        return !self.current_file_is_root or self.isCrossModuleRef(entity_id);
    }

    /// Note `def` when it names something in another module, then walk the
    /// node's children. A statement node is a node in a different table, so it
    /// is followed here too rather than at the call site.
    fn recordCrossModuleRefs(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        owner: ir.spine.EntityId,
        visited: []bool,
    ) CrossModuleScanError!void {
        if (node >= self.ir.bodies.exprs.len) return;
        if (visited[node]) return;
        visited[node] = true;
        try self.noteCrossModuleRef(node, owner);
        switch (self.ir.bodies.exprs[node].kind) {
            .array => |array| try self.recordRefList(array.elements, owner, visited),
            .vec_lit => |vec| {
                try self.recordRefList(vec.elements, owner, visited);
                if (vec.repeat) |count| {
                    if (count == .expression) try self.recordCrossModuleRefs(count.expression, owner, visited);
                }
            },
            .range => |range| {
                try self.recordCrossModuleRefs(range.start, owner, visited);
                if (range.end) |end| try self.recordCrossModuleRefs(end, owner, visited);
            },
            .block => |block| try self.recordBlockRefs(block, owner, visited),
            .if_else => |if_else| {
                try self.recordCrossModuleRefs(if_else.cond, owner, visited);
                try self.recordBlockRefs(if_else.then_, owner, visited);
                switch (if_else.@"else") {
                    .none, .block => {},
                    .chain => |chain| try self.recordCrossModuleRefs(chain, owner, visited),
                }
            },
            .if_let => |if_let| {
                try self.recordCrossModuleRefs(if_let.scrutinee, owner, visited);
                try self.recordBlockRefs(if_let.then_, owner, visited);
                switch (if_let.@"else") {
                    .none, .block => {},
                    .chain => |chain| try self.recordCrossModuleRefs(chain, owner, visited),
                }
            },
            .match => |match| {
                try self.recordCrossModuleRefs(match.scrutinee, owner, visited);
                for (match.arms) |arm| {
                    if (arm.guard) |guard| try self.recordCrossModuleRefs(guard, owner, visited);
                    try self.recordCrossModuleRefs(arm.body, owner, visited);
                }
            },
            .loop_ => |loop_expr| try self.recordBlockRefs(loop_expr.body, owner, visited),
            .while_ => |while_expr| {
                try self.recordCrossModuleRefs(while_expr.cond, owner, visited);
                try self.recordBlockRefs(while_expr.body, owner, visited);
            },
            .for_ => |for_expr| {
                try self.recordCrossModuleRefs(for_expr.iterable, owner, visited);
                try self.recordBlockRefs(for_expr.body, owner, visited);
            },
            .break_ => |break_expr| {
                if (break_expr.value) |value| try self.recordCrossModuleRefs(value, owner, visited);
            },
            .call => |call| try self.recordRefList(call.args, owner, visited),
            .core_call => |call| try self.recordRefList(call.args, owner, visited),
            .method_call => |method| {
                try self.recordCrossModuleRefs(method.receiver, owner, visited);
                try self.recordRefList(method.args, owner, visited);
            },
            .struct_lit => |literal| {
                for (literal.fields) |field| {
                    try self.recordCrossModuleRefs(field.value, owner, visited);
                }
                if (literal.base) |base| try self.recordCrossModuleRefs(base, owner, visited);
            },
            .enum_variant => |variant| {
                try self.recordRefList(variant.tuple_fields, owner, visited);
                for (variant.named_fields) |field| {
                    try self.recordCrossModuleRefs(field.value, owner, visited);
                }
            },
            .format_write => |format| {
                try self.recordCrossModuleRefs(format.writer, owner, visited);
                try self.recordRefList(format.args, owner, visited);
            },
            .field => |field| try self.recordCrossModuleRefs(field.base, owner, visited),
            .index => |index| {
                try self.recordCrossModuleRefs(index.base, owner, visited);
                try self.recordCrossModuleRefs(index.index, owner, visited);
            },
            .cast => |cast| try self.recordCrossModuleRefs(cast.operand, owner, visited),
            .binary => |binary| {
                try self.recordCrossModuleRefs(binary.lhs, owner, visited);
                try self.recordCrossModuleRefs(binary.rhs, owner, visited);
            },
            .unary => |unary| try self.recordCrossModuleRefs(unary.operand, owner, visited),
            .assign => |assign| {
                try self.recordCrossModuleRefs(assign.target, owner, visited);
                try self.recordCrossModuleRefs(assign.value, owner, visited);
            },
            .try_ => |try_expr| try self.recordCrossModuleRefs(try_expr.inner, owner, visited),
            .return_ => |return_expr| {
                if (return_expr.value) |value| try self.recordCrossModuleRefs(value, owner, visited);
            },
            .closure => |closure| try self.recordBlockRefs(closure.body, owner, visited),
            .iterator_chain => |chain| {
                try self.recordCrossModuleRefs(chain.source, owner, visited);
                for (chain.adapters) |adapter| switch (adapter) {
                    .map => |map| try self.recordBlockRefs(map.closure.body, owner, visited),
                    .filter => |filter| try self.recordBlockRefs(filter.closure.body, owner, visited),
                    .flat_map => |flat| try self.recordBlockRefs(flat.body, owner, visited),
                    .zip => |zip| try self.recordCrossModuleRefs(zip.other, owner, visited),
                    .enumerate, .range_rev, .other => {},
                };
            },
            // An assertion marker stands for a real condition elsewhere in
            // the graph: `assert_eq!` expands to one node that names its
            // condition as `assertion:<id>`. Treating it as a leaf hid every
            // name the condition reaches — a `mod test` asserting on a
            // private crate-root helper left that helper private, and the
            // generated package then refused the call from the child file.
            .unsupported => |unsupported| {
                if (allocationAssertionCondition(
                    unsupported.reason,
                    node,
                    self.ir.bodies.exprs.len,
                )) |condition| {
                    try self.recordCrossModuleRefs(condition, owner, visited);
                }
            },
            // A `continue` names no value and a panic carries only text.
            .path,
            .literal,
            .unit,
            .core_function,
            .external_variant,
            .continue_,
            .panic_,
            => {},
        }
    }

    fn recordRefList(
        self: *Lowerer,
        nodes: []const ir.exprs.NodeId,
        owner: ir.spine.EntityId,
        visited: []bool,
    ) CrossModuleScanError!void {
        for (nodes) |node| try self.recordCrossModuleRefs(node, owner, visited);
    }

    fn recordBlockRefs(
        self: *Lowerer,
        block: ir.exprs.BlockExpr,
        owner: ir.spine.EntityId,
        visited: []bool,
    ) CrossModuleScanError!void {
        for (block.statements) |statement| {
            if (statement >= self.ir.bodies.stmts.len) continue;
            switch (self.ir.bodies.stmts[statement].kind) {
                .expr => |expr| try self.recordCrossModuleRefs(expr, owner, visited),
                .let => |let_stmt| {
                    if (let_stmt.init) |initialiser| {
                        try self.recordCrossModuleRefs(initialiser, owner, visited);
                    }
                },
                .let_else => |let_else| {
                    try self.recordCrossModuleRefs(let_else.init, owner, visited);
                    try self.recordBlockRefs(let_else.else_block, owner, visited);
                },
                .item => {},
            }
        }
        if (block.tail) |tail| try self.recordCrossModuleRefs(tail, owner, visited);
    }

    /// Record the entity a node names when it does not belong to `owner`. A
    /// `use` alias resolves to its target first, so a re-export names the
    /// declaration rather than the import that introduced it.
    fn noteCrossModuleRef(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        owner: ir.spine.EntityId,
    ) CrossModuleScanError!void {
        var target: ?ir.spine.EntityId = null;
        switch (self.ir.bodies.exprs[node].kind) {
            .path => |path| target = path.def,
            .field => |field| target = field.resolved,
            .struct_lit => |literal| target = literal.def,
            .enum_variant => |variant| target = variant.def,
            .call => |call| target = switch (call.call_kind) {
                .free => |def| def,
                .associated => |def| def,
                .constructor => |def| def,
            },
            .method_call => |method| target = method.method,
            else => {},
        }
        const def = target orelse return;
        const entity = self.ir.graph.symbol_table.get(def) orelse return;
        const resolved = entity.resolved orelse def;
        const declared_in = (try self.owningModuleEntity(resolved)) orelse return;
        if (declared_in == owner) return;
        try self.cross_module_refs.put(self.alloc, resolved, {});
    }

    /// The name a method called `name` is emitted under on `target`.
    ///
    /// The first impl block to claim a name on a target keeps it. A later
    /// block that declares the SAME function — the same self type and the same
    /// trait instantiation — resolves to the same name, which is what
    /// collapses the redeclaration. A later block that declares the same
    /// method name for a different reason is a different function and gets a
    /// name of its own, because the target holds one Zig namespace: `impl
    /// FromHex for [u8; 6]` and `impl FromHex for [u8; 5]` declare the same
    /// Rust method name and two different return types, and each call site
    /// must reach its own.
    ///
    /// Two blocks that share a SELF type as well — `impl From<Inner> for
    /// Outer` beside `impl From<TaggedInner> for Outer` — leave nothing for
    /// the self type to separate, so the trait instantiation joins the
    /// discriminator for those. Each is what a different call site asked for:
    /// the pair `(Inner, Outer)` and the pair `(TaggedInner, Outer)` are two
    /// conversions, and a `hoisted_method_names` entry that cannot tell them
    /// apart sends every call to whichever was emitted first.
    fn hoistedMethodName(
        self: *Lowerer,
        target: ir.spine.EntityId,
        parent_ent: ir.spine.Entity,
        name: []const u8,
    ) ![]const u8 {
        const entry = try self.hoisted_self_type_keys.getOrPut(self.alloc, target);
        if (!entry.found_existing) entry.value_ptr.* = .empty;
        const claimed = &entry.value_ptr.*;
        const identity = try self.implMethodIdentity(parent_ent);
        const previous = claimed.get(name) orelse
            return self.claimHoistedName(target, name, parent_ent);
        if (std.mem.eql(u8, previous, identity)) return name;
        const self_key = try self.implSelfTypeKey(parent_ent);
        defer self.alloc.free(self_key);
        const mangled = try std.fmt.allocPrint(self.alloc, "{s}__{s}", .{ name, self_key });
        const previous_mangled = claimed.get(mangled) orelse {
            try claimed.put(self.alloc, mangled, identity);
            return mangled;
        };
        if (std.mem.eql(u8, previous_mangled, identity)) return mangled;
        const trait_key = try self.implTraitKey(parent_ent);
        defer self.alloc.free(trait_key);
        const qualified = try std.fmt.allocPrint(self.alloc, "{s}_{s}", .{ mangled, trait_key });
        try claimed.put(self.alloc, qualified, identity);
        return qualified;
    }

    /// Record `name` on `target` as belonging to this impl block, and hand the
    /// name back.
    ///
    /// A name a target's `StructBody` renders is claimed here too, even though
    /// nothing is hoisted for it: the claim is what tells a later impl block
    /// declaring the same method name that the source name is taken and that
    /// it has to take a name of its own. An existing claim is never
    /// overwritten — the first impl block to name it is the one that holds it.
    fn claimHoistedName(
        self: *Lowerer,
        target: ir.spine.EntityId,
        name: []const u8,
        parent_ent: ir.spine.Entity,
    ) ![]const u8 {
        const entry = try self.hoisted_self_type_keys.getOrPut(self.alloc, target);
        if (!entry.found_existing) entry.value_ptr.* = .empty;
        const identity = try self.implMethodIdentity(parent_ent);
        const slot = try entry.value_ptr.getOrPut(self.alloc, name);
        if (!slot.found_existing) slot.value_ptr.* = identity;
        return name;
    }

    /// The identity of the FUNCTION an `impl` block contributes: the self type
    /// it names together with the trait instantiation it implements.
    ///
    /// A trait's arguments are part of which function this is, exactly as much
    /// as the self type is: `impl From<Inner> for Outer` and `impl
    /// From<TaggedInner> for Outer` declare the same method on the same target
    /// and convert two different sources. The rendering is a pure function of
    /// the IR, so it neither moves between runs nor depends on the order
    /// entities are visited in, and it is spelled rather than numbered so a
    /// renamed trait stays as stable as the graph is. Only `[A-Za-z0-9_]` is
    /// produced, so a mangled name stays a plain Zig identifier instead of
    /// reaching for `@"..."` escaping.
    fn implMethodIdentity(self: *Lowerer, parent_ent: ir.spine.Entity) ![]const u8 {
        const impl_body = implBodyFor(self.ir.bodies.bodies, parent_ent) orelse
            return self.alloc.dupe(u8, "none");
        var key: std.ArrayListUnmanaged(u8) = .empty;
        errdefer key.deinit(self.alloc);
        try self.writeTypeKey(impl_body.self_ty, &key, 0);
        if (impl_body.trait_path) |trait_path| {
            try key.append(self.alloc, '_');
            try self.writePathKey(trait_path, &key, 0);
            for (impl_body.trait_args) |arg| {
                try key.append(self.alloc, '_');
                try self.writeTypeKey(arg, &key, 1);
            }
        }
        return key.toOwnedSlice(self.alloc);
    }

    /// A stable discriminator for the self type an `impl` block names.
    ///
    /// The rendering is a pure function of the IR type, so it neither moves
    /// between runs nor depends on the order entities are visited in. Only
    /// `[A-Za-z0-9_]` is produced, so a mangled name stays a plain Zig
    /// identifier instead of reaching for `@"..."` escaping.
    fn implSelfTypeKey(self: *Lowerer, parent_ent: ir.spine.Entity) ![]const u8 {
        const impl_body = implBodyFor(self.ir.bodies.bodies, parent_ent) orelse
            return self.alloc.dupe(u8, "none");
        var key: std.ArrayListUnmanaged(u8) = .empty;
        errdefer key.deinit(self.alloc);
        try self.writeTypeKey(impl_body.self_ty, &key, 0);
        return key.toOwnedSlice(self.alloc);
    }

    /// The trait instantiation an `impl` block implements, as one
    /// identifier-safe key: the trait's own path and each of its arguments.
    ///
    /// This is the part of `implMethodIdentity` that survives a self-type
    /// collision, so it is what tells two conversions that share a target
    /// apart when neither the name nor the self type can.
    fn implTraitKey(self: *Lowerer, parent_ent: ir.spine.Entity) ![]const u8 {
        var key: std.ArrayListUnmanaged(u8) = .empty;
        errdefer key.deinit(self.alloc);
        const impl_body = implBodyFor(self.ir.bodies.bodies, parent_ent) orelse
            return key.toOwnedSlice(self.alloc);
        if (impl_body.trait_path) |trait_path| try self.writePathKey(trait_path, &key, 0);
        for (impl_body.trait_args) |arg| {
            try key.append(self.alloc, '_');
            try self.writeTypeKey(arg, &key, 1);
        }
        return key.toOwnedSlice(self.alloc);
    }

    /// Append a path's own spelling to `key`, one identifier-safe segment at a
    /// time.
    fn writePathKey(
        self: *Lowerer,
        path: ir.types.Path,
        key: *std.ArrayListUnmanaged(u8),
        depth: usize,
    ) !void {
        if (depth >= ir.types.traversal_depth_max) return key.append(self.alloc, '_');
        for (path.segments, 0..) |segment, index| {
            if (index != 0) try key.append(self.alloc, '_');
            try self.writeIdentifierKey(segment.name, key);
        }
    }

    fn writeTypeKey(
        self: *Lowerer,
        ty: ir.types.Type,
        key: *std.ArrayListUnmanaged(u8),
        depth: usize,
    ) !void {
        if (depth >= ir.types.traversal_depth_max) return key.append(self.alloc, '_');
        switch (ty) {
            .path => |path| {
                for (path.segments, 0..) |segment, index| {
                    if (index != 0) try key.append(self.alloc, '_');
                    try self.writeIdentifierKey(segment.name, key);
                }
            },
            .external_nominal => |nominal| {
                for (nominal.path, 0..) |segment, index| {
                    if (index != 0) try key.append(self.alloc, '_');
                    try self.writeIdentifierKey(segment, key);
                }
                for (nominal.args) |arg| {
                    try key.append(self.alloc, '_');
                    try self.writeTypeKey(arg, key, depth + 1);
                }
            },
            .prim => |prim| try self.writeIdentifierKey(@tagName(prim), key),
            .reference => |ref| {
                try self.writeIdentifierKey(if (ref.mut) "mutref" else "ref", key);
                try self.writeTypeKey(ref.pointee, key, depth + 1);
            },
            .raw_ptr => |ptr| {
                try self.writeIdentifierKey(if (ptr.mut) "mutraw" else "raw", key);
                try self.writeTypeKey(ptr.pointee, key, depth + 1);
            },
            .slice => |slice| {
                try self.writeIdentifierKey(if (slice.const_) "cslice" else "slice", key);
                try self.writeTypeKey(slice.elem, key, depth + 1);
            },
            .array => |array| {
                try self.writeTypeKey(array.elem, key, depth + 1);
                try key.append(self.alloc, '_');
                switch (array.len) {
                    .literal => |len| try key.print(self.alloc, "{d}", .{len}),
                    .generic => |index| try key.print(self.alloc, "g{d}", .{index}),
                    .expression => |index| try key.print(self.alloc, "e{d}", .{index}),
                }
            },
            .tuple => |members| {
                try self.writeIdentifierKey("tuple", key);
                for (members, 0..) |member, index| {
                    if (index != 0) try key.append(self.alloc, '_');
                    try self.writeTypeKey(member, key, depth + 1);
                }
            },
            .fn_ptr => |ptr| {
                try self.writeIdentifierKey("fnptr", key);
                try self.writeTypeKey(ptr.ret, key, depth + 1);
            },
            .generic_inst => |inst| {
                try self.writeIdentifierKey("inst", key);
                try key.append(self.alloc, '_');
                try key.print(self.alloc, "{d}", .{inst.decl});
                for (inst.args.params) |arg| {
                    try key.append(self.alloc, '_');
                    try self.writeTypeKey(arg, key, depth + 1);
                }
            },
            .option => |inner| {
                try self.writeIdentifierKey("opt", key);
                try self.writeTypeKey(inner.*, key, depth + 1);
            },
            .result => |res| {
                try self.writeIdentifierKey("res", key);
                try self.writeTypeKey(res.ok, key, depth + 1);
                try self.writeTypeKey(res.err, key, depth + 1);
            },
            .boxed => |inner| {
                try self.writeIdentifierKey("box", key);
                try self.writeTypeKey(inner.*, key, depth + 1);
            },
            .@"opaque" => |opaque_ty| {
                try self.writeIdentifierKey("opaque", key);
                if (opaque_ty.concrete) |concrete| {
                    try self.writeTypeKey(concrete.*, key, depth + 1);
                }
            },
            .dyn_trait => try self.writeIdentifierKey("dyn", key),
            .unsupported => |unsupported| try self.writeIdentifierKey(
                @tagName(unsupported.reason),
                key,
            ),
        }
    }

    /// Append `name` to `key`, mapping every byte outside `[A-Za-z0-9_]` to
    /// an underscore so the result can never split into a dotted path or need
    /// identifier escaping when it is spliced into a declaration name.
    fn writeIdentifierKey(
        self: *Lowerer,
        name: []const u8,
        key: *std.ArrayListUnmanaged(u8),
    ) !void {
        for (name) |c| {
            const word = (c >= 'a' and c <= 'z') or
                (c >= 'A' and c <= 'Z') or
                (c >= '0' and c <= '9') or c == '_';
            try key.append(self.alloc, if (word) c else '_');
        }
    }

    /// Type parameters an `impl` binds that a method hoisted onto `target_id`
    /// has to declare on its own signature.
    ///
    /// A blanket `impl<T: Bound> Trait for T` names a type parameter as its
    /// self type, so the target has no declaration body of its own and every
    /// method lands at module scope. The emitted receiver is still `*const T`,
    /// and a module file binds nothing else named `T`, so the hoisted function
    /// has to carry the impl's type parameter with it. An impl whose self type
    /// is a real declaration keeps the parameter inside that declaration, and
    /// the hoisted method stays inside it too, so it needs nothing here.
    fn moduleHoistGenericParams(
        self: *Lowerer,
        parent_ent: ir.spine.Entity,
        target_id: ir.spine.EntityId,
    ) []const []const u8 {
        if (parent_ent.kind != .impl_) return &.{};
        const target_ent = self.ir.graph.symbol_table.get(target_id) orelse return &.{};
        if (target_ent.kind != .module) return &.{};
        if (parent_ent.id >= self.ir.bodies.bodies.len) return &.{};
        const impl_body = switch (self.ir.bodies.bodies[parent_ent.id]) {
            .impl_ => |body| body,
            else => return &.{},
        };
        const generics = impl_body.generics orelse return &.{};
        const self_segment = switch (impl_body.self_ty) {
            .path => |path| lastPathSegment(path.segments) orelse return &.{},
            else => return &.{},
        };
        var carried: std.ArrayListUnmanaged([]const u8) = .empty;
        for (generics.params) |param| {
            const name = switch (param) {
                .type_ => |type_param| type_param.name,
                // A lifetime is erased and a const parameter needs a value the
                // method does not have, so neither becomes a Zig type parameter.
                .const_, .lifetime => continue,
            };
            if (!std.mem.eql(u8, name, self_segment.name)) continue;
            var already_carried = false;
            for (carried.items) |carried_name| {
                if (std.mem.eql(u8, carried_name, name)) {
                    already_carried = true;
                    break;
                }
            }
            if (already_carried) continue;
            carried.append(self.alloc, name) catch return &.{};
        }
        return carried.items;
    }

    /// Record every struct field whose source name is also a method name on
    /// the same struct, and give it a fresh emitted name.
    ///
    /// Rust keeps fields and methods in separate namespaces, so `struct
    /// BytesToHexChars { next: Option<char> }` beside `fn next(&mut self)` is
    /// legal. Zig has one namespace for fields and declarations, so one of the
    /// two has to move. The method keeps the name — `Iterator` is driven by
    /// calling `.next()` — and the field takes a fresh one, which is invisible
    /// outside the struct.
    fn prepareStructFieldNames(self: *Lowerer) !void {
        const count = self.ir.graph.symbol_table.count();
        for (0..count) |idx| {
            const entity_id: ir.spine.EntityId = @intCast(idx);
            const ent = self.ir.graph.symbol_table.get(entity_id) orelse continue;
            if (ent.kind != .struct_) continue;
            if (entity_id >= self.ir.bodies.bodies.len) continue;
            const struct_body = switch (self.ir.bodies.bodies[entity_id]) {
                .struct_ => |sb| sb,
                else => continue,
            };

            // The struct's single Zig namespace holds its methods, its other
            // declarations, and its fields, so a generated name must avoid
            // all three.
            var taken: std.ArrayListUnmanaged([]const u8) = .empty;
            defer taken.deinit(self.alloc);
            for (struct_body.methods) |method| {
                const method_id = self.methodEntityForDefinition(entity_id, method);
                const name = if (method_id) |id|
                    self.hoisted_method_names.get(id) orelse method.name
                else
                    method.name;
                try taken.append(self.alloc, name);
            }
            if (self.hoisted_by_id.get(entity_id)) |hoisted| {
                for (hoisted.items) |decl| {
                    if (decl == .fn_decl) try taken.append(self.alloc, decl.fn_decl.name);
                }
            }
            const method_names = try self.alloc.alloc([]const u8, taken.items.len);
            defer self.alloc.free(method_names);
            @memcpy(method_names, taken.items);
            for (struct_body.fields) |field| try taken.append(self.alloc, field.name);

            var renames: std.StringHashMapUnmanaged([]const u8) = .empty;
            var renamed_any = false;
            for (struct_body.fields) |field| {
                if (!nameInList(method_names, field.name)) continue;
                const base = try self.collectorBindingName("field", taken.items);
                const candidate = try std.fmt.allocPrint(
                    self.alloc,
                    "{s}_{s}",
                    .{ field.name, base },
                );
                try taken.append(self.alloc, candidate);
                try renames.put(self.alloc, field.name, candidate);
                renamed_any = true;
            }
            if (renamed_any) try self.renamed_struct_fields.put(self.alloc, entity_id, renames);
        }
    }

    /// Emitted name of the enum that owns `def`. An `enum_variant` node names
    /// the variant entity when the graph linked one, and the enum otherwise,
    /// so the owner is one level up in the first case.
    fn enumOwnerName(self: *Lowerer, def: ir.spine.EntityId) ![]const u8 {
        const entity = self.ir.graph.symbol_table.get(def) orelse
            return error.MissingDefinition;
        const owner_id = if (entity.kind == .variant)
            entity.parent orelse return error.MissingParentId
        else
            def;
        return self.lowerResolvedEntityName(owner_id);
    }

    /// True when the enum owning `def` declares as a tagged `union(enum)`,
    /// which the declaration lowering picks only for a data-carrying Rust
    /// enum (`EnumKind == .data`). A purely field-free enum declares as a
    /// plain Zig `enum`, whose members are bare tags with no field to
    /// initialize.
    fn enumDeclaresTagFields(self: *const Lowerer, def: ir.spine.EntityId) bool {
        const entity = self.ir.graph.symbol_table.get(def) orelse return false;
        const owner = if (entity.kind == .variant)
            entity.parent orelse return false
        else
            def;
        if (owner >= self.ir.bodies.bodies.len) return false;
        const enum_body = switch (self.ir.bodies.bodies[owner]) {
            .enum_ => |body| body,
            else => return false,
        };
        return enum_body.kind == .data;
    }

    /// Emitted name of a struct field, applying any collision rename.
    fn structFieldName(
        self: *const Lowerer,
        struct_id: ir.spine.EntityId,
        source_name: []const u8,
    ) []const u8 {
        const renames = self.renamed_struct_fields.get(struct_id) orelse return source_name;
        return renames.get(source_name) orelse source_name;
    }

    /// Struct EntityId behind an expression type, if the type names one.
    fn structDefForType(self: *const Lowerer, ty: ir.types.Type) ?ir.spine.EntityId {
        var current = ty;
        for (0..32) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .boxed => |boxed| current = boxed.*,
                else => break,
            }
        }
        const path = switch (current) {
            .path => |p| p,
            else => return null,
        };
        const segment = lastPathSegment(path.segments) orelse return null;
        const id = segment.id orelse return null;
        const ent = self.ir.graph.symbol_table.get(id) orelse return null;
        if (ent.kind != .struct_) return null;
        return id;
    }

    /// Whether the `.struct_` body of `target` renders `entity_id` itself.
    ///
    /// `StructBody.methods` keeps ONE entry per method NAME, so the question
    /// is not "does the struct have a method with this name" but "is this
    /// declaration the one it kept". Answering it by name alone is what let two
    /// impl blocks for one target collapse onto a single declaration: the
    /// second was emitted nowhere, so every call that pair asked for silently
    /// reached the first. The signature cannot answer it either — two
    /// instantiations of one trait for one target may declare the same
    /// signature, as `impl Marker<u8> for Outer` and `impl Marker<u16> for
    /// Outer` both declaring `fn marker() -> u8` do, and those are two
    /// functions.
    ///
    /// The entry's recorded body root is the answer: `extractFunction` writes
    /// each method's own body node into the struct's entry, and that node is
    /// the very one the method's `FnBody` carries, so it names one actual
    /// declaration rather than a resemblance to one.
    fn structBodyRendersMethod(
        self: *const Lowerer,
        target: ir.spine.EntityId,
        entity_id: ir.spine.EntityId,
        name: []const u8,
    ) bool {
        if (target >= self.ir.bodies.bodies.len) return false;
        const struct_body = switch (self.ir.bodies.bodies[target]) {
            .struct_ => |sb| sb,
            else => return false,
        };
        var attributed = false;
        for (struct_body.methods) |method| {
            if (!std.mem.eql(u8, method.name, name)) continue;
            const owner = self.recordedMethodOwner(target, name, method.body) orelse continue;
            attributed = true;
            if (owner == entity_id) return true;
        }
        // An entry that names no single method is the one shape left, and then
        // the first impl block to declare the name is the one the struct
        // renders — the rule `StructBody` itself follows. An entry that DOES
        // name one is never overridden by this: that is a different
        // declaration, and answering the question about it anyway is what
        // dropped a conversion the source asked for.
        if (attributed) return false;
        return self.firstImplMethodFor(target, entity_id, name);
    }

    /// The method on `target` whose body root IS `recorded`, or null when that
    /// node names no single method.
    ///
    /// Node zero is what an entry carries before any body is extracted, and it
    /// is not an identity — every such entry shares it. Two methods sharing one
    /// real body node would name the declaration just as little, so that is
    /// reported as no answer rather than picked from.
    fn recordedMethodOwner(
        self: *const Lowerer,
        target: ir.spine.EntityId,
        name: []const u8,
        recorded: ir.exprs.NodeId,
    ) ?ir.spine.EntityId {
        if (recorded == 0) return null;
        var owner: ?ir.spine.EntityId = null;
        const count = self.ir.graph.symbol_table.count();
        for (0..count) |index| {
            const candidate_id: ir.spine.EntityId = @intCast(index);
            const candidate = self.ir.graph.symbol_table.get(candidate_id) orelse continue;
            if (candidate.kind != .fn_ or candidate.parent == null) continue;
            if (!std.mem.eql(u8, candidate.name, name)) continue;
            if (candidate_id >= self.ir.bodies.bodies.len) continue;
            const candidate_body = switch (self.ir.bodies.bodies[candidate_id]) {
                .fn_ => |body| body,
                else => continue,
            };
            if (candidate_body.body != recorded) continue;
            const impl_entity = self.ir.graph.symbol_table.get(candidate.parent.?) orelse
                continue;
            const impl_target = hoistTargetFor(impl_entity) orelse continue;
            if (impl_target != target) continue;
            if (owner != null) return null;
            owner = candidate_id;
        }
        return owner;
    }

    /// Whether `entity_id` is the first impl-declared method called `name` on
    /// `target`.
    fn firstImplMethodFor(
        self: *const Lowerer,
        target: ir.spine.EntityId,
        entity_id: ir.spine.EntityId,
        name: []const u8,
    ) bool {
        const count = self.ir.graph.symbol_table.count();
        for (0..count) |index| {
            const candidate_id: ir.spine.EntityId = @intCast(index);
            const candidate = self.ir.graph.symbol_table.get(candidate_id) orelse continue;
            if (candidate.kind != .fn_ or candidate.parent == null) continue;
            if (!std.mem.eql(u8, candidate.name, name)) continue;
            const impl_entity = self.ir.graph.symbol_table.get(candidate.parent.?) orelse
                continue;
            const impl_target = hoistTargetFor(impl_entity) orelse continue;
            if (impl_target != target) continue;
            return candidate_id == entity_id;
        }
        return false;
    }

    /// True when a hoisted declaration already exists for `name` on `tid`.
    fn isHoistedMethodRegistered(self: *Lowerer, tid: ir.spine.EntityId, name: []const u8) bool {
        if (self.hoisted_by_id.get(tid)) |list| {
            for (list.items) |d| {
                if (d == .fn_decl and std.mem.eql(u8, d.fn_decl.name, name)) return true;
            }
        }
        return false;
    }

    fn appendImport(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        local_name: []const u8,
        module_or_path: []const u8,
        is_pub: bool,
    ) !void {
        for (imports.items) |*existing| {
            if (std.mem.eql(u8, existing.local_name, local_name) and
                std.mem.eql(u8, existing.module_or_path, module_or_path))
            {
                // An import can be requested privately first and publicly
                // later, when a `pub mod` is re-exported from the crate root.
                // Widening the existing entry is what makes the re-export
                // reachable; keeping the first-seen visibility would discard
                // the `pub`.
                existing.is_pub = existing.is_pub or is_pub;
                return;
            }
        }
        const owned_local_name = try self.alloc.dupe(u8, local_name);
        errdefer self.alloc.free(owned_local_name);
        const owned_module_or_path = try self.alloc.dupe(u8, module_or_path);
        errdefer self.alloc.free(owned_module_or_path);
        try imports.append(self.alloc, .{
            .local_name = owned_local_name,
            .module_or_path = owned_module_or_path,
            .is_pub = is_pub,
        });
    }

    /// Rust `pub mod foo;` at the crate root is a re-export: the module
    /// namespace is part of the crate's public API, so the Zig import has to
    /// be `pub const` or nothing outside the package can reach it. A private
    /// `mod` stays a private import — publishing it would widen the generated
    /// API beyond what the source declared.
    ///
    /// Scoped to the crate root, where a `pub` binding is genuinely the
    /// crate's public surface. Inside a nested module the binding is only as
    /// visible as that module, so re-exporting it changes nothing reachable.
    fn moduleImportIsReExport(
        self: *const Lowerer,
        importing_module: ir.graph.Module,
        target_module_id: ir.spine.EntityId,
    ) bool {
        if (!importing_module.is_crate) return false;
        const target = self.ir.graph.symbol_table.get(target_module_id) orelse return false;
        return target.visibility == .public;
    }
    fn appendStdImportIfNeeded(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        decls: []const ast.Decl,
        tests: []const ast.TestDecl,
    ) !void {
        if (!try StdImportDemand.fileRequiresStd(decls, tests)) return;
        for (imports.items) |existing| {
            if (std.mem.eql(u8, existing.local_name, "std") and
                std.mem.eql(u8, existing.module_or_path, "std"))
            {
                return;
            }
        }
        try imports.insert(self.alloc, 0, .{
            .local_name = "std",
            .module_or_path = "std",
            .is_pub = false,
        });
    }

    fn moduleImportNameTaken(
        self: *const Lowerer,
        current_module: ir.graph.Module,
        target_module_id: ir.spine.EntityId,
        candidate: []const u8,
        module_path: []const u8,
    ) bool {
        if (self.current_owner_reserved) |reserved| {
            for (reserved.items) |name| {
                if (std.mem.eql(u8, name, candidate)) return true;
            }
        }
        if (self.current_imports) |imports| {
            for (imports.items) |existing| {
                if (!std.mem.eql(u8, existing.local_name, candidate)) continue;
                return !std.mem.eql(u8, existing.module_or_path, module_path);
            }
        }

        if (isReservedZigIdentifier(candidate)) return true;
        for (current_module.items) |item_id| {
            const entity = self.ir.graph.symbol_table.get(item_id) orelse continue;
            if (entity.kind == .module and entity.id == target_module_id) continue;
            if (entity.kind == .use_) {
                const use_decl = self.ir.graph.useById(entity.id) orelse continue;
                if (std.mem.eql(u8, use_decl.local_name, candidate)) return true;
                continue;
            }
            const name = entity.renamed_to orelse entity.name;
            if (std.mem.eql(u8, name, candidate)) return true;
        }

        if (current_module.is_crate and self.ir.graph.crates.items.len > 0) {
            for (self.ir.graph.crates.items[0].deps) |dependency| {
                // Only an emitted import occupies a name. A runtime-bound
                // dependency emits none, so reserving its alias here would make
                // a submodule import take a different, source-foreign name for
                // a binding that does not exist. The module scan above this
                // block already claimed a real module of the same name, so
                // dropping the reservation cannot let one be read as a
                // dependency root either.
                if (self.rootIsRuntimeBound(dependency.local_alias)) continue;
                if (normalizedPackageNameEqual(dependency.local_alias, candidate)) return true;
            }
        }
        return false;
    }

    fn moduleImportAlias(
        self: *Lowerer,
        current_module: ir.graph.Module,
        target_module: ir.graph.Module,
        target_module_id: ir.spine.EntityId,
        module_path: []const u8,
    ) ![]const u8 {
        const base_name = if (target_module.name.len == 0) "root" else target_module.name;
        var candidate: []const u8 = base_name;
        var suffix: usize = 1;
        while (self.moduleImportNameTaken(
            current_module,
            target_module_id,
            candidate,
            module_path,
        )) {
            candidate = try std.fmt.allocPrint(self.alloc, "{s}_{d}", .{ base_name, suffix });
            suffix += 1;
        }
        return candidate;
    }

    fn ensureModuleImport(self: *Lowerer, target_module_id: ir.spine.EntityId) ![]const u8 {
        const importing_module_id = self.current_module_id orelse return error.MissingModule;
        const current_module = self.moduleForEntity(importing_module_id) orelse {
            return error.MissingModule;
        };
        const target_module = self.moduleForEntity(target_module_id) orelse {
            return error.MissingModule;
        };
        const module_path = try self.moduleImportPath(current_module, target_module);
        defer self.alloc.free(module_path);

        const key: ModuleImportKey = .{
            .importing = importing_module_id,
            .target = target_module_id,
        };
        const re_export = self.moduleImportIsReExport(current_module, target_module_id);
        if (self.pending_module_imports.get(key)) |alias| {
            if (self.current_imports) |imports| {
                try self.appendImport(imports, alias, module_path, re_export);
            }
            return alias;
        }

        const alias = try self.moduleImportAlias(
            current_module,
            target_module,
            target_module_id,
            module_path,
        );
        try self.pending_module_imports.put(self.alloc, key, alias);
        if (self.current_imports) |imports| {
            try self.appendImport(imports, alias, module_path, re_export);
        }
        return alias;
    }

    fn appendPendingModuleImports(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        importing_module: ir.graph.Module,
        importing_module_id: ir.spine.EntityId,
    ) !void {
        var pending = self.pending_module_imports.iterator();
        while (pending.next()) |entry| {
            const key = entry.key_ptr.*;
            if (key.importing != importing_module_id) continue;
            const target_module = self.moduleForEntity(key.target) orelse {
                return error.MissingModule;
            };
            const module_path = try self.moduleImportPath(importing_module, target_module);
            defer self.alloc.free(module_path);
            try self.appendImport(
                imports,
                entry.value_ptr.*,
                module_path,
                self.moduleImportIsReExport(importing_module, key.target),
            );
        }
    }

    fn markRuntimeImport(self: *Lowerer) !void {
        const module_id = self.current_module_id orelse return error.MissingModule;
        try self.runtime_import_modules.put(self.alloc, module_id, {});
    }

    fn appendRuntimeImport(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        module_id: ir.spine.EntityId,
    ) !void {
        if (self.runtime_import_modules.contains(module_id)) {
            try self.appendImport(imports, "r2z", "r2z", false);
        }
    }

    /// Find the module row for a module entity. Module rows are dense, while
    /// symbol entities also contain non-module items, so their ids can differ.
    fn moduleForEntity(self: *const Lowerer, entity_id: ir.spine.EntityId) ?ir.graph.Module {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse {
            return self.ir.graph.module(entity_id);
        };

        // Some hand-built IR fixtures contain module rows without matching
        // module entities. Preserve the dense row lookup for those graphs,
        // but prefer a name/parent match when the entity table is complete.
        if (self.ir.graph.module(entity_id)) |dense_module| {
            var has_matching_module_entity = false;
            for (self.ir.graph.symbol_table.entities.items) |candidate| {
                if (candidate.kind != .module) continue;
                if (candidate.parent == dense_module.parent and
                    std.mem.eql(u8, candidate.name, dense_module.name))
                {
                    has_matching_module_entity = true;
                    break;
                }
            }
            if (!has_matching_module_entity) return dense_module;
            if (dense_module.parent == entity.parent and
                std.mem.eql(u8, dense_module.name, entity.name))
            {
                return dense_module;
            }
        }

        for (self.ir.graph.modules.items) |module| {
            if (module.parent == entity.parent and std.mem.eql(u8, module.name, entity.name)) {
                return module;
            }
        }
        return null;
    }

    fn moduleEntityId(self: *const Lowerer, module: ir.graph.Module) ?ir.spine.EntityId {
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .module) continue;
            if (entity.parent == module.parent and std.mem.eql(u8, entity.name, module.name)) {
                return entity.id;
            }
        }
        return null;
    }

    /// Return the generated source path for a module. The Rust module ancestry
    /// forms the directory hierarchy so equal leaf names under different
    /// parents cannot collide.
    fn moduleFilePath(self: *Lowerer, module: ir.graph.Module) ![]const u8 {
        if (module.kind == .root or module.is_crate) {
            return self.alloc.dupe(u8, "src/root.zig");
        }

        var components: std.ArrayListUnmanaged([]const u8) = .empty;
        defer components.deinit(self.alloc);

        var current = module;
        var remaining = self.ir.graph.modules.items.len + 1;
        while (current.kind != .root and !current.is_crate) {
            if (remaining == 0) return error.ModuleHierarchyCycle;
            remaining -= 1;

            if (current.name.len > 0) {
                try components.append(self.alloc, current.name);
            }
            const parent_id = current.parent orelse break;
            current = self.moduleForEntity(parent_id) orelse {
                return error.ModuleParentMissing;
            };
        }

        if (components.items.len == 0) {
            return self.alloc.dupe(u8, "src/root.zig");
        }

        var path: std.ArrayListUnmanaged(u8) = .empty;
        errdefer path.deinit(self.alloc);
        try path.appendSlice(self.alloc, "src/");

        var index = components.items.len;
        while (index > 0) {
            index -= 1;
            try path.appendSlice(self.alloc, components.items[index]);
            if (index > 0) try path.append(self.alloc, '/');
        }
        try path.appendSlice(self.alloc, ".zig");
        return path.toOwnedSlice(self.alloc);
    }

    /// Return the target module path relative to the importing module file.
    fn moduleImportPath(
        self: *Lowerer,
        importing_module: ir.graph.Module,
        target_module: ir.graph.Module,
    ) ![]const u8 {
        const importing_path = try self.moduleFilePath(importing_module);
        defer self.alloc.free(importing_path);
        const target_path = try self.moduleFilePath(target_module);
        defer self.alloc.free(target_path);

        const importing_dir = std.fs.path.dirname(importing_path) orelse ".";
        const relative_path = try std.fs.path.relativePosix(
            self.alloc,
            ".",
            importing_dir,
            target_path,
        );
        if (relative_path.len > 0 and relative_path[0] == '.') {
            return relative_path;
        }
        defer self.alloc.free(relative_path);
        return std.fmt.allocPrint(self.alloc, "./{s}", .{relative_path});
    }

    /// Add the import required by a sibling path or call.
    fn appendUseSiblingImport(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        current_mod_id: ir.spine.EntityId,
        use_id: ir.spine.EntityId,
    ) !void {
        const use_decl = self.ir.graph.useById(use_id) orelse return error.MissingUseDeclaration;
        if (!(try self.useHasLowerableTarget(use_decl))) return;
        if (use_decl.kind == .glob) return;

        const target = self.ir.graph.symbol_table.get(use_decl.target) orelse {
            return error.MissingUseTarget;
        };
        const parent_id = if (target.kind == .module)
            target.id
        else
            target.parent orelse return error.MissingParentId;
        if (parent_id == current_mod_id or parent_id == 0) return;

        const parent_module = self.moduleForEntity(parent_id) orelse return error.MissingModule;
        if (parent_module.name.len == 0 or parent_module.is_extern) return;
        const current_module = self.moduleForEntity(current_mod_id) orelse return error.MissingModule;
        const module_path = try self.moduleImportPath(current_module, parent_module);
        defer self.alloc.free(module_path);
        const parent_entity = self.ir.graph.symbol_table.get(parent_id) orelse {
            return error.MissingParentId;
        };
        try self.appendImport(
            imports,
            parent_module.name,
            module_path,
            use_decl.is_pub_export and parent_entity.visibility == .public,
        );
    }
    fn owningModuleEntity(self: *const Lowerer, entity_id: ir.spine.EntityId) !?ir.spine.EntityId {
        var current: ?ir.spine.EntityId = entity_id;
        var remaining = self.ir.graph.symbol_table.count();
        while (current) |id| {
            if (remaining == 0) return error.ModuleHierarchyCycle;
            remaining -= 1;
            const entity = self.ir.graph.symbol_table.get(id) orelse return error.MissingEntityId;
            if (entity.kind == .module) return id;
            current = entity.parent;
        }
        return null;
    }

    fn entityBelongsToExternalModule(
        self: *const Lowerer,
        entity_id: ir.spine.EntityId,
    ) !bool {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse return error.MissingEntityId;
        if (entity.kind == .use_) return false;
        const owner = try self.owningModuleEntity(entity_id) orelse return false;
        const module = self.moduleForEntity(owner) orelse return false;
        return module.is_extern;
    }

    /// Return the nominal type that owns an inherent method entity.
    fn inherentStructForEntity(
        self: *const Lowerer,
        entity_id: ir.spine.EntityId,
    ) !?ir.spine.EntityId {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse {
            return error.MissingEntityId;
        };
        if (entity.kind != .fn_) return null;

        var parent_id = entity.parent;
        while (parent_id) |id| {
            const parent = self.ir.graph.symbol_table.get(id) orelse return error.MissingParentId;
            switch (parent.kind) {
                .struct_, .enum_, .union_ => return id,
                .impl_ => {
                    // An impl whose name contains " for " is a trait impl.
                    // Trait methods are not inherent members of the target.
                    if (std.mem.indexOf(u8, parent.name, " for ") != null) return null;
                    const target_id = parent.parent orelse return error.MissingParentId;
                    const target = self.ir.graph.symbol_table.get(target_id) orelse {
                        return error.MissingDefinition;
                    };
                    switch (target.kind) {
                        .struct_, .enum_, .union_ => return target_id,
                        else => parent_id = target.parent,
                    }
                },
                else => parent_id = parent.parent,
            }
        }
        return null;
    }

    /// Qualify an inherent method with its type namespace. Methods called from
    /// their own struct use `Self`; calls from another scope use the type name.
    fn qualifyInherentMethod(
        self: *Lowerer,
        entity_id: ir.spine.EntityId,
        resolved: ast.Expr,
    ) !ast.Expr {
        const owner_id = (try self.inherentStructForEntity(entity_id)) orelse return resolved;
        const owner = self.ir.graph.symbol_table.get(owner_id) orelse return error.MissingDefinition;
        const owner_name = owner.renamed_to orelse owner.name;
        if (owner_name.len == 0) return error.MissingDefinitionName;
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse return error.MissingDefinition;
        const name = entity.renamed_to orelse entity.name;
        if (name.len == 0) return error.MissingDefinitionName;

        const target = if (self.current_struct_id) |current_id|
            if (current_id == owner_id)
                try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, "Self") })
            else
                try self.allocExpr(try self.lowerResolvedEntity(owner_id))
        else
            try self.allocExpr(try self.lowerResolvedEntity(owner_id));
        return .{ .field_access = .{
            .target = target,
            .field_name = try self.alloc.dupe(u8, name),
        } };
    }
    fn lowerPathExpr(self: *Lowerer, path: ir.exprs.PathExpr) !ast.Expr {
        const entity = self.ir.graph.symbol_table.get(path.def) orelse return error.MissingDefinition;
        if (entity.kind == .const_) {
            if (entity.parent) |parent_id| {
                const parent = self.ir.graph.symbol_table.get(parent_id) orelse return error.MissingDefinition;
                if (parent.kind == .trait_) {
                    if (path.generic_args.len != 1 or !self.traitHasAssociatedMember(parent_id, entity.name))
                        return error.UnsupportedAssociatedTypeProjection;
                    const generic_args = try self.alloc.alloc(ast.Type, 1);
                    generic_args[0] = try self.lowerType(path.generic_args[0]);
                    const descriptor = try self.ensureTraitDescriptor(parent_id);
                    const target = try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = descriptor }),
                        .generic_args = generic_args,
                        .args = &.{},
                    } });
                    return .{ .field_access = .{ .target = target, .field_name = entity.name } };
                }
            }
        }
        const resolved = try self.lowerResolvedEntity(path.def);
        const preferred: ?[]const ir.types.Type =
            if (path.generic_args.len > 0) path.generic_args else null;
        const generic_args = try self.lowerGenericArgs(path.def, preferred);
        if (resolved == .ident) {
            for (self.current_mutable_copies) |copy| {
                if (!copy.conditional_bufread or copy.def != path.def) continue;
                return .{ .if_expr = .{
                    .cond = try self.bufReadThinPointerCondition(.{ .ident = copy.signature_name }),
                    .then_body = try self.allocExpr(.{ .ident = copy.signature_name }),
                    .else_body = try self.allocExpr(resolved),
                } };
            }
        }
        if (generic_args.len == 0) {
            if (try self.fieldlessStructConstructor(path.def)) |value| return value;
            return resolved;
        }
        const callee = try self.allocExpr(resolved);
        errdefer self.alloc.destroy(callee);
        return .{
            .call = .{
                .callee = callee,
                .generic_args = generic_args,
                .args = &.{},
            },
        };
    }

    /// The one value a fieldless struct declaration has.
    ///
    /// `struct Unit;` is a complete nominal, and the declaration the emitter
    /// writes for it is `const Unit = struct {};` — a TYPE. Naming that type
    /// where the source named the VALUE answers `type` inside a signature that
    /// promises the struct, so a path naming such a declaration is its
    /// constructor: `Unit{}`.
    ///
    /// The question is the declaration's own emptiness, not the source form it
    /// was written in, because `struct Unit;`, `struct Record {}` and `struct
    /// Tuple();` all reach the same fieldless container and each keeps its own
    /// nominal name. A struct with a field of its own is a different question:
    /// `Point{}` is not a `Point` unless every field has a default, and the
    /// source always spells that value out. A generic one is a type FUNCTION,
    /// so its bare name is a constructor to call rather than a type to build.
    fn fieldlessStructConstructor(self: *Lowerer, def: ir.spine.EntityId) !?ast.Expr {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (entity.kind != .struct_) return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        const body = switch (self.ir.bodies.bodies[def]) {
            .struct_ => |value| value,
            else => return null,
        };
        if (body.fields.len != 0 or body.generic_params.len != 0) return null;
        return .{ .struct_init = .{
            .type_name = .{ .named = try self.lowerResolvedEntityName(def) },
            .fields = &.{},
        } };
    }

    fn resolvedEntityModuleAlias(
        self: *Lowerer,
        owner_id: ?ir.spine.EntityId,
        declaration_parent: ?ir.spine.EntityId,
    ) !?[]const u8 {
        const owner = owner_id orelse return null;
        const current_module = self.current_module_id orelse return null;
        if (current_module == owner) {
            if (self.current_struct_id == null or declaration_parent != owner) return null;
        }
        const module_alias = try self.ensureModuleImport(owner);
        return module_alias;
    }
    fn prepareLocalBindingNames(
        self: *Lowerer,
        callable_id: ?ir.spine.EntityId,
        names: *LocalBindingNames,
    ) !void {
        names.* = .{ .callable_id = callable_id };
        const cid = callable_id orelse return;

        var count: usize = 0;
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind == .field and entity.parent == cid) count += 1;
        }
        if (count == 0) return;

        const defs = try self.alloc.alloc(ir.spine.EntityId, count);
        errdefer self.alloc.free(defs);
        const claimed = try self.alloc.alloc(bool, count);
        errdefer self.alloc.free(claimed);
        for (claimed) |*c| c.* = false;

        var idx: usize = 0;
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind == .field and entity.parent == cid) {
                defs[idx] = entity.id;
                idx += 1;
            }
        }
        names.local_defs = defs;
        names.local_claimed = claimed;

        var all_source_names: std.StringHashMapUnmanaged(void) = .empty;
        defer all_source_names.deinit(self.alloc);
        for (defs) |def| {
            if (self.ir.graph.symbol_table.get(def)) |entity| {
                const src_name = entity.renamed_to orelse entity.name;
                if (src_name.len > 0) {
                    try all_source_names.put(self.alloc, src_name, {});
                }
            }
        }
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            switch (entity.kind) {
                .module, .fn_, .struct_, .enum_, .union_, .trait_, .const_, .static_, .type_alias => {
                    const declaration_name = entity.renamed_to orelse entity.name;
                    if (declaration_name.len > 0) try names.used_names.put(self.alloc, declaration_name, {});
                },
                else => {},
            }
        }
        for ([_][]const u8{ "std", "r2z", "Self" }) |reserved| {
            try names.used_names.put(self.alloc, reserved, {});
        }
        for (defs) |def| {
            const entity = self.ir.graph.symbol_table.get(def) orelse continue;
            const src_name = entity.renamed_to orelse entity.name;
            if (src_name.len == 0) continue;

            if (!names.used_names.contains(src_name)) {
                try names.used_names.put(self.alloc, src_name, {});
                try names.emitted_by_entity.put(self.alloc, def, src_name);
            } else {
                var suffix: usize = 1;
                while (true) : (suffix += 1) {
                    const candidate = try std.fmt.allocPrint(self.alloc, "{s}_{d}", .{ src_name, suffix });
                    if (!names.used_names.contains(candidate) and !all_source_names.contains(candidate)) {
                        try names.used_names.put(self.alloc, candidate, {});
                        try names.emitted_by_entity.put(self.alloc, def, candidate);
                        break;
                    }
                }
            }
        }
    }

    fn activeClosureCaptureOverride(
        self: *const Lowerer,
        def: ir.spine.EntityId,
    ) ?[]const u8 {
        const overrides = &self.active_closure_capture_overrides;
        if (overrides.count() == 0) return null;
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (overrides.get(entity.name)) |name| return name;
        if (entity.renamed_to) |renamed| {
            if (overrides.get(renamed)) |name| return name;
        }
        return null;
    }
    fn clearLocalClosureSnapshots(self: *Lowerer) void {
        var iterator = self.local_closure_snapshots.iterator();
        while (iterator.next()) |entry| {
            self.alloc.free(entry.value_ptr.*);
        }
        self.local_closure_snapshots.clearRetainingCapacity();
    }

    fn deinitLocalClosureSnapshots(self: *Lowerer) void {
        self.clearLocalClosureSnapshots();
        self.local_closure_snapshots.deinit(self.alloc);
    }

    fn lowerResolvedEntityName(self: *Lowerer, def: ir.spine.EntityId) ![]const u8 {
        if (self.local_static_names.get(def)) |emitted_name| {
            return self.alloc.dupe(u8, emitted_name);
        }
        if (self.activeClosureCaptureOverride(def)) |snapshot_name| {
            return self.alloc.dupe(u8, snapshot_name);
        }
        if (self.current_local_binding_names) |names| {
            if (names.emitted_by_entity.get(def)) |emitted_name| {
                return self.alloc.dupe(u8, emitted_name);
            }
        }
        const entity = self.ir.graph.symbol_table.get(def) orelse {
            return error.MissingDefinition;
        };
        // A hoisted method can be emitted under a name of its own when a
        // second impl for a different self type claimed the source name.
        const name = self.hoisted_method_names.get(def) orelse
            (entity.renamed_to orelse entity.name);
        if (name.len == 0) return error.MissingDefinitionName;
        const owner = try self.owningModuleEntity(def);
        if (owner == null and entity.parent != null) return error.MissingModuleOwner;
        if (try self.resolvedEntityModuleAlias(owner, entity.parent)) |module_alias| {
            return std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ module_alias, name });
        }
        return self.alloc.dupe(u8, name);
    }

    /// Qualify declarations across modules and from nested container scopes.
    fn lowerResolvedEntity(self: *Lowerer, def: ir.spine.EntityId) !ast.Expr {
        if (self.local_static_names.get(def)) |emitted_name| {
            return .{ .ident = try self.alloc.dupe(u8, emitted_name) };
        }
        if (self.activeClosureCaptureOverride(def)) |snapshot_name| {
            return .{ .ident = try self.alloc.dupe(u8, snapshot_name) };
        }
        if (self.current_local_binding_names) |names| {
            if (names.emitted_by_entity.get(def)) |emitted_name| {
                return .{ .ident = try self.alloc.dupe(u8, emitted_name) };
            }
        }
        const entity = self.ir.graph.symbol_table.get(def) orelse {
            return error.MissingDefinition;
        };
        // A hoisted method can be emitted under a name of its own when a
        // second impl for a different self type claimed the source name.
        const name = self.hoisted_method_names.get(def) orelse
            (entity.renamed_to orelse entity.name);
        if (name.len == 0) return error.MissingDefinitionName;
        const owner = try self.owningModuleEntity(def);
        if (owner == null) {
            if (entity.parent != null) return error.MissingModuleOwner;
            return .{ .ident = try self.alloc.dupe(u8, name) };
        }
        if (try self.resolvedEntityModuleAlias(owner, entity.parent)) |module_alias| {
            const target = try self.allocExpr(.{
                .ident = try self.alloc.dupe(u8, module_alias),
            });
            return .{ .field_access = .{
                .target = target,
                .field_name = try self.alloc.dupe(u8, name),
            } };
        }
        return .{ .ident = try self.alloc.dupe(u8, name) };
    }

    fn traitImplReceiverForEntity(
        self: *const Lowerer,
        entity_id: ir.spine.EntityId,
    ) !?ir.spine.EntityId {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse {
            return error.MissingDefinition;
        };
        if (entity.kind != .fn_) return null;
        const impl_id = entity.parent orelse return null;
        const impl = self.ir.graph.symbol_table.get(impl_id) orelse {
            return error.MissingParentId;
        };
        if (impl.kind != .impl_ or std.mem.indexOf(u8, impl.name, " for ") == null) return null;

        if (impl.parent) |target_id| {
            const target = self.ir.graph.symbol_table.get(target_id) orelse {
                return error.MissingDefinition;
            };
            switch (target.kind) {
                .struct_, .enum_, .union_ => return target_id,
                else => {},
            }
        }

        const separator = std.mem.indexOf(u8, impl.name, " for ") orelse return null;
        var receiver_name = std.mem.trim(u8, impl.name[separator + 5 ..], " \t\r\n");
        if (std.mem.indexOf(u8, receiver_name, "<")) |generic_start| {
            receiver_name = receiver_name[0..generic_start];
        }
        if (std.mem.lastIndexOf(u8, receiver_name, "::")) |path_separator| {
            receiver_name = receiver_name[path_separator + 2 ..];
        }

        var match: ?ir.spine.EntityId = null;
        for (self.ir.graph.symbol_table.entities.items) |candidate| {
            switch (candidate.kind) {
                .struct_, .enum_, .union_ => {},
                else => continue,
            }
            if (!std.mem.eql(u8, candidate.name, receiver_name)) continue;
            if (match != null) return null;
            match = candidate.id;
        }
        return match;
    }

    fn qualifyTraitImplMethod(
        self: *Lowerer,
        entity_id: ir.spine.EntityId,
    ) !?ast.Expr {
        const receiver_id = (try self.traitImplReceiverForEntity(entity_id)) orelse return null;
        const receiver = try self.lowerResolvedEntity(receiver_id);
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse {
            return error.MissingDefinition;
        };
        const name = self.hoisted_method_names.get(entity_id) orelse
            (entity.renamed_to orelse entity.name);
        if (name.len == 0) return error.MissingDefinitionName;
        const target = try self.allocExpr(receiver);
        errdefer self.alloc.destroy(target);
        const field_name = try self.alloc.dupe(u8, name);
        errdefer self.alloc.free(field_name);
        return .{ .field_access = .{
            .target = target,
            .field_name = field_name,
        } };
    }
    /// Register the module that owns a qualified public re-export.
    fn appendUseModuleImport(
        self: *Lowerer,
        imports: *std.ArrayListUnmanaged(ast.Import),
        current_mod_id: ir.spine.EntityId,
        use_id: ir.spine.EntityId,
    ) !void {
        const use_decl = self.ir.graph.useById(use_id) orelse return error.MissingUseDeclaration;
        if (!use_decl.is_pub_export) return;
        if (!(try self.useHasLowerableTarget(use_decl))) return;
        if (use_decl.kind == .glob) return;

        const target = self.ir.graph.symbol_table.get(use_decl.target) orelse {
            return error.MissingUseTarget;
        };
        const parent_id = target.parent orelse return error.MissingParentId;
        if (parent_id == current_mod_id or parent_id == 0) return;
        const current_module = self.moduleForEntity(current_mod_id) orelse return error.MissingModule;
        const parent_module = self.moduleForEntity(parent_id) orelse return error.MissingModule;
        const module_path = try self.moduleImportPath(current_module, parent_module);
        defer self.alloc.free(module_path);
        const parent_entity = self.ir.graph.symbol_table.get(parent_id) orelse {
            return error.MissingParentId;
        };
        try self.appendImport(
            imports,
            parent_module.name,
            module_path,
            parent_entity.visibility == .public,
        );
    }

    fn appendFunctionLocalStatics(
        self: *Lowerer,
        decls: *std.ArrayListUnmanaged(ast.Decl),
        module_id: ir.spine.EntityId,
    ) !void {
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .static_ or entity.parent == null) continue;
            const owner = try self.owningModuleEntity(entity.id) orelse continue;
            if (owner != module_id) continue;
            if (try self.lowerEntityDecl(entity.id, entity, module_id)) |decl| {
                try decls.append(self.alloc, decl);
            }
        }
    }

    /// Hoist the `fn` items a block declares to the module that contains them.
    ///
    /// Zig has no nested functions, so a helper written inside another
    /// function's body is a module-scope declaration or nothing at all. Its
    /// entity name is already the collision-safe identity — two tests that
    /// each declare `read` cannot collide — and the declaration emits that
    /// same name, so no name map is needed here: the call sites already spell
    /// what this declaration answers to. The parent must be a FUNCTION, which
    /// is what separates a block-local helper from an impl method.
    fn appendBlockLocalFunctions(
        self: *Lowerer,
        decls: *std.ArrayListUnmanaged(ast.Decl),
        module_id: ir.spine.EntityId,
    ) !void {
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .fn_ or entity.parent == null) continue;
            const parent = self.ir.graph.symbol_table.get(entity.parent.?) orelse continue;
            if (parent.kind != .fn_) continue;
            const owner = try self.owningModuleEntity(entity.id) orelse continue;
            if (owner != module_id) continue;
            if (try self.lowerEntityDecl(entity.id, entity, module_id)) |decl| {
                try decls.append(self.alloc, decl);
            }
        }
    }

    fn prepareLocalStaticNames(self: *Lowerer) !void {
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .static_ or entity.parent == null) continue;
            const owner = try self.owningModuleEntity(entity.id) orelse continue;
            const module = self.moduleForEntity(owner) orelse continue;
            if (module.is_extern) continue;
            const name = try std.fmt.allocPrint(
                self.alloc,
                "__r2z_static_{d}_{s}",
                .{ entity.parent.?, entity.name },
            );
            try self.local_static_names.put(self.alloc, entity.id, name);
        }
    }

    fn moduleDocumentation(
        self: *Lowerer,
        module_name: []const u8,
        attributes: []const ir.spine.Attribute,
    ) ![]const u8 {
        const authored = try documentation.fromAttributes(self.alloc, attributes);
        defer if (authored.len > 0) self.alloc.free(authored);
        return std.fmt.allocPrint(
            self.alloc,
            \\Zig translation of Rust crate `{s}`, module `{s}`.
            \\
            \\{s}{s}{s}Zig consumer contract:
            \\Import the registered `{s}` module through a build dependency; child
            \\modules are reached through the crate's exported namespaces.
            \\Requires Zig 0.16.0. Target and optimization options belong to the consumer.
            \\Rust names are preserved except native protocol hooks and name collisions.
            \\Zig field access and value copying do not enforce Rust privacy or moves.
            \\Pointers, slices and erased interfaces borrow their backing storage.
            \\Release returned owned runtime storage with its creating allocator;
            \\assignment is not a deep clone and does not create a second cleanup owner.
            \\This package does not supply a borrow checker or a process-wide allocator.
            \\
            \\```zig
            \\const library = @import("{s}");
            \\```
        ,
            .{
                self.ir.crate_name,
                if (module_name.len == 0) "crate root" else module_name,
                if (authored.len > 0) "Rust source documentation:\n" else "",
                authored,
                if (authored.len > 0) "\n\n" else "",
                self.ir.crate_name,
                self.ir.crate_name,
            },
        );
    }

    fn entityDocumentation(self: *Lowerer, ent: ir.spine.Entity) ![]const u8 {
        const authored = try documentation.fromAttributes(self.alloc, ent.attributes);
        if (authored.len > 0) return authored;
        return switch (ent.kind) {
            .struct_, .union_ => std.fmt.allocPrint(
                self.alloc,
                "Rust `{s}` state with Zig value semantics.",
                .{ent.name},
            ),
            .enum_ => std.fmt.allocPrint(
                self.alloc,
                "Alternatives of Rust `{s}`; the active tag determines the payload.",
                .{ent.name},
            ),
            .fn_ => std.fmt.allocPrint(
                self.alloc,
                "Runs the translated Rust operation `{s}`.",
                .{ent.name},
            ),
            // Re-exports keep the owning declaration's contract.
            else => "",
        };
    }

    fn runtimeOwnsStorage(ty: ast.Type, depth: usize) bool {
        if (depth >= ir.types.traversal_depth_max) return false;
        return switch (ty) {
            .named => |name| std.mem.eql(u8, name, "r2z.alloc.String") or
                std.mem.eql(u8, name, "r2z.alloc.CowStr") or
                std.mem.eql(u8, name, "r2z.alloc.FromUtf8Error"),
            .generic => |generic| blk: {
                if (std.mem.eql(u8, generic.name, "r2z.alloc.Vec") or
                    std.mem.eql(u8, generic.name, "std.ArrayList") or
                    std.mem.eql(u8, generic.name, "std.ArrayListUnmanaged") or
                    std.mem.eql(u8, generic.name, "r2z.alloc.CowSlice")) break :blk true;
                if (std.mem.eql(u8, generic.name, "r2z.Result")) {
                    for (generic.params) |param| {
                        if (runtimeOwnsStorage(param, depth + 1)) break :blk true;
                    }
                }
                break :blk false;
            },
            .opt => |inner| runtimeOwnsStorage(inner.*, depth + 1),
            .err_union => |result| runtimeOwnsStorage(result.payload.*, depth + 1),
            .array => |array| runtimeOwnsStorage(array.elem.*, depth + 1),
            .tuple => |members| blk: {
                for (members) |member| {
                    if (runtimeOwnsStorage(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn callableDocumentation(
        self: *Lowerer,
        authored: []const u8,
        params: []const ast.FnParam,
        ret_type: ast.Type,
    ) ![]const u8 {
        var takes_allocator = false;
        var takes_owner = false;
        for (params) |param| {
            if (param.ty == .named and
                std.mem.eql(u8, param.ty.named, "std.mem.Allocator")) takes_allocator = true;
            if (runtimeOwnsStorage(param.ty, 0)) takes_owner = true;
        }
        const returns_owner = runtimeOwnsStorage(ret_type, 0);
        if (!takes_allocator and !takes_owner and !returns_owner) return authored;
        defer if (authored.len > 0) self.alloc.free(authored);
        return std.fmt.allocPrint(
            self.alloc,
            "{s}\n\n{s}{s}{s}",
            .{
                authored,
                if (takes_allocator)
                    "`allocator` supplies memory operations and cleanup; use an allocator\n" ++
                        "compatible with any pre-existing storage passed into this call.\n"
                else
                    "",
                if (takes_owner)
                    "By-value runtime-owned arguments transfer their storage by contract.\n" ++
                        "Zig copies alias that storage and are not separate cleanup owners.\n"
                else
                    "",
                if (returns_owner)
                    "Release each returned owned runtime payload once with the allocator used\n" ++
                        "to create or grow it; see that runtime type's cleanup contract.\n"
                else
                    "",
            },
        );
    }

    fn lowerModule(self: *Lowerer, mod: ir.graph.Module) !ast.File {
        const file_path = try self.moduleFilePath(mod);
        const current_mod_id = self.moduleEntityId(mod) orelse mod.id;
        const previous_is_root = self.current_file_is_root;
        self.current_file_is_root = mod.id == 0;
        defer self.current_file_is_root = previous_is_root;

        var imports_list: std.ArrayListUnmanaged(ast.Import) = .empty;
        if (mod.id == 0) {
            try self.appendCrateDependencyImports(&imports_list);
        }

        var decls_list: std.ArrayListUnmanaged(ast.Decl) = .empty;
        var tests_list: std.ArrayListUnmanaged(ast.TestDecl) = .empty;
        const previous_imports = self.current_imports;
        self.current_imports = &imports_list;
        defer self.current_imports = previous_imports;
        try self.appendPendingModuleImports(&imports_list, mod, current_mod_id);
        try self.appendFunctionLocalStatics(&decls_list, current_mod_id);
        try self.appendBlockLocalFunctions(&decls_list, current_mod_id);

        for (mod.items) |item_id| {
            const ent = self.ir.graph.symbol_table.get(item_id) orelse {
                return error.MissingEntityId;
            };
            if (try self.entityBelongsToExternalModule(item_id)) continue;

            if (ent.kind == .module) {
                const child_mod = self.moduleForEntity(item_id) orelse return error.MissingModule;
                const module_path = try self.moduleImportPath(mod, child_mod);
                defer self.alloc.free(module_path);
                try self.appendImport(
                    &imports_list,
                    child_mod.name,
                    module_path,
                    ent.visibility == .public,
                );
                continue;
            }

            if (ent.kind == .use_) {
                const use_decl = self.ir.graph.useById(item_id) orelse {
                    return error.MissingUseDeclaration;
                };
                if (!(try self.useHasLowerableTarget(use_decl))) continue;
                try self.appendUseModuleImport(&imports_list, current_mod_id, item_id);
                try self.appendUseSiblingImport(&imports_list, current_mod_id, item_id);
            }
            if (ent.kind == .fn_ and isTestEntity(ent)) {
                if (try self.lowerTestEntity(item_id, ent)) |td| {
                    try tests_list.append(self.alloc, td);
                    continue;
                }
            }

            if (try self.lowerEntityDecl(item_id, ent, current_mod_id)) |decl| {
                try decls_list.append(self.alloc, decl);
            }
        }
        // An `impl` on a type with no declaration body of its own — an array,
        // a primitive — hoists onto the enclosing module, and only the
        // struct/enum/union branches of `lowerEntityDecl` ever render a
        // hoisted list. Without this the methods vanish from the package.
        try self.appendModuleHoistedMethods(&decls_list, current_mod_id);
        // At the crate root a `pub mod` is re-exported as a real
        // declaration, so the root declares its public API instead of only
        // referencing it. Nested modules keep plain imports: there a `pub`
        // binding is only as visible as the file that holds it.
        if (mod.id == 0) {
            try self.promotePublicModuleImportsToReExports(&decls_list, &imports_list);
        }

        try self.appendRuntimeImport(&imports_list, current_mod_id);
        try self.appendStdImportIfNeeded(&imports_list, decls_list.items, tests_list.items);
        const imports = try imports_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(imports);
        const decls = try decls_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(decls);
        const tests = try tests_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(tests);

        return .{
            .path = file_path,
            .documentation = try self.moduleDocumentation(mod.name, mod.attributes),
            .imports = imports,
            .decls = decls,
            .tests = tests,
        };
    }

    /// Rust `pub mod foo;` at the crate root is a re-export: the module
    /// namespace is part of the crate's public API, so it has to be reachable
    /// from outside the generated package. A top-level
    /// `pub const foo = @import("./foo.zig");` is a Zig *declaration*, so a
    /// public submodule import is promoted from the import list to a real
    /// decl. That is what makes the root genuinely declare its API, which is
    /// exactly what the empty-root guard looks for, and the submodule stays
    /// reachable as `root.foo`.
    ///
    /// Only a `pub` submodule is promoted. A private `mod` keeps its private
    /// import, so the generated surface stays exactly what the source
    /// declared. `./…` is the only path that is a sibling module of this
    /// package; `std.…` and `r2z` are not crate modules and are never
    /// re-exported.
    fn promotePublicModuleImportsToReExports(
        self: *Lowerer,
        decls: *std.ArrayListUnmanaged(ast.Decl),
        imports: *std.ArrayListUnmanaged(ast.Import),
    ) !void {
        var kept: usize = 0;
        for (imports.items) |entry| {
            if (!entry.is_pub or !std.mem.startsWith(u8, entry.module_or_path, "./")) {
                imports.items[kept] = entry;
                kept += 1;
                continue;
            }
            const path = try self.allocExpr(.{ .lit = .{ .str = entry.module_or_path } });
            // The argument slice must outlive this statement; a `&.{}`
            // temporary would dangle once the decl is stored.
            const args = try self.alloc.alloc(ast.Expr, 1);
            args[0] = path.*;
            const builtin = try self.allocExpr(.{ .builtin = .{
                .name = "import",
                .args = args,
            } });
            try decls.append(self.alloc, .{ .const_decl = .{
                .name = entry.local_name,
                .documentation = entry.documentation,
                .is_pub = true,
                .init = builtin.*,
            } });
        }
        imports.shrinkRetainingCapacity(kept);
    }

    fn lowerRootFileFromSymbolTable(self: *Lowerer) !ast.File {
        const previous_is_root = self.current_file_is_root;
        self.current_file_is_root = true;
        defer self.current_file_is_root = previous_is_root;
        var imports_list: std.ArrayListUnmanaged(ast.Import) = .empty;
        try self.appendCrateDependencyImports(&imports_list);
        var decls_list: std.ArrayListUnmanaged(ast.Decl) = .empty;
        var tests_list: std.ArrayListUnmanaged(ast.TestDecl) = .empty;
        const previous_imports = self.current_imports;
        self.current_imports = &imports_list;
        defer self.current_imports = previous_imports;
        if (self.moduleForEntity(0)) |root_module| {
            try self.appendPendingModuleImports(&imports_list, root_module, 0);
        }
        try self.appendFunctionLocalStatics(&decls_list, 0);
        try self.appendBlockLocalFunctions(&decls_list, 0);

        const count = self.ir.graph.symbol_table.count();
        for (0..count) |idx| {
            const entity_id: ir.spine.EntityId = @intCast(idx);
            const ent = self.ir.graph.symbol_table.get(entity_id) orelse {
                return error.MissingEntityId;
            };
            if (try self.entityBelongsToExternalModule(entity_id)) continue;

            // Skip nested methods (they are hoisted into structs)
            if (ent.parent != null and ent.kind == .fn_) continue;
            if (ent.kind == .use_) {
                const use_decl = self.ir.graph.useById(entity_id) orelse {
                    return error.MissingUseDeclaration;
                };
                if (!(try self.useHasLowerableTarget(use_decl))) continue;
                try self.appendUseModuleImport(&imports_list, 0, entity_id);
                try self.appendUseSiblingImport(&imports_list, 0, entity_id);
            }

            if (ent.kind == .fn_ and isTestEntity(ent)) {
                if (try self.lowerTestEntity(entity_id, ent)) |td| {
                    try tests_list.append(self.alloc, td);
                    continue;
                }
            }

            if (try self.lowerEntityDecl(entity_id, ent, 0)) |decl| {
                try decls_list.append(self.alloc, decl);
            }
        }
        try self.appendModuleHoistedMethods(&decls_list, 0);
        // A `pub mod` is re-exported as a real declaration, so the root
        // declares its public API instead of only referencing it.
        try self.promotePublicModuleImportsToReExports(&decls_list, &imports_list);

        try self.appendRuntimeImport(&imports_list, 0);
        try self.appendStdImportIfNeeded(&imports_list, decls_list.items, tests_list.items);
        const imports = try imports_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(imports);
        const decls = try decls_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(decls);
        const tests = try tests_list.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(tests);

        return .{
            .path = "src/root.zig",
            .documentation = try self.moduleDocumentation("", &.{}),
            .imports = imports,
            .decls = decls,
            .tests = tests,
        };
    }

    /// Append the hoisted methods whose target is `module_id` itself.
    ///
    /// `collectHoistedMethods` targets a struct, enum, or union when the impl
    /// has one, and otherwise the impl's enclosing module. Only the first
    /// three get rendered by `lowerEntityDecl`; a module target has no
    /// declaration of its own to hang them on, so they are appended here.
    fn appendModuleHoistedMethods(
        self: *Lowerer,
        decls: *std.ArrayListUnmanaged(ast.Decl),
        module_id: ir.spine.EntityId,
    ) !void {
        const hoisted = self.hoisted_by_id.get(module_id) orelse return;
        for (hoisted.items) |decl| try decls.append(self.alloc, decl);
    }

    fn isExternalMarkerPath(path: []const []const u8) bool {
        if (path.len != 3) return false;
        if (!std.mem.eql(u8, path[0], "core") and
            !std.mem.eql(u8, path[0], "std"))
        {
            return false;
        }
        const namespace = path[1];
        const name = path[2];
        if (std.mem.eql(u8, namespace, "ops")) {
            inline for (.{
                "Add",       "Sub",       "Mul",       "Div",       "Rem",       "BitAnd",       "BitOr",       "BitXor",       "Shl",       "Shr",
                "AddAssign", "SubAssign", "MulAssign", "DivAssign", "RemAssign", "BitAndAssign", "BitOrAssign", "BitXorAssign", "ShlAssign", "ShrAssign",
            }) |operator| {
                if (std.mem.eql(u8, name, operator)) return true;
            }
        }
        if (std.mem.eql(u8, namespace, "convert")) {
            inline for (.{ "AsRef", "From", "Into", "TryFrom", "TryInto" }) |trait_name| {
                if (std.mem.eql(u8, name, trait_name)) return true;
            }
        }
        return (std.mem.eql(u8, namespace, "default") and std.mem.eql(u8, name, "Default")) or
            (std.mem.eql(u8, namespace, "hash") and
                (std.mem.eql(u8, name, "Hasher") or std.mem.eql(u8, name, "BuildHasher"))) or
            (std.mem.eql(u8, namespace, "cmp") and
                (std.mem.eql(u8, name, "PartialEq") or std.mem.eql(u8, name, "PartialOrd"))) or
            (std.mem.eql(u8, namespace, "fmt") and
                (std.mem.eql(u8, name, "Debug") or std.mem.eql(u8, name, "Display") or
                    std.mem.eql(u8, name, "Write")));
    }

    /// External module namespaces whose `use` emits no declaration.
    ///
    /// `use core::iter;` names the standard iteration namespace. Nothing under
    /// it is ever declared: iteration traits are erased at emit and the
    /// adapters are reached through the r2z mappings, which add their own
    /// imports on demand. The lexical import is therefore a no-op, exactly as
    /// `use std::io;` already is.
    ///
    /// Only the bare two-segment module is a no-op. A three-segment path under
    /// one of these namespaces names a *type*, and a type is only importable
    /// once the lowerer owns a mapping for it — see `isRuntimeTypeImport` and
    /// `lowerExternalNominal`. `std::collections::HashMap` and
    /// `std::collections::HashSet` have such a mapping; every other
    /// three-segment path under that namespace (`VecDeque`, `BinaryHeap`,
    /// ...) keeps rejecting. Dropping their import would emit a package that
    /// names a type the translator cannot build.
    fn isExternalModuleNamespace(path: []const []const u8) bool {
        if (path.len != 2) return false;
        if (!std.mem.eql(u8, path[0], "core") and !std.mem.eql(u8, path[0], "std")) return false;
        return std.mem.eql(u8, path[1], "iter") or
            std.mem.eql(u8, path[1], "io") or
            std.mem.eql(u8, path[1], "collections");
    }

    fn isBuildHasherDefaultPath(path: []const []const u8) bool {
        if (path.len != 3 or !std.mem.eql(u8, path[1], "hash") or
            !std.mem.eql(u8, path[2], "BuildHasherDefault"))
        {
            return false;
        }
        return std.mem.eql(u8, path[0], "core") or std.mem.eql(u8, path[0], "std");
    }

    fn isMappedIoTypeImport(path: []const []const u8) bool {
        if (path.len != 3) return false;
        if (!std.mem.eql(u8, path[0], "std") or !std.mem.eql(u8, path[1], "io")) return false;
        inline for (.{ "Error", "ErrorKind", "Cursor", "BufReader" }) |name| {
            if (std.mem.eql(u8, path[2], name)) return true;
        }
        return false;
    }

    /// Whether an external path names Rust's own growable `String`.
    ///
    /// `std::string::String` is a re-export of `alloc::string::String`, so
    /// both spellings name the one type — the same equivalence
    /// `isOwnedStringType` already allows. A crate's own `String` is a
    /// different declaration and is never reached here.
    fn isAllocStringPath(path: []const []const u8) bool {
        if (path.len != 3) return false;
        return (std.mem.eql(u8, path[0], "alloc") or std.mem.eql(u8, path[0], "std")) and
            std.mem.eql(u8, path[1], "string") and
            std.mem.eql(u8, path[2], "String");
    }

    /// `core::collections`, `std::collections`, and `alloc::collections` are
    /// the same Rust module; only `HashMap` and `HashSet` have a lowering.
    fn isCollectionsPath(path: []const []const u8) bool {
        if (path.len != 3) return false;
        if (!std.mem.eql(u8, path[0], "core") and
            !std.mem.eql(u8, path[0], "std") and
            !std.mem.eql(u8, path[0], "alloc")) return false;
        return std.mem.eql(u8, path[1], "collections");
    }

    fn isCollectionsMapPath(path: []const []const u8) bool {
        return isCollectionsPath(path) and std.mem.eql(u8, path[2], "HashMap");
    }

    fn isCollectionsSetPath(path: []const []const u8) bool {
        return isCollectionsPath(path) and std.mem.eql(u8, path[2], "HashSet");
    }

    /// `HashMap`/`HashSet` type paths the lowerer can name, so a `use` of
    /// them emits no declaration of its own.
    fn isCollectionsTypePath(path: []const []const u8) bool {
        return isCollectionsMapPath(path) or isCollectionsSetPath(path);
    }

    fn isCoreFunctionImport(path: []const []const u8) bool {
        if (path.len != 2 and path.len != 3) return false;
        if (!std.mem.eql(u8, path[0], "core") and
            !std.mem.eql(u8, path[0], "std")) return false;
        inline for (comptime std.meta.tags(ir.exprs.CoreFunction)) |function| {
            const name = comptime @tagName(function);
            const separator = comptime std.mem.indexOfScalar(u8, name, '_').?;
            if (std.mem.eql(u8, path[1], name[0..separator]) and
                (path.len == 2 or std.mem.eql(u8, path[2], name[separator + 1 ..])))
            {
                return true;
            }
        }
        return false;
    }

    fn isRuntimeTypeImport(path: []const []const u8) bool {
        if (isBuildHasherDefaultPath(path) or isAllocVecPath(path) or isCowPath(path) or
            isCollectionsTypePath(path) or isMappedIoTypeImport(path)) return true;
        if (path.len < 2 or path.len > 3) return false;
        const is_core = std.mem.eql(u8, path[0], "core") or std.mem.eql(u8, path[0], "std");
        const is_alloc = std.mem.eql(u8, path[0], "alloc") or std.mem.eql(u8, path[0], "std");
        if (is_core and std.mem.eql(u8, path[1], "fmt")) {
            if (path.len == 2) return true;
            inline for (.{ "Formatter", "Error", "Result" }) |name| {
                if (std.mem.eql(u8, path[2], name)) return true;
            }
        }
        if (is_core and path.len == 3) {
            if (std.mem.eql(u8, path[1], "mem") and std.mem.eql(u8, path[2], "MaybeUninit")) return true;
            if (std.mem.eql(u8, path[1], "marker") and std.mem.eql(u8, path[2], "PhantomData")) return true;
        }
        if (is_alloc and path.len == 3) {
            if (std.mem.eql(u8, path[1], "string") and
                (std.mem.eql(u8, path[2], "String") or std.mem.eql(u8, path[2], "FromUtf8Error") or
                    std.mem.eql(u8, path[2], "ToString"))) return true;
            if (std.mem.eql(u8, path[1], "borrow") and std.mem.eql(u8, path[2], "ToOwned")) return true;
        }
        return false;
    }

    /// True when a `use` path is rooted at something this crate does not
    /// declare: neither one of its modules, nor a `self`/`super`/`crate`
    /// relative prefix, nor a declared dependency binding.
    fn useNamesUntranslatedCrate(self: *const Lowerer, use_name: []const u8) bool {
        const separator = std.mem.indexOf(u8, use_name, "::") orelse return false;
        const root = use_name[0..separator];
        if (root.len == 0) return false;
        if (std.mem.eql(u8, root, "self") or std.mem.eql(u8, root, "super") or
            std.mem.eql(u8, root, "crate")) return false;
        for (self.ir.graph.modules.items) |module| {
            if (std.mem.eql(u8, module.name, root)) return false;
        }
        for (self.ir.graph.crates.items) |entry| {
            for (entry.deps) |dep| {
                if (normalizedPackageNameEqual(dep.local_alias, root)) return false;
            }
        }
        return true;
    }

    fn isIoBoundTraitImport(path: []const []const u8) bool {
        if (path.len != 3) return false;
        if (!std.mem.eql(u8, path[0], "std") or !std.mem.eql(u8, path[1], "io")) return false;
        inline for (.{ "Read", "Write", "BufRead" }) |name| {
            if (std.mem.eql(u8, path[2], name)) return true;
        }
        return false;
    }

    /// True when `root` names a crate this manifest declares as a dependency,
    /// however the package is going to be satisfied.
    ///
    /// A runtime-bound dependency is ADMITTED here even though its alias is
    /// reserved, imported and zon-listed nowhere: the runtime binding is what
    /// its names resolve to, so `use renamed::RngCore;`,
    /// `use renamed::SeedableRng;`, `use renamed::impls;` and
    /// `use renamed::Error;` must declare nothing rather than become an
    /// `error.UnsupportedExternalUse`. Answering `false` for it — treating an
    /// erased dependency as absent from the graph — is the one mistake this
    /// arm exists to prevent, so the runtime-bound case is named here rather
    /// than falling out of a bare `return true`.
    ///
    /// The module scan above stays ahead of this one: an unreserved alias may
    /// now be claimed by a real module, and that module must win.
    fn isDeclaredDependencyRoot(self: *const Lowerer, root: []const u8) bool {
        if (root.len == 0) return false;
        if (std.mem.eql(u8, root, "self") or std.mem.eql(u8, root, "super") or
            std.mem.eql(u8, root, "crate") or std.mem.eql(u8, root, "core") or
            std.mem.eql(u8, root, "std") or std.mem.eql(u8, root, "alloc")) return false;
        for (self.ir.graph.modules.items) |module| {
            if (std.mem.eql(u8, module.name, root)) return false;
        }
        for (self.ir.graph.crates.items) |entry| {
            for (entry.deps) |dep| {
                if (!normalizedPackageNameEqual(dep.local_alias, root) and
                    !normalizedPackageNameEqual(dep.extern_name, root)) continue;
                switch (self.dependencyDispositionOf(root) orelse .source_needed) {
                    .runtime_bound, .source_needed, .unavailable => return true,
                }
            }
        }
        return false;
    }

    fn useHasLowerableTarget(
        self: *const Lowerer,
        use_decl: ir.graph.UseDecl,
    ) !bool {
        switch (use_decl.kind) {
            .external => |external| {
                if (use_decl.is_pub_export) return error.UnsupportedExternalUse;
                if (isExternalMarkerPath(external.path)) return false;
                if (isExternalModuleNamespace(external.path)) return false;
                if (isCoreFunctionImport(external.path)) return false;
                if (isIoBoundTraitImport(external.path)) return false;
                // The nominal type lowering adds the r2z import when needed;
                // the lexical use itself does not emit a declaration.
                if (isRuntimeTypeImport(external.path)) {
                    return false;
                }
                // Dependency bindings are emitted by appendCrateDependencyImports.
                if (external.path.len > 0 and self.isDeclaredDependencyRoot(external.path[0])) {
                    return false;
                }
                return error.UnsupportedExternalUse;
            },
            else => {},
        }
        if (use_decl.kind == .glob) return false;
        if (use_decl.local_name.len == 0) return error.MissingUseTarget;
        if (std.mem.eql(u8, use_decl.local_name, "_")) return false;

        const use_entity = self.ir.graph.symbol_table.get(use_decl.id) orelse {
            return error.MissingUseDeclaration;
        };
        if (use_entity.kind != .use_) return error.UseDeclarationMismatch;
        if (use_entity.resolved == null) {
            // A `use` whose root names no module of this crate imports from a
            // dependency. Dependency crates enter the IR as metadata and are
            // never translated, so the import has nothing to declare — the same
            // no-emission policy `std::io` and `core::iter` already take. A
            // macro import such as `use pretty_assertions::assert_eq;` lands
            // here too: the macro itself is expanded by the frontend, so the
            // import is already spent.
            if (self.useNamesUntranslatedCrate(use_entity.name)) return false;
            return error.UnresolvedUseTarget;
        }

        const target = self.ir.graph.symbol_table.get(use_decl.target) orelse {
            return error.MissingUseTarget;
        };
        if (target.name.len == 0) return error.MissingUseTarget;
        if (std.mem.eql(u8, target.name, "_")) return false;
        if (target.kind == .extern_crate) return false;

        if (target.parent) |parent_id| {
            const parent_module = self.moduleForEntity(parent_id) orelse {
                return error.MissingModule;
            };
            if (parent_module.is_extern) return false;
        } else if (target.kind != .module) {
            return error.MissingParentId;
        }

        return true;
    }

    /// Return true for a Rust `#[test]` function.
    ///
    /// Only the attribute decides. A `#[cfg(test)] mod tests` module is full of
    /// helpers no test ever calls, and `fn test_hash` is one of them: reading
    /// its name as the attribute turns a generic helper into a Zig `test`
    /// block, which drops its signature and leaves every call to it naming a
    /// declaration the package never declared.
    fn isTestEntity(ent: ir.spine.Entity) bool {
        for (ent.attributes) |attribute| {
            if (std.mem.eql(u8, attribute.name, "test")) return true;
        }
        return false;
    }

    fn lowerEntityDecl(
        self: *Lowerer,
        entity_id: ir.spine.EntityId,
        ent: ir.spine.Entity,
        current_mod_id: ?ir.spine.EntityId,
    ) !?ast.Decl {
        const previous_module_id = self.current_module_id;
        self.current_module_id = current_mod_id;
        defer self.current_module_id = previous_module_id;
        if (try self.entityBelongsToExternalModule(entity_id)) return null;
        const is_pub = switch (ent.visibility) {
            .public, .crate_restricted, .super_restricted, .in_path => true,
            // Rust `private` means "this module and its descendants". Zig files
            // are hard module boundaries, so a descendant Rust module becomes a
            // sibling file that cannot see a non-`pub` item.
            .private => self.privateItemIsPublished(entity_id),
        };
        if (ent.kind == .extern_crate) {
            return switch (ent.visibility) {
                .private => null,
                else => error.UnsupportedEntityKind,
            };
        }
        if (ent.kind == .field or ent.kind == .variant or ent.kind == .method_ref) return null;

        if (entity_id >= self.ir.bodies.bodies.len) {
            return error.MissingBodyId;
        }
        const body_kind = self.ir.bodies.bodies[entity_id];

        switch (ent.kind) {
            .struct_ => {
                const previous_struct_id = self.current_struct_id;
                self.current_struct_id = entity_id;
                defer self.current_struct_id = previous_struct_id;
                var fields_list: std.ArrayListUnmanaged(ast.StructField) = .empty;
                var inner_decls: std.ArrayListUnmanaged(ast.Decl) = .empty;
                var generic_params_list: std.ArrayListUnmanaged(ast.GenericParam) = .empty;

                switch (body_kind) {
                    .struct_ => |sb| {
                        if (sb.generic_params.len > 0) {
                            for (sb.generic_params) |gp| {
                                try generic_params_list.append(self.alloc, .{
                                    .name = try self.alloc.dupe(u8, gp),
                                    .is_comptime = true,
                                    .ty = null,
                                });
                            }
                        } else {
                            for (sb.fields) |f| {
                                try self.collectGenericTypeParams(f.ty, &generic_params_list);
                            }
                        }

                        for (sb.fields) |f| {
                            const f_ty = try self.lowerType(f.ty);
                            try fields_list.append(self.alloc, .{
                                .name = try self.alloc.dupe(u8, self.structFieldName(entity_id, f.name)),
                                .documentation = try self.alloc.dupe(u8, f.documentation),
                                .ty = f_ty,
                                .is_pub = switch (f.visibility) {
                                    .public, .crate_restricted, .super_restricted, .in_path => true,
                                    .private => !self.current_file_is_root,
                                },
                            });
                        }

                        // Inherent methods from StructBody
                        for (sb.methods) |m| {
                            const m_decl = try self.lowerStructMethod(
                                m,
                                ent.name,
                                generic_params_list.items,
                                entity_id,
                            );
                            try inner_decls.append(self.alloc, ast.Decl{ .fn_decl = m_decl });
                        }
                    },
                    else => return error.DeclarationBodyMismatch,
                }

                // Append any hoisted methods from impl blocks
                if (self.hoisted_by_id.get(entity_id)) |hoisted| {
                    for (hoisted.items) |d| {
                        try inner_decls.append(self.alloc, d);
                    }
                }

                const fields = try fields_list.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(fields);
                const decls = try inner_decls.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(decls);
                const generic_params = try generic_params_list.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(generic_params);
                // A struct the source declared with no members is still a
                // complete declaration, and it is a NOMINAL one: `struct Unit;`,
                // `struct Marker {}` and `struct Pair();` are three different
                // types that each answer to their own name and are each built
                // `.{}`. An empty `struct_decl` cannot carry that — `ast`
                // refuses a container with nothing in it, because a struct
                // whose body translated to nothing is a translation loss and
                // that refusal is right. The fix is the spelling a populated
                // struct already emits (`const X = struct { ... };`) with the
                // member list empty: same nominal name, same constructor
                // spelling, same visibility, same docs, and nothing invented
                // to fill it. A generic one keeps its factory form, because a
                // use site calls `X(T)` rather than naming `X` as a type, so a
                // `const` would break every reference to it.
                if (fields.len == 0 and decls.len == 0) {
                    const unit = ast.Type{ .anon_struct = .{} };
                    if (generic_params.len == 0) {
                        return ast.Decl{ .const_decl = .{
                            .name = try self.alloc.dupe(u8, ent.name),
                            .documentation = try self.entityDocumentation(ent),
                            .is_pub = is_pub,
                            .ty = null,
                            .init = .{ .type_value = unit },
                        } };
                    }
                    return ast.Decl{ .fn_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .params = &.{},
                        .ret_type = ast.Type{ .named = "type" },
                        .body = .{ .expr = try self.allocExpr(.{ .type_value = unit }) },
                        .generic_params = generic_params,
                    } };
                }

                return ast.Decl{
                    .struct_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .fields = fields,
                        .decls = decls,
                        .generic_params = generic_params,
                    },
                };
            },
            .enum_ => {
                var variants_list: std.ArrayListUnmanaged(ast.EnumVariant) = .empty;
                var union_fields: std.ArrayListUnmanaged(ast.UnionField) = .empty;
                var inner_decls: std.ArrayListUnmanaged(ast.Decl) = .empty;
                var is_data_carrying = false;

                switch (body_kind) {
                    .enum_ => |eb| {
                        if (eb.kind == .data) is_data_carrying = true;
                        for (eb.variants) |v| {
                            if (is_data_carrying) {
                                var v_ty: ast.Type = ast.Type{ .void_type = {} };
                                switch (v.fields) {
                                    .none => {
                                        v_ty = ast.Type{ .void_type = {} };
                                    },
                                    .tuple => |tup| {
                                        if (tup.len == 1) {
                                            v_ty = try self.lowerType(tup[0]);
                                        } else if (tup.len > 1) {
                                            v_ty = try self.lowerType(ir.types.Type{ .tuple = tup });
                                        }
                                    },
                                    .named => |flds| {
                                        var sf_list: std.ArrayListUnmanaged(ast.StructField) = .empty;
                                        for (flds) |f| {
                                            const f_ty = try self.lowerType(f.ty);
                                            try sf_list.append(self.alloc, .{
                                                .name = try self.alloc.dupe(u8, f.name),
                                                .documentation = try self.alloc.dupe(u8, f.documentation),
                                                .ty = f_ty,
                                            });
                                        }
                                        v_ty = ast.Type{
                                            .anon_struct = .{
                                                .fields = try sf_list.toOwnedSlice(self.alloc),
                                            },
                                        };
                                    },
                                }
                                try union_fields.append(self.alloc, .{
                                    .name = try self.alloc.dupe(u8, v.name),
                                    .documentation = try self.alloc.dupe(u8, v.documentation),
                                    .ty = v_ty,
                                });
                            } else {
                                try variants_list.append(self.alloc, .{
                                    .name = try self.alloc.dupe(u8, v.name),
                                    .documentation = try self.alloc.dupe(u8, v.documentation),
                                    .value = null,
                                });
                            }
                        }
                    },
                    else => return error.DeclarationBodyMismatch,
                }

                if (self.hoisted_by_id.get(entity_id)) |hoisted| {
                    for (hoisted.items) |d| {
                        try inner_decls.append(self.alloc, d);
                    }
                }

                if (is_data_carrying) {
                    const fields = try union_fields.toOwnedSlice(self.alloc);
                    errdefer self.alloc.free(fields);
                    const decls = try inner_decls.toOwnedSlice(self.alloc);
                    errdefer self.alloc.free(decls);

                    return ast.Decl{
                        .union_decl = .{
                            .name = try self.alloc.dupe(u8, ent.name),
                            .documentation = try self.entityDocumentation(ent),
                            .is_pub = is_pub,
                            .tag_type = ast.Type{ .named = "enum" },
                            .fields = fields,
                            .decls = decls,
                        },
                    };
                }

                const variants = try variants_list.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(variants);
                const decls = try inner_decls.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(decls);

                return ast.Decl{
                    .enum_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .variants = variants,
                        .decls = decls,
                    },
                };
            },
            .fn_ => {
                const fn_d = try self.lowerFnEntity(entity_id, ent);
                return ast.Decl{ .fn_decl = fn_d };
            },
            .const_ => {
                var ty: ?ast.Type = null;
                var init_expr: ?ast.Expr = null;

                switch (body_kind) {
                    .const_ => |cb| {
                        ty = try self.lowerType(cb.ty);
                        init_expr = try self.lowerExpr(cb.init);
                    },
                    else => return error.DeclarationBodyMismatch,
                }

                return ast.Decl{
                    .const_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .ty = ty,
                        .init = init_expr orelse return error.EmptyDeclaration,
                    },
                };
            },
            .static_ => {
                var ty: ?ast.Type = null;
                var init_expr: ?ast.Expr = null;

                switch (body_kind) {
                    .const_ => |cb| {
                        ty = try self.lowerType(cb.ty);
                        init_expr = try self.lowerExpr(cb.init);
                    },
                    else => return error.DeclarationBodyMismatch,
                }

                const emitted_name = self.local_static_names.get(entity_id) orelse ent.name;
                // Static bodies do not encode binding mutability. Keep writable
                // storage for `static mut`; shared borrows retain const pointees.
                return ast.Decl{
                    .var_decl = .{
                        .name = try self.alloc.dupe(u8, emitted_name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .is_mut = true,
                        .ty = ty,
                        .init = init_expr orelse return error.EmptyDeclaration,
                    },
                };
            },
            .type_alias => {
                const alias = switch (body_kind) {
                    .type_alias => |tab| tab,
                    else => return error.DeclarationBodyMismatch,
                };
                const target_ty = try self.lowerType(alias.target);

                const init_expr: ast.Expr = switch (target_ty) {
                    .named => |n| ast.Expr{ .ident = try self.alloc.dupe(u8, n) },
                    .generic => |g| ast.Expr{
                        .call = .{
                            .callee = try self.allocExpr(ast.Expr{
                                .ident = try self.alloc.dupe(u8, g.name),
                            }),
                            .generic_args = g.params,
                            .args = &.{},
                        },
                    },
                    .prim => |p| ast.Expr{ .ident = try self.alloc.dupe(u8, @tagName(p)) },
                    .projected => |projection| blk: {
                        const receiver_name = switch (projection.receiver.*) {
                            .named => |name| name,
                            else => return error.UnsupportedTypeAliasTarget,
                        };
                        const args = try self.alloc.alloc(ast.Expr, 1);
                        args[0] = .{ .ident = try self.alloc.dupe(u8, receiver_name) };
                        const call = try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{
                                .ident = try self.alloc.dupe(u8, projection.descriptor),
                            }),
                            .args = args,
                        } });
                        break :blk .{ .field_access = .{
                            .target = call,
                            .field_name = try self.alloc.dupe(u8, projection.member),
                        } };
                    },
                    else => ast.Expr{ .type_value = target_ty },
                };

                // `pub type X<K, V> = ...` binds K and V inside its own
                // target, so the Zig form has to be a comptime type
                // function. A `const` cannot mention them: the names would
                // dangle and the generated package would not compile.
                if (alias.generic_params.len != 0) {
                    const generic_params = try self.alloc.alloc(ast.GenericParam, alias.generic_params.len);
                    for (alias.generic_params, 0..) |param_name, i| {
                        generic_params[i] = .{
                            .name = try self.alloc.dupe(u8, param_name),
                            .is_comptime = true,
                            .ty = ast.Type{ .named = "type" },
                        };
                    }
                    return ast.Decl{ .fn_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .params = &.{},
                        .ret_type = ast.Type{ .named = "type" },
                        .body = .{ .expr = try self.allocExpr(init_expr) },
                        .generic_params = generic_params,
                    } };
                }
                return ast.Decl{
                    .const_decl = .{
                        .name = try self.alloc.dupe(u8, ent.name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = is_pub,
                        .ty = null,
                        .init = init_expr,
                    },
                };
            },
            .use_ => {
                const use_decl = self.ir.graph.useById(entity_id) orelse {
                    return error.MissingUseDeclaration;
                };
                if (!use_decl.is_pub_export) return null;
                if (!(try self.useHasLowerableTarget(use_decl))) return null;
                if (use_decl.kind == .glob) return null;

                const target_entity = self.ir.graph.symbol_table.get(use_decl.target) orelse {
                    return error.MissingUseTarget;
                };
                var init_expr: ?ast.Expr = null;

                if (target_entity.parent) |parent_id| {
                    const cur_mod_id = current_mod_id orelse 0;
                    if (parent_id != cur_mod_id and parent_id != 0) {
                        const parent_module = self.moduleForEntity(parent_id) orelse {
                            return error.MissingModule;
                        };
                        if (parent_module.name.len == 0) return error.MissingModule;
                        const target_name = try self.alloc.dupe(u8, parent_module.name);
                        errdefer self.alloc.free(target_name);
                        const target = try self.allocExpr(ast.Expr{ .ident = target_name });
                        errdefer self.alloc.destroy(target);
                        const field_name = try self.alloc.dupe(u8, target_entity.name);
                        errdefer self.alloc.free(field_name);
                        init_expr = ast.Expr{
                            .field_access = .{
                                .target = target,
                                .field_name = field_name,
                            },
                        };
                    }
                }

                if (init_expr == null) {
                    const cur_mod_id = current_mod_id orelse 0;
                    const target_parent = target_entity.parent orelse 0;
                    if (target_parent == cur_mod_id and
                        std.mem.eql(u8, use_decl.local_name, target_entity.name))
                    {
                        return null;
                    }
                    init_expr = ast.Expr{ .ident = try self.alloc.dupe(u8, target_entity.name) };
                }

                return ast.Decl{
                    .const_decl = .{
                        .name = try self.alloc.dupe(u8, use_decl.local_name),
                        .documentation = try self.entityDocumentation(ent),
                        .is_pub = true,
                        .ty = null,
                        .init = init_expr orelse return error.EmptyDeclaration,
                    },
                };
            },
            .impl_ => {
                // Impl items are hoisted into their target structs/enums; skip at module root.
                return null;
            },
            .trait_ => {
                // A trait has no Zig counterpart. Its methods reach the output
                // through the impl blocks, which `collectHoistedMethods` hoists
                // onto the implementing type, and its bounds are erased at
                // emit. The declaration itself therefore contributes nothing.
                return null;
            },
            else => return error.UnsupportedEntityKind,
        }
    }

    fn appendFunctionGenericParams(
        self: *Lowerer,
        generic_params: []const []const u8,
        params: *std.ArrayListUnmanaged(ast.FnParam),
    ) !void {
        for (generic_params) |generic_name| {
            try params.append(self.alloc, .{
                .name = try self.alloc.dupe(u8, generic_name),
                .ty = .{ .named = "type" },
                .is_comptime = true,
            });
        }
    }
    fn isConstU8SliceValue(ty: ir.types.Type) bool {
        return switch (ty) {
            .slice => |slice| {
                if (!slice.const_) return false;
                return switch (slice.elem) {
                    .prim => |primitive| primitive == .u8,
                    else => false,
                };
            },
            .reference => |reference| if (reference.mut) false else switch (reference.pointee) {
                .slice => |slice| {
                    if (!slice.const_) return false;
                    return switch (slice.elem) {
                        .prim => |primitive| primitive == .u8,
                        else => false,
                    };
                },
                else => false,
            },
            else => false,
        };
    }

    fn isPlainU8VecType(ty: ir.types.Type) bool {
        return switch (ty) {
            .external_nominal => |external| blk: {
                if (!isAllocVecPath(external.path)) break :blk false;
                if (external.args.len != 1) break :blk false;
                break :blk switch (external.args[0]) {
                    .prim => |primitive| primitive == .u8,
                    else => false,
                };
            },
            else => false,
        };
    }

    fn isConstU8SliceType(self: *Lowerer, type_id: ir.exprs.TypeRef) bool {
        const ty = self.typeById(type_id) catch return false;
        return switch (ty) {
            .slice => |slice| {
                if (!slice.const_) return false;
                return switch (slice.elem) {
                    .prim => |primitive| primitive == .u8,
                    else => false,
                };
            },
            else => false,
        };
    }

    fn ownedCollectionCapturePath(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        capture_name: []const u8,
    ) ?ir.exprs.NodeId {
        if (expr_id >= self.ir.bodies.exprs.len) return null;
        return switch (self.ir.bodies.exprs[expr_id].kind) {
            .path => |path| {
                if (path.generic_args.len != 0) return null;
                const entity = self.ir.graph.symbol_table.get(path.def) orelse return null;
                return if (std.mem.eql(u8, entity.name, capture_name)) expr_id else null;
            },
            .method_call => |cloned| {
                if (cloned.args.len != 0) return null;
                const cloned_entity = self.ir.graph.symbol_table.get(cloned.method) orelse {
                    return null;
                };
                if (!std.mem.eql(u8, cloned_entity.name, "cloned")) return null;
                if (cloned.receiver >= self.ir.bodies.exprs.len) return null;
                const iter = switch (self.ir.bodies.exprs[cloned.receiver].kind) {
                    .method_call => |value| value,
                    else => return null,
                };
                if (iter.args.len != 0) return null;
                const iter_entity = self.ir.graph.symbol_table.get(iter.method) orelse {
                    return null;
                };
                if (!std.mem.eql(u8, iter_entity.name, "iter")) return null;
                return self.ownedCollectionCapturePath(iter.receiver, capture_name);
            },
            else => null,
        };
    }

    fn matchOwnedTemporary(
        self: *Lowerer,
        arg_id: ir.exprs.NodeId,
        expected_type: ir.types.Type,
    ) anyerror!?OwnedTemporaryPlan {
        if (arg_id >= self.ir.bodies.exprs.len) return null;
        const borrowed = switch (self.ir.bodies.exprs[arg_id].kind) {
            .unary => |unary| unary,
            else => return null,
        };
        if (borrowed.op != .ref) return null;
        const producer_expr = borrowed.operand;
        if (producer_expr >= self.ir.bodies.exprs.len) return null;
        var producer_call_id = producer_expr;
        switch (self.ir.bodies.exprs[producer_expr].kind) {
            .call => {},
            .try_ => |try_expr| {
                if (try_expr.inner >= self.ir.bodies.exprs.len) return null;
                producer_call_id = try_expr.inner;
            },
            else => return null,
        }
        if (self.ir.bodies.exprs[producer_call_id].kind != .call) return null;
        const producer_call = self.ir.bodies.exprs[producer_call_id].kind.call;
        const producer_def = switch (producer_call.call_kind) {
            .free => |def| def,
            .associated => |def| def,
            .constructor => |def| def,
        };
        if (!self.callPassesAllocator(producer_def)) return null;
        const return_type = (try self.exprType(producer_call_id)) orelse return null;
        if (!isPlainU8VecType(return_type)) return null;
        if (!isConstU8SliceValue(expected_type)) return null;
        return .{ .return_type = return_type };
    }

    fn appendIteratorClosurePatternNames(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        names: *std.ArrayListUnmanaged([]const u8),
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .binding, .wildcard => try names.append(self.alloc, try self.patternName(pat_id)),
            .reference => |reference| try self.appendIteratorClosurePatternNames(reference.inner, names),
            .tuple => |tuple| {
                if (tuple.rest) return error.UnsupportedIteratorAdapter;
                for (tuple.elements) |element| {
                    try self.appendIteratorClosurePatternNames(element, names);
                }
            },
            else => return error.UnsupportedIteratorAdapter,
        }
    }

    fn prepareIteratorClosureParams(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
    ) anyerror!void {
        if (closure.params.len != 1) return error.UnsupportedIteratorAdapter;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer names.deinit(self.alloc);
        try self.appendIteratorClosurePatternNames(closure.params[0], &names);
    }

    fn lowerIteratorClosureBody(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
    ) anyerror!ast.Expr {
        try self.prepareIteratorClosureParams(closure);
        const tail = closure.body.tail orelse return error.UnsupportedIteratorAdapter;
        if (closure.body.statements.len == 0) return self.lowerExpr(tail);
        return .{ .block = try self.lowerBlock(closure.body) };
    }
    fn lowerIteratorClosureBodyWithSnapshots(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
    ) anyerror!ast.Expr {
        const previous = try self.beginIteratorClosureSnapshots(closure);
        if (previous) |saved| {
            var saved_map = saved;
            defer self.endIteratorClosureSnapshots(&saved_map);
            return self.lowerIteratorClosureBody(closure);
        }
        return self.lowerIteratorClosureBody(closure);
    }

    fn iteratorRangeTail(
        self: *const Lowerer,
        closure: ir.exprs.ClosureExpr,
    ) ?IteratorRangeTail {
        const tail = closure.body.tail orelse return null;
        if (tail >= self.ir.bodies.exprs.len) return null;
        if (self.ir.bodies.exprs[tail].kind != .range) return null;
        return .{ .id = tail };
    }

    fn iteratorRangeEndpointType(
        self: *Lowerer,
        node: ir.exprs.NodeId,
    ) anyerror!ir.types.Type {
        const known = self.concreteExprType(node) orelse
            (try self.exprType(node)) orelse return error.MissingExpressionType;
        return integerOperandType(known) orelse error.UnsupportedIteratorAdapter;
    }

    fn lowerIteratorRange(
        self: *Lowerer,
        node: ir.exprs.NodeId,
    ) anyerror!LoweredIteratorRange {
        if (node >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        const range = switch (self.ir.bodies.exprs[node].kind) {
            .range => |value| value,
            else => return error.UnsupportedIteratorAdapter,
        };
        const end_node = range.end orelse return error.UnsupportedIteratorAdapter;
        const start_type = try self.iteratorRangeEndpointType(range.start);
        const end_type = try self.iteratorRangeEndpointType(end_node);
        if (!typeEquals(start_type, end_type)) return error.UnsupportedIteratorAdapter;
        return .{
            .start = try self.lowerExpr(range.start),
            .end = try self.lowerExpr(end_node),
            .item_type = try self.lowerType(start_type),
            .inclusive = range.inclusive,
        };
    }

    fn appendIteratorRangeSetup(
        self: *Lowerer,
        range: LoweredIteratorRange,
        direction: IteratorRangeDirection,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!IteratorRangeLoop {
        const start_name = try self.iteratorTemporaryName("__r2z_range_start");
        const end_name = try self.iteratorTemporaryName("__r2z_range_end");
        const cursor_name = try self.iteratorTemporaryName("__r2z_range_cursor");
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = start_name,
            .ty = range.item_type,
            .init = range.start,
        } });
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = end_name,
            .ty = range.item_type,
            .init = range.end,
        } });
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = cursor_name,
            .ty = range.item_type,
            .init = .{ .ident = if (direction == .forward) start_name else end_name },
            .is_mut = true,
        } });
        const done_name = if (range.inclusive) blk: {
            const name = try self.iteratorTemporaryName("__r2z_range_done");
            try statements.append(self.alloc, .{ .let_stmt = .{
                .name = name,
                .ty = .{ .prim = .bool },
                .init = .{ .lit = .{ .bool_lit = false } },
                .is_mut = true,
            } });
            break :blk @as(?[]const u8, name);
        } else null;
        const item: ast.Expr = .{ .ident = cursor_name };
        return .{
            .direction = direction,
            .inclusive = range.inclusive,
            .start_name = start_name,
            .end_name = end_name,
            .cursor_name = cursor_name,
            .done_name = done_name,
            .item = item,
        };
    }

    fn appendIteratorRangeAssignment(
        self: *Lowerer,
        loop: IteratorRangeLoop,
        op: ast.AssignOp,
    ) anyerror!ast.Expr {
        const assignment = try self.alloc.alloc(ast.Stmt, 1);
        assignment[0] = .{ .assign = .{
            .target = .{ .ident = loop.cursor_name },
            .val = .{ .lit = .{ .int = 1 } },
            .op = op,
        } };
        return .{ .block = .{ .stmts = assignment } };
    }

    fn appendIteratorRangeLoop(
        self: *Lowerer,
        loop: IteratorRangeLoop,
        body: []const ast.Stmt,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        label: ?[]const u8,
    ) anyerror!void {
        const endpoint = if (loop.direction == .forward)
            loop.end_name
        else
            loop.start_name;
        const comparison = if (loop.direction == .forward)
            if (loop.inclusive) ast.BinOpKind.less_than_equal else ast.BinOpKind.less_than
        else if (loop.inclusive) ast.BinOpKind.greater_than_equal else ast.BinOpKind.greater_than;
        const comparison_condition: ast.Expr = .{ .bin_op = .{
            .op = comparison,
            .lhs = try self.allocExpr(.{ .ident = loop.cursor_name }),
            .rhs = try self.allocExpr(.{ .ident = endpoint }),
        } };
        const condition: ast.Expr = if (loop.done_name) |done_name| .{ .bin_op = .{
            .op = .bool_and,
            .lhs = try self.allocExpr(comparison_condition),
            .rhs = try self.allocExpr(.{ .unary_op = .{
                .op = .bool_not,
                .operand = try self.allocExpr(.{ .ident = done_name }),
            } }),
        } } else comparison_condition;
        const decrement_before_body = loop.direction == .reverse and !loop.inclusive;
        const loop_body: []const ast.Stmt = if (decrement_before_body or loop.done_name != null) blk: {
            const before_count: usize = @intFromBool(decrement_before_body);
            const completion_count: usize = @intFromBool(loop.done_name != null);
            const body_with_prefix = try self.alloc.alloc(ast.Stmt, body.len + before_count + completion_count);
            var body_index: usize = 0;
            if (decrement_before_body) {
                body_with_prefix[body_index] = .{ .assign = .{
                    .target = .{ .ident = loop.cursor_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .sub_assign,
                } };
                body_index += 1;
            }
            if (loop.done_name) |done_name| {
                body_with_prefix[body_index] = .{ .assign = .{
                    .target = .{ .ident = done_name },
                    .val = .{ .bin_op = .{
                        .op = .equal,
                        .lhs = try self.allocExpr(.{ .ident = loop.cursor_name }),
                        .rhs = try self.allocExpr(.{ .ident = endpoint }),
                    } },
                } };
                body_index += 1;
            }
            @memcpy(body_with_prefix[body_index..], body);
            break :blk body_with_prefix;
        } else try self.alloc.dupe(ast.Stmt, body);
        const continue_expr: ?*const ast.Expr = if (decrement_before_body)
            null
        else blk: {
            const advance_op: ast.AssignOp = if (loop.direction == .forward) .add_assign else .sub_assign;
            if (loop.done_name) |done_name| {
                const advance = try self.appendIteratorRangeAssignment(loop, advance_op);
                break :blk try self.allocExpr(.{ .if_expr = .{
                    .cond = try self.allocExpr(.{ .unary_op = .{
                        .op = .bool_not,
                        .operand = try self.allocExpr(.{ .ident = done_name }),
                    } }),
                    .then_body = try self.allocExpr(advance),
                    .else_body = try self.allocExpr(.{ .unit = {} }),
                } });
            }
            break :blk try self.allocExpr(
                try self.appendIteratorRangeAssignment(loop, advance_op),
            );
        };
        try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .while_expr = .{
            .cond = try self.allocExpr(condition),
            .continue_expr = continue_expr,
            .body = .{ .stmts = loop_body },
            .label = label,
        } }) });
    }

    const IteratorCaptureFrame = struct {
        overrides: std.StringHashMapUnmanaged([]const u8),
        moves: std.ArrayListUnmanaged(OwnedCaptureMove) = .empty,
        previous_move: ?OwnedCaptureMoveSet = null,
    };

    fn appendCaptureSnapshot(
        self: *Lowerer,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        snapshot_name: []const u8,
        capture: ir.exprs.Capture,
        source_name: []const u8,
        payload_type: ir.types.Type,
    ) anyerror!void {
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = snapshot_name,
            .init = try self.ownedTransferCall(.{
                .source_name = capture.name,
                .capture_name = source_name,
                .alias_name = source_name,
                .payload_type = payload_type,
            }),
            .is_mut = true,
        } });
        try statements.append(
            self.alloc,
            try self.ownerReleaseStatement(snapshot_name, ownerReleasesElements(payload_type)),
        );
    }
    fn beginIteratorClosureSnapshots(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
    ) anyerror!?IteratorCaptureFrame {
        const prelude = self.current_iterator_capture_prelude orelse return null;
        const previous = self.active_closure_capture_overrides;
        self.active_closure_capture_overrides = .empty;
        var frame: IteratorCaptureFrame = .{ .overrides = previous };
        errdefer {
            for (frame.moves.items) |*entry| entry.sites.deinit(self.alloc);
            frame.moves.deinit(self.alloc);
            self.active_closure_capture_overrides.deinit(self.alloc);
            self.active_closure_capture_overrides = previous;
        }
        var previous_iterator = previous.iterator();
        while (previous_iterator.next()) |entry| {
            try self.active_closure_capture_overrides.put(
                self.alloc,
                entry.key_ptr.*,
                entry.value_ptr.*,
            );
        }
        for (closure.captures) |capture| {
            if (capture.mode != .by_value) continue;
            const source_name = self.active_closure_capture_overrides.get(capture.name) orelse
                self.currentClosureBindingName(capture.name);
            const snapshot_name = try std.fmt.allocPrint(
                self.alloc,
                "__r2z_capture_iter_{d}_{s}",
                .{ self.next_iterator_capture_id, capture.name },
            );
            self.next_iterator_capture_id +%= 1;
            const resolved_type = try self.closureCapturePayloadType(capture, source_name);
            if (ownedRuntimeContainerType(resolved_type)) {
                try self.appendCaptureSnapshot(
                    prelude,
                    snapshot_name,
                    capture,
                    source_name,
                    resolved_type,
                );
                var moves = try self.collectOwnedCaptureMovesOverBlock(.{
                    .source_name = capture.name,
                    .capture_name = snapshot_name,
                    .alias_name = snapshot_name,
                    .payload_type = resolved_type,
                }, closure.body);
                errdefer moves.sites.deinit(self.alloc);
                try frame.moves.append(self.alloc, moves);
            } else {
                try prelude.append(self.alloc, .{ .let_stmt = .{
                    .name = snapshot_name,
                    .init = .{ .ident = try self.alloc.dupe(u8, source_name) },
                    .is_mut = closure.trait == .fn_mut,
                } });
            }
            try self.active_closure_capture_overrides.put(
                self.alloc,
                capture.name,
                snapshot_name,
            );
        }
        frame.previous_move = self.active_owned_capture_move;
        self.active_owned_capture_move = .{ .entries = frame.moves.items };
        return frame;
    }

    fn endIteratorClosureSnapshots(
        self: *Lowerer,
        frame: *IteratorCaptureFrame,
    ) void {
        self.active_owned_capture_move = frame.previous_move;
        for (frame.moves.items) |*entry| entry.sites.deinit(self.alloc);
        frame.moves.deinit(self.alloc);
        self.active_closure_capture_overrides.deinit(self.alloc);
        self.active_closure_capture_overrides = frame.overrides;
        frame.* = undefined;
    }

    fn lowerIteratorClosureRangeTail(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
        tail: IteratorRangeTail,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!LoweredIteratorRange {
        if (closure.body.labelled != null) return error.UnsupportedIteratorAdapter;
        try self.prepareIteratorClosureParams(closure);
        const previous = try self.beginIteratorClosureSnapshots(closure);
        if (previous) |saved| {
            var saved_map = saved;
            defer self.endIteratorClosureSnapshots(&saved_map);
            return self.lowerIteratorClosureRangeTailBody(closure, tail, statements);
        }
        return self.lowerIteratorClosureRangeTailBody(closure, tail, statements);
    }

    fn lowerIteratorClosureRangeTailBody(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
        tail: IteratorRangeTail,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!LoweredIteratorRange {
        var prelude = closure.body;
        prelude.tail = null;
        const lowered_prelude = try self.lowerBlock(prelude);
        try statements.appendSlice(self.alloc, lowered_prelude.stmts);
        return self.lowerIteratorRange(tail.id);
    }

    fn iteratorTemporaryName(
        self: *Lowerer,
        base_name: []const u8,
    ) ![]const u8 {
        var reserved: std.ArrayListUnmanaged([]const u8) = .empty;
        defer reserved.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            try reserved.append(self.alloc, entity.name);
        }
        try self.appendParameterNames(&reserved);
        try self.appendDeclaredLabelNames(&reserved);
        if (self.current_local_binding_names) |names| {
            var used = names.used_names.keyIterator();
            while (used.next()) |name| try reserved.append(self.alloc, name.*);
            const generated = try self.collectorBindingName(base_name, reserved.items);
            try names.used_names.put(self.alloc, generated, {});
            return generated;
        }
        return self.collectorBindingName(base_name, reserved.items);
    }

    /// Every label the source names, appended to the names a generated
    /// identifier has to dodge.
    ///
    /// A label occupies the same namespace a binding does. A program that
    /// spells `'__r2z_match_block: loop { .. }` has claimed the spelling as
    /// firmly as `let __r2z_match_block = ..` does, and a guarded match that
    /// minted the same one emitted two blocks carrying one label, which Zig
    /// refuses as a redefinition.
    fn appendDeclaredLabelNames(
        self: *const Lowerer,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        for (self.ir.bodies.exprs) |expr| {
            switch (expr.kind) {
                // A loop's label is recorded on the block its body is.
                .block => |block| {
                    if (block.labelled) |label| try reserved.append(self.alloc, label);
                },
                .break_ => |break_expr| {
                    if (break_expr.label) |label| try reserved.append(self.alloc, label);
                },
                .continue_ => |continue_expr| {
                    if (continue_expr.label) |label| try reserved.append(self.alloc, label);
                },
                else => {},
            }
        }
    }

    fn iteratorSourceByReference(self: *Lowerer, source_id: ir.exprs.NodeId) !bool {
        if (source_id >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        const source = self.ir.bodies.exprs[source_id];
        if (source.kind != .method_call) return false;
        const method = self.ir.graph.symbol_table.get(source.kind.method_call.method) orelse
            return error.MissingDefinition;
        return std.mem.eql(u8, method.name, "iter") or std.mem.eql(u8, method.name, "iter_mut");
    }

    fn lowerIteratorSource(
        self: *Lowerer,
        source_id: ir.exprs.NodeId,
    ) anyerror!ast.Expr {
        return self.lowerForInput(source_id, try self.iteratorSourceByReference(source_id));
    }

    /// Bind one item to a local so an expression used more than once is
    /// lowered once. `ty` names the type when the surrounding expression has
    /// already worked it out: a `Result` collect unwraps its item through the
    /// collection's own methods, and an anonymous `.{ .Ok = v }` has no peer
    /// type to find them with.
    fn materializeIteratorItem(
        self: *Lowerer,
        value: ast.Expr,
        mutable: bool,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        ty: ?ast.Type,
    ) anyerror!ast.Expr {
        const name = try self.iteratorTemporaryName("__r2z_item_value");
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = name,
            .ty = ty,
            .is_mut = mutable,
            .init = value,
        } });
        return .{ .ident = name };
    }
    fn appendIteratorClosureBindings(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        value: ast.Expr,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .wildcard => {},
            .binding => |binding| {
                if (binding.name.len == 0) return error.MissingBindingName;
                const binding_value = if (binding.mode == .mut_ref)
                    try self.materializeIteratorItem(value, true, statements, null)
                else
                    value;
                try statements.append(self.alloc, .{ .let_stmt = .{
                    .name = try self.patternName(pat_id),
                    .is_mut = binding.mutable,
                    .init = if (binding.mode == .value) binding_value else .{ .unary_op = .{
                        .op = .addr_of,
                        .operand = try self.allocExpr(binding_value),
                    } },
                } });
            },
            .reference => |reference| {
                try self.appendIteratorClosureBindings(reference.inner, .{ .unary_op = .{
                    .op = .deref,
                    .operand = try self.allocExpr(value),
                } }, statements);
            },
            .tuple => |tuple| {
                if (tuple.rest) return error.UnsupportedIteratorAdapter;
                const tuple_name = try self.iteratorTemporaryName("__r2z_tuple");
                try statements.append(self.alloc, .{ .let_stmt = .{
                    .name = tuple_name,
                    .init = value,
                } });
                for (tuple.elements, 0..) |element, index| {
                    const args = try self.alloc.alloc(ast.Expr, 2);
                    args[0] = .{ .ident = tuple_name };
                    args[1] = .{ .lit = .{ .int = @intCast(index) } };
                    try self.appendIteratorClosureBindings(
                        element,
                        .{ .builtin = .{ .name = "index", .args = args } },
                        statements,
                    );
                }
            },
            else => return error.UnsupportedIteratorAdapter,
        }
    }

    /// Whether a `for` input is a runtime iterator. Zig's `for` walks a
    /// range, array, slice, tuple or vector, and every `r2z` iterator is a
    /// struct, so such an input has to be pulled with `next` instead. A `for`
    /// input is a statement position, so a range node keeps the bare Zig range
    /// form and is never an iterator value.
    fn isRuntimeIteratorInput(self: *Lowerer, node: ir.exprs.NodeId) anyerror!bool {
        if (node >= self.ir.bodies.exprs.len) return false;
        if (self.ir.bodies.exprs[node].kind == .range) return false;
        const ty = try self.exprType(node) orelse return false;
        return isRuntimeIteratorCarrier(peelReceiverType(ty));
    }

    /// Hoist one runtime-iterator `for` input and bind its item. `capture` is
    /// the `while` capture name when this input drives the loop; without one
    /// the item is pulled from the top of the body instead, and an input that
    /// runs dry breaks the loop — which is how a multi-input Zig `for` stops
    /// at its shortest input.
    fn appendRuntimeIteratorInput(
        self: *Lowerer,
        source: ir.exprs.NodeId,
        pattern: ir.exprs.NodeId,
        index: usize,
        capture: ?[]const u8,
        hoist: *std.ArrayListUnmanaged(ast.Stmt),
        items: *std.ArrayListUnmanaged(ast.Stmt),
        scope_names: *std.ArrayListUnmanaged([]const u8),
        claims: *ClaimCollector,
    ) anyerror!RuntimeIteratorInput {
        if (try self.patternCapturesByReference(pattern)) {
            return error.UnsupportedIteratorInput;
        }
        // The iterator has to be a value here: a `for` header spells a range
        // as a statement, and a `var` initializer has to be an expression.
        const value = try self.lowerMemoryReceiver(source, try self.allocExpr(try self.lowerExpr(source)));
        const binding = try self.iteratorTemporaryName(
            try std.fmt.allocPrint(self.alloc, "__r2z_iter_{d}", .{index}),
        );
        try hoist.append(self.alloc, .{ .let_stmt = .{
            .name = binding,
            .init = value.*,
            .is_mut = true,
        } });
        const step = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(.{ .ident = binding }),
                .field_name = "next",
            } }),
            .args = &.{},
        } });
        try self.appendIteratorClosurePatternNames(pattern, scope_names);

        if (capture) |capture_name| {
            try self.appendIteratorPayload(pattern, try self.exprType(source) orelse return error.MissingExpressionType, .{ .ident = capture_name }, items, claims);
            return .{ .binding = binding, .step = step, .capture = capture_name };
        }

        // `const item = iter.next();` / `if (item == null) break;` /
        // `const <pattern> = r2z.option.unwrap(item);`
        const pending = try self.iteratorTemporaryName(
            try std.fmt.allocPrint(self.alloc, "__r2z_pending_{d}", .{index}),
        );
        try items.append(self.alloc, .{ .let_stmt = .{
            .name = pending,
            .init = step.*,
        } });
        const is_null = try self.allocExpr(.{ .bin_op = .{
            .op = .equal,
            .lhs = try self.allocExpr(.{ .ident = pending }),
            .rhs = try self.allocExpr(.{ .lit = .null_lit }),
        } });
        const break_stmts = try self.alloc.alloc(ast.Stmt, 1);
        break_stmts[0] = .{ .expr_stmt = try self.allocExpr(.{ .break_expr = .{} }) };
        try items.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
            .cond = is_null,
            .then_body = try self.allocExpr(.{ .block = .{ .stmts = break_stmts } }),
        } }) });
        try self.markRuntimeImport();
        const unwrap_args = try self.alloc.alloc(ast.Expr, 1);
        unwrap_args[0] = .{ .ident = pending };
        const unwrapped = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.option.unwrap" }),
            .args = unwrap_args,
        } });
        try self.appendIteratorPayload(pattern, try self.exprType(source) orelse return error.MissingExpressionType, unwrapped.*, items, claims);
        return .{ .binding = binding, .step = step, .capture = null };
    }
    fn appendIteratorPayload(
        self: *Lowerer,
        pattern: ir.exprs.NodeId,
        carrier_ty: ir.types.Type,
        payload: ast.Expr,
        items: *std.ArrayListUnmanaged(ast.Stmt),
        claims: *ClaimCollector,
    ) anyerror!void {
        const produced = try self.producedItemOf(carrier_ty);
        if (!produced.owning) return self.appendIteratorClosureBindings(pattern, payload, items);
        try self.destructureStorageArmable(produced.ty);
        if (pattern >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const carrier = try self.iteratorTemporaryName("__r2z_iterator_payload");
        try items.append(self.alloc, .{ .let_stmt = .{ .name = carrier, .init = payload, .is_mut = true } });
        try items.append(self.alloc, try self.ownerReleaseStatement(carrier, ownerReleasesElements(produced.ty)));
        const base = try self.allocExpr(.{ .ident = carrier });
        const pat = self.ir.bodies.pats[pattern];
        switch (pat.kind) {
            .binding => |binding| {
                const name = try self.patternName(pattern);
                if (binding.mode != .value) {
                    try items.append(self.alloc, .{ .let_stmt = .{ .name = name, .init = .{ .unary_op = .{ .op = .addr_of, .operand = base } } } });
                    return;
                }
                if (try self.destructureClaimDef(pattern) == null) return error.MissingDefinition;
                try self.emitDestructureBinding(pattern, binding, name, base.*, produced.ty, items, &.{ .claims = claims, .drains_carrier = true, .source_type = produced.ty });
            },
            .tuple => |tuple| {
                if (tuple.rest) return error.UnsupportedPattern;
                try self.requireDestructureClaimDefs(tuple, &.{ .claims = claims, .drains_carrier = true, .source_type = produced.ty });
                try self.emitTupleDestructure(tuple, base, items, &.{ .claims = claims, .drains_carrier = true, .source_type = produced.ty });
            },
            .wildcard => {},
            else => return error.UnsupportedPattern,
        }
    }

    /// Build the loop that walks a set of runtime iterators. A plain input
    /// keeps the Zig `for` and preserves its by-reference captures; the first
    /// iterator with no plain sibling drives a `while` instead.
    fn lowerRuntimeIteratorFor(
        self: *Lowerer,
        runtime_inputs: []const RuntimeIteratorInput,
        plain_inputs: []const ast.Expr,
        plain_captures: []const ast.Capture,
        body: ast.Block,
        label: ?[]const u8,
    ) anyerror!ast.Expr {
        // Exactly one input drives the loop: the first runtime iterator when
        // there is no plain input to walk, and otherwise the Zig `for`.
        if (runtime_inputs.len > 0 and runtime_inputs[0].capture != null) {
            if (plain_inputs.len != 0) return error.InvalidIteratorInput;
            for (runtime_inputs[1..]) |other| {
                if (other.capture != null) return error.InvalidIteratorInput;
            }
            const captures = try self.alloc.alloc([]const u8, 1);
            captures[0] = runtime_inputs[0].capture.?;
            return .{ .while_expr = .{
                .cond = runtime_inputs[0].step,
                .captures = captures,
                .body = body,
                .label = label,
            } };
        }
        for (runtime_inputs) |other| {
            if (other.capture != null) return error.InvalidIteratorInput;
        }
        if (plain_inputs.len == 0) return error.MissingLoopInput;
        return .{ .for_expr = .{
            .inputs = plain_inputs,
            .captures = plain_captures,
            .body = body,
            .label = label,
        } };
    }

    fn appendIteratorClosureScope(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
        item: ast.Expr,
        nested: []const ast.Stmt,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (closure.params.len != 1) return error.UnsupportedIteratorAdapter;
        var scoped: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer scoped.deinit(self.alloc);
        try self.appendIteratorClosureBindings(closure.params[0], item, &scoped);
        try scoped.appendSlice(self.alloc, nested);
        const scoped_statements = try scoped.toOwnedSlice(self.alloc);
        const block: ast.Block = .{ .stmts = scoped_statements };
        for (scoped_statements) |*statement| {
            if (statement.* == .let_stmt and statement.let_stmt.is_mut) {
                statement.let_stmt.is_mut = try astMutatesBinding(block, statement.let_stmt.name, 0);
            }
        }
        try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .block = block }) });
    }

    /// Whether the item reaching the `sum` sink is still the by-pointer
    /// capture of an `.iter()`/`.iter_mut()` chain.
    ///
    /// Such a chain lowers to `for (xs[0..]) |*item|`, so `item` is a
    /// `*const T` while the accumulator is a `T`. `.map`, `.flat_map`,
    /// `enumerate` and `zip` each replace the item with a value of their own,
    /// so the sink derefs only while nothing upstream has already produced
    /// one — which is why `.copied().map(..).filter().sum()` (a by-value
    /// source) needs no deref and a bare `.iter().sum()` does.
    fn iteratorSumItemIsReference(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        adapter_index: usize,
    ) anyerror!bool {
        if (!try self.iteratorSourceByReference(chain.source)) return false;
        for (chain.adapters[0..adapter_index]) |adapter| switch (adapter) {
            .map, .flat_map, .enumerate, .zip => return false,
            // An unsupported adapter refuses before it reaches here, so the
            // deref decision for one is never actually taken.
            .filter, .range_rev, .other => {},
        };
        return true;
    }

    fn appendIteratorSumTail(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        adapter_index: usize,
        item: ast.Expr,
        accumulator_name: []const u8,
        state: IteratorStructuralState,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (adapter_index == chain.adapters.len) {
            const sink_item: ast.Expr = if (try self.iteratorSumItemIsReference(chain, adapter_index))
                .{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(item) } }
            else
                item;
            try statements.append(self.alloc, .{ .assign = .{
                .target = .{ .ident = accumulator_name },
                .val = sink_item,
                .op = .add_assign,
            } });
            return;
        }

        switch (chain.adapters[adapter_index]) {
            .map => |map| {
                const mapped = try self.lowerIteratorClosureBodyWithSnapshots(map.closure);
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                const mapped_value = try self.materializeIteratorItem(mapped, false, &nested, null);
                try self.appendIteratorSumTail(
                    chain,
                    adapter_index + 1,
                    mapped_value,
                    accumulator_name,
                    state,
                    &nested,
                );
                try self.appendIteratorClosureScope(
                    map.closure,
                    item,
                    nested.items,
                    statements,
                );
            },
            .filter => |filter| {
                const predicate = try self.lowerIteratorClosureBodyWithSnapshots(filter.closure);
                var then_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer then_stmts.deinit(self.alloc);
                try self.appendIteratorSumTail(
                    chain,
                    adapter_index + 1,
                    item,
                    accumulator_name,
                    state,
                    &then_stmts,
                );
                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try then_stmts.toOwnedSlice(self.alloc),
                } });
                const if_expr = try self.allocExpr(.{ .if_expr = .{
                    .cond = try self.allocExpr(predicate),
                    .then_body = then_body,
                } });
                const predicate_stmt = [_]ast.Stmt{.{ .expr_stmt = if_expr }};
                try self.appendIteratorClosureScope(
                    filter.closure,
                    .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(item) } },
                    &predicate_stmt,
                    statements,
                );
            },
            .flat_map => |closure| {
                if (self.iteratorRangeTail(closure)) |range_tail| {
                    var range_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer range_stmts.deinit(self.alloc);
                    const lowered_range = try self.lowerIteratorClosureRangeTail(
                        closure,
                        range_tail,
                        &range_stmts,
                    );
                    const range_loop = try self.appendIteratorRangeSetup(
                        lowered_range,
                        .forward,
                        &range_stmts,
                    );
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorSumTail(
                        chain,
                        adapter_index + 1,
                        range_loop.item,
                        accumulator_name,
                        state,
                        &inner_stmts,
                    );
                    try self.appendIteratorRangeLoop(
                        range_loop,
                        inner_stmts.items,
                        &range_stmts,
                        null,
                    );
                    try self.appendIteratorClosureScope(
                        closure,
                        item,
                        range_stmts.items,
                        statements,
                    );
                } else {
                    const iterable = try self.lowerIteratorClosureBodyWithSnapshots(closure);
                    const inner_name = try self.iteratorTemporaryName("__r2z_flat_item");
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorSumTail(
                        chain,
                        adapter_index + 1,
                        .{ .ident = inner_name },
                        accumulator_name,
                        state,
                        &inner_stmts,
                    );
                    const inputs = try self.alloc.alloc(ast.Expr, 1);
                    inputs[0] = iterable;
                    const captures = try self.alloc.alloc(ast.Capture, 1);
                    captures[0] = .{ .name = inner_name };
                    const inner_loop = try self.allocExpr(.{ .for_expr = .{
                        .inputs = inputs,
                        .captures = captures,
                        .body = .{ .stmts = try inner_stmts.toOwnedSlice(self.alloc) },
                    } });
                    const inner_stmt = [_]ast.Stmt{.{ .expr_stmt = inner_loop }};
                    try self.appendIteratorClosureScope(
                        closure,
                        item,
                        &inner_stmt,
                        statements,
                    );
                }
            },
            .enumerate => {
                const index_name = state.enumerate_indices[adapter_index];
                const stage_name = state.enumerate_items[adapter_index];
                if (index_name.len == 0 or stage_name.len == 0) return error.UnsupportedIteratorAdapter;
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = .{ .ident = index_name };
                tuple_items[1] = item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorSumTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    accumulator_name,
                    state,
                    &nested,
                );
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } }) });
            },
            .zip => {
                const index_name = state.zip_indices[adapter_index];
                const right_name = state.zip_rights[adapter_index];
                const stage_name = state.zip_items[adapter_index];
                if (index_name.len == 0 or right_name.len == 0 or stage_name.len == 0) {
                    return error.UnsupportedIteratorAdapter;
                }
                const right_len = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = right_name }),
                    .field_name = "len",
                } });
                const condition = try self.allocExpr(.{ .bin_op = .{
                    .op = .less_than,
                    .lhs = try self.allocExpr(.{ .ident = index_name }),
                    .rhs = right_len,
                } });
                const right_args = try self.alloc.alloc(ast.Expr, 2);
                right_args[0] = .{ .ident = right_name };
                right_args[1] = .{ .ident = index_name };
                var right_item: ast.Expr = .{ .builtin = .{
                    .name = "index",
                    .args = right_args,
                } };
                if (state.zip_right_by_ref[adapter_index]) {
                    right_item = .{ .unary_op = .{
                        .op = .addr_of,
                        .operand = try self.allocExpr(right_item),
                    } };
                }
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = item;
                tuple_items[1] = right_item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorSumTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    accumulator_name,
                    state,
                    &nested,
                );
                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } });
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
                    .cond = condition,
                    .then_body = then_body,
                } }) });
            },
            .range_rev, .other => return error.UnsupportedIteratorAdapter,
        }
    }

    fn lowerIteratorSumBlock(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        return_type: ir.types.Type,
    ) anyerror!ast.Block {
        if (chain.terminal != .sum) return error.UnsupportedIteratorTerminal;
        const accumulator_name = try self.iteratorTemporaryName("__r2z_sum");
        const adapter_count = chain.adapters.len;
        const enumerate_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_indices);
        const enumerate_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_items);
        const zip_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_indices);
        const zip_rights = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_rights);
        const zip_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_items);
        const zip_right_by_ref = try self.alloc.alloc(bool, adapter_count);
        defer self.alloc.free(zip_right_by_ref);
        for (enumerate_indices, 0..) |*name, index| {
            name.* = &.{};
            enumerate_items[index] = &.{};
            zip_indices[index] = &.{};
            zip_rights[index] = &.{};
            zip_items[index] = &.{};
            zip_right_by_ref[index] = false;
        }

        var prefix: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prefix.deinit(self.alloc);
        for (chain.adapters, 0..) |adapter, index| {
            switch (adapter) {
                .enumerate => {
                    const name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_index_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_item_{d}", .{index}),
                    );
                    enumerate_indices[index] = name;
                    enumerate_items[index] = item_name;
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .zip => |zip| {
                    const index_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_index_{d}", .{index}),
                    );
                    const right_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_right_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_item_{d}", .{index}),
                    );
                    zip_indices[index] = index_name;
                    zip_rights[index] = right_name;
                    zip_items[index] = item_name;
                    zip_right_by_ref[index] = try self.iteratorSourceByReference(zip.other);
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = right_name,
                        .init = try self.lowerIteratorSource(zip.other),
                    } });
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = index_name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .range_rev => if (index != 0) return error.UnsupportedIteratorAdapter,
                .map, .filter, .flat_map => {},
                .other => return error.UnsupportedIteratorAdapter,
            }
        }

        const reverse = if (chain.adapters.len > 0) switch (chain.adapters[0]) {
            .range_rev => true,
            else => false,
        } else false;
        const source_is_range = chain.source < self.ir.bodies.exprs.len and
            self.ir.bodies.exprs[chain.source].kind == .range;
        const source = if (source_is_range)
            @as(?ast.Expr, null)
        else
            try self.lowerIteratorSource(chain.source);
        const source_by_ref = if (source_is_range)
            false
        else
            try self.iteratorSourceByReference(chain.source);
        var loop_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer loop_stmts.deinit(self.alloc);
        const state: IteratorStructuralState = .{
            .enumerate_indices = enumerate_indices,
            .enumerate_items = enumerate_items,
            .zip_indices = zip_indices,
            .zip_rights = zip_rights,
            .zip_items = zip_items,
            .zip_right_by_ref = zip_right_by_ref,
        };
        const previous_iterator_prelude = self.current_iterator_capture_prelude;
        self.current_iterator_capture_prelude = &prefix;
        defer self.current_iterator_capture_prelude = previous_iterator_prelude;

        if (source_is_range) {
            const lowered_range = try self.lowerIteratorRange(chain.source);
            const direction: IteratorRangeDirection = if (reverse) .reverse else .forward;
            const range_loop = try self.appendIteratorRangeSetup(
                lowered_range,
                direction,
                &prefix,
            );
            try self.appendIteratorSumTail(
                chain,
                if (reverse) 1 else 0,
                range_loop.item,
                accumulator_name,
                state,
                &loop_stmts,
            );
            try self.appendIteratorRangeLoop(range_loop, loop_stmts.items, &prefix, null);
        } else {
            if (reverse) return error.UnsupportedIteratorAdapter;
            const item_name = try self.iteratorTemporaryName("__r2z_item");
            try self.appendIteratorSumTail(
                chain,
                0,
                .{ .ident = item_name },
                accumulator_name,
                state,
                &loop_stmts,
            );
            const inputs = try self.alloc.alloc(ast.Expr, 1);
            inputs[0] = source.?;
            const captures = try self.alloc.alloc(ast.Capture, 1);
            captures[0] = .{ .name = item_name, .by_ref = source_by_ref };
            try prefix.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .for_expr = .{
                .inputs = inputs,
                .captures = captures,
                .body = .{ .stmts = try loop_stmts.toOwnedSlice(self.alloc) },
            } }) });
        }

        const statements = try self.alloc.alloc(ast.Stmt, prefix.items.len + 1);
        statements[0] = .{ .let_stmt = .{
            .name = accumulator_name,
            .ty = try self.lowerType(return_type),
            .init = .{ .lit = .{ .int = 0 } },
            .is_mut = true,
        } };
        @memcpy(statements[1..], prefix.items);
        return .{
            .stmts = statements,
            .expr = try self.allocExpr(.{ .ident = accumulator_name }),
        };
    }
    fn appendIteratorCollectionTail(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        adapter_index: usize,
        item: ast.Expr,
        collector: Collector,
        owner_name: []const u8,
        state: IteratorStructuralState,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        // A `?` inside an adapter body is a Rust error value the collection
        // reports, not a Zig allocation failure the function propagates, so
        // the rest of the lowering has to know which collection is open. The
        // item type is the context an adapter body assembles its value in.
        const previous_collector = self.current_collector;
        self.current_collector = collector;
        defer self.current_collector = previous_collector;
        const previous_item_type = self.expected_value_type;
        if (collector.result != null) self.expected_value_type = collector.item;
        defer self.expected_value_type = previous_item_type;
        if (adapter_index == chain.adapters.len) {
            try self.appendCollectorItem(collector, owner_name, item, statements);
            return;
        }
        switch (chain.adapters[adapter_index]) {
            .map => |map| {
                const mapped = try self.lowerIteratorClosureBodyWithSnapshots(map.closure);
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                // A `Result` collect's item is a `Result`, and the closure
                // assembles it from an `Ok(..)` node the frontend left
                // untyped. The local has to name the union, or the anonymous
                // struct that node produces is a type of its own and nothing
                // downstream can unwrap it.
                //
                // Only an adapter with a stage still to run needs that local
                // here: whatever follows reads this value more than once, once
                // per stage. A `map` at the END of the chain hands its value to
                // the deposit, which binds it once itself — under the same
                // type — and binding it twice would leave a second local that
                // names nothing the first one does not.
                const mapped_value = if (adapter_index + 1 == chain.adapters.len)
                    mapped
                else
                    try self.materializeIteratorItem(
                        mapped,
                        false,
                        &nested,
                        if (collector.result != null) try self.lowerType(collector.item) else null,
                    );
                try self.appendIteratorCollectionTail(
                    chain,
                    adapter_index + 1,
                    mapped_value,
                    collector,
                    owner_name,
                    state,
                    &nested,
                );
                try self.appendIteratorClosureScope(map.closure, item, nested.items, statements);
            },
            .filter => |filter| {
                const predicate = try self.lowerIteratorClosureBodyWithSnapshots(filter.closure);
                var then_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer then_stmts.deinit(self.alloc);
                try self.appendIteratorCollectionTail(
                    chain,
                    adapter_index + 1,
                    item,
                    collector,
                    owner_name,
                    state,
                    &then_stmts,
                );
                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try then_stmts.toOwnedSlice(self.alloc),
                } });
                const if_expr = try self.allocExpr(.{ .if_expr = .{
                    .cond = try self.allocExpr(predicate),
                    .then_body = then_body,
                } });
                const predicate_stmt = [_]ast.Stmt{.{ .expr_stmt = if_expr }};
                try self.appendIteratorClosureScope(filter.closure, .{ .unary_op = .{
                    .op = .addr_of,
                    .operand = try self.allocExpr(item),
                } }, &predicate_stmt, statements);
            },
            .flat_map => |closure| {
                if (self.iteratorRangeTail(closure)) |range_tail| {
                    var range_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer range_stmts.deinit(self.alloc);
                    const lowered_range = try self.lowerIteratorClosureRangeTail(
                        closure,
                        range_tail,
                        &range_stmts,
                    );
                    const range_loop = try self.appendIteratorRangeSetup(
                        lowered_range,
                        .forward,
                        &range_stmts,
                    );
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorCollectionTail(
                        chain,
                        adapter_index + 1,
                        range_loop.item,
                        collector,
                        owner_name,
                        state,
                        &inner_stmts,
                    );
                    try self.appendIteratorRangeLoop(
                        range_loop,
                        inner_stmts.items,
                        &range_stmts,
                        null,
                    );
                    try self.appendIteratorClosureScope(
                        closure,
                        item,
                        range_stmts.items,
                        statements,
                    );
                } else {
                    const iterable = try self.lowerIteratorClosureBodyWithSnapshots(closure);
                    const inner_name = try self.iteratorTemporaryName("__r2z_flat_item");
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorCollectionTail(
                        chain,
                        adapter_index + 1,
                        .{ .ident = inner_name },
                        collector,
                        owner_name,
                        state,
                        &inner_stmts,
                    );
                    const inputs = try self.alloc.alloc(ast.Expr, 1);
                    inputs[0] = iterable;
                    const captures = try self.alloc.alloc(ast.Capture, 1);
                    captures[0] = .{ .name = inner_name };
                    const inner_loop = try self.allocExpr(.{ .for_expr = .{
                        .inputs = inputs,
                        .captures = captures,
                        .body = .{ .stmts = try inner_stmts.toOwnedSlice(self.alloc) },
                    } });
                    var scope_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer scope_stmts.deinit(self.alloc);
                    try scope_stmts.append(self.alloc, .{ .expr_stmt = inner_loop });
                    try self.appendIteratorClosureScope(
                        closure,
                        item,
                        try scope_stmts.toOwnedSlice(self.alloc),
                        statements,
                    );
                }
            },
            .enumerate => {
                const index_name = state.enumerate_indices[adapter_index];
                const stage_name = state.enumerate_items[adapter_index];
                if (index_name.len == 0 or stage_name.len == 0) return error.UnsupportedIteratorAdapter;
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = .{ .ident = index_name };
                tuple_items[1] = item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorCollectionTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    collector,
                    owner_name,
                    state,
                    &nested,
                );
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } }) });
            },
            .zip => {
                const index_name = state.zip_indices[adapter_index];
                const right_name = state.zip_rights[adapter_index];
                const stage_name = state.zip_items[adapter_index];
                if (index_name.len == 0 or right_name.len == 0 or stage_name.len == 0) {
                    return error.UnsupportedIteratorAdapter;
                }
                const right_len = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = right_name }),
                    .field_name = "len",
                } });
                const condition = try self.allocExpr(.{ .bin_op = .{
                    .op = .less_than,
                    .lhs = try self.allocExpr(.{ .ident = index_name }),
                    .rhs = right_len,
                } });
                const right_args = try self.alloc.alloc(ast.Expr, 2);
                right_args[0] = .{ .ident = right_name };
                right_args[1] = .{ .ident = index_name };
                var right_item: ast.Expr = .{ .builtin = .{
                    .name = "index",
                    .args = right_args,
                } };
                if (state.zip_right_by_ref[adapter_index]) {
                    right_item = .{ .unary_op = .{
                        .op = .addr_of,
                        .operand = try self.allocExpr(right_item),
                    } };
                }
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = item;
                tuple_items[1] = right_item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorCollectionTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    collector,
                    owner_name,
                    state,
                    &nested,
                );
                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } });
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
                    .cond = condition,
                    .then_body = then_body,
                } }) });
            },
            .range_rev, .other => return error.UnsupportedIteratorAdapter,
        }
    }

    /// The Zig container a `collect` target lowers to.
    ///
    /// The target type alone decides this. `Vec<T>` becomes an
    /// `ArrayListUnmanaged` and takes `append`; `String` becomes
    /// `r2z.alloc.String` and takes `push` of a codepoint. What a collection
    /// HOLDS is the item type, a separate question, and it never picks the
    /// container: `Vec<char>` and `String` hold the same elements and are
    /// built by different calls.
    const CollectorTarget = enum {
        /// `Vec<T>` lowers to `std.ArrayListUnmanaged(T)`.
        vec,
        /// `String` lowers to `r2z.alloc.String`.
        string,
        /// A bare type parameter. The Zig instantiation is the only thing
        /// that knows which container it is, and that is a comptime value,
        /// so the emitted deposit picks the operation with a comptime branch
        /// instead of guessing one from the item type.
        comptime_param,
    };

    /// A `collect` terminal resolved against the collection it actually builds.
    const Collector = struct {
        /// Which container the loop fills.
        target: CollectorTarget,
        /// The Rust type the loop fills. A `Result` collect fills the `Ok`
        /// arm's collection and wraps it once the loop is done, so this is
        /// that inner type and never the `Result` itself.
        owner: ir.types.Type,
        /// The type of one item: the `Result` a `Result` collect unwraps, the
        /// element otherwise. Context, so an adapter body that assembles its
        /// value from literals names the type those literals have to match.
        item: ir.types.Type,
        /// The `Result<owner, err>` the `collect` expression itself produces,
        /// or null for a plain collection. Set means the first item error ends
        /// the collection instead of the enclosing function, and it is the
        /// type a `?` inside an adapter body reports in.
        result: ?ir.types.Type,
        /// Local that holds that error while the loop runs.
        error_name: []const u8,
        /// Label on the block that wraps the collect's own loop, and so the
        /// target every item error and every adapter propagation breaks to.
        /// Empty for a plain collection, which records nothing to leave with.
        ///
        /// The block carries no value: a Zig block's type comes from its
        /// `break` payloads, and an exit raised halfway through the loop has
        /// no `Result` to hand over yet. The error itself rides out in
        /// `error_name`, and the block's own tail is what turns it into the
        /// collection's `Err`.
        exit_label: []const u8,
    };

    /// True when a `collect` result is a `String` rather than a `Vec`.
    fn isStringCollectionType(ty: ir.types.Type) bool {
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        return externalPathEqual(external.path, &.{ "alloc", "string", "String" }) or
            externalPathEqual(external.path, &.{ "std", "string", "String" });
    }

    /// Element type a collection target accepts, or null when the target is
    /// not one of the collections the translator emits. This is the ITEM type
    /// only: it never chooses the container (see `collectorTargetFor`).
    fn collectionElementType(self: *Lowerer, ty: ir.types.Type) anyerror!?ir.types.Type {
        if (isStringCollectionType(ty)) return .{ .prim = .char };
        if (isTypeParameterPath(ty)) return self.boundCollectionItemType(ty);
        return vecElementOfContext(ty);
    }

    /// The `Item` the enclosing callable's own `FromIterator` bound declares
    /// for a type parameter.
    ///
    /// `T: FromIterator<char>` says what the collection HOLDS, which is the
    /// one thing a bare type parameter target leaves unstated: the element
    /// type the loop's item is assembled in, so `Vec<char>` and `String` both
    /// agree on `char`. It says nothing about WHICH collection `T` is — the
    /// same bound serves a `String` and a `Vec<char>` — so the container is
    /// never read from here. Null when the bound is absent or names no
    /// `FromIterator`, and the caller refuses instead of guessing.
    fn boundCollectionItemType(self: *Lowerer, ty: ir.types.Type) ?ir.types.Type {
        const path = switch (ty) {
            .path => |value| value,
            else => return null,
        };
        const param_name = lastPathSegment(path.segments) orelse return null;
        const callable_id = self.current_callable_id orelse return null;
        if (callable_id >= self.ir.bodies.bodies.len) return null;
        const fn_body = switch (self.ir.bodies.bodies[callable_id]) {
            .fn_ => |body| body,
            else => return null,
        };
        const generics = fn_body.generics orelse return null;
        for (generics.params) |param| {
            const type_param = switch (param) {
                .type_ => |value| value,
                else => continue,
            };
            if (!std.mem.eql(u8, type_param.name, param_name.name)) continue;
            for (type_param.bounds) |bound| {
                const bound_name = lastPathSegment(bound.path.segments) orelse continue;
                if (!std.mem.eql(u8, bound_name.name, "FromIterator")) continue;
                if (bound.args.len != 1) continue;
                return bound.args[0];
            }
        }
        return null;
    }

    /// The container a `collect` target lowers to, from the target type the
    /// source wrote and nothing else.
    ///
    /// A bare type parameter is the one target whose container the body
    /// cannot name: `fn collect<T: FromIterator<char>>() -> T` is emitted
    /// once and instantiated as `String` by one caller and as `Vec<char>` by
    /// the next. Its `FromIterator` bound says what the collection holds,
    /// never which collection it is, so that answer waits for the
    /// instantiation.
    fn collectorTargetFor(owner: ir.types.Type) CollectorTarget {
        if (isStringCollectionType(owner)) return .string;
        if (isTypeParameterPath(owner)) return .comptime_param;
        return .vec;
    }

    /// Resolve the collection a `collect` terminal builds, unwrapping a
    /// `Result` target so the loop fills the `Ok` arm's collection and the
    /// first item error becomes the `Err` arm.
    fn resolveCollector(self: *Lowerer, return_type: ir.types.Type) anyerror!Collector {
        const target: struct { owner: ir.types.Type, result: ?ir.types.Type } =
            switch (return_type) {
                .result => |arms| result_target: {
                    // A `Result` that lowers to a Zig error union carries no
                    // tagged arms to unwrap and no `Err` value to hand back,
                    // so there is nothing faithful to emit for one.
                    if (self.resultUsesErrorUnion(return_type)) {
                        return error.UnsupportedCollectionType;
                    }
                    break :result_target .{ .owner = arms.ok, .result = return_type };
                },
                else => .{ .owner = return_type, .result = null },
            };
        const element = (try self.collectionElementType(target.owner)) orelse
            return error.UnsupportedCollectionType;
        const item: ir.types.Type = if (target.result) |result_type| item_result: {
            const arms = try self.alloc.create(ir.types.Result);
            arms.* = .{
                .ok = element,
                .err = result_type.result.err,
                .is_error_unionable = false,
            };
            break :item_result .{ .result = arms };
        } else element;
        return .{
            .target = collectorTargetFor(target.owner),
            .owner = target.owner,
            .item = item,
            .result = target.result,
            // Both names are only read on the error path, so a plain
            // collection does not pay a temporary for either.
            .error_name = if (target.result != null)
                try self.iteratorTemporaryName("__r2z_collect_error")
            else
                &.{},
            .exit_label = if (target.result != null)
                try self.iteratorTemporaryName("__r2z_collect_exit")
            else
                &.{},
        };
    }

    /// `try <owner>.<method>(allocator, <item>);` — the one statement a
    /// collection emits per item.
    ///
    /// `method` is the container's own. The argument list is arena-allocated
    /// because it carries an item expression built per item, and a slice
    /// literal over a runtime value would dangle the moment this frame
    /// returned.
    fn collectorAppendStatement(
        self: *Lowerer,
        owner_name: []const u8,
        method: []const u8,
        item: ast.Expr,
    ) anyerror!ast.Stmt {
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .ident = "allocator" };
        args[1] = item;
        return .{ .expr_stmt = try self.allocExpr(.{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(.{ .call = .{
                .callee = try self.collectorOwnerMethod(owner_name, method),
                .args = args,
            } }),
        } }) };
    }

    /// The statements one item deposits, in the order the collect's target
    /// needs them.
    fn collectorDeposit(
        self: *Lowerer,
        collector: Collector,
        owner_name: []const u8,
        item: ast.Expr,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        switch (collector.target) {
            .vec => try statements.append(
                self.alloc,
                try self.collectorAppendStatement(owner_name, "append", item),
            ),
            .string => try statements.append(
                self.alloc,
                try self.collectorAppendStatement(owner_name, "push", item),
            ),
            .comptime_param => {
                // One name for the item, so the branch that wins prints that
                // name: a single `ast.Expr` shared by two call sites is one
                // node emitted twice, and the emitter renames generated
                // labels per nesting depth.
                const bound = try self.materializeIteratorItem(item, false, statements, null);
                try statements.append(
                    self.alloc,
                    try self.collectorComptimeDispatchStatement(owner_name, bound),
                );
            },
        }
    }

    /// The comptime branch that picks the deposit the container has.
    ///
    /// The comparison is comptime — the owner is a `comptime T: type`
    /// parameter — so Zig analyzes the branch that matches and leaves the
    /// other one alone. That is what lets one emitted body serve both a
    /// `String`, whose `push` takes a codepoint, and a `Vec<Item>`, whose
    /// `append` takes an element: neither container grows the other's
    /// method, and no `String.append` alias is invented to paper over the
    /// overlap.
    fn collectorComptimeDispatchStatement(
        self: *Lowerer,
        owner_name: []const u8,
        item: ast.Expr,
    ) anyerror!ast.Stmt {
        const owner_args = try self.alloc.alloc(ast.Expr, 1);
        owner_args[0] = .{ .ident = owner_name };
        const push_stmts = try self.alloc.alloc(ast.Stmt, 1);
        push_stmts[0] = try self.collectorAppendStatement(owner_name, "push", item);
        const append_stmts = try self.alloc.alloc(ast.Stmt, 1);
        append_stmts[0] = try self.collectorAppendStatement(owner_name, "append", item);
        return .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
            .cond = try self.allocExpr(.{ .bin_op = .{
                .op = .equal,
                .lhs = try self.allocExpr(.{ .builtin = .{
                    .name = "TypeOf",
                    .args = owner_args,
                } }),
                .rhs = try self.allocExpr(try self.ownedStringTypeExpr()),
            } }),
            .then_body = try self.allocExpr(.{ .block = .{ .stmts = push_stmts } }),
            .else_body = try self.allocExpr(.{ .block = .{ .stmts = append_stmts } }),
        } }) };
    }

    /// `r2z.alloc.String` as a Zig type expression, taken from the mapping
    /// for `String` itself so the comptime dispatch cannot compare against a
    /// name the type mapping no longer emits. Lowering the type is also what
    /// records the runtime import the emitted name needs.
    fn ownedStringTypeExpr(self: *Lowerer) anyerror!ast.Expr {
        const string_type: ir.types.Type = .{ .external_nominal = .{
            .path = &.{ "alloc", "string", "String" },
            .args = &.{},
        } };
        return switch (try self.lowerType(string_type)) {
            .named => |name| .{ .ident = name },
            .generic => |generic| .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = generic.name }),
                .generic_args = generic.params,
                .args = &.{},
            } },
            else => return error.UnsupportedCollectionType,
        };
    }

    /// A method call on the collection being built, e.g. `__r2z_owner.append`.
    fn collectorOwnerMethod(
        self: *Lowerer,
        owner_name: []const u8,
        method_name: []const u8,
    ) anyerror!*const ast.Expr {
        return self.allocExpr(.{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = owner_name }),
            .field_name = method_name,
        } });
    }

    /// `<owner>.deinit(allocator)` — releasing what the loop accumulated.
    /// The argument list is arena-allocated with every other call list here.
    fn collectorDeinit(self: *Lowerer, owner_name: []const u8) anyerror!ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = .{ .ident = "allocator" };
        return .{ .call = .{
            .callee = try self.collectorOwnerMethod(owner_name, "deinit"),
            .args = args,
        } };
    }

    /// Deposit one item into the collection.
    ///
    /// A `Result` collect unwraps the item instead of appending it whole: Rust
    /// collects `Result<A, E>` items into `Result<V, E>` by stopping at the
    /// first `Err` and handing it back, and the value the `Ok` arm carried is
    /// the only thing that belongs in the collection. `is_ok`, `unwrap` and
    /// `unwrap_err` are the runtime's own arms, so the two branches cannot
    /// disagree about which tag they are looking at.
    ///
    /// The exit names the collect's own exit block, so it leaves the whole
    /// collection however deeply the chain is nested. An adapter that walks a
    /// second iterable, and a Rust loop written inside an adapter body, each
    /// put a loop between this deposit and the block the collect owns; a bare
    /// `break` would stop the nearest of them and carry on with an answer the
    /// collection never finished building, so the label is what makes the exit
    /// total rather than a cascade of guards. A source `break` or `continue`
    /// names its own target and is never caught here, and nothing after this
    /// deposit runs on the way out, so no later item is evaluated. The
    /// enclosing function keeps running: a `return` could not, in let or
    /// argument position.
    fn appendCollectorItem(
        self: *Lowerer,
        collector: Collector,
        owner_name: []const u8,
        item: ast.Expr,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (collector.result == null) {
            try self.collectorDeposit(collector, owner_name, item, statements);
            return;
        }
        // The item is bound to a local of the `Result` type: the collection
        // names its own unwrap, and a bare `.{ .Ok = v }` has no peer type to
        // find it with.
        const item_name = try self.materializeIteratorItem(
            item,
            false,
            statements,
            try self.lowerType(collector.item),
        );
        const name = switch (item_name) {
            .ident => |ident| ident,
            else => return error.UnsupportedCollectionType,
        };
        var then_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer then_stmts.deinit(self.alloc);
        try self.collectorDeposit(
            collector,
            owner_name,
            try self.collectorUnwrap(name, "unwrap"),
            &then_stmts,
        );
        var exit_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer exit_stmts.deinit(self.alloc);
        try exit_stmts.append(self.alloc, .{ .assign = .{
            .target = .{ .ident = collector.error_name },
            .val = try self.collectorUnwrap(name, "unwrap_err"),
        } });
        try exit_stmts.append(self.alloc, .{
            .expr_stmt = try self.allocExpr(.{ .break_expr = .{
                .label = collector.exit_label,
            } }),
        });
        const exit_body = try self.allocExpr(.{ .block = .{
            .stmts = try exit_stmts.toOwnedSlice(self.alloc),
        } });
        try statements.append(self.alloc, .{
            .expr_stmt = try self.allocExpr(.{
                .if_expr = .{
                    // The condition is an arena-allocated expression of its own, like
                    // every other `ast.IfExpr` the lowering builds: the AST keeps
                    // conditions by pointer, and the call it wraps is built by value.
                    .cond = try self.allocExpr(try self.collectorUnwrap(name, "is_ok")),
                    .then_body = try self.allocExpr(.{ .block = .{
                        .stmts = try then_stmts.toOwnedSlice(self.alloc),
                    } }),
                    .else_body = exit_body,
                },
            }),
        });
    }

    /// Both consuming Result projections release the discarded arm through
    /// the enclosing allocator. Tag predicates have no arguments.
    fn collectorUnwrap(
        self: *Lowerer,
        item_name: []const u8,
        method: []const u8,
    ) anyerror!ast.Expr {
        const args: []const ast.Expr = if (std.mem.eql(u8, method, "unwrap") or std.mem.eql(u8, method, "unwrap_err"))
            try self.alloc.dupe(ast.Expr, &.{.{ .ident = "allocator" }})
        else
            &.{};
        return .{ .call = .{
            .callee = try self.collectorOwnerMethod(item_name, method),
            .args = args,
        } };
    }

    /// `{ <error> = <error_value>; break :<exit>; }` — how a `?` inside an
    /// adapter body leaves a `Result` collect.
    ///
    /// The `?` sits in a `switch` whose other arm yields the unwrapped payload,
    /// so this arm has to be a value of that payload's type or no value at all.
    /// It is no value at all: the labeled exit is the block's own result, so the
    /// block diverges, which is what lets Zig read the `?` as a type that never
    /// produced a payload rather than as one that produced the wrong type. A
    /// trailing `unreachable` would say the same thing and cost the emitted
    /// crate a `unreachable code` error, because Zig rejects a statement that
    /// follows an unconditional exit.
    ///
    /// The exit names the collect's own exit block, which is what makes a `?`
    /// in a body that also runs a loop work: the label is resolved against the
    /// block that carries it, so the nested loop the body opens is stepped
    /// over rather than stopped, and the enclosing function keeps running.
    fn collectorErrorExit(
        self: *Lowerer,
        collector: Collector,
        err_expr: ast.Expr,
    ) anyerror!ast.Expr {
        var stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer stmts.deinit(self.alloc);
        try stmts.append(self.alloc, .{ .assign = .{
            .target = .{ .ident = collector.error_name },
            .val = err_expr,
        } });
        return .{ .block = .{
            .stmts = try stmts.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(.{ .break_expr = .{
                .label = collector.exit_label,
            } }),
        } };
    }

    /// The value a `Result` collect hands back, which is the whole of Rust's
    /// `collect::<Result<V, E>>()`: an empty source and a source that ran to
    /// completion both report `Ok` with the collection they built, and the
    /// first `Err` item reports that error with the prefix released.
    ///
    /// The release is explicit because the `errdefer` above the loop cannot do
    /// it: this is an ordinary Rust result, so the block returns normally and
    /// no error return runs. `deinit` leaves the collection empty, so the
    /// `errdefer` is a no-op if the enclosing function does return an error
    /// after this value has moved on, and the `Ok` arm moves the buffer on
    /// without releasing it.
    ///
    /// The condition is the error local, so the value is decided by whether
    /// anything recorded an error and never by what the loop happened to
    /// iterate: iteration stopped at the first `Err`, and the `Ok` payload it
    /// would have carried is not in the collection either way. Recording and
    /// leaving are two statements at the exit site; this is where the value
    /// they carry out is finally built, and the `Err` arm is the one place the
    /// accumulated prefix is released.
    fn collectorResultTail(
        self: *Lowerer,
        collector: Collector,
        owner_name: []const u8,
    ) anyerror!ast.Expr {
        const arms = collector.result orelse return error.UnsupportedCollectionType;
        try self.markRuntimeImport();
        const result_type = try self.allocType(try self.lowerTaggedResult(
            arms.result.ok,
            arms.result.err,
        ));
        const err_fields = try self.alloc.alloc(ast.StructInitField, 1);
        const unwrap_args = try self.alloc.alloc(ast.Expr, 1);
        unwrap_args[0] = .{ .ident = collector.error_name };
        err_fields[0] = .{
            .name = try self.alloc.dupe(u8, "Err"),
            .expr = .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, "r2z.option.unwrap") }),
                .args = unwrap_args,
            } },
        };
        const exit_stmts = try self.alloc.alloc(ast.Stmt, 1);
        exit_stmts[0] = .{ .expr_stmt = try self.allocExpr(try self.collectorDeinit(owner_name)) };
        const ok_fields = try self.alloc.alloc(ast.StructInitField, 1);
        ok_fields[0] = .{
            .name = try self.alloc.dupe(u8, "Ok"),
            .expr = .{ .ident = owner_name },
        };
        return .{ .if_expr = .{
            .cond = try self.allocExpr(.{ .bin_op = .{
                .op = .not_equal,
                .lhs = try self.allocExpr(.{ .ident = collector.error_name }),
                .rhs = try self.allocExpr(.{ .lit = .null_lit }),
            } }),
            .then_body = try self.allocExpr(.{ .block = .{
                .label = try self.iteratorTemporaryName("__r2z_collect_err"),
                .stmts = exit_stmts,
                .expr = try self.allocExpr(.{ .struct_init = .{
                    .type_name = result_type.*,
                    .fields = err_fields,
                } }),
            } }),
            .else_body = try self.allocExpr(.{ .struct_init = .{
                .type_name = result_type.*,
                .fields = ok_fields,
            } }),
        } };
    }

    /// The collect's own loop, inside the block its exits leave through.
    ///
    /// The label is what makes an exit total. A bare `break` reaches the
    /// nearest enclosing loop, and an adapter that walks a second iterable or
    /// a Rust loop written inside an adapter body each put one between that
    /// exit and the loop the collect owns; naming this block instead steps
    /// over every one of them, so no guard has to guess how deep the chain
    /// went. A source `break` or `continue` names its own target and is never
    /// claimed here.
    ///
    /// The block carries no value, which is what every `break` into it has to
    /// match: the error it is leaving with is still in `error_name` at that
    /// point, and `collectorResultTail` is what turns it into the collection's
    /// `Err` once the loop is behind. A plain collection records nothing, so
    /// its loop goes in unwrapped rather than behind a label nothing names.
    ///
    /// It reaches the emitter as a `const` INITIALISER, not as a statement of
    /// its own. The emitter decides a labelled block's position before it
    /// writes a byte and refuses the one shape it cannot spell, and a block
    /// written as a bare statement is that shape — so the carrier is what makes
    /// it writable. This is the same carrier `bindGuardChainToLocal` puts in
    /// front of a guarded chain, and one rule for both is the point: a labelled
    /// block is always bound, never naked. The carrier is `_`, so nothing is
    /// bound and Zig has no unused local to reject.
    fn appendCollectLoopStatement(
        self: *Lowerer,
        collector: Collector,
        loop_scope: []const ast.Stmt,
        prefix: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (collector.exit_label.len == 0) {
            try prefix.appendSlice(self.alloc, loop_scope);
            return;
        }
        // One statement: the labelled block carries the loop with it, so the
        // loop is emitted inside the block and nowhere else. The carrier is a
        // DISCARD ASSIGNMENT, not a binding named `_`: Zig has no identifier
        // `_`, so `const _ = ...;` would not compile in the generated file,
        // and `unusedBindingAsDiscard` deliberately passes a `_` binding
        // through instead of rewriting it, so a `_` let_stmt is the one form
        // that reaches the emitter intact. Writing the discard itself is also
        // the same shape that rewrite produces, so one spelling means one
        // thing.
        const statements = try self.alloc.alloc(ast.Stmt, 1);
        statements[0] = .{ .assign = .{
            .target = .{ .ident = "_" },
            .val = .{ .block = .{
                .label = collector.exit_label,
                .stmts = loop_scope,
            } },
        } };
        try prefix.appendSlice(self.alloc, statements);
    }

    fn lowerIteratorCollectionBlock(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        return_type: ir.types.Type,
    ) anyerror!ast.Block {
        if (chain.terminal != .collect_vec) return error.UnsupportedIteratorTerminal;
        const collector = try self.resolveCollector(return_type);
        const owner_type = try self.lowerType(collector.owner);
        const owner_name = try self.iteratorTemporaryName("__r2z_owner");
        const owner_type_expr: ast.Expr = switch (owner_type) {
            .named => |name| .{ .ident = name },
            .generic => |generic| .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = generic.name }),
                .generic_args = generic.params,
                .args = &.{},
            } },
            else => return error.UnsupportedCollectionType,
        };
        const owner_init: ast.Expr = .{ .field_access = .{
            .target = try self.allocExpr(owner_type_expr),
            .field_name = "empty",
        } };

        const adapter_count = chain.adapters.len;
        const enumerate_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_indices);
        const enumerate_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_items);
        const zip_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_indices);
        const zip_rights = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_rights);
        const zip_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_items);
        const zip_right_by_ref = try self.alloc.alloc(bool, adapter_count);
        defer self.alloc.free(zip_right_by_ref);
        for (enumerate_indices, 0..) |*name, index| {
            name.* = &.{};
            enumerate_items[index] = &.{};
            zip_indices[index] = &.{};
            zip_rights[index] = &.{};
            zip_items[index] = &.{};
            zip_right_by_ref[index] = false;
        }

        var prefix: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prefix.deinit(self.alloc);
        for (chain.adapters, 0..) |adapter, index| {
            switch (adapter) {
                .enumerate => {
                    const name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_index_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_item_{d}", .{index}),
                    );
                    enumerate_indices[index] = name;
                    enumerate_items[index] = item_name;
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .zip => |zip| {
                    const index_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_index_{d}", .{index}),
                    );
                    const right_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_right_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_item_{d}", .{index}),
                    );
                    zip_indices[index] = index_name;
                    zip_rights[index] = right_name;
                    zip_items[index] = item_name;
                    zip_right_by_ref[index] = try self.iteratorSourceByReference(zip.other);
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = right_name,
                        .init = try self.lowerIteratorSource(zip.other),
                    } });
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = index_name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .range_rev => if (index != 0) return error.UnsupportedIteratorAdapter,
                .map, .filter, .flat_map => {},
                .other => return error.UnsupportedIteratorAdapter,
            }
        }

        const reverse = if (chain.adapters.len > 0) switch (chain.adapters[0]) {
            .range_rev => true,
            else => false,
        } else false;
        const source_is_range = chain.source < self.ir.bodies.exprs.len and
            self.ir.bodies.exprs[chain.source].kind == .range;
        const source = if (source_is_range)
            @as(?ast.Expr, null)
        else
            try self.lowerIteratorSource(chain.source);
        const source_by_ref = if (source_is_range)
            false
        else
            try self.iteratorSourceByReference(chain.source);
        const state: IteratorStructuralState = .{
            .enumerate_indices = enumerate_indices,
            .enumerate_items = enumerate_items,
            .zip_indices = zip_indices,
            .zip_rights = zip_rights,
            .zip_items = zip_items,
            .zip_right_by_ref = zip_right_by_ref,
        };
        const previous_iterator_prelude = self.current_iterator_capture_prelude;
        self.current_iterator_capture_prelude = &prefix;
        defer self.current_iterator_capture_prelude = previous_iterator_prelude;
        var loop_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer loop_stmts.deinit(self.alloc);
        // The loop itself goes inside the labelled block every exit names, so
        // it is built apart from the adapter bindings that have to stay outside
        // that block and in scope for the tail below.
        var loop_scope: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer loop_scope.deinit(self.alloc);
        if (source_is_range) {
            const lowered_range = try self.lowerIteratorRange(chain.source);
            const direction: IteratorRangeDirection = if (reverse) .reverse else .forward;
            const range_loop = try self.appendIteratorRangeSetup(
                lowered_range,
                direction,
                &prefix,
            );
            try self.appendIteratorCollectionTail(
                chain,
                if (reverse) 1 else 0,
                range_loop.item,
                collector,
                owner_name,
                state,
                &loop_stmts,
            );
            try self.appendIteratorRangeLoop(range_loop, loop_stmts.items, &loop_scope, null);
        } else {
            if (reverse) return error.UnsupportedIteratorAdapter;
            const item_name = try self.iteratorTemporaryName("__r2z_item");
            try self.appendIteratorCollectionTail(
                chain,
                0,
                .{ .ident = item_name },
                collector,
                owner_name,
                state,
                &loop_stmts,
            );
            const inputs = try self.alloc.alloc(ast.Expr, 1);
            // A user-defined `Iterator` is driven through `next()`, exactly
            // as in a plain `for` loop over the same value.
            const source_is_user_iterator = if (try self.exprType(chain.source)) |value|
                isUserIteratorType(self, value)
            else
                false;
            if (source_is_user_iterator) {
                const iterator_args = try self.alloc.alloc(ast.Expr, 1);
                iterator_args[0] = source.?;
                inputs[0] = .{ .builtin = .{
                    .name = "iteratorValue",
                    .args = iterator_args,
                } };
            } else {
                inputs[0] = source.?;
            }
            const captures = try self.alloc.alloc(ast.Capture, 1);
            captures[0] = .{ .name = item_name, .by_ref = source_by_ref };
            try loop_scope.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .for_expr = .{
                .inputs = inputs,
                .captures = captures,
                .body = .{ .stmts = try loop_stmts.toOwnedSlice(self.alloc) },
            } }) });
        }
        try self.appendCollectLoopStatement(
            collector,
            try loop_scope.toOwnedSlice(self.alloc),
            &prefix,
        );

        // The error local comes before the loop, so the loop can record an
        // item error and leave, and the block's own value reports it.
        //
        // The owner is released exactly once on every path out: `errdefer`
        // covers an allocation failure while the loop runs, the `Err` arm
        // below releases what the prefix accumulated, and the `Ok` arm hands
        // the buffer to the caller instead of dropping it. An empty collect
        // and a full one both reach the `Ok` arm with nothing released.
        const error_local: usize = if (collector.result != null) 1 else 0;
        const statements = try self.alloc.alloc(ast.Stmt, prefix.items.len + 2 + error_local);
        statements[0] = .{ .let_stmt = .{
            .name = owner_name,
            .ty = owner_type,
            .init = owner_init,
            .is_mut = true,
        } };
        // `errdefer`, not `defer`: on the way out the block hands the
        // collection to its caller, which owns it from then on. Only an
        // allocation failure while building it still has to release what was
        // appended so far.
        statements[1] = .{ .defer_stmt = .{
            .expr = try self.collectorDeinit(owner_name),
            .is_errdefer = true,
        } };
        var at: usize = 2;
        if (collector.result) |arms| {
            statements[at] = .{ .let_stmt = .{
                .name = collector.error_name,
                .ty = .{ .opt = try self.allocType(try self.lowerType(arms.result.err)) },
                .init = .{ .lit = .null_lit },
                .is_mut = true,
            } };
            at += 1;
        }
        @memcpy(statements[at..], prefix.items);
        return .{
            .stmts = statements,
            .expr = try self.allocExpr(if (collector.result != null)
                try self.collectorResultTail(collector, owner_name)
            else
                .{ .ident = owner_name }),
        };
    }

    const IteratorForSink = struct {
        pattern: ir.exprs.NodeId,
        body: ast.Block,
    };

    fn appendIteratorForTail(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        adapter_index: usize,
        item: ast.Expr,
        sink: IteratorForSink,
        state: IteratorStructuralState,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (adapter_index == chain.adapters.len) {
            try self.appendIteratorClosureBindings(sink.pattern, item, statements);
            try statements.appendSlice(self.alloc, sink.body.stmts);
            if (sink.body.expr) |tail| {
                try statements.append(self.alloc, .{ .expr_stmt = tail });
            }
            return;
        }
        switch (chain.adapters[adapter_index]) {
            .map => |map| {
                const mapped = try self.lowerIteratorClosureBodyWithSnapshots(map.closure);
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                const mapped_value = try self.materializeIteratorItem(mapped, false, &nested, null);
                try self.appendIteratorForTail(
                    chain,
                    adapter_index + 1,
                    mapped_value,
                    sink,
                    state,
                    &nested,
                );
                try self.appendIteratorClosureScope(map.closure, item, nested.items, statements);
            },
            .filter => |filter| {
                const predicate = try self.lowerIteratorClosureBodyWithSnapshots(filter.closure);
                var then_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer then_stmts.deinit(self.alloc);
                try self.appendIteratorForTail(
                    chain,
                    adapter_index + 1,
                    item,
                    sink,
                    state,
                    &then_stmts,
                );
                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try then_stmts.toOwnedSlice(self.alloc),
                } });
                const if_expr = try self.allocExpr(.{ .if_expr = .{
                    .cond = try self.allocExpr(predicate),
                    .then_body = then_body,
                } });
                const predicate_stmt = [_]ast.Stmt{.{ .expr_stmt = if_expr }};
                try self.appendIteratorClosureScope(filter.closure, .{ .unary_op = .{
                    .op = .addr_of,
                    .operand = try self.allocExpr(item),
                } }, &predicate_stmt, statements);
            },
            .flat_map => |closure| {
                if (self.iteratorRangeTail(closure)) |range_tail| {
                    var range_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer range_stmts.deinit(self.alloc);
                    const lowered_range = try self.lowerIteratorClosureRangeTail(
                        closure,
                        range_tail,
                        &range_stmts,
                    );
                    const range_loop = try self.appendIteratorRangeSetup(
                        lowered_range,
                        .forward,
                        &range_stmts,
                    );
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorForTail(
                        chain,
                        adapter_index + 1,
                        range_loop.item,
                        sink,
                        state,
                        &inner_stmts,
                    );
                    try self.appendIteratorRangeLoop(
                        range_loop,
                        inner_stmts.items,
                        &range_stmts,
                        null,
                    );
                    try self.appendIteratorClosureScope(
                        closure,
                        item,
                        range_stmts.items,
                        statements,
                    );
                } else {
                    const iterable = try self.lowerIteratorClosureBodyWithSnapshots(closure);
                    const inner_name = try self.iteratorTemporaryName("__r2z_flat_item");
                    var inner_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer inner_stmts.deinit(self.alloc);
                    try self.appendIteratorForTail(
                        chain,
                        adapter_index + 1,
                        .{ .ident = inner_name },
                        sink,
                        state,
                        &inner_stmts,
                    );
                    const inputs = try self.alloc.alloc(ast.Expr, 1);
                    inputs[0] = iterable;
                    const captures = try self.alloc.alloc(ast.Capture, 1);
                    captures[0] = .{ .name = inner_name };
                    const inner_loop = try self.allocExpr(.{ .for_expr = .{
                        .inputs = inputs,
                        .captures = captures,
                        .body = .{ .stmts = try inner_stmts.toOwnedSlice(self.alloc) },
                    } });
                    const inner_stmt = [_]ast.Stmt{.{ .expr_stmt = inner_loop }};
                    try self.appendIteratorClosureScope(closure, item, &inner_stmt, statements);
                }
            },
            .enumerate => {
                const index_name = state.enumerate_indices[adapter_index];
                const stage_name = state.enumerate_items[adapter_index];
                if (index_name.len == 0 or stage_name.len == 0) return error.UnsupportedIteratorAdapter;
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = .{ .ident = index_name };
                tuple_items[1] = item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorForTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    sink,
                    state,
                    &nested,
                );
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } }) });
            },
            .zip => {
                const index_name = state.zip_indices[adapter_index];
                const right_name = state.zip_rights[adapter_index];
                const stage_name = state.zip_items[adapter_index];
                if (index_name.len == 0 or right_name.len == 0 or stage_name.len == 0) {
                    return error.UnsupportedIteratorAdapter;
                }
                const right_len = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = right_name }),
                    .field_name = "len",
                } });
                const condition = try self.allocExpr(.{ .bin_op = .{
                    .op = .less_than,
                    .lhs = try self.allocExpr(.{ .ident = index_name }),
                    .rhs = right_len,
                } });
                const right_args = try self.alloc.alloc(ast.Expr, 2);
                right_args[0] = .{ .ident = right_name };
                right_args[1] = .{ .ident = index_name };
                var right_item: ast.Expr = .{ .builtin = .{
                    .name = "index",
                    .args = right_args,
                } };
                if (state.zip_right_by_ref[adapter_index]) {
                    right_item = .{ .unary_op = .{
                        .op = .addr_of,
                        .operand = try self.allocExpr(right_item),
                    } };
                }
                const tuple_items = try self.alloc.alloc(ast.Expr, 2);
                tuple_items[0] = item;
                tuple_items[1] = right_item;
                var nested: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer nested.deinit(self.alloc);
                try nested.append(self.alloc, .{ .let_stmt = .{
                    .name = stage_name,
                    .init = .{ .tuple = tuple_items },
                } });
                try nested.append(self.alloc, .{ .assign = .{
                    .target = .{ .ident = index_name },
                    .val = .{ .lit = .{ .int = 1 } },
                    .op = .add_assign,
                } });
                try self.appendIteratorForTail(
                    chain,
                    adapter_index + 1,
                    .{ .ident = stage_name },
                    sink,
                    state,
                    &nested,
                );

                const then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try nested.toOwnedSlice(self.alloc),
                } });
                try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
                    .cond = condition,
                    .then_body = then_body,
                } }) });
            },
            .range_rev, .other => return error.UnsupportedIteratorAdapter,
        }
    }
    fn lowerIteratorAdapterForBlock(
        self: *Lowerer,
        chain: ir.exprs.IteratorChainExpr,
        pattern_id: ir.exprs.NodeId,
        body_expr: ir.exprs.BlockExpr,
    ) anyerror!ast.Expr {
        const adapter_count = chain.adapters.len;
        const enumerate_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_indices);
        const enumerate_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(enumerate_items);
        const zip_indices = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_indices);
        const zip_rights = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_rights);
        const zip_items = try self.alloc.alloc([]const u8, adapter_count);
        defer self.alloc.free(zip_items);
        const zip_right_by_ref = try self.alloc.alloc(bool, adapter_count);
        defer self.alloc.free(zip_right_by_ref);
        for (enumerate_indices, 0..) |*name, index| {
            name.* = &.{};
            enumerate_items[index] = &.{};
            zip_indices[index] = &.{};
            zip_rights[index] = &.{};
            zip_items[index] = &.{};
            zip_right_by_ref[index] = false;
        }

        var prefix: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prefix.deinit(self.alloc);
        for (chain.adapters, 0..) |adapter, index| {
            switch (adapter) {
                .enumerate => {
                    const index_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_index_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_enumerate_item_{d}", .{index}),
                    );
                    enumerate_indices[index] = index_name;
                    enumerate_items[index] = item_name;
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = index_name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .zip => |zip| {
                    const index_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_index_{d}", .{index}),
                    );
                    const right_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_right_{d}", .{index}),
                    );
                    const item_name = try self.iteratorTemporaryName(
                        try std.fmt.allocPrint(self.alloc, "__r2z_zip_item_{d}", .{index}),
                    );
                    zip_indices[index] = index_name;
                    zip_rights[index] = right_name;
                    zip_items[index] = item_name;
                    zip_right_by_ref[index] = try self.iteratorSourceByReference(zip.other);
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = right_name,
                        .init = try self.lowerIteratorSource(zip.other),
                    } });
                    try prefix.append(self.alloc, .{ .let_stmt = .{
                        .name = index_name,
                        .ty = .{ .prim = .usize },
                        .init = .{ .lit = .{ .int = 0 } },
                        .is_mut = true,
                    } });
                },
                .range_rev => if (index != 0) return error.UnsupportedIteratorAdapter,
                .map, .filter, .flat_map => {},
                .other => return error.UnsupportedIteratorAdapter,
            }
        }

        var binding_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer binding_names.deinit(self.alloc);
        try self.appendIteratorClosurePatternNames(pattern_id, &binding_names);
        const previous_capture_names = self.current_capture_names;
        const capture_names = try self.alloc.alloc(
            []const u8,
            previous_capture_names.len + binding_names.items.len,
        );
        defer self.alloc.free(capture_names);
        @memcpy(capture_names[0..previous_capture_names.len], previous_capture_names);
        @memcpy(capture_names[previous_capture_names.len..], binding_names.items);
        self.current_capture_names = capture_names;
        defer self.current_capture_names = previous_capture_names;

        const previous_value_capture_scopes = self.current_value_capture_scopes;
        const value_capture_scopes = try self.alloc.alloc(
            ValueCaptureScope,
            previous_value_capture_scopes.len + 1,
        );
        defer self.alloc.free(value_capture_scopes);
        @memcpy(
            value_capture_scopes[0..previous_value_capture_scopes.len],
            previous_value_capture_scopes,
        );
        value_capture_scopes[previous_value_capture_scopes.len] = .{
            .names = binding_names.items,
            .value_name = try self.valueCaptureName(pattern_id),
        };
        self.current_value_capture_scopes = value_capture_scopes;
        defer self.current_value_capture_scopes = previous_value_capture_scopes;

        const sink: IteratorForSink = .{
            .pattern = pattern_id,
            .body = try self.lowerBlock(body_expr),
        };
        const item_name = try self.iteratorTemporaryName("__r2z_item");

        const state: IteratorStructuralState = .{
            .enumerate_indices = enumerate_indices,
            .enumerate_items = enumerate_items,
            .zip_indices = zip_indices,
            .zip_rights = zip_rights,
            .zip_items = zip_items,
            .zip_right_by_ref = zip_right_by_ref,
        };
        const previous_iterator_prelude = self.current_iterator_capture_prelude;
        self.current_iterator_capture_prelude = &prefix;
        defer self.current_iterator_capture_prelude = previous_iterator_prelude;
        const source_is_range = chain.source < self.ir.bodies.exprs.len and
            self.ir.bodies.exprs[chain.source].kind == .range;
        const source = if (source_is_range)
            @as(?ast.Expr, null)
        else
            try self.lowerIteratorSource(chain.source);
        const source_by_ref = if (source_is_range)
            false
        else
            try self.iteratorSourceByReference(chain.source);
        var loop_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer loop_stmts.deinit(self.alloc);
        const reverse = if (chain.adapters.len > 0) switch (chain.adapters[0]) {
            .range_rev => true,
            else => false,
        } else false;
        if (source_is_range) {
            const lowered_range = try self.lowerIteratorRange(chain.source);
            const direction: IteratorRangeDirection = if (reverse) .reverse else .forward;
            const range_loop = try self.appendIteratorRangeSetup(
                lowered_range,
                direction,
                &prefix,
            );
            try self.appendIteratorForTail(
                chain,
                if (reverse) 1 else 0,
                range_loop.item,
                sink,
                state,
                &loop_stmts,
            );
            try self.appendIteratorRangeLoop(range_loop, loop_stmts.items, &prefix, null);
        } else {
            if (reverse) return error.UnsupportedIteratorAdapter;
            try self.appendIteratorForTail(
                chain,
                0,
                .{ .ident = item_name },
                sink,
                state,
                &loop_stmts,
            );
            const inputs = try self.alloc.alloc(ast.Expr, 1);
            inputs[0] = source.?;
            const captures = try self.alloc.alloc(ast.Capture, 1);
            captures[0] = .{ .name = item_name, .by_ref = source_by_ref };
            try prefix.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .for_expr = .{
                .inputs = inputs,
                .captures = captures,
                .body = .{ .stmts = try loop_stmts.toOwnedSlice(self.alloc) },
            } }) });
        }
        return .{ .block = .{
            .stmts = try prefix.toOwnedSlice(self.alloc),
        } };
    }

    fn matchIteratorTerminal(
        self: *Lowerer,
        body_id: ir.exprs.NodeId,
        terminal: ir.exprs.IteratorTerminal,
    ) ?ir.exprs.IteratorChainExpr {
        if (body_id >= self.ir.bodies.exprs.len) return null;
        const body = switch (self.ir.bodies.exprs[body_id].kind) {
            .block => |value| value,
            else => return null,
        };
        if (body.statements.len != 0 or body.labelled != null) return null;
        const tail_id = body.tail orelse return null;
        if (tail_id >= self.ir.bodies.exprs.len) return null;
        const chain = switch (self.ir.bodies.exprs[tail_id].kind) {
            .iterator_chain => |value| value,
            else => return null,
        };
        return if (chain.terminal == terminal) chain else null;
    }

    fn matchOwnedCollection(
        self: *Lowerer,
        body_id: ir.exprs.NodeId,
        return_type: ir.types.Type,
        is_allocating: bool,
    ) ?OwnedCollectionPlan {
        if (!is_allocating) return null;
        if (!isPlainU8VecType(return_type)) return null;
        if (body_id >= self.ir.bodies.exprs.len) return null;

        const body = switch (self.ir.bodies.exprs[body_id].kind) {
            .block => |value| value,
            else => return null,
        };
        if (body.statements.len != 0 or body.labelled != null) return null;
        const tail_id = body.tail orelse return null;
        if (tail_id >= self.ir.bodies.exprs.len) return null;
        const chain = switch (self.ir.bodies.exprs[tail_id].kind) {
            .iterator_chain => |value| value,
            else => return null,
        };
        if (chain.terminal != .collect_vec or chain.adapters.len != 1) return null;
        const closure = switch (chain.adapters[0]) {
            .flat_map => |value| value,
            else => return null,
        };
        if (chain.source >= self.ir.bodies.exprs.len) return null;
        const range = switch (self.ir.bodies.exprs[chain.source].kind) {
            .range => |value| value,
            else => return null,
        };
        if (range.inclusive) return null;
        if (range.start >= self.ir.bodies.exprs.len) return null;
        const range_end = range.end orelse return null;
        if (range_end >= self.ir.bodies.exprs.len) return null;

        if (closure.trait != .@"fn" or closure.captures.len != 1) return null;
        const capture = closure.captures[0];
        if (capture.name.len == 0 or capture.mode != .by_ref) return null;
        if (!self.isConstU8SliceType(capture.ty)) return null;
        if (closure.params.len != 1) return null;
        if (closure.params[0] >= self.ir.bodies.pats.len) return null;
        const item_name = switch (self.ir.bodies.pats[closure.params[0]].kind) {
            .wildcard => "_",
            .binding => |value| blk: {
                if (value.name.len == 0 or value.mutable) return null;
                switch (value.mode) {
                    .value => {},
                    else => return null,
                }
                break :blk value.name;
            },
            else => return null,
        };
        if (closure.body.statements.len != 0 or closure.body.labelled != null) return null;
        const closure_tail = closure.body.tail orelse return null;
        const source_id = self.ownedCollectionCapturePath(closure_tail, capture.name) orelse return null;

        return .{
            .range_id = chain.source,
            .source_id = source_id,
            .item_name = item_name,
        };
    }

    fn lowerOwnedCollectionReturnType(
        self: *Lowerer,
        return_type: ir.types.Type,
    ) !ast.Type {
        const payload = try self.allocType(try self.lowerType(return_type));
        return .{ .err_union = .{
            .err_set = null,
            .payload = payload,
        } };
    }

    fn appendCollectorStmtIdentifiers(
        self: *Lowerer,
        stmt: ast.Stmt,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        switch (stmt) {
            .let_stmt => |let_stmt| {
                try reserved.append(self.alloc, let_stmt.name);
                try self.appendCollectorExprIdentifiers(let_stmt.init, reserved);
            },
            .assign => |assign| {
                try self.appendCollectorExprIdentifiers(assign.target, reserved);
                try self.appendCollectorExprIdentifiers(assign.val, reserved);
            },
            .defer_stmt => |defer_stmt| {
                try self.appendCollectorExprIdentifiers(defer_stmt.expr, reserved);
            },
            .expr_stmt => |expr| {
                try self.appendCollectorExprIdentifiers(expr.*, reserved);
            },
        }
    }
    fn appendShadowBindingName(
        self: *Lowerer,
        stmt: ast.Stmt,
        names: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        switch (stmt) {
            .let_stmt => |let_stmt| try names.append(self.alloc, let_stmt.name),
            else => {},
        }
    }

    fn appendPatternBindingName(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        if (pat_id >= self.ir.bodies.pats.len) return;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .binding => |binding| try reserved.append(self.alloc, binding.name),
            .external_variant => |variant| for (variant.fields) |field| {
                if (field.pat) |pattern| {
                    try self.appendPatternBindingName(pattern, reserved);
                } else if (field.shorthand) {
                    try reserved.append(self.alloc, field.field);
                }
            },
            .reference => |reference| try self.appendPatternBindingName(reference.inner, reserved),
            .tuple => |tuple| for (tuple.elements) |element| {
                try self.appendPatternBindingName(element, reserved);
            },
            .slice => |slice| {
                for (slice.elements) |element| {
                    try self.appendPatternBindingName(element, reserved);
                }
                if (slice.rest) |rest| try self.appendPatternBindingName(rest, reserved);
            },
            .struct_pat => |struct_pat| for (struct_pat.fields) |field| {
                if (field.pat) |field_pat| {
                    try self.appendPatternBindingName(field_pat, reserved);
                } else if (field.shorthand) {
                    try reserved.append(self.alloc, field.field);
                }
            },
            .@"or" => |or_pattern| for (or_pattern.alternatives) |alternative| {
                try self.appendPatternBindingName(alternative, reserved);
            },
            else => {},
        }
    }

    fn appendBlockBindingNames(
        self: *Lowerer,
        statement_ids: []const ir.exprs.NodeId,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        for (statement_ids) |stmt_id| {
            if (stmt_id >= self.ir.bodies.stmts.len) continue;
            switch (self.ir.bodies.stmts[stmt_id].kind) {
                .let => |let_stmt| try self.appendPatternBindingName(let_stmt.pattern, reserved),
                .let_else => |let_else| try self.appendPatternBindingName(let_else.pattern, reserved),
                else => {},
            }
        }
    }

    fn appendCollectorBlockIdentifiers(
        self: *Lowerer,
        block: ast.Block,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        for (block.stmts) |stmt| {
            try self.appendCollectorStmtIdentifiers(stmt, reserved);
        }
        if (block.expr) |expr| {
            try self.appendCollectorExprIdentifiers(expr.*, reserved);
        }
    }

    fn ensureErrorUnion(self: *Lowerer, ty: ast.Type) !ast.Type {
        return switch (ty) {
            .err_union => ty,
            else => .{ .err_union = .{
                .err_set = null,
                .payload = try self.allocType(ty),
            } },
        };
    }

    fn paramsWithAllocator(
        self: *Lowerer,
        params: []const ast.FnParam,
        position: usize,
    ) ![]const ast.FnParam {
        if (position > params.len) return error.InvalidAllocatorPosition;
        const result = try self.alloc.alloc(ast.FnParam, params.len + 1);
        @memcpy(result[0..position], params[0..position]);
        result[position] = .{
            .name = "allocator",
            .ty = ast.Type{ .named = "std.mem.Allocator" },
        };
        @memcpy(result[position + 1 ..], params[position..]);
        return result;
    }

    fn appendCollectorExprIdentifiers(
        self: *Lowerer,
        expr: ast.Expr,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) std.mem.Allocator.Error!void {
        switch (expr) {
            .lit, .unit, .unsupported, .panic_, .type_value => {},
            .ident => |name| try reserved.append(self.alloc, name),
            .field_access => |field_access| {
                try self.appendCollectorExprIdentifiers(field_access.target.*, reserved);
            },
            .call => |call| {
                try self.appendCollectorExprIdentifiers(call.callee.*, reserved);
                for (call.args) |arg| {
                    try self.appendCollectorExprIdentifiers(arg, reserved);
                }
            },
            .block => |block| try self.appendCollectorBlockIdentifiers(block, reserved),
            .match_expr => |match| {
                try self.appendCollectorExprIdentifiers(match.target.*, reserved);
                for (match.arms) |arm| {
                    try self.appendCollectorExprIdentifiers(arm.body, reserved);
                }
            },
            .bin_op => |bin_op| {
                try self.appendCollectorExprIdentifiers(bin_op.lhs.*, reserved);
                try self.appendCollectorExprIdentifiers(bin_op.rhs.*, reserved);
            },
            .unary_op => |unary_op| {
                try self.appendCollectorExprIdentifiers(unary_op.operand.*, reserved);
            },
            .cast => |cast| {
                try self.appendCollectorExprIdentifiers(cast.operand.*, reserved);
            },
            .struct_init => |struct_init| {
                for (struct_init.fields) |field| {
                    try self.appendCollectorExprIdentifiers(field.expr, reserved);
                }
            },
            .array_init => |array_init| {
                for (array_init.elements) |element| {
                    try self.appendCollectorExprIdentifiers(element, reserved);
                }
            },
            .repeat => |repeat| {
                try self.appendCollectorExprIdentifiers(repeat.elem.*, reserved);
            },
            .multi_array => |multi_array| {
                for (multi_array.elements) |element| {
                    try self.appendCollectorExprIdentifiers(element, reserved);
                }
            },
            .tuple => |elements| {
                for (elements) |element| {
                    try self.appendCollectorExprIdentifiers(element, reserved);
                }
            },
            .builtin => |builtin| {
                for (builtin.args) |arg| {
                    try self.appendCollectorExprIdentifiers(arg, reserved);
                }
            },
            .if_expr => |if_expr| {
                try self.appendCollectorExprIdentifiers(if_expr.cond.*, reserved);
                try self.appendCollectorExprIdentifiers(if_expr.then_body.*, reserved);
                if (if_expr.else_body) |else_body| {
                    try self.appendCollectorExprIdentifiers(else_body.*, reserved);
                }
            },
            .while_expr => |while_expr| {
                try self.appendCollectorExprIdentifiers(while_expr.cond.*, reserved);
                try self.appendCollectorBlockIdentifiers(while_expr.body, reserved);
                if (while_expr.else_body) |else_body| {
                    try self.appendCollectorExprIdentifiers(else_body.*, reserved);
                }
            },
            .for_expr => |for_expr| {
                for (for_expr.inputs) |input| {
                    try self.appendCollectorExprIdentifiers(input, reserved);
                }
                try self.appendCollectorBlockIdentifiers(for_expr.body, reserved);
                if (for_expr.else_body) |else_body| {
                    try self.appendCollectorExprIdentifiers(else_body.*, reserved);
                }
            },
            .range => |range| {
                try self.appendCollectorExprIdentifiers(range.start.*, reserved);
                if (range.end) |end| {
                    try self.appendCollectorExprIdentifiers(end.*, reserved);
                }
            },
            .return_expr => |value| {
                if (value) |expr_ptr| {
                    try self.appendCollectorExprIdentifiers(expr_ptr.*, reserved);
                }
            },
            .break_expr => |break_expr| {
                if (break_expr.value) |expr_ptr| {
                    try self.appendCollectorExprIdentifiers(expr_ptr.*, reserved);
                }
            },
            // A labelled `continue` names a loop that already exists, so the
            // label binds nothing to reserve and there is no value to visit.
            .continue_expr, .unreachable_ => {},
        }
    }

    fn appendCollectorImportAliases(
        self: *Lowerer,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        if (self.current_imports) |imports| {
            for (imports.items) |import| {
                try reserved.append(self.alloc, import.local_name);
            }
        }
    }

    fn collectorBindingName(
        self: *Lowerer,
        base_name: []const u8,
        reserved: []const []const u8,
    ) ![]const u8 {
        var candidate = base_name;
        var suffix: usize = 1;
        while (true) {
            var taken = false;
            for (reserved) |name| {
                if (std.mem.eql(u8, name, candidate)) {
                    taken = true;
                    break;
                }
            }
            if (!taken) return candidate;
            candidate = try std.fmt.allocPrint(self.alloc, "{s}_{d}", .{ base_name, suffix });
            suffix += 1;
        }
    }

    /// Remember that `stmts` is the statement list of an owner prelude, so the
    /// places that flatten a prelude can recognise it by this identity rather
    /// than by the `let`/`defer` shape every scope-released block also has.
    fn recordOwnerPrelude(self: *Lowerer, stmts: []const ast.Stmt) !void {
        try self.owner_prelude_stmts.put(self.alloc, @intFromPtr(stmts.ptr), stmts.len);
    }

    /// Whether this block's statement list IS an owner prelude, asked by
    /// identity.
    fn isOwnerPrelude(self: *const Lowerer, stmts: []const ast.Stmt) bool {
        if (stmts.len == 0) return false;
        const recorded = self.owner_prelude_stmts.get(@intFromPtr(stmts.ptr)) orelse return false;
        return recorded == stmts.len;
    }

    fn lowerOwnedCollectionBlock(
        self: *Lowerer,
        plan: OwnedCollectionPlan,
        return_type: ir.types.Type,
        params: []const ast.FnParam,
        declaration_name: []const u8,
    ) !ast.Block {
        const owner_type = try self.lowerType(return_type);
        const lowered_range = try self.lowerIteratorRange(plan.range_id);
        const source = try self.lowerExpr(plan.source_id);

        var reserved_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer reserved_names.deinit(self.alloc);
        for (params) |param| {
            try reserved_names.append(self.alloc, param.name);
        }
        try reserved_names.append(self.alloc, declaration_name);
        try self.appendCollectorExprIdentifiers(source, &reserved_names);
        try reserved_names.append(self.alloc, plan.item_name);
        try self.appendCollectorExprIdentifiers(lowered_range.start, &reserved_names);
        try self.appendCollectorExprIdentifiers(lowered_range.end, &reserved_names);
        try self.appendCollectorImportAliases(&reserved_names);

        const owner_name = try self.collectorBindingName("owner", reserved_names.items);
        try reserved_names.append(self.alloc, owner_name);
        const byte_name = try self.collectorBindingName("_byte", reserved_names.items);

        const owner_generic = switch (owner_type) {
            .generic => |generic| generic,
            else => unreachable,
        };
        const owner_type_expr = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = owner_generic.name }),
            .generic_args = owner_generic.params,
            .args = &.{},
        } });
        const owner_init: ast.Expr = .{ .field_access = .{
            .target = owner_type_expr,
            .field_name = "empty",
        } };

        const append_target = try self.allocExpr(.{ .ident = owner_name });
        const append_callee = try self.allocExpr(.{ .field_access = .{
            .target = append_target,
            .field_name = "append",
        } });
        const append_args = try self.alloc.alloc(ast.Expr, 2);
        append_args[0] = .{ .ident = "allocator" };
        append_args[1] = .{ .ident = byte_name };
        const append_call = try self.allocExpr(.{ .call = .{
            .callee = append_callee,
            .args = append_args,
        } });
        const append_try = try self.allocExpr(.{ .unary_op = .{
            .op = .try_op,
            .operand = append_call,
        } });
        const inner_stmts = try self.alloc.alloc(ast.Stmt, 1);
        inner_stmts[0] = .{ .expr_stmt = append_try };
        const inner_inputs = try self.alloc.alloc(ast.Expr, 1);
        inner_inputs[0] = source;
        const inner_captures = try self.alloc.alloc(ast.Capture, 1);
        inner_captures[0] = .{ .name = byte_name };
        const inner_loop = try self.allocExpr(.{ .for_expr = .{
            .inputs = inner_inputs,
            .captures = inner_captures,
            .body = .{ .stmts = inner_stmts },
        } });
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = owner_name,
            .ty = owner_type,
            .init = owner_init,
            .is_mut = true,
        } });
        try statements.append(self.alloc, .{ .defer_stmt = .{
            .expr = .{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = owner_name }),
                    .field_name = "deinit",
                } }),
                .args = &.{.{ .ident = "allocator" }},
            } },
            .is_errdefer = true,
        } });
        const range_loop = try self.appendIteratorRangeSetup(
            lowered_range,
            .forward,
            &statements,
        );
        const outer_body = [_]ast.Stmt{.{ .expr_stmt = inner_loop }};
        try self.appendIteratorRangeLoop(range_loop, &outer_body, &statements, null);
        return .{
            .stmts = try statements.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(.{ .ident = owner_name }),
        };
    }
    fn lowerFnEntity(self: *Lowerer, entity_id: ir.spine.EntityId, ent: ir.spine.Entity) !ast.FnDecl {
        const previous_module_id = self.current_module_id;
        self.current_module_id = (try self.owningModuleEntity(entity_id)) orelse previous_module_id;
        defer self.current_module_id = previous_module_id;
        const previous_struct_id = self.current_struct_id;
        self.current_struct_id =
            (try self.inherentStructForEntity(entity_id)) orelse previous_struct_id;
        defer self.current_struct_id = previous_struct_id;
        const previous_callable_name = self.current_callable_name;
        self.current_callable_name = ent.name;
        defer self.current_callable_name = previous_callable_name;
        self.local_closures.clearRetainingCapacity();
        self.clearLocalClosureSnapshots();
        self.active_closure_capture_overrides.clearRetainingCapacity();
        self.current_iterator_capture_prelude = null;
        self.next_iterator_capture_id = 0;

        const is_pub = switch (ent.visibility) {
            .public, .crate_restricted, .super_restricted, .in_path => true,
            // Rust `private` means "this module and its descendants". Zig files
            // are hard module boundaries, so a descendant Rust module becomes a
            // sibling file that cannot see a non-`pub` item.
            .private => self.privateItemIsPublished(entity_id),
        };

        if (entity_id >= self.ir.bodies.bodies.len) {
            return error.MissingBodyId;
        }
        const body_kind = self.ir.bodies.bodies[entity_id];

        var local_binding_names: LocalBindingNames = .{};
        try self.prepareLocalBindingNames(entity_id, &local_binding_names);
        defer local_binding_names.deinit(self.alloc);
        const previous_local_binding_names = self.current_local_binding_names;
        self.current_local_binding_names = &local_binding_names;
        defer self.current_local_binding_names = previous_local_binding_names;

        const previous_callable_id = self.current_callable_id;
        self.current_callable_id = entity_id;
        defer self.current_callable_id = previous_callable_id;
        var params_list: std.ArrayListUnmanaged(ast.FnParam) = .empty;
        var ret_type: ast.Type = ast.Type{ .void_type = {} };
        var fn_block: ?ast.Block = null;
        var callable_is_allocating = false;
        var allocator_param_index: usize = 0;
        var has_allocator_param = false;
        switch (body_kind) {
            .fn_ => |fb| {
                const previous_callable_effect = self.current_callable_is_allocating;
                const stable_callable_effect = self.callPassesAllocator(entity_id);
                if (stable_callable_effect and self.formattingMethodName(ent) != null) {
                    return error.UnsupportedAllocatingFormatter;
                }
                self.current_callable_is_allocating = stable_callable_effect;
                defer self.current_callable_is_allocating = previous_callable_effect;
                callable_is_allocating = stable_callable_effect;
                // A module-hoisted method declares the impl's own type
                // parameters first: the method's own parameters and its
                // receiver may all name them.
                const impl_generic_params = self.hoisted_impl_generic_params;
                allocator_param_index = impl_generic_params.len + fb.generic_params.len;
                has_allocator_param = stable_callable_effect;
                try self.appendFunctionGenericParams(impl_generic_params, &params_list);
                try self.appendFunctionGenericParams(fb.generic_params, &params_list);
                if (stable_callable_effect) {
                    try params_list.append(self.alloc, .{
                        .name = "allocator",
                        .ty = ast.Type{ .named = "std.mem.Allocator" },
                    });
                }

                var mutable_param_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer mutable_param_stmts.deinit(self.alloc);
                var mutable_copies: std.ArrayListUnmanaged(MutableCopyBinding) = .empty;
                defer mutable_copies.deinit(self.alloc);

                // A by-value owner parameter is an owner this callable OWNS: Rust
                // moved the bytes in, so nobody else releases them and this
                // callable's body has to. Collected here because this is the
                // only point where the parameter's binding entity, its emitted
                // name and its declared type are all in hand together.
                var parameter_owners: std.ArrayListUnmanaged(ParameterOwner) = .empty;
                defer parameter_owners.deinit(self.alloc);
                for (fb.params) |p| {
                    const callable_ty = try self.lowerCallableParamType(p.ty);
                    const p_ty = callable_ty orelse try self.lowerType(p.ty);
                    const param_def = local_binding_names.claimLocal(&self.ir.graph.symbol_table, p.name);
                    const param_name = if (param_def) |d|
                        local_binding_names.emitted_by_entity.get(d) orelse p.name
                    else
                        p.name;
                    const is_mut_assigned = if (param_def) |d|
                        try self.isParameterAssigned(d)
                    else
                        false;
                    if (param_def) |d| {
                        if (ownsRuntimeTableOrContainer(p.ty)) {
                            try parameter_owners.append(self.alloc, .{
                                .def = d,
                                .alias = .{
                                    .source_name = p.name,
                                    .capture_name = param_name,
                                    .alias_name = param_name,
                                    .payload_type = p.ty,
                                },
                            });
                        }
                    }

                    if (is_mut_assigned or (param_def != null and ownedRuntimeContainerType(p.ty))) {
                        const sig_name = try self.mutableCopyParamName(
                            &local_binding_names,
                            &mutable_copies,
                            param_name,
                        );
                        try params_list.append(self.alloc, .{
                            .name = sig_name,
                            .ty = p_ty,
                        });
                        try mutable_param_stmts.append(self.alloc, try self.mutableParameterCopy(
                            &mutable_copies.items[mutable_copies.items.len - 1],
                            p_ty,
                            p.ty,
                            param_def.?,
                        ));
                    } else {
                        try params_list.append(self.alloc, .{
                            .name = try self.alloc.dupe(u8, param_name),
                            .ty = p_ty,
                        });
                    }
                }

                // Installed BEFORE the body lowers. The move sites are keyed by
                // expression id, so a move the lowering had already walked past
                // would never be rewritten and the release would free storage
                // this callable had already given away.
                try self.installParameterOwnerMoves(parameter_owners.items, fb.body);

                // Explicit Rust `-> T` (including `-> ()`) wins. Only when the
                // return type was left implicit (unit) do we try to infer a
                // concrete type from the tail expression so the emitted fn
                // carries a real `ret_type` (e.g. `origin() -> Point`,
                // `area(s) -> f64`).
                // A declared `-> ()` and a declared `impl Trait` that the
                // frontend could not resolve to a concrete type are the same
                // situation: the signature names no type, so the tail decides.
                const ret_needs_tail = (fb.ret == .prim and fb.ret.prim == .unit) or
                    (fb.ret == .@"opaque" and fb.ret.@"opaque".concrete == null);
                const effective_ret = if (ret_needs_tail)
                    if (try self.inferTailReturnType(fb.body)) |t| t else fb.ret
                else
                    fb.ret;
                const iterator_sum = self.matchIteratorTerminal(fb.body, .sum);
                const owned_collection =
                    self.matchOwnedCollection(fb.body, effective_ret, stable_callable_effect);
                const iterator_collection = if (stable_callable_effect)
                    self.matchIteratorTerminal(fb.body, .collect_vec)
                else
                    null;
                ret_type = if (owned_collection != null or iterator_collection != null)
                    try self.lowerOwnedCollectionReturnType(effective_ret)
                else
                    try self.lowerType(effective_ret);
                const previous_return_type = self.current_return_type;
                const previous_parameter_names = self.current_parameter_names;
                self.current_parameter_names = params_list.items;
                defer self.current_parameter_names = previous_parameter_names;
                const previous_mutable_copies = self.current_mutable_copies;
                self.current_mutable_copies = mutable_copies.items;
                defer self.current_mutable_copies = previous_mutable_copies;

                self.current_return_type = effective_ret;
                defer self.current_return_type = previous_return_type;
                const previous_float_context = self.float_context;
                self.float_context = isFloatType(effective_ret);
                defer self.float_context = previous_float_context;

                if (owned_collection) |plan| {
                    fn_block = try self.lowerOwnedCollectionBlock(
                        plan,
                        effective_ret,
                        params_list.items,
                        ent.name,
                    );
                } else if (iterator_collection) |chain| {
                    fn_block = try self.lowerIteratorCollectionBlock(chain, effective_ret);
                } else if (iterator_sum) |chain| {
                    fn_block = try self.lowerIteratorSumBlock(chain, effective_ret);
                } else {
                    if (fb.body >= self.ir.bodies.exprs.len) {
                        return error.MissingExpressionNode;
                    }
                    const expr_node = self.ir.bodies.exprs[fb.body];
                    switch (expr_node.kind) {
                        .block => |be| {
                            // Zig's function body cannot declare a label, and
                            // `lowerBlock` has to know that so a guarded
                            // match keeps its chain whole instead of handing
                            // its label to a scope that cannot take one.
                            self.callable_body_block = true;
                            var body = try self.lowerBlock(be);
                            switch (ret_type) {
                                .void_type => {},
                                else => try promoteTrailingMatch(self, &body),
                            }
                            fn_block = body;
                        },
                        else => {
                            const lowered_e = try self.lowerExpr(fb.body);
                            fn_block = ast.Block{
                                .stmts = &.{},
                                .expr = try self.allocExpr(lowered_e),
                            };
                        },
                    }
                }
                // Emitted BEFORE the mutable copies are spliced in, and both
                // PREPEND: the parameter's defer has to be armed before any body
                // statement runs, and a parameter the body writes needs its
                // `var x = _x;` copy declared BEFORE the defer that names it.
                // Emitting in this order leaves the copies ahead of the
                // releases, which is the only order that is both in scope and
                // not naming something the body has not declared yet.
                if (fn_block != null) {
                    try self.appendParameterOwnerReleases(parameter_owners.items, &fn_block.?);
                }
                if (mutable_param_stmts.items.len > 0 and fn_block != null) {
                    const old_stmts = fn_block.?.stmts;
                    const merged = try self.alloc.alloc(ast.Stmt, mutable_param_stmts.items.len + old_stmts.len);
                    @memcpy(merged[0..mutable_param_stmts.items.len], mutable_param_stmts.items);
                    @memcpy(merged[mutable_param_stmts.items.len..], old_stmts);
                    fn_block.?.stmts = merged;
                }
                callable_is_allocating = self.current_callable_is_allocating;
            },
            else => return error.DeclarationBodyMismatch,
        }

        const final_params = if (callable_is_allocating and !has_allocator_param) blk: {
            const params = try self.paramsWithAllocator(
                params_list.items,
                allocator_param_index,
            );
            params_list.deinit(self.alloc);
            break :blk params;
        } else try params_list.toOwnedSlice(self.alloc);
        if (self.callableFallible(entity_id)) {
            ret_type = try self.ensureErrorUnion(ret_type);
        }

        const body = fn_block orelse return error.EmptyFunctionBody;

        return .{
            .name = try self.alloc.dupe(
                u8,
                self.hoisted_method_names.get(entity_id) orelse ent.name,
            ),
            .documentation = try self.callableDocumentation(
                try self.entityDocumentation(ent),
                final_params,
                ret_type,
            ),
            .is_pub = is_pub,
            .params = final_params,
            .ret_type = ret_type,
            .body = body,
        };
    }

    /// Tree-sitter represents a final Rust match as an expression statement.
    /// Restore value position when the function has a non-void return type.
    ///
    /// A `match` or an `if` IS a legal Zig tail — `return switch (..) {..};` and
    /// `return if (..) a else b;` both parse — so those two are moved up as
    /// they always were. A guarded `match` is neither: it lowers to a LABELLED
    /// block whose arms leave through `break :<label> <value>`, and a labelled
    /// block is legal in Zig only as an `if`/`else` BRANCH. Written as a tail it
    /// is `return <label>: { .. };`, which is not a grammar production at all.
    ///
    /// That is what `bindGuardChainToLocal` exists for, and it is called instead
    /// of moving such a chain into the tail.
    fn promoteTrailingMatch(self: *Lowerer, block: *ast.Block) !void {
        if (block.expr != null) return;
        if (block.stmts.len == 0) return;

        const tail = switch (block.stmts[block.stmts.len - 1]) {
            .expr_stmt => |expr| expr,
            else => return,
        };
        if (isGuardChainBlock(tail.*)) {
            try self.bindGuardChainToLocal(block);
            return;
        }
        if (tail.* != .match_expr and tail.* != .if_expr) return;

        block.stmts = block.stmts[0 .. block.stmts.len - 1];
        block.expr = tail;
    }

    /// Restore value position for a body whose last statement is the ordered
    /// chain a guarded `match` lowers to.
    ///
    /// The chain does NOT go into the tail: see `promoteTrailingMatch`. It is
    /// bound to a local in statement position, and the tail names that local.
    fn promoteGuardChainTail(self: *Lowerer, block: *ast.Block) !void {
        if (block.expr != null) return;
        if (block.stmts.len == 0) return;
        const tail = switch (block.stmts[block.stmts.len - 1]) {
            .expr_stmt => |expr| expr,
            else => return,
        };
        if (!isGuardChainBlock(tail.*)) return;
        try self.bindGuardChainToLocal(block);
    }

    /// Move a trailing guarded-match chain out of tail position by binding it
    /// to a local, so the label never reaches a position that cannot declare it.
    ///
    /// The emitted shape is
    ///
    ///     const __r2z_chain = <label>: { .. break :<label> <value> .. };
    ///     return __r2z_chain;
    ///
    /// and it is the shape the corpus already compiles: the labelled block sits
    /// in a statement's initializer, where the label belongs to the block and
    /// nothing outside it has to resolve the exit, and the value is read back
    /// off a local by name. The chain's own `break :<label>` statements reach
    /// that label because the block is emitted whole, in the position where a
    /// label IS legal — which is the whole difference from promoting it.
    ///
    /// Promoting instead produced `return <label>: { .. };`, which is not a
    /// grammar production: a labelled block is legal only as an `if`/`else`
    /// branch. It failed in BOTH spellings the parenthesised form could be
    /// written in, and it failed a second way as well — the function body's
    /// tail is emitted through `emitExpr`, which builds an empty
    /// `EmitContext`, so the `break :<label>` inside resolved against no exit
    /// scope at all and printed as a BARE `break`.
    ///
    /// No type annotation is written: the block's type is the type its own
    /// `break :<label> <value>` carries, which is the type this tail used to
    /// hand back, so inference reads the same value it always did.
    fn bindGuardChainToLocal(self: *Lowerer, block: *ast.Block) !void {
        const tail = switch (block.stmts[block.stmts.len - 1]) {
            .expr_stmt => |expr| expr,
            else => return error.ExpectedGuardChainTail,
        };
        const name = try self.iteratorTemporaryName("__r2z_chain");
        const kept = block.stmts.len - 1;
        const rebound = try self.alloc.alloc(ast.Stmt, kept + 1);
        @memcpy(rebound[0..kept], block.stmts[0..kept]);
        rebound[kept] = .{ .let_stmt = .{ .name = name, .init = tail.* } };
        block.stmts = rebound;
        block.expr = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) });
    }

    /// Whether this expression is the labeled value block a guarded `match`
    /// lowers to.
    ///
    /// A label alone does not tell it apart — a source block can carry one
    /// too. What no other block has is the `unreachable` that closes the
    /// ordered chain.
    fn isGuardChainBlock(value: ast.Expr) bool {
        const block = switch (value) {
            .block => |inner| inner,
            else => return false,
        };
        if (block.label == null or block.expr != null) return false;
        if (block.stmts.len == 0) return false;
        const last = block.stmts[block.stmts.len - 1];
        return last == .expr_stmt and last.expr_stmt.* == .unreachable_;
    }

    /// Infer a concrete return type from a function body's tail expression when
    /// the return type was left implicit (Rust `-> ()` desugars to unit). Used
    /// only to surface an accurate `ret_type` on the emitted fn; never attempts
    /// full type inference. Returns `null` when the tail is unit/empty or an
    /// explicit `return ...;` statement owns the value (the statement set has
    /// no tail).
    fn inferTailReturnType(self: *Lowerer, body: ir.exprs.NodeId) anyerror!?ir.types.Type {
        if (body >= self.ir.bodies.exprs.len) return null;
        const tail = switch (self.ir.bodies.exprs[body].kind) {
            .block => |be| blk: {
                if (be.tail) |tail_id| {
                    if (tail_id >= self.ir.bodies.exprs.len) return null;
                    break :blk tail_id;
                }
                if (be.statements.len == 0) return null;

                const stmt_id = be.statements[be.statements.len - 1];
                if (stmt_id >= self.ir.bodies.stmts.len) return null;
                break :blk switch (self.ir.bodies.stmts[stmt_id].kind) {
                    .expr => |expr_id| expr_id,
                    else => return null,
                };
            },
            else => body,
        };
        if (tail >= self.ir.bodies.exprs.len) return null;

        const e = self.ir.bodies.exprs[tail];
        // A wired concerete type annotation on the tail expr is authoritative.
        if (e.ty) |ty_id| {
            if (ty_id < self.ir.types.len) {
                const ct = self.ir.types[ty_id];
                if (ct != .unsupported) {
                    if (try self.sourceCallProducedType(tail, ct)) |produced| return produced;
                    return ct;
                }
            }
        }

        return switch (e.kind) {
            .literal => |lit| switch (lit) {
                .int => |il| blk: {
                    const nm = il.ty_suffix orelse break :blk .{ .prim = .i32 };
                    const prim: ir.types.Prim = if (std.mem.eql(u8, nm, "i8"))
                        .i8
                    else if (std.mem.eql(u8, nm, "i16"))
                        .i16
                    else if (std.mem.eql(u8, nm, "i32"))
                        .i32
                    else if (std.mem.eql(u8, nm, "i64"))
                        .i64
                    else if (std.mem.eql(u8, nm, "i128"))
                        .i128
                    else if (std.mem.eql(u8, nm, "isize"))
                        .isize
                    else if (std.mem.eql(u8, nm, "u8"))
                        .u8
                    else if (std.mem.eql(u8, nm, "u16"))
                        .u16
                    else if (std.mem.eql(u8, nm, "u32"))
                        .u32
                    else if (std.mem.eql(u8, nm, "u64"))
                        .u64
                    else if (std.mem.eql(u8, nm, "u128"))
                        .u128
                    else if (std.mem.eql(u8, nm, "usize"))
                        .usize
                    else
                        .i32;
                    break :blk .{ .prim = prim };
                },
                .float => .{ .prim = .f64 },
                .boolean => .{ .prim = .bool },
                .character => .{ .prim = .char },
                .string => .{ .slice = (try self.sliceU8Alloc()) orelse return null },
                .byte_array => .{ .slice = (try self.sliceU8Alloc()) orelse return null },
            },
            .struct_lit => |sl| try self.namedFromDef(sl.def),
            .enum_variant => |ev| try self.valueEntityType(ev.def),
            .external_variant => |variant| .{ .external_nominal = variant.owner },
            .call => |c| switch (c.call_kind) {
                .free => |def_id| try self.namedFromDef(def_id),
                .associated => |def_id| try self.namedFromDef(def_id),
                .constructor => |def_id| try self.namedFromDef(def_id),
            },
            .path => |pe| try self.valueEntityType(pe.def),
            .binary => |b| try self.binopResultType(b),
            .unary => |u| switch (u.op) {
                .negate, .deref => try self.exprType(u.operand),
                else => null,
            },
            .if_else => |ie| try self.exprType(ie.then_.tail orelse return null),
            .match => |match| try self.matchResultType(match),
            else => null,
        };
    }

    /// Re-wrap a concrete ir type as a fresh slice-of-u8 (for string/byte-array
    /// tail literals). The returned slice is arena-backed.
    fn sliceU8Alloc(self: *Lowerer) anyerror!?*const ir.types.Slice {
        const s = try self.alloc.create(ir.types.Slice);
        s.* = .{ .const_ = true, .elem = .{ .prim = .u8 } };
        return s;
    }

    /// Resolve a def id to its emitted name as a `.named` type; null when
    /// unresolvable in the symbol table.
    fn namedFromDef(self: *Lowerer, def: ir.spine.EntityId) anyerror!?ir.types.Type {
        const ent = self.ir.graph.symbol_table.get(def) orelse return null;
        const nm = ent.renamed_to orelse ent.name;
        if (nm.len == 0) return null;
        const segments = try self.alloc.alloc(ir.types.PathSegment, 1);
        segments[0] = .{ .name = nm, .id = def };
        return .{ .path = .{ .segments = segments } };
    }

    /// The type of the value a `const` declares, or null when the entity has
    /// no constant body. A path to a constant is a *use* of that value, not a
    /// type: naming the declaration back produced a path whose entity is a
    /// `const_`, which every type-lowering path refuses because a constant is
    /// not a type definition. `test_hash(fnv1a_hash_str_32, FOOBAR,
    /// FOOBAR_HASH_32)` binds the callee's `T` from its third argument, so
    /// the constant's own type is exactly the evidence the call needs.
    fn valueDefType(self: *Lowerer, def: ir.spine.EntityId) ?ir.types.Type {
        if (def >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[def]) {
            .const_ => |body| body.ty,
            else => null,
        };
    }

    /// The declared type of the binding a `.field` entity names, read from
    /// the body that declares it rather than from the callable being
    /// lowered.
    ///
    /// A parameter is a `.field` entity parented to its own function or
    /// method — an `impl` method keeps the method entity as its parent — so
    /// free functions, inherent and trait methods, and a closure reading a
    /// captured parameter all resolve through the same static hop, and the
    /// answer is the same row before any callable is lowered and while its
    /// own declaration is.
    ///
    /// `paramTypeByName` answers the same question from the AMBIENT callable,
    /// which is null while `computeComparisonTemporaries` walks the flat
    /// expression table. An unannotated `r: Result<String, u8>` then read as
    /// unowned there and owned while `r.unwrap() == "same"` was lowered, so
    /// the declaration took an allocator no call site had been told to pass.
    /// What the name match cannot do is separate a parameter from a local
    /// that shadows it: `pushLocal` registers both as a `.field` entity
    /// parented to the function, and `Param` carries only name, type and
    /// span, so the two are one row here. A local that no parameter shares
    /// its name with is answered by `localBindingType`, which reads the
    /// `let` that declares it. A struct or enum field is the same question
    /// against a different owner: its declared type is the owner's field
    /// list, so the same name match answers it.
    fn declaredBindingType(self: *const Lowerer, def: ir.spine.EntityId) ?ir.types.Type {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (entity.kind != .field) return null;
        const owner = entity.parent orelse return null;
        if (owner >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[owner]) {
            .fn_ => |body| blk: {
                for (body.params) |param| {
                    if (std.mem.eql(u8, param.name, entity.name)) break :blk param.ty;
                }
                break :blk null;
            },
            .struct_ => |body| declaredFieldType(body.fields, entity.name),
            .enum_ => |body| declaredVariantFieldType(body.variants, entity.name),
            else => null,
        };
    }

    /// Declared type of the named field in a field list, or null when the
    /// owner declares no field by that name.
    fn declaredFieldType(fields: []const ir.items.Field, name: []const u8) ?ir.types.Type {
        for (fields) |field| {
            if (std.mem.eql(u8, field.name, name)) return field.ty;
        }
        return null;
    }

    /// Declared type of the named variant field. A tuple variant carries no
    /// names to match, so only a struct-like variant can answer.
    fn declaredVariantFieldType(
        variants: []const ir.items.Variant,
        name: []const u8,
    ) ?ir.types.Type {
        for (variants) |variant| {
            switch (variant.fields) {
                .named => |fields| {
                    if (declaredFieldType(fields, name)) |ty| return ty;
                },
                else => {},
            }
        }
        return null;
    }

    /// The Rust type of a node, falling back to the type the surrounding
    /// expression has already established (`expected_value_type`) when the
    /// frontend left the node unannotated. `exprType` answers the same
    /// question but ends in a per-kind guess, which an array or tuple literal
    /// does not have: Zig writes both with a type name, and nothing about the
    /// node's own contents says whether it is one or the other.
    fn nodeType(self: *Lowerer, id: ir.exprs.NodeId) anyerror!?ir.types.Type {
        if (id < self.ir.bodies.exprs.len) {
            if (self.ir.bodies.exprs[id].ty) |ty_id| {
                if (ty_id < self.ir.types.len) return self.ir.types[ty_id];
                if (ty_id < self.ir.bodies.types.len) return self.ir.bodies.types[ty_id];
            }
        }
        return self.expected_value_type;
    }

    /// Best-effort concrete type of a sub-expression (used by binary/unary/if
    /// inference), recursing one level only.
    fn exprType(self: *Lowerer, id: ir.exprs.NodeId) anyerror!?ir.types.Type {
        if (id >= self.ir.bodies.exprs.len) return null;
        const e = self.ir.bodies.exprs[id];
        if (e.ty) |ty_id| {
            const ct: ?ir.types.Type = if (ty_id < self.ir.types.len)
                self.ir.types[ty_id]
            else if (ty_id < self.ir.bodies.types.len)
                self.ir.bodies.types[ty_id]
            else
                null;
            if (ct) |resolved| {
                if (resolved != .unsupported) {
                    if (try self.sourceCallProducedType(id, resolved)) |produced| return produced;
                    return resolved;
                }
            }
        }
        return switch (e.kind) {
            .literal => |lit| switch (lit) {
                .int => .{ .prim = .i32 },
                .float => .{ .prim = .f64 },
                .boolean => .{ .prim = .bool },
                .character => .{ .prim = .char },
                // Rust types both literals for us: `"..."` is `&'static str`
                // and `b"..."` is `&'static [u8; N]`. Without these the
                // frontend leaves the node untyped, and a generic callee's
                // type parameter can then never be bound from the argument.
                .string => .{ .slice = (try self.sliceU8Alloc()) orelse return null },
                .byte_array => |bytes| blk: {
                    const array = try self.alloc.create(ir.types.Array);
                    array.* = .{
                        .elem = .{ .prim = .u8 },
                        .len = .{ .literal = bytes.items.len },
                    };
                    const reference = try self.alloc.create(ir.types.Ref);
                    reference.* = .{ .mut = false, .pointee = .{ .array = array } };
                    break :blk .{ .reference = reference };
                },
            },
            .struct_lit => |sl| try self.namedFromDef(sl.def),
            .path => |pe| try self.valueEntityType(pe.def),
            .unary => |unary| switch (unary.op) {
                // `&e` borrows whatever `e` is. The frontend pins most of
                // these, but a borrow written on an argument the inference
                // pass did not reach is left untyped — and then a generic
                // callee's type parameter cannot be bound from that argument
                // at all, so the call is refused outright instead of emitted.
                // The borrow's shape is not a guess: it is the operand's own
                // type under one more reference, which is exactly what the
                // source wrote.
                .ref => |mode| blk: {
                    if (mode == .value) break :blk null;
                    const borrowed = (try self.exprType(unary.operand)) orelse break :blk null;
                    const reference = try self.alloc.create(ir.types.Ref);
                    reference.* = .{ .mut = mode == .mutable, .pointee = borrowed };
                    break :blk .{ .reference = reference };
                },
                else => null,
            },
            .field => |fe| blk: {
                if (std.mem.eql(u8, fe.field, "len")) {
                    break :blk ir.types.Type{ .prim = .usize };
                }
                // The field's own declaration is the source's answer: the
                // resolved entity names the row, and the base's nominal
                // names the same row when the graph did not link one.
                if (self.declaredBindingType(fe.resolved)) |declared| break :blk declared;
                break :blk self.fieldSlotType(try self.exprType(fe.base), fe.field);
            },
            .index => |index_expr| try self.indexExprType(index_expr),
            .array => |array_expr| try self.arrayExprType(array_expr),
            .method_call => |mc| blk: {
                const method = self.ir.graph.symbol_table.get(mc.method) orelse break :blk null;
                if (std.mem.eql(u8, method.name, "len")) {
                    break :blk ir.types.Type{ .prim = .usize };
                }
                if (try self.lookupRecognizedStdMethod(mc.receiver, method.name)) |recognized| {
                    switch (recognized) {
                        .to_string => break :blk ownedRuntimeStringType(),
                        // `Iterator::any` answers `bool` whatever the
                        // predicate accepts; no closure return type is
                        // needed to know it, because the trait declares it.
                        .iterator_any => break :blk ir.types.Type{ .prim = .bool },
                        // `expect` hands back the `Ok` payload and `expect_err`
                        // the `E`; both name which half they keep, so the
                        // receiver's own `Result` says which one this is.
                        .result_unwrap,
                        .result_unwrap_err,
                        .result_expect,
                        .result_expect_err,
                        => {
                            const result = try self.taggedResultType(mc.receiver) orelse break :blk null;
                            const keeps_ok = recognized == .result_unwrap or
                                recognized == .result_expect;
                            break :blk if (keeps_ok) result.ok else result.err;
                        },
                        else => {},
                    }
                }
                break :blk null;
            },
            // `E::Variant` is a value of `E`. A variant carries no type of
            // its own, so the enum that declares it is the only type a method
            // call on the value can mean. Without this arm the receiver type
            // was unknown, which silently disabled every type-driven decision
            // downstream: `FromHexError::OddLength.to_string()` lost its
            // `Display` recognition and emitted `recv.to_string()`, a method
            // no Zig value has.
            .enum_variant => |variant| try self.valueEntityType(variant.def),
            .binary => |binary| try self.binopResultType(binary),
            .match => |match| try self.matchResultType(match),
            else => null,
        };
    }

    fn matchResultType(self: *Lowerer, match: ir.exprs.MatchExpr) anyerror!?ir.types.Type {
        for (match.arms) |arm| {
            if (try self.exprType(arm.body)) |result_type| return result_type;
        }
        return null;
    }

    /// The type of the VALUE a path names.
    ///
    /// A path expression is a use, so the answer is whatever the declaration
    /// says the name holds: a parameter's declared type, a constant's own
    /// type, a local's annotation or initialiser, or the type itself when the
    /// name declares one. Answering with the NAME instead, for anything that
    /// is not a type definition, produced a type path that names no type at
    /// all — `writable` is a binding, not a type — and made generic inference
    /// bind a callee's parameter to it: `write::unsigned(&mut writable, 128)`
    /// inferred `W = writable`, and lowering that argument was refused
    /// outright. A value entity that declares no type is not evidence of
    /// anything, so this answers null rather than inventing one.
    fn valueEntityType(self: *Lowerer, def: ir.spine.EntityId) anyerror!?ir.types.Type {
        if (self.value_entity_depth >= 32) return null;
        self.value_entity_depth += 1;
        defer self.value_entity_depth -= 1;
        if (self.declaredBindingType(def)) |declared| return declared;
        if (self.valueDefType(def)) |declared| return declared;
        if (try self.localBindingType(def)) |declared| return declared;
        return self.namedTypeDef(def);
    }

    /// The type a def declares, when the def IS a type definition. A
    /// variant is a value of the enum that owns it, so a variant names its
    /// owner; everything else that is not a type definition is a value, and
    /// naming one back produces a path no type-checker accepts.
    fn namedTypeDef(self: *Lowerer, def: ir.spine.EntityId) ?ir.types.Type {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        const owner = if (entity.kind == .variant)
            entity.parent orelse return null
        else
            def;
        const owner_entity = self.ir.graph.symbol_table.get(owner) orelse return null;
        if (!isTypeDefinition(owner_entity.kind)) return null;
        return self.namedFromDef(owner) catch null;
    }

    /// Type of `base[index]`.
    ///
    /// A range index slices — `buf[..]` is `&[T]`, not the element — so the
    /// index expression, not the base, decides whether the result is one
    /// value or a view of the sequence. Any other index reads the element
    /// the sequence's own type already names. A base that is neither an
    /// array nor a slice (a map, a `Vec` behind a trait) has no element type
    /// this way, and says so.
    fn indexExprType(self: *Lowerer, index_expr: ir.exprs.IndexExpr) anyerror!?ir.types.Type {
        const base = try self.exprType(index_expr.base) orelse return null;
        const element: ir.types.Type = switch (base) {
            .slice => |slice| slice.elem,
            .array => |array| array.elem,
            else => return null,
        };
        if (index_expr.index >= self.ir.bodies.exprs.len) return null;
        if (self.ir.bodies.exprs[index_expr.index].kind != .range) return element;
        const slice = try self.alloc.create(ir.types.Slice);
        slice.* = .{ .const_ = true, .elem = element };
        return .{ .slice = slice };
    }

    /// Type of an array literal: `[T; N]` where `T` is its first element's
    /// type and `N` its repeated or written length.
    fn arrayExprType(self: *Lowerer, array_expr: ir.exprs.ArrayExpr) anyerror!?ir.types.Type {
        if (array_expr.elements.len == 0) return null;
        const element = try self.exprType(array_expr.elements[0]) orelse return null;
        const array = try self.alloc.create(ir.types.Array);
        array.* = .{
            .elem = element,
            // The written count is a `u64` target-side length; the element
            // list this stands in for is a real slice, so it widens here.
            .len = .{ .literal = array_expr.repeat orelse
                @as(u64, @intCast(array_expr.elements.len)) },
        };
        return .{ .array = array };
    }

    /// The type of a local binding, read from the `let` that declares it.
    ///
    /// `pushLocal` registers a local exactly as it registers a parameter — a
    /// `.field` entity parented to the callable — so the parameter list is
    /// not the only place a local's type is written down. The `let` is: an
    /// annotation or the pattern's own recorded type is the source's
    /// declaration, and an initialiser states the same thing by inference.
    /// `let mut writable = &mut buf[..]` is `&mut [T]`, and typing that
    /// initialiser is what resolves the chain of `let`s behind it.
    fn localBindingType(self: *Lowerer, def: ir.spine.EntityId) anyerror!?ir.types.Type {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (entity.kind != .field) return null;
        const owner = entity.parent orelse return null;
        if (owner >= self.ir.bodies.bodies.len) return null;
        const fn_body = switch (self.ir.bodies.bodies[owner]) {
            .fn_ => |body| body,
            else => return null,
        };
        if (fn_body.body >= self.ir.bodies.exprs.len) return null;
        const block = switch (self.ir.bodies.exprs[fn_body.body].kind) {
            .block => |value| value,
            else => return null,
        };
        return self.bindingTypeInBlock(block, entity.name, 0);
    }

    /// The type the first `let` in `block` that binds `name` gives it. A
    /// nested scope is read too: Rust lets a name be shadowed by an inner
    /// block, so the inner declaration is a real answer to the question.
    fn bindingTypeInBlock(
        self: *Lowerer,
        block: ir.exprs.BlockExpr,
        name: []const u8,
        depth: usize,
    ) anyerror!?ir.types.Type {
        if (depth > 32) return null;
        for (block.statements) |statement_id| {
            if (statement_id >= self.ir.bodies.stmts.len) continue;
            switch (self.ir.bodies.stmts[statement_id].kind) {
                .let => |let_stmt| {
                    if (try self.letBindingType(let_stmt, name, depth)) |ty| return ty;
                },
                .let_else => |let_else| {
                    if (try self.patternDeclaredType(
                        let_else.pattern,
                        name,
                        try self.exprType(let_else.init),
                        depth,
                    )) |ty| {
                        return ty;
                    }
                    if (try self.bindingTypeInBlock(let_else.else_block, name, depth + 1)) |ty| {
                        return ty;
                    }
                },
                .expr => |expr_id| {
                    if (try self.bindingTypeInScope(expr_id, name, depth + 1)) |ty| return ty;
                },
                .item => {},
            }
        }
        return null;
    }

    /// The same search through any expression that opens a scope of its own.
    fn bindingTypeInScope(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        name: []const u8,
        depth: usize,
    ) anyerror!?ir.types.Type {
        if (depth > 32 or node >= self.ir.bodies.exprs.len) return null;
        switch (self.ir.bodies.exprs[node].kind) {
            .block => |block| return self.bindingTypeInBlock(block, name, depth),
            .if_else => |if_expr| {
                if (try self.bindingTypeInBlock(if_expr.then_, name, depth + 1)) |ty| return ty;
                return self.bindingTypeInElse(if_expr.@"else", name, depth + 1);
            },
            .if_let => |if_let| {
                if (try self.bindingTypeInBlock(if_let.then_, name, depth + 1)) |ty| return ty;
                return self.bindingTypeInElse(if_let.@"else", name, depth + 1);
            },
            .loop_ => |loop_expr| return self.bindingTypeInBlock(loop_expr.body, name, depth + 1),
            .while_ => |while_expr| return self.bindingTypeInBlock(while_expr.body, name, depth + 1),
            .for_ => |for_expr| return self.bindingTypeInBlock(for_expr.body, name, depth + 1),
            .match => |match_expr| {
                for (match_expr.arms) |arm| {
                    if (try self.bindingTypeInScope(arm.body, name, depth + 1)) |ty| return ty;
                }
                return null;
            },
            else => return null,
        }
    }

    fn bindingTypeInElse(
        self: *Lowerer,
        branch: ir.exprs.ElseBranch,
        name: []const u8,
        depth: usize,
    ) anyerror!?ir.types.Type {
        return switch (branch) {
            .none => null,
            .block => |block| try self.bindingTypeInBlock(block, name, depth),
            .chain => |node| try self.bindingTypeInScope(node, name, depth),
        };
    }

    /// The type a `let` gives `name`. A `let` whose pattern does not bind the
    /// name says nothing about it, so it is skipped rather than answered
    /// with its initialiser's type.
    fn letBindingType(
        self: *Lowerer,
        let_stmt: ir.exprs.LetStmt,
        name: []const u8,
        depth: usize,
    ) anyerror!?ir.types.Type {
        if (!self.patternBindsName(let_stmt.pattern, name, depth)) return null;
        if (let_stmt.ty) |ty_id| {
            if (self.typeById(ty_id) catch null) |declared| return declared;
        }
        // The initialiser is what the pattern destructures, so it is the
        // container each part is read out of: `let (a, b) = pair` gives `a`
        // the pair's first element, not the pair.
        const initialiser = try self.exprType(let_stmt.init orelse return null);
        return self.patternDeclaredType(let_stmt.pattern, name, initialiser, depth);
    }

    /// Whether `pattern` binds `name` anywhere inside it.
    fn patternBindsName(
        self: *const Lowerer,
        pattern_id: ir.exprs.NodeId,
        name: []const u8,
        depth: usize,
    ) bool {
        if (depth > 32 or pattern_id >= self.ir.bodies.pats.len) return false;
        return switch (self.ir.bodies.pats[pattern_id].kind) {
            .binding => |binding| std.mem.eql(u8, binding.name, name),
            .tuple => |tuple| patternListBindsName(self, tuple.elements, name, depth),
            .slice => |slice| blk: {
                if (patternListBindsName(self, slice.elements, name, depth)) break :blk true;
                if (slice.rest) |rest| break :blk self.patternBindsName(rest, name, depth + 1);
                break :blk false;
            },
            .reference => |reference| self.patternBindsName(reference.inner, name, depth + 1),
            .@"or" => |or_pattern| patternListBindsName(self, or_pattern.alternatives, name, depth),
            .struct_pat => |structure| patternFieldsBindName(self, structure.fields, name, depth),
            .external_variant => |variant| patternFieldsBindName(self, variant.fields, name, depth),
            else => false,
        };
    }

    /// The type a pattern gives the name it binds: its own recorded type when
    /// the frontend pinned one, else the matching part of `container`, the
    /// type the value being destructured already has. Destructuring is how
    /// most bindings are written — `Some((&first, rest))`, `Err(e)` — and the
    /// container is the only place their types are written down.
    fn patternDeclaredType(
        self: *Lowerer,
        pattern_id: ir.exprs.NodeId,
        name: []const u8,
        container: ?ir.types.Type,
        depth: usize,
    ) anyerror!?ir.types.Type {
        if (depth > 32 or pattern_id >= self.ir.bodies.pats.len) return null;
        const pattern = self.ir.bodies.pats[pattern_id];
        switch (pattern.kind) {
            .binding => |binding| {
                if (!std.mem.eql(u8, binding.name, name)) return null;
                if (pattern.ty) |ty_id| {
                    if (self.typeById(ty_id) catch null) |declared| return declared;
                }
                return container;
            },
            .reference => |reference| {
                const pointee: ?ir.types.Type = switch (container orelse return null) {
                    .reference => |borrowed| borrowed.pointee,
                    else => null,
                };
                return self.patternDeclaredType(reference.inner, name, pointee, depth + 1);
            },
            .tuple => |tuple| {
                const parts: []const ir.types.Type = switch (container orelse return null) {
                    .tuple => |elements| elements,
                    else => return null,
                };
                for (tuple.elements, 0..) |element, index| {
                    const part: ?ir.types.Type = if (index < parts.len) parts[index] else null;
                    if (try self.patternDeclaredType(element, name, part, depth + 1)) |ty| {
                        return ty;
                    }
                }
                return null;
            },
            .slice => |slice| {
                const element: ?ir.types.Type = switch (container orelse return null) {
                    .slice => |parts| parts.elem,
                    .array => |parts| parts.elem,
                    else => return null,
                };
                for (slice.elements) |element_pattern| {
                    if (try self.patternDeclaredType(element_pattern, name, element, depth + 1)) |ty| {
                        return ty;
                    }
                }
                if (slice.rest) |rest| {
                    return self.patternDeclaredType(rest, name, element, depth + 1);
                }
                return null;
            },
            .@"or" => |or_pattern| {
                for (or_pattern.alternatives) |alternative| {
                    if (try self.patternDeclaredType(alternative, name, container, depth + 1)) |ty| {
                        return ty;
                    }
                }
                return null;
            },
            .struct_pat => |structure| return self.patternFieldsDeclaredType(
                structure.fields,
                name,
                container,
                depth,
            ),
            .external_variant => |variant| return self.patternFieldsDeclaredType(
                variant.fields,
                name,
                container,
                depth,
            ),
            else => return null,
        }
    }

    fn patternFieldsDeclaredType(
        self: *Lowerer,
        fields: []const ir.exprs.FieldPat,
        name: []const u8,
        container: ?ir.types.Type,
        depth: usize,
    ) anyerror!?ir.types.Type {
        for (fields) |field| {
            if (field.pat) |pattern| {
                if (try self.patternDeclaredType(
                    pattern,
                    name,
                    self.fieldSlotType(container, field.field),
                    depth + 1,
                )) |ty| return ty;
            } else if (field.shorthand and std.mem.eql(u8, field.field, name)) {
                return self.fieldSlotType(container, field.field);
            }
        }
        return null;
    }

    /// The declared type of one named field of a value already typed. A
    /// struct is a `.path` (or a `.generic_inst` of one) whose terminal
    /// segment resolves to the declaring entity, so the field list is read
    /// from that declaration and not from the name.
    fn fieldSlotType(
        self: *const Lowerer,
        container: ?ir.types.Type,
        field: []const u8,
    ) ?ir.types.Type {
        const owner = nominalOwnerId(container orelse return null) orelse return null;
        if (owner >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[owner]) {
            .struct_ => |body| declaredFieldType(body.fields, field),
            .enum_ => |body| declaredVariantFieldType(body.variants, field),
            else => null,
        };
    }

    fn patternListBindsName(
        self: *const Lowerer,
        patterns: []const ir.exprs.NodeId,
        name: []const u8,
        depth: usize,
    ) bool {
        for (patterns) |pattern| {
            if (self.patternBindsName(pattern, name, depth + 1)) return true;
        }
        return false;
    }

    fn patternFieldsBindName(
        self: *const Lowerer,
        fields: []const ir.exprs.FieldPat,
        name: []const u8,
        depth: usize,
    ) bool {
        for (fields) |field| {
            if (field.pat) |pattern| {
                if (self.patternBindsName(pattern, name, depth + 1)) return true;
            } else if (field.shorthand and std.mem.eql(u8, field.field, name)) {
                return true;
            }
        }
        return false;
    }

    /// Result type of a binary expression: comparisons/boolean ops are bool;
    /// otherwise prefer an operand's concrete type (float vs int), falling back
    /// to any operand concrete type.
    fn binopResultType(self: *Lowerer, b: ir.exprs.BinaryExpr) anyerror!?ir.types.Type {
        return switch (b.op) {
            .eq, .ne, .lt, .le, .gt, .ge, .boolean_and, .boolean_or => .{ .prim = .bool },
            else => blk: {
                const lt = try self.exprType(b.lhs);
                if (isFloatType(lt)) break :blk lt;
                const rt = try self.exprType(b.rhs);
                if (isFloatType(rt)) break :blk rt;
                break :blk if (lt) |t| t else rt;
            },
        };
    }

    /// True for a resolved f32/f64 type. Float arithmetic must never use
    /// integer wrapping operators, even when the source overflow mode is
    /// `.wrapping`.
    fn isFloatType(t: ?ir.types.Type) bool {
        return if (t) |ty| ty == .prim and (ty.prim == .f32 or ty.prim == .f64) else false;
    }

    /// Entity that declares the nominal a type names, or null when the type
    /// is not a nominal of this crate. A generic application is the same
    /// declaration as its owner: `Wrapper<u8>` is `Wrapper`.
    fn nominalOwnerId(ty: ir.types.Type) ?ir.spine.EntityId {
        return switch (ty) {
            .path => |path| if (path.segments.len == 0) null else path.segments[path.segments.len - 1].id,
            .generic_inst => |instance| instance.decl,
            else => null,
        };
    }

    /// The type behind any run of references and raw pointers. An lvalue's
    /// IR type is the pointer it is reached through, so an operator that has
    /// to know the arithmetic type underneath it walks them off first.
    fn peelPointers(t: ?ir.types.Type) ?ir.types.Type {
        var current = t orelse return null;
        for (0..128) |_| {
            const next = switch (current) {
                .reference => |reference| reference.pointee,
                .raw_ptr => |raw_ptr| raw_ptr.pointee,
                else => return current,
            };
            current = next;
        }
        return current;
    }

    /// True for a resolved integer primitive type.
    fn isIntegerType(t: ?ir.types.Type) bool {
        const ty = t orelse return false;
        return switch (ty) {
            .prim => |p| switch (p) {
                .u8, .u16, .u32, .u64, .u128, .usize, .i8, .i16, .i32, .i64, .i128, .isize => true,
                else => false,
            },
            else => false,
        };
    }
    fn integerOperandType(t: ?ir.types.Type) ?ir.types.Type {
        var current = t orelse return null;
        for (0..128) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .raw_ptr => |raw_ptr| current = raw_ptr.pointee,
                else => return if (isIntegerType(current)) current else null,
            }
        }
        return null;
    }

    /// The primitive an IR type really names, following a local type ALIAS to
    /// the declaration it stands for.
    ///
    /// `type Chunk = u32;` reaches the backend as a `path`, and every width
    /// decision has to see the `u32` through it. It matters most for a
    /// literal: Rust types `1` in `let mask: Chunk = 1 << n` as a `u32`, while
    /// Zig lowers the same literal to a `comptime_int` and `r2z.ops.binary`
    /// cannot shift or combine one at a runtime width. A path that names a
    /// struct, an enum, or a foreign type answers null, which is the only
    /// thing a caller may do with a width it does not have.
    fn canonicalPrimType(self: *Lowerer, ty: ?ir.types.Type) ?ir.types.Prim {
        var current = ty orelse return null;
        for (0..128) |_| {
            switch (current) {
                .prim => |primitive| return primitive,
                .path => |path| {
                    const target = lastPathSegment(path.segments) orelse return null;
                    const def = target.id orelse return null;
                    const entity = self.ir.graph.symbol_table.get(def) orelse return null;
                    if (entity.kind != .type_alias) return null;
                    if (def >= self.ir.bodies.bodies.len) return null;
                    const alias = switch (self.ir.bodies.bodies[def]) {
                        .type_alias => |body| body,
                        else => return null,
                    };
                    if (typeEquals(alias.target, current)) return null;
                    current = alias.target;
                },
                else => return null,
            }
        }
        return null;
    }

    /// Whether `ty` is a primitive that only an ALIAS stands between the
    /// expression and its width.
    ///
    /// A literal the IR typed as a bare primitive already reaches Zig as
    /// `@as(T, ..)` and needs nothing added; one it typed as `Chunk` reaches
    /// it as a `comptime_int` and does. That difference is the whole test.
    fn aliasedIntegerWidth(self: *Lowerer, ty: ?ir.types.Type) ?ir.types.Prim {
        const concrete = ty orelse return null;
        if (concrete == .prim) return null;
        const primitive = self.canonicalPrimType(concrete) orelse return null;
        return if (isIntegerType(.{ .prim = primitive })) primitive else null;
    }

    /// Whether `ty` names an integer, directly or through a local primitive
    /// ALIAS.
    ///
    /// `type Chunk = u32;` is a `path` in the IR, and a `!` or a `~` over it
    /// is a bit operation on a `u32` — not the boolean one. Every decision
    /// that turns a type into "is this arithmetic" has to look through the
    /// alias for the same reason the width decisions do.
    fn isIntegerOperand(self: *Lowerer, ty: ?ir.types.Type) bool {
        if (isIntegerType(ty)) return true;
        const primitive = self.canonicalPrimType(ty) orelse return false;
        return isIntegerType(.{ .prim = primitive });
    }

    /// The width a bare integer literal reaches a runtime operator at.
    ///
    /// `lowerShiftOperand`'s job, reached through an alias as well: a shift
    /// whose left side is `1u32` behind `Chunk` shifts inside `u32`, and one
    /// whose left side is already `u32` is left alone.
    fn lowerAliasedLiteralOperand(
        self: *Lowerer,
        operand: ir.exprs.NodeId,
        lowered: *const ast.Expr,
        operand_ty: ?ir.types.Type,
    ) !*const ast.Expr {
        if (!self.isComptimeIntExpr(operand)) return lowered;
        const primitive = self.aliasedIntegerWidth(operand_ty) orelse return lowered;
        return self.allocExpr(ast.Expr{ .cast = .{
            .target = try self.lowerType(.{ .prim = primitive }),
            .operand = lowered,
        } });
    }

    /// Zig's shift operators take the amount in `u5`, so a Rust shift by a
    /// wider integer needs a narrowing cast. `@intCast` takes its result type
    /// from context, so the surrounding `<<` / `>>` / `<<=` / `>>=` supplies
    /// the `u5` and the emitted amount is well typed. Callers must not hand
    /// this a float amount, nor an amount the runtime operator path owns —
    /// `r2z.ops` casts for itself.
    fn lowerShiftAmount(self: *Lowerer, amount: ast.Expr) !ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 1);
        errdefer self.alloc.free(args);
        args[0] = amount;
        return .{ .builtin = .{
            .name = "intCast",
            .args = args,
        } };
    }

    /// True when a Rust expression reaches Zig as a `comptime_int`: a bare
    /// integer literal, or such a literal under unary `-`. A binding, a call,
    /// a field, and a Rust `as` cast all carry a type of their own, a nested
    /// shift is typed by the left operand this one types, and unary `!` types
    /// its own literal from the expected type, so nothing else reaches a
    /// shift as a bare comptime value.
    fn isComptimeIntExpr(self: *const Lowerer, id: ir.exprs.NodeId) bool {
        if (id >= self.ir.bodies.exprs.len) return false;
        return switch (self.ir.bodies.exprs[id].kind) {
            .literal => |lit| lit == .int,
            .unary => |unary| switch (unary.op) {
                .negate => self.isComptimeIntExpr(unary.operand),
                else => false,
            },
            else => false,
        };
    }

    /// Zig gives `<<` and `>>` the type of their left operand, and a Rust
    /// integer literal lowers to a `comptime_int`. So `1 << 7` shifts at
    /// arbitrary precision and hands an enclosing `i8` the value `128`, which
    /// Zig rejects. Rust types the literal from its context and shifts inside
    /// that type, so `1i8 << 7` is `-128` and `-8i8 >> 2` is `-2`. Casting the
    /// left operand to the Rust operand type before the shift restores both
    /// the truncating left shift and the arithmetic right shift, and the
    /// result then carries that type to every enclosing expression. A left
    /// operand that already reaches Zig typed is handed back as is, so no
    /// runtime conversion is added. The amount is `lowerShiftAmount`'s job.
    fn lowerShiftOperand(
        self: *Lowerer,
        operand: ir.exprs.NodeId,
        lowered: *const ast.Expr,
        operand_ty: ?ir.types.Type,
    ) !*const ast.Expr {
        if (!self.isComptimeIntExpr(operand)) return lowered;
        if (integerOperandType(operand_ty)) |int_ty| {
            return self.allocExpr(ast.Expr{ .cast = .{
                .target = try self.lowerType(int_ty),
                .operand = lowered,
            } });
        }
        // `integerOperandType` sees only a resolved primitive, and a literal
        // the source typed as `Chunk` is a `path`. The width is the one the
        // alias stands for, so the shift happens inside it rather than at
        // `comptime_int` width.
        return self.lowerAliasedLiteralOperand(operand, lowered, operand_ty);
    }

    /// True when indexing `ty` has to go through the container's storage.
    /// `Vec<T>` lowers to `std.ArrayListUnmanaged`, and Zig indexes the `items`
    /// slice, not the list value: `list[i]` is a compile error, `list.items[i]`
    /// is the element. A reference or raw pointer in front of the vector is
    /// transparent, so the walk stops at the nominal.
    fn needsContainerStorageProjection(ty: ?ir.types.Type) bool {
        var current = ty orelse return false;
        for (0..128) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .raw_ptr => |raw_ptr| current = raw_ptr.pointee,
                .external_nominal => |external| return isAllocVecPath(external.path),
                else => return false,
            }
        }
        return false;
    }

    /// Whether a lowered expression is a call whose error has not been
    /// propagated, so its Zig type is still an error union.
    fn isUnpropagatedErrorUnionExpr(expression: ast.Expr) bool {
        return switch (expression) {
            .call => true,
            // `try f()` still carries the error union in its operand, and an
            // `.items` after it applies the projection to that operand, so
            // the walk follows both operators.
            .unary_op => |unary| isUnpropagatedErrorUnionExpr(unary.operand.*),
            .field_access => |field| isUnpropagatedErrorUnionExpr(field.target.*),
            else => false,
        };
    }

    /// Rust reference comparisons read the referenced pointer value, not its
    /// pointee. Alias names do not add another dereference.
    fn rawPointerReferenceDepth(self: *const Lowerer, ty: ?ir.types.Type) ?usize {
        var current = ty orelse return null;
        var depth: usize = 0;
        for (0..ir.types.traversal_depth_max) |_| {
            switch (current) {
                .raw_ptr => return depth,
                .reference => |reference| {
                    depth += 1;
                    current = reference.pointee;
                },
                .path => |path| {
                    const terminal = lastPathSegment(path.segments) orelse return null;
                    const id = terminal.id orelse return null;
                    const entity = self.ir.graph.symbol_table.get(id) orelse return null;
                    if (entity.kind != .type_alias or id >= self.ir.bodies.bodies.len) return null;
                    current = switch (self.ir.bodies.bodies[id]) {
                        .type_alias => |alias| alias.target,
                        else => return null,
                    };
                },
                else => return null,
            }
        }
        return null;
    }

    fn binaryOperandNeedsDeref(
        ty: ?ir.types.Type,
        op: ir.exprs.BinaryOp,
    ) bool {
        const pointer_ty = ty orelse return false;
        return switch (pointer_ty) {
            .reference => |reference| switch (op) {
                .eq, .ne => reference.pointee == .prim,
                else => true,
            },
            .raw_ptr => false,
            else => false,
        };
    }

    fn requiresRuntimeOperator(ty: ?ir.types.Type) bool {
        var current = ty orelse return false;
        for (0..128) |_| {
            if (current == .reference) {
                current = current.reference.pointee;
                continue;
            }
            return current != .prim;
        }
        return false;
    }

    /// Whether a binary operator has to go through the runtime helper.
    ///
    /// Zig's `==` is a primitive operator: a slice, an array, a struct, a
    /// tagged union, or an enum has no native `==` at all, and naming one is
    /// a compile error rather than a value comparison. The runtime helper
    /// walks those structurally, so it is the only spelling that compiles.
    ///
    /// Both operands are consulted for `==` and `!=` because the frontend
    /// leaves plenty of values untyped, and an unknown LEFT operand is exactly
    /// the case that used to reach a native `==`: a `String` built by
    /// `ToString::to_string` compared against a string literal, and
    /// `E::Variant` — a tagged-union value — compared against an unwrapped
    /// `Result`, both on the right of a left side the frontend never typed. An
    /// unknown operand still falls back to the native operator, which is what
    /// an untyped `x == 0` needs.
    fn requiresRuntimeComparison(
        self: *const Lowerer,
        op: ir.exprs.BinaryOp,
        lhs: ?ir.types.Type,
        rhs: ?ir.types.Type,
    ) bool {
        switch (op) {
            .eq, .ne, .lt, .le, .gt, .ge => {
                if (self.rawPointerReferenceDepth(lhs) != null and
                    self.rawPointerReferenceDepth(rhs) != null) return false;
            },
            else => {},
        }
        if (op != .eq and op != .ne) return requiresRuntimeOperator(lhs);
        return requiresRuntimeOperator(lhs) or requiresRuntimeOperator(rhs);
    }

    fn lowerRuntimeOperator(
        self: *Lowerer,
        name: []const u8,
        operation: []const u8,
        overflow: ir.exprs.Overflow,
        left: ast.Expr,
        right: ast.Expr,
    ) !ast.Expr {
        try self.markRuntimeImport();
        const args = try self.alloc.alloc(ast.Expr, 4);
        args[0] = .{ .ident = try std.fmt.allocPrint(self.alloc, "r2z.ops.Operation.{s}", .{operation}) };
        args[1] = .{ .ident = try std.fmt.allocPrint(self.alloc, "r2z.ops.Overflow.{s}", .{@tagName(overflow)}) };
        args[2] = left;
        args[3] = right;
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = try std.fmt.allocPrint(self.alloc, "r2z.ops.{s}", .{name}) }),
            .args = args,
        } };
    }

    /// Comparison operands are borrowed, not moved. Own only rvalues; a path,
    /// field, index or dereference still belongs to its existing owner.
    ///
    /// A type annotation is the FIRST answer to "does this operand own
    /// storage?", not the only one, and `computeComparisonTemporaries` reads
    /// this same function — so the mask the effect table is built from and the
    /// binding the declaration emits cannot disagree about the verdict.
    fn comparisonTemporaryType(self: *Lowerer, node: ir.exprs.NodeId) anyerror!?ir.types.Type {
        switch (self.ir.bodies.exprs[node].kind) {
            .literal, .path, .field, .index, .unary => return null,
            else => {},
        }
        if (try self.exprType(node)) |ty| {
            if (typeNeedsTemporaryDrop(ty)) return ty;
        }
        return self.recognizedCallOwnerType(node);
    }

    /// The runtime owner a method call hands back AS ITS RESULT, read off the
    /// backend's own recognition of the call rather than off an annotation.
    ///
    /// The annotation comes up empty wherever nothing in the source made the
    /// frontend write one. `FromHexError::InvalidHexCharacter { .. }.to_string()`
    /// is a blanket `ToString` call over a `Display` impl that no signature in
    /// the crate declares, so its node carries no type, and the recovery in
    /// `exprType` is the guess that then decides — and when that guess comes up
    /// empty the operand is handed to `r2z.ops.binary` inline, the `String` the
    /// call built reaches the runtime by value, and nothing anywhere releases
    /// it. The call knows what it builds, so this asks it rather than the
    /// annotation the source happened to leave behind.
    ///
    /// Only a method that BUILDS an owner and returns it qualifies. The rest of
    /// the recognised set takes the allocator for storage the CALLER already
    /// owns — `push` and `extend` grow the receiver, `expect_err` and
    /// `unwrap_err` release out of a union the caller holds — so their result
    /// is the caller's own storage and binding it here would free it twice.
    fn recognizedCallOwnerType(self: *Lowerer, node: ir.exprs.NodeId) anyerror!?ir.types.Type {
        const method_call = switch (self.ir.bodies.exprs[node].kind) {
            .method_call => |value| value,
            else => return null,
        };
        const method = self.ir.graph.symbol_table.get(method_call.method) orelse return null;
        const recognized = try self.lookupRecognizedStdMethod(method_call.receiver, method.name) orelse
            return null;
        return switch (recognized) {
            .to_string => ownedRuntimeStringType(),
            else => null,
        };
    }

    /// The runtime owner `alloc::string::String` lowers to.
    fn ownedRuntimeStringType() ir.types.Type {
        return .{ .external_nominal = .{
            .path = &.{ "alloc", "string", "String" },
            .args = &.{},
        } };
    }

    fn typeNeedsTemporaryDrop(ty: ir.types.Type) bool {
        return switch (ty) {
            .option => |payload| typeNeedsTemporaryDrop(payload.*),
            .result => |result| typeNeedsTemporaryDrop(result.ok) or typeNeedsTemporaryDrop(result.err),
            .@"opaque" => |opaque_type| if (opaque_type.concrete) |concrete|
                typeNeedsTemporaryDrop(concrete.*)
            else
                false,
            else => ownedRuntimeContainerType(ty),
        };
    }

    fn bindComparisonOperand(
        self: *Lowerer,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        value: ast.Expr,
        owner_type: ?ir.types.Type,
    ) anyerror!ast.Expr {
        const name = try self.iteratorTemporaryName("__r2z_compare");
        // Borrow existing places without copying their storage. Other
        // operands are evaluated once, in source order.
        const borrow_place = owner_type == null and exprIsAddressable(value);
        const operand_init = if (borrow_place)
            ast.Expr{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(value) } }
        else
            value;
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = name,
            .ty = if (owner_type) |ty| try self.lowerType(ty) else null,
            .init = operand_init,
            .is_mut = owner_type != null,
        } });
        const held: ast.Expr = .{ .ident = name };
        if (owner_type != null) {
            self.current_callable_is_allocating = true;
            try statements.append(self.alloc, .{ .defer_stmt = .{
                .expr = .{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.alloc.dropTemporary" }),
                    .args = try self.alloc.dupe(ast.Expr, &.{
                        .{ .ident = "allocator" },
                        .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(held) } },
                    }),
                } },
            } });
        }
        return if (borrow_place)
            .{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(held) } }
        else
            held;
    }

    fn lowerBorrowedComparison(
        self: *Lowerer,
        binary: ir.exprs.BinaryExpr,
        lhs: ast.Expr,
        rhs: ast.Expr,
    ) anyerror!ast.Expr {
        if (binary.op != .eq and binary.op != .ne) {
            return self.lowerRuntimeOperator("binary", @tagName(binary.op), binary.overflow, lhs, rhs);
        }
        const lhs_owner = try self.comparisonTemporaryType(binary.lhs);
        const rhs_owner = try self.comparisonTemporaryType(binary.rhs);
        if (lhs_owner == null and rhs_owner == null) {
            return self.lowerRuntimeOperator("binary", @tagName(binary.op), binary.overflow, lhs, rhs);
        }
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        const left = try self.bindComparisonOperand(&statements, lhs, lhs_owner);
        const right = try self.bindComparisonOperand(&statements, rhs, rhs_owner);
        return .{ .block = .{
            .stmts = try statements.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(try self.lowerRuntimeOperator(
                "binary",
                @tagName(binary.op),
                binary.overflow,
                left,
                right,
            )),
        } };
    }

    /// How an assignment target reaches the local binding it writes.
    ///
    /// Rebinding and addressing a descriptor need mutable local storage.
    /// Writing an owned place needs it only for a non-handle value; writing
    /// through a pointer leaves the pointer binding unchanged.
    const BindingWrite = enum {
        /// No assignment target reaches this binding.
        none,
        /// `x = v`: the binding itself is replaced.
        rebind,
        /// The lowered descriptor is passed by mutable address.
        addressed,
        /// `x.f = v` / `x[i] = v`: a place the binding owns is written.
        owned_place,
        /// `*p = v`: the pointee is written, so the binding is untouched.
        pointee,
    };

    /// One parameter the prologue passed as an immutable copy, beside the
    /// body binding the copy was made for.
    ///
    /// Zig parameters are const, so a parameter the body writes is declared
    /// as `_{name}` and copied into a `var {name}` the body reads. The two
    /// names differ, and a body binding already spelled `_{name}` pushes the
    /// signature spelling to `_{name}_N`. Nothing recovers one name from the
    /// other — `isCurrentParameterPath` recognizes the copy through this
    /// pair, which is recorded where the copy is decided.
    const MutableCopyBinding = struct {
        /// The name the emitted signature declares.
        signature_name: []const u8,
        /// The name the body binds and reads.
        body_name: []const u8,
        def: ?ir.spine.EntityId = null,
        /// Only BufRead receiver writes need this copy. Thin-pointer
        /// instantiations retain the signature handle and use void storage.
        conditional_bufread: bool = false,
    };

    /// How far an assignment target is followed down its base chain before
    /// the walk gives up. `a.b.c[i].d = v` is four steps; the bound keeps the
    /// walk finite on a table this function does not own.
    const binding_write_depth_limit: usize = 32;

    fn targetWriteReach(
        self: *const Lowerer,
        target: ir.exprs.NodeId,
        entity_id: ir.spine.EntityId,
        depth: usize,
    ) BindingWrite {
        if (depth >= binding_write_depth_limit) return .none;
        if (target >= self.ir.bodies.exprs.len) return .none;
        return switch (self.ir.bodies.exprs[target].kind) {
            .path => |pe| blk: {
                if (pe.def != entity_id) break :blk .none;
                if (depth == 0) break :blk .rebind;
                break :blk .owned_place;
            },
            .field => |fe| self.targetWriteReach(fe.base, entity_id, depth + 1),
            .index => |ie| self.targetWriteReach(ie.base, entity_id, depth + 1),
            // A dereference writes the pointee. The binding it was read from
            // keeps whatever mutability it already had.
            .unary => |ue| switch (ue.op) {
                .deref => .pointee,
                else => .none,
            },
            else => .none,
        };
    }

    /// How a `receiver.method(..)` call writes through the storage the
    /// receiver names.
    ///
    /// `r2z.alloc.String` spells `into_bytes`, `push`, `reserve` and the rest
    /// with a `self: *String` receiver, so the call reaches the string through
    /// a mutable pointer. An owned `String` the binding holds is exactly the
    /// storage that pointer needs: it has to be a `var`, and an immutable Zig
    /// parameter cannot be one. A receiver reached through a field or an index
    /// is a place the binding owns too.
    ///
    /// Both other answers are deliberate refusals. A receiver behind a
    /// dereference is a pointee the binding does not own, and a receiver of
    /// any other type is not this method at all — a `Vec` has a `push`, and
    /// the resolved receiver type is what keeps the two apart.
    fn methodReceiverWrite(
        self: *Lowerer,
        call: ir.exprs.MethodCall,
        entity_id: ir.spine.EntityId,
    ) anyerror!BindingWrite {
        const method = self.ir.graph.symbol_table.get(call.method) orelse return .none;
        if (!stringMethodNeedsMutableReceiver(method.name)) return .none;
        const reach = self.targetWriteReach(call.receiver, entity_id, 0);
        if (reach == .none or reach == .pointee) return .none;
        const receiver_type = (try self.exprType(call.receiver)) orelse return .none;
        if (ownedStringType(receiver_type) == null) return .none;
        return reach;
    }

    /// Whether this receiver reaches the runtime already carrying the mutable
    /// pointer both of the runtime's arms need, and so must be handed over
    /// untouched.
    ///
    /// The question is about the representation the receiver HAS, never about
    /// the IR spelling `&`:
    ///
    ///   - `&mut SliceReader` is a thin pointer to a sized type — the handle.
    ///   - `lowerType` spells `&[u8]` as the descriptor VALUE itself, so that
    ///     descriptor needs mutable local storage. `&mut &[u8]` instead has a
    ///     thin pointer to the descriptor and already carries its handle.
    ///   - a bare type parameter requires a comptime representation split:
    ///     it may instantiate as an owned reader, a slice, or a thin pointer.
    fn bufReadReceiverIsPointer(self: *Lowerer, receiver_node: ir.exprs.NodeId) anyerror!?bool {
        var current = (try self.exprType(receiver_node)) orelse return null;
        for (0..128) |_| {
            switch (current) {
                .@"opaque" => |opaque_type| current = (opaque_type.concrete orelse return null).*,
                .raw_ptr => return true,
                .reference => |reference| {
                    if (reference.pointee == .dyn_trait) return false;
                    return !isSliceShapedBorrow(reference.pointee);
                },
                .boxed => |boxed| current = boxed.*,
                .path => return if (isTypeParameterPath(current)) null else false,
                else => return false,
            }
        } else return null;
    }

    /// How a `BufRead` method call writes through the storage its receiver
    /// names.
    ///
    /// `fill_buf` and `consume` are the one pair that reaches the reader
    /// through a MUTABLE HANDLE, so a receiver that does not already carry one
    /// needs storage this frame can write through. Zig parameters are `const`,
    /// so a by-value `reader` takes the immutable-signature-plus-`var`-copy
    /// shape every other written parameter already uses, and the call then hands
    /// the runtime that copy's address.
    ///
    /// A concrete thin pointer already carries the handle. A generic receiver
    /// needs conditional mutable storage because its representation is not
    /// known until the emitted Zig function is instantiated.
    ///
    /// The decision reads the receiver's declared `BufRead` BOUND rather than
    /// the method's spelling, the same rule `lookupRecognizedStdMethod` applies
    /// when it recognises the pair, so a user's own `fill_buf` — or a crate's
    /// own `BufRead` trait with a different meaning — never claims this.
    fn bufReadReceiverWrite(
        self: *Lowerer,
        call: ir.exprs.MethodCall,
        entity_id: ir.spine.EntityId,
    ) anyerror!BindingWrite {
        const method = self.ir.graph.symbol_table.get(call.method) orelse return .none;
        const recognized = (try self.lookupRecognizedStdMethod(call.receiver, method.name)) orelse
            return .none;
        if (recognized != .io_fill_buf and recognized != .io_consume) return .none;
        if ((try self.bufReadReceiverIsPointer(call.receiver)) orelse false) return .none;
        const reach = self.targetWriteReach(call.receiver, entity_id, 0);
        // A receiver behind a dereference is a pointee this binding does not
        // own: it already reached the reader through a pointer it holds.
        if (reach == .none or reach == .pointee) return .none;
        return reach;
    }

    /// The stronger of two reaches, so `bindingWrite` can ask each receiver
    /// question independently and combine rather than pick one.
    fn strongerBindingWrite(left: BindingWrite, right: BindingWrite) BindingWrite {
        if (left == .rebind or right == .rebind) return .rebind;
        if (left == .addressed or right == .addressed) return .addressed;
        if (left == .owned_place or right == .owned_place) return .owned_place;
        // `.none` and `.pointee` are both "this reach writes nothing", and
        // which of them it was does not change the answer above.
        return .none;
    }

    /// Whether either receiver question writes this call's receiver.
    fn methodReceiverWrites(
        self: *Lowerer,
        call: ir.exprs.MethodCall,
        entity_id: ir.spine.EntityId,
    ) anyerror!BindingWrite {
        return strongerBindingWrite(
            try self.methodReceiverWrite(call, entity_id),
            try self.bufReadReceiverWrite(call, entity_id),
        );
    }

    /// The strongest write any expression in this callable performs on one
    /// local binding — an assignment target, a receiver that reaches its
    /// string's storage, or a call argument handed over by address. A rebind
    /// outranks a written place and a written place outranks a written
    /// pointee, so the answer does not depend on where in the expression
    /// table each write happens to sit.
    fn bindingWrite(self: *Lowerer, entity_id: ir.spine.EntityId) anyerror!BindingWrite {
        var strongest: BindingWrite = .none;
        for (self.ir.bodies.exprs) |e| {
            const reach: BindingWrite = switch (e.kind) {
                .assign => |value| self.targetWriteReach(value.target, entity_id, 0),
                // Both receiver reaches are asked: a `String` method and a
                // `BufRead` method can each write the place they name, they
                // answer different questions, and asking only one would leave
                // the other's parameter immutable.
                .method_call => |call| try self.methodReceiverWrites(call, entity_id),
                .call => |call| try self.callArgumentWrite(call, entity_id),
                else => continue,
            };
            switch (reach) {
                .rebind => strongest = .rebind,
                .addressed => {
                    if (strongest == .none or strongest == .owned_place) strongest = .addressed;
                },
                .owned_place => {
                    if (strongest == .none) strongest = .owned_place;
                },
                .none, .pointee => {},
            }
        }
        return strongest;
    }

    /// How a call argument writes through the storage a local binding owns.
    ///
    /// A generic `&mut R` parameter lowers to the Zig pointer `*R`: a bare
    /// type parameter is the pointee, and the callee writes through it. An
    /// argument whose OWN type lowers to a fat value — `&str`, `&[T]`,
    /// `&dyn Trait` — is not that pointer, so the call hands over its ADDRESS
    /// and the binding is a value it has to own as a mutable local. An
    /// argument that is already a pointer is the pointer the parameter wants
    /// and leaves the binding exactly as it was.
    fn callArgumentWrite(
        self: *Lowerer,
        call: ir.exprs.Call,
        entity_id: ir.spine.EntityId,
    ) anyerror!BindingWrite {
        var strongest: BindingWrite = .none;
        for (call.args, 0..) |arg_id, index| {
            if (!try self.argumentTakesGenericBorrowAddress(call, index, arg_id)) continue;
            const reach = self.targetWriteReach(arg_id, entity_id, 1);
            switch (reach) {
                .rebind => strongest = .rebind,
                .owned_place, .addressed => strongest = .addressed,
                .none, .pointee => {},
            }
        }
        return strongest;
    }

    /// Whether a binding of this type already reaches the place it names
    /// through a pointer it holds. A reference, raw pointer, slice, and
    /// function pointer do, and Zig writes through one from an immutable
    /// binding. Every other type — a struct, an array, a tuple, a scalar —
    /// is a value the binding owns, so writing part of it writes the binding.
    fn typeIsHandle(ty: ir.types.Type) bool {
        return switch (ty) {
            .reference, .raw_ptr, .slice, .fn_ptr => true,
            else => false,
        };
    }

    /// Whether this borrow lowers to the fat VALUE rather than to a Zig
    /// pointer, which is what `lowerType` does for every fat borrow Rust has:
    /// `&str`, `&[T]` and `&dyn Trait` are all the value itself, because the
    /// fat pointer already carries everything the borrow names.
    fn borrowLowersToFatValue(pointee: ir.types.Type) bool {
        return isSliceShapedBorrow(pointee) or pointee == .dyn_trait;
    }

    /// Whether a write to `entity_id` needs a mutable local in the emitted
    /// Zig: an immutable `_x` signature parameter plus a `var x` copy.
    fn bindingNeedsMutableLocal(
        self: *Lowerer,
        entity_id: ir.spine.EntityId,
        handle_type: bool,
    ) anyerror!bool {
        return switch (try self.bindingWrite(entity_id)) {
            .rebind, .addressed => true,
            .owned_place => !handle_type,
            .none, .pointee => false,
        };
    }

    /// The binding-entity spelling, for a caller that holds no declared type
    /// of its own. The type decides whether a written place belongs to the
    /// binding or to a pointee behind it; a binding whose type cannot be read
    /// is taken as a value, which is the shape a mutable copy exists for.
    fn isParameterAssigned(self: *Lowerer, entity_id: ir.spine.EntityId) anyerror!bool {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse return false;
        const handle_type = if (self.paramTypeByName(entity.name)) |pty|
            typeIsHandle(pty)
        else
            false;
        return self.bindingNeedsMutableLocal(entity_id, handle_type);
    }

    /// The signature name an immutable copy is bound to before the mutable
    /// local takes over. `_{name}` is the established spelling, and the
    /// numbered spelling exists because a body may already bind that name:
    /// one identifier cannot be both.
    ///
    /// The body name and the signature name are one decision, so the pair is
    /// recorded here for whoever has to tell the copy from a binding of the
    /// same name later. A spelling rule cannot do it: `_{name}_N` is the same
    /// copy, and `isCurrentParameterPath` would have to guess which suffix
    /// belongs to a parameter and which to the body's own binding.
    fn mutableCopyParamName(
        self: *Lowerer,
        names: *LocalBindingNames,
        copies: *std.ArrayListUnmanaged(MutableCopyBinding),
        local_name: []const u8,
    ) ![]const u8 {
        var candidate = try std.fmt.allocPrint(self.alloc, "_{s}", .{local_name});
        var suffix: usize = 1;
        while (names.used_names.contains(candidate)) {
            candidate = try std.fmt.allocPrint(self.alloc, "_{s}_{d}", .{ local_name, suffix });
            suffix += 1;
        }
        try names.used_names.put(self.alloc, candidate, {});
        try copies.append(self.alloc, .{
            .signature_name = candidate,
            .body_name = local_name,
        });
        return candidate;
    }

    /// Preserve ordinary mutable copies whenever the source writes the
    /// parameter itself. BufRead-only writes need no storage for thin handles.
    fn mutableParameterCopy(
        self: *Lowerer,
        copy: *MutableCopyBinding,
        ty: ast.Type,
        rust_ty: ir.types.Type,
        def: ir.spine.EntityId,
    ) anyerror!ast.Stmt {
        var conditional = isTypeParameterPath(rust_ty) and !ownedRuntimeContainerType(rust_ty);
        if (conditional) {
            for (self.ir.bodies.exprs) |expr| {
                const write = switch (expr.kind) {
                    .assign => |assignment| self.targetWriteReach(assignment.target, def, 0),
                    .call => |call| try self.callArgumentWrite(call, def),
                    .method_call => |call| try self.methodReceiverWrite(call, def),
                    else => .none,
                };
                if (write != .none and write != .pointee) {
                    conditional = false;
                    break;
                }
            }
        }
        copy.conditional_bufread = conditional;
        copy.def = def;
        const parameter_value: ast.Expr = .{ .ident = copy.signature_name };
        return .{ .let_stmt = .{
            .name = copy.body_name,
            .ty = if (conditional) null else ty,
            .init = if (conditional) .{ .if_expr = .{
                .cond = try self.bufReadThinPointerCondition(parameter_value),
                .then_body = try self.allocExpr(.{ .unit = {} }),
                .else_body = try self.allocExpr(parameter_value),
            } } else parameter_value,
            .is_mut = true,
        } };
    }

    /// Reflection is entirely comptime. The nested switch avoids accessing
    /// pointer metadata on an owned reader and distinguishes fat slices.
    fn bufReadThinPointerCondition(self: *Lowerer, receiver: ast.Expr) anyerror!*const ast.Expr {
        const pointer_name = try self.iteratorTemporaryName("__r2z_bufread_pointer");
        const type_args = try self.alloc.alloc(ast.Expr, 1);
        type_args[0] = receiver;
        const info_args = try self.alloc.alloc(ast.Expr, 1);
        info_args[0] = .{ .builtin = .{ .name = "TypeOf", .args = type_args } };
        const size_arms = try self.alloc.alloc(ast.MatchArm, 2);
        size_arms[0] = .{
            .patterns = &.{.{ .enum_literal = "slice" }},
            .body = .{ .lit = .{ .bool_lit = false } },
        };
        size_arms[1] = .{
            .patterns = &.{.wildcard},
            .body = .{ .lit = .{ .bool_lit = true } },
        };
        const arms = try self.alloc.alloc(ast.MatchArm, 2);
        arms[0] = .{
            .patterns = &.{.{ .enum_literal = "pointer" }},
            .capture = .{ .name = pointer_name },
            .body = .{ .match_expr = .{
                .target = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = pointer_name }),
                    .field_name = "size",
                } }),
                .arms = size_arms,
            } },
        };
        arms[1] = .{
            .patterns = &.{.wildcard},
            .body = .{ .lit = .{ .bool_lit = false } },
        };
        return self.allocExpr(.{ .match_expr = .{
            .target = try self.allocExpr(.{ .builtin = .{ .name = "typeInfo", .args = info_args } }),
            .arms = arms,
        } });
    }

    /// Reserve every spelling a parameter of the current callable is emitted
    /// under: the signature name, and — for a parameter the prologue copied —
    /// the body binding the copy feeds. A generated name that collides with
    /// either is a redeclaration, and the body spelling is the one a
    /// signature-only list misses.
    fn appendParameterNames(
        self: *Lowerer,
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        for (self.current_parameter_names) |param| {
            try reserved.append(self.alloc, param.name);
        }
        for (self.current_mutable_copies) |copy| {
            try reserved.append(self.alloc, copy.signature_name);
            try reserved.append(self.alloc, copy.body_name);
        }
    }

    fn paramTypeByName(self: *const Lowerer, name: []const u8) ?ir.types.Type {
        const cid = self.current_callable_id orelse return null;
        if (cid >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[cid]) {
            .fn_ => |fb| blk: {
                for (fb.params) |p| {
                    if (std.mem.eql(u8, p.name, name)) break :blk p.ty;
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn isIntegerLiteral(self: *const Lowerer, id: ir.exprs.NodeId) bool {
        if (id >= self.ir.bodies.exprs.len) return false;
        return switch (self.ir.bodies.exprs[id].kind) {
            .literal => |lit| lit == .int,
            else => false,
        };
    }
    fn lowerStructMethod(
        self: *Lowerer,
        m: ir.bodies.StructMethod,
        struct_name: []const u8,
        generic_params: []const ast.GenericParam,
        owner_id: ir.spine.EntityId,
    ) !ast.FnDecl {
        const previous_callable_name = self.current_callable_name;
        self.current_callable_name = m.name;
        defer self.current_callable_name = previous_callable_name;

        const method_entity_id = self.methodEntityForDefinition(owner_id, m);
        var local_binding_names: LocalBindingNames = .{};
        try self.prepareLocalBindingNames(method_entity_id, &local_binding_names);
        defer local_binding_names.deinit(self.alloc);
        const previous_local_binding_names = self.current_local_binding_names;
        self.current_local_binding_names = &local_binding_names;
        defer self.current_local_binding_names = previous_local_binding_names;

        const previous_callable_id = self.current_callable_id;
        self.current_callable_id = method_entity_id;
        defer self.current_callable_id = previous_callable_id;
        var params_list: std.ArrayListUnmanaged(ast.FnParam) = .empty;
        const method_is_allocating = self.methodAllocates(owner_id, m);
        if (method_is_allocating) {
            if (method_entity_id) |id| {
                if (self.formattingMethodName(self.ir.graph.symbol_table.get(id).?) != null) {
                    return error.UnsupportedAllocatingFormatter;
                }
            }
        }
        var callable_is_allocating = method_is_allocating;
        const allocator_param_index =
            (if (m.receiver != null) @as(usize, 1) else 0) + m.generic_params.len;
        const has_allocator_param = method_is_allocating;
        const previous_callable_effect = self.current_callable_is_allocating;
        self.current_callable_is_allocating = method_is_allocating;
        defer self.current_callable_is_allocating = previous_callable_effect;
        var generic_args: []ast.Type = &.{};
        if (generic_params.len > 0) {
            generic_args = try self.alloc.alloc(ast.Type, generic_params.len);
            for (generic_params, 0..) |gp, i| {
                generic_args[i] = .{ .named = try self.alloc.dupe(u8, gp.name) };
            }
        }
        const is_generic = generic_params.len > 0;
        const self_type = if (is_generic)
            ast.Type{ .generic = .{
                .name = try self.alloc.dupe(u8, struct_name),
                .params = generic_args,
            } }
        else
            ast.Type{ .named = try self.alloc.dupe(u8, struct_name) };

        var mutable_param_stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer mutable_param_stmts.deinit(self.alloc);
        var mutable_copies: std.ArrayListUnmanaged(MutableCopyBinding) = .empty;
        defer mutable_copies.deinit(self.alloc);

        if (m.receiver) |rec| {
            // A generic struct is emitted as a comptime type function. Keep the
            // receiver tied to that type so its AST matches the method return.
            const self_type_ptr = try self.allocType(self_type);

            const rec_ty: ast.Type = switch (rec) {
                .ref_ => ast.Type{
                    .ptr = .{
                        .elem = self_type_ptr,
                        .is_const = true,
                        .size = .one,
                    },
                },
                .mut_ref => ast.Type{
                    .ptr = .{
                        .elem = self_type_ptr,
                        .is_const = false,
                        .size = .one,
                    },
                },
                .owned => self_type,
            };

            const receiver_def = local_binding_names.claimLocal(&self.ir.graph.symbol_table, "self");
            const receiver_name = if (receiver_def) |d|
                local_binding_names.emitted_by_entity.get(d) orelse "self"
            else
                "self";
            // A by-value receiver IS a Zig value: a write to it, or to a field
            // or element it owns, needs a mutable local, so the signature
            // keeps an immutable copy of it and the body copies that. A
            // borrowed receiver already points at the caller's value, and Zig
            // writes through the pointer without a local of its own.
            const receiver_is_written = if (receiver_def) |d| blk: {
                if (rec != .owned) break :blk false;
                break :blk try self.bindingNeedsMutableLocal(d, false);
            } else false;

            if (receiver_is_written) {
                const signature_name = try self.mutableCopyParamName(
                    &local_binding_names,
                    &mutable_copies,
                    receiver_name,
                );
                try params_list.append(self.alloc, .{
                    .name = signature_name,
                    .ty = rec_ty,
                });
                try mutable_param_stmts.append(self.alloc, .{
                    .let_stmt = .{
                        .name = try self.alloc.dupe(u8, receiver_name),
                        .ty = rec_ty,
                        .init = .{ .ident = try self.alloc.dupe(u8, signature_name) },
                        .is_mut = true,
                    },
                });
            } else {
                try params_list.append(self.alloc, .{
                    .name = try self.alloc.dupe(u8, receiver_name),
                    .ty = rec_ty,
                });
            }
        }
        try self.appendFunctionGenericParams(m.generic_params, &params_list);
        if (method_is_allocating) {
            try params_list.append(self.alloc, .{
                .name = "allocator",
                .ty = ast.Type{ .named = "std.mem.Allocator" },
            });
        }

        // A by-value owner parameter is an owner this method OWNS, exactly as
        // it is for a free function: Rust moved the bytes in, so nobody else
        // releases them and this frame has to. Collected out here because the
        // parameter loop below is where the binding entity, the emitted name
        // and the declared type are all in hand together — which is the only
        // place a `ParameterOwner` can be spelled.
        var parameter_owners: std.ArrayListUnmanaged(ParameterOwner) = .empty;
        defer parameter_owners.deinit(self.alloc);

        for (m.params) |p| {
            const p_ty = try self.lowerType(p.ty);
            const param_def = local_binding_names.claimLocal(&self.ir.graph.symbol_table, p.name);
            const param_name = if (param_def) |d|
                local_binding_names.emitted_by_entity.get(d) orelse p.name
            else
                p.name;
            const is_mut_assigned = if (param_def) |d|
                try self.bindingNeedsMutableLocal(d, typeIsHandle(p.ty))
            else
                false;

            if (param_def) |d| {
                if (ownsRuntimeTableOrContainer(p.ty)) {
                    try parameter_owners.append(self.alloc, .{
                        .def = d,
                        .alias = .{
                            .source_name = p.name,
                            .capture_name = param_name,
                            .alias_name = param_name,
                            .payload_type = p.ty,
                        },
                    });
                }
            }

            if (is_mut_assigned or (param_def != null and ownedRuntimeContainerType(p.ty))) {
                const sig_name = try self.mutableCopyParamName(
                    &local_binding_names,
                    &mutable_copies,
                    param_name,
                );
                try params_list.append(self.alloc, .{
                    .name = sig_name,
                    .ty = p_ty,
                });
                try mutable_param_stmts.append(self.alloc, try self.mutableParameterCopy(
                    &mutable_copies.items[mutable_copies.items.len - 1],
                    p_ty,
                    p.ty,
                    param_def.?,
                ));
            } else {
                try params_list.append(self.alloc, .{
                    .name = try self.alloc.dupe(u8, param_name),
                    .ty = p_ty,
                });
            }
        }
        const previous_parameter_names = self.current_parameter_names;
        self.current_parameter_names = params_list.items;
        defer self.current_parameter_names = previous_parameter_names;
        const previous_mutable_copies = self.current_mutable_copies;
        self.current_mutable_copies = mutable_copies.items;
        defer self.current_mutable_copies = previous_mutable_copies;

        const owned_collection = self.matchOwnedCollection(m.body, m.ret, method_is_allocating);
        var ret_type = if (owned_collection != null)
            try self.lowerOwnedCollectionReturnType(m.ret)
        else if (is_generic and isSelfPath(m.ret))
            self_type
        else
            try self.lowerType(m.ret);
        const previous_float_context = self.float_context;
        self.float_context = isFloatType(m.ret);
        defer self.float_context = previous_float_context;

        if (m.name.len == 0) return error.MissingDefinitionName;
        if (m.body >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        // Installed BEFORE the body lowers, for the same reason a free
        // function installs its own here: the sites are keyed by expression id,
        // so a move the lowering had already walked past would never be
        // rewritten and the release would free storage this method had given
        // away. `lowerBlock` unwinds the owner stack with its own scope, so
        // what this pushed outlives it and is still there to be released.
        try self.installParameterOwnerMoves(parameter_owners.items, m.body);
        var fn_block: ast.Block = if (owned_collection) |plan|
            try self.lowerOwnedCollectionBlock(
                plan,
                m.ret,
                params_list.items,
                m.name,
            )
        else blk: {
            const expr_node = self.ir.bodies.exprs[m.body];
            break :blk switch (expr_node.kind) {
                .block => |be| blk_body: {
                    self.callable_body_block = true;
                    break :blk_body try self.lowerBlock(be);
                },
                else => .{
                    .stmts = &.{},
                    .expr = try self.allocExpr(try self.lowerExpr(m.body)),
                },
            };
        };
        // Under the same return-type rule the free-function body uses, because
        // a `()` method returns nothing and must not be handed a value. The
        // chain is bound to a local rather than promoted into the tail: a
        // labelled block is legal only as an `if`/`else` branch, so a tail
        // holding one is not spellable Zig at all. See `promoteTrailingMatch`.
        switch (ret_type) {
            .void_type => {},
            else => try promoteGuardChainTail(self, &fn_block),
        }
        // Emitted BEFORE the mutable copies are spliced in, and for the same
        // ordering reason a free function emits them in that order: the copies
        // have to be declared ahead of a defer that names the handle they feed.
        try self.appendParameterOwnerReleases(parameter_owners.items, &fn_block);
        callable_is_allocating = self.current_callable_is_allocating;
        const final_params = if (callable_is_allocating and !has_allocator_param) blk: {
            const params = try self.paramsWithAllocator(
                params_list.items,
                allocator_param_index,
            );
            params_list.deinit(self.alloc);
            break :blk params;
        } else try params_list.toOwnedSlice(self.alloc);
        if (self.methodFallible(owner_id, m)) {
            ret_type = try self.ensureErrorUnion(ret_type);
        }

        var final_fn_block = fn_block;
        if (mutable_param_stmts.items.len > 0) {
            const old_stmts = final_fn_block.stmts;
            const merged = try self.alloc.alloc(ast.Stmt, mutable_param_stmts.items.len + old_stmts.len);
            @memcpy(merged[0..mutable_param_stmts.items.len], mutable_param_stmts.items);
            @memcpy(merged[mutable_param_stmts.items.len..], old_stmts);
            final_fn_block.stmts = merged;
        }

        return .{
            .name = try self.alloc.dupe(u8, if (method_entity_id) |id|
                self.hoisted_method_names.get(id) orelse m.name
            else
                m.name),
            .documentation = try self.callableDocumentation(
                if (method_entity_id) |id|
                    try self.entityDocumentation(self.ir.graph.symbol_table.get(id).?)
                else
                    try std.fmt.allocPrint(self.alloc, "Runs the Rust method `{s}.{s}`.", .{
                        struct_name, m.name,
                    }),
                final_params,
                ret_type,
            ),
            .is_pub = switch (m.visibility) {
                .public, .crate_restricted, .super_restricted, .in_path => true,
                .private => method_entity_id == null or
                    self.privateItemIsPublished(method_entity_id.?),
            },
            .params = final_params,
            .ret_type = ret_type,
            .body = final_fn_block,
        };
    }

    /// Collect generic type parameters referenced by a struct's field types so
    /// a generic struct (e.g. `Fletcher<T>` with `a: T`) is recognized even
    /// when the StructBody did not populate its own `generic_params` list.
    /// Recurses through container types; appends each new parameter once.
    fn collectGenericTypeParams(self: *Lowerer, ty: ir.types.Type, out: *std.ArrayListUnmanaged(ast.GenericParam)) !void {
        switch (ty) {
            .path => |p| {
                if (p.segments.len > 0) {
                    const first = p.segments[0];
                    if (first.id == null and isGenericParamName(first.name) and
                        !hasGenericParam(first.name, out.items))
                    {
                        try out.append(self.alloc, .{
                            .name = try self.alloc.dupe(u8, first.name),
                            .is_comptime = true,
                            .ty = null,
                        });
                    }
                }
            },
            .reference => |r| try self.collectGenericTypeParams(r.pointee, out),
            .raw_ptr => |r| try self.collectGenericTypeParams(r.pointee, out),
            .slice => |s| try self.collectGenericTypeParams(s.elem, out),
            .array => |a| try self.collectGenericTypeParams(a.elem, out),
            .tuple => |tup| for (tup) |t| try self.collectGenericTypeParams(t, out),
            .generic_inst => |gi| for (gi.args.params) |arg| try self.collectGenericTypeParams(arg, out),
            .external_nominal => |external| {
                for (external.args) |arg| try self.collectGenericTypeParams(arg, out);
            },
            .option => |inner| try self.collectGenericTypeParams(inner.*, out),
            .result => |r| {
                try self.collectGenericTypeParams(r.ok, out);
                try self.collectGenericTypeParams(r.err, out);
            },
            .boxed => |inner| try self.collectGenericTypeParams(inner.*, out),
            else => {},
        }
    }

    fn hasGenericParam(name: []const u8, list: []const ast.GenericParam) bool {
        for (list) |gp| {
            if (std.mem.eql(u8, gp.name, name)) return true;
        }
        return false;
    }

    /// Heuristic: a bare single segment whose name looks like a type parameter
    /// (single uppercase letter `T`/`U`/`V`, or an uppercase-leading identifier
    /// that is not a known resolved nominal type). Used only to recover generic
    /// structs when `StructBody.generic_params` is empty.
    fn isGenericParamName(name: []const u8) bool {
        if (name.len == 0) return false;
        // Single uppercase letter type params (T, U, V, ...)
        if (name.len == 1 and name[0] >= 'A' and name[0] <= 'Z') return true;
        // Already declared as a generic param somewhere? Treat any
        // non-resolved uppercase-leading identifier as a type parameter.
        if (name[0] >= 'A' and name[0] <= 'Z') return true;
        return false;
    }

    fn lowerTestEntity(self: *Lowerer, entity_id: ir.spine.EntityId, ent: ir.spine.Entity) !?ast.TestDecl {
        const previous_module_id = self.current_module_id;
        self.current_module_id = (try self.owningModuleEntity(entity_id)) orelse previous_module_id;
        defer self.current_module_id = previous_module_id;
        const previous_struct_id = self.current_struct_id;
        self.current_struct_id =
            (try self.inherentStructForEntity(entity_id)) orelse previous_struct_id;
        defer self.current_struct_id = previous_struct_id;
        const previous_callable_name = self.current_callable_name;
        self.current_callable_name = ent.name;
        defer self.current_callable_name = previous_callable_name;

        if (entity_id >= self.ir.bodies.bodies.len) return error.MissingBodyId;
        var local_binding_names: LocalBindingNames = .{};
        try self.prepareLocalBindingNames(entity_id, &local_binding_names);
        defer local_binding_names.deinit(self.alloc);
        const previous_local_binding_names = self.current_local_binding_names;
        self.current_local_binding_names = &local_binding_names;
        defer self.current_local_binding_names = previous_local_binding_names;

        const body_kind = self.ir.bodies.bodies[entity_id];
        const fb = switch (body_kind) {
            .fn_ => |value| value,
            else => return error.DeclarationBodyMismatch,
        };
        const previous_callable_effect = self.current_callable_is_allocating;
        const stable_callable_effect = self.callPassesAllocator(entity_id);
        self.current_callable_is_allocating = stable_callable_effect;
        defer self.current_callable_is_allocating = previous_callable_effect;
        if (fb.body >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;

        const expr_node = self.ir.bodies.exprs[fb.body];

        var test_block: ast.Block = blk: {
            const previous_test_context = self.lowering_test_entity;
            self.lowering_test_entity = true;
            defer self.lowering_test_entity = previous_test_context;
            break :blk switch (expr_node.kind) {
                .block => |be| try self.lowerBlock(be),
                else => .{
                    .stmts = &.{},
                    .expr = try self.allocExpr(try self.lowerExpr(fb.body)),
                },
            };
        };

        const test_is_allocating = self.current_callable_is_allocating;
        if (test_is_allocating) {
            const std_target = try self.allocExpr(.{ .ident = "std" });
            const testing_target = try self.allocExpr(.{ .field_access = .{
                .target = std_target,
                .field_name = "testing",
            } });
            const allocator_init: ast.Expr = .{ .field_access = .{
                .target = testing_target,
                .field_name = "allocator",
            } };
            const stmts = try self.alloc.alloc(ast.Stmt, test_block.stmts.len + 1);
            stmts[0] = .{ .let_stmt = .{
                .name = "allocator",
                .ty = ast.Type{ .named = "std.mem.Allocator" },
                .init = allocator_init,
            } };
            @memcpy(stmts[1..], test_block.stmts);
            test_block.stmts = stmts;
        }

        return .{
            .name = try self.alloc.dupe(u8, ent.name),
            .body = test_block,
        };
    }
    /// Whether any of these parameters hands the callee an owner it has to
    /// release.
    ///
    /// Rust moves a by-value `String` into the callee, so the callee — not the
    /// caller — is the one whose scope ends with the bytes. A `&String` or
    /// `&mut String` parameter borrows storage the caller still owns and is
    /// released by nobody here, and `ownedRuntimeContainerType` already draws
    /// that line: a borrow is a `.reference`, not the `.external_nominal` the
    /// owner predicate matches. Reading the declared type is therefore the
    /// whole decision, and no separate by-value flag is needed or consulted.
    fn paramsOwnRuntimeContainer(params: []const ir.items.Param) bool {
        for (params) |param| {
            if (ownsRuntimeTableOrContainer(param.ty)) return true;
        }
        return false;
    }

    /// Whether releasing this owner has to walk its ELEMENTS before the slab.
    ///
    /// `Vec(u8)` owns only its buffer, so `deinit` frees exactly what there is.
    /// `Vec(String)` owns a buffer plus a `String` per element, and `deinit` on
    /// the slab alone strands every one of them. This is the same decision
    /// `vecFailureReleaseStatement` already makes for a half-built list.
    fn ownerReleasesElements(ty: ir.types.Type) bool {
        switch (ty) {
            .tuple, .array, .option, .result => return ownedRuntimeContainerType(ty),
            else => {},
        }
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        // The spelling is the SOURCE's choice, and `std::vec::Vec` is the same
        // type as `alloc::vec::Vec`. Answering only for `alloc` here meant a
        // `Vec<String>` written the `std` way released its slab and stranded
        // every element, while the identical type written the `alloc` way
        // walked them.
        if (!isAllocVecPath(external.path)) return false;
        if (external.args.len != 1) return false;
        return vecElementMayOwnRuntimeStorage(external.args[0]);
    }

    /// The `defer` that releases one lexical owner when its scope ends.
    ///
    /// Unconditional, and it runs on the OWNING HANDLE rather than a copy of
    /// it. That is what makes one defer correct on both exits: every move
    /// empties this handle in place, so the path that handed the owner on finds
    /// nothing here and frees nothing, while every path that stayed still frees
    /// what the scope held. Deciding it statically instead would either leak
    /// the path that did not move or free the path that did.
    fn ownerReleaseStatement(
        self: *Lowerer,
        owner_name: []const u8,
        releases_elements: bool,
    ) anyerror!ast.Stmt {
        return .{ .defer_stmt = .{ .expr = try self.ownerReleaseCall(
            .{ .ident = owner_name },
            releases_elements,
        ) } };
    }

    /// The release of one owner PLACE, as an expression rather than a `defer`.
    ///
    /// The same operation the scope-end defer runs, reachable on its own
    /// because an overwrite releases the owner the place held BEFORE the
    /// replacement lands in it. Naming the place rather than an identifier is
    /// what lets both callers share one decision: a scope-end defer names the
    /// binding, and an overwrite names the very expression the assignment
    /// targets.
    fn ownerReleaseCall(
        self: *Lowerer,
        owner: ast.Expr,
        releases_elements: bool,
    ) anyerror!ast.Expr {
        const handle = try self.allocExpr(owner);
        if (!releases_elements) {
            return .{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = handle,
                    .field_name = "deinit",
                } }),
                .args = &.{.{ .ident = "allocator" }},
            } };
        }
        try self.markRuntimeImport();
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .ident = "allocator" };
        args[1] = .{ .unary_op = .{ .op = .addr_of, .operand = handle } };
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.dropTemporary" }),
            .args = args,
        } };
    }

    /// Find the innermost armed owner by source entity, without reading its value.
    fn ownerScopeBinding(self: *const Lowerer, node: ir.exprs.NodeId) ?*const OwnedScopeBinding {
        if (node >= self.ir.bodies.exprs.len) return null;
        const path = switch (self.ir.bodies.exprs[node].kind) {
            .path => |value| value,
            else => return null,
        };
        var index = self.owned_scope_bindings.items.len;
        while (index != 0) {
            index -= 1;
            const owner = &self.owned_scope_bindings.items[index];
            if (owner.def == path.def) return owner;
        }
        return null;
    }

    fn scopeOwnerHandleForPath(self: *const Lowerer, node: ir.exprs.NodeId) ?[]const u8 {
        const owner = self.ownerScopeBinding(node) orelse return null;
        return owner.alias.alias_name;
    }

    /// The live owner binding a plain assignment TARGET names, or null when
    /// the target is not one.
    ///
    /// IDENTITY is the whole test, for the same reason it is everywhere else in
    /// this pass: two bindings may share a source name in nested scopes, and
    /// only the entity says which storage an overwrite empties. Finding one
    /// here also says its scope release is already ARMED — the entry was
    /// pushed when the binding was declared and is popped when the scope ends —
    /// and arming that release is exactly the condition under which an
    /// overwrite owes a release of what the place already held.
    fn ownerOverwriteBinding(self: *Lowerer, target: ir.exprs.NodeId) ?*const OwnedScopeBinding {
        if (target >= self.ir.bodies.exprs.len) return null;
        const path = switch (self.ir.bodies.exprs[target].kind) {
            .path => |value| value,
            else => return null,
        };
        for (self.owned_scope_bindings.items) |*candidate| {
            if (candidate.def == path.def) return candidate;
        }
        return null;
    }

    /// The statement sequence an owner OVERWRITE lowers to, or null when this
    /// assignment is not one.
    ///
    /// The order is the contract, and it is Rust's order:
    ///
    ///   1. the replacement is evaluated into a binding of its OWN, so a
    ///      failing `?` or an allocation failure leaves this frame with the
    ///      owner the place held still in it and still releasable by the defer
    ///      this scope already armed;
    ///   2. only then is what the place held released;
    ///   3. only then does the replacement move in, exactly once.
    ///
    /// A self-move is what makes the order load-bearing. The replacement read
    /// was rewritten to `takeOwned` when the body lowered, so it has already
    /// emptied this very handle by the time step 2 runs; a release that ran
    /// first would free the bytes the replacement was built out of, and one
    /// that ran last would free the replacement a second time. Step 2 finds
    /// nothing to free and the scope's own defer frees the replacement once.
    ///
    /// The release is emitted on the binding's OWN handle, which is what makes
    /// it agree with the defer armed for the same scope: both name one storage.
    fn lowerOwnerOverwrite(
        self: *Lowerer,
        assignment: ir.exprs.AssignExpr,
        value: ast.Expr,
    ) anyerror!?*const ast.Expr {
        if (assignment.op != .plain) return null;
        const binding = self.ownerOverwriteBinding(assignment.target) orelse return null;
        // The replacement has to BE an owner for the overwrite to be one. Any
        // other value cannot have reached an owner-typed place in valid Rust,
        // so emitting this sequence for one would release storage the place
        // never held.
        const replacement_type = (try self.exprType(assignment.value)) orelse return null;
        if (!ownedRuntimeContainerType(replacement_type)) return null;

        var reserved: std.ArrayListUnmanaged([]const u8) = .empty;
        defer reserved.deinit(self.alloc);
        if (self.current_owner_reserved) |outer| {
            try reserved.appendSlice(self.alloc, outer.items);
        }
        try self.appendParameterNames(&reserved);
        try self.appendCollectorImportAliases(&reserved);
        const replacement_name = try self.collectorBindingName("__r2z_replacement", reserved.items);
        // Reserved in the ENCLOSING prelude's own list, so every name generated
        // after this statement sees it and no later binding can take it.
        if (self.current_owner_reserved) |outer| {
            try outer.append(self.alloc, replacement_name);
        }

        const place: ast.Expr = .{ .ident = binding.alias.alias_name };
        const stmts = try self.alloc.alloc(ast.Stmt, 3);
        stmts[0] = .{ .let_stmt = .{
            .name = replacement_name,
            .ty = null,
            .init = value,
            .is_mut = false,
        } };
        stmts[1] = .{ .expr_stmt = try self.allocExpr(try self.ownerReleaseCall(
            place,
            ownerReleasesElements(binding.alias.payload_type),
        )) };
        stmts[2] = .{ .assign = .{
            .target = place,
            .val = .{ .ident = replacement_name },
            .op = .assign,
        } };
        return try self.allocExpr(.{ .block = .{ .stmts = stmts, .expr = null } });
    }

    /// The reads of `alias` that hand the owner on, over the window of the block
    /// that declares it.
    ///
    /// `from` is the index of the declaration, and only what FOLLOWS it is
    /// scanned. That bound is not an optimisation: the scan recognises the
    /// payload by SOURCE NAME, so an earlier binding of the same name is a
    /// different owner and a read of it must not empty this one. Everything from
    /// the declaration onward is exactly the window a move can happen in.
    fn collectScopeOwnerMoves(
        self: *Lowerer,
        def: ir.spine.EntityId,
        alias: OwnedCaptureAlias,
        statements: []const ir.exprs.NodeId,
        from: usize,
        tail: ?ir.exprs.NodeId,
    ) anyerror!OwnedScopeBinding {
        var scan: OwnedCaptureScan = .{ .sites = .empty, .visited = .empty };
        errdefer {
            scan.sites.deinit(self.alloc);
            scan.visited.deinit(self.alloc);
        }
        for (statements[from..]) |statement| {
            try self.scanOwnedCaptureStatement(alias, statement, &scan);
        }
        if (tail) |tail_id| try self.scanOwnedCaptureExpr(alias, tail_id, true, &scan);
        scan.visited.deinit(self.alloc);
        return .{ .def = def, .alias = alias, .sites = scan.sites };
    }

    /// Release the owner a `let` statement declares, at the end of the block
    /// that declared it.
    ///
    /// This is where a nested block, a branch arm, a match arm, a loop body, a
    /// closure body and a method body all stop leaking: each of those IS a
    /// block, and each one runs this for the bindings IT introduced. A pass that
    /// only read the callable root reached none of them, which is why the
    /// generated package computed the right answer and still leaked.
    ///
    /// The handle is the binding's own emitted name, so the release runs on the
    /// storage the binding actually holds rather than on a copy of it, and the
    /// move set installed beside it is what empties that same handle on the
    /// paths that hand the owner on.
    fn appendLexicalOwnerRelease(
        self: *Lowerer,
        be: ir.exprs.BlockExpr,
        index: usize,
        stmt_id: ir.exprs.NodeId,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (stmt_id >= self.ir.bodies.stmts.len) return;
        const let_statement = switch (self.ir.bodies.stmts[stmt_id].kind) {
            .let => |value| value,
            else => return,
        };
        // Late initialization is refused where it is declared rather than
        // decided here: an owner whose initializer this pass cannot see owes a
        // release on some paths and not others, and that is a borrow-checker
        // question, not one this lowering answers by guesswork.
        const init_id = let_statement.init orelse return;
        if (let_statement.pattern >= self.ir.bodies.pats.len) return;
        const pattern = self.ir.bodies.pats[let_statement.pattern];
        const binding = switch (pattern.kind) {
            .binding => |value| value,
            // A tuple or struct pattern names no single owner of its own; its
            // fields are bound by their own statements and released by their
            // own scopes.
            else => return,
        };
        if (init_id >= self.ir.bodies.exprs.len) return;
        const type_id = pattern.ty orelse self.ir.bodies.exprs[init_id].ty orelse return;
        const payload_type = try self.typeById(type_id);
        if (!ownedRuntimeContainerType(payload_type)) return;
        const names = self.current_local_binding_names orelse return;
        const def = names.def_by_pattern.get(let_statement.pattern) orelse return;
        const emitted = names.emitted_by_pattern.get(let_statement.pattern) orelse binding.name;
        if (emitted.len == 0) return;

        const owner = try self.collectScopeOwnerMoves(
            def,
            .{
                .source_name = binding.name,
                .capture_name = emitted,
                .alias_name = emitted,
                .payload_type = payload_type,
            },
            be.statements,
            index + 1,
            be.tail,
        );
        try self.owned_scope_bindings.append(self.alloc, owner);
        try statements.append(
            self.alloc,
            try self.ownerReleaseStatement(emitted, ownerReleasesElements(payload_type)),
        );
    }

    /// One by-value owner parameter, pending the release its body owes.
    const ParameterOwner = struct {
        def: ir.spine.EntityId,
        alias: OwnedCaptureAlias,
    };

    /// The reads of a parameter's owner that hand it on, over the whole body.
    ///
    /// A parameter is in scope for every statement of the body and for its
    /// tail, so the scan starts at the body itself. The tail transfers, because
    /// a function body that ends in a binding RETURNS it — the emitter writes
    /// that `return` — so a tail read of the parameter moves the owner out.
    fn collectOwnerMovesOverBody(
        self: *Lowerer,
        def: ir.spine.EntityId,
        alias: OwnedCaptureAlias,
        body: ir.exprs.NodeId,
    ) anyerror!OwnedScopeBinding {
        var scan: OwnedCaptureScan = .{ .sites = .empty, .visited = .empty };
        errdefer {
            scan.sites.deinit(self.alloc);
            scan.visited.deinit(self.alloc);
        }
        try self.scanOwnedCaptureExpr(alias, body, true, &scan);
        scan.visited.deinit(self.alloc);
        return .{ .def = def, .alias = alias, .sites = scan.sites };
    }

    /// Put each parameter owner's move set on the stack, so the body about to
    /// lower empties the handle on the paths that hand the owner on.
    ///
    /// This runs BEFORE the body lowers: the sites are keyed by expression id,
    /// so a move the lowering had already passed would never be rewritten and
    /// the release would free storage the callee had given away.
    fn installParameterOwnerMoves(
        self: *Lowerer,
        owners: []const ParameterOwner,
        body: ir.exprs.NodeId,
    ) anyerror!void {
        for (owners) |owner| {
            try self.owned_scope_bindings.append(
                self.alloc,
                try self.collectOwnerMovesOverBody(owner.def, owner.alias, body),
            );
        }
    }

    /// Release the owners a callable's parameters HAND IT, at the end of the
    /// body they were given.
    ///
    /// A by-value `String` is an owner the callee OWNS: Rust moved the bytes
    /// in, so nobody else will ever release them. It is the same mechanism a
    /// lexical binding gets, and unconditionally for the same reason: every move
    /// emptied this handle in place while the body lowered, so the path that
    /// handed the owner on frees nothing and the path that kept it frees exactly
    /// what it held.
    ///
    /// The releases are PREPENDED because a parameter is in scope for the whole
    /// body, so its defer must be armed before any statement runs. Arming it
    /// after the last statement would arm it after the exits it must survive.
    fn appendParameterOwnerReleases(
        self: *Lowerer,
        owners: []const ParameterOwner,
        block: *ast.Block,
    ) anyerror!void {
        if (owners.len == 0) return;
        const scope_start = self.owned_scope_bindings.items.len - owners.len;
        defer {
            for (self.owned_scope_bindings.items[scope_start..]) |*binding| {
                binding.sites.deinit(self.alloc);
            }
            self.owned_scope_bindings.shrinkRetainingCapacity(scope_start);
        }
        var releases: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer releases.deinit(self.alloc);
        for (owners) |owner| {
            try releases.append(
                self.alloc,
                try self.ownerReleaseStatement(
                    owner.alias.alias_name,
                    ownerReleasesElements(owner.alias.payload_type),
                ),
            );
        }
        const stmts = try self.alloc.alloc(ast.Stmt, block.stmts.len + releases.items.len);
        @memcpy(stmts[0..releases.items.len], releases.items);
        @memcpy(stmts[releases.items.len..], block.stmts);
        block.stmts = stmts;
    }

    /// Whether a runtime container owns heap storage the runtime releases with
    /// `deinit(gpa)`. A borrowed view of one is not: the value it reads
    /// belongs to somebody else.
    ///
    /// `FromUtf8Error` belongs here for the same reason `String` does: it RETAINS
    /// the bytes that failed validation, so an arm binding one owns those bytes
    /// and has to release them. Reading the character-level detail out of it is a
    /// borrow — the runtime's accessor takes `self: *const` — so the wrapper is
    /// still full afterwards and its release still has work to do.
    fn ownedRuntimeContainerType(ty: ir.types.Type) bool {
        return ownedRuntimeStorageAt(ty, 0, false);
    }

    /// Whether this binding holds storage whose release is a bare
    /// `handle.deinit(allocator)` — a runtime container's, or a map TABLE's.
    ///
    /// A `HashMap`/`HashSet` belongs here and NOT in
    /// `ownedRuntimeContainerType`, which is what the MOVE machinery reads. A
    /// moved container is handed over by `r2z.alloc.takeOwned`, and that
    /// refuses a map outright — `supportsOwnedMove` reaches only the five
    /// runtime containers — so classifying a map as an owner type would emit a
    /// `takeOwned` the runtime answers with a compile error. The two answers
    /// are genuinely different decisions:
    ///
    ///   - "does this scope owe a `deinit(allocator)`?" — yes for a map, and
    ///     `dropTemporary` is a no-op on one, so nothing else would ever free
    ///     the table;
    ///   - "does this scope owe a `takeOwned(..)` transfer?" — no, because the
    ///     runtime cannot move a map and its entries are borrowed slabs.
    ///
    /// So the map reaches the release and allocator gates through here, and
    /// only there. `ownerReleasesElements` keeps answering false for it, which
    /// is what keeps the release a `deinit` rather than a
    /// `dropTemporary` element walk that would free borrowed slabs.
    fn ownsRuntimeTableOrContainer(ty: ir.types.Type) bool {
        if (ownedRuntimeContainerType(ty)) return true;
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        return isRuntimeMapPath(external.path);
    }

    /// Unknown elements are inspected only inside an already-owning Vec.
    fn vecElementMayOwnRuntimeStorage(ty: ir.types.Type) bool {
        return ownedRuntimeStorageAt(ty, 0, true);
    }

    fn ownedRuntimeStorageAt(ty: ir.types.Type, depth: usize, allow_parameter: bool) bool {
        if (depth >= ir.types.traversal_depth_max) return false;
        if (allow_parameter and isTypeParameterPath(ty)) return true;
        return switch (ty) {
            .external_nominal => ownedRuntimeContainerIsRuntimeMovable(ty),
            .tuple => |fields| blk: {
                for (fields) |field| {
                    if (ownedRuntimeStorageAt(field, depth + 1, allow_parameter)) break :blk true;
                }
                break :blk false;
            },
            .array => |array| switch (array.len) {
                .literal => |count| count != 0 and ownedRuntimeStorageAt(array.elem, depth + 1, allow_parameter),
                else => ownedRuntimeStorageAt(array.elem, depth + 1, allow_parameter),
            },
            .option => |payload| ownedRuntimeStorageAt(payload.*, depth + 1, allow_parameter),
            .result => |result| ownedRuntimeStorageAt(result.ok, depth + 1, allow_parameter) or
                ownedRuntimeStorageAt(result.err, depth + 1, allow_parameter),
            else => false,
        };
    }

    fn ownedMoveHasUnknownLength(ty: ir.types.Type, depth: usize) bool {
        if (depth >= ir.types.traversal_depth_max) return false;
        return switch (ty) {
            .array => |array| (array.len != .literal and
                ownedRuntimeStorageAt(array.elem, depth + 1, false)) or
                ownedMoveHasUnknownLength(array.elem, depth + 1),
            .tuple => |fields| blk: {
                for (fields) |field| {
                    if (ownedMoveHasUnknownLength(field, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .option => |payload| ownedMoveHasUnknownLength(payload.*, depth + 1),
            .result => |result| ownedMoveHasUnknownLength(result.ok, depth + 1) or
                ownedMoveHasUnknownLength(result.err, depth + 1),
            else => false,
        };
    }

    /// Refuse owned generic arrays whose existing ABI is a borrowed slice.
    fn ownedMoveHasUnsupportedGenericArray(ty: ir.types.Type, depth: usize) bool {
        if (depth >= ir.types.traversal_depth_max) return false;
        return switch (ty) {
            .array => |array| switch (array.len) {
                .literal => |count| count != 0 and ownedMoveHasUnsupportedGenericArray(array.elem, depth + 1),
                .generic => ownedRuntimeStorageAt(array.elem, depth + 1, false),
                .expression => ownedMoveHasUnsupportedGenericArray(array.elem, depth + 1),
            },
            .tuple => |fields| blk: {
                for (fields) |field| {
                    if (ownedMoveHasUnsupportedGenericArray(field, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .option => |payload| ownedMoveHasUnsupportedGenericArray(payload.*, depth + 1),
            .result => |result| ownedMoveHasUnsupportedGenericArray(result.ok, depth + 1) or
                ownedMoveHasUnsupportedGenericArray(result.err, depth + 1),
            else => false,
        };
    }

    fn ownedRuntimeContainerIsRuntimeMovable(ty: ir.types.Type) bool {
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        // `Vec` is listed through the shared spelling predicate for the reason
        // `String` is listed TWICE here: `std::vec::Vec` and `alloc::vec::Vec`
        // are one type, and naming only the `alloc` one left every binding
        // whose source wrote `std::…` classified as a NON-owner. Nothing was
        // ever armed for such a binding, so its allocation was never released —
        // the same leak the `alloc` spelling of the same type does not have.
        return isAllocVecPath(external.path) or
            externalPathEqual(external.path, &.{ "alloc", "string", "String" }) or
            externalPathEqual(external.path, &.{ "std", "string", "String" }) or
            externalPathEqual(external.path, &.{ "alloc", "string", "FromUtf8Error" }) or
            externalPathEqual(external.path, &.{ "std", "string", "FromUtf8Error" }) or
            isCowPath(external.path);
    }

    /// Reject user enum payloads with known owned storage before emitting a move.
    fn ownedTaggedPayloadAt(
        self: *Lowerer,
        ty: ir.types.Type,
        depth: usize,
        inside_tagged: bool,
    ) anyerror!bool {
        if (depth >= ir.types.traversal_depth_max) return inside_tagged;
        switch (ty) {
            .external_nominal => {
                if (ownedRuntimeContainerIsRuntimeMovable(ty)) return inside_tagged;
                return false;
            },
            .tuple => |fields| {
                for (fields) |field| {
                    if (try self.ownedTaggedPayloadAt(field, depth + 1, inside_tagged)) {
                        return true;
                    }
                }
                return false;
            },
            .array => |array| {
                switch (array.len) {
                    .literal => |count| if (count == 0) return false,
                    else => {},
                }
                if (array.len == .generic and ownedRuntimeStorageAt(array.elem, depth + 1, false))
                    return error.UnsupportedOwnedGenericArrayRepresentation;
                return self.ownedTaggedPayloadAt(array.elem, depth + 1, inside_tagged);
            },
            .option => |payload| {
                return self.ownedTaggedPayloadAt(payload.*, depth + 1, inside_tagged);
            },
            .result => |result| {
                if (try self.ownedTaggedPayloadAt(result.ok, depth + 1, inside_tagged)) {
                    return true;
                }
                return self.ownedTaggedPayloadAt(result.err, depth + 1, inside_tagged);
            },
            .@"opaque" => |opaque_type| {
                const concrete = opaque_type.concrete orelse return false;
                return self.ownedTaggedPayloadAt(concrete.*, depth + 1, inside_tagged);
            },
            .path, .generic_inst => {},
            else => return false,
        }
        const entity_id: ir.spine.EntityId = switch (ty) {
            .generic_inst => |inst| inst.decl,
            .path => |path| (lastPathSegment(path.segments) orelse return false).id orelse
                return false,
            else => return false,
        };
        const generic_args: []const ir.types.Type = switch (ty) {
            .generic_inst => |inst| inst.args.params,
            else => &.{},
        };
        if (self.hashAliasDeclaration(entity_id)) |alias| {
            const target = try ir.types.substType(
                self.alloc,
                alias.target,
                alias.generic_params,
                generic_args,
            );
            return self.ownedTaggedPayloadAt(target, depth + 1, inside_tagged);
        }
        if (self.syntheticExternalType(entity_id)) |kind| {
            switch (kind) {
                .option => {
                    if (generic_args.len != 1) return error.GenericArgumentArityMismatch;
                    return self.ownedTaggedPayloadAt(generic_args[0], depth + 1, inside_tagged);
                },
                .result => {
                    if (generic_args.len != 2) return error.GenericArgumentArityMismatch;
                    return (try self.ownedTaggedPayloadAt(generic_args[0], depth + 1, inside_tagged)) or
                        (try self.ownedTaggedPayloadAt(generic_args[1], depth + 1, inside_tagged));
                },
            }
        }
        if (entity_id >= self.ir.bodies.bodies.len) return false;
        const enum_body = switch (self.ir.bodies.bodies[entity_id]) {
            .enum_ => |body| body,
            else => return false,
        };
        for (enum_body.variants) |variant| {
            const payload_count = switch (variant.fields) {
                .none => 0,
                .tuple => |tuple| tuple.len,
                .named => |named| named.len,
            };
            for (0..payload_count) |index| {
                const payload = switch (variant.fields) {
                    .tuple => |tuple| tuple[index],
                    .named => |named| named[index].ty,
                    .none => unreachable,
                };
                const spelled = if (enum_body.generic_params.len == 0) payload else try ir.types.substType(
                    self.alloc,
                    payload,
                    enum_body.generic_params,
                    generic_args,
                );
                if (try self.ownedTaggedPayloadAt(spelled, depth + 1, true)) return true;
            }
        }
        return false;
    }

    // -------------------------------------------------------------------------
    // Type Lowering
    // -------------------------------------------------------------------------

    /// A path can come from a partially recovered sidecar or from a temporary
    /// model slice. Reject null-ish/corrupt metadata before indexing it.
    fn validPathSegments(segments: []const ir.types.PathSegment) bool {
        if (segments.len == 0 or segments.len > 4096) return false;
        const address = @intFromPtr(segments.ptr);
        return address >= 4096 and address % @alignOf(ir.types.PathSegment) == 0;
    }

    /// Validate a path name before passing it to an allocator. In particular,
    /// a stale slice can carry a huge length even when its pointer is non-null.
    fn validPathName(name: []const u8) bool {
        if (name.len == 0 or name.len > 4096) return false;
        if (@intFromPtr(name.ptr) < 4096) return false;
        for (name) |c| {
            if (c == 0) return false;
        }
        return true;
    }

    fn lastPathSegment(segments: []const ir.types.PathSegment) ?ir.types.PathSegment {
        var last: ?ir.types.PathSegment = null;
        for (segments) |segment| {
            last = segment;
        }
        return last;
    }

    fn projectionImplBody(self: *const Lowerer, def: ir.spine.EntityId) ?ir.bodies.ImplBody {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        const impl_id = entity.parent orelse return null;
        if (impl_id >= self.ir.bodies.bodies.len) return null;
        const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
            .impl_ => |body| body,
            else => return null,
        };
        for (impl_body.assoc_items) |assoc_id| {
            if (assoc_id == def) return impl_body;
        }
        return null;
    }

    fn implSelfTypeMatchesReceiver(
        self: *const Lowerer,
        self_ty: ir.types.Type,
        receiver_id: ir.spine.EntityId,
    ) bool {
        return switch (self_ty) {
            .path => |self_path| blk: {
                const target = lastPathSegment(self_path.segments) orelse break :blk false;
                break :blk target.id != null and target.id.? == receiver_id;
            },
            .generic_inst => |inst| inst.decl == receiver_id,
            .reference => |reference| self.implSelfTypeMatchesReceiver(reference.pointee, receiver_id),
            .raw_ptr => |raw_ptr| self.implSelfTypeMatchesReceiver(raw_ptr.pointee, receiver_id),
            .boxed => |boxed| self.implSelfTypeMatchesReceiver(boxed.*, receiver_id),
            else => false,
        };
    }

    fn projectionMatchesImpl(
        self: *const Lowerer,
        path: ir.types.Path,
        impl_body: ir.bodies.ImplBody,
    ) bool {
        if (path.segments.len > 2) {
            const trait_segment = path.segments[1];
            const trait_id = trait_segment.id orelse return false;
            const trait_path = impl_body.trait_path orelse return false;
            const impl_trait_segment = lastPathSegment(trait_path.segments) orelse return false;
            const impl_trait_id = impl_trait_segment.id orelse return false;
            if (trait_id != impl_trait_id) return false;
            const trait_entity = self.ir.graph.symbol_table.get(trait_id) orelse return false;
            if (trait_entity.kind != .trait_) return false;
        }

        const receiver = path.segments[0];
        if (receiver.id) |receiver_id| {
            if (!self.implSelfTypeMatchesReceiver(impl_body.self_ty, receiver_id)) {
                return false;
            }
        } else if (!std.mem.eql(u8, receiver.name, "Self")) {
            if (path.segments.len < 3 or path.segments[1].id == null) return false;
        }
        return true;
    }

    fn lowerAssociatedProjection(
        self: *Lowerer,
        path: ir.types.Path,
    ) !?ast.Type {
        if (path.segments.len < 2) return null;
        const terminal = path.segments[path.segments.len - 1];
        if (terminal.id == null and path.segments.len == 3) {
            const receiver_segment = path.segments[0];
            const trait_segment = path.segments[1];
            const trait_id = trait_segment.id orelse return null;
            const trait_entity = self.ir.graph.symbol_table.get(trait_id) orelse {
                return error.MissingDefinition;
            };
            if (trait_entity.kind != .trait_ or receiver_segment.id != null or
                !self.traitHasAssociatedMember(trait_id, terminal.name))
            {
                return null;
            }
            const descriptor = try self.ensureTraitDescriptor(trait_id);
            const receiver = try self.lowerType(.{ .path = .{
                .segments = path.segments[0..1],
            } });
            const receiver_ptr = try self.allocType(receiver);
            errdefer self.alloc.destroy(receiver_ptr);
            const member = try self.alloc.dupe(u8, terminal.name);
            return .{ .projected = .{
                .descriptor = descriptor,
                .receiver = receiver_ptr,
                .member = member,
            } };
        }
        const def = terminal.id orelse return null;
        const impl_body = self.projectionImplBody(def) orelse return null;
        if (!self.projectionMatchesImpl(path, impl_body)) return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[def]) {
            .type_alias => |alias| blk: {
                if (alias.target == .path and
                    pathTypeEquals(alias.target.path, path))
                {
                    break :blk null;
                }
                break :blk try self.lowerType(alias.target);
            },
            else => null,
        };
    }

    fn isSelfPath(ty: ir.types.Type) bool {
        return switch (ty) {
            .path => |p| blk: {
                if (!validPathSegments(p.segments)) break :blk false;
                const last = lastPathSegment(p.segments) orelse break :blk false;
                break :blk validPathName(last.name) and std.mem.eql(u8, last.name, "Self");
            },
            else => false,
        };
    }

    fn pathTypeEquals(a: ir.types.Path, b: ir.types.Path) bool {
        if (a.segments.len != b.segments.len) return false;
        for (a.segments, b.segments) |left, right| {
            if (!std.mem.eql(u8, left.name, right.name) or left.id != right.id) {
                return false;
            }
        }
        return true;
    }

    fn arrayLenEquals(a: ir.types.ArrayLen, b: ir.types.ArrayLen) bool {
        return switch (a) {
            .literal => |av| switch (b) {
                .literal => |bv| av == bv,
                else => false,
            },
            .generic => |av| switch (b) {
                .generic => |bv| av == bv,
                else => false,
            },
            .expression => |av| switch (b) {
                .expression => |bv| av == bv,
                else => false,
            },
        };
    }

    fn typeSliceEquals(a: []const ir.types.Type, b: []const ir.types.Type) bool {
        if (a.len != b.len) return false;
        for (a, 0..) |value, index| {
            if (!typeEquals(value, b[index])) return false;
        }
        return true;
    }

    fn boundsEqual(a: []const ir.types.Bound, b: []const ir.types.Bound) bool {
        if (a.len != b.len) return false;
        for (a, b) |left, right| {
            if (left.optional != right.optional or !pathTypeEquals(left.path, right.path)) return false;
            if (!typeSliceEquals(left.args, right.args)) return false;
            if (left.associated_types.len != right.associated_types.len) return false;
            for (left.associated_types, right.associated_types) |left_binding, right_binding| {
                if (!std.mem.eql(u8, left_binding.name, right_binding.name)) return false;
                if (!typeEquals(left_binding.ty, right_binding.ty)) return false;
            }
        }
        return true;
    }

    fn typeEquals(a: ir.types.Type, b: ir.types.Type) bool {
        return switch (a) {
            .path => |ap| switch (b) {
                .path => |bp| pathTypeEquals(ap, bp),
                else => false,
            },
            .external_nominal => |ae| switch (b) {
                .external_nominal => |be| {
                    if (ae.path.len != be.path.len or ae.args.len != be.args.len) return false;
                    for (ae.path, be.path) |left, right| {
                        if (!std.mem.eql(u8, left, right)) return false;
                    }
                    return typeSliceEquals(ae.args, be.args);
                },
                else => false,
            },
            .prim => |ap| switch (b) {
                .prim => |bp| ap == bp,
                else => false,
            },
            .reference => |ap| switch (b) {
                .reference => |bp| ap.mut == bp.mut and typeEquals(ap.pointee, bp.pointee),
                else => false,
            },
            .raw_ptr => |ap| switch (b) {
                .raw_ptr => |bp| ap.mut == bp.mut and typeEquals(ap.pointee, bp.pointee),
                else => false,
            },
            .slice => |ap| switch (b) {
                .slice => |bp| ap.const_ == bp.const_ and typeEquals(ap.elem, bp.elem),
                else => false,
            },
            .array => |ap| switch (b) {
                .array => |bp| arrayLenEquals(ap.len, bp.len) and typeEquals(ap.elem, bp.elem),
                else => false,
            },
            .tuple => |ap| switch (b) {
                .tuple => |bp| typeSliceEquals(ap, bp),
                else => false,
            },
            .fn_ptr => |ap| switch (b) {
                .fn_ptr => |bp| typeSliceEquals(ap.params, bp.params) and typeEquals(ap.ret, bp.ret),
                else => false,
            },
            .generic_inst => |ap| switch (b) {
                .generic_inst => |bp| ap.decl == bp.decl and
                    typeSliceEquals(ap.args.params, bp.args.params),
                else => false,
            },
            .option => |ap| switch (b) {
                .option => |bp| typeEquals(ap.*, bp.*),
                else => false,
            },
            .result => |ap| switch (b) {
                .result => |bp| ap.is_error_unionable == bp.is_error_unionable and
                    typeEquals(ap.ok, bp.ok) and typeEquals(ap.err, bp.err),
                else => false,
            },
            .boxed => |ap| switch (b) {
                .boxed => |bp| typeEquals(ap.*, bp.*),
                else => false,
            },
            .@"opaque" => |ap| switch (b) {
                .@"opaque" => |bp| {
                    if (!boundsEqual(ap.bounds, bp.bounds)) return false;
                    const left = ap.concrete orelse return bp.concrete == null;
                    const right = bp.concrete orelse return false;
                    return typeEquals(left.*, right.*);
                },
                else => false,
            },
            .dyn_trait => |ap| switch (b) {
                .dyn_trait => |bp| boundsEqual(ap, bp),
                else => false,
            },
            .unsupported => |ap| switch (b) {
                .unsupported => |bp| ap.reason == bp.reason and
                    std.mem.eql(u8, ap.message, bp.message),
                else => false,
            },
        };
    }

    fn genericParamIndex(
        pattern: ir.types.Type,
        names: []const []const u8,
    ) ?usize {
        return switch (pattern) {
            .path => |path| if (path.segments.len == 1 and path.segments[0].id == null) blk: {
                for (names, 0..) |name, index| {
                    if (std.mem.eql(u8, name, path.segments[0].name)) break :blk index;
                }
                break :blk null;
            } else null,
            else => null,
        };
    }

    fn matchGenericType(
        pattern: ir.types.Type,
        actual: ir.types.Type,
        names: []const []const u8,
        slots: []?ir.types.Type,
    ) void {
        if (genericParamIndex(pattern, names)) |index| {
            if (slots[index] == null) slots[index] = actual;
            return;
        }

        switch (pattern) {
            .external_nominal => |p| switch (actual) {
                .external_nominal => |a| {
                    if (p.path.len != a.path.len) return;
                    for (p.path, a.path) |left, right| {
                        if (!std.mem.eql(u8, left, right)) return;
                    }
                    const count = @min(p.args.len, a.args.len);
                    for (0..count) |index| {
                        matchGenericType(p.args[index], a.args[index], names, slots);
                    }
                },
                else => {},
            },
            .reference => |p| switch (actual) {
                .reference => |a| matchGenericType(p.pointee, a.pointee, names, slots),
                else => {},
            },
            .raw_ptr => |p| switch (actual) {
                .raw_ptr => |a| matchGenericType(p.pointee, a.pointee, names, slots),
                else => {},
            },
            .slice => |p| switch (actual) {
                .slice => |a| matchGenericType(p.elem, a.elem, names, slots),
                else => {},
            },
            .array => |p| switch (actual) {
                .array => |a| matchGenericType(p.elem, a.elem, names, slots),
                else => {},
            },
            .tuple => |p| switch (actual) {
                .tuple => |a| {
                    const count = @min(p.len, a.len);
                    for (0..count) |index| matchGenericType(p[index], a[index], names, slots);
                },
                else => {},
            },
            .generic_inst => |p| switch (actual) {
                .generic_inst => |a| {
                    if (p.decl != a.decl) return;
                    const count = @min(p.args.params.len, a.args.params.len);
                    for (0..count) |index| {
                        matchGenericType(p.args.params[index], a.args.params[index], names, slots);
                    }
                },
                else => {},
            },
            .option => |p| switch (actual) {
                .option => |a| matchGenericType(p.*, a.*, names, slots),
                else => {},
            },
            .result => |p| switch (actual) {
                .result => |a| {
                    matchGenericType(p.ok, a.ok, names, slots);
                    matchGenericType(p.err, a.err, names, slots);
                },
                else => {},
            },
            .boxed => |p| switch (actual) {
                .boxed => |a| matchGenericType(p.*, a.*, names, slots),
                else => {},
            },
            else => {},
        }
    }

    fn concreteExprType(self: *Lowerer, expr_id: ir.exprs.NodeId) ?ir.types.Type {
        if (expr_id >= self.ir.bodies.exprs.len) return null;
        const expr = self.ir.bodies.exprs[expr_id];
        // Fall back to the lowerer's own resolver for nodes the frontend left
        // untyped. A string or byte-array literal has no `ty` but a perfectly
        // well-known Rust type, and generic inference needs that type to bind
        // a callee's parameter.
        const type_id = expr.ty orelse return self.exprType(expr_id) catch null;
        if (type_id < self.ir.types.len) return self.ir.types[type_id];
        if (type_id < self.ir.bodies.types.len) return self.ir.bodies.types[type_id];
        return null;
    }

    fn sourceCalleeReturn(self: *Lowerer, def: ir.spine.EntityId) ?ir.types.Type {
        if (def < self.ir.bodies.bodies.len) {
            switch (self.ir.bodies.bodies[def]) {
                .fn_ => |function| return function.ret,
                else => {},
            }
        }
        if (self.structMethodForDef(def)) |method| return method.ret;
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        const parent_id = entity.parent orelse return null;
        if (parent_id >= self.ir.bodies.bodies.len) return null;
        const trait_body = switch (self.ir.bodies.bodies[parent_id]) {
            .trait_ => |body| body,
            else => return null,
        };
        for (trait_body.methods) |declared| {
            if (std.mem.eql(u8, declared.name, entity.name)) return declared.ret;
        }
        return null;
    }

    fn sourceCalleeOwnParams(self: *Lowerer, def: ir.spine.EntityId) []const []const u8 {
        if (def < self.ir.bodies.bodies.len) {
            switch (self.ir.bodies.bodies[def]) {
                .fn_ => |function| return function.generic_params,
                else => {},
            }
        }
        if (self.structMethodForDef(def)) |method| return method.generic_params;
        const entity = self.ir.graph.symbol_table.get(def) orelse return &.{};
        const parent_id = entity.parent orelse return &.{};
        if (parent_id >= self.ir.bodies.bodies.len) return &.{};
        const trait_body = switch (self.ir.bodies.bodies[parent_id]) {
            .trait_ => |body| body,
            else => return &.{},
        };
        for (trait_body.methods) |declared| {
            if (std.mem.eql(u8, declared.name, entity.name)) return declared.generic_params;
        }
        return &.{};
    }

    fn sourceCallProducedType(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        annotation: ir.types.Type,
    ) anyerror!?ir.types.Type {
        if (node >= self.ir.bodies.exprs.len) return null;
        const call = switch (self.ir.bodies.exprs[node].kind) {
            .call => |value| value,
            else => return null,
        };
        const def = switch (call.call_kind) {
            .free => |value| value,
            .associated => |value| value,
            .constructor => return null,
        };
        if (annotation != .generic_inst) return null;
        if (annotation.generic_inst.decl != def) return null;

        const supplied = annotation.generic_inst.args.params;
        var produced = self.sourceCalleeReturn(def) orelse return null;
        if (self.descriptorTypeIsConcrete(produced)) return produced;

        const own = self.sourceCalleeOwnParams(def);
        const inherited = self.inheritedHoistParams(def);
        const prefix_len: usize = if (inherited.len != 0 and supplied.len == inherited.len + own.len)
            inherited.len
        else if (supplied.len > own.len)
            1
        else
            0;

        if (prefix_len != 0 and inherited.len != 0 and
            ir.types.typeContainsParam(produced, inherited))
        {
            produced = try ir.types.substType(
                self.alloc,
                produced,
                inherited,
                supplied[0..prefix_len],
            );
        }

        if (own.len != 0 and supplied.len >= prefix_len + own.len and
            ir.types.typeContainsParam(produced, own))
        {
            produced = try ir.types.substType(
                self.alloc,
                produced,
                own,
                supplied[prefix_len .. prefix_len + own.len],
            );
        }

        if (ir.types.mentionsSelf(produced)) {
            var receiver: ?ir.types.Type = null;
            if (prefix_len != 0) {
                receiver = supplied[0];
            } else if (self.projectionImplBody(def)) |body| {
                receiver = body.self_ty;
            }
            const self_type = receiver orelse return null;
            produced = (try ir.types.replaceSelfLeaves(self.alloc, self_type, produced)) orelse produced;
        }

        const owner = self.current_callable_id;
        const bound_inherited: []const []const u8 = if (owner) |id|
            self.inheritedHoistParams(id)
        else
            &.{};
        const bound_own: []const []const u8 = if (owner) |id|
            self.sourceCalleeOwnParams(id)
        else
            &.{};
        if (!self.sourceSignatureReachableAt(produced, bound_inherited, bound_own, 0)) {
            return null;
        }
        return produced;
    }

    fn sourceSignatureReachableAt(
        self: *Lowerer,
        ty: ir.types.Type,
        inherited: []const []const u8,
        own: []const []const u8,
        depth: usize,
    ) bool {
        if (depth >= ir.types.traversal_depth_max) return false;
        return switch (ty) {
            .path => |path| {
                if (path.segments.len == 0) return false;
                if (path.segments.len == 1) {
                    const segment = path.segments[0];
                    if (segment.id != null) return true;
                    if (std.mem.eql(u8, segment.name, "Self")) return true;
                    return typeParameterIsBound(segment.name, inherited, own);
                }
                if (path.segments.len == 3 and
                    path.segments[0].id == null and
                    path.segments[1].id != null)
                {
                    const head = path.segments[0].name;
                    if (!std.mem.eql(u8, head, "Self") and
                        !typeParameterIsBound(head, inherited, own)) return false;
                    if (path.segments[2].id != null) return true;
                    return self.traitHasAssociatedMember(path.segments[1].id.?, path.segments[2].name);
                }
                for (path.segments) |segment| {
                    if (segment.id == null) return false;
                }
                return true;
            },
            .reference => |value| return self.sourceSignatureReachableAt(value.pointee, inherited, own, depth + 1),
            .raw_ptr => |value| return self.sourceSignatureReachableAt(value.pointee, inherited, own, depth + 1),
            .boxed => |value| return self.sourceSignatureReachableAt(value.*, inherited, own, depth + 1),
            .slice => |value| return self.sourceSignatureReachableAt(value.elem, inherited, own, depth + 1),
            .array => |value| return self.sourceSignatureReachableAt(value.elem, inherited, own, depth + 1),
            .option => |value| return self.sourceSignatureReachableAt(value.*, inherited, own, depth + 1),
            .result => |value| return self.sourceSignatureReachableAt(value.ok, inherited, own, depth + 1) and
                self.sourceSignatureReachableAt(value.err, inherited, own, depth + 1),
            .tuple => |values| blk: {
                for (values) |value| {
                    if (!self.sourceSignatureReachableAt(value, inherited, own, depth + 1)) break :blk false;
                }
                break :blk true;
            },
            .generic_inst => |inst| blk: {
                if (inst.decl == std.math.maxInt(ir.spine.EntityId)) break :blk false;
                for (inst.args.params) |value| {
                    if (!self.sourceSignatureReachableAt(value, inherited, own, depth + 1)) break :blk false;
                }
                break :blk true;
            },
            .external_nominal => |nominal| blk: {
                if (nominal.path.len == 0) break :blk false;
                for (nominal.args) |value| {
                    if (!self.sourceSignatureReachableAt(value, inherited, own, depth + 1)) break :blk false;
                }
                break :blk true;
            },
            .fn_ptr => |fn_ptr| blk: {
                for (fn_ptr.params) |value| {
                    if (!self.sourceSignatureReachableAt(value, inherited, own, depth + 1)) break :blk false;
                }
                break :blk self.sourceSignatureReachableAt(fn_ptr.ret, inherited, own, depth + 1);
            },
            .@"opaque" => |opaque_type| if (opaque_type.concrete) |concrete|
                self.sourceSignatureReachableAt(concrete.*, inherited, own, depth + 1)
            else
                false,
            .prim, .dyn_trait, .unsupported => self.descriptorTypeIsConcrete(ty),
        };
    }

    fn inferGenericArgs(
        self: *Lowerer,
        names: []const []const u8,
        param_types: []const ir.types.Type,
        arg_ids: []const ir.exprs.NodeId,
    ) !?[]const ir.types.Type {
        if (names.len == 0) return null;
        const slots = try self.alloc.alloc(?ir.types.Type, names.len);
        defer self.alloc.free(slots);
        for (slots) |*slot| slot.* = null;

        const count = @min(param_types.len, arg_ids.len);
        for (0..count) |index| {
            if (self.concreteExprType(arg_ids[index])) |actual| {
                matchGenericType(param_types[index], actual, names, slots);
            }
        }

        var complete = true;
        for (slots) |slot| {
            if (slot == null) {
                complete = false;
                break;
            }
        }
        if (!complete) return null;

        const result = try self.alloc.alloc(ir.types.Type, names.len);
        for (slots, 0..) |slot, index| result[index] = slot.?;
        return result;
    }

    fn genericArgsFromExprType(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        def: ir.spine.EntityId,
    ) ?[]const ir.types.Type {
        const actual = self.concreteExprType(expr_id) orelse return null;
        return switch (actual) {
            .generic_inst => |inst| if (inst.decl == def) inst.args.params else null,
            else => null,
        };
    }

    fn genericParamsForDef(
        self: *Lowerer,
        def: ir.spine.EntityId,
    ) ?[]const []const u8 {
        if (def >= self.ir.bodies.bodies.len) return null;
        return switch (self.ir.bodies.bodies[def]) {
            .fn_ => |fb| if (fb.generic_params.len > 0) fb.generic_params else null,
            .struct_ => |sb| if (sb.generic_params.len > 0) sb.generic_params else null,
            else => null,
        };
    }

    /// The generic-parameter count the callee at `def` declares.
    ///
    /// A `.method_ref` is a call-site reference with no declaration of its
    /// own, so its count is the one the OWNER it names declares: a trait
    /// keeps its methods in its own body, and any other owner declares the
    /// method as a child `fn_`. This is the same read
    /// `ir.validate.methodRefGenericCount` performs before it admits a call's
    /// turbofish, so the two agree on which callee takes how many arguments.
    /// Answering zero for every `.method_ref` instead made the backend refuse
    /// `x.encode_hex::<String>()` — a `.method_ref` naming a trait method that
    /// declares one parameter — over a count the frontend had already read as
    /// one and let through.
    ///
    /// A reference whose owner declares no such method is a STANDARD-library
    /// method: `resolveMethods` leaves one as a bodiless `.method_ref` because
    /// the backend picks the implementation from the receiver type and the
    /// name. There is no arity to check it against and none is owed, so the
    /// count stays zero and a turbofish naming arguments is refused rather
    /// than invented — which is what `xs.collect::<Vec<_>>()` must still do.
    fn genericArityForDef(self: *Lowerer, def: ir.spine.EntityId) !usize {
        const entity = self.ir.graph.symbol_table.get(def) orelse {
            return error.MissingDefinition;
        };
        // Local pattern bindings and values have no generic application.
        if (entity.kind == .field or entity.kind == .const_ or entity.kind == .static_) return 0;
        if (entity.kind == .method_ref) return self.declaredMethodArity(entity) orelse 0;
        if (def < self.ir.bodies.bodies.len) {
            switch (self.ir.bodies.bodies[def]) {
                .fn_ => |fb| return fb.generic_params.len,
                .struct_ => |sb| return sb.generic_params.len,
                // A bare path naming an enum is a variant construction, and a
                // generic enum applies its parameters at that path.
                .enum_ => |eb| return eb.generic_params.len,
                else => {},
            }
        }
        const method = self.structMethodForDef(def) orelse {
            return error.GenericDefinitionMismatch;
        };
        return method.generic_params.len;
    }

    /// The generic-parameter count of the method a `.method_ref` names, or
    /// null when nothing this crate declares is what the reference names.
    ///
    /// A trait declares its methods in its own body rather than as child
    /// entities, so its signature is read from that list. Any other owner
    /// declares the method as a child `fn_` carrying it. The walk descends
    /// exactly one level below the owner, so a `fn_` owner — the shape
    /// `pushMethodRef` produces for a call written inside a callable —
    /// declares nothing of that name and answers null rather than chasing its
    /// own children.
    fn declaredMethodArity(self: *const Lowerer, reference: ir.spine.Entity) ?usize {
        const owner_id = reference.parent orelse return null;
        const owner = self.ir.graph.symbol_table.get(owner_id) orelse return null;
        if (owner.kind == .trait_) {
            if (owner_id >= self.ir.bodies.bodies.len) return null;
            const trait_body = switch (self.ir.bodies.bodies[owner_id]) {
                .trait_ => |body| body,
                else => return null,
            };
            for (trait_body.methods) |method| {
                if (std.mem.eql(u8, method.name, reference.name)) return method.generic_params.len;
            }
            return null;
        }
        for (self.ir.graph.symbol_table.entities.items, 0..) |candidate, index| {
            const parent_id = candidate.parent orelse continue;
            if (parent_id != owner_id) continue;
            if (candidate.kind != .fn_) continue;
            if (!std.mem.eql(u8, candidate.name, reference.name)) continue;
            if (index >= self.ir.bodies.bodies.len) continue;
            return switch (self.ir.bodies.bodies[index]) {
                .fn_ => |body| body.generic_params.len,
                else => null,
            };
        }
        return null;
    }

    fn inferredCallArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
        arg_ids: []const ir.exprs.NodeId,
    ) !?[]const ir.types.Type {
        const names = self.genericParamsForDef(def) orelse return null;
        if (def >= self.ir.bodies.bodies.len) return null;

        switch (self.ir.bodies.bodies[def]) {
            .fn_ => |fb| {
                const param_types = try self.alloc.alloc(ir.types.Type, fb.params.len);
                defer self.alloc.free(param_types);
                for (fb.params, 0..) |param, index| param_types[index] = param.ty;
                return self.inferGenericArgs(names, param_types, arg_ids);
            },
            .struct_ => |sb| {
                const field_types = try self.alloc.alloc(ir.types.Type, sb.fields.len);
                defer self.alloc.free(field_types);
                for (sb.fields, 0..) |field, index| field_types[index] = field.ty;
                return self.inferGenericArgs(names, field_types, arg_ids);
            },
            else => return null,
        }
    }

    /// Generic arguments recovered from the call's *result* position.
    ///
    /// A callee may mention a type parameter only in its return type — Rust's
    /// `fn collect<T: FromIterator<_>>(..) -> T` is the canonical shape. No
    /// argument carries that parameter, so argument unification cannot bind
    /// it. Unifying the callee's declared return type against the return type
    /// of the callable currently being lowered does bind it, and it binds it to
    /// the caller's own type parameter, which is exactly what the emitted Zig
    /// needs: inside a generic `fn encode_hex(comptime U: type)`, the call
    /// becomes `encode_to_iter(U, ..)`.
    fn inferredReturnArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
    ) !?[]const ir.types.Type {
        const names = self.genericParamsForDef(def) orelse return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        const fn_body = switch (self.ir.bodies.bodies[def]) {
            .fn_ => |fb| fb,
            else => return null,
        };
        const callee_ret = fn_body.ret;

        // The type this call site wants the call's value to have, strongest
        // evidence first. The declared type of the parameter this call is
        // passed as is exact, and it stays set for nested sub-expressions, so
        // it also covers a generic call that only a method receiver sits on:
        // `round(acc, get_chunk::<u32>(p).to_le())`. The enclosing callable's
        // return type is the weaker fallback — it is only the right shape for
        // a call in tail position. Both are tried, so every binding that
        // already worked still works; this only adds bindings.
        if (try self.bindReturnShape(callee_ret, names, self.expected_argument_type)) |bound| {
            return bound;
        }
        return self.bindReturnShape(callee_ret, names, self.current_return_type);
    }

    /// Bind a callee's type parameters by unifying its declared return type
    /// against the type its call site wants.
    ///
    /// A dereference in the source removes one borrow layer between the two:
    /// `*f()` where `f()` is declared `-> &T` supplies `T`, not `&T`, to a
    /// context that asked for `T`. `matchGenericType` compares borrows
    /// structurally, so while the shapes disagree its `.reference` arm never
    /// matches and the parameter stays unbound. Normalize the callee to the
    /// requested shape rather than adding a second inference door for it.
    ///
    /// Only the callee is peeled, and only while it stays more borrowed than
    /// the context, so a call whose shapes already agree keeps its declared
    /// return type and its existing binding.
    fn bindReturnShape(
        self: *Lowerer,
        callee_ret: ir.types.Type,
        names: []const []const u8,
        maybe_expected: ?ir.types.Type,
    ) !?[]const ir.types.Type {
        const expected = maybe_expected orelse return null;
        var shaped = callee_ret;
        while (referenceDepth(shaped) > referenceDepth(expected)) {
            const borrowed = switch (shaped) {
                .reference => |value| value,
                else => break,
            };
            shaped = borrowed.pointee;
        }

        const slots = try self.alloc.alloc(?ir.types.Type, names.len);
        defer self.alloc.free(slots);
        for (slots) |*slot| slot.* = null;
        matchGenericType(shaped, expected, names, slots);

        for (slots) |slot| {
            if (slot == null) return null;
        }
        const result = try self.alloc.alloc(ir.types.Type, names.len);
        for (slots, 0..) |slot, index| result[index] = slot.?;
        return result;
    }

    /// Borrow layers wrapping `ty`. A dereference is the only operation that
    /// removes one, so this counts how many a context may have consumed
    /// between a call and the value that call produced.
    fn referenceDepth(ty: ir.types.Type) usize {
        var depth: usize = 0;
        var current = ty;
        while (true) {
            switch (current) {
                .reference => |borrowed| {
                    depth += 1;
                    current = borrowed.pointee;
                },
                else => return depth,
            }
        }
    }

    fn structMethodForDef(self: *const Lowerer, def: ir.spine.EntityId) ?ir.bodies.StructMethod {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        var parent_id = entity.parent;
        while (parent_id) |id| {
            if (id < self.ir.bodies.bodies.len) {
                switch (self.ir.bodies.bodies[id]) {
                    .struct_ => |sb| {
                        for (sb.methods) |method| {
                            if (std.mem.eql(u8, method.name, entity.name)) return method;
                        }
                    },
                    else => {},
                }
            }
            const parent = self.ir.graph.symbol_table.get(id) orelse break;
            parent_id = parent.parent;
        }
        return null;
    }
    fn methodAllocates(
        self: *Lowerer,
        owner_id: ir.spine.EntityId,
        method: ir.bodies.StructMethod,
    ) bool {
        if (structMethodTakesAllocator(self, method, 0)) return true;
        if (self.methodEntityForDefinition(owner_id, method)) |method_id| {
            return self.callPassesAllocator(method_id);
        }
        const effects: []const bool = if (self.allocation_effects) |values| values else &.{};
        const scanner: AllocationEffectScanner = .{
            .exprs = self.ir.bodies.exprs,
            .stmts = self.ir.bodies.stmts,
            .effects = effects,
            .comparison_temporaries = self.comparison_temporaries orelse &.{},
            .owner_cleanups = self.owner_cleanups orelse &.{},
            .pattern_cleanups = self.pattern_cleanups orelse &.{},
            .hash_dispatches = self.hash_dispatches orelse &.{},
            .hash_source_methods = self.hash_source_methods orelse &.{},
        };
        return scanner.exprAllocates(method.body);
    }

    fn methodFallible(
        self: *Lowerer,
        owner_id: ir.spine.EntityId,
        method: ir.bodies.StructMethod,
    ) bool {
        if (self.methodEntityForDefinition(owner_id, method)) |method_id| {
            return self.callableFallible(method_id);
        }
        const scanner: AllocationEffectScanner = .{
            .exprs = self.ir.bodies.exprs,
            .stmts = self.ir.bodies.stmts,
            .effects = self.fallibility_effects orelse &.{},
            .comparison_temporaries = &.{},
            // An owner release cannot fail, so a method whose only effect is
            // cleanup contributes nothing to the failure table it reads here.
            .owner_cleanups = &.{},
            .pattern_cleanups = &.{},
            .hash_dispatches = self.hash_dispatches orelse &.{},
            .hash_source_methods = self.hash_source_methods orelse &.{},
        };
        return scanner.exprAllocates(method.body);
    }

    fn directFreeCallArgumentType(
        self: *Lowerer,
        call_kind: ir.exprs.CallKind,
        arg_index: usize,
    ) ?ir.types.Type {
        const def = switch (call_kind) {
            .free => |free_def| free_def,
            else => return null,
        };
        if (def >= self.ir.bodies.bodies.len) return null;
        const params = switch (self.ir.bodies.bodies[def]) {
            .fn_ => |function| function.params,
            else => return null,
        };
        if (arg_index >= params.len) return null;
        return params[arg_index].ty;
    }

    /// Whether `call` hands argument `arg_index` over as the ADDRESS a
    /// declared `&mut R` parameter needs.
    ///
    /// `lowerType` spells a borrow of a fat value AS that value — `&str` is
    /// `[]const u8`, `&[T]` is `[]const T`, `&dyn Trait` is the erased handle
    /// — because the fat pointer already carries everything the borrow names.
    /// A borrow of a type PARAMETER is not fat: it lowers to the Zig pointer
    /// `*R`, since a bare parameter is the pointee and the callee writes
    /// through it. So an argument whose own type lowers to a fat value reaches
    /// that pointer only once it is addressed.
    ///
    /// The question is asked of the declared parameter and the argument's own
    /// recorded type, never of a name: every translated generic whose
    /// parameter is `&mut T` is answered the same way, and an argument that is
    /// already a pointer — `&readable`, a dereference — is the pointer the
    /// parameter wants, so it is never addressed a second time.
    fn argumentTakesGenericBorrowAddress(
        self: *Lowerer,
        call: ir.exprs.Call,
        arg_index: usize,
        arg_id: ir.exprs.NodeId,
    ) anyerror!bool {
        const declared = self.directCallParameterType(call, arg_index) orelse return false;
        const reference = switch (declared) {
            .reference => |value| value,
            else => return false,
        };
        const generic_names = self.genericParamsForDef(self.directCallDef(call) orelse return false) orelse
            return false;
        if (!typeNamesGenericParam(reference.pointee, generic_names)) return false;
        const argument_type = (try self.exprType(arg_id)) orelse return false;
        return lowersToFatValue(argument_type);
    }

    /// The definition a direct call names, or null when it is not one.
    fn directCallDef(_: *const Lowerer, call: ir.exprs.Call) ?ir.spine.EntityId {
        return switch (call.call_kind) {
            .free => |def_id| def_id,
            .associated => |def_id| def_id,
            .constructor => null,
        };
    }

    /// The declared type of one direct call argument.
    ///
    /// `directFreeCallArgumentType` is this for the free calls alone, which is
    /// all the expected-type context asks for; an associated call declares the
    /// same list and the borrow bridge needs it too.
    fn directCallParameterType(
        self: *const Lowerer,
        call: ir.exprs.Call,
        arg_index: usize,
    ) ?ir.types.Type {
        const def = self.directCallDef(call) orelse return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        const params = switch (self.ir.bodies.bodies[def]) {
            .fn_ => |function| function.params,
            else => return null,
        };
        if (arg_index >= params.len) return null;
        return params[arg_index].ty;
    }

    /// Whether this type is one of the callee's own type parameters, spelled
    /// the way the IR spells one: a single-segment path with no graph entity,
    /// because a declared type always resolves to one.
    fn typeNamesGenericParam(ty: ir.types.Type, generic_names: []const []const u8) bool {
        const path = switch (ty) {
            .path => |value| value,
            else => return false,
        };
        if (path.segments.len != 1) return false;
        if (path.segments[0].id != null) return false;
        for (generic_names) |generic_name| {
            if (std.mem.eql(u8, generic_name, path.segments[0].name)) return true;
        }
        return false;
    }

    /// Whether this value LOWERS to a fat Zig value — a slice descriptor or a
    /// borrowed dyn handle — rather than to a pointer.
    ///
    /// `dynErasedValueNeedsAddress` asks the same question for a handle that
    /// has to point AT the value; there the answer defaults to "address it",
    /// because anything that is not already a pointer has to be given one.
    /// Here the default is the opposite: only a fat value is something a `*R`
    /// parameter cannot take as it stands.
    fn lowersToFatValue(ty: ir.types.Type) bool {
        return switch (ty) {
            .reference => |reference| borrowLowersToFatValue(reference.pointee),
            .raw_ptr => |pointer| isSliceShapedBorrow(pointer.pointee),
            .slice => true,
            .dyn_trait => true,
            else => false,
        };
    }
    fn methodCallArgumentType(
        self: *Lowerer,
        method_def: ir.spine.EntityId,
        arg_index: usize,
    ) ?ir.types.Type {
        const method = self.structMethodForDef(method_def) orelse return null;
        if (arg_index >= method.params.len) return null;
        return method.params[arg_index].ty;
    }

    /// Whether the direct call that is a source `?`'s operand lowers to a
    /// TAGGED `Result`, which decides whether Rust's `?` can stand in for the
    /// Zig `try` it would otherwise take.
    ///
    /// Rust's `?` absorbs the callee's own error union, which is why the
    /// operand is not handed a second `try`: `let x = fallible()?;` is one
    /// propagation in the source and must stay one in the emitted Zig. That
    /// holds only while the propagated `Result` IS the Zig error union. A
    /// `Result` whose error type is not a Zig error set lowers to the tagged
    /// `r2z.Result(T, E)`, and a declaration returning one is published as
    /// `!r2z.Result(T, E)` — the source error travels in the payload and the
    /// INJECTED allocation failure is the outer error set, which Rust's `?`
    /// cannot reach. The tag switch the operand lowers to reads the payload's
    /// `Ok`/`Err` tags and leaves the outer error set unconsumed, so the `try`
    /// has to stay.
    fn explicitTryOperandIsTaggedResult(self: *Lowerer, expr_id: ir.exprs.NodeId) bool {
        // A type the frontend never recorded cannot be a tagged `Result`, and
        // the call site keeps the `try` it has always had.
        const operand_type = self.exprType(expr_id) catch return false;
        const result = switch (operand_type orelse return false) {
            .result => |descriptor| descriptor.*,
            else => return false,
        };
        return !self.resultFieldsUseErrorUnion(result);
    }

    fn lowerDirectCallResult(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        expr: ast.Expr,
        allocates: bool,
        fallible: bool,
    ) !ast.Expr {
        if (allocates) self.current_callable_is_allocating = true;
        if (!fallible) return expr;
        if (self.explicit_try_expr) |explicit_expr| {
            if (explicit_expr == expr_id and !self.explicitTryOperandIsTaggedResult(expr_id)) return expr;
        }
        return .{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(expr),
        } };
    }

    fn inferredMethodArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
        arg_ids: []const ir.exprs.NodeId,
    ) !?[]const ir.types.Type {
        const method = self.structMethodForDef(def) orelse return null;
        if (method.generic_params.len == 0) return null;
        const param_types = try self.alloc.alloc(ir.types.Type, method.params.len);
        defer self.alloc.free(param_types);
        for (method.params, 0..) |param, index| param_types[index] = param.ty;
        return self.inferGenericArgs(method.generic_params, param_types, arg_ids);
    }

    fn inferredStructLitArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
        fields: []const ir.exprs.FieldInit,
    ) !?[]const ir.types.Type {
        const names = self.genericParamsForDef(def) orelse return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        const sb = switch (self.ir.bodies.bodies[def]) {
            .struct_ => |body| body,
            else => return null,
        };

        const slots = try self.alloc.alloc(?ir.types.Type, names.len);
        defer self.alloc.free(slots);
        for (slots) |*slot| slot.* = null;
        for (fields) |field| {
            if (self.concreteExprType(field.value)) |actual| {
                for (sb.fields) |declared| {
                    if (std.mem.eql(u8, declared.name, field.field)) {
                        matchGenericType(declared.ty, actual, names, slots);
                        break;
                    }
                }
            }
        }

        var complete = true;
        for (slots) |slot| {
            if (slot == null) {
                complete = false;
                break;
            }
        }
        if (!complete) return null;

        const result = try self.alloc.alloc(ir.types.Type, names.len);
        for (slots, 0..) |slot, index| result[index] = slot.?;
        return result;
    }
    /// Select concrete arguments for this expression only. A missing
    /// preference is intentionally not resolved by declaration-wide order:
    /// two call sites may instantiate the same generic with different types.
    fn claimInstantiation(
        self: *Lowerer,
        def: ir.spine.EntityId,
        preferred: ?[]const ir.types.Type,
    ) ?ir.types.GenericArgs {
        const args = preferred orelse return null;
        for (self.ir.instantiations) |inst| {
            if (inst.generic_id == def and typeSliceEquals(inst.args.params, args)) {
                return inst.args;
            }
        }
        return .{ .params = args };
    }

    fn lowerGenericArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
        preferred: ?[]const ir.types.Type,
    ) ![]const ast.Type {
        const expected_arity = try self.genericArityForDef(def);
        const selected = if (preferred) |args| blk: {
            if (args.len != expected_arity) return error.GenericArgumentArityMismatch;
            break :blk self.claimInstantiation(def, args) orelse ir.types.GenericArgs{ .params = args };
        } else blk: {
            if (expected_arity != 0) return error.GenericInferenceFailed;
            break :blk ir.types.GenericArgs{ .params = &.{} };
        };
        if (selected.params.len != expected_arity) {
            return error.GenericArgumentArityMismatch;
        }
        if (selected.params.len == 0) return &.{};
        return self.lowerGenericArgTypes(def, selected.params);
    }

    /// Lower one callee's generic arguments in DECLARATION order, binding a
    /// `Hash`-bound slot to the caller's DESCRIPTOR instead of to a Zig type.
    ///
    /// Arity is unchanged and no slot is inserted or dropped: the Zig
    /// parameter is `comptime T: type` either way, so only what binds to it
    /// differs. An ordinary parameter still receives `T.Type` through
    /// `lowerType`, which is what keeps a `Hash`-bound argument usable by a
    /// callee that never heard of the descriptor.
    fn lowerGenericArgTypes(
        self: *Lowerer,
        def: ir.spine.EntityId,
        params: []const ir.types.Type,
    ) anyerror![]const ast.Type {
        const names = self.genericParamsForDef(def) orelse &.{};
        const result = try self.alloc.alloc(ast.Type, params.len);
        for (params, 0..) |param, index| {
            result[index] = if (index < names.len and
                self.isHashDescriptorParameterFor(names[index], def))
                try self.hashDescriptorType(param)
            else
                try self.lowerType(param);
        }
        return result;
    }

    /// Generic arguments for one call site, preferring what the source
    /// pinned over what inference can recover.
    ///
    /// `explicit` is the call's own turbofish, empty for a call that wrote
    /// none. A turbofish is the source stating which instantiation it wants,
    /// so it outranks every inferred door below: `x.encode_hex::<String>()`
    /// names its result type outright, and neither the (empty) argument list
    /// nor the caller's own return position says anything an inference pass
    /// could read the type back out of.
    fn lowerCallGenericArgs(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        def: ir.spine.EntityId,
        arg_ids: []const ir.exprs.NodeId,
        explicit: []const ir.types.Type,
    ) ![]const ast.Type {
        if (explicit.len != 0) return self.lowerGenericArgs(def, explicit);
        if (self.concreteExprType(expr_id)) |actual| {
            switch (actual) {
                .generic_inst => |inst| {
                    if (inst.decl == def) {
                        // Associated calls can carry the impl's inherited
                        // Self type ahead of the method's own parameters.
                        // Ordinary blanket receiver calls prepend it elsewhere.
                        const source_call = self.ir.bodies.exprs[expr_id].kind;
                        if (source_call == .call and source_call.call.call_kind == .associated) {
                            const entity = self.ir.graph.symbol_table.get(def) orelse return error.MissingDefinition;
                            if (entity.parent) |parent_id| {
                                const parent = self.ir.graph.symbol_table.get(parent_id) orelse return error.MissingDefinition;
                                if (hoistTargetFor(parent)) |target_id| {
                                    const inherited = self.moduleHoistGenericParams(parent, target_id);
                                    if (inherited.len != 0 and inst.args.params.len == inherited.len + try self.genericArityForDef(def)) {
                                        const result = try self.alloc.alloc(ast.Type, inst.args.params.len);
                                        const own = self.genericParamsForDef(def) orelse &.{};
                                        for (inst.args.params, 0..) |parameter, index| {
                                            // The impl's own parameters lead this
                                            // list, so a slot before
                                            // `inherited.len` answers to the impl
                                            // and a slot after it to the method.
                                            const bound_name: ?[]const u8 = if (index < inherited.len)
                                                inherited[index]
                                            else if (index - inherited.len < own.len)
                                                own[index - inherited.len]
                                            else
                                                null;
                                            result[index] = if (bound_name != null and
                                                self.isHashDescriptorParameterFor(bound_name.?, def))
                                                try self.hashDescriptorType(parameter)
                                            else
                                                try self.lowerType(parameter);
                                        }
                                        return result;
                                    }
                                }
                            }
                        }
                        return self.lowerGenericArgs(def, inst.args.params);
                    }
                },
                // `Cursor::new(buf)` yields `Cursor<[u8; 1]>`, an EXTERNAL
                // nominal rather than a `generic_inst` of the callee: the
                // callee returns that nominal and its argument is the very
                // type parameter the call instantiated, so the call's own
                // result type carries the argument.
                .external_nominal => |actual_nominal| {
                    if (try self.bindExternalReturnArgs(def, actual_nominal)) |bound| {
                        return self.lowerGenericArgs(def, bound);
                    }
                },
                else => {},
            }
        }
        if (try self.inferredCallArgs(def, arg_ids)) |inferred| {
            return self.lowerGenericArgs(def, inferred);
        }
        if (try self.inferredMethodArgs(def, arg_ids)) |inferred| {
            return self.lowerGenericArgs(def, inferred);
        }
        // Last door: the callee's type parameter may live only in its return
        // type, in which case only the caller's own return type can supply it.
        if (try self.inferredReturnArgs(def)) |inferred| {
            return self.lowerGenericArgs(def, inferred);
        }
        return self.lowerGenericArgs(def, null);
    }

    /// Generic arguments recovered by unifying a callee's declared return
    /// type against the concrete type THIS call produced.
    ///
    /// `Cursor::new(buf)` yields `Cursor<[u8; 1]>`. The callee returns an
    /// external nominal whose argument is the very type parameter the call
    /// instantiated, so the two types say the same thing about that argument
    /// and unifying them binds it. Argument unification cannot: the callee's
    /// `inner: T` is one slot the call fills with a VALUE, not a type, so
    /// nothing in the argument list names `T`.
    ///
    /// This reads the call node in front of it and never a global
    /// instantiation table. Several call sites share this one callee id and
    /// each names a different instantiation — leb128 reads
    /// `Cursor<[u8; 1]>`, `Cursor<[u8; 1024]>` and `Cursor<Vec<u8>>` through
    /// the same `Cursor::new` — so only the type at this call can say which.
    /// A table scanned by callee would hand all three whichever it found
    /// first: a wrong answer for at least two of them, not a missing one.
    fn bindExternalReturnArgs(
        self: *Lowerer,
        def: ir.spine.EntityId,
        actual: ir.types.ExternalNominal,
    ) !?[]const ir.types.Type {
        const names = self.genericParamsForDef(def) orelse return null;
        if (names.len == 0 or actual.args.len == 0) return null;
        if (def >= self.ir.bodies.bodies.len) return null;
        const fn_body = switch (self.ir.bodies.bodies[def]) {
            .fn_ => |fb| fb,
            else => return null,
        };
        const declared = switch (fn_body.ret) {
            .external_nominal => |nominal| nominal,
            else => return null,
        };
        if (declared.args.len != actual.args.len) return null;
        const slots = try self.alloc.alloc(?ir.types.Type, names.len);
        defer self.alloc.free(slots);
        for (slots) |*slot| slot.* = null;
        // `matchGenericType` already compares the owner path, refuses a
        // different nominal, and recurses into the arguments — which is the
        // whole shape of this unification.
        matchGenericType(
            .{ .external_nominal = declared },
            .{ .external_nominal = actual },
            names,
            slots,
        );
        for (slots) |slot| {
            if (slot == null) return null;
        }
        const result = try self.alloc.alloc(ir.types.Type, names.len);
        for (slots, 0..) |slot, index| result[index] = slot.?;
        return result;
    }

    /// Lower a tuple-struct constructor as a typed struct literal. A
    /// constructor's generic arguments belong to the type application
    /// (`Foo(T)`), while its source arguments initialize tuple fields.
    fn lowerTupleStructConstructor(
        self: *Lowerer,
        def: ir.spine.EntityId,
        generic_args: []const ast.Type,
        args: []const ast.Expr,
    ) !ast.Expr {
        if (def >= self.ir.bodies.bodies.len) return error.MissingBodyId;
        const entity = self.ir.graph.symbol_table.get(def) orelse {
            return error.MissingDefinition;
        };
        if (entity.kind != .struct_) return error.InvalidConstructorDefinition;
        const struct_body = switch (self.ir.bodies.bodies[def]) {
            .struct_ => |body| body,
            else => return error.DeclarationBodyMismatch,
        };
        if (struct_body.layout != .tuple) return error.InvalidConstructorDefinition;
        if (args.len != struct_body.fields.len) return error.ConstructorArityMismatch;

        const name = try self.lowerResolvedEntityName(def);
        const type_name: ast.Type = if (generic_args.len > 0)
            ast.Type{ .generic = .{ .name = name, .params = generic_args } }
        else
            ast.Type{ .named = name };

        var fields = try self.alloc.alloc(ast.StructInitField, args.len);
        errdefer self.alloc.free(fields);
        for (args, 0..) |arg, index| {
            const field_name = try std.fmt.allocPrint(self.alloc, "{d}", .{index});
            errdefer self.alloc.free(field_name);
            fields[index] = .{
                .name = field_name,
                .expr = arg,
            };
        }

        return .{
            .struct_init = .{
                .type_name = type_name,
                .fields = fields,
            },
        };
    }

    /// One `Ok`/`Err` arm of the tagged `r2z.Result` union. `type_name` is
    /// null when no surrounding context names the union, which is the only
    /// case the anonymous `.{}` form can still coerce in.
    fn taggedResultArm(
        self: *Lowerer,
        variant: []const u8,
        payload: ast.Expr,
        type_name: ?ast.Type,
    ) !ast.Expr {
        const fields = try self.alloc.alloc(ast.StructInitField, 1);
        errdefer self.alloc.free(fields);
        const name = try self.alloc.dupe(u8, variant);
        errdefer self.alloc.free(name);
        fields[0] = .{ .name = name, .expr = payload };
        return .{ .struct_init = .{ .type_name = type_name, .fields = fields } };
    }
    fn lowerTaggedResult(self: *Lowerer, ok: ir.types.Type, err: ir.types.Type) !ast.Type {
        try self.markRuntimeImport();
        const params = try self.alloc.alloc(ast.Type, 2);
        errdefer self.alloc.free(params);
        params[0] = try self.lowerType(ok);
        params[1] = try self.lowerType(err);
        return .{ .generic = .{ .name = "r2z.Result", .params = params } };
    }

    /// True when `ty` can be spelled as a Zig error set.
    ///
    /// A Zig error set is a finite list of payload-free names, so only a
    /// fieldless `enum` qualifies. A data-carrying error enum
    /// (`FromHexError::InvalidHexCharacter { c, index }`) cannot: an error
    /// union would have to drop the payload, and the tagged `r2z.Result`
    /// union keeps it. `ir.types.Result.is_error_unionable` records that the
    /// frontend was asked to treat the error as a set, not that the shape
    /// permits one.
    fn errorTypeIsZigErrorSet(self: *const Lowerer, ty: ir.types.Type) bool {
        // A standard error whose Zig spelling IS an error set is one however
        // the source named it, so the classification is read from the same
        // answer `lowerExternalNominal` builds the type from rather than from
        // the entity graph alone.
        if (externalErrorSetName(ty) != null) return true;
        const id = self.nominalEntityForType(ty) orelse return false;
        if (id >= self.ir.bodies.bodies.len) return false;
        const enum_body = switch (self.ir.bodies.bodies[id]) {
            .enum_ => |body| body,
            else => return false,
        };
        if (enum_body.variants.len == 0) return false;
        for (enum_body.variants) |variant| {
            if (variant.fields != .none) return false;
        }
        return true;
    }

    /// Entity behind a nominal type, looking through the indirections that
    /// never change which type is named.
    fn nominalEntityForType(_: *const Lowerer, ty: ir.types.Type) ?ir.spine.EntityId {
        var current = ty;
        for (0..32) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .boxed => |boxed| current = boxed.*,
                .@"opaque" => |opaque_type| current = (opaque_type.concrete orelse return null).*,
                .generic_inst => |inst| return inst.decl,
                else => break,
            }
        }
        const path = switch (current) {
            .path => |p| p,
            else => return null,
        };
        const segment = lastPathSegment(path.segments) orelse return null;
        return segment.id;
    }

    /// True when a `Result` type lowers to a Zig error union, which is the
    /// representation `Ok`/`Err` constructors and `.unwrap()` must match.
    fn resultUsesErrorUnion(self: *const Lowerer, ty: ir.types.Type) bool {
        const result = resultDescriptorOf(ty) orelse return false;
        return self.resultFieldsUseErrorUnion(result);
    }

    /// The same question asked of a `Result` whose fields are already in hand,
    /// so a caller that has unwrapped one asks exactly what a caller holding
    /// the type asks.
    fn resultFieldsUseErrorUnion(self: *const Lowerer, result: ir.types.Result) bool {
        return result.is_error_unionable and self.errorTypeIsZigErrorSet(result.err);
    }

    /// The source error type of a `Result` receiver, read through the same
    /// indirections `resultUsesErrorUnion` peels before it looks for one.
    fn resultErrorTypeOf(self: *const Lowerer, ty: ir.types.Type) ?ir.types.Type {
        _ = self;
        var current = ty;
        for (0..128) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .boxed => |boxed| current = boxed.*,
                .@"opaque" => |opaque_type| current = (opaque_type.concrete orelse return null).*,
                else => break,
            }
        }
        return switch (current) {
            .result => |result| result.err,
            else => null,
        };
    }

    /// The variant name an `Err` payload is already an error tag by: a
    /// payload-free variant of the error enum, which is `error.Name` in the
    /// error slot. Only meaningful under `resultUsesErrorUnion`, which is
    /// what makes every variant of that enum payload-free. The name is
    /// borrowed from the IR; the caller owns the copy it emits.
    fn errorTagConstant(
        self: *const Lowerer,
        payload_node: ir.exprs.NodeId,
        err_ty: ir.types.Type,
    ) ?[]const u8 {
        const err_enum = self.nominalEntityForType(err_ty) orelse return null;
        if (err_enum >= self.ir.bodies.bodies.len) return null;
        if (payload_node >= self.ir.bodies.exprs.len) return null;
        const variant = switch (self.ir.bodies.exprs[payload_node].kind) {
            .enum_variant => |ev| ev,
            else => return null,
        };
        if (variant.variant.len == 0) return null;
        if (variant.tuple_fields.len != 0 or variant.named_fields.len != 0) return null;
        // `def` names the variant when the graph linked one and the owning
        // enum otherwise, so the owner is one level up in the first case —
        // the same resolution `enumOwnerName` reads. A name the error enum
        // does not declare is not a tag it could carry.
        const entity = self.ir.graph.symbol_table.get(variant.def) orelse return null;
        const owner = switch (entity.kind) {
            .variant => entity.parent orelse return null,
            .enum_ => variant.def,
            else => return null,
        };
        if (owner != err_enum) return null;
        const enum_body = switch (self.ir.bodies.bodies[err_enum]) {
            .enum_ => |body| body,
            else => return null,
        };
        for (enum_body.variants) |declared| {
            if (std.mem.eql(u8, declared.name, variant.variant)) return variant.variant;
        }
        return null;
    }

    /// The error value an `Err` payload carries into a Zig error union.
    ///
    /// An ordinary value is mapped tag by tag here — after it was lowered, so
    /// every node under it stays the value it is — because the Zig enum a
    /// Rust error enum lowers to is a different type from the `error.Name` the
    /// union holds. The mapping is exhaustive: one arm per declared variant.
    fn errorTagMapping(
        self: *Lowerer,
        payload: ast.Expr,
        err_ty: ir.types.Type,
    ) !ast.Expr {
        // A refusal marker stays where the refusal plumbing put it.
        if (payload == .unsupported) return payload;
        const err_enum = self.nominalEntityForType(err_ty) orelse
            return error.MissingTypeDefinition;
        if (err_enum >= self.ir.bodies.bodies.len) return error.MissingTypeDefinition;
        const variants = switch (self.ir.bodies.bodies[err_enum]) {
            .enum_ => |body| body.variants,
            else => return error.DeclarationBodyMismatch,
        };
        if (variants.len == 0) return error.MissingVariantDefinition;
        const arms = try self.alloc.alloc(ast.MatchArm, variants.len);
        errdefer self.alloc.free(arms);
        for (variants, 0..) |variant, index| {
            const selector = try self.alloc.alloc(ast.Pattern, 1);
            errdefer self.alloc.free(selector);
            const selector_name = try self.alloc.dupe(u8, variant.name);
            errdefer self.alloc.free(selector_name);
            selector[0] = .{ .enum_literal = selector_name };
            const tag = try self.alloc.dupe(u8, variant.name);
            errdefer self.alloc.free(tag);
            arms[index] = .{
                .patterns = selector,
                .body = .{ .lit = .{ .error_tag = tag } },
            };
        }
        return .{ .match_expr = .{
            .target = try self.allocExpr(payload),
            .arms = arms,
        } };
    }

    const SyntheticExternalType = enum {
        option,
        result,
    };

    fn syntheticExternalType(
        self: *const Lowerer,
        entity_id: ir.spine.EntityId,
    ) ?SyntheticExternalType {
        const entity = self.ir.graph.symbol_table.get(entity_id) orelse return null;
        if (entity.kind != .enum_) return null;
        const module_id = entity.parent orelse return null;
        const module = self.moduleForEntity(module_id) orelse return null;
        if (!module.is_extern) return null;
        const root_id = module.parent orelse return null;
        const root = self.moduleForEntity(root_id) orelse return null;
        if (!root.is_extern or
            (!std.mem.eql(u8, root.name, "core") and !std.mem.eql(u8, root.name, "std")))
        {
            return null;
        }
        if (std.mem.eql(u8, module.name, "option") and
            std.mem.eql(u8, entity.name, "Option"))
        {
            return .option;
        }
        if (std.mem.eql(u8, module.name, "result") and
            std.mem.eql(u8, entity.name, "Result"))
        {
            return .result;
        }
        return null;
    }

    fn lowerSyntheticExternalType(
        self: *Lowerer,
        kind: SyntheticExternalType,
        args: []const ir.types.Type,
    ) !ast.Type {
        return switch (kind) {
            .option => {
                if (args.len != 1) return error.GenericArgumentArityMismatch;
                return .{ .opt = try self.allocType(try self.lowerType(args[0])) };
            },
            .result => {
                if (args.len != 2) return error.GenericArgumentArityMismatch;
                return self.lowerTaggedResult(args[0], args[1]);
            },
        };
    }

    fn lowerRuntimeGenericExternalType(
        self: *Lowerer,
        name: []const u8,
        args: []const ir.types.Type,
        expected_arity: usize,
    ) !ast.Type {
        if (args.len != expected_arity) return error.GenericArgumentArityMismatch;
        if (std.mem.startsWith(u8, name, "r2z.")) try self.markRuntimeImport();
        const params = try self.alloc.alloc(ast.Type, args.len);
        errdefer self.alloc.free(params);
        for (args, 0..) |arg, index| params[index] = try self.lowerType(arg);
        return .{ .generic = .{
            .name = try self.alloc.dupe(u8, name),
            .params = params,
        } };
    }

    /// Mark the runtime import when `ty` is a type name the strategy resolved
    /// into the `r2z` namespace.
    ///
    /// `lowerRuntimeGenericExternalType` does this for the names lower.zig
    /// builds itself, but a strategy can return an `r2z.` name on its own
    /// (`DefaultStrategy.lowerStdGeneric` maps a type called `HashMap` with
    /// three parameters to `r2z.collections.HashMap`) and it has no route to
    /// the module bookkeeping — it only receives the `LoweringStrategy`
    /// vtable, not the `Lowerer`. The mark therefore belongs at the call
    /// site, on the same prefix test the two other name-to-runtime paths use.
    ///
    /// Only `.named` is checked: that is the form a strategy-built runtime
    /// type takes. A `.generic` name still has to be marked by whoever built
    /// it, since the parameters are where that lowering happens.
    fn markRuntimeTypeImport(self: *Lowerer, ty: ast.Type) !void {
        switch (ty) {
            .named => |name| {
                if (std.mem.startsWith(u8, name, "r2z.")) try self.markRuntimeImport();
            },
            else => {},
        }
    }

    fn lowerExternalNominal(
        self: *Lowerer,
        external: ir.types.ExternalNominal,
    ) !ast.Type {
        if (external.path.len == 0) return error.InvalidTypePath;
        if (ir.types.isStr(.{ .external_nominal = external })) {
            return .{ .slice = .{
                .elem = try self.allocType(.{ .prim = .u8 }),
                .is_const = true,
            } };
        }

        if (externalPathEqual(external.path, &.{ "core", "fmt", "Formatter" }) or
            externalPathEqual(external.path, &.{ "std", "fmt", "Formatter" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            return .{ .named = "std.Io.Writer" };
        }

        if (externalPathEqual(external.path, &.{ "core", "fmt", "Error" }) or
            externalPathEqual(external.path, &.{ "std", "fmt", "Error" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            return .{ .named = "std.Io.Writer.Error" };
        }

        if (externalPathEqual(external.path, &.{ "core", "fmt", "Result" }) or
            externalPathEqual(external.path, &.{ "std", "fmt", "Result" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            const payload = try self.allocType(.{ .void_type = {} });
            return .{ .err_union = .{
                .err_set = "std.Io.Writer.Error",
                .payload = payload,
            } };
        }

        if (externalPathEqual(external.path, &.{ "std", "io", "Error" }) or
            externalPathEqual(external.path, &.{ "std", "io", "ErrorKind" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = if (std.mem.eql(u8, external.path[2], "Error"))
                "r2z.io.Error"
            else
                "r2z.io.ErrorKind" };
        }

        // `rand_core::Error` is the one type a runtime-bound dependency
        // contributes, and it is bound by PACKAGE identity rather than by
        // spelling: the disposition table is keyed by both the Cargo dependency
        // key and the package name, so `use rand_core::Error;` and
        // `use rng_api::Error;` answer alike while an unrelated package that
        // merely carries the name falls through to the refusal below.
        //
        // It is an ordinary runtime type, never an error set.
        // `externalErrorSetName` answers only for `std::fmt::Error`, so
        // `errorTypeIsZigErrorSet` is false and a `Result` carrying this keeps
        // its code payload in a tagged `r2z.Result` rather than collapsing into
        // a Zig error union. `try_fill_bytes` never constructs an error, so
        // there is no constructor to lower here either.
        if (external.path.len == 2 and
            std.mem.eql(u8, external.path[1], "Error") and
            self.rootIsRuntimeBound(external.path[0]))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.random.Error" };
        }

        // `Cursor<T>` reads and writes through a read position kept beside
        // the source it owns or borrows, and the runtime cursor is generic
        // over exactly that source. A cursor over an owned array allocates
        // nothing, and a cursor over a borrowed slice leaves the borrow alone.
        if (externalPathEqual(external.path, &.{ "std", "io", "Cursor" })) {
            return self.lowerRuntimeGenericExternalType("r2z.io.Cursor", external.args, 1);
        }

        // `BufReader<R>` reads through a fixed-size buffer the runtime owns
        // BESIDE the reader it wraps, so the wrapped reader is the whole type
        // parameter and the buffer is not one. Nothing is copied out of `R` and
        // nothing is allocated here; the buffer belongs to the value the
        // constructor builds.
        if (externalPathEqual(external.path, &.{ "std", "io", "BufReader" })) {
            return self.lowerRuntimeGenericExternalType("r2z.io.BufReader", external.args, 1);
        }

        if (externalPathEqual(external.path, &.{ "core", "option", "Option" }) or
            externalPathEqual(external.path, &.{ "std", "option", "Option" }))
        {
            if (external.args.len != 1) return error.GenericArgumentArityMismatch;
            return .{ .opt = try self.allocType(try self.lowerType(external.args[0])) };
        }

        if (externalPathEqual(external.path, &.{ "core", "result", "Result" }) or
            externalPathEqual(external.path, &.{ "std", "result", "Result" }))
        {
            if (external.args.len != 2) return error.GenericArgumentArityMismatch;
            return self.lowerTaggedResult(external.args[0], external.args[1]);
        }
        if (externalPathEqual(external.path, &.{ "core", "convert", "TryInto", "Error" }) or
            externalPathEqual(external.path, &.{ "std", "convert", "TryInto", "Error" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.convert.Error", external.args, 2);
        }
        if (externalPathEqual(external.path, &.{ "core", "convert", "Infallible" }) or
            externalPathEqual(external.path, &.{ "std", "convert", "Infallible" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.convert.Infallible" };
        }
        if (externalPathEqual(external.path, &.{ "alloc", "string", "String" }) or
            externalPathEqual(external.path, &.{ "std", "string", "String" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.alloc.String" };
        }

        if (isAllocVecPath(external.path)) {
            return self.lowerRuntimeGenericExternalType("std.ArrayListUnmanaged", external.args, 1);
        }

        if (isCowPath(external.path)) {
            if (external.args.len != 1) return error.GenericArgumentArityMismatch;
            if (external.args[0] == .slice) {
                const slice = external.args[0].slice;
                return self.lowerRuntimeGenericExternalType(
                    "r2z.alloc.CowSlice",
                    &.{slice.elem},
                    1,
                );
            }
            if (!ir.types.isStr(external.args[0])) return error.UnsupportedExternalNominalType;
            try self.markRuntimeImport();
            return .{ .named = "r2z.alloc.CowStr" };
        }

        if (externalPathEqual(external.path, &.{ "core", "mem", "MaybeUninit" }) or
            externalPathEqual(external.path, &.{ "std", "mem", "MaybeUninit" }))
        {
            if (external.args.len != 1) return error.GenericArgumentArityMismatch;
            return self.lowerType(external.args[0]);
        }

        if (externalPathEqual(external.path, &.{ "core", "str", "Utf8Error" }) or
            externalPathEqual(external.path, &.{ "std", "str", "Utf8Error" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.character.Utf8Error" };
        }
        if (externalPathEqual(external.path, &.{ "alloc", "string", "FromUtf8Error" }) or
            externalPathEqual(external.path, &.{ "std", "string", "FromUtf8Error" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.alloc.FromUtf8Error" };
        }
        if (externalPathEqual(external.path, &.{ "core", "num", "TryFromIntError" }) or
            externalPathEqual(external.path, &.{ "std", "num", "TryFromIntError" }))
        {
            if (external.args.len != 0) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.convert.TryFromIntError" };
        }

        if (externalPathEqual(external.path, &.{ "core", "ops", "Range" }) or
            externalPathEqual(external.path, &.{ "std", "ops", "Range" }))
        {
            if (external.args.len != 1) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            return .{ .named = "r2z.Range" };
        }

        if (externalPathEqual(external.path, &.{ "core", "slice", "Iter" }) or
            externalPathEqual(external.path, &.{ "std", "slice", "Iter" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.SliceIter", external.args, 1);
        }
        if (externalPathEqual(external.path, &.{ "core", "slice", "IterMut" }) or
            externalPathEqual(external.path, &.{ "std", "slice", "IterMut" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.SliceIterMut", external.args, 1);
        }
        if (externalPathEqual(external.path, &.{ "core", "slice", "Chunks" }) or
            externalPathEqual(external.path, &.{ "std", "slice", "Chunks" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.Chunks", external.args, 1);
        }
        if (externalPathEqual(external.path, &.{ "core", "slice", "ChunksExact" }) or
            externalPathEqual(external.path, &.{ "std", "slice", "ChunksExact" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.ChunksExact", external.args, 1);
        }
        if (externalPathEqual(external.path, &.{ "core", "slice", "Windows" }) or
            externalPathEqual(external.path, &.{ "std", "slice", "Windows" }))
        {
            return self.lowerRuntimeGenericExternalType("r2z.Windows", external.args, 1);
        }

        if (external.path.len == 3 and
            (std.mem.eql(u8, external.path[0], "core") or
                std.mem.eql(u8, external.path[0], "std")) and
            std.mem.eql(u8, external.path[1], "iter"))
        {
            const name = if (std.mem.eql(u8, external.path[2], "StepBy"))
                "r2z.StepBy"
            else if (std.mem.eql(u8, external.path[2], "Skip"))
                "r2z.Skip"
            else if (std.mem.eql(u8, external.path[2], "Enumerate"))
                "r2z.Enumerate"
            else if (std.mem.eql(u8, external.path[2], "Rev"))
                "r2z.Rev"
            else if (std.mem.eql(u8, external.path[2], "Zip"))
                "r2z.Zip"
            else
                "";
            if (name.len != 0) {
                return self.lowerRuntimeGenericExternalType(
                    name,
                    external.args,
                    if (std.mem.eql(u8, name, "r2z.Zip")) 2 else 1,
                );
            }
        }

        if (externalPathEqual(external.path, &.{
            "core",
            "hash",
            "BuildHasherDefault",
        }) or externalPathEqual(external.path, &.{
            "std",
            "hash",
            "BuildHasherDefault",
        })) {
            if (external.args.len != 1) return error.GenericArgumentArityMismatch;
            try self.markRuntimeImport();
            const params = try self.alloc.alloc(ast.Type, 1);
            params[0] = try self.lowerType(external.args[0]);
            return .{ .generic = .{
                .name = try self.alloc.dupe(u8, "r2z.BuildHasherDefault"),
                .params = params,
            } };
        }

        // `HashMap`/`HashSet` keep the `BuildHasher` the Rust source named.
        // They must NOT become `std.AutoHashMap`: that would substitute
        // Wyhash for the crate's own algorithm, which for the `fnv` crate
        // silently deletes the only thing it provides. The builder argument
        // is forwarded untouched and the r2z runtime builds a
        // `std.hash_map` context from it.
        //
        // The builder parameter is required. A bare `HashMap<K, V>` means
        // Rust's `RandomState`, which is seeded per process and has no
        // static Zig equivalent, so it keeps rejecting.
        if (isCollectionsMapPath(external.path)) {
            if (external.args.len != 3) return error.GenericArgumentArityMismatch;
            return self.lowerRuntimeGenericExternalType(
                "r2z.collections.HashMap",
                external.args,
                3,
            );
        }
        if (isCollectionsSetPath(external.path)) {
            if (external.args.len != 2) return error.GenericArgumentArityMismatch;
            return self.lowerRuntimeGenericExternalType(
                "r2z.collections.HashSet",
                external.args,
                2,
            );
        }

        // Unknown external nominals have no faithful Zig equivalent here.
        // Do not emit a plausible-looking name or a null type.
        return error.UnsupportedExternalNominalType;
    }

    fn isTypeDefinition(kind: ir.spine.EntityKind) bool {
        return switch (kind) {
            .struct_, .enum_, .union_, .trait_, .type_alias => true,
            else => false,
        };
    }

    fn validateTypePath(self: *Lowerer, path: ir.types.Path) !void {
        if (!validPathSegments(path.segments)) return error.InvalidTypePath;
        for (path.segments) |segment| {
            if (!validPathName(segment.name)) return error.InvalidTypePath;
            if (segment.id) |id| {
                const entity = self.ir.graph.symbol_table.get(id) orelse {
                    return error.MissingTypeDefinition;
                };
                if (!isTypeDefinition(entity.kind)) return error.InvalidTypeDefinition;
            }
        }
    }

    /// The borrowed handle a trait object lowers to.
    const DynTraitHandle = enum {
        read,
        write,
        error_handle,
    };

    /// True when `bounds` declares the trait named at `wanted`.
    ///
    /// The identity is the BOUND PATH, resolved the way Rust resolves a name
    /// in the scope that declares it — `ir.bodies`' own generic-bound proof,
    /// the same question `fn f<T: Read>` is answered with — so a crate's own
    /// `Read` is never `std::io::Read`, and a `dyn Read` in a module that
    /// never imported the standard trait does not match on spelling alone.
    ///
    /// That scope walk reads the module's `use` declarations, and a `use std;`
    /// that names a graph entity answers for every path spelled `std::…` from
    /// there down. A bound the source wrote out in full (`dyn std::io::Read`)
    /// therefore has a second, independent answer: a path whose EVERY segment
    /// carries no entity id names nothing this crate declares, because a local
    /// name always resolves to one, so for exactly that shape the written path
    /// IS the trait. It is compared segment by segment under the same
    /// `std`/`core` rule `boundPathMatches` applies at the root, so both
    /// answers accept the same trait and neither compares a bare leaf name.
    fn dynTraitBoundIs(
        self: *const Lowerer,
        bounds: []const ir.types.Bound,
        wanted: []const []const u8,
    ) bool {
        if (self.traitBoundOwner()) |owner| {
            const object: ir.types.Type = .{ .dyn_trait = bounds };
            if (ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, object, wanted) != null) {
                return true;
            }
        }
        for (bounds) |bound| {
            if (externalBoundPathIs(bound.path, wanted)) return true;
        }
        return false;
    }

    /// The entity a bound in the declaration being lowered resolves from: the
    /// callable whose signature or body carries it, or the module that owns
    /// that callable when there is none in scope yet. Both reach the enclosing
    /// scope through their parent edges, which is the chain the bound walk
    /// follows, and both are real declarations — unlike the bound's own first
    /// segment, which is exactly null for a path written out in full.
    fn traitBoundOwner(self: *const Lowerer) ?ir.spine.EntityId {
        return self.current_callable_id orelse self.current_module_id;
    }

    fn dynTraitHandleFor(
        self: *const Lowerer,
        bounds: []const ir.types.Bound,
    ) ?DynTraitHandle {
        if (self.dynTraitBoundIs(bounds, &.{ "std", "io", "Read" })) return .read;
        if (self.dynTraitBoundIs(bounds, &.{ "std", "io", "Write" })) return .write;
        // `std::error::Error` re-exports `core::error::Error`, and either
        // spelling in the source names the same trait, so both are asked.
        if (self.dynTraitBoundIs(bounds, &.{ "core", "error", "Error" }) or
            self.dynTraitBoundIs(bounds, &.{ "std", "error", "Error" }))
        {
            return .error_handle;
        }
        return null;
    }

    /// The borrowed handle for a supported trait object.
    ///
    /// `dyn Trait + 'a` may also carry marker traits (`Send`, `Sync`,
    /// `Unpin`), which the runtime represents by neither adding nor removing
    /// anything: a handle borrows, so it is as shareable as the value it
    /// points at. Any OTHER bound names a trait with no runtime handle, and
    /// erasing it would mean inventing a vtable entry no runtime declares, so
    /// it is refused rather than approximated.
    fn lowerDynTraitType(self: *Lowerer, bounds: []const ir.types.Bound) !ast.Type {
        const handle = self.dynTraitHandleFor(bounds) orelse
            return error.UnsupportedDynamicTrait;
        try self.markRuntimeImport();
        return .{ .named = switch (handle) {
            .read => "r2z.io.DynRead",
            .write => "r2z.io.DynWrite",
            .error_handle => "r2z.io.DynError",
        } };
    }

    /// The handle a context is asking this expression to become, when the
    /// context names one by trait.
    ///
    /// Only a BORROW erases: `&dyn Trait` is the fat pointer the source means
    /// by a trait-object borrow, and it is what the handles are borrowed
    /// spellings of. An owned `Box<dyn Trait>` has no faithful handle here —
    /// the runtime handle owns nothing — so it is left to refuse.
    fn dynCoercionTarget(
        self: *const Lowerer,
        expected: ir.types.Type,
    ) ?DynTraitHandle {
        const pointee = switch (expected) {
            .reference => |reference| reference.pointee,
            else => return null,
        };
        const bounds = switch (pointee) {
            .dyn_trait => |declared| declared,
            else => return null,
        };
        return self.dynTraitHandleFor(bounds);
    }

    /// True when the receiver IS a trait object rather than a concrete value.
    ///
    /// A trait object has no other lowering, so its methods must be answered
    /// from the standard-method table even when the resolver recorded the call
    /// against something other than a trait method reference — a standard
    /// trait has no graph entity of its own to point at.
    fn dynTraitMethodReceiver(self: *Lowerer, receiver_node: ir.exprs.NodeId) anyerror!bool {
        const owned = (try self.receiverValueType(receiver_node)) orelse return false;
        return owned == .dyn_trait;
    }

    /// Whether `method_name` on `ty` is one of the runtime's OWN methods that
    /// grows storage, so the allocator belongs in its argument list.
    ///
    /// `r2z.alloc.String` spells `push`, `push_str` and `extend` exactly as
    /// Rust's `String` does and takes the allocator first, so the only thing
    /// missing is the argument itself — the mutable-receiver binding those
    /// calls need is already in place. `Vec` is excluded on purpose: its
    /// runtime names are `append` and `appendSlice`, so it is answered by its
    /// own arms rather than by borrowing these.
    fn stdMethodTakesAllocatorArg(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        method_name: []const u8,
    ) anyerror!bool {
        if (!std.mem.eql(u8, method_name, "push") and
            !std.mem.eql(u8, method_name, "push_str") and
            !std.mem.eql(u8, method_name, "extend")) return false;
        const receiver_type = (try self.exprType(receiver_node)) orelse return false;
        return ownedStringType(receiver_type) != null;
    }

    /// True when the expression already carries the trait-object type the
    /// context asks for, so there is nothing left to erase.
    fn exprAlreadyDynTrait(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        handle: DynTraitHandle,
    ) anyerror!bool {
        const receiver_type = (try self.exprType(expr_id)) orelse return false;
        const pointee = switch (receiver_type) {
            .reference => |reference| reference.pointee,
            else => return false,
        };
        if (pointee != .dyn_trait) return false;
        return self.dynTraitHandleFor(pointee.dyn_trait) == handle;
    }

    /// Whether this `&`/`&mut` node is a borrow whose own value IS the trait
    /// object, so the address-of reifies nothing.
    ///
    /// `lowerType` spells a borrow of a trait object AS that object: `&dyn
    /// Trait` and `&mut dyn Trait` are the borrowed handle, because the
    /// handle already carries the erased pointer to the caller's own value
    /// and a `*r2z.io.DynRead` would be a second indirection the source never
    /// wrote. The address-of has to follow that identity instead of
    /// contradicting it.
    ///
    /// The shape is reached when the source's `&mut concrete` is recorded
    /// against the `&mut dyn Trait` its coercion produces — which is exactly
    /// `read_byte(&mut reader)`. There the coercion belongs to the OPERAND,
    /// so the borrow must hand the operand straight through and let the
    /// operand become the handle; addressing the borrow instead wrapped the
    /// finished handle in a pointer, and a parameter declared by value cannot
    /// take one.
    ///
    /// The question is asked of the borrow's own recorded type, so it holds
    /// for every receiver the coercion can produce — a slice descriptor, a
    /// cursor, a vector — and never for a borrow of a concrete type, which
    /// really is an address.
    fn borrowIsTraitObjectItself(self: *Lowerer, expr_id: ir.exprs.NodeId) anyerror!bool {
        const node_type = (try self.exprType(expr_id)) orelse return false;
        const pointee = switch (node_type) {
            .reference => |reference| reference.pointee,
            else => return false,
        };
        if (pointee != .dyn_trait) return false;
        return self.dynTraitHandleFor(pointee.dyn_trait) != null;
    }

    /// Whether the value `expr_id` lowers to has to be ADDRESSED before it can
    /// be the pointer a dyn handle erases a concrete borrow into.
    ///
    /// `lowerType` spells a borrow of a fat value AS that value: `&str` is
    /// `[]const u8`, `&[T]` is `[]const T`, and `&dyn Trait` is the handle
    /// itself. Those three lower to VALUES, so a receiver that is one of them
    /// is the descriptor the handle has to point AT — handing the value on
    /// instead would let the read position the runtime advances die with the
    /// copy, which is exactly the `reader` of `read_byte(&mut reader)` behind
    /// a `&[u8]`: the caller's own slice would never move. Every other borrow
    /// lowers to `*T`, and `*T` already IS the address.
    ///
    /// The question is asked of the LOWERED type, never of the node that
    /// wrote the borrow or of the borrow's own spelling, so `&mut cursor`,
    /// `&mut vec` and a `&mut Concrete` binding moved into a call all answer
    /// the one way their value really is.
    fn dynErasedValueNeedsAddress(self: *Lowerer, expr_id: ir.exprs.NodeId) anyerror!bool {
        var current = (try self.exprType(expr_id)) orelse return true;
        for (0..128) |_| {
            switch (current) {
                // A borrow of a fat value lowers to that VALUE, so it is the
                // descriptor the handle points at and has to be addressed. A
                // borrow of a sized value lowers to `*T`, which already IS the
                // address — addressing that again would hand the runtime a
                // pointer to a pointer with no `read` behind it.
                .reference => |reference| return isSliceShapedBorrow(reference.pointee) or
                    reference.pointee == .dyn_trait,
                .raw_ptr => return isSliceShapedBorrow(current.raw_ptr.pointee),
                .boxed => |boxed| current = boxed.*,
                .@"opaque" => |opaque_type| {
                    current = (opaque_type.concrete orelse return true).*;
                },
                else => return true,
            }
        }
        return true;
    }

    /// The handle the context around this expression asks it to become.
    ///
    /// A declared parameter, a declared binding, and a value an enclosing
    /// expression already typed all reach this one answer, so erasing a
    /// concrete borrow into a trait object needs no new IR tag and no second
    /// call site.
    fn dynCoercionContext(self: *const Lowerer) ?DynTraitHandle {
        const expected = self.expected_value_type orelse
            self.expected_argument_type orelse return null;
        return self.dynCoercionTarget(expected);
    }

    /// Lower a `let` initializer under the binding's own DECLARED type when
    /// that type names a trait object.
    ///
    /// A declared type is normally a hint the initializer already carries, and
    /// the existing shapes lower without it. A trait-object binding is
    /// different: the declaration is the only place the source states that
    /// the value is to be erased, so it is what the initializer is lowered
    /// against, and every other declared type is left exactly as it was.
    fn lowerLetInitializer(
        self: *Lowerer,
        init_id: ir.exprs.NodeId,
        declared_type: ?ir.types.Type,
    ) !ast.Expr {
        if (declared_type) |declared| {
            if (self.dynCoercionTarget(declared) != null) {
                const previous_value_type = self.expected_value_type;
                self.expected_value_type = declared;
                defer self.expected_value_type = previous_value_type;
                return self.lowerExpr(init_id);
            }
        }
        return self.lowerExpr(init_id);
    }

    /// Bind a handle to the caller's own value, so nothing is copied.
    ///
    /// The erased pointer is the ADDRESS of the value the source borrowed — the
    /// caller's own slice descriptor, vector, cursor, or error — so read
    /// position, written length, and error fields keep living where the caller
    /// left them. `dynErasedValueNeedsAddress` decides what still has to be
    /// addressed to reach that address: a borrow of a fat value lowers to the
    /// value itself, so it is addressed, and a borrow of a sized value already
    /// lowers to a pointer and is passed through. `DynWrite` carries the
    /// allocator its appends need, so building one takes the caller's allocator
    /// and makes the enclosing callable declare one, exactly as every other
    /// allocating runtime call does.
    fn buildDynTraitHandle(
        self: *Lowerer,
        handle: DynTraitHandle,
        expr_id: ir.exprs.NodeId,
        lowered: ast.Expr,
    ) !ast.Expr {
        try self.markRuntimeImport();
        if (handle == .write) self.current_callable_is_allocating = true;
        const source = try self.allocExpr(lowered);
        const target = if (try self.dynErasedValueNeedsAddress(expr_id))
            try self.allocExpr(.{ .unary_op = .{
                .op = .addr_of,
                .operand = source,
            } })
        else
            source;
        const takes_allocator = handle == .write;
        const call_args = try self.alloc.alloc(ast.Expr, if (takes_allocator) 2 else 1);
        call_args[0] = target.*;
        if (takes_allocator) call_args[1] = .{ .ident = "allocator" };
        return (try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = switch (handle) {
                .read => "r2z.io.DynRead.init",
                .write => "r2z.io.DynWrite.init",
                .error_handle => "r2z.io.DynError.init",
            } }),
            .args = call_args,
        } })).*;
    }

    /// True when `def` is a std/core `io` module's `new` whose DECLARED return
    /// type is the external nominal named `owner` with one generic argument.
    ///
    /// The return type is the identity, not a parent hop: the standard library
    /// seeds `Cursor::new` and `BufReader::new` as siblings parented straight
    /// to the EXTERNAL `io` module, so nothing between either constructor and
    /// that module can tell them apart. What does is the signature — and it is
    /// the signature the emitter matches on when it lowers this same nominal
    /// to `r2z.io.Cursor` / `r2z.io.BufReader`, so a constructor is claimed
    /// exactly when the type it returns is the runtime type it will produce.
    /// The module chain still has to be the external `std`/`core` `io` module,
    /// which is what keeps a crate's own `new` its own constructor.
    fn isExternalIoNewReturning(
        self: *const Lowerer,
        def: ir.spine.EntityId,
        owner: []const u8,
    ) bool {
        const entity = self.ir.graph.symbol_table.get(def) orelse return false;
        if (entity.kind != .fn_) return false;
        if (!std.mem.eql(u8, entity.name, "new")) return false;
        if (entity.renamed_to) |renamed| {
            if (!std.mem.eql(u8, renamed, "new")) return false;
        }
        const module = self.moduleForEntity(entity.parent orelse return false) orelse return false;
        if (!module.is_extern or !std.mem.eql(u8, module.name, "io")) return false;
        const root = self.moduleForEntity(module.parent orelse return false) orelse return false;
        if (!root.is_extern) return false;
        if (!std.mem.eql(u8, root.name, "std") and !std.mem.eql(u8, root.name, "core")) {
            return false;
        }
        if (def >= self.ir.bodies.bodies.len) return false;
        const declared = switch (self.ir.bodies.bodies[def]) {
            .fn_ => |body| switch (body.ret) {
                .external_nominal => |nominal| nominal,
                else => return false,
            },
            else => return false,
        };
        if (declared.args.len != 1) return false;
        const expected = [_][]const u8{ "std", "io", owner };
        return externalPathEqual(declared.path, &expected);
    }

    /// True when `def` is `std::io::Cursor::new`.
    fn isIoCursorNew(self: *const Lowerer, def: ir.spine.EntityId) bool {
        return self.isExternalIoNewReturning(def, "Cursor");
    }

    /// True when `def` is `std::io::BufReader::new`.
    fn isIoBufReaderNew(self: *const Lowerer, def: ir.spine.EntityId) bool {
        return self.isExternalIoNewReturning(def, "BufReader");
    }

    /// True when `def` names a variant of `std::io::ErrorKind`.
    ///
    /// The identity is the declaration's own place in the graph, exactly as
    /// `isIoCursorNew` decides the same question for `Cursor::new`: the owning
    /// enum must live in an EXTERNAL `io` module whose own root is `std` or
    /// `core`, so a crate that declares its own `ErrorKind` keeps its own
    /// variants and this never claims them. An `enum_variant` node names the
    /// VARIANT entity when the graph linked one — one level below its enum —
    /// and the enum itself when it did not, so both are resolved here.
    fn isIoErrorKindVariant(self: *const Lowerer, def: ir.spine.EntityId) bool {
        const entity = self.ir.graph.symbol_table.get(def) orelse return false;
        const owner_id = switch (entity.kind) {
            .variant => entity.parent orelse return false,
            else => def,
        };
        const owner = self.ir.graph.symbol_table.get(owner_id) orelse return false;
        if (!std.mem.eql(u8, owner.name, "ErrorKind")) return false;
        if (owner.renamed_to) |renamed| {
            if (!std.mem.eql(u8, renamed, "ErrorKind")) return false;
        }
        const module_id = owner.parent orelse return false;
        const module = self.moduleForEntity(module_id) orelse return false;
        if (!module.is_extern or !std.mem.eql(u8, module.name, "io")) return false;
        const root_id = module.parent orelse return false;
        const root = self.moduleForEntity(root_id) orelse return false;
        if (!root.is_extern) return false;
        return std.mem.eql(u8, root.name, "std") or std.mem.eql(u8, root.name, "core");
    }

    pub fn lowerType(self: *Lowerer, ir_ty: ir.types.Type) anyerror!ast.Type {
        // Structural lowering is arena-backed and always safe to retain. The
        // pluggable strategy is consulted only for standard generic name
        // mapping (returns `.named` values — never transient pointers).
        return switch (ir_ty) {
            .prim => |p| ast.Type{ .prim = lowerPrim(p) },
            .@"opaque" => |opaque_type| self.lowerType(
                (opaque_type.concrete orelse return error.UnresolvedOpaqueType).*,
            ),
            .dyn_trait => |bounds| try self.lowerDynTraitType(bounds),
            .slice => |s| ast.Type{
                .slice = .{
                    .elem = try self.allocType(try self.lowerType(s.elem)),
                    .is_const = s.const_,
                },
            },
            // `&str` and `&[T]` are the borrow of a fat pointer, and Zig spells
            // both as a slice. Emitting `*const []const T` instead is a
            // pointer *to* the slice: it cannot borrow a `&[u8; N]`
            // byte-string literal, and every `s[i]` then needs a manual
            // dereference. `&[T; N]` stays a pointer to the array, which is
            // what a byte-string literal already is.
            .reference => |r| blk: {
                const pointee = self.hashPayloadPointee(r.pointee);
                if (hashResolvedFatElement(pointee)) |elem| break :blk .{ .slice = .{
                    .elem = try self.allocType(try self.lowerType(elem)),
                    .is_const = !r.mut,
                } };
                if (pointee == .dyn_trait) break :blk try self.lowerDynTraitType(pointee.dyn_trait);
                if (self.hashReferenceNeedsDescriptor(pointee))
                    break :blk try self.hashReferenceZigType(.{ .mut = r.mut, .pointee = pointee });
                break :blk .{ .ptr = .{
                    .elem = try self.allocType(try self.lowerType(r.pointee)),
                    .is_const = !r.mut,
                    .size = .one,
                } };
            },
            // A raw pointer to an UNSIZED pointee is the fat pointer itself:
            // `*const [u8]` carries the element AND the length, and Zig spells
            // that `[]const u8`. A pointer *to* the slice would be a thin
            // pointer to a fat value — a different type, a different width,
            // and `@ptrCast` to or from it is a width change Zig refuses.
            .raw_ptr => |r| blk: {
                const pointee = self.hashPayloadPointee(r.pointee);
                if (self.hashReferenceNeedsDescriptor(pointee))
                    break :blk try self.hashRawPointerPayloadType(pointee, r.mut);
                if (hashResolvedFatElement(pointee)) |elem| break :blk .{ .slice = .{
                    .elem = try self.allocType(try self.lowerType(elem)),
                    .is_const = !r.mut,
                } };
                break :blk .{ .ptr = .{
                    .elem = try self.allocType(try self.lowerType(r.pointee)),
                    .is_const = !r.mut,
                    .is_allowzero = true,
                    .size = .many,
                    .alignment = 1,
                } };
            },
            .array => |a| blk: {
                const elem_ty = try self.allocType(try self.lowerType(a.elem));
                switch (a.len) {
                    // The IR length and the AST length are both `u64`: a
                    // count describes the target's array, and translating it
                    // must not depend on the translator's own pointer width.
                    .literal => |len| break :blk ast.Type{
                        .array = .{
                            .elem = elem_ty,
                            .len = len,
                        },
                    },
                    .generic => break :blk ast.Type{
                        .slice = .{
                            .elem = elem_ty,
                            .is_const = true,
                        },
                    },
                    .expression => |length| break :blk .{ .array_expr = .{
                        .elem = elem_ty,
                        .len = try self.allocExpr(try self.lowerExpr(length)),
                    } },
                }
            },
            .option => |opt| ast.Type{
                .opt = try self.allocType(try self.lowerType(opt.*)),
            },
            .result => |r| blk: {
                if (r.is_error_unionable and self.errorTypeIsZigErrorSet(r.err)) {
                    // Rust Result is a reusable value type, not an inferred
                    // function-return error set. Its error set must also be
                    // valid in locals and nested Option/container types.
                    const payload_ty = try self.allocType(try self.lowerType(r.ok));
                    break :blk ast.Type{
                        .err_union = .{
                            .err_set = "anyerror",
                            .payload = payload_ty,
                        },
                    };
                } else {
                    break :blk try self.lowerTaggedResult(r.ok, r.err);
                }
            },
            .tuple => |elems| blk: {
                var arr = try self.alloc.alloc(ast.Type, elems.len);
                for (elems, 0..) |e, i| {
                    arr[i] = try self.lowerType(e);
                }
                break :blk ast.Type{ .tuple = arr };
            },
            .path => |p| blk: {
                try self.validateTypePath(p);
                if (try self.lowerAssociatedProjection(p)) |projection| {
                    break :blk projection;
                }
                const last_segment = lastPathSegment(p.segments) orelse {
                    return error.InvalidTypePath;
                };
                if (try self.strat.lowerStdGeneric(last_segment.name, &.{})) |std_ty| {
                    try self.markRuntimeTypeImport(std_ty);
                    break :blk std_ty;
                }
                if (last_segment.id) |def| {
                    break :blk ast.Type{
                        .named = try self.lowerResolvedEntityName(def),
                    };
                }
                if (p.segments.len > 1) {
                    return error.UnsupportedAssociatedTypeProjection;
                }
                // A `Hash`-bound parameter is not the Zig type: it binds to a
                // descriptor, and the type every ordinary callee, field and
                // annotation wants back is that descriptor's own payload.
                // The signature is unchanged — the parameter still reads
                // `comptime T: type` — so only the body is projected.
                if (self.isHashDescriptorParameter(last_segment.name)) {
                    try self.markRuntimeImport();
                    break :blk ast.Type{ .named = try std.fmt.allocPrint(
                        self.alloc,
                        "{s}.Type",
                        .{last_segment.name},
                    ) };
                }
                break :blk ast.Type{ .named = try self.alloc.dupe(u8, last_segment.name) };
            },
            .external_nominal => |external| try self.lowerExternalNominal(external),
            .generic_inst => |gi| blk: {
                if (self.syntheticExternalType(gi.decl)) |synthetic_kind| {
                    break :blk try self.lowerSyntheticExternalType(
                        synthetic_kind,
                        gi.args.params,
                    );
                }
                const entity = self.ir.graph.symbol_table.get(gi.decl) orelse {
                    return error.MissingTypeDefinition;
                };
                if (!isTypeDefinition(entity.kind)) return error.InvalidTypeDefinition;
                const decl_name = entity.renamed_to orelse entity.name;
                if (decl_name.len == 0) return error.MissingTypeDefinition;
                const expected_arity = try self.genericArityForDef(gi.decl);
                if (gi.args.params.len != expected_arity) {
                    return error.GenericArgumentArityMismatch;
                }
                if (try self.strat.lowerStdGeneric(decl_name, gi.args.params)) |std_ty| {
                    try self.markRuntimeTypeImport(std_ty);
                    break :blk std_ty;
                }
                var params = try self.alloc.alloc(ast.Type, gi.args.params.len);
                for (gi.args.params, 0..) |p, i| {
                    params[i] = try self.lowerType(p);
                }
                break :blk ast.Type{
                    .generic = .{
                        .name = try self.lowerResolvedEntityName(gi.decl),
                        .params = params,
                    },
                };
            },
            .boxed => |b| try self.lowerType(b.*),
            .fn_ptr => |function| blk: {
                const params = try self.alloc.alloc(ast.Type, function.params.len);
                for (function.params, params) |param, *lowered| {
                    lowered.* = try self.lowerType(param);
                }
                break :blk .{ .fn_ptr = .{
                    .params = params,
                    .ret = try self.allocType(try self.lowerType(function.ret)),
                } };
            },
            .unsupported => return error.UnsupportedType,
        };
    }

    fn lowerPrim(p: ir.types.Prim) ast.Prim {
        return switch (p) {
            .i8 => .i8,
            .i16 => .i16,
            .i32 => .i32,
            .i64 => .i64,
            .i128 => .i128,
            .u8 => .u8,
            .u16 => .u16,
            .u32 => .u32,
            .u64 => .u64,
            .u128 => .u128,
            .isize => .isize,
            .usize => .usize,
            .f32 => .f32,
            .f64 => .f64,
            .bool => .bool,
            .char => .u21,
            .unit => .void_type,
            .never => .noreturn_type,
        };
    }

    // ---------------------------------------------------------------------
    // core::hash::Hash descriptors
    //
    // A `Hash`-bound parameter keeps its Zig spelling, `comptime T: type`, but
    // what binds to it is a descriptor, not a Zig type: `T.Type` is the type
    // every ordinary callee wants back. No signature arity or parameter
    // spelling changes. Everything here is gated on a bound the DECLARATION
    // proved through `ir.bodies.genericBound`, so a generic with no `Hash`
    // bound keeps the type and the borrow it has always had.
    //
    // All typed AST: the layout is an `ast.StructInit` over
    // `r2z.RustHashLayout`, never source text.

    /// The only spelling of `Hash` this file accepts.
    ///
    /// `boundPathMatches` resolves the name through the scope's own `use` and
    /// answers for `core` and `std` alike, so a crate's own `Hash` homonym
    /// proves nothing.
    const canonical_hash_bound = [_][]const u8{ "core", "hash", "Hash" };

    const hash_descriptor_runtime = "r2z.RustHashType";
    const hash_layout_runtime = "r2z.RustHashLayout";
    const hash_reference_runtime = "r2z.RustHashRef";
    const hash_reference_is_fat_runtime = "r2z.rustHashRefIsFat";

    /// The IR type a bare parameter name spells, for `genericBound` to read.
    ///
    /// `segments` is supplied by the CALLER, not built here: a pointer to a
    /// literal created inside this function would dangle the moment it
    /// returned, and `genericBound` reads the name back out of that slice —
    /// so `T: core::hash::Hash` would compare against a garbage name and
    /// answer no bound for a bound the source did spell.
    fn hashParameterType(segments: []const ir.types.PathSegment) ir.types.Type {
        return .{ .path = .{ .segments = segments } };
    }

    /// Whether `name` is a parameter of the callable being lowered, or of any
    /// `fn`/`impl`/`trait` scope it inherits from, bounded by canonical `Hash`.
    ///
    /// Read from the declaration, so an inherited blanket-impl parameter
    /// (`impl<T: Hash> Hash for T`) answers the same as a locally declared one.
    fn isHashDescriptorParameter(self: *Lowerer, name: []const u8) bool {
        if (name.len == 0) return false;
        const owner = self.current_callable_id orelse return false;
        const segments = [_]ir.types.PathSegment{.{ .name = name, .id = null }};
        return ir.bodies.genericBound(
            &self.ir.graph,
            &self.ir.bodies,
            owner,
            hashParameterType(&segments),
            &canonical_hash_bound,
        ) != null;
    }

    /// As above, anchored at `def`: a parameter name only means a bound inside
    /// the declaration that introduces it, so a call site's own `Hash` bound
    /// says nothing about what the callee asked for.
    fn isHashDescriptorParameterFor(
        self: *Lowerer,
        name: []const u8,
        def: ir.spine.EntityId,
    ) bool {
        if (name.len == 0) return false;
        const segments = [_]ir.types.PathSegment{.{ .name = name, .id = null }};
        return ir.bodies.genericBound(
            &self.ir.graph,
            &self.ir.bodies,
            def,
            hashParameterType(&segments),
            &canonical_hash_bound,
        ) != null;
    }

    /// Whether a `&T` borrow is spelled through `RustHashRef`. Hash bound
    /// only: `&I` for `I: Copy` stays `*const I`.
    fn hashReferenceNeedsDescriptor(self: *Lowerer, pointee: ir.types.Type) bool {
        const name = hashParameterName(pointee) orelse return false;
        return self.isHashDescriptorParameter(name);
    }

    /// The body of `def` when it declares a type alias, else null.
    fn hashAliasDeclaration(self: *Lowerer, def: ir.spine.EntityId) ?ir.bodies.TypeAliasBody {
        if (def >= self.ir.bodies.bodies.len) return null;
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (entity.kind != .type_alias) return null;
        return switch (self.ir.bodies.bodies[def]) {
            .type_alias => |body| body,
            else => null,
        };
    }

    /// The type a chain of NON-GENERIC aliases ends on, or null.
    ///
    /// `type Bytes = [u8]` declares no new type and no new impl, so its `Hash`
    /// is its target's. Answering `nominal` for the alias instead would send
    /// the runtime after a `hash` method no impl provides.
    ///
    /// Null whenever no alias was followed, which is what keeps the caller from
    /// recursing on the type it was handed. Bounded by the IR's own
    /// `traversal_depth_max`, and null on overflow, so two aliases naming each
    /// other stop instead of spinning.
    fn hashAliasTarget(self: *Lowerer, ty: ir.types.Type) ?ir.types.Type {
        var current = ty;
        var followed = false;
        for (0..ir.types.traversal_depth_max) |_| {
            const path = switch (current) {
                .path => |value| value,
                else => return if (followed) current else null,
            };
            if (path.segments.len != 1) return if (followed) current else null;
            const id = path.segments[0].id orelse return if (followed) current else null;
            const alias = self.hashAliasDeclaration(id) orelse {
                return if (followed) current else null;
            };
            if (alias.generic_params.len != 0) return if (followed) current else null;
            current = alias.target;
            followed = true;
        }
        return null;
    }

    /// The layout a descriptor declares, in the three forms `RustHashLayout`
    /// actually has.
    const HashLayout = union(enum) {
        /// Exact Rust identity, including pointer-sized integer distinctions.
        scalar: ir.types.Prim,
        /// A `void`-payload tag: `.str`, `.nominal`.
        unit: []const u8,
        /// A tag carrying one child descriptor.
        child: struct { tag: []const u8, ty: ir.types.Type },
        /// `.tuple`: one descriptor per field, in Rust tuple order.
        tuple: []const ir.types.Type,
    };

    /// One classification: the type a non-`Hash` callee receives, and the
    /// source shape a recursive hash walks.
    const HashShape = struct {
        /// `RustHashType`'s first generic argument. A forwarded `Hash`-bound
        /// parameter is settled before this struct is built.
        runtime_type: ast.Type,
        layout: HashLayout,
    };

    /// The classification one descriptor is built from.
    ///
    /// One function, so the layout a hash walks and the type a non-`Hash`
    /// callee takes cannot come from two readings of the same IR type. Every
    /// decision reads the IR tag, never the Zig type it renders to: `str` and
    /// `[u8]` render the same `[]const u8` and get different layouts.
    fn hashShapeFor(self: *Lowerer, ty: ir.types.Type) anyerror!HashShape {
        return switch (ty) {
            .prim => |primitive| .{
                .runtime_type = try self.lowerType(ty),
                .layout = switch (primitive) {
                    .u8, .u16, .u32, .u64, .u128, .usize, .i8, .i16, .i32, .i64, .i128, .isize, .bool, .char, .unit => .{ .scalar = primitive },
                    .f32, .f64, .never => .{ .unit = "nominal" },
                },
            },
            // `str` is UNSIZED, so it is its own layout, not a borrow of one.
            .external_nominal => if (ir.types.isStr(ty)) .{
                .runtime_type = try self.lowerType(ir.types.str_type),
                .layout = .{ .unit = "str" },
            } else try self.hashNominalShape(ty),
            .slice => |slice| .{
                .runtime_type = try self.lowerType(ty),
                .layout = .{ .child = .{ .tag = "slice", .ty = slice.elem } },
            },
            // The descriptor must describe the actual emitted payload. A
            // generic array's existing slice ABI still keeps its Rust array
            // layout, so the walk borrows that view rather than inventing [N]T.
            .array => |array| .{
                .runtime_type = try self.lowerType(ty),
                .layout = .{ .child = .{ .tag = "array", .ty = array.elem } },
            },
            .tuple => |elements| .{
                .runtime_type = try self.lowerType(ty),
                .layout = .{ .tuple = elements },
            },
            // `&str` and `&[T]` are SIZED borrows OF an unsized value, so their
            // layout is `.reference`, not `.str`/`.slice`.
            .reference => |reference| .{
                .runtime_type = try self.hashReferenceZigType(reference.*),
                .layout = .{ .child = .{ .tag = "reference", .ty = reference.pointee } },
            },
            .raw_ptr => |raw_ptr| .{
                .runtime_type = try self.lowerType(ty),
                .layout = .{ .child = .{ .tag = "raw_pointer", .ty = raw_ptr.pointee } },
            },
            .@"opaque" => |opaque_type| try self.hashShapeFor(
                (opaque_type.concrete orelse return error.UnresolvedOpaqueType).*,
            ),
            .path => blk: {
                if (self.hashAliasTarget(ty)) |resolved| {
                    break :blk try self.hashShapeFor(resolved);
                }
                break :blk try self.hashNominalShape(ty);
            },
            // A generic alias is its target with the arguments applied, which
            // is substitution rather than classification. `substType` is the
            // pipeline's shared substitution and allocates only when a
            // parameter is actually replaced.
            .generic_inst => |inst| blk: {
                const alias = self.hashAliasDeclaration(inst.decl) orelse
                    break :blk try self.hashNominalShape(ty);
                if (alias.generic_params.len != inst.args.params.len) {
                    break :blk try self.hashNominalShape(ty);
                }
                // RETAINED, not released: the shape holds this IR type and the
                // descriptor that walks it is built after this returns. The
                // target and the argument storage are borrowed and outlive it,
                // so this copy is the only allocation involved.
                const substituted = ir.types.substType(
                    self.alloc,
                    alias.target,
                    alias.generic_params,
                    inst.args.params,
                ) catch return error.OutOfMemory;
                break :blk try self.hashShapeFor(substituted);
            },
            // `Box<T>` OWNS its payload and the source gives it its own hashing
            // path; following the payload would hash it exactly as a bare `T`.
            // So a box, like every other shapeless value, stays whole.
            else => try self.hashNominalShape(ty),
        };
    }

    /// The shape of a value the source gave no interior structure to walk.
    /// Guessing a layout would hash bytes the source never wrote.
    fn hashNominalShape(self: *Lowerer, ty: ir.types.Type) anyerror!HashShape {
        return .{ .runtime_type = try self.lowerType(ty), .layout = .{ .unit = "nominal" } };
    }

    /// The `RustHashLayout` argument, as a typed `ast.StructInit`.
    ///
    /// `.{ .slice = D }` is the only spelling the union accepts; `.slice(D)`
    /// is a function call and names no field. Built from typed nodes so the
    /// validator and the generated-name walker both see it.
    fn hashLayoutExpr(self: *Lowerer, layout: HashLayout) anyerror!ast.Expr {
        const fields = try self.alloc.alloc(ast.StructInitField, 1);
        fields[0] = switch (layout) {
            .scalar => |primitive| .{
                .name = try self.alloc.dupe(u8, "scalar"),
                .expr = try self.hashScalarKindExpr(primitive),
            },
            .unit => |tag| .{
                .name = try self.alloc.dupe(u8, tag),
                .expr = .{ .unit = {} },
            },
            .child => |child| .{
                .name = try self.alloc.dupe(u8, child.tag),
                .expr = .{ .type_value = try self.hashDescriptorType(child.ty) },
            },
            .tuple => |elements| .{
                .name = try self.alloc.dupe(u8, "tuple"),
                .expr = try self.hashDescriptorListExpr(elements),
            },
        };
        return .{ .struct_init = .{
            .type_name = .{ .named = try self.alloc.dupe(u8, hash_layout_runtime) },
            .fields = fields,
        } };
    }

    fn hashScalarKindExpr(self: *Lowerer, primitive: ir.types.Prim) !ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .type_value = .{ .named = hash_layout_runtime } };
        args[1] = .{ .lit = .{ .str = "scalar" } };
        return .{ .field_access = .{
            .target = try self.allocExpr(.{ .builtin = .{ .name = "FieldType", .args = args } }),
            .field_name = @tagName(primitive),
        } };
    }

    fn hashScalarMatchesExpr(self: *Lowerer, ty: ir.types.Type, primitive: ir.types.Prim) anyerror!ast.Expr {
        const kind_name = try self.iteratorTemporaryName("__r2z_hash_kind");
        const arms = try self.alloc.alloc(ast.MatchArm, 2);
        arms[0] = .{
            .patterns = &.{.{ .enum_literal = "scalar" }},
            .capture = .{ .name = kind_name },
            .body = .{ .bin_op = .{
                .op = .equal,
                .lhs = try self.allocExpr(.{ .ident = kind_name }),
                .rhs = try self.allocExpr(try self.hashScalarKindExpr(primitive)),
            } },
        };
        arms[1] = .{
            .patterns = &.{.wildcard},
            .body = .{ .lit = .{ .bool_lit = false } },
        };
        return .{ .match_expr = .{
            .target = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(try self.hashDescriptorForType(ty)),
                .field_name = "Layout",
            } }),
            .arms = arms,
        } };
    }

    /// `&.{ D, D, ... }` — the comptime slice a `.tuple` layout carries.
    ///
    /// An `addr_of` over an UNTYPED array literal: descriptors of different
    /// shapes share no element type but `type`, which the field declares.
    fn hashDescriptorListExpr(self: *Lowerer, elements: []const ir.types.Type) anyerror!ast.Expr {
        const values = try self.alloc.alloc(ast.Expr, elements.len);
        for (elements, 0..) |element, index| {
            values[index] = .{ .type_value = try self.hashDescriptorType(element) };
        }
        const literal = try self.allocExpr(.{ .array_init = .{ .elements = values } });
        return .{ .unary_op = .{ .op = .addr_of, .operand = literal } };
    }

    /// `r2z.RustHashType(RuntimeType, layout)` for one IR Rust type.
    ///
    /// The one entry every generic-argument site calls for a Hash-bound slot.
    /// The aggregate hash lowering calls it too and MUST NOT define or edit it.
    fn hashDescriptorType(self: *Lowerer, ty: ir.types.Type) anyerror!ast.Type {
        // A `Hash`-bound parameter of this scope IS a descriptor already:
        // forwarding it forwards the parameter. Rebuilding one would ask this
        // scope to name a type it cannot see, and rewrapping the payload as
        // `.nominal` would erase the shape the parameter stands for. A bare
        // identifier is an ordinary named type here, not source text.
        if (hashParameterName(ty)) |name| {
            if (self.isHashDescriptorParameter(name)) {
                return .{ .named = try self.alloc.dupe(u8, name) };
            }
        }
        const shape = try self.hashShapeFor(ty);
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = shape.runtime_type;
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = try self.hashLayoutExpr(shape.layout);
        try self.markRuntimeImport();
        return .{ .expr = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{
                .ident = try self.alloc.dupe(u8, hash_descriptor_runtime),
            }),
            .generic_args = generic_args,
            .args = args,
        } }) };
    }

    /// The same descriptor as an `ast.Expr`, for positions that hold an
    /// expression rather than a type. Both entries build through
    /// `hashShapeFor`, so there is one descriptor and not two spellings.
    fn hashDescriptorForType(self: *Lowerer, ty: ir.types.Type) anyerror!ast.Expr {
        if (hashParameterName(ty)) |name| {
            if (self.isHashDescriptorParameter(name)) {
                return .{ .ident = try self.alloc.dupe(u8, name) };
            }
        }
        return (try self.hashDescriptorType(ty)).expr.*;
    }

    /// The Zig type a `&T` borrow has: `lowerType`'s spelling for every
    /// pointee it can already spell, `RustHashRef` for a Hash-bound type
    /// parameter alone.
    ///
    /// `Descriptor: type` is the one generic argument; `mutable: bool` is a
    /// comptime VALUE parameter and so an ordinary argument.
    fn hashReferenceZigType(self: *Lowerer, reference: ir.types.Ref) anyerror!ast.Type {
        if (!self.hashReferenceNeedsDescriptor(reference.pointee)) {
            return self.lowerType(.{ .reference = &reference });
        }
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.hashDescriptorType(reference.pointee);
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = .{ .lit = .{ .bool_lit = reference.mut } };
        try self.markRuntimeImport();
        return .{ .expr = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{
                .ident = try self.alloc.dupe(u8, hash_reference_runtime),
            }),
            .generic_args = generic_args,
            .args = args,
        } }) };
    }

    /// `r2z.rustHashRefIsFat(<descriptor>)` — the comptime question a `&T`
    /// borrow cannot answer by itself. Asked of the descriptor, so the answer
    /// is read off the same layout the recursive hash walks.
    fn hashReferenceIsFatExpr(self: *Lowerer, pointee: ir.types.Type) anyerror!*const ast.Expr {
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.hashDescriptorType(pointee);
        try self.markRuntimeImport();
        return self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{
                .ident = try self.alloc.dupe(u8, hash_reference_is_fat_runtime),
            }),
            .generic_args = generic_args,
            .args = &.{},
        } });
    }

    fn hashPayloadPointee(self: *Lowerer, pointee: ir.types.Type) ir.types.Type {
        return self.hashAliasTarget(pointee) orelse pointee;
    }

    fn hashResolvedFatElement(pointee: ir.types.Type) ?ir.types.Type {
        if (ir.types.isStr(pointee)) return .{ .prim = .u8 };
        return switch (pointee) {
            .slice => |slice| slice.elem,
            else => null,
        };
    }

    fn hashFatPointeeElement(self: *Lowerer, pointee: ir.types.Type) ?ir.types.Type {
        return hashResolvedFatElement(self.hashPayloadPointee(pointee));
    }

    fn hashRawPointerPayloadType(self: *Lowerer, pointee: ir.types.Type, mutable: bool) anyerror!ast.Type {
        const is_fat = try self.hashReferenceIsFatExpr(pointee);
        return .{ .expr = try self.allocExpr(try self.hashRawPointerPayloadExpr(pointee, mutable, is_fat)) };
    }

    fn hashRawPointerPayloadExpr(
        self: *Lowerer,
        pointee: ir.types.Type,
        mutable: bool,
        is_fat: *const ast.Expr,
    ) anyerror!ast.Expr {
        const fat = try self.hashReferenceZigType(.{ .mut = mutable, .pointee = pointee });
        const thin: ast.Type = .{ .ptr = .{
            .elem = try self.allocType(try self.lowerType(pointee)),
            .is_const = !mutable,
            .is_allowzero = true,
            .size = .many,
            .alignment = 1,
        } };
        return .{ .if_expr = .{
            .cond = is_fat,
            .then_body = try self.allocExpr(.{ .type_value = fat }),
            .else_body = try self.allocExpr(.{ .type_value = thin }),
        } };
    }

    fn referenceToRawPointerCast(
        self: *Lowerer,
        source: ir.types.Ref,
        target_pointer: ir.types.RawPtr,
        operand: ast.Expr,
    ) anyerror!ast.Expr {
        if (target_pointer.mut and !source.mut) return error.UnsupportedExpression;
        const pointee = self.hashPayloadPointee(source.pointee);
        if (self.hashReferenceNeedsDescriptor(pointee)) {
            if (!sameIrType(pointee, self.hashPayloadPointee(target_pointer.pointee)))
                return error.UnsupportedExpression;
            return self.hashReferenceToRawPointerCast(pointee, target_pointer.mut, operand);
        }
        const array = switch (pointee) {
            .array => |value| value,
            else => return error.UnsupportedExpression,
        };
        const target_pointee = self.hashPayloadPointee(target_pointer.pointee);
        const canonical_array = try self.lowerType(pointee);
        switch (canonical_array) {
            .array, .array_expr => {},
            else => return error.UnsupportedExpression,
        }
        // `&mut self.bytes as *mut [MaybeUninit<u8>; N]` is the shape
        // `itoa::Buffer::format` writes, and its destination names the VERY
        // array the borrow names. A pointer to that array is not a pointer to
        // the element the array starts at, so the destination's own shape —
        // not the element the two happen to share — decides what this emits.
        //
        // A destination that is an array keeps the array on BOTH sides: the
        // two pointees have to be the same array, length included. The
        // comparison is structural because `sameIrType` reads primitive tags
        // only and so answers "no" to every array and every nominal element.
        // Agreeing elements alone would admit a destination of any length and
        // then re-label a `[N]T` as the `[M]T` the caller never named, which
        // is a different program; a destination whose length differs is
        // refused here instead.
        if (target_pointee == .array) {
            if (!ir.types.deepEqual(target_pointee, pointee)) return error.UnsupportedExpression;
            const ptr_cast_args = try self.alloc.alloc(ast.Expr, 1);
            ptr_cast_args[0] = operand;
            // The two sides differ in mutability alone, so they share one
            // lowering of the array the structural check just made the same
            // type on both. A pointer cast records BOTH sides as the pointer's
            // own ABI form, and `lowerType` spells a raw pointer
            // `[*]allowzero align(1) T`: the target the destination array under
            // its own mutability, the source the very array the borrow named.
            // `ast` admits only a many-item source for a many-item target, and
            // `@ptrCast` may widen a single pointer to a many one exactly when
            // the pointee is an array. No `@constCast` belongs here: the gate
            // above already refuses a shared borrow becoming a mutable pointer,
            // so this cast can only preserve the qualifier.
            const array_pointee = try self.allocType(canonical_array);
            return .{ .cast = .{
                .target = .{ .ptr = .{
                    .elem = array_pointee,
                    .is_const = !target_pointer.mut,
                    .is_allowzero = true,
                    .size = .many,
                    .alignment = 1,
                } },
                .operand = try self.allocExpr(.{ .builtin = .{
                    .name = "ptrCast",
                    .args = ptr_cast_args,
                } }),
                .source = .{ .ptr = .{
                    .elem = array_pointee,
                    .is_const = !source.mut,
                    .is_allowzero = true,
                    .size = .many,
                    .alignment = 1,
                } },
            } };
        }
        // A destination that is not an array names the element the source
        // array starts at, and the `.ptr` of a widened slice is that pointer.
        // The length the slice is built from is the SOURCE array's own — the
        // destination's spelling of it is a `const` expression the frontend
        // already resolved when it admitted the cast — and what has to agree
        // is the ELEMENT, compared structurally for the same reason as above.
        const element = self.hashPayloadPointee(array.elem);
        if (!ir.types.deepEqual(target_pointee, element)) return error.UnsupportedExpression;
        const widened = try self.allocExpr(.{ .cast = .{
            .target = .{ .slice = .{
                .elem = try self.allocType(try self.lowerType(array.elem)),
                .is_const = !target_pointer.mut,
            } },
            .source = .{ .ptr = .{
                .elem = try self.allocType(canonical_array),
                .is_const = !source.mut,
                .size = .one,
            } },
            .operand = try self.allocExpr(operand),
        } });
        return .{ .field_access = .{ .target = widened, .field_name = try self.alloc.dupe(u8, "ptr") } };
    }

    fn hashReferenceToRawPointerCast(
        self: *Lowerer,
        pointee: ir.types.Type,
        mutable: bool,
        operand: ast.Expr,
    ) anyerror!ast.Expr {
        const is_fat = try self.hashReferenceIsFatExpr(pointee);
        const destination = try self.hashRawPointerPayloadExpr(pointee, mutable, is_fat);
        const refusal_args = try self.alloc.alloc(ast.Expr, 1);
        refusal_args[0] = .{ .lit = .{ .str = try self.alloc.dupe(
            u8,
            "A thin Hash borrow cannot become a many-item raw pointer in this representation.",
        ) } };
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .type_value = .{ .expr = try self.allocExpr(destination) } };
        args[1] = .{ .if_expr = .{
            .cond = is_fat,
            .then_body = try self.allocExpr(operand),
            .else_body = try self.allocExpr(.{ .builtin = .{
                .name = try self.alloc.dupe(u8, "compileError"),
                .args = refusal_args,
            } }),
        } };
        return .{ .builtin = .{ .name = try self.alloc.dupe(u8, "as"), .args = args } };
    }

    // -------------------------------------------------------------------------
    // Expression Lowering
    // -------------------------------------------------------------------------

    /// True when the declared type of `expr_id` is (or reference-wraps) an array.
    fn receiverIsArray(self: *const Lowerer, expr_id: ir.exprs.NodeId) bool {
        if (expr_id >= self.ir.bodies.exprs.len) return false;
        const e = self.ir.bodies.exprs[expr_id];
        if (e.ty) |tid| {
            if (tid < self.ir.bodies.types.len) {
                var t = self.ir.bodies.types[tid];
                while (true) {
                    switch (t) {
                        .array => return true,
                        .reference => |r| t = r.pointee,
                        else => return false,
                    }
                }
            }
        }
        return false;
    }

    /// True when the declared type of `expr_id` is (or reference-wraps) a
    /// slice.
    fn receiverIsSlice(self: *const Lowerer, expr_id: ir.exprs.NodeId) bool {
        if (expr_id >= self.ir.bodies.exprs.len) return false;
        const e = self.ir.bodies.exprs[expr_id];
        if (e.ty) |tid| {
            if (tid < self.ir.bodies.types.len) {
                var t = self.ir.bodies.types[tid];
                while (true) {
                    switch (t) {
                        .slice => return true,
                        .reference => |r| t = r.pointee,
                        else => return false,
                    }
                }
            }
        }
        return false;
    }

    /// The borrowed view an `AsRef`-shaped method call names: an array receiver
    /// is cited as `receiver[0..]`, and a receiver whose pointee is a type
    /// parameter is read through, because `AsRef` borrows the value the
    /// receiver points at rather than the pointer the receiver already is.
    /// Everything else — a slice, an array behind a reference, a concrete
    /// reference — is already the shape the caller wants.
    fn lowerAsRef(self: *Lowerer, receiver_node: ir.exprs.NodeId, receiver: *const ast.Expr) anyerror!*const ast.Expr {
        const borrowed = if (try self.borrowReadsThroughGenericPointee(receiver_node))
            try self.allocExpr(.{ .unary_op = .{ .op = .deref, .operand = receiver } })
        else
            receiver;
        // `self.as_ref()` inside a blanket impl is emitted once and
        // instantiated for every type that reaches it, so the form written
        // here has to be the one that works for a slice and for the array it
        // may also be. Both take a view of the borrowed place; the array is
        // the one that needs it, since a `[N]u8` value does not coerce to
        // `[]const u8` on its own.
        if (self.receiverIsArray(receiver_node) or
            try self.borrowReadsThroughGenericPointee(receiver_node))
        {
            const zero = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
            const open = try self.allocExpr(ast.Expr{ .range = .{ .start = zero, .end = null } });
            var args = try self.alloc.alloc(ast.Expr, 2);
            args[0] = borrowed.*;
            args[1] = open.*;
            const result = try self.allocExpr(ast.Expr{ .builtin = .{ .name = "index", .args = args } });
            return result;
        }
        return borrowed;
    }

    /// The `&[T]` a call that only READS a sequence is handed.
    ///
    /// A borrow the source wrote is read through unchanged — except when its
    /// pointee is a runtime CONTAINER whose storage is not the value itself.
    /// `&Vec<u8>` is Rust's way of naming `&[u8]`, and a lowered `Vec` is an
    /// `ArrayListUnmanaged` whose elements live in `items`, so the borrow names
    /// that slice. Nothing is copied and no owner changes hands: the argument is
    /// still the caller's own storage, reached the way Rust reaches it.
    fn lowerBorrowedSequence(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        lowered: *const ast.Expr,
    ) anyerror!ast.Expr {
        if (!needsContainerStorageProjection(try self.exprType(node))) return lowered.*;
        if (lowered.* == .unary_op and lowered.unary_op.op == .addr_of) {
            return (try self.allocExpr(.{ .field_access = .{
                .target = lowered.unary_op.operand,
                .field_name = "items",
            } })).*;
        }
        return lowered.*;
    }

    /// Whether a borrow's operand is a dereference of a runtime CONTAINER, so
    /// the borrow names the sequence that container derefs to.
    ///
    /// `&*bytes` over a `Vec<u8>` is `&[u8]`, and a lowered `Vec` keeps its
    /// elements in `items`, so the borrow is that slice. Spelling it as the
    /// address of the descriptor would hand the callee a pointer to a list
    /// where it asked for bytes — and would then `@ptrCast` a thin pointer into
    /// a fat one, which Zig refuses.
    fn borrowOfContainerStorage(self: *Lowerer, operand: ir.exprs.NodeId) anyerror!bool {
        if (operand >= self.ir.bodies.exprs.len) return false;
        const deref = switch (self.ir.bodies.exprs[operand].kind) {
            .unary => |value| value,
            else => return false,
        };
        if (deref.op != .deref) return false;
        return needsContainerStorageProjection(try self.exprType(deref.operand));
    }

    /// The type a BORROWED receiver points at, or null when the receiver is
    /// not reached through a pointer.
    ///
    /// The node type alone cannot answer it. A `.path` node carries the type
    /// inference settled on, which for a `&mut slice::Iter` parameter is the
    /// POINTEED cursor — that is what `.clone()` and `.next()` are called on —
    /// while the Zig binding is the pointer the source's borrow lowered to, and
    /// that pointer is what a member call auto-derefs. Reading the DECLARED
    /// type of the entity the path names recovers the borrow the node type left
    /// behind; a receiver that already holds the value has neither and stays
    /// null.
    fn borrowedReceiverPointee(self: *Lowerer, receiver_node: ir.exprs.NodeId) anyerror!?ir.types.Type {
        if (try self.exprType(receiver_node)) |known| {
            switch (known) {
                .reference => |reference| return reference.pointee,
                .raw_ptr => |pointer| return pointer.pointee,
                else => {},
            }
        }
        if (receiver_node >= self.ir.bodies.exprs.len) return null;
        const path = switch (self.ir.bodies.exprs[receiver_node].kind) {
            .path => |value| value,
            else => return null,
        };
        const declared = self.declaredBindingType(path.def) orelse return null;
        return switch (declared) {
            .reference => |reference| reference.pointee,
            .raw_ptr => |pointer| pointer.pointee,
            else => null,
        };
    }

    fn validateMethodTopology(
        self: *const Lowerer,
        method: ir.spine.Entity,
    ) !void {
        if (method.kind == .method_ref) return;
        if (method.kind != .fn_) return error.GenericDefinitionMismatch;

        const parent_id = method.parent orelse return error.GenericDefinitionMismatch;
        const parent = self.ir.graph.symbol_table.get(parent_id) orelse {
            return error.GenericDefinitionMismatch;
        };
        switch (parent.kind) {
            .trait_, .struct_, .enum_, .union_ => {},
            .impl_ => {
                const target_id = parent.parent orelse return error.GenericDefinitionMismatch;
                const target = self.ir.graph.symbol_table.get(target_id) orelse {
                    return error.GenericDefinitionMismatch;
                };
                switch (target.kind) {
                    .struct_, .enum_, .union_ => {},
                    // A blanket `impl<T: Bound> Trait for T` has no concrete
                    // self type: the frontend gives it the enclosing module
                    // as its target, because the module is the scope the
                    // impl's items actually belong to. Its methods still hoist
                    // onto that module (see `collectHoistedMethods`), so the
                    // emitted shape is a free function — the same shape a
                    // method on a named type produces. Only the *self* type is
                    // a type parameter rather than a declaration, and that is
                    // the call site's business, not the topology's.
                    //
                    // This is deliberately narrow: the enclosing module must
                    // actually BE the impl's parent, and a module that is not
                    // a crate or root scope is still refused below, because a
                    // stray module parent means the impl was never attached
                    // to anything real.
                    .module => {
                        const module = self.moduleForEntity(target_id) orelse {
                            return error.GenericDefinitionMismatch;
                        };
                        if (!module.is_crate) return error.GenericDefinitionMismatch;
                    },
                    else => return error.GenericDefinitionMismatch,
                }
            },
            else => return error.GenericDefinitionMismatch,
        }
    }
    fn isChunksExactType(ty: ir.types.Type) bool {
        return switch (ty) {
            .external_nominal => |external| external.path.len == 3 and
                (std.mem.eql(u8, external.path[0], "core") or
                    std.mem.eql(u8, external.path[0], "std")) and
                std.mem.eql(u8, external.path[1], "slice") and
                std.mem.eql(u8, external.path[2], "ChunksExact"),
            else => false,
        };
    }

    /// Strip the indirections that do not change which Rust carrier a receiver
    /// names: a borrow, a box, or an `impl Trait` with a known concrete type.
    fn peelReceiverType(ty: ir.types.Type) ir.types.Type {
        var current = ty;
        for (0..128) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .boxed => |boxed| current = boxed.*,
                .@"opaque" => |opaque_type| current = (opaque_type.concrete orelse return current).*,
                else => return current,
            }
        }
        return current;
    }

    /// The `core::iter` adapters the runtime mirrors, each of which is a
    /// single-argument generic over its source. `Zip` is the two-argument
    /// exception and is handled alongside the others.
    fn isRuntimeIteratorAdapterName(name: []const u8) bool {
        return std.mem.eql(u8, name, "StepBy") or
            std.mem.eql(u8, name, "Skip") or
            std.mem.eql(u8, name, "Enumerate") or
            std.mem.eql(u8, name, "Rev");
    }

    /// True when `ty` is one of the Rust iterator carriers the runtime models
    /// as an `r2z` iterator struct: a half-open `core::ops::Range` and the
    /// `core::iter` adapters. Each of them is driven by `next` rather than by
    /// a Zig `for`, and each adapter is built by a free function that takes
    /// the source by value, so a method on one of them is that constructor.
    fn isRuntimeIteratorCarrier(ty: ir.types.Type) bool {
        return switch (ty) {
            .external_nominal => |external| blk: {
                if (external.path.len != 3) break :blk false;
                if (!std.mem.eql(u8, external.path[0], "core") and
                    !std.mem.eql(u8, external.path[0], "std")) break :blk false;
                const is_range = std.mem.eql(u8, external.path[1], "ops") and
                    std.mem.eql(u8, external.path[2], "Range");
                const is_zip = std.mem.eql(u8, external.path[1], "iter") and
                    std.mem.eql(u8, external.path[2], "Zip");
                const is_adapter = std.mem.eql(u8, external.path[1], "iter") and
                    isRuntimeIteratorAdapterName(external.path[2]);
                if (!is_range and !is_zip and !is_adapter) break :blk false;
                const arity: usize = if (is_zip) 2 else 1;
                break :blk external.args.len == arity;
            },
            else => false,
        };
    }

    /// True when `ty` is a Rust iterator carrier the backend can WALK, which
    /// is the whole of what `Iterator::any` needs: it lowers to an `r2z` (or
    /// user) struct that publishes `next`, and every element reaches the
    /// predicate as that `next` hands it over.
    ///
    /// This is `isRuntimeIteratorCarrier`'s set plus the slice-owned
    /// iterators, and it is asked of the canonical receiver type for the same
    /// reason the `step_by`/`skip`/`zip`/`collect` arms are: a crate's own
    /// `any` is answered by its own declaration, and a `method_ref` on any
    /// other receiver is not this operation.
    ///
    /// `Chunks`/`ChunksExact` stay out. Their Rust `Item` is a BORROW of a
    /// sub-slice while the runtime's `next` hands back the slice value itself,
    /// so the `|&chunk|` pattern the source writes would dereference a value
    /// rather than a pointer. `Iter`/`IterMut` are the pair whose `next`
    /// yields `*const T`/`*T`, matching the `&T`/`&mut T` those two promise.
    fn isNextDrivenIteratorCarrier(ty: ir.types.Type) bool {
        if (isRuntimeIteratorCarrier(ty)) return true;
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        if (external.path.len != 3 or external.args.len != 1) return false;
        if (!std.mem.eql(u8, external.path[0], "core") and
            !std.mem.eql(u8, external.path[0], "std")) return false;
        if (!std.mem.eql(u8, external.path[1], "slice")) return false;
        return std.mem.eql(u8, external.path[2], "Iter") or
            std.mem.eql(u8, external.path[2], "IterMut");
    }

    /// True when the runtime's Zig struct for `ty` publishes the by-value
    /// `clone` a Rust `Clone` on it promises.
    ///
    /// `SliceIter`, `Range` and every `core::iter` adapter copy their cursor
    /// by reading `*self`, which is exactly what `iter.clone()` on `&mut Iter`
    /// asks for: a second cursor over the same bytes, moved back into the
    /// original with `*iter = cloned`. `IterMut` is not one of them — the
    /// runtime's mutable cursor is not `Clone` — and neither is a local
    /// struct, whose `Clone` is a copy the backend has no member to call.
    fn runtimeCarrierCopiesByClone(ty: ir.types.Type) bool {
        if (isRuntimeIteratorCarrier(ty)) return true;
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        if (external.path.len != 3 or external.args.len != 1) return false;
        if (!std.mem.eql(u8, external.path[0], "core") and
            !std.mem.eql(u8, external.path[0], "std")) return false;
        if (!std.mem.eql(u8, external.path[1], "slice")) return false;
        return std.mem.eql(u8, external.path[2], "Iter");
    }

    /// True when the receiver is a Rust CURSOR — a slice iterator — whose
    /// `as_slice` is the remaining sequence rather than the cursor itself.
    ///
    /// `slice::Iter` is a (pointer, front, back) triple and `as_slice` is what
    /// makes it readable as the rest of the input. The runtime publishes that
    /// method, so the call has to survive the borrow shortcut a plain `&T`
    /// receiver would take; dropping it would hand back the cursor where the
    /// source asked for the bytes still in it.
    fn isCursorCarrierWithAsSlice(ty: ir.types.Type) bool {
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return false,
        };
        if (external.path.len != 3 or external.args.len != 1) return false;
        if (!std.mem.eql(u8, external.path[0], "core") and
            !std.mem.eql(u8, external.path[0], "std")) return false;
        if (!std.mem.eql(u8, external.path[1], "slice")) return false;
        return std.mem.eql(u8, external.path[2], "Iter") or
            std.mem.eql(u8, external.path[2], "IterMut");
    }

    /// True when `ty` names a local struct that carries a `next` method, which
    /// is how a user-defined Rust `Iterator` is consumed in Zig: the value is
    /// iterated with `while (iter.next())`, not with a Zig `for`.
    fn isUserIteratorType(self: *const Lowerer, ty: ir.types.Type) bool {
        var maybe_path: ?ir.types.Path = null;
        switch (ty) {
            .path => |value| maybe_path = value,
            .@"opaque" => |opaque_type| {
                if (opaque_type.concrete) |concrete| {
                    switch (concrete.*) {
                        .path => |value| maybe_path = value,
                        else => {},
                    }
                }
            },
            else => {},
        }
        const path = maybe_path orelse return false;
        const target = lastPathSegment(path.segments) orelse return false;
        const struct_id = target.id orelse return false;
        const entity = self.ir.graph.symbol_table.get(struct_id) orelse return false;
        if (entity.kind != .struct_) return false;
        if (struct_id >= self.ir.bodies.bodies.len) return false;
        switch (self.ir.bodies.bodies[struct_id]) {
            .struct_ => |structure| {
                for (structure.methods) |method| {
                    if (std.mem.eql(u8, method.name, "next")) return true;
                }
            },
            else => {},
        }
        // A method hoisted from a separate `impl` block is not listed on the
        // StructBody, so consult the collected declarations as well.
        if (self.hoisted_by_id.get(struct_id)) |list| {
            for (list.items) |decl| {
                if (decl == .fn_decl and std.mem.eql(u8, decl.fn_decl.name, "next")) return true;
            }
        }
        return false;
    }
    const RecognizedStdMethod = enum {
        io_read_exact,
        io_write_all,
        /// `BufRead::fill_buf`: the runtime buffer's unread span, which stays
        /// valid only until the next `consume` on that same reader.
        io_fill_buf,
        /// `BufRead::consume`: advance past `count` bytes of what `fill_buf`
        /// last handed out.
        io_consume,
        option_is_some,
        option_is_none,
        option_unwrap,
        option_unwrap_or,
        option_map,
        option_and_then,
        option_as_ref,
        option_take,

        result_is_ok,
        result_is_err,
        result_unwrap,
        result_unwrap_err,
        result_unwrap_or,
        result_expect,
        result_expect_err,
        result_ok,
        result_err,
        result_map,
        result_map_err,
        result_as_ref,
        result_as_mut,
        /// `Result::unwrap` on a value already lowered to a Zig error union.
        error_union_unwrap,
        /// `Result::expect` on a value already lowered to a Zig error union,
        /// which has no runtime `Result` to carry a method.
        error_union_expect,
        /// `Result::expect_err` on a value already lowered to a Zig error
        /// union, whose failure survives as the error tag it became.
        error_union_expect_err,
        memory_ptr_add,
        memory_ptr_sub,
        memory_ptr_offset,
        memory_ptr_read_unaligned,
        memory_slice_as_ptr,
        memory_slice_as_mut_ptr,
        memory_slice_get_unchecked,
        memory_slice_get_unchecked_mut,

        slice_len,
        slice_is_empty,
        slice_as_bytes,
        slice_as_slice,
        slice_iter,
        slice_chunks,
        slice_split_at,
        slice_split_first,
        slice_first,
        slice_chunks_exact,
        slice_copy_from_slice,
        chunks_exact_remainder,

        iterator_step_by,
        iterator_skip,
        iterator_zip,
        iterator_collect,
        /// `Iterator::any`: does the predicate hold for at least one element,
        /// with the receiver's own cursor consumed up to and including the
        /// element that answered `true`.
        iterator_any,
        num_wrapping_add,
        num_wrapping_sub,
        num_wrapping_mul,
        num_saturating_add,
        num_saturating_sub,
        num_saturating_mul,
        num_count_ones,
        num_leading_zeros,
        num_trailing_zeros,
        num_rotate_left,
        num_rotate_right,
        num_to_le,
        num_to_be,
        num_swap_bytes,
        num_checked_add,
        num_checked_sub,
        num_checked_mul,
        byte_is_ascii,
        format_write_str,
        to_string,

        /// `ToOwned::to_owned` on a borrowed byte sequence: an OWNED COPY of
        /// exactly the bytes the receiver borrows. `&str` becomes
        /// `r2z.alloc.String`; `&[T]` becomes `r2z.alloc.Vec(T)`.
        borrowed_to_owned,
        /// `Cow::as_bytes`: the borrowed bytes the cow is holding, whichever
        /// arm it happens to be holding them in.
        cow_as_bytes,
        /// `Cow::into_owned`: the owned payload the cow was guarding, handed
        /// back by the very same allocation when it already owns one and by a
        /// fresh copy when it borrowed. `Cow::to_owned` is NOT this half — a
        /// `Cow` is `Clone`, so that name answers with a copy of the same cow
        /// taken through `&self` and is lowered as `.clone`.
        cow_to_owned,
        /// `alloc::vec::Vec::push`: append one element to the caller's vector,
        /// which is `ArrayList.append` under its own name.
        vec_push,
        /// `alloc::vec::Vec::extend`: append everything the argument yields
        /// to the caller's vector. Rust accepts any `IntoIterator` here, so the
        /// runtime helper covers a sequence it can copy in whole and an
        /// iterator it can drain item by item.
        vec_extend,
        /// `alloc::string::String::push`: append one `char`. The receiver is
        /// the `&mut String` the source borrowed, so it arrives as a
        /// reference to the owned string, and the bytes it gains may grow the
        /// buffer — which is why the call names the enclosing allocator.
        string_push,
        /// `alloc::string::String::push_str`: append the borrowed text.
        string_push_str,
        /// `FromUtf8Error::utf8_error`: the character-level failure this error
        /// wraps, handed back unchanged.
        utf8_error,
        /// `Utf8Error::valid_up_to`: how many bytes at the front of the slice
        /// were valid before the failure. Rust declares it `&self` and it is a
        /// plain field on the runtime's `r2z.character.Utf8Error`, so the call
        /// is a field read and the error keeps the bytes it came with.
        utf8_error_valid_up_to,

        default,
        clone,
    };

    fn canonicalExternalMethodType(
        self: *const Lowerer,
        ty: ir.types.Type,
    ) ?SyntheticExternalType {
        return switch (ty) {
            .external_nominal => |external| blk: {
                if (external.path.len != 3) break :blk null;
                const root_is_valid = std.mem.eql(u8, external.path[0], "core") or
                    std.mem.eql(u8, external.path[0], "std");
                if (!root_is_valid) break :blk null;
                if (std.mem.eql(u8, external.path[1], "option") and
                    std.mem.eql(u8, external.path[2], "Option"))
                {
                    break :blk .option;
                }
                if (std.mem.eql(u8, external.path[1], "result") and
                    std.mem.eql(u8, external.path[2], "Result"))
                {
                    break :blk .result;
                }
                break :blk null;
            },
            .generic_inst => |inst| self.syntheticExternalType(inst.decl),
            else => null,
        };
    }

    /// Classify a resolver-recognized standard method from the typed receiver.
    /// Keeping this type-aware prevents an inherent method with the same name
    /// from being mistaken for a prelude operation.
    fn lookupRecognizedStdMethod(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        method_name: []const u8,
    ) anyerror!?RecognizedStdMethod {
        var cur_t = try self.exprType(receiver_node) orelse return null;
        if (self.current_callable_id) |owner| {
            if (std.mem.eql(u8, method_name, "read_exact") and
                ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "std", "io", "Read" }) != null)
            {
                return .io_read_exact;
            }
            if (std.mem.eql(u8, method_name, "write_all") and
                ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "std", "io", "Write" }) != null)
            {
                return .io_write_all;
            }
            // `BufRead` is the bound that separates the buffered pair from an
            // ordinary `Read`, and it is the bound the source declares — not
            // the spelling — that identifies them. `fill_buf` hands back a view
            // of the runtime's own buffer and `consume` advances past it, so
            // neither is an operation on the wrapped reader's state and both
            // reach the buffered pair by address.
            if (std.mem.eql(u8, method_name, "fill_buf") and
                ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "std", "io", "BufRead" }) != null)
            {
                return .io_fill_buf;
            }
            if (std.mem.eql(u8, method_name, "consume") and
                ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "std", "io", "BufRead" }) != null)
            {
                return .io_consume;
            }
            const checked_trait: ?[]const u8 = if (std.mem.eql(u8, method_name, "checked_add"))
                "CheckedAdd"
            else if (std.mem.eql(u8, method_name, "checked_sub"))
                "CheckedSub"
            else if (std.mem.eql(u8, method_name, "checked_mul"))
                "CheckedMul"
            else
                null;
            if (checked_trait) |trait_name| {
                if (ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "num_traits", "ops", "checked", trait_name }) != null or
                    ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, cur_t, &.{ "num_traits", trait_name }) != null)
                {
                    if (std.mem.eql(u8, method_name, "checked_add")) return .num_checked_add;
                    if (std.mem.eql(u8, method_name, "checked_sub")) return .num_checked_sub;
                    return .num_checked_mul;
                }
            }
        }
        for (0..128) |_| {
            switch (cur_t) {
                .reference => |reference| cur_t = reference.pointee,
                .boxed => |boxed| cur_t = boxed.*,
                .@"opaque" => |opaque_type| {
                    cur_t = (opaque_type.concrete orelse break).*;
                },
                else => break,
            }
        }
        if (ir.types.isStr(cur_t)) {
            if (std.mem.eql(u8, method_name, "len")) return .slice_len;
            if (std.mem.eql(u8, method_name, "is_empty")) return .slice_is_empty;
            if (std.mem.eql(u8, method_name, "as_bytes")) return .slice_as_bytes;
        }

        // `ToString::to_string` is blanket-implemented for `T: Display`. The
        // frontend proved the bound; re-deriving it here keeps the backend
        // from emitting a runtime call for a receiver the resolver refuses.
        if (std.mem.eql(u8, method_name, "to_string") and self.hasDisplayReceiver(cur_t)) {
            return .to_string;
        }

        switch (cur_t) {
            .option => {
                if (std.mem.eql(u8, method_name, "is_some")) return .option_is_some;
                if (std.mem.eql(u8, method_name, "is_none")) return .option_is_none;
                if (std.mem.eql(u8, method_name, "unwrap")) return .option_unwrap;
                if (std.mem.eql(u8, method_name, "unwrap_or")) return .option_unwrap_or;
                if (std.mem.eql(u8, method_name, "map")) return .option_map;
                if (std.mem.eql(u8, method_name, "and_then")) return .option_and_then;
                if (std.mem.eql(u8, method_name, "as_ref")) return .option_as_ref;
                if (std.mem.eql(u8, method_name, "take")) return .option_take;
            },
            .result => |result| {
                // A `Result` lowers to a Zig error union only when its error
                // type is a fieldless enum, which is the decision `lowerType`
                // makes and `resultUsesErrorUnion` reads back. An error that
                // carries a payload cannot be spelled as a Zig error set —
                // a union would have to drop it — so the value is the tagged
                // `r2z.Result`, which does carry the error value. Gating on
                // `is_error_unionable` alone is therefore too coarse: it
                // records what the frontend was ASKED to do, not what the
                // shape permits, and it refuses every method below for a
                // receiver that lowered to the tagged union.
                if (!self.resultUsesErrorUnion(.{ .result = result })) {
                    if (std.mem.eql(u8, method_name, "is_ok")) return .result_is_ok;
                    if (std.mem.eql(u8, method_name, "is_err")) return .result_is_err;
                    if (std.mem.eql(u8, method_name, "unwrap")) return .result_unwrap;
                    if (std.mem.eql(u8, method_name, "unwrap_err")) return .result_unwrap_err;
                    if (std.mem.eql(u8, method_name, "expect")) return .result_expect;
                    if (std.mem.eql(u8, method_name, "expect_err")) return .result_expect_err;
                    if (std.mem.eql(u8, method_name, "unwrap_or")) return .result_unwrap_or;
                    if (std.mem.eql(u8, method_name, "ok")) return .result_ok;
                    if (std.mem.eql(u8, method_name, "err")) return .result_err;
                    if (std.mem.eql(u8, method_name, "map")) return .result_map;
                    if (std.mem.eql(u8, method_name, "map_err")) return .result_map_err;
                    if (std.mem.eql(u8, method_name, "as_ref")) return .result_as_ref;
                    if (std.mem.eql(u8, method_name, "as_mut")) return .result_as_mut;
                } else if (self.errorTypeIsZigErrorSet(result.err)) {
                    // The receiver lowered to a Zig error union, so unwrapping
                    // is propagating its error.
                    if (std.mem.eql(u8, method_name, "unwrap")) return .error_union_unwrap;
                    // The union holds the `Ok` payload and the failure as a
                    // tag, and carries no runtime `Result` for a method to
                    // live on, so both expectations are runtime helpers that
                    // read the union out whole.
                    if (std.mem.eql(u8, method_name, "expect")) return .error_union_expect;
                    // A fieldless error enum kept its variants when it became
                    // an error set, so there IS a failure here for
                    // `expect_err` to hand back: the tag.
                    if (std.mem.eql(u8, method_name, "expect_err")) {
                        return .error_union_expect_err;
                    }
                }
            },
            .slice, .array => {
                if (std.mem.eql(u8, method_name, "len")) return .slice_len;
                if (std.mem.eql(u8, method_name, "is_empty")) return .slice_is_empty;
                if (std.mem.eql(u8, method_name, "as_bytes")) return .slice_as_bytes;
                if (std.mem.eql(u8, method_name, "as_slice")) return .slice_as_slice;
                if (std.mem.eql(u8, method_name, "iter")) return .slice_iter;
                if (std.mem.eql(u8, method_name, "chunks")) return .slice_chunks;
                if (std.mem.eql(u8, method_name, "split_at")) return .slice_split_at;
                if (std.mem.eql(u8, method_name, "split_first")) return .slice_split_first;
                if (std.mem.eql(u8, method_name, "first")) return .slice_first;
                if (std.mem.eql(u8, method_name, "chunks_exact")) return .slice_chunks_exact;
                if (std.mem.eql(u8, method_name, "copy_from_slice")) return .slice_copy_from_slice;
                if (std.mem.eql(u8, method_name, "as_ptr")) return .memory_slice_as_ptr;
                if (std.mem.eql(u8, method_name, "as_mut_ptr")) return .memory_slice_as_mut_ptr;
                if (std.mem.eql(u8, method_name, "get_unchecked")) {
                    return .memory_slice_get_unchecked;
                }
                if (std.mem.eql(u8, method_name, "get_unchecked_mut")) {
                    return .memory_slice_get_unchecked_mut;
                }
                // `to_owned` on a SLICE is the owned copy of exactly the bytes
                // it borrows. An ARRAY receiver is deliberately left out: the
                // runtime copy takes a sequence, and reading one out of an
                // array would have to build that slice first, which is a
                // conversion the source never performed.
                if (cur_t == .slice and std.mem.eql(u8, method_name, "to_owned")) {
                    return .borrowed_to_owned;
                }
            },
            .raw_ptr => {
                if (std.mem.eql(u8, method_name, "add")) return .memory_ptr_add;
                if (std.mem.eql(u8, method_name, "sub")) return .memory_ptr_sub;
                if (std.mem.eql(u8, method_name, "offset")) return .memory_ptr_offset;
                if (std.mem.eql(u8, method_name, "read_unaligned")) {
                    return .memory_ptr_read_unaligned;
                }
            },
            .prim => |prim| switch (prim) {
                .u8, .u16, .u32, .u64, .u128, .usize, .i8, .i16, .i32, .i64, .i128, .isize => {
                    if (prim == .u8 and std.mem.eql(u8, method_name, "is_ascii")) return .byte_is_ascii;
                    if (std.mem.eql(u8, method_name, "wrapping_add")) return .num_wrapping_add;
                    if (std.mem.eql(u8, method_name, "wrapping_sub")) return .num_wrapping_sub;
                    if (std.mem.eql(u8, method_name, "wrapping_mul")) return .num_wrapping_mul;
                    if (std.mem.eql(u8, method_name, "saturating_add")) return .num_saturating_add;
                    if (std.mem.eql(u8, method_name, "saturating_sub")) return .num_saturating_sub;
                    if (std.mem.eql(u8, method_name, "saturating_mul")) return .num_saturating_mul;
                    if (std.mem.eql(u8, method_name, "count_ones")) return .num_count_ones;
                    if (std.mem.eql(u8, method_name, "leading_zeros")) return .num_leading_zeros;
                    if (std.mem.eql(u8, method_name, "trailing_zeros")) return .num_trailing_zeros;
                    if (std.mem.eql(u8, method_name, "rotate_left")) return .num_rotate_left;
                    if (std.mem.eql(u8, method_name, "rotate_right")) return .num_rotate_right;
                    if (std.mem.eql(u8, method_name, "to_le")) return .num_to_le;
                    if (std.mem.eql(u8, method_name, "to_be")) return .num_to_be;
                    if (std.mem.eql(u8, method_name, "swap_bytes")) return .num_swap_bytes;
                    if (std.mem.eql(u8, method_name, "checked_add")) return .num_checked_add;
                    if (std.mem.eql(u8, method_name, "checked_sub")) return .num_checked_sub;
                    if (std.mem.eql(u8, method_name, "checked_mul")) return .num_checked_mul;
                },
                else => {},
            },
            .external_nominal => {
                const external = cur_t.external_nominal;
                if ((externalPathEqual(external.path, &.{ "core", "fmt", "Formatter" }) or
                    externalPathEqual(external.path, &.{ "std", "fmt", "Formatter" })) and
                    std.mem.eql(u8, method_name, "write_str")) return .format_write_str;
                if (canonicalExternalMethodType(self, cur_t)) |synthetic_kind| {
                    switch (synthetic_kind) {
                        .option => {
                            if (std.mem.eql(u8, method_name, "is_some")) return .option_is_some;
                            if (std.mem.eql(u8, method_name, "is_none")) return .option_is_none;
                            if (std.mem.eql(u8, method_name, "unwrap")) return .option_unwrap;
                            if (std.mem.eql(u8, method_name, "unwrap_or")) return .option_unwrap_or;
                            if (std.mem.eql(u8, method_name, "map")) return .option_map;
                            if (std.mem.eql(u8, method_name, "and_then")) return .option_and_then;
                            if (std.mem.eql(u8, method_name, "as_ref")) return .option_as_ref;
                            if (std.mem.eql(u8, method_name, "take")) return .option_take;
                        },
                        .result => {
                            if (std.mem.eql(u8, method_name, "is_ok")) return .result_is_ok;
                            if (std.mem.eql(u8, method_name, "is_err")) return .result_is_err;
                            if (std.mem.eql(u8, method_name, "unwrap")) return .result_unwrap;
                            if (std.mem.eql(u8, method_name, "unwrap_err")) return .result_unwrap_err;
                            if (std.mem.eql(u8, method_name, "expect")) return .result_expect;
                            if (std.mem.eql(u8, method_name, "expect_err")) return .result_expect_err;
                            if (std.mem.eql(u8, method_name, "unwrap_or")) return .result_unwrap_or;
                            if (std.mem.eql(u8, method_name, "ok")) return .result_ok;
                            if (std.mem.eql(u8, method_name, "err")) return .result_err;
                            if (std.mem.eql(u8, method_name, "map")) return .result_map;
                            if (std.mem.eql(u8, method_name, "map_err")) return .result_map_err;
                            if (std.mem.eql(u8, method_name, "as_ref")) return .result_as_ref;
                            if (std.mem.eql(u8, method_name, "as_mut")) return .result_as_mut;
                        },
                    }
                }
                if (isChunksExactType(cur_t) and std.mem.eql(u8, method_name, "remainder")) {
                    return .chunks_exact_remainder;
                }
                // `ToOwned::to_owned` on `&str` is the owned copy of the very
                // bytes the borrow names, and `FromUtf8Error::utf8_error` is
                // the character-level failure this error already wraps. Both
                // receivers are named by their FULL standard-library path, so
                // a crate's own `String` or `FromUtf8Error` cannot claim them.
                if (ir.types.isStr(cur_t) and std.mem.eql(u8, method_name, "to_owned")) {
                    return .borrowed_to_owned;
                }
                if ((externalPathEqual(external.path, &.{ "alloc", "string", "FromUtf8Error" }) or
                    externalPathEqual(external.path, &.{ "std", "string", "FromUtf8Error" })) and
                    std.mem.eql(u8, method_name, "utf8_error"))
                {
                    return .utf8_error;
                }
                // `core::str::Utf8Error` is the character-level failure itself
                // — the type `FromUtf8Error` wraps, and the one a direct
                // `core::str::from_utf8` produces. `valid_up_to` is a `&self`
                // accessor over a plain field, so the receiver is READ and
                // nothing is moved out of it. Naming the FULL standard path is
                // what keeps a crate's own `Utf8Error`, and a user's inherent
                // method of this name on any other receiver, out of this arm.
                if ((externalPathEqual(external.path, &.{ "core", "str", "Utf8Error" }) or
                    externalPathEqual(external.path, &.{ "std", "str", "Utf8Error" })) and
                    std.mem.eql(u8, method_name, "valid_up_to"))
                {
                    return .utf8_error_valid_up_to;
                }
                // `Cow` is a borrow-or-own pair: asking it for bytes reads the
                // arm it is holding, asking it to CONSUME the pair trades the
                // borrow for the owned payload it was guarding, and asking it
                // for its own owned form COPIES it.
                //
                // `to_owned` is that copy, not the consuming conversion. A
                // `Cow` is `Clone`, so `impl<T: Clone> ToOwned for T { type
                // Owned = T }` answers the name with a copy of the SAME cow
                // taken through `&self`, and the receiver is still usable
                // afterwards. Naming `into_owned` for it would move a value
                // Rust only read, and answering it with the receiver itself
                // would hand two owners the same allocation the moment both are
                // released. `.clone` is the only faithful answer, and it is the
                // deep copy the runtime publishes for an owned arm.
                if (isCowPath(external.path) and external.args.len == 1) {
                    if (std.mem.eql(u8, method_name, "as_bytes")) return .cow_as_bytes;
                    if (std.mem.eql(u8, method_name, "into_owned")) return .cow_to_owned;
                    if (std.mem.eql(u8, method_name, "to_owned")) return .clone;
                }
                // Growing a `Vec` needs the allocator; reading its length uses
                // the existing slice-length operation over runtime storage.
                if (isAllocVecPath(external.path)) {
                    if (external.args.len == 1 and std.mem.eql(u8, method_name, "len")) return .slice_len;
                    if (std.mem.eql(u8, method_name, "push")) return .vec_push;
                    if (std.mem.eql(u8, method_name, "extend")) return .vec_extend;
                }
                // `&mut String` reaches this point already peeled to the owned
                // nominal by the deref loop above, which is the same peel
                // `resolve_methods.unpeelReceiverType` performs before its own
                // `string_push` arm — so both halves of the pipeline classify
                // the receiver at the same place in the borrow chain.
                if (isAllocStringPath(external.path) and external.args.len == 0) {
                    if (std.mem.eql(u8, method_name, "push")) return .string_push;
                    if (std.mem.eql(u8, method_name, "push_str")) return .string_push_str;
                }
                if (isRuntimeIteratorCarrier(cur_t)) {
                    if (std.mem.eql(u8, method_name, "step_by")) return .iterator_step_by;
                    if (std.mem.eql(u8, method_name, "skip")) return .iterator_skip;
                    if (std.mem.eql(u8, method_name, "zip")) return .iterator_zip;
                    if (std.mem.eql(u8, method_name, "collect")) return .iterator_collect;
                }
                // `any` takes `&mut self` and a closure, and it is the
                // closure that decides it — no Zig member spells it, so it
                // is expanded into an explicit walk at the call site. The
                // receiver is the wider `next`-driven set, which also covers
                // the slice-owned iterators the arms above do not model.
                if (std.mem.eql(u8, method_name, "any") and
                    isNextDrivenIteratorCarrier(cur_t)) return .iterator_any;
            },
            .generic_inst => {
                if (canonicalExternalMethodType(self, cur_t)) |synthetic_kind| {
                    switch (synthetic_kind) {
                        .option => {
                            if (std.mem.eql(u8, method_name, "is_some")) return .option_is_some;
                            if (std.mem.eql(u8, method_name, "is_none")) return .option_is_none;
                            if (std.mem.eql(u8, method_name, "unwrap")) return .option_unwrap;
                            if (std.mem.eql(u8, method_name, "unwrap_or")) return .option_unwrap_or;
                            if (std.mem.eql(u8, method_name, "map")) return .option_map;
                            if (std.mem.eql(u8, method_name, "and_then")) return .option_and_then;
                            if (std.mem.eql(u8, method_name, "as_ref")) return .option_as_ref;
                            if (std.mem.eql(u8, method_name, "take")) return .option_take;
                        },
                        .result => {
                            if (std.mem.eql(u8, method_name, "is_ok")) return .result_is_ok;
                            if (std.mem.eql(u8, method_name, "is_err")) return .result_is_err;
                            if (std.mem.eql(u8, method_name, "unwrap")) return .result_unwrap;
                            if (std.mem.eql(u8, method_name, "unwrap_err")) return .result_unwrap_err;
                            if (std.mem.eql(u8, method_name, "expect")) return .result_expect;
                            if (std.mem.eql(u8, method_name, "expect_err")) return .result_expect_err;
                            if (std.mem.eql(u8, method_name, "unwrap_or")) return .result_unwrap_or;
                            if (std.mem.eql(u8, method_name, "ok")) return .result_ok;
                            if (std.mem.eql(u8, method_name, "err")) return .result_err;
                            if (std.mem.eql(u8, method_name, "map")) return .result_map;
                            if (std.mem.eql(u8, method_name, "map_err")) return .result_map_err;
                            if (std.mem.eql(u8, method_name, "as_ref")) return .result_as_ref;
                            if (std.mem.eql(u8, method_name, "as_mut")) return .result_as_mut;
                        },
                    }
                }
            },
            .path,
            .reference,
            .tuple,
            .fn_ptr,
            .boxed,
            .@"opaque",
            .dyn_trait,
            .unsupported,
            => {},
        }

        if (std.mem.eql(u8, method_name, "default")) return .default;
        if (std.mem.eql(u8, method_name, "clone")) return .clone;
        return null;
    }

    /// The element type a `collect::<C>()` deposits, or null when the
    /// turbofish does not name one.
    ///
    /// Rust writes the element down exactly once, as the `Item` of the
    /// iterator's bound, and `collect::<Vec<_>>()` leaves the container's own
    /// argument as an inference placeholder. Inference fills that placeholder
    /// from the bound; when the bound declares no `Item` nothing stands in for
    /// it and the placeholder survives. A placeholder is therefore not an
    /// element type: admitting one would emit a `vec_collect` whose element
    /// nothing in the program names.
    ///
    /// The receiver's own `Item` is deliberately not read here. It is the
    /// same evidence, and reading it twice would give the two paths a chance
    /// to disagree.
    fn collectElementType(generic_args: []const ir.types.Type) ?ir.types.Type {
        if (generic_args.len != 1) return null;
        const external = switch (generic_args[0]) {
            .external_nominal => |value| value,
            else => return null,
        };
        if (external.args.len != 1) return null;
        const element = external.args[0];
        if (element == .external_nominal and element.external_nominal.path.len == 1 and
            std.mem.eql(u8, element.external_nominal.path[0], "_"))
        {
            return null;
        }
        return element;
    }

    /// Whether the Zig backend can render `t` through a Rust `Display`
    /// implementation. Mirrors the frontend's `hasGraphFreeDisplay` plus the
    /// crate-local `impl Display for T` bound, because a runtime call must
    /// never be emitted for a receiver the resolver would have refused.
    fn hasDisplayReceiver(self: *const Lowerer, t: ir.types.Type) bool {
        return switch (t) {
            .prim => |primitive| switch (primitive) {
                // `()`, `!`, and floats have no `r2z.format.writeValue` arm.
                .unit, .never, .f32, .f64 => false,
                else => true,
            },
            // A Rust `&str` reaches the backend as a byte slice, and it is
            // the one sequence type with a `Display` impl: `"x".to_string()`
            // writes the bytes and nothing else. `r2z.format.writeValue`
            // renders a `[]const u8` receiver exactly that way, so the
            // runtime already has the arm. A `&[u8]` cannot reach this
            // line: Rust has no `Display` for it, so the resolver never
            // hands the backend the call.
            .slice => |slice| sameIrType(slice.elem, .{ .prim = .u8 }),
            .external_nominal => |external| {
                if (ir.types.isStr(t)) return true;
                if (external.args.len == 0 and externalPathEqual(
                    external.path,
                    &.{ "alloc", "string", "String" },
                )) return true;
                if (externalPathEqual(external.path, &.{ "std", "string", "String" })) {
                    return external.args.len == 0;
                }
                if (isCowPath(external.path) and external.args.len == 1 and
                    ir.types.isStr(external.args[0])) return true;
                return false;
            },
            // A crate-local nominal qualifies only when the crate declares the
            // bound. `fmt` is required, not just `Display`: it is the decl
            // `r2z.format.writeValue` looks for on the lowered type.
            .path => |path| {
                if (path.segments.len == 0) return false;
                return self.declaresDisplayFmt(path.segments[path.segments.len - 1].name);
            },
            .generic_inst => |inst| {
                const decl = self.ir.graph.symbol_table.get(inst.decl) orelse return false;
                return self.declaresDisplayFmt(decl.name);
            },
            else => false,
        };
    }

    /// Whether the crate declares `impl Display for <type_name>` carrying a
    /// `fmt` member. `Debug` is never accepted: Rust declares only
    /// `impl<T: Display + ?Sized> ToString for T`, so a `Debug`-only type
    /// cannot call `.to_string()`.
    fn declaresDisplayFmt(self: *const Lowerer, type_name: []const u8) bool {
        if (type_name.len == 0) return false;
        const entities = self.ir.graph.symbol_table.entities.items;
        for (entities) |entity| {
            if (entity.kind != .impl_) continue;
            const separator = std.mem.indexOf(u8, entity.name, " for ") orelse continue;
            if (!std.mem.eql(u8, entity.name[separator + 5 ..], type_name)) continue;
            const trait_name = entity.name[0..separator];
            // The impl header may spell the trait bare (`Display for T`) or
            // path-qualified (`fmt::Display for T`); both name `Display`.
            const colon = std.mem.lastIndexOf(u8, trait_name, "::");
            const simple_trait = if (colon) |index| trait_name[index + 2 ..] else trait_name;
            if (!std.mem.eql(u8, simple_trait, "Display")) continue;
            for (entities) |child| {
                if (child.kind == .fn_ and child.parent == entity.id and
                    std.mem.eql(u8, child.name, "fmt")) return true;
            }
        }
        return false;
    }

    fn lowerUnsupportedStdMethod(
        self: *Lowerer,
        method_name: []const u8,
    ) !*const ast.Expr {
        _ = self;
        _ = method_name;
        return error.UnsupportedStandardMethod;
    }

    /// Iterator and range methods with no Zig counterpart. They must refuse
    /// instead of falling through to a `receiver.method()` call Zig rejects.
    fn isMissingIteratorMethod(method_name: []const u8) bool {
        const names = [_][]const u8{ "rev", "count", "nth", "last", "position" };
        for (names) |name| {
            if (std.mem.eql(u8, method_name, name)) return true;
        }
        return false;
    }

    /// Whether a method receiver is a bare range or an `r2z` iterator — the
    /// two shapes with no Zig member surface for `rev`, `count` and friends.
    fn isRangeOrRuntimeIteratorReceiver(self: *Lowerer, receiver_id: ir.exprs.NodeId) anyerror!bool {
        if (receiver_id < self.ir.bodies.exprs.len and
            self.ir.bodies.exprs[receiver_id].kind == .range) return true;
        return self.isRuntimeIteratorInput(receiver_id);
    }

    fn receiverIsPointerLike(self: *Lowerer, receiver_node: ir.exprs.NodeId) !bool {
        const receiver_type = try self.exprType(receiver_node) orelse return false;
        return switch (receiver_type) {
            .reference, .raw_ptr => true,
            else => false,
        };
    }

    fn lowerRuntimeResultMethodCall(
        self: *Lowerer,
        method_name: []const u8,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
    ) !*const ast.Expr {
        const needs_pointer = std.mem.eql(u8, method_name, "as_ref") or
            std.mem.eql(u8, method_name, "as_mut");
        const method_receiver = if (needs_pointer) blk: {
            if (try self.receiverIsPointerLike(receiver_node)) break :blk receiver;
            break :blk try self.allocExpr(.{ .unary_op = .{
                .op = .addr_of,
                .operand = receiver,
            } });
        } else if (try self.receiverIsPointerLike(receiver_node))
            try self.allocExpr(.{ .unary_op = .{
                .op = .deref,
                .operand = receiver,
            } })
        else
            receiver;

        // Consuming extraction releases the discarded arm, including null and
        // panic paths. This needs an allocator but adds no returned failure.
        const takes_allocator = std.mem.eql(u8, method_name, "unwrap") or
            std.mem.eql(u8, method_name, "unwrap_err") or
            std.mem.eql(u8, method_name, "expect") or
            std.mem.eql(u8, method_name, "expect_err") or
            std.mem.eql(u8, method_name, "ok") or
            std.mem.eql(u8, method_name, "err");
        const callee = try self.allocExpr(.{ .field_access = .{
            .target = method_receiver,
            .field_name = try self.alloc.dupe(u8, method_name),
        } });
        if (!takes_allocator) return self.allocExpr(.{ .call = .{
            .callee = callee,
            .args = args,
        } });
        try self.markRuntimeImport();
        self.current_callable_is_allocating = true;
        const call_args = try self.alloc.alloc(ast.Expr, args.len + 1);
        call_args[0] = .{ .ident = "allocator" };
        @memcpy(call_args[1..], args);
        return self.allocExpr(.{ .call = .{
            .callee = callee,
            .args = call_args,
        } });
    }

    fn memoryElementType(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!?ir.types.Type {
        var receiver_type = try self.exprType(receiver_node) orelse return null;
        for (0..128) |_| {
            switch (receiver_type) {
                .reference => |reference| receiver_type = reference.pointee,
                .boxed => |boxed| receiver_type = boxed.*,
                .@"opaque" => |opaque_type| {
                    receiver_type = (opaque_type.concrete orelse return null).*;
                },
                .raw_ptr => |raw_ptr| return raw_ptr.pointee,
                .slice => |slice| return slice.elem,
                .array => |array| return array.elem,
                else => return null,
            }
        }
        return null;
    }

    fn lowerMemoryReceiver(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
    ) anyerror!*const ast.Expr {
        var current_type = try self.exprType(receiver_node) orelse return receiver;
        var result = receiver;
        for (0..128) |_| {
            switch (current_type) {
                .reference => |reference| {
                    // `lowerType` spells the borrow of a FAT pointer AS that
                    // pointer: `&str` is `[]const u8` and `&[T]` is `[]const T`,
                    // with no pointee behind them to read out of. A `*` here
                    // would read the slice back as one element rather than as
                    // the slice, so the receiver already is the borrowed
                    // value and there is nothing to dereference.
                    if (isSliceShapedBorrow(reference.pointee)) return result;
                    // A borrow of a HASH-BOUND type parameter is the one shape
                    // that is neither statically fat nor statically thin, and
                    // the IR cannot say which. The signature already decided
                    // through `RustHashRef`, so the read follows that SAME
                    // decision. `rustHashRefIsFat` is comptime, so one arm is
                    // analyzed per instantiation and the untaken one never has
                    // to type. A parameter with no proven `Hash` bound keeps
                    // the unconditional `*` below.
                    if (self.hashReferenceNeedsDescriptor(reference.pointee)) {
                        const borrowed = if (result.* == .unary_op and result.unary_op.op == .addr_of)
                            result.unary_op.operand
                        else
                            result;
                        return try self.allocExpr(.{ .if_expr = .{
                            .cond = try self.hashReferenceIsFatExpr(reference.pointee),
                            .then_body = borrowed,
                            .else_body = try self.allocExpr(.{ .unary_op = .{
                                .op = .deref,
                                .operand = try self.allocExpr(borrowed.*),
                            } }),
                        } });
                    }
                    result = if (result.* == .unary_op and result.unary_op.op == .addr_of)
                        result.unary_op.operand
                    else
                        try self.allocExpr(.{ .unary_op = .{ .op = .deref, .operand = result } });
                    current_type = reference.pointee;
                },
                else => return result,
            }
        }
        return result;
    }

    fn lowerMemoryMethodCall(
        self: *Lowerer,
        method: RecognizedStdMethod,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
    ) anyerror!*const ast.Expr {
        const method_receiver = try self.lowerMemoryReceiver(receiver_node, receiver);
        switch (method) {
            .memory_slice_as_ptr, .memory_slice_as_mut_ptr => {
                if (args.len != 0) return self.lowerUnsupportedStdMethod("as_ptr");
                const slice = try self.lowerAsRef(receiver_node, method_receiver);
                return try self.allocExpr(.{ .field_access = .{
                    .target = slice,
                    .field_name = try self.alloc.dupe(u8, "ptr"),
                } });
            },
            .memory_slice_get_unchecked, .memory_slice_get_unchecked_mut => {
                if (args.len != 1) return self.lowerUnsupportedStdMethod("get_unchecked");
                const index_args = try self.alloc.alloc(ast.Expr, 2);
                index_args[0] = method_receiver.*;
                index_args[1] = args[0];
                const indexed = try self.allocExpr(.{ .builtin = .{
                    .name = "index",
                    .args = index_args,
                } });
                return try self.allocExpr(.{ .unary_op = .{
                    .op = .addr_of,
                    .operand = indexed,
                } });
            },
            .memory_ptr_add, .memory_ptr_sub, .memory_ptr_offset, .memory_ptr_read_unaligned => {},
            else => return error.InvalidMethod,
        }

        const elem_type = try self.memoryElementType(receiver_node) orelse {
            return error.UnsupportedStandardMethod;
        };
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(elem_type);
        const method_name = switch (method) {
            .memory_ptr_add => "add",
            .memory_ptr_sub => "sub",
            .memory_ptr_offset => "offset",
            .memory_ptr_read_unaligned => "read_unaligned",
            else => unreachable,
        };
        const expected_args: usize = if (method == .memory_ptr_read_unaligned) 0 else 1;
        if (args.len != expected_args) return self.lowerUnsupportedStdMethod(method_name);
        const call_args = try self.alloc.alloc(ast.Expr, args.len + 1);
        call_args[0] = method_receiver.*;
        @memcpy(call_args[1..], args);
        try self.markRuntimeImport();
        const callee_name = try std.fmt.allocPrint(self.alloc, "r2z.memory.{s}", .{method_name});
        const callee = try self.allocExpr(.{ .ident = callee_name });
        return self.allocExpr(.{ .call = .{
            .callee = callee,
            .generic_args = generic_args,
            .args = call_args,
        } });
    }

    fn lowerIntegerStdMethod(
        self: *Lowerer,
        method: RecognizedStdMethod,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        argument_nodes: []const ir.exprs.NodeId,
    ) anyerror!*const ast.Expr {
        const argument_count: usize = switch (method) {
            .num_rotate_left, .num_rotate_right, .num_checked_add, .num_checked_sub, .num_checked_mul => 1,
            .num_to_le, .num_to_be, .num_swap_bytes => 0,
            else => return error.UnsupportedStandardMethod,
        };
        if (args.len != argument_count or argument_nodes.len != args.len)
            return error.UnsupportedStandardMethod;
        var scalar = (try self.exprType(receiver_node)) orelse return error.MissingExpressionType;
        for (0..128) |_| {
            if (scalar != .reference) break;
            scalar = scalar.reference.pointee;
        }
        if (scalar != .prim and !isTypeParameterPath(scalar)) return error.UnsupportedStandardMethod;
        const value = try self.lowerMemoryReceiver(receiver_node, receiver);
        const call_args = try self.alloc.alloc(ast.Expr, args.len + 1);
        call_args[0] = value.*;
        for (args, argument_nodes, 1..) |argument, node, index| {
            call_args[index] = (try self.lowerMemoryReceiver(node, try self.allocExpr(argument))).*;
        }
        if (method == .num_swap_bytes) {
            return self.allocExpr(.{ .builtin = .{ .name = "byteSwap", .args = call_args } });
        }
        const name = switch (method) {
            .num_rotate_left => "r2z.rotateLeft",
            .num_rotate_right => "r2z.rotateRight",
            .num_checked_add => "r2z.checkedAdd",
            .num_checked_sub => "r2z.checkedSub",
            .num_checked_mul => "r2z.checkedMul",
            .num_to_le => "std.mem.nativeToLittle",
            .num_to_be => "std.mem.nativeToBig",
            else => return error.UnsupportedStandardMethod,
        };
        if (std.mem.startsWith(u8, name, "r2z.")) try self.markRuntimeImport();
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(scalar);
        return self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = name }),
            .generic_args = generic_args,
            .args = call_args,
        } });
    }

    fn lowerOptionTake(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
    ) !*const ast.Expr {
        if (args.len != 0) return self.lowerUnsupportedStdMethod("take");
        const target = if (try self.receiverIsPointerLike(receiver_node))
            try self.allocExpr(.{ .unary_op = .{
                .op = .deref,
                .operand = receiver,
            } })
        else
            receiver;
        const option_type = try self.exprType(receiver_node) orelse {
            return error.UnsupportedStandardMethod;
        };
        var lowered_option_type = option_type;
        for (0..128) |_| {
            switch (lowered_option_type) {
                .reference => |reference| lowered_option_type = reference.pointee,
                .raw_ptr => |raw_ptr| lowered_option_type = raw_ptr.pointee,
                .boxed => |boxed| lowered_option_type = boxed.*,
                .@"opaque" => |opaque_type| {
                    lowered_option_type = (opaque_type.concrete orelse {
                        return error.UnsupportedStandardMethod;
                    }).*;
                },
                else => break,
            }
        }
        const name = try std.fmt.allocPrint(
            self.alloc,
            "__r2z_option_take_{d}",
            .{receiver_node},
        );
        const statements = try self.alloc.alloc(ast.Stmt, 2);
        statements[0] = .{ .let_stmt = .{
            .name = name,
            .ty = try self.lowerType(lowered_option_type),
            .init = target.*,
            .is_mut = false,
        } };
        statements[1] = .{ .assign = .{
            .target = target.*,
            .val = .{ .lit = .null_lit },
            .op = .assign,
        } };
        return self.allocExpr(.{ .block = .{
            .stmts = statements,
            .expr = try self.allocExpr(.{ .ident = name }),
        } });
    }

    /// The `Cow<..>` nominal a conversion is heading for, or null when the
    /// target is some other type entirely.
    fn cowConversionNominal(ty: ir.types.Type) ?ir.types.ExternalNominal {
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return null,
        };
        if (external.args.len != 1) return null;
        return if (isCowPath(external.path)) external else null;
    }

    /// `into()` a concrete borrow or an owned value into a `Cow`.
    ///
    /// A BORROW keeps the caller's own bytes and owns nothing, so the cow
    /// points at what it already pointed at. An owned value hands its
    /// allocation over and is left empty, so nothing is copied and nothing
    /// leaks. Each is one constructor on the runtime cow, and the generic
    /// argument belongs to the TYPE rather than to the call: these are
    /// declarations inside the type its parameter list instantiates.
    ///
    /// `from_owned` transfers IN PLACE, so it is handed a pointer to the
    /// storage the source named: a place directly, and an rvalue — the shape
    /// every conversion receiver has, `String::from_utf8(bytes).into()` —
    /// materialized once first. Either way the transfer empties what it was
    /// handed, so the source ends the call holding no storage of its own and
    /// is never released a second time.
    fn lowerCowConversion(
        self: *Lowerer,
        cow: ir.types.ExternalNominal,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
    ) !ast.Expr {
        try self.markRuntimeImport();
        const source_type = try self.exprType(receiver_node) orelse
            return error.MissingExpressionType;
        const borrowed = switch (source_type) {
            .reference => true,
            else => false,
        };
        const is_str = ir.types.isStr(cow.args[0]);
        const generic_args: []const ast.Type = if (is_str) &.{} else blk: {
            const borrowed_slice = switch (cow.args[0]) {
                .slice => |value| value,
                else => return error.UnsupportedExternalNominalType,
            };
            const params = try self.alloc.alloc(ast.Type, 1);
            params[0] = try self.lowerType(borrowed_slice.elem);
            break :blk params;
        };
        const cow_type = try self.runtimeCowType(is_str, generic_args);
        const call_args = try self.alloc.alloc(ast.Expr, 1);
        call_args[0] = if (borrowed)
            receiver.*
        else
            try self.lowerOwnedReceiverPointer(receiver_node, receiver);
        return (try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(cow_type),
                .field_name = if (borrowed) "from_borrowed" else "from_owned",
            } }),
            .args = call_args,
        } })).*;
    }

    /// The receiver's own type, with the indirections that do not change which
    /// Rust carrier it names stripped: what decides which runtime shape the
    /// VALUE has. A `&Cow<str>` and a `Cow<str>` name the same runtime type,
    /// so both answer `CowStr` here.
    fn receiverValueType(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!?ir.types.Type {
        return peelReceiverType(try self.exprType(receiver_node) orelse return null);
    }

    /// Whether a receiver is one of the runtime `Cow` types.
    ///
    /// A cow is the one clone receiver whose copy constructor cannot be the
    /// receiver itself: its `Owned` arm owns storage, so copying the union
    /// would leave two owners releasing the same bytes.
    fn isCowReceiver(self: *Lowerer, receiver_node: ir.exprs.NodeId) anyerror!bool {
        const owned = (try self.receiverValueType(receiver_node)) orelse return false;
        return switch (owned) {
            .external_nominal => |external| external.args.len == 1 and isCowPath(external.path),
            else => false,
        };
    }

    /// The element type a `Vec<T>` receiver names, or null when the receiver
    /// is not a vector.
    fn vecElementOfReceiver(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!?ir.types.Type {
        const owned = (try self.receiverValueType(receiver_node)) orelse return null;
        const element = try vecElementOfContext(owned);
        return element;
    }

    /// The pointer a runtime helper needs in order to read, consume or grow the
    /// caller's OWN storage rather than a copy of it.
    ///
    /// A place — a binding, a field, an index, a dereference — has an address
    /// already, so it is handed over directly and the helper empties or grows
    /// exactly the storage the caller declared. An rvalue, which is what a
    /// conversion receiver usually is (`String::from_utf8(bytes).into()`), has
    /// no place at all and Zig cannot take the address of a temporary, so it is
    /// materialized exactly once into a local — what a Rust `let` binding
    /// would have done — and the helper reads that.
    ///
    /// Nothing is copied a second time and nothing is freed twice: the value is
    /// evaluated once into the local, and every helper this feeds either empties
    /// the local it was handed (`from_owned` transfers the allocation and
    /// leaves an empty owner behind) or grows the very vector the local owns.
    /// Either way the local is left holding no storage of its own, so there is
    /// nothing for a later release to free a second time.
    fn lowerOwnedReceiverPointer(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
    ) anyerror!ast.Expr {
        if (exprIsAddressable(receiver.*)) {
            return (try self.allocExpr(.{ .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(receiver.*),
            } })).*;
        }
        const name = try std.fmt.allocPrint(
            self.alloc,
            "__r2z_owned_receiver_{d}",
            .{receiver_node},
        );
        const statements = try self.alloc.alloc(ast.Stmt, 1);
        statements[0] = .{ .let_stmt = .{
            .name = name,
            .ty = null,
            .init = (try self.allocExpr(receiver.*)).*,
            .is_mut = true,
        } };
        return (try self.allocExpr(.{ .block = .{
            .label = null,
            .stmts = statements,
            .expr = try self.allocExpr(.{ .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(.{ .ident = name }),
            } }),
        } })).*;
    }

    /// Capture a destination handle before evaluating the transferred item.
    /// The runtime owns the item on both append success and allocation failure.
    /// A temporary vector remains in this scope until its final cleanup.
    fn lowerOwnedVecPush(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        element_type: ir.types.Type,
        item: ast.Expr,
    ) anyerror!*const ast.Expr {
        const name = try self.iteratorTemporaryName("__r2z_push_destination");
        const borrowed = (try self.borrowedReceiverPointee(receiver_node)) != null;
        const temporary = !borrowed and !exprIsAddressable(receiver.*);
        const statements = try self.alloc.alloc(ast.Stmt, if (temporary) 2 else 1);
        statements[0] = .{ .let_stmt = .{
            .name = name,
            .init = if (borrowed or temporary) receiver.* else .{ .unary_op = .{
                .op = .addr_of,
                .operand = receiver,
            } },
            .is_mut = temporary,
        } };
        if (temporary) statements[1] = try self.ownerReleaseStatement(
            name,
            vecElementMayOwnRuntimeStorage(element_type),
        );
        const arguments = try self.alloc.alloc(ast.Expr, 3);
        arguments[0] = .{ .ident = "allocator" };
        arguments[1] = if (temporary) .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(.{ .ident = name }),
        } } else .{ .ident = name };
        arguments[2] = item;
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(element_type);
        return self.allocExpr(.{ .block = .{
            .stmts = statements,
            .expr = try self.allocExpr(.{ .unary_op = .{
                .op = .try_op,
                .operand = try self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_push_owned" }),
                    .generic_args = generic_args,
                    .args = arguments,
                } }),
            } }),
        } });
    }

    /// The `*String` a growing helper reads and appends through.
    ///
    /// Rust borrows the receiver mutably, so the helper needs the address of
    /// the owned string whether or not the call site wrote the borrow:
    /// `s.push(c)` on an owned `s` and `text.push(c)` on a `&mut String`
    /// binding are the same call. The second already holds that pointer and
    /// is handed on as it stands; the first is a place, and handing the
    /// place itself on would pass a copy of the descriptor — the appended
    /// bytes would land in that copy and the caller's string would be
    /// unchanged.
    fn lowerStringReceiverPointer(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
    ) anyerror!ast.Expr {
        const receiver_type = try self.exprType(receiver_node) orelse
            return self.lowerOwnedReceiverPointer(receiver_node, receiver);
        return switch (receiver_type) {
            .reference, .raw_ptr => receiver.*,
            else => try self.lowerOwnedReceiverPointer(receiver_node, receiver),
        };
    }

    fn lowerBoundConversion(
        self: *Lowerer,
        expression: ir.exprs.NodeId,
        method: ir.spine.Entity,
        receiver: *const ast.Expr,
        receiver_node: ir.exprs.NodeId,
    ) !?ast.Expr {
        const fallible = std.mem.eql(u8, method.name, "try_into");
        if (!fallible and !std.mem.eql(u8, method.name, "into")) return null;
        if (method.kind != .method_ref) return null;
        const result = try self.exprType(expression) orelse return error.MissingExpressionType;
        const target = if (fallible) switch (result) {
            .result => |value| value.ok,
            .external_nominal => |external| if (external.args.len == 2 and
                (externalPathEqual(external.path, &.{ "core", "result", "Result" }) or
                    externalPathEqual(external.path, &.{ "std", "result", "Result" })))
                external.args[0]
            else
                return error.UnsupportedStandardMethod,
            else => return error.UnsupportedStandardMethod,
        } else result;
        // `Cow<..>` is a borrow-or-own pair, and the `From` impls a crate
        // writes for it are exactly its two constructors: borrowing copies
        // nothing and owns nothing, while moving hands the allocation over and
        // leaves the source empty. Nothing generic can express that, so it is
        // spelled here rather than routed through `r2z.convert.from` — the
        // runtime cow publishes no `from` for it to find.
        if (cowConversionNominal(target)) |cow| {
            const converted = try self.lowerCowConversion(cow, receiver_node, receiver);
            return converted;
        }
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(target);
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = receiver.*;
        try self.markRuntimeImport();
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = if (fallible) "r2z.convert.try_from" else "r2z.convert.from" }),
            .generic_args = generic_args,
            .args = args,
        } };
    }

    /// Lower a prelude method call to native Zig or an explicit unsupported
    /// node. Returns null only for an ordinary method that the resolver did
    /// not classify as a standard-library method.
    fn lowerStdMethodCall(
        self: *Lowerer,
        method_name: []const u8,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        argument_nodes: []const ir.exprs.NodeId,
        turbofish: []const ir.types.Type,
    ) anyerror!?*const ast.Expr {
        const recognized_std_method = try self.lookupRecognizedStdMethod(receiver_node, method_name);
        const is_option_as_ref = if (recognized_std_method) |method|
            method == .option_as_ref
        else
            false;
        const is_result_as_ref = if (recognized_std_method) |method|
            method == .result_as_ref
        else
            false;
        if (std.mem.eql(u8, method_name, "to_digit")) {
            const receiver_type = try self.exprType(receiver_node);
            const is_char_receiver = if (receiver_type) |ty| switch (ty) {
                .prim => |primitive| primitive == .char,
                else => false,
            } else false;
            if (is_char_receiver) {
                if (args.len != 1) return self.lowerUnsupportedStdMethod(method_name);
                try self.markRuntimeImport();
                const call_args = try self.alloc.alloc(ast.Expr, args.len + 1);
                call_args[0] = receiver.*;
                @memcpy(call_args[1..], args);
                const callee = try self.allocExpr(.{
                    .ident = try self.alloc.dupe(u8, "r2z.character.to_digit"),
                });
                return self.allocExpr(.{ .call = .{
                    .callee = callee,
                    .args = call_args,
                } });
            }
        }
        if (std.mem.eql(u8, method_name, "as_bytes")) {
            // `String::as_bytes` hands back a borrow of the string's own
            // bytes, and the identity `lowerAsRef` returns is the string
            // itself. A `&[u8]` method reached through it then reads a field
            // the runtime `String` does not have, so the view has to be
            // asked for by name.
            const receiver_type = try self.exprType(receiver_node);
            if (receiver_type != null and ownedStringType(receiver_type.?) != null) {
                try self.markRuntimeImport();
                return self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .field_access = .{
                        .target = receiver,
                        .field_name = try self.alloc.dupe(u8, "as_bytes"),
                    } }),
                    .args = &.{},
                } });
            }
        }
        // A `Cow` is excluded from the `as_bytes` half of this group: its bytes
        // are a borrow of whichever arm it holds, not the identity
        // `lowerAsRef` would hand back, so the cow's own accessor answers it
        // further down.
        // A cursor's `as_slice` is the sequence still in it, not a borrow of
        // the cursor: `self.bytes.as_slice()` on a `slice::Iter` reads out the
        // bytes between its front and back indices. `lowerAsRef` would answer
        // the receiver itself — the cursor — which is a different value of a
        // different type, and the runtime publishes the real accessor.
        if (std.mem.eql(u8, method_name, "as_slice")) {
            if (try self.receiverValueType(receiver_node)) |cursor_type| {
                if (isCursorCarrierWithAsSlice(peelReceiverType(cursor_type))) {
                    return self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = receiver,
                            .field_name = try self.alloc.dupe(u8, "as_slice"),
                        } }),
                        .args = &.{},
                    } });
                }
            }
        }
        if ((std.mem.eql(u8, method_name, "as_ref") and
            !is_option_as_ref and !is_result_as_ref) or
            (std.mem.eql(u8, method_name, "as_bytes") and
                !try self.isCowReceiver(receiver_node)) or
            std.mem.eql(u8, method_name, "borrow") or
            std.mem.eql(u8, method_name, "as_slice"))
        {
            const result = try self.lowerAsRef(receiver_node, receiver);
            return result;
        }
        // The RECOGNIZED method decides, not the spelling: `Clone::clone` and a
        // `Cow`'s `to_owned` are the same operation and both answer `.clone`.
        if (recognized_std_method == .clone) {
            // A `Clone` receiver whose copy constructor is the value itself
            // stands in for the result. A `Cow` is the one receiver that
            // cannot: its `Owned` arm owns storage, so a copy of the union
            // would leave two owners releasing the same bytes. The runtime
            // publishes the deep copy the source's `Clone` bound asks for —
            // a borrowed arm stays borrowed, an owned arm is copied into
            // fresh storage — and that copy allocates, so the allocator
            // leads its argument list and the enclosing callable declares one.
            if (try self.isCowReceiver(receiver_node)) {
                try self.markRuntimeImport();
                self.current_callable_is_allocating = true;
                const clone_args = try self.alloc.alloc(ast.Expr, 1);
                clone_args[0] = .{ .ident = "allocator" };
                const cloned = try self.allocExpr(.{ .unary_op = .{
                    .op = .try_op,
                    .operand = try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = try self.allocExpr(receiver.*),
                            .field_name = "clone",
                        } }),
                        .args = clone_args,
                    } }),
                } });
                return cloned;
            }
            // A borrow of a cursor is not the cursor: `iter.clone()` on a
            // `&mut slice::Iter` is `(*iter).clone()`, a second cursor over the
            // same bytes that the source then writes back with `*iter =
            // cloned`. Standing in for the result with the receiver would
            // assign the caller's own cursor to a binding of the same type and
            // leave `iter` already advanced, so the body would read from
            // storage the source never copied. The runtime publishes the copy
            // for exactly these carriers, so it is spelled; a receiver that
            // already IS the value keeps the identity that is right for it,
            // and one with no runtime `clone` is left as it was.
            const cloned_receiver = try self.lowerMemoryReceiver(receiver_node, receiver);
            const pointee = (try self.borrowedReceiverPointee(receiver_node)) orelse
                return cloned_receiver;
            if (!runtimeCarrierCopiesByClone(peelReceiverType(pointee))) {
                return cloned_receiver;
            }
            const cloned = try self.allocExpr(.{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(cloned_receiver.*),
                    .field_name = "clone",
                } }),
                .args = &.{},
            } });
            return cloned;
        }
        if (recognized_std_method == .slice_len) {
            const storage = if (needsContainerStorageProjection(try self.exprType(receiver_node)))
                try self.allocExpr(ast.Expr{ .field_access = .{
                    .target = receiver,
                    .field_name = "items",
                } })
            else
                receiver;
            const result = try self.allocExpr(ast.Expr{
                .field_access = .{
                    .target = storage,
                    .field_name = "len",
                },
            });
            return result;
        }
        if (recognized_std_method == .slice_is_empty) {
            if (args.len != 0) return null;
            const len = try self.allocExpr(ast.Expr{
                .field_access = .{
                    .target = receiver,
                    .field_name = try self.alloc.dupe(u8, "len"),
                },
            });
            const zero = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
            const result = try self.allocExpr(ast.Expr{
                .bin_op = .{ .op = .equal, .lhs = len, .rhs = zero },
            });
            return result;
        }
        if (recognized_std_method) |std_method| {
            switch (std_method) {
                .option_unwrap, .option_unwrap_or, .option_as_ref, .option_map, .option_and_then => {
                    const expected_args: usize = switch (std_method) {
                        .option_unwrap, .option_as_ref => 0,
                        else => 1,
                    };
                    if (args.len != expected_args) return error.UnsupportedStandardMethod;
                    const value = if (std_method == .option_as_ref) borrow: {
                        if (try self.receiverIsPointerLike(receiver_node)) break :borrow receiver;
                        break :borrow try self.allocExpr(.{ .unary_op = .{ .op = .addr_of, .operand = receiver } });
                    } else try self.lowerMemoryReceiver(receiver_node, receiver);
                    const call_args = try self.alloc.alloc(ast.Expr, args.len + 1);
                    call_args[0] = value.*;
                    @memcpy(call_args[1..], args);
                    try self.markRuntimeImport();
                    return try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = try std.fmt.allocPrint(self.alloc, "r2z.option.{s}", .{method_name}) }),
                        .args = call_args,
                    } });
                },
                .byte_is_ascii => {
                    if (args.len != 0) return error.UnsupportedStandardMethod;
                    return try self.allocExpr(.{ .bin_op = .{
                        .op = .less_than_equal,
                        .lhs = try self.lowerMemoryReceiver(receiver_node, receiver),
                        .rhs = try self.allocExpr(.{ .lit = .{ .int = 127 } }),
                    } });
                },
                .borrowed_to_owned => {
                    if (args.len != 0) return try self.lowerUnsupportedStdMethod(method_name);
                    try self.markRuntimeImport();
                    // The copy is owned storage, so the allocator leads the
                    // argument list and its presence makes the enclosing
                    // callable declare one. The bytes are COPIED, so the
                    // result outlives the borrow it came from.
                    self.current_callable_is_allocating = true;
                    const call_args = try self.alloc.alloc(ast.Expr, 2);
                    call_args[0] = .{ .ident = "allocator" };
                    call_args[1] = (try self.lowerMemoryReceiver(receiver_node, receiver)).*;
                    const receiver_type = try self.exprType(receiver_node) orelse
                        return error.MissingExpressionType;
                    // `str` and `&str` are the same text; only the borrow is
                    // spelled differently in the IR. A `&[u8]` is a different
                    // type that shares the Zig ABI, so the decision is the
                    // Rust type and never the lowered one.
                    const call = if (canonicalBorrowedStr(receiver_type))
                        try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.String.from_str" }),
                            .args = call_args,
                        } })
                    else blk_vec: {
                        const element = try self.memoryElementType(receiver_node) orelse
                            return try self.lowerUnsupportedStdMethod(method_name);
                        const generic_args = try self.alloc.alloc(ast.Type, 1);
                        generic_args[0] = try self.lowerType(element);
                        break :blk_vec try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_from_slice" }),
                            .generic_args = generic_args,
                            .args = call_args,
                        } });
                    };
                    return try self.allocExpr(.{ .unary_op = .{
                        .op = .try_op,
                        .operand = call,
                    } });
                },
                .cow_as_bytes => {
                    if (args.len != 0) return try self.lowerUnsupportedStdMethod(method_name);
                    // The cow already holds the borrowed bytes; reading them
                    // is reading whichever arm it is holding, which is what
                    // the runtime's own accessor does.
                    return try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = receiver,
                            .field_name = "as_ref",
                        } }),
                        .args = &.{},
                    } });
                },
                .cow_to_owned => {
                    if (args.len != 0) return try self.lowerUnsupportedStdMethod(method_name);
                    try self.markRuntimeImport();
                    self.current_callable_is_allocating = true;
                    const call_args = try self.alloc.alloc(ast.Expr, 1);
                    call_args[0] = .{ .ident = "allocator" };
                    return try self.allocExpr(.{ .unary_op = .{
                        .op = .try_op,
                        .operand = try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{ .field_access = .{
                                .target = try self.allocExpr(receiver.*),
                                .field_name = "into_owned",
                            } }),
                            .args = call_args,
                        } }),
                    } });
                },
                .string_push, .string_push_str => {
                    if (args.len != 1) return try self.lowerUnsupportedStdMethod(method_name);
                    try self.markRuntimeImport();
                    // Growing the string may reallocate its buffer, so the
                    // call declares the enclosing allocator exactly as the
                    // vector's own append does.
                    self.current_callable_is_allocating = true;
                    // The runtime reads and grows the string through a
                    // `*String`. A receiver the source already reached
                    // through `&mut String` IS that pointer and is handed on
                    // as it stands; a bare place is given its address, so the
                    // growth lands in the caller's own string rather than in
                    // a copy of its descriptor.
                    const call_args = try self.alloc.alloc(ast.Expr, 3);
                    call_args[0] = try self.lowerStringReceiverPointer(receiver_node, receiver);
                    call_args[1] = .{ .ident = "allocator" };
                    call_args[2] = args[0];
                    return try self.allocExpr(.{ .unary_op = .{
                        .op = .try_op,
                        .operand = try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{ .ident = if (std_method == .string_push)
                                "r2z.alloc.String.push"
                            else
                                "r2z.alloc.String.push_str" }),
                            .args = call_args,
                        } }),
                    } });
                },
                .vec_push, .vec_extend => {
                    if (args.len != 1) return try self.lowerUnsupportedStdMethod(method_name);
                    try self.markRuntimeImport();
                    self.current_callable_is_allocating = true;
                    if (std_method == .vec_extend) {
                        // Rust's `extend` takes any `IntoIterator`, and the
                        // runtime helper is the one call that covers both
                        // shapes: a sequence is copied in whole, and an
                        // iterator is drained item by item straight into the
                        // caller's own vector, with no intermediate container
                        // and no prefix rewrite. Deciding here would be a
                        // second, weaker copy of that rule, and refusing
                        // anything the helper accepts would drop calls the
                        // source compiles.
                        //
                        // The vector's own element type is what the helper
                        // checks each drained item against, so it is named as
                        // the generic argument.
                        const element = (try self.vecElementOfReceiver(receiver_node)) orelse
                            return try self.lowerUnsupportedStdMethod(method_name);
                        const generic_args = try self.alloc.alloc(ast.Type, 1);
                        generic_args[0] = try self.lowerType(element);
                        const extend_args = try self.alloc.alloc(ast.Expr, 3);
                        extend_args[0] = .{ .ident = "allocator" };
                        extend_args[1] = try self.lowerOwnedReceiverPointer(receiver_node, receiver);
                        extend_args[2] = args[0];
                        return try self.allocExpr(.{ .unary_op = .{
                            .op = .try_op,
                            .operand = try self.allocExpr(.{ .call = .{
                                .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_extend" }),
                                .generic_args = generic_args,
                                .args = extend_args,
                            } }),
                        } });
                    }
                    const element = (try self.vecElementOfReceiver(receiver_node)) orelse
                        return try self.lowerUnsupportedStdMethod(method_name);
                    if (vecElementMayOwnRuntimeStorage(element))
                        return self.lowerOwnedVecPush(receiver_node, receiver, element, args[0]);
                    const call_args = try self.alloc.alloc(ast.Expr, 2);
                    call_args[0] = .{ .ident = "allocator" };
                    call_args[1] = args[0];
                    return try self.allocExpr(.{ .unary_op = .{
                        .op = .try_op,
                        .operand = try self.allocExpr(.{ .call = .{
                            .callee = try self.allocExpr(.{ .field_access = .{
                                .target = try self.allocExpr(receiver.*),
                                .field_name = "append",
                            } }),
                            .args = call_args,
                        } }),
                    } });
                },
                .utf8_error => {
                    if (args.len != 0) return try self.lowerUnsupportedStdMethod(method_name);
                    // The error ALREADY carries the character-level failure:
                    // the wrapper exists to name where a string conversion gave
                    // up, not to hold a second, different one. What the source's
                    // `Err` arm binds is that failure, not the wrapper, so the
                    // runtime's own accessor is what reads it out — it takes
                    // `self: *const` and no allocator, because reading the
                    // detail allocates nothing and the wrapper keeps the bytes
                    // it came with for the arm to release. Forwarding the
                    // receiver here would hand back the wrapper itself, which is
                    // a different type than the `Utf8Error` the source expects.
                    return try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = receiver,
                            .field_name = try self.alloc.dupe(u8, "utf8_error"),
                        } }),
                        .args = &.{},
                    } });
                },
                .utf8_error_valid_up_to => {
                    if (args.len != 0) return try self.lowerUnsupportedStdMethod(method_name);
                    // The runtime's `Utf8Error` is a plain struct and
                    // `valid_up_to` is a field of it, so the whole accessor
                    // lowers to a field read on the receiver Rust borrowed.
                    // There is no `takeOwned` here and there must not be one:
                    // this is a `&self` read of a failure that retains the
                    // bytes it came with, so emptying the receiver would free
                    // storage the surrounding arm still owes a release for.
                    // The arm that produced the receiver already typed it —
                    // `core::str::Utf8Error` lowered to
                    // `r2z.character.Utf8Error` — so the field is spelled
                    // against that runtime type and nothing else.
                    return try self.allocExpr(.{ .field_access = .{
                        .target = receiver,
                        .field_name = try self.alloc.dupe(u8, "valid_up_to"),
                    } });
                },
                .format_write_str => {
                    if (args.len != 1) return error.UnsupportedStandardMethod;
                    return try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{ .target = receiver, .field_name = "writeAll" } }),
                        .args = args,
                    } });
                },
                .slice_first => {
                    if (args.len != 0) return error.UnsupportedStandardMethod;
                    const value = try self.lowerMemoryReceiver(receiver_node, receiver);
                    const slice_value = try self.lowerAsRef(receiver_node, value);
                    const element = try self.memoryElementType(receiver_node) orelse
                        return error.UnsupportedStandardMethod;
                    // A receiver that is already a plain binding IS the slice
                    // the borrow is taken from, and it outlives this call: it
                    // belongs to the caller the parameter was passed by.
                    // Binding it would COPY it, and that copy is exactly the
                    // temporary the returned pointer must not name — so both
                    // arms below read the binding itself. A FIELD is the other
                    // case: it is a place behind the receiver, and one binding
                    // is what keeps both arms reading that field's storage
                    // instead of deriving a second value from it. Anything
                    // with no place at all — a call result — is bound so it is
                    // evaluated exactly once, as `exprIsAddressable` requires
                    // everywhere else a receiver that is read twice is.
                    var stmts: []const ast.Stmt = &.{};
