                .num_rotate_left,
                .num_rotate_right,
                .num_to_le,
                .num_to_be,
                .num_swap_bytes,
                .num_checked_add,
                .num_checked_sub,
                .num_checked_mul,
                => return try self.lowerIntegerStdMethod(std_method, receiver_node, receiver, args, argument_nodes),
