            // operator form does, by value or behind a pointer alike.
            const rhs = if ((bk == .shl or bk == .shr) and
                !isFloatType(receiver_ty) and
                !requiresRuntimeOperator(receiver_ty))
                try self.allocExpr(try self.lowerShiftAmount(args[0]))
