            else
                false;
            const num_receiver = if (is_pointer_receiver)
                try self.allocExpr(ast.Expr{ .unary_op = .{ .op = .deref, .operand = receiver } })
            else
                receiver;
            const result = try self.allocExpr(ast.Expr{
                .unary_op = .{ .op = .negate, .operand = num_receiver },
            });
            return result;
        }
        if (std.mem.eql(u8, method_name, "not")) {
            const is_pointer_receiver = if (try self.exprType(receiver_node)) |ty|
                ty == .reference or ty == .raw_ptr
            else
                false;
            const num_receiver = if (is_pointer_receiver)
                try self.allocExpr(ast.Expr{ .unary_op = .{ .op = .deref, .operand = receiver } })
            else
                receiver;
            const result = try self.allocExpr(ast.Expr{
                .unary_op = .{ .op = .bit_not, .operand = num_receiver },
            });
            return result;
        }
        if (recognized_std_method != null) {
            const result = try self.lowerUnsupportedStdMethod(method_name);
            return result;
        }
        return null;
    }

    fn hoistOwnedAssertionOperand(
        self: *Lowerer,
        operand: *const ast.Expr,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
    ) !*const ast.Expr {
        if (operand.* != .block) return operand;
        const block = operand.block;
        // The operand is hoisted out only when it IS an owner prelude, which
        // is an identity question and not a shape one: an ordinary Rust block
        // that declares an owner and drops it at the end of its own scope is
        // spelled `let` then `defer` too, and lifting ITS statements into the
        // assertion would move that release out of the scope that owns it.
        if (block.expr == null or !self.isOwnerPrelude(block.stmts)) return operand;
        for (block.stmts) |stmt| {
            try prelude.append(self.alloc, stmt);
        }
        return block.expr.?;
    }

    fn hoistOwnedAssertionCondition(
        self: *Lowerer,
        condition: ast.Expr,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
    ) !ast.Expr {
        return switch (condition) {
            .bin_op => |binary| .{ .bin_op = .{
                .op = binary.op,
                .lhs = try self.hoistOwnedAssertionOperand(binary.lhs, prelude),
                .rhs = if (binary.op == .bool_and or binary.op == .bool_or)
                    binary.rhs
                else
                    try self.hoistOwnedAssertionOperand(binary.rhs, prelude),
            } },
            else => condition,
        };
    }

    /// Lower an assertion marker emitted by the frontend macro pass. The
    /// marker stores the condition node id as `assertion:<id>` so the
    /// condition remains a normal IR expression while the assertion call is
    /// represented in the target AST.
    fn lowerAssertionMarker(self: *Lowerer, reason: []const u8) anyerror!ast.Expr {
        if (!std.mem.startsWith(u8, reason, "assertion:")) {
            return error.MalformedAssertionMarker;
        }
        const suffix = reason["assertion:".len..];
        if (suffix.len == 0 or std.mem.eql(u8, suffix, "none")) {
            return error.MalformedAssertionMarker;
        }
        const condition_id = std.fmt.parseInt(u32, suffix, 10) catch {
            return error.MalformedAssertionMarker;
        };
        if (condition_id >= self.ir.bodies.exprs.len) {
            return error.MissingAssertionCondition;
        }

        var assertion_prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer assertion_prelude.deinit(self.alloc);
        const lowered_condition = try self.lowerExpr(@intCast(condition_id));
        const condition = try self.hoistOwnedAssertionCondition(
            lowered_condition,
            &assertion_prelude,
        );

        var args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = condition;
        const assertion = if (self.lowering_test_entity) blk: {
            const std_target = try self.allocExpr(.{ .ident = "std" });
            const testing_target = try self.allocExpr(.{ .field_access = .{
                .target = std_target,
                .field_name = "testing",
            } });
            const expect_target = try self.allocExpr(.{ .field_access = .{
                .target = testing_target,
                .field_name = "expect",
            } });
            const expect_call = try self.allocExpr(.{ .call = .{
                .callee = expect_target,
                .args = args,
            } });
            break :blk ast.Expr{ .unary_op = .{
                .op = .try_op,
                .operand = expect_call,
            } };
        } else ast.Expr{
            .call = .{
                .callee = try self.allocExpr(.{
                    .ident = try self.alloc.dupe(u8, "std.debug.assert"),
                }),
                .args = args,
            },
        };
        if (assertion_prelude.items.len == 0) return assertion;
        const statements = try assertion_prelude.toOwnedSlice(self.alloc);
        return .{ .block = .{
            .stmts = statements,
            .expr = try self.allocExpr(assertion),
        } };
    }

    fn isAssertionReason(reason: []const u8) bool {
        if (std.mem.startsWith(u8, reason, "assertion:")) return true;
        return std.mem.eql(u8, reason, "macro debug_assert") or
            std.mem.eql(u8, reason, "macro debug_assert_eq") or
            std.mem.eql(u8, reason, "macro debug_assert_ne");
    }

    fn isScalarCastType(ty: ir.types.Type) bool {
        return switch (ty) {
            .prim => |primitive| switch (primitive) {
                .i8, .i16, .i32, .i64, .i128, .u8, .u16, .u32, .u64, .u128, .isize, .usize, .f32, .f64, .char => true,
                .bool, .unit, .never => false,
            },
            else => false,
        };
    }

    /// Whether `ty` may be the SOURCE of a scalar `as` conversion.
    ///
    /// The same rule `ir.validate.isValidCastType` states for a scalar
    /// destination: any scalar, and a `bool` as well. `true as usize` is
    /// ordinary Rust and the validator admits it, so refusing it here made the
    /// backend narrower than the IR it is handed. `bool` is deliberately not a
    /// legal DESTINATION there, so this widens the source side only.
    fn isScalarCastSource(ty: ir.types.Type) bool {
        if (isScalarCastType(ty)) return true;
        return ty == .prim and ty.prim == .bool;
    }

    /// A raw-pointer cast reinterprets one address under a different pointee;
    /// it never allocates or narrows. `lowerType` spells a thin raw pointer
    /// `[*]allowzero align(1) T`, so neither side can raise alignment and
    /// `@ptrCast` stays legal at any pointee width — a `u32` chunk read from a
    /// `u8` byte cursor, or a `u8` slice read as the generic `T`, are both
    /// well-formed.
    ///
    /// The one combination Zig refuses is a change of pointer *width*: a
    /// pointer to an unsized type is fat, and a thin pointer cannot
    /// `@ptrCast` into one.
    fn pointerPointeeIsSized(self: *Lowerer, ty: ir.types.Type) bool {
        const pointee = self.hashPayloadPointee(ty);
        return pointee != .dyn_trait and hashResolvedFatElement(pointee) == null;
    }

    fn pointerPointeesCompatible(self: *Lowerer, source: ir.types.Type, target: ir.types.Type) bool {
        return self.pointerPointeeIsSized(source) and self.pointerPointeeIsSized(target);
    }

    /// Element borrowed by a str/slice view, including non-generic aliases.
    fn fatBorrowElement(self: *Lowerer, ty: ir.types.Type) ?ir.types.Type {
        return switch (ty) {
            .slice => |slice| slice.elem,
            .reference => |reference| self.hashFatPointeeElement(reference.pointee),
            .raw_ptr => |pointer| self.hashFatPointeeElement(pointer.pointee),
            else => null,
        };
    }

    /// Whether `target` can stand for `source` in a fat-borrow cast.
    ///
    /// The rule, as the frontend and the validator state it: the element types
    /// have to be the same, and a shared borrow cannot become a mutable
    /// pointer. That the destination is fat at all is settled by the caller,
    /// which only offers a `.raw_ptr` holding a slice or str.
    fn fatBorrowCastCompatible(
        source_elem: ir.types.Type,
        source_const: bool,
        target_elem: ir.types.Type,
        target_mut: bool,
    ) bool {
        if (target_mut and source_const) return false;
        return sameIrType(source_elem, target_elem);
    }

    /// Whether a fat borrow of this type lowers to a `[]const` rather than a
    /// `[]`.
    fn fatBorrowIsShared(ty: ir.types.Type) bool {
        return switch (ty) {
            .slice => |slice| slice.const_,
            .reference => |reference| !reference.mut,
            .raw_ptr => |pointer| !pointer.mut,
            else => true,
        };
    }

    /// The cast that re-labels one fat borrow as another.
    ///
    /// Both sides lower to a slice, so nothing is thinned to a bare address and
    /// nothing is dropped: `@constCast` for the one direction a shared borrow
    /// may go, then `@ptrCast` between two slices of the same element.
    fn fatBorrowCast(
        self: *Lowerer,
        source_ir: ir.types.Type,
        target_ir: ir.types.Type,
        operand: ir.exprs.NodeId,
    ) anyerror!ast.Expr {
        const target = try self.lowerType(target_ir);
        const source = try self.lowerType(source_ir);
        var cast_operand = try self.allocExpr(try self.lowerExpr(operand));
        if (fatBorrowIsShared(source_ir) and !fatBorrowIsShared(target_ir)) {
            const const_cast_args = try self.alloc.alloc(ast.Expr, 1);
            const_cast_args[0] = cast_operand.*;
            cast_operand = try self.allocExpr(.{ .builtin = .{
                .name = "constCast",
                .args = const_cast_args,
            } });
        }
        const ptr_cast_args = try self.alloc.alloc(ast.Expr, 1);
        ptr_cast_args[0] = cast_operand.*;
        const pointer_cast = try self.allocExpr(.{ .builtin = .{
            .name = "ptrCast",
            .args = ptr_cast_args,
        } });
        return .{ .cast = .{
            .target = target,
            .operand = pointer_cast,
            .source = source,
        } };
    }

    /// The width a `From` conversion is measured against. `.char` carries the
    /// same 32 `ir.validate.unsignedPrimitiveWidth` and `infer`'s own table give
    /// it, and it has to: `char::from(byte)` is an ordinary `From` conversion
    /// the frontend lowers to a `primitive_from` cast and already accepts, so a
    /// backend that gave `char` no width would refuse a cast the frontend had
    /// decided was well formed — and `u8` to `char` is valid Rust.
    fn unsignedPrimitiveWidth(primitive: ir.types.Prim) ?u16 {
        return switch (primitive) {
            .u8 => 8,
            .u16 => 16,
            .u32 => 32,
            .u64 => 64,
            .u128 => 128,
            .usize => 64,
            .char => 32,
            else => null,
        };
    }

    fn isValidPrimitiveFrom(source: ir.types.Type, target: ir.types.Type) bool {
        const source_primitive = switch (source) {
            .prim => |primitive| primitive,
            else => return false,
        };
        const target_primitive = switch (target) {
            .prim => |primitive| primitive,
            else => return false,
        };
        const source_width = unsignedPrimitiveWidth(source_primitive) orelse return false;
        const target_width = unsignedPrimitiveWidth(target_primitive) orelse return false;
        return source_width <= target_width;
    }

    fn scalarPrimitive(ty: ir.types.Type) ?ir.types.Prim {
        return switch (ty) {
            .prim => |primitive| primitive,
            else => null,
        };
    }

    fn integerWidth(primitive: ir.types.Prim) ?u16 {
        return switch (primitive) {
            .i8, .u8 => 8,
            .i16, .u16 => 16,
            .i32, .u32 => 32,
            .i64, .u64, .isize, .usize => 64,
            .i128, .u128 => 128,
            .char => 21,
            .f32, .f64, .bool, .unit, .never => null,
        };
    }

    fn isFloatPrimitive(primitive: ir.types.Prim) bool {
        return primitive == .f32 or primitive == .f64;
    }

    fn isSignedPrimitive(primitive: ir.types.Prim) bool {
        return switch (primitive) {
            .i8, .i16, .i32, .i64, .i128, .isize => true,
            else => false,
        };
    }

    fn signedCounterpart(primitive: ir.types.Prim) ?ir.types.Prim {
        return switch (primitive) {
            .u8 => .i8,
            .u16 => .i16,
            .u32 => .i32,
            .u64 => .i64,
            .u128 => .i128,
            .usize => .isize,
            else => null,
        };
    }

    fn unsignedCounterpart(primitive: ir.types.Prim) ?ir.types.Prim {
        return switch (primitive) {
            .i8 => .u8,
            .i16 => .u16,
            .i32 => .u32,
            .i64 => .u64,
            .i128 => .u128,
            .isize => .usize,
            else => null,
        };
    }

    fn scalarBuiltin(self: *Lowerer, name: []const u8, operand: ast.Expr) !ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = operand;
        return .{ .builtin = .{ .name = name, .args = args } };
    }

    fn scalarCast(
        self: *Lowerer,
        source_type: ir.types.Type,
        target_type: ir.types.Type,
        operand: ast.Expr,
    ) !ast.Expr {
        const source = scalarPrimitive(source_type) orelse return error.UnsupportedExpression;
        const target = scalarPrimitive(target_type) orelse return error.UnsupportedExpression;
        const target_ast = try self.lowerType(target_type);

        // `true as usize` is 1 and `false as usize` is 0, which is exactly
        // `@intFromBool`; the cast that follows widens its `u1` to the
        // destination. There is no boolean-to-FLOAT conversion in Rust, so a
        // float destination is a conversion the source never wrote and is
        // refused rather than approximated: Zig has no `@floatFromBool` to
        // name it with, and inventing one would emit a builtin that does not
        // exist. The destination is never `bool` either, since `ir.validate`
        // does not admit one, so this cannot become a bool-to-bool cast. It
        // comes before the integer-width and signedness arms below, which have
        // no width for a boolean.
        if (source == .bool) {
            if (isFloatPrimitive(target)) return error.UnsupportedExpression;
            const converted = try self.scalarBuiltin("intFromBool", operand);
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(converted),
            } };
        }

        if (isFloatPrimitive(source)) {
            if (isFloatPrimitive(target)) {
                const converted = if (source == target)
                    operand
                else
                    try self.scalarBuiltin("floatCast", operand);
                return .{ .cast = .{
                    .target = target_ast,
                    .operand = try self.allocExpr(converted),
                } };
            }
            const target_width = integerWidth(target) orelse return error.UnsupportedExpression;
            if (target_width >= 128) return error.UnsupportedExpression;
            const max_integer: i128 = if (isSignedPrimitive(target))
                (@as(i128, 1) << @intCast(target_width - 1)) - 1
            else
                (@as(i128, 1) << @intCast(target_width)) - 1;
            const min_integer: i128 = if (isSignedPrimitive(target))
                -(@as(i128, 1) << @intCast(target_width - 1))
            else
                0;
            const max_value: f64 = @floatFromInt(max_integer);
            const min_value: f64 = @floatFromInt(min_integer);

            var conversion: ast.Expr = try self.scalarBuiltin("intFromFloat", operand);
            const max_lhs = try self.allocExpr(operand);
            errdefer self.alloc.destroy(max_lhs);
            const max_rhs = try self.allocExpr(.{ .lit = .{ .float = max_value } });
            errdefer self.alloc.destroy(max_rhs);
            const max_condition = try self.allocExpr(.{ .bin_op = .{
                .op = .greater_than,
                .lhs = max_lhs,
                .rhs = max_rhs,
            } });
            errdefer self.alloc.destroy(max_condition);
            const max_then_body = try self.allocExpr(.{ .lit = .{ .int = max_integer } });
            errdefer self.alloc.destroy(max_then_body);
            const max_else_body = try self.allocExpr(conversion);
            errdefer self.alloc.destroy(max_else_body);
            conversion = .{ .if_expr = .{
                .cond = max_condition,
                .then_body = max_then_body,
                .else_body = max_else_body,
            } };

            const min_lhs = try self.allocExpr(operand);
            errdefer self.alloc.destroy(min_lhs);
            const min_rhs = try self.allocExpr(.{ .lit = .{ .float = min_value } });
            errdefer self.alloc.destroy(min_rhs);
            const min_condition = try self.allocExpr(.{ .bin_op = .{
                .op = .less_than,
                .lhs = min_lhs,
                .rhs = min_rhs,
            } });
            errdefer self.alloc.destroy(min_condition);
            const min_then_body = try self.allocExpr(.{ .lit = .{ .int = min_integer } });
            errdefer self.alloc.destroy(min_then_body);
            const min_else_body = try self.allocExpr(conversion);
            errdefer self.alloc.destroy(min_else_body);
            conversion = .{ .if_expr = .{
                .cond = min_condition,
                .then_body = min_then_body,
                .else_body = min_else_body,
            } };

            const nan_callee = try self.allocExpr(.{ .ident = "std.math.isNan" });
            errdefer self.alloc.destroy(nan_callee);
            const nan_args = try self.alloc.alloc(ast.Expr, 1);
            errdefer self.alloc.free(nan_args);
            nan_args[0] = operand;
            const nan_condition = try self.allocExpr(.{ .call = .{
                .callee = nan_callee,
                .args = nan_args,
            } });
            errdefer self.alloc.destroy(nan_condition);
            const nan_then_body = try self.allocExpr(.{ .lit = .{ .int = 0 } });
            errdefer self.alloc.destroy(nan_then_body);
            const nan_else_body = try self.allocExpr(conversion);
            errdefer self.alloc.destroy(nan_else_body);
            conversion = .{ .if_expr = .{
                .cond = nan_condition,
                .then_body = nan_then_body,
                .else_body = nan_else_body,
            } };
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(conversion),
            } };
        }

        if (isFloatPrimitive(target)) {
            const converted = try self.scalarBuiltin("floatFromInt", operand);
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(converted),
            } };
        }

        const source_width = integerWidth(source) orelse return error.UnsupportedExpression;
        const target_width = integerWidth(target) orelse return error.UnsupportedExpression;
        if (source_width > target_width) {
            const truncated = try self.scalarBuiltin("truncate", operand);
            // `@truncate` KEEPS the operand's signedness — it cannot even be
            // spelled for a destination of the other one — while a Rust `as`
            // keeps the low bits and says nothing about the sign. So a
            // narrowing cast across signedness narrows into a type of the
            // SOURCE's sign and reinterprets those same bits into the
            // destination, which is the pair the same-width case below
            // already uses and the one Zig will accept.
            if (isSignedPrimitive(source) == isSignedPrimitive(target)) {
                return .{ .cast = .{
                    .target = target_ast,
                    .operand = try self.allocExpr(truncated),
                } };
            }
            const narrow = if (isSignedPrimitive(source))
                signedCounterpart(target) orelse return error.UnsupportedExpression
            else
                unsignedCounterpart(target) orelse return error.UnsupportedExpression;
            const narrowed: ast.Expr = .{ .cast = .{
                .target = try self.lowerType(.{ .prim = narrow }),
                .operand = try self.allocExpr(truncated),
            } };
            const reinterpreted = try self.scalarBuiltin("bitCast", narrowed);
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(reinterpreted),
            } };
        }
        if (source_width == target_width and isSignedPrimitive(source) != isSignedPrimitive(target)) {
            const reinterpreted = try self.scalarBuiltin("bitCast", operand);
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(reinterpreted),
            } };
        }
        if (source_width < target_width and isSignedPrimitive(source) and
            !isSignedPrimitive(target))
        {
            const signed_target = signedCounterpart(target) orelse return error.UnsupportedExpression;
            const widened: ast.Expr = .{ .cast = .{
                .target = try self.lowerType(.{ .prim = signed_target }),
                .operand = try self.allocExpr(operand),
            } };
            const reinterpreted = try self.scalarBuiltin("bitCast", widened);
            return .{ .cast = .{
                .target = target_ast,
                .operand = try self.allocExpr(reinterpreted),
            } };
        }
        return .{ .cast = .{
            .target = target_ast,
            .operand = try self.allocExpr(operand),
        } };
    }

    fn typeById(self: *const Lowerer, type_id: ir.spine.TypeId) !ir.types.Type {
        if (type_id < self.ir.types.len) return self.ir.types[type_id];
        if (type_id < self.ir.bodies.types.len) return self.ir.bodies.types[type_id];
        return error.MissingTypeId;
    }

    /// Lower a Rust range used as a value. A Zig range is a statement rather
    /// than an expression, so it cannot be a receiver, an argument or a
    /// binding; the runtime's `r2z.Range` struct is the value form.
    fn lowerRangeExpr(
        self: *Lowerer,
        range: ir.exprs.RangeExpr,
    ) anyerror!ast.Expr {
        const end_id = range.end orelse return error.UnsupportedExpression;
        const start = try self.allocExpr(try self.lowerExpr(range.start));
        const lowered_end = try self.lowerExpr(end_id);
        const end: ast.Expr = if (!range.inclusive)
            lowered_end
        else
            .{ .bin_op = .{
                .op = .add,
                .lhs = try self.allocExpr(lowered_end),
                .rhs = try self.allocExpr(.{ .lit = .{ .int = 1 } }),
            } };
        try self.markRuntimeImport();
        const fields = try self.alloc.alloc(ast.StructInitField, 2);
        fields[0] = .{ .name = "start", .expr = start.* };
        fields[1] = .{ .name = "end", .expr = end };
        return .{ .struct_init = .{
            .type_name = .{ .named = "r2z.Range" },
            .fields = fields,
        } };
    }

    /// Lower a Rust range in a statement position, where Zig wants the bare
    /// `start..end` form: a slice index, or the input of a `for` loop.
    fn lowerRangeSliceExpr(
        self: *Lowerer,
        range: ir.exprs.RangeExpr,
        allow_open: bool,
    ) anyerror!ast.Expr {
        if (range.end == null) {
            if (!allow_open) return error.UnsupportedExpression;
            if (range.inclusive) return error.UnsupportedExpression;
        }
        const start = try self.allocExpr(try self.lowerExpr(range.start));
        const end: ?*const ast.Expr = if (range.end) |end_id| blk: {
            const lowered_end = try self.lowerExpr(end_id);
            if (!range.inclusive) break :blk try self.allocExpr(lowered_end);
            const one = try self.allocExpr(.{ .lit = .{ .int = 1 } });
            break :blk try self.allocExpr(.{ .bin_op = .{
                .op = .add,
                .lhs = try self.allocExpr(lowered_end),
                .rhs = one,
            } });
        } else null;
        return .{ .range = .{ .start = start, .end = end } };
    }

    fn shouldElideSliceBorrow(self: *const Lowerer, operand_id: ir.exprs.NodeId) bool {
        if (operand_id >= self.ir.bodies.exprs.len) return false;
        const index = switch (self.ir.bodies.exprs[operand_id].kind) {
            .index => |value| value,
            else => return false,
        };
        if (index.index >= self.ir.bodies.exprs.len) return false;
        return self.ir.bodies.exprs[index.index].kind == .range;
    }

    /// `base[index]`, the one shape a slice index and a range index share.
    fn indexSliceExpr(
        self: *Lowerer,
        base: *const ast.Expr,
        index_expr: *const ast.Expr,
    ) anyerror!ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = base.*;
        args[1] = index_expr.*;
        return .{ .builtin = .{
            .name = "index",
            .args = args,
        } };
    }

    /// Whether `&mut place[..]` writes an OWNED ARRAY a binding holds.
    ///
    /// `&mut buf[..]` and `&buf[..]` lower to the same slice `buf[0..]` — the
    /// borrow IS the descriptor — but only the mutable one writes the array.
    /// The array's mutability is the whole reason the slice is `[]T` rather
    /// than `[]const T`, so the address has to survive the elision: it is the
    /// one trace the emitted block carries that the binding is written
    /// through, and without it the mutability post-pass puts `const` on a
    /// binding the source declared `mut`, and the slice it yields is a
    /// `const` slice the call cannot take.
    ///
    /// The gate is the source's own `&mut` and an array PLACE the caller's
    /// storage owns. A slice descriptor already carries the pointer and its own
    /// element mutability, a pointer to an array is already an address, and a
    /// shared borrow writes nothing at all — so those keep the plain slice.
    fn mutableBorrowWritesOwnedArray(self: *Lowerer, operand_id: ir.exprs.NodeId) bool {
        if (operand_id >= self.ir.bodies.exprs.len) return false;
        const index = switch (self.ir.bodies.exprs[operand_id].kind) {
            .index => |value| value,
            else => return false,
        };
        if (index.index >= self.ir.bodies.exprs.len) return false;
        if (self.ir.bodies.exprs[index.index].kind != .range) return false;
        // The base has to be a PLACE the caller owns storage in. A binding is
        // one, and so is a field or an indexed element reached through one:
        // `&mut state.data[..]` and `&mut rows[1][..]` write exactly the array
        // those name, and the mutability that proves it is the binding's, so
        // dropping the address drops the `var` too. An array LITERAL is a
        // temporary with no mutability of its own to restore, and any other
        // expression base is a value rather than storage this lowering can
        // keep addressable.
        if (index.base >= self.ir.bodies.exprs.len) return false;
        switch (self.ir.bodies.exprs[index.base].kind) {
            .path, .field, .index => {},
            .unary => |unary| if (unary.op != .deref) return false,
            else => return false,
        }
        const base_type = self.concreteExprType(index.base) orelse return false;
        return switch (base_type) {
            // A `[T; N]` whose length is the type parameter lowers to a Zig
            // slice, which is already a descriptor.
            .array => |array| array.len != .generic,
            else => false,
        };
    }

    /// The elided slice for `&mut buf[..]`, with the array's address kept.
    ///
    /// This is `(&buf)[0..]`: the same sequence `buf[0..]` names, reached
    /// through the array's own address. Zig takes the address of a `var` array
    /// and slices through the pointer, so the slice is `[]T`, and the
    /// address is what keeps the binding a `var`.
    fn lowerAddressedSliceBorrow(self: *Lowerer, operand_id: ir.exprs.NodeId) anyerror!ast.Expr {
        const index = self.ir.bodies.exprs[operand_id].kind.index;
        const base = try self.allocExpr(.{
            .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(try self.lowerExpr(index.base)),
            },
        });
        const bounds = try self.allocExpr(switch (self.ir.bodies.exprs[index.index].kind) {
            .range => |range| try self.lowerRangeSliceExpr(range, true),
            else => try self.lowerExpr(index.index),
        });
        return self.indexSliceExpr(base, bounds);
    }

    fn isCowPath(path: []const []const u8) bool {
        return externalPathEqual(path, &.{ "alloc", "borrow", "Cow" }) or
            externalPathEqual(path, &.{ "std", "borrow", "Cow" });
    }

    fn lowerCoreFunction(self: *Lowerer, function: ir.exprs.CoreFunctionValue) anyerror!ast.Expr {
        if (function.function != .mem_transmute) return error.UnsupportedCoreFunction;
        if (function.generic_args.len != 2) return error.InvalidCoreFunctionArity;
        try self.markRuntimeImport();
        const arguments = try self.alloc.alloc(ast.Type, 2);
        for (function.generic_args, 0..) |argument, index| arguments[index] = try self.lowerType(argument);
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.memory.transmute" }),
            .generic_args = arguments,
        } };
    }

    fn lowerExternalVariant(self: *Lowerer, node: ir.exprs.NodeId, variant: ir.exprs.ExternalVariant) anyerror!ast.Expr {
        if (!isCowPath(variant.owner.path)) return error.UnsupportedExternalType;
        if (!std.mem.eql(u8, variant.variant, "Borrowed") and
            !std.mem.eql(u8, variant.variant, "Owned")) return error.MissingVariantName;
        if (variant.tuple_fields.len != 1 or variant.named_fields.len != 0) return error.VariantArityMismatch;
        const value_type = try self.exprType(node) orelse return error.MissingTypeId;
        const payload = try self.lowerExpr(variant.tuple_fields[0]);
        // `Cow::Owned(value)` MOVES the payload: the value leaves the arm, so
        // whatever owned it before must end the call owning nothing. A struct
        // literal cannot do that — it copies and leaves the source full — so an
        // owned runtime container goes through the runtime's own `from_owned`,
        // which transfers the allocation AND empties the owner it is handed.
        // That is a pointer transfer like every other one, so an arm that moves
        // on one branch and keeps on another is correct on both: the moved
        // branch empties the alias and the release frees nothing, the kept
        // branch leaves it full and the release frees it.
        if (std.mem.eql(u8, variant.variant, "Owned")) {
            if (try self.cowOwnedTransfer(value_type, variant.tuple_fields[0], payload)) |transfer| {
                return transfer;
            }
        }
        const fields = try self.alloc.alloc(ast.StructInitField, 1);
        errdefer self.alloc.free(fields);
        const name = try self.alloc.dupe(u8, variant.variant);
        errdefer self.alloc.free(name);
        fields[0] = .{ .name = name, .expr = payload };
        return .{ .struct_init = .{
            .type_name = try self.lowerType(value_type),
            .fields = fields,
        } };
    }

    /// `CowType.from_owned(&payload)` when `payload` is an owned runtime
    /// container this cow can take over, or null when the struct literal is the
    /// honest lowering.
    ///
    /// A borrowed payload has nothing to transfer and keeps its literal. An
    /// owned container is exactly what `from_owned` exists for, and reaching it
    /// here rather than through a conversion keeps this a MOVE instead of a
    /// copy — which is what lets the arm's own release stay in place.
    fn cowOwnedTransfer(
        self: *Lowerer,
        cow_type: ir.types.Type,
        payload_node: ir.exprs.NodeId,
        payload: ast.Expr,
    ) anyerror!?ast.Expr {
        const cow = switch (cow_type) {
            .external_nominal => |external| external,
            else => return null,
        };
        if (!isCowPath(cow.path) or cow.args.len != 1) return null;
        const payload_type = try self.exprType(payload_node) orelse return null;
        if (!ownedRuntimeContainerType(payload_type)) return null;
        const generic_args: []const ast.Type = if (ir.types.isStr(cow.args[0])) &.{} else blk: {
            const borrowed_slice = switch (cow.args[0]) {
                .slice => |value| value,
                else => return null,
            };
            const params = try self.alloc.alloc(ast.Type, 1);
            params[0] = try self.lowerType(borrowed_slice.elem);
            break :blk params;
        };
        try self.markRuntimeImport();
        const cow_constructor = try self.runtimeCowType(
            ir.types.isStr(cow.args[0]),
            generic_args,
        );
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = try self.lowerOwnedReceiverPointer(payload_node, try self.allocExpr(payload));
        return (try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(cow_constructor),
                .field_name = "from_owned",
            } }),
            .args = args,
        } })).*;
    }

    /// The runtime cow TYPE a constructor hangs off, as the receiver a member
    /// access is written on.
    ///
    /// `CowSlice` is generic, so its type is a call that instantiates it.
    /// `CowStr` is a concrete union, and `CowStr()` would be calling one — the
    /// declaration is named directly instead, which reaches the same members
    /// without spelling a call that does not exist.
    fn runtimeCowType(
        self: *Lowerer,
        is_str: bool,
        generic_args: []const ast.Type,
    ) !ast.Expr {
        if (is_str) return (try self.allocExpr(.{ .ident = "r2z.alloc.CowStr" })).*;
        return (try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.CowSlice" }),
            .generic_args = generic_args,
            .args = &.{},
        } })).*;
    }

    fn lowerOwnedStringCall(self: *Lowerer, call: ir.exprs.CoreCall, input: ast.Expr) anyerror!ast.Expr {
        try self.markRuntimeImport();
        if (call.function == .string_from_utf8_lossy) {
            const args = try self.alloc.alloc(ast.Expr, 2);
            args[0] = .{ .ident = "allocator" };
            args[1] = try self.lowerBorrowedSequence(call.args[0], try self.allocExpr(input));
            self.current_callable_is_allocating = true;
            return .{ .unary_op = .{ .op = .try_op, .operand = try self.allocExpr(.{ .call = .{
                .callee = try self.allocExpr(.{ .ident = "r2z.alloc.String.from_utf8_lossy" }),
                .args = args,
            } }) } };
        }
        // `String::from_utf8` CONSUMES the vector it is handed: it takes the
        // bytes and leaves the caller's vector empty, so handing it a copy
        // would leave the original owner of those bytes still holding them and
        // freeing storage the returned string owns. The shared receiver helper
        // is the same one every other consuming receiver uses — a place is
        // handed over by address and ends the call empty, a value with no place
        // is materialized exactly once first — so the arm's own owner of this
        // storage ends up empty and its release has nothing to free.
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = try self.lowerOwnedReceiverPointer(call.args[0], try self.allocExpr(input));
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = if (call.function == .string_from_utf8)
                "r2z.alloc.String.from_utf8"
            else
                "r2z.alloc.String.from_utf8_unchecked" }),
            .args = args,
        } };
    }

    /// The `[]const T` a runtime helper that COPIES a sequence reads.
    ///
    /// The helper copies bytes, so it takes a slice and never ownership. A
    /// borrow the call site already wrote is read through unchanged; a
    /// sequence the call site NAMED is given its address, which is the
    /// coercion Zig makes from an array to a slice. The source is evaluated
    /// once either way — an address taken of a temporary is good for exactly
    /// the call it appears in, and the runtime copies out of it before it is
    /// gone — and a place that is already addressable is never copied into a
    /// local to be addressed, because that would duplicate storage the caller
    /// still owns and still releases.
    ///
    /// Whether the source is an array is read from its type where the
    /// frontend recorded one, and from the array literal's own shape where it
    /// did not: an array literal has exactly one lowered form, and handing
    /// that form to a slice parameter without its address is the one coercion
    /// that cannot be right.
    fn lowerSourceSequenceAsSlice(
        self: *Lowerer,
        source_node: ir.exprs.NodeId,
        source: *const ast.Expr,
    ) anyerror!ast.Expr {
        const read = try self.lowerMemoryReceiver(source_node, source);
        const is_array = if (try self.exprType(source_node)) |source_type| switch (source_type) {
            .array => true,
            .reference => |reference| reference.pointee == .array,
            else => false,
        } else read.* == .multi_array;
        if (!is_array) return read.*;
        return (try self.allocExpr(.{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(read.*),
        } })).*;
    }

    fn lowerCoreCall(self: *Lowerer, node: ir.exprs.NodeId, call: ir.exprs.CoreCall) anyerror!ast.Expr {
        if (call.function == .string_from_utf8 or call.function == .string_from_utf8_lossy or
            call.function == .string_from_utf8_unchecked)
        {
            if (call.args.len != 1 or call.generic_args.len != 0) return error.InvalidCoreCallArity;
            return self.lowerOwnedStringCall(call, try self.lowerExpr(call.args[0]));
        }
        if (call.function == .maybe_uninit_uninit) {
            if (call.args.len != 0 or call.generic_args.len != 1) return error.InvalidCoreCallArity;
            const result_type = (try self.exprType(node)) orelse call.generic_args[0];
            return .{ .cast = .{
                .target = try self.lowerType(result_type),
                .operand = try self.allocExpr(.{ .lit = .undefined_lit }),
            } };
        }
        if (call.function == .numeric_min_value or call.function == .numeric_max_value or
            call.function == .numeric_zero or call.function == .numeric_one)
        {
            if (call.args.len != 0 or call.generic_args.len != 1) return error.InvalidCoreCallArity;
            return self.lowerNumericCoreCall(node, call);
        }
        if (call.function == .prim_from_le_bytes or call.function == .prim_to_le_bytes) {
            if (call.args.len != 1 or call.generic_args.len != 1) return error.InvalidCoreCallArity;
            return self.lowerLittleEndianBytes(node, call);
        }
        if (call.function == .hash_write_primitive) {
            if (call.args.len != 2 or call.generic_args.len != 1) return error.InvalidCoreCallArity;
            return self.lowerHasherPrimitiveWrite(node, call);
        }
        if (call.function == .rng_fill_bytes_via_next and
            (call.args.len != 2 or call.generic_args.len != 0)) return error.InvalidCoreCallArity;
        const args = try self.alloc.alloc(ast.Expr, call.args.len);
        for (call.args, 0..) |arg, index| args[index] = try self.lowerExpr(arg);
        if (call.function == .mem_transmute) {
            return .{ .call = .{
                .callee = try self.allocExpr(try self.lowerCoreFunction(.{
                    .function = call.function,
                    .generic_args = call.generic_args,
                })),
                .args = args,
            } };
        }
        if (call.function == .cmp_min or call.function == .cmp_max) {
            return .{ .builtin = .{
                .name = if (call.function == .cmp_min) "min" else "max",
                .args = args,
            } };
        }
        if (call.function == .convert_from and call.generic_args.len == 1) {
            if (call.args.len != 1) return error.InvalidCoreCallArity;
            // Both conversions copy the caller's sequence into FRESH owned
            // storage, which is why neither is a conversion the runtime can
            // declare: `String::from` copies borrowed bytes and `Vec::from`
            // copies elements, and the runtime already has one copy-into-owned
            // helper for each. Both allocate, so the allocator leads the
            // argument list and the enclosing callable declares one.
            if (isOwnedStringType(call.generic_args[0])) {
                const string_args = try self.alloc.alloc(ast.Expr, 2);
                string_args[0] = .{ .ident = "allocator" };
                string_args[1] = (try self.lowerMemoryReceiver(
                    call.args[0],
                    try self.allocExpr(args[0]),
                )).*;
                try self.markRuntimeImport();
                self.current_callable_is_allocating = true;
                const string_call = try self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.alloc.String.from_str" }),
                    .args = string_args,
                } });
                return .{ .unary_op = .{
                    .op = .try_op,
                    .operand = string_call,
                } };
            }
            // `Vec<T>::from(sequence)`: the element type is the vector's own,
            // and the source is read through any borrow the call site wrote,
            // which is what turns `&buf[..]` into the bytes themselves.
            if (try vecElementOfContext(call.generic_args[0])) |element| {
                const element_args = try self.alloc.alloc(ast.Type, 1);
                element_args[0] = try self.lowerType(element);
                const vec_args = try self.alloc.alloc(ast.Expr, 2);
                vec_args[0] = .{ .ident = "allocator" };
                vec_args[1] = try self.lowerSourceSequenceAsSlice(
                    call.args[0],
                    try self.allocExpr(args[0]),
                );
                try self.markRuntimeImport();
                self.current_callable_is_allocating = true;
                const vec_call = try self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_from_slice" }),
                    .generic_args = element_args,
                    .args = vec_args,
                } });
                return .{ .unary_op = .{
                    .op = .try_op,
                    .operand = vec_call,
                } };
            }
        }
        const generic_args = try self.alloc.alloc(ast.Type, call.generic_args.len);
        for (call.generic_args, 0..) |arg, index| generic_args[index] = try self.lowerType(arg);
        const name = switch (call.function) {
            .mem_size_of => "r2z.memory.size_of",
            .mem_size_of_val => "r2z.memory.size_of_val",
            .rng_fill_bytes_via_next => "r2z.random.fill_bytes_via_next",
            .ptr_copy_nonoverlapping => "r2z.memory.copy_nonoverlapping",
            .ptr_write_bytes => "r2z.memory.write_bytes",
            .ptr_read_unaligned => "r2z.memory.read_unaligned",
            .slice_from_raw_parts => "r2z.memory.from_raw_parts",
            .slice_from_raw_parts_mut => "r2z.memory.from_raw_parts_mut",
            .str_from_utf8 => "r2z.character.from_utf8",
            .str_from_utf8_unchecked => "r2z.character.from_utf8_unchecked",
            .default_value => "r2z.convert.default_value",
            .convert_from => "r2z.convert.from",
            .mem_transmute => unreachable,
            .prim_from_le_bytes, .prim_to_le_bytes, .maybe_uninit_uninit, .hash_write_primitive => unreachable,
            .cmp_min, .cmp_max => unreachable,
            .numeric_min_value, .numeric_max_value, .numeric_zero, .numeric_one => unreachable,
            .string_from_utf8, .string_from_utf8_lossy, .string_from_utf8_unchecked => unreachable,
        };
        try self.markRuntimeImport();
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) }),
            .generic_args = generic_args,
            .args = args,
        } };
    }

    /// Rust's explicit LE conversions use the same endian on every target.
    /// Materialize each value once; the only storage is the fixed-size array.
    fn lowerLittleEndianBytes(self: *Lowerer, node: ir.exprs.NodeId, call: ir.exprs.CoreCall) anyerror!ast.Expr {
        const integer = try self.lowerType(call.generic_args[0]);
        const decoding = call.function == .prim_from_le_bytes;
        const input = try self.lowerExpr(call.args[0]);
        const reads_place = decoding and exprIsAddressable(input);
        const name = try std.fmt.allocPrint(self.alloc, "__r2z_le_bytes_{d}", .{node});
        const type_arg = try self.alloc.alloc(ast.Expr, 1);
        type_arg[0] = .{ .type_value = integer };
        const bytes_type: ast.Type = .{ .array_expr = .{
            .elem = try self.allocType(.{ .prim = .u8 }),
            .len = try self.allocExpr(.{ .builtin = .{ .name = "sizeOf", .args = type_arg } }),
        } };
        const statements = try self.alloc.alloc(ast.Stmt, if (reads_place) 0 else if (decoding) 1 else 2);
        if (!reads_place) statements[0] = .{ .let_stmt = .{
            .name = name,
            .ty = bytes_type,
            .init = if (decoding) input else .{ .lit = .undefined_lit },
            .is_mut = !decoding,
        } };
        const arguments = try self.alloc.alloc(ast.Expr, if (decoding) 2 else 3);
        arguments[0] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(if (reads_place) input else .{ .ident = name }),
        } };
        if (!decoding) arguments[1] = input;
        arguments[arguments.len - 1] = .{ .ident = "std.builtin.Endian.little" };
        const integer_args = try self.alloc.alloc(ast.Type, 1);
        integer_args[0] = integer;
        const operation: ast.Expr = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = if (decoding) "std.mem.readInt" else "std.mem.writeInt" }),
            .generic_args = integer_args,
            .args = arguments,
        } };
        if (reads_place) return operation;
        if (!decoding) statements[1] = .{ .expr_stmt = try self.allocExpr(operation) };
        return .{ .block = .{
            .stmts = statements,
            .expr = try self.allocExpr(if (decoding) operation else .{ .ident = name }),
        } };
    }

    /// Standard integer defaults are invalid for custom source types. This
    /// comptime switch analyzes the primitive body only for an actual integer;
    /// custom types must select an exact source implementation above it.
    fn integerTraitFallback(self: *Lowerer, target: ast.Type, operation: ast.Expr) anyerror!ast.Expr {
        const type_args = try self.alloc.alloc(ast.Expr, 1);
        type_args[0] = .{ .type_value = target };
        const message = try self.alloc.alloc(ast.Expr, 1);
        message[0] = .{ .lit = .{ .str = "custom numeric type requires its source trait implementation" } };
        const arms = try self.alloc.alloc(ast.MatchArm, 2);
        arms[0] = .{ .patterns = &.{.{ .enum_literal = "int" }}, .body = operation };
        arms[1] = .{ .patterns = &.{.wildcard}, .body = .{ .builtin = .{ .name = "compileError", .args = message } } };
        return .{ .match_expr = .{
            .target = try self.allocExpr(.{ .builtin = .{ .name = "typeInfo", .args = type_args } }),
            .arms = arms,
        } };
    }

    fn sourceAssociatedCallee(self: *Lowerer, method_id: ir.spine.EntityId) anyerror!ast.Expr {
        if (moduleHoistedImplMethod(self, method_id) != null) return self.lowerResolvedEntity(method_id);
        const method = self.ir.graph.symbol_table.get(method_id) orelse return error.MissingDefinition;
        if (method.parent) |parent| {
            if (parent < self.ir.bodies.bodies.len) switch (self.ir.bodies.bodies[parent]) {
                .impl_ => |impl_body| {
                    return .{ .field_access = .{
                        .target = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                        .field_name = self.hoisted_method_names.get(method_id) orelse (method.renamed_to orelse method.name),
                    } };
                },
                else => {},
            };
        }
        if (try self.qualifyTraitImplMethod(method_id)) |qualified| return qualified;
        return self.qualifyInherentMethod(method_id, try self.lowerResolvedEntity(method_id));
    }

    /// `I::method(args)` records its Self type on the call, even when the
    /// return type does not mention Self. Resolve by that trait identity, not
    /// by the returned type or by a same-named function in another impl.
    fn lowerSourceAssociatedTraitCall(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        call: ir.exprs.Call,
        args: []const ast.Expr,
    ) anyerror!?ast.Expr {
        const method_id = switch (call.call_kind) {
            .associated => |id| id,
            else => return null,
        };
        const method = self.ir.graph.symbol_table.get(method_id) orelse return null;
        if (method.kind != .method_ref) return null;
        const trait_id = method.parent orelse return null;
        const trait_entity = self.ir.graph.symbol_table.get(trait_id) orelse return null;
        if (trait_entity.kind != .trait_) return null;
        const metadata = self.concreteExprType(node) orelse return null;
        if (metadata != .generic_inst or metadata.generic_inst.decl != method_id or
            metadata.generic_inst.args.params.len == 0) return null;
        const parameters = metadata.generic_inst.args.params;
        const receiver_type = parameters[0];
        const target = try self.lowerType(receiver_type);
        const message = try self.alloc.alloc(ast.Expr, 1);
        message[0] = .{ .lit = .{ .str = "source associated trait has no implementation for the instantiated Self type" } };
        var result: ast.Expr = .{ .builtin = .{ .name = "compileError", .args = message } };
        var blanket_found = false;
        // A blanket answers EVERY instantiation, so the scan may not stop at it:
        // the whole question is whether a second impl claims the same function,
        // and a loop that returned on the first blanket never asked. The answer
        // is kept and returned once the scan has proved it is the only one.
        var blanket_operation: ?ast.Expr = null;
        var matches: std.ArrayListUnmanaged(ir.types.Type) = .empty;
        defer matches.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            if (!traitPathMatches(trait_path, trait_id)) continue;
            const source_method = self.blanketImplMethod(entity.id, method.name) orelse continue;
            const blanket = blanketSelfTypeParam(impl_body.self_ty) != null;
            if (blanket) {
                if (blanket_found or matches.items.len != 0) return error.AmbiguousTraitImplMatch;
                blanket_found = true;
            } else {
                if (blanket_found) return error.AmbiguousTraitImplMatch;
                if (!self.descriptorTypeIsConcrete(impl_body.self_ty)) continue;
                if (!isTypeParameterPath(receiver_type) and !typeEquals(receiver_type, impl_body.self_ty)) continue;
                for (matches.items) |matched| {
                    if (typeEquals(matched, impl_body.self_ty)) return error.AmbiguousTraitImplMatch;
                }
                try matches.append(self.alloc, impl_body.self_ty);
            }
            const method_generics = try self.lowerCallGenericArgs(node, source_method, call.args, parameters[1..]);
            const generic_args = if (blanket) blk: {
                const combined = try self.alloc.alloc(ast.Type, method_generics.len + 1);
                combined[0] = target;
                @memcpy(combined[1..], method_generics);
                break :blk combined;
            } else method_generics;
            const allocates = self.hoistedMethodTakesAllocator(source_method);
            if (allocates) self.current_callable_is_allocating = true;
            const arguments = try self.alloc.alloc(ast.Expr, args.len + @intFromBool(allocates));
            if (allocates) arguments[0] = .{ .ident = "allocator" };
            @memcpy(arguments[@intFromBool(allocates)..], args);
            const operation = try self.lowerDirectCallResult(node, .{ .call = .{
                .callee = try self.allocExpr(try self.sourceAssociatedCallee(source_method)),
                .generic_args = generic_args,
                .args = arguments,
            } }, allocates, self.callableFallible(source_method));
            if (blanket) {
                blanket_operation = operation;
                continue;
            }
            if (!isTypeParameterPath(receiver_type)) return operation;
            const previous_result = try self.allocExpr(result);
            result = .{ .if_expr = .{
                .cond = try self.allocExpr(.{ .bin_op = .{
                    .op = .equal,
                    .lhs = try self.allocExpr(.{ .type_value = target }),
                    .rhs = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                } }),
                .then_body = try self.allocExpr(operation),
                .else_body = previous_result,
            } };
        }
        return blanket_operation orelse result;
    }

    /// Numeric traits are standard identities, not leaf names. A custom
    /// `Bounded`, `Zero`, or `One` implementation keeps its source function;
    /// only primitive instantiations reach the built-in numeric fallback.
    fn lowerNumericCoreCall(self: *Lowerer, node: ir.exprs.NodeId, call: ir.exprs.CoreCall) anyerror!ast.Expr {
        const source_type = call.generic_args[0];
        const target = try self.lowerType(source_type);
        const trait_name: []const u8 = switch (call.function) {
            .numeric_min_value, .numeric_max_value => "Bounded",
            .numeric_zero => "Zero",
            .numeric_one => "One",
            else => return error.UnsupportedCoreFunction,
        };
        const method_name: []const u8 = switch (call.function) {
            .numeric_min_value => "min_value",
            .numeric_max_value => "max_value",
            .numeric_zero => "zero",
            .numeric_one => "one",
            else => unreachable,
        };
        var result: ast.Expr = if (call.function == .numeric_zero or call.function == .numeric_one)
            .{ .cast = .{
                .target = target,
                .operand = try self.allocExpr(.{ .lit = .{ .int = if (call.function == .numeric_zero) 0 else 1 } }),
            } }
        else blk: {
            const generic_args = try self.alloc.alloc(ast.Type, 1);
            generic_args[0] = target;
            break :blk .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = if (call.function == .numeric_min_value) "std.math.minInt" else "std.math.maxInt" }),
                .generic_args = generic_args,
                .args = &.{},
            } };
        };
        if (isTypeParameterPath(source_type)) {
            result = try self.integerTraitFallback(target, result);
        }
        var matches: std.ArrayListUnmanaged(ir.types.Type) = .empty;
        defer matches.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            const module_name: []const u8 = if (std.mem.eql(u8, trait_name, "Bounded")) "bounds" else "identities";
            if (!ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "num_traits", trait_name }) and
                !ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "num_traits", module_name, trait_name })) continue;
            const method_id = self.blanketImplMethod(entity.id, method_name) orelse continue;
            if (!self.descriptorTypeIsConcrete(impl_body.self_ty)) continue;
            if (!isTypeParameterPath(source_type) and !typeEquals(source_type, impl_body.self_ty)) continue;
            for (matches.items) |matched| {
                if (typeEquals(matched, impl_body.self_ty)) return error.AmbiguousTraitImplMatch;
            }
            try matches.append(self.alloc, impl_body.self_ty);
            const allocates = self.hoistedMethodTakesAllocator(method_id);
            if (allocates) self.current_callable_is_allocating = true;
            const arguments = try self.alloc.alloc(ast.Expr, @intFromBool(allocates));
            if (allocates) arguments[0] = .{ .ident = "allocator" };
            const operation = try self.lowerDirectCallResult(node, .{ .call = .{
                .callee = try self.allocExpr(try self.sourceAssociatedCallee(method_id)),
                .args = arguments,
            } }, allocates, self.callableFallible(method_id));
            if (!isTypeParameterPath(source_type)) return operation;
            // Preserve the old tree before the aggregate reuses result's storage.
            const previous_result = try self.allocExpr(result);
            result = .{ .if_expr = .{
                .cond = try self.allocExpr(.{ .bin_op = .{
                    .op = .equal,
                    .lhs = try self.allocExpr(.{ .type_value = target }),
                    .rhs = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                } }),
                .then_body = try self.allocExpr(operation),
                .else_body = previous_result,
            } };
        }
        if (source_type != .prim and !isTypeParameterPath(source_type))
            return error.UnsupportedNumericTraitImpl;
        return result;
    }

    fn hasherPrimitiveType(name: []const u8) ?ir.types.Type {
        inline for (hasher_write_primitives) |suffix| {
            if (std.mem.eql(u8, name, "write_" ++ suffix))
                return .{ .prim = @field(ir.types.Prim, suffix) };
        }
        return null;
    }

    /// A generic source trait call keeps the exact trait identity until Zig
    /// instantiates its receiver. Primitive impls already have module-hoisted
    /// declarations; local nominal impls already have member declarations.
    /// Type comparisons select those declarations without copying the receiver.
    /// Canonical standard bounds permit defaults only after source overrides.
    fn lowerGenericSourceMethodCall(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        call: ir.exprs.MethodCall,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        requested_name: ?[]const u8,
    ) anyerror!?ast.Expr {
        const method = self.ir.graph.symbol_table.get(call.method) orelse return null;
        if (method.kind != .method_ref) return null;
        const method_name = requested_name orelse method.name;
        const receiver_type = (try self.exprType(call.receiver)) orelse return null;
        const scalar = peelReceiverType(receiver_type);
        if (!isTypeParameterPath(scalar)) return null;
        const owner = self.current_callable_id orelse return null;
        const source_trait = if (requested_name != null)
            null
        else if (method.parent) |parent| blk: {
            const entity = self.ir.graph.symbol_table.get(parent) orelse break :blk null;
            break :blk if (entity.kind == .trait_) parent else null;
        } else null;
        const integer = hasherPrimitiveType(method_name);
        const hasher_method = integer != null or std.mem.eql(u8, method_name, "write") or std.mem.eql(u8, method_name, "finish");
        if (requested_name != null and !hasher_method) return null;
        const hasher_bound = source_trait == null and hasher_method and
            ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, receiver_type, &.{ "core", "hash", "Hasher" }) != null;
        const hash_bound = source_trait == null and std.mem.eql(u8, method_name, "hash") and
            ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, receiver_type, &.{ "core", "hash", "Hash" }) != null;
        const checked_trait: ?[]const u8 = if (std.mem.eql(u8, method_name, "checked_add"))
            "CheckedAdd"
        else if (std.mem.eql(u8, method_name, "checked_sub"))
            "CheckedSub"
        else if (std.mem.eql(u8, method_name, "checked_mul"))
            "CheckedMul"
        else
            null;
        const checked_bound = if (source_trait != null)
            false
        else if (checked_trait) |trait_name|
            ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, receiver_type, &.{ "num_traits", "ops", "checked", trait_name }) != null or
                ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, receiver_type, &.{ "num_traits", trait_name }) != null
        else
            false;
        if (source_trait == null and !hasher_bound and !hash_bound and !checked_bound) return null;

        var result: ast.Expr = if (hasher_bound) blk: {
            if (integer) |primitive| {
                if (args.len != 1) return error.UnsupportedStandardMethod;
                break :blk try self.lowerHasherDefaultWrite(node, primitive, receiver.*, args[0], null, call.receiver);
            }
            if (args.len != (if (std.mem.eql(u8, method_name, "write")) @as(usize, 1) else 0))
                return error.UnsupportedStandardMethod;
            break :blk .{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{ .target = receiver, .field_name = method_name } }),
                .args = args,
            } };
        } else if (checked_bound) blk: {
            const recognized: RecognizedStdMethod = if (std.mem.eql(u8, method_name, "checked_add"))
                .num_checked_add
            else if (std.mem.eql(u8, method_name, "checked_sub"))
                .num_checked_sub
            else
                .num_checked_mul;
            break :blk try self.integerTraitFallback(
                try self.lowerType(scalar),
                (try self.lowerIntegerStdMethod(recognized, call.receiver, receiver, args, call.args)).*,
            );
        } else blk: {
            const message = try self.alloc.alloc(ast.Expr, 1);
            message[0] = .{ .lit = .{ .str = "source trait has no implementation for the instantiated receiver" } };
            const refusal: ast.Expr = .{ .builtin = .{ .name = "compileError", .args = message } };
            break :blk if (hash_bound)
                (try self.lowerPrimitiveHashDefaults(node, call, receiver, args, scalar) orelse refusal)
            else
                refusal;
        };
        var matches: std.ArrayListUnmanaged(ir.types.Type) = .empty;
        defer matches.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            const matches_trait = if (source_trait) |trait_id|
                traitPathMatches(trait_path, trait_id)
            else if (hasher_bound)
                ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "core", "hash", "Hasher" })
            else if (hash_bound)
                ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "core", "hash", "Hash" })
            else
                ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "num_traits", "ops", "checked", checked_trait.? }) or
                    ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "num_traits", checked_trait.? });
            if (!matches_trait) continue;
            if (source_trait != null and blanketSelfTypeParam(impl_body.self_ty) != null) continue;
            const direct_method = self.blanketImplMethod(entity.id, method_name);
            const native_default = hasher_bound and integer != null and direct_method == null;
            const method_id = direct_method orelse
                (if (native_default) self.blanketImplMethod(entity.id, "write") else null) orelse continue;
            if (!self.descriptorTypeIsConcrete(impl_body.self_ty)) continue;
            for (matches.items) |matched| {
                if (typeEquals(matched, impl_body.self_ty)) return error.AmbiguousTraitImplMatch;
            }
            try matches.append(self.alloc, impl_body.self_ty);
            const operation = if (native_default)
                try self.lowerHasherDefaultWrite(node, integer.?, receiver.*, args[0], method_id, call.receiver)
            else
                try self.lowerSourceReceiverCall(node, method_id, call.receiver, receiver, args, call.args, call.generic_args);
            const previous_result = try self.allocExpr(result);
            result = .{ .if_expr = .{
                .cond = try self.allocExpr(.{ .bin_op = .{
                    .op = .equal,
                    .lhs = try self.allocExpr(.{ .type_value = try self.lowerType(scalar) }),
                    .rhs = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                } }),
                .then_body = try self.allocExpr(operation),
                .else_body = previous_result,
            } };
        }
        if (matches.items.len == 0 and source_trait != null) {
            switch (self.blanketImplForMethod(call.method)) {
                .none => {},
                .unique => return null,
                .ambiguous => {
                    const message = try self.alloc.alloc(ast.Expr, 1);
                    message[0] = .{ .lit = .{
                        .str = "ambiguous source trait method implementation for instantiated receiver",
                    } };
                    return .{ .builtin = .{ .name = "compileError", .args = message } };
                },
            }
        }
        return result;
    }

    const HashPrimitiveDefault = struct {
        hashed: ir.types.Prim,
        written: ir.types.Prim,
    };

    const hash_primitive_defaults = [_]HashPrimitiveDefault{
        .{ .hashed = .u8, .written = .u8 },
        .{ .hashed = .u16, .written = .u16 },
        .{ .hashed = .u32, .written = .u32 },
        .{ .hashed = .u64, .written = .u64 },
        .{ .hashed = .u128, .written = .u128 },
        .{ .hashed = .usize, .written = .usize },
        .{ .hashed = .i8, .written = .i8 },
        .{ .hashed = .i16, .written = .i16 },
        .{ .hashed = .i32, .written = .i32 },
        .{ .hashed = .i64, .written = .i64 },
        .{ .hashed = .i128, .written = .i128 },
        .{ .hashed = .isize, .written = .isize },
        .{ .hashed = .bool, .written = .u8 },
        .{ .hashed = .char, .written = .u32 },
        .{ .hashed = .unit, .written = .unit },
    };

    fn lowerPrimitiveHashDefaults(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        call: ir.exprs.MethodCall,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        scalar: ir.types.Type,
    ) anyerror!?ast.Expr {
        if (call.args.len != 1 or args.len != 1) return null;
        const hasher_node = call.args[0];
        const hasher = args[0];
        const hasher_type = peelReceiverType((try self.exprType(hasher_node)) orelse return null);
        const generic_hasher = isTypeParameterPath(hasher_type);
        const hashed = try self.lowerMemoryReceiver(call.receiver, receiver);
        const operand_name = try self.iteratorTemporaryName("__r2z_hash_operand");
        var result: ast.Expr = try self.recursiveHashDefaultExpr(
            node,
            call.receiver,
            receiver.*,
            hasher_type,
            hasher,
            scalar,
        );
        inline for (hash_primitive_defaults) |entry| {
            if (entry.hashed == .unit) continue;
            const hashed_type: ir.types.Type = .{ .prim = entry.hashed };
            const written_type: ir.types.Type = .{ .prim = entry.written };
            const binding = try self.alloc.alloc(ast.Stmt, 1);
            binding[0] = .{ .let_stmt = .{
                .name = operand_name,
                .ty = try self.lowerType(hashed_type),
                .init = hashed.*,
                .is_mut = false,
            } };
            const operand: ast.Expr = .{ .ident = operand_name };
            const value: ast.Expr = if (entry.hashed == entry.written)
                operand
            else
                try self.scalarCast(hashed_type, written_type, operand);
            const write_name = try std.fmt.allocPrint(self.alloc, "write_{s}", .{@tagName(entry.written)});
            const source = if (generic_hasher)
                SourceHasherWrites{}
            else
                try self.sourceHasherWrites(hasher_type, write_name);
            const operation = if (generic_hasher)
                (try self.lowerGenericHasherWrite(node, call, hasher, hasher_node, write_name, value)) orelse return null
            else
                try self.lowerHasherValueWrite(
                    node,
                    written_type,
                    source orelse return null,
                    hasher_node,
                    hasher,
                    value,
                    &.{call.receiver},
                );
            const previous_result = try self.allocExpr(result);
            result = .{ .if_expr = .{
                .cond = try self.allocExpr(try self.hashScalarMatchesExpr(scalar, entry.hashed)),
                .then_body = try self.allocExpr(.{ .block = .{
                    .stmts = binding,
                    .expr = try self.allocExpr(operation),
                } }),
                .else_body = previous_result,
            } };
        }
        return result;
    }

    fn recursiveHashDefaultExpr(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        receiver_node: ir.exprs.NodeId,
        receiver: ast.Expr,
        hasher_type: ir.types.Type,
        hasher: ast.Expr,
        hashed_type: ir.types.Type,
    ) anyerror!ast.Expr {
        const walk = try self.ensureHashWalk();
        try self.markRuntimeImport();
        if (walk.is_allocating) self.current_callable_is_allocating = true;
        const generic_args = try self.alloc.alloc(ast.Type, 2);
        generic_args[0] = try self.hashDescriptorType(hashed_type);
        generic_args[1] = try self.lowerType(hasher_type);
        const args = try self.alloc.alloc(ast.Expr, 2 + @as(usize, @intFromBool(walk.is_allocating)));
        const offset: usize = @intFromBool(walk.is_allocating);
        if (walk.is_allocating) args[0] = .{ .ident = "allocator" };
        args[offset] = hasher;
        var statements: []const ast.Stmt = &.{};
        args[offset + 1] = if ((try self.borrowedReceiverPointee(receiver_node)) != null)
            receiver
        else if (exprIsAddressable(receiver))
            .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(receiver) } }
        else blk: {
            const name = try self.iteratorTemporaryName("__r2z_hash_borrow");
            const binding = try self.alloc.alloc(ast.Stmt, 1);
            binding[0] = .{ .let_stmt = .{
                .name = name,
                .ty = try self.lowerType(hashed_type),
                .init = receiver,
                .is_mut = false,
            } };
            statements = binding;
            break :blk .{ .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(.{ .ident = name }),
            } };
        };
        const operation = try self.lowerDirectCallResult(node, .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = walk.value }),
            .generic_args = generic_args,
            .args = args,
        } }, walk.is_allocating, walk.is_fallible);
        if (statements.len == 0) return operation;
        return .{ .block = .{ .stmts = statements, .expr = try self.allocExpr(operation) } };
    }

    /// Select only canonical source-trait declarations. A same-named inherent
    /// member is not evidence that the source supplied a trait override.
    fn hashWalkTraitCall(
        self: *Lowerer,
        trait_name: []const u8,
        method_name: []const u8,
        receiver_type: ast.Expr,
        receiver: ast.Expr,
        args: []const ast.Expr,
        generic_args: []const ast.Type,
        fallback: ast.Expr,
    ) anyerror!ast.Expr {
        var result = fallback;
        var matches: std.ArrayListUnmanaged(ir.types.Type) = .empty;
        defer matches.deinit(self.alloc);
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            if (!ir.bodies.boundPathMatches(
                &self.ir.graph,
                entity.id,
                trait_path,
                &.{ "core", "hash", trait_name },
            )) continue;
            const method_id = self.blanketImplMethod(entity.id, method_name) orelse continue;
            if (!self.descriptorTypeIsConcrete(impl_body.self_ty)) continue;
            for (matches.items) |matched| {
                if (typeEquals(matched, impl_body.self_ty)) return error.AmbiguousTraitImplMatch;
            }
            try matches.append(self.alloc, impl_body.self_ty);
            const method = self.ir.graph.symbol_table.get(method_id) orelse return error.MissingDefinition;
            if (method_id >= self.ir.bodies.bodies.len) return error.MissingBodyId;
            const body = switch (self.ir.bodies.bodies[method_id]) {
                .fn_ => |body| body,
                else => return error.DeclarationBodyMismatch,
            };
            const allocates = self.hoistedMethodTakesAllocator(method_id);
            const takes_self = body.params.len != 0 and std.mem.eql(u8, body.params[0].name, "self");
            const argument_offset: usize = @intFromBool(allocates) + @intFromBool(takes_self);
            const call_args = try self.alloc.alloc(ast.Expr, args.len + argument_offset);
            if (allocates) call_args[0] = .{ .ident = "allocator" };
            if (takes_self) call_args[@intFromBool(allocates)] = receiver;
            @memcpy(call_args[argument_offset..], args);
            const callee = if (moduleHoistedImplMethod(self, method_id) != null)
                try self.lowerResolvedEntity(method_id)
            else
                ast.Expr{ .field_access = .{
                    .target = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                    .field_name = self.hoisted_method_names.get(method_id) orelse
                        (method.renamed_to orelse method.name),
                } };
            if (body.generic_params.len != 0 and body.generic_params.len != generic_args.len)
                return error.UnsupportedGenericTraitImpl;
            const operation: ast.Expr = .{ .call = .{
                .callee = try self.allocExpr(callee),
                .generic_args = if (body.generic_params.len == 0) &.{} else try self.alloc.dupe(ast.Type, generic_args),
                .args = call_args,
            } };
            const previous_result = try self.allocExpr(result);
            result = .{ .if_expr = .{
                .cond = try self.allocExpr(.{ .bin_op = .{
                    .op = .equal,
                    .lhs = try self.allocExpr(receiver_type),
                    .rhs = try self.allocExpr(.{ .type_value = try self.lowerType(impl_body.self_ty) }),
                } }),
                .then_body = try self.allocExpr(if (self.callableFallible(method_id))
                    .{ .unary_op = .{ .op = .try_op, .operand = try self.allocExpr(operation) } }
                else
                    operation),
                .else_body = previous_result,
            } };
        }
        return result;
    }

    // Canonical Hash defaults recurse through original borrowed source values.
    fn hashTypeParamExpr(self: *Lowerer, name: []const u8) anyerror!ast.Expr {
        return .{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) }),
            .field_name = "Type",
        } };
    }

    fn hashLayoutParamExpr(self: *Lowerer, name: []const u8) anyerror!ast.Expr {
        return .{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) }),
            .field_name = "Layout",
        } };
    }

    fn hashSingleArg(self: *Lowerer, argument: ast.Expr) anyerror![]const ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = argument;
        return args;
    }

    fn hashTwoArgs(self: *Lowerer, first: ast.Expr, second: ast.Expr) anyerror![]const ast.Expr {
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = first;
        args[1] = second;
        return args;
    }

    fn hashSingleStmt(self: *Lowerer, body: ast.Expr) anyerror![]const ast.Stmt {
        const statements = try self.alloc.alloc(ast.Stmt, 1);
        statements[0] = .{ .expr_stmt = try self.allocExpr(body) };
        return statements;
    }

    fn hashDeref(self: *Lowerer, name: []const u8) anyerror!ast.Expr {
        return .{ .unary_op = .{
            .op = .deref,
            .operand = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) }),
        } };
    }

    fn hashAddress(self: *Lowerer, operand: ast.Expr) anyerror!ast.Expr {
        return .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(operand),
        } };
    }

    fn hashArm(
        self: *Lowerer,
        tag: []const u8,
        capture: ?[]const u8,
        body: ast.Expr,
    ) anyerror!ast.MatchArm {
        const patterns = try self.alloc.alloc(ast.Pattern, 1);
        patterns[0] = .{ .enum_literal = try self.alloc.dupe(u8, tag) };
        return .{
            .patterns = patterns,
            .capture = if (capture) |name| .{
                .name = try self.alloc.dupe(u8, name),
                .by_ref = false,
            } else null,
            .body = body,
        };
    }

    fn hashWildcardArm(self: *Lowerer, body: ast.Expr) anyerror!ast.MatchArm {
        const patterns = try self.alloc.alloc(ast.Pattern, 1);
        patterns[0] = .wildcard;
        return .{ .patterns = patterns, .body = body };
    }

    fn hashState(_: *Lowerer) anyerror!ast.Expr {
        return .{ .ident = "state" };
    }

    fn hashValueLen(self: *Lowerer) anyerror!ast.Expr {
        return .{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = "value" }),
            .field_name = "len",
        } };
    }

    fn hashRefuse(self: *Lowerer, message: []const u8) anyerror!ast.Expr {
        return .{ .builtin = .{
            .name = "compileError",
            .args = try self.hashSingleArg(.{ .lit = .{ .str = try self.alloc.dupe(u8, message) } }),
        } };
    }

    fn hashHasherWriteCall(
        self: *Lowerer,
        method: []const u8,
        argument: ast.Expr,
        fallback: ast.Expr,
    ) anyerror!ast.Expr {
        return self.hashWalkTraitCall(
            "Hasher",
            method,
            .{ .type_value = .{ .named = "H" } },
            try self.hashState(),
            try self.hashSingleArg(argument),
            &.{},
            fallback,
        );
    }

    fn hashCanonicalBytesCall(self: *Lowerer, operand: ast.Expr) anyerror!ast.Expr {
        const as_bytes: ast.Expr = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "std.mem.asBytes" }),
            .args = try self.hashSingleArg(try self.hashAddress(operand)),
        } };
        return self.hashHasherWriteCall(
            "write",
            as_bytes,
            try self.hashRefuse("no canonical impl of core::hash::Hasher::write"),
        );
    }

    fn hashWalkRecursion(
        self: *Lowerer,
        callee_name: []const u8,
        descriptor: []const u8,
        hasher: []const u8,
        value: ast.Expr,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        const generic_args = try self.alloc.alloc(ast.Type, 2);
        generic_args[0] = .{ .named = try self.alloc.dupe(u8, descriptor) };
        generic_args[1] = .{ .named = try self.alloc.dupe(u8, hasher) };
        const call_args = try self.alloc.alloc(ast.Expr, 2 + @as(usize, @intFromBool(request.is_allocating)));
        var next: usize = 0;
        if (request.is_allocating) {
            call_args[next] = .{ .ident = "allocator" };
            next += 1;
        }
        call_args[next] = try self.hashState();
        call_args[next + 1] = value;
        const call: ast.Expr = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, callee_name) }),
            .generic_args = generic_args,
            .args = call_args,
        } };
        if (!request.is_fallible) return call;
        return .{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(call),
        } };
    }

    fn hashBorrowType(self: *Lowerer, descriptor: []const u8) anyerror!ast.Type {
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = .{ .lit = .{ .bool_lit = false } };
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = .{ .named = try self.alloc.dupe(u8, descriptor) };
        try self.markRuntimeImport();
        return .{ .expr = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .ident = hash_reference_runtime }),
            .generic_args = generic_args,
            .args = args,
        } }) };
    }

    fn hashItemsType(self: *Lowerer) anyerror!ast.Type {
        return .{ .slice = .{
            .elem = try self.allocType(.{ .expr = try self.allocExpr(try self.hashTypeParamExpr("C")) }),
            .is_const = true,
        } };
    }

    fn hashPairBlock(self: *Lowerer, first: ast.Expr, second: ast.Expr) anyerror!ast.Expr {
        const statements = try self.alloc.alloc(ast.Stmt, 2);
        statements[0] = .{ .expr_stmt = try self.allocExpr(first) };
        statements[1] = .{ .expr_stmt = try self.allocExpr(second) };
        return .{ .block = .{ .stmts = statements } };
    }

    fn hashTypedBytesWrite(
        self: *Lowerer,
        name: []const u8,
        prim: ast.Prim,
        initial_value: ast.Expr,
    ) anyerror!ast.Expr {
        const write = try self.hashCanonicalBytesCall(.{ .ident = name });
        const statements = try self.alloc.alloc(ast.Stmt, 2);
        statements[0] = .{ .let_stmt = .{
            .name = name,
            .ty = .{ .prim = prim },
            .init = initial_value,
            .is_mut = false,
        } };
        statements[1] = .{ .expr_stmt = try self.allocExpr(write) };
        return .{ .block = .{ .stmts = statements } };
    }

    fn hashStdMetaFields(self: *Lowerer) anyerror!ast.Expr {
        const callee = try self.allocExpr(.{ .field_access = .{
            .target = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(.{ .ident = "std" }),
                .field_name = "meta",
            } }),
            .field_name = "fields",
        } });
        return .{ .call = .{
            .callee = callee,
            .args = try self.hashSingleArg(.{ .builtin = .{
                .name = "TypeOf",
                .args = try self.hashSingleArg(try self.hashDeref("value")),
            } }),
        } };
    }

    fn hashScalarMethodName(self: *Lowerer, entry: HashPrimitiveDefault) ![]const u8 {
        if (entry.written == .unit) return "";
        return std.fmt.allocPrint(self.alloc, "write_{s}", .{@tagName(entry.written)});
    }

    fn hashLengthPrefix(self: *Lowerer, length: ast.Expr) anyerror!ast.Expr {
        return self.hashHasherWriteCall(
            "write_length_prefix",
            length,
            try self.hashHasherWriteCall(
                "write_usize",
                length,
                try self.hashTypedBytesWrite("__r2z_hash_length", .usize, length),
            ),
        );
    }

    fn hashArrayView(self: *Lowerer) anyerror!ast.Expr {
        const bounds = try self.allocExpr(.{ .range = .{
            .start = try self.allocExpr(.{ .lit = .{ .uint = 0 } }),
            .end = null,
        } });
        const base = try self.allocExpr(try self.hashDeref("value"));
        return self.indexSliceExpr(base, bounds);
    }

    fn hashWalkRetType(self: *Lowerer, request: HashWalkRequest) anyerror!ast.Type {
        if (!request.is_fallible) return .{ .prim = .void_type };
        return .{ .err_union = .{
            .err_set = "anyerror",
            .payload = try self.allocType(.{ .prim = .void_type }),
        } };
    }

    fn hashScalarProng(self: *Lowerer) anyerror!ast.Expr {
        const arms = try self.alloc.alloc(ast.MatchArm, hash_primitive_defaults.len);
        for (hash_primitive_defaults, 0..) |entry, index| {
            if (entry.hashed == .unit) {
                arms[index] = try self.hashArm(
                    @tagName(entry.hashed),
                    null,
                    .{ .block = .{ .stmts = &.{} } },
                );
                continue;
            }
            const operand = try self.hashDeref("value");
            const call_argument: ast.Expr = if (entry.hashed == entry.written)
                operand
            else
                try self.scalarCast(
                    .{ .prim = entry.hashed },
                    .{ .prim = entry.written },
                    operand,
                );
            const fallback: ast.Expr = if (entry.hashed == entry.written)
                try self.hashCanonicalBytesCall(operand)
            else
                try self.hashTypedBytesWrite(
                    "__r2z_hash_scalar",
                    switch (entry.written) {
                        .u8 => .u8,
                        .u32 => .u32,
                        else => unreachable,
                    },
                    call_argument,
                );
            arms[index] = try self.hashArm(
                @tagName(entry.hashed),
                null,
                try self.hashHasherWriteCall(
                    try self.hashScalarMethodName(entry),
                    call_argument,
                    fallback,
                ),
            );
        }
        return .{ .match_expr = .{
            .target = try self.allocExpr(.{ .ident = "Primitive" }),
            .arms = arms,
        } };
    }

    fn hashStringArm(self: *Lowerer) anyerror!ast.MatchArm {
        const terminator = ast.Expr{ .lit = .{ .uint = 0xff } };
        const write = try self.hashHasherWriteCall(
            "write",
            .{ .ident = "value" },
            try self.hashRefuse("no canonical impl of core::hash::Hasher::write"),
        );
        const term = try self.hashHasherWriteCall(
            "write_u8",
            terminator,
            try self.hashTypedBytesWrite("__r2z_hash_terminator", .u8, terminator),
        );
        return self.hashArm("str", null, try self.hashHasherWriteCall(
            "write_str",
            .{ .ident = "value" },
            try self.hashPairBlock(
                write,
                term,
            ),
        ));
    }

    fn hashSliceProng(
        self: *Lowerer,
        slice_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        const prefix = try self.hashLengthPrefix(try self.hashValueLen());
        const elements = try self.hashWalkRecursion(
            slice_name,
            "Element",
            "H",
            .{ .ident = "value" },
            request,
        );
        return self.hashPairBlock(
            prefix,
            elements,
        );
    }

    fn hashArrayProng(
        self: *Lowerer,
        slice_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        const array_value = try self.hashDeref("value");
        const array_length = ast.Expr{ .field_access = .{
            .target = try self.allocExpr(array_value),
            .field_name = "len",
        } };
        const by_array = try self.hashPairBlock(
            try self.hashLengthPrefix(array_length),
            try self.hashWalkRecursion(
                slice_name,
                "Element",
                "H",
                try self.hashArrayView(),
                request,
            ),
        );
        const by_slice = try self.hashPairBlock(
            try self.hashLengthPrefix(array_length),
            try self.hashWalkRecursion(
                slice_name,
                "Element",
                "H",
                array_value,
                request,
            ),
        );

        const arms = try self.alloc.alloc(ast.MatchArm, 3);
        arms[0] = try self.hashArm("array", null, by_array);
        arms[1] = try self.hashArm("pointer", null, by_slice);
        arms[2] = try self.hashWildcardArm(.{ .builtin = .{
            .name = "compileError",
            .args = try self.hashSingleArg(.{
                .lit = .{ .str = "Rust array Hash needs an array or slice runtime type" },
            }),
        } });
        const info = try self.allocExpr(.{ .builtin = .{
            .name = "typeInfo",
            .args = try self.hashSingleArg(try self.hashTypeParamExpr("D")),
        } });
        return .{ .match_expr = .{
            .target = info,
            .arms = arms,
        } };
    }

    fn hashTupleProng(
        self: *Lowerer,
        value_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        const binding = try self.alloc.alloc(ast.Stmt, 1);
        binding[0] = .{ .let_stmt = .{
            .name = "Slots",
            .ty = null,
            .init = try self.hashStdMetaFields(),
            .is_mut = false,
        } };

        const slot_name = ast.Expr{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = "Slot" }),
            .field_name = "name",
        } };
        const field_of_tuple = try self.allocExpr(.{ .builtin = .{
            .name = "field",
            .args = try self.hashTwoArgs(
                try self.hashDeref("value"),
                slot_name,
            ),
        } });
        const recurse = try self.hashWalkRecursion(
            value_name,
            "Field",
            "H",
            try self.hashAddress(field_of_tuple.*),
            request,
        );

        const inputs = try self.alloc.alloc(ast.Expr, 2);
        inputs[0] = .{ .ident = "Fields" };
        inputs[1] = .{ .ident = "Slots" };
        const captures = try self.alloc.alloc(ast.Capture, 2);
        captures[0] = .{ .name = "Field" };
        captures[1] = .{ .name = "Slot" };
        const body = try self.hashSingleStmt(recurse);

        const statements = try self.alloc.alloc(ast.Stmt, 2);
        statements[0] = binding[0];
        statements[1] = .{ .expr_stmt = try self.allocExpr(.{ .for_expr = .{
            .inputs = inputs,
            .captures = captures,
            .body = .{ .stmts = body },
            .is_inline = true,
        } }) };
        return .{ .block = .{ .stmts = statements } };
    }

    fn hashReferenceProng(
        self: *Lowerer,
        value_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        return self.hashWalkRecursion(
            value_name,
            "Pointee",
            "H",
            try self.hashDeref("value"),
            request,
        );
    }

    fn hashRawPointerProng(self: *Lowerer) anyerror!ast.Expr {
        const view = try self.hashDeref("value");
        const fat_address: ast.Expr = .{ .builtin = .{
            .name = "intFromPtr",
            .args = try self.hashSingleArg(.{ .field_access = .{
                .target = try self.allocExpr(view),
                .field_name = "ptr",
            } }),
        } };
        const fat_length: ast.Expr = .{ .field_access = .{
            .target = try self.allocExpr(view),
            .field_name = "len",
        } };
        const fat = try self.hashPairBlock(
            try self.hashHasherWriteCall(
                "write_usize",
                fat_address,
                try self.hashTypedBytesWrite("__r2z_hash_address", .usize, fat_address),
            ),
            try self.hashHasherWriteCall(
                "write_usize",
                fat_length,
                try self.hashTypedBytesWrite("__r2z_hash_metadata", .usize, fat_length),
            ),
        );
        const thin_address: ast.Expr = .{ .builtin = .{
            .name = "intFromPtr",
            .args = try self.hashSingleArg(view),
        } };
        const thin = try self.hashHasherWriteCall(
            "write_usize",
            thin_address,
            try self.hashTypedBytesWrite("__r2z_hash_address", .usize, thin_address),
        );
        const arms = try self.alloc.alloc(ast.MatchArm, 3);
        arms[0] = try self.hashArm("str", null, fat);
        arms[1] = try self.hashArm("slice", null, fat);
        arms[2] = try self.hashWildcardArm(thin);
        return .{ .match_expr = .{
            .target = try self.allocExpr(try self.hashLayoutParamExpr("Pointee")),
            .arms = arms,
        } };
    }

    fn hashNominalProng(self: *Lowerer) anyerror!ast.MatchArm {
        return self.hashArm("nominal", null, try self.hashRefuse(
            "no source Hash impl for this type",
        ));
    }

    fn hashBulkSwitch(
        self: *Lowerer,
        value_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        var bulk_count: usize = 0;
        for (hash_primitive_defaults) |entry| {
            if (entry.hashed == .unit or entry.hashed == .bool or entry.hashed == .char) continue;
            bulk_count += 1;
        }
        const bulk = try self.hashHasherWriteCall(
            "write",
            .{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .field_access = .{
                        .target = try self.allocExpr(.{ .ident = "std" }),
                        .field_name = "mem",
                    } }),
                    .field_name = "sliceAsBytes",
                } }),
                .args = try self.hashSingleArg(.{ .ident = "items" }),
            } },
            try self.hashRefuse("no canonical impl of core::hash::Hasher::write"),
        );

        const arms = try self.alloc.alloc(ast.MatchArm, bulk_count + 1);
        var next: usize = 0;
        for (hash_primitive_defaults) |entry| {
            if (entry.hashed == .unit or entry.hashed == .bool or entry.hashed == .char) continue;
            arms[next] = try self.hashArm(@tagName(entry.hashed), null, bulk);
            next += 1;
        }
        arms[next] = try self.hashWildcardArm(
            try self.hashElementLoop(value_name, request),
        );
        return .{ .match_expr = .{
            .target = try self.allocExpr(.{ .ident = "Primitive" }),
            .arms = arms,
        } };
    }

    fn hashElementLoop(
        self: *Lowerer,
        value_name: []const u8,
        request: HashWalkRequest,
    ) anyerror!ast.Expr {
        const forward = try self.hashWalkRecursion(
            value_name,
            "C",
            "H",
            .{ .ident = "item" },
            request,
        );
        const captures = try self.alloc.alloc(ast.Capture, 1);
        captures[0] = .{ .name = "item", .by_ref = true };
        const body = try self.hashSingleStmt(forward);
        return .{ .for_expr = .{
            .inputs = try self.hashSingleArg(.{ .ident = "items" }),
            .captures = captures,
            .body = .{ .stmts = body },
        } };
    }

    fn lowerHashValueDecl(self: *Lowerer, request: HashWalkRequest) anyerror!ast.Decl {
        const generic_params = try self.alloc.alloc(ast.GenericParam, 2);
        generic_params[0] = .{ .name = "D", .is_comptime = true, .ty = null };
        generic_params[1] = .{ .name = "H", .is_comptime = true, .ty = null };

        const params = try self.alloc.alloc(ast.FnParam, 2 + @as(usize, @intFromBool(request.is_allocating)));
        var next: usize = 0;
        if (request.is_allocating) {
            params[next] = .{
                .name = "allocator",
                .ty = .{ .named = try self.alloc.dupe(u8, "std.mem.Allocator") },
            };
            next += 1;
        }
        params[next] = .{
            .name = "state",
            .ty = .{ .ptr = .{
                .elem = try self.allocType(.{ .named = "H" }),
                .is_const = false,
                .size = .one,
            } },
        };
        params[next + 1] = .{ .name = "value", .ty = try self.hashBorrowType("D") };

        const arms = try self.alloc.alloc(ast.MatchArm, 8);
        arms[0] = try self.hashArm("scalar", "Primitive", try self.hashScalarProng());
        arms[1] = try self.hashStringArm();
        arms[2] = try self.hashArm("slice", "Element", try self.hashSliceProng(request.slice_name, request));
        arms[3] = try self.hashArm("array", "Element", try self.hashArrayProng(request.slice_name, request));
        arms[4] = try self.hashArm("tuple", "Fields", try self.hashTupleProng(request.value_name, request));
        arms[5] = try self.hashArm("reference", "Pointee", try self.hashReferenceProng(request.value_name, request));
        arms[6] = try self.hashArm("raw_pointer", "Pointee", try self.hashRawPointerProng());
        arms[7] = try self.hashNominalProng();

        const derived = try self.allocExpr(.{ .match_expr = .{
            .target = try self.allocExpr(try self.hashLayoutParamExpr("D")),
            .arms = arms,
        } });

        const source_args = try self.hashSingleArg(try self.hashState());
        const source_generics = try self.alloc.alloc(ast.Type, 1);
        source_generics[0] = .{ .named = "H" };
        const body = try self.hashWalkTraitCall(
            "Hash",
            "hash",
            try self.hashTypeParamExpr("D"),
            .{ .ident = "value" },
            source_args,
            source_generics,
            derived.*,
        );

        const statements = try self.hashSingleStmt(body);
        return .{ .fn_decl = .{
            .name = request.value_name,
            .is_pub = false,
            .params = params,
            .ret_type = try self.hashWalkRetType(request),
            .body = .{ .stmts = statements },
            .generic_params = generic_params,
        } };
    }

    fn lowerHashSliceDecl(self: *Lowerer, request: HashWalkRequest) anyerror!ast.Decl {
        const generic_params = try self.alloc.alloc(ast.GenericParam, 2);
        generic_params[0] = .{ .name = "C", .is_comptime = true, .ty = null };
        generic_params[1] = .{ .name = "H", .is_comptime = true, .ty = null };

        const params = try self.alloc.alloc(ast.FnParam, 2 + @as(usize, @intFromBool(request.is_allocating)));
        var next: usize = 0;
        if (request.is_allocating) {
            params[next] = .{
                .name = "allocator",
                .ty = .{ .named = try self.alloc.dupe(u8, "std.mem.Allocator") },
            };
            next += 1;
        }
        params[next] = .{
            .name = "state",
            .ty = .{ .ptr = .{
                .elem = try self.allocType(.{ .named = "H" }),
                .is_const = false,
                .size = .one,
            } },
        };
        params[next + 1] = .{ .name = "items", .ty = try self.hashItemsType() };

        const bulk = try self.alloc.alloc(ast.MatchArm, 2);
        bulk[0] = try self.hashArm("scalar", "Primitive", try self.hashBulkSwitch(request.value_name, request));
        bulk[1] = try self.hashWildcardArm(try self.hashElementLoop(request.value_name, request));
        const default_walk = try self.allocExpr(.{ .match_expr = .{
            .target = try self.allocExpr(try self.hashLayoutParamExpr("C")),
            .arms = bulk,
        } });

        const override_args = try self.hashTwoArgs(
            .{ .ident = "items" },
            try self.hashState(),
        );
        const override_generics = try self.alloc.alloc(ast.Type, 1);
        override_generics[0] = .{ .named = "H" };
        const body = try self.hashWalkTraitCall(
            "Hash",
            "hash_slice",
            try self.hashTypeParamExpr("C"),
            .{ .unit = {} },
            override_args,
            override_generics,
            default_walk.*,
        );

        const statements = try self.hashSingleStmt(body);
        return .{ .fn_decl = .{
            .name = request.slice_name,
            .is_pub = false,
            .params = params,
            .ret_type = try self.hashWalkRetType(request),
            .body = .{ .stmts = statements },
            .generic_params = generic_params,
        } };
    }

    fn lowerGenericHasherWrite(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        call: ir.exprs.MethodCall,
        hasher: ast.Expr,
        hasher_node: ir.exprs.NodeId,
        write_name: []const u8,
        value: ast.Expr,
    ) anyerror!?ast.Expr {
        const receiver = try self.allocExpr(hasher);
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = value;
        return self.lowerGenericSourceMethodCall(node, .{
            .receiver = hasher_node,
            .receiver_mode = .mutable,
            .method = call.method,
            .args = &.{call.receiver},
            .generic_args = &.{},
        }, receiver, args, write_name);
    }
    fn lowerSourceReceiverCall(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        method_id: ir.spine.EntityId,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        argument_nodes: []const ir.exprs.NodeId,
        generic_parameters: []const ir.types.Type,
    ) anyerror!ast.Expr {
        const method = self.ir.graph.symbol_table.get(method_id) orelse return error.MissingDefinition;
        const allocates = self.hoistedMethodTakesAllocator(method_id);
        if (allocates) self.current_callable_is_allocating = true;
        const explicit_temporary_borrow = receiver.* == .unary_op and receiver.unary_op.op == .addr_of and
            !exprIsAddressable(receiver.unary_op.operand.*);
        const borrows_self = if (method_id < self.ir.bodies.bodies.len) switch (self.ir.bodies.bodies[method_id]) {
            .fn_ => |body| body.params.len != 0 and
                (body.params[0].ty == .reference or body.params[0].ty == .raw_ptr),
            else => false,
        } else false;
        const materialize = explicit_temporary_borrow or (borrows_self and
            (try self.borrowedReceiverPointee(receiver_node)) == null and !exprIsAddressable(receiver.*));
        var call_receiver = receiver;
        var materialized_value: ?*const ast.Expr = null;
        const statements = try self.alloc.alloc(ast.Stmt, @intFromBool(materialize));
        if (materialize) {
            const name = try self.iteratorTemporaryName("__r2z_source_receiver");
            statements[0] = .{ .let_stmt = .{
                .name = name,
                .init = if (explicit_temporary_borrow) receiver.unary_op.operand.* else receiver.*,
                .is_mut = true,
            } };
            materialized_value = try self.allocExpr(.{ .ident = name });
            call_receiver = try self.allocExpr(.{ .unary_op = .{ .op = .addr_of, .operand = materialized_value.? } });
        }
        const hoisted = moduleHoistedImplMethod(self, method_id);
        const call_args = if (hoisted != null)
            try self.hoistedSelfArguments(method_id, materialized_value orelse try self.lowerMemoryReceiver(receiver_node, receiver), args, allocates)
        else if (allocates) blk: {
            const with_allocator = try self.alloc.alloc(ast.Expr, args.len + 1);
            with_allocator[0] = .{ .ident = "allocator" };
            @memcpy(with_allocator[1..], args);
            break :blk with_allocator;
        } else args;
        const callee = if (hoisted) |method_fn|
            try self.allocExpr(try self.lowerResolvedEntity(method_fn))
        else
            try self.allocExpr(.{ .field_access = .{
                .target = call_receiver,
                .field_name = self.hoisted_method_names.get(method_id) orelse (method.renamed_to orelse method.name),
            } });
        const operation = try self.lowerDirectCallResult(node, .{ .call = .{
            .callee = callee,
            .generic_args = try self.lowerCallGenericArgs(node, method_id, argument_nodes, generic_parameters),
            .args = call_args,
        } }, allocates, self.callableFallible(method_id));
        if (!materialize) return operation;
        return .{ .block = .{ .stmts = statements, .expr = try self.allocExpr(operation) } };
    }

    /// A canonical Hasher call must use its source override even when an
    /// inherent method claims the same name. The default still writes native
    /// bytes, but through that exact trait's required `write` declaration.
    fn lowerHasherPrimitiveWrite(self: *Lowerer, node: ir.exprs.NodeId, call: ir.exprs.CoreCall) anyerror!ast.Expr {
        const receiver = try self.allocExpr(try self.lowerExpr(call.args[0]));
        const value = try self.lowerExpr(call.args[1]);
        const receiver_type = if (try self.exprType(call.args[0])) |ty| peelReceiverType(ty) else null;
        const primitive_name = try std.fmt.allocPrint(self.alloc, "write_{s}", .{@tagName(call.generic_args[0].prim)});
        const source = if (receiver_type) |actual|
            (try self.sourceHasherWrites(actual, primitive_name)) orelse SourceHasherWrites{}
        else
            SourceHasherWrites{};
        return self.lowerHasherValueWrite(node, call.generic_args[0], source, call.args[0], receiver.*, value, call.args[1..]);
    }

    const SourceHasherWrites = struct {
        primitive_write: ?ir.spine.EntityId = null,
        byte_write: ?ir.spine.EntityId = null,
    };

    fn sourceHasherWrites(
        self: *const Lowerer,
        hasher_type: ir.types.Type,
        primitive_name: []const u8,
    ) anyerror!?SourceHasherWrites {
        if (isTypeParameterPath(hasher_type)) return null;
        var found: ?SourceHasherWrites = null;
        for (self.ir.graph.symbol_table.entities.items) |entity| {
            if (entity.kind != .impl_ or entity.id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[entity.id]) {
                .impl_ => |body| body,
                else => continue,
            };
            if (!typeEquals(hasher_type, impl_body.self_ty)) continue;
            const trait_path = impl_body.trait_path orelse continue;
            if (!ir.bodies.boundPathMatches(&self.ir.graph, entity.id, trait_path, &.{ "core", "hash", "Hasher" })) continue;
            if (found) |earlier| {
                if (earlier.primitive_write != null or earlier.byte_write != null)
                    return error.AmbiguousTraitImplMatch;
            }
            found = .{
                .primitive_write = self.blanketImplMethod(entity.id, primitive_name),
                .byte_write = self.blanketImplMethod(entity.id, "write"),
            };
        }
        return found;
    }

    fn lowerHasherValueWrite(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        written: ir.types.Type,
        source: SourceHasherWrites,
        receiver_node: ir.exprs.NodeId,
        receiver: ast.Expr,
        value: ast.Expr,
        value_nodes: []const ir.exprs.NodeId,
    ) anyerror!ast.Expr {
        if (source.primitive_write) |method_id| {
            const arguments = try self.alloc.alloc(ast.Expr, 1);
            errdefer self.alloc.free(arguments);
            arguments[0] = value;
            return self.lowerSourceReceiverCall(
                node,
                method_id,
                receiver_node,
                try self.allocExpr(receiver),
                arguments,
                value_nodes,
                &.{},
            );
        }
        return self.lowerHasherDefaultWrite(node, written, receiver, value, source.byte_write, receiver_node);
    }

    fn lowerHasherDefaultWrite(
        self: *Lowerer,
        node: ir.exprs.NodeId,
        integer: ir.types.Type,
        receiver_value: ast.Expr,
        value: ast.Expr,
        source_write: ?ir.spine.EntityId,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!ast.Expr {
        const name = try std.fmt.allocPrint(self.alloc, "__r2z_hash_value_{d}", .{node});
        var receiver = receiver_value;
        const bind_receiver = receiver != .ident;
        const temporary_borrow = receiver == .unary_op and receiver.unary_op.op == .addr_of and
            !exprIsAddressable(receiver.unary_op.operand.*);
        const borrowed_handle = !temporary_borrow and (try self.borrowedReceiverPointee(receiver_node)) != null;
        const place_handle = bind_receiver and !borrowed_handle and exprIsAddressable(receiver);
        const statements = try self.alloc.alloc(ast.Stmt, if (bind_receiver) 3 else 2);
        if (bind_receiver) {
            const receiver_name = try self.iteratorTemporaryName("__r2z_hash_receiver");
            statements[0] = .{ .let_stmt = .{
                .name = receiver_name,
                .ty = null,
                .init = if (temporary_borrow) receiver.unary_op.operand.* else if (place_handle) .{ .unary_op = .{
                    .op = .addr_of,
                    .operand = try self.allocExpr(receiver),
                } } else receiver,
                .is_mut = !borrowed_handle and !place_handle,
            } };
            receiver = .{ .ident = receiver_name };
        }
        statements[@intFromBool(bind_receiver)] = .{ .let_stmt = .{
            .name = name,
            .ty = try self.lowerType(integer),
            .init = value,
            .is_mut = false,
        } };
        const bytes_args = try self.alloc.alloc(ast.Expr, 1);
        bytes_args[0] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(.{ .ident = name }),
        } };
        const write_args = try self.alloc.alloc(ast.Expr, 1);
        write_args[0] = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "std.mem.asBytes" }),
            .args = bytes_args,
        } };
        const allocates = if (source_write) |method_id| self.hoistedMethodTakesAllocator(method_id) else false;
        if (allocates) self.current_callable_is_allocating = true;
        const hoisted = if (source_write) |method_id| moduleHoistedImplMethod(self, method_id) else null;
        const call_args = if (hoisted) |method_id|
            try self.hoistedSelfArguments(
                method_id,
                if (temporary_borrow)
                    try self.allocExpr(receiver)
                else if (place_handle)
                    try self.allocExpr(.{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(receiver) } })
                else
                    try self.lowerMemoryReceiver(receiver_node, try self.allocExpr(receiver)),
                write_args,
                allocates,
            )
        else if (allocates) blk: {
            const arguments = try self.alloc.alloc(ast.Expr, 2);
            arguments[0] = .{ .ident = "allocator" };
            arguments[1] = write_args[0];
            break :blk arguments;
        } else write_args;
        const callee = if (hoisted) |method_id|
            try self.allocExpr(try self.lowerResolvedEntity(method_id))
        else
            try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(if (bind_receiver and !borrowed_handle and !place_handle)
                    .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(receiver) } }
                else
                    receiver),
                .field_name = if (source_write) |method_id| self.hoisted_method_names.get(method_id) orelse "write" else "write",
            } });
        const operation: ast.Expr = .{ .call = .{ .callee = callee, .args = call_args } };
        statements[statements.len - 1] = .{ .expr_stmt = try self.allocExpr(
            if (source_write) |method_id|
                try self.lowerDirectCallResult(node, operation, allocates, self.callableFallible(method_id))
            else
                operation,
        ) };
        return .{ .block = .{ .stmts = statements } };
    }

    fn referenceMatchCapture(self: *Lowerer, patterns: []const ir.exprs.NodeId) anyerror!?ast.Capture {
        if (patterns.len != 1) return null;
        if (patterns[0] >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const fields = switch (self.ir.bodies.pats[patterns[0]].kind) {
            .struct_pat => |pattern| pattern.fields,
            .external_variant => |pattern| pattern.fields,
            else => return null,
        };
        if (fields.len != 1) return null;
        const id = fields[0].pat orelse return null;
        if (id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const binding = switch (self.ir.bodies.pats[id].kind) {
            .binding => |value| value,
            else => return null,
        };
        if (binding.mode == .value) return null;
        if (!std.mem.eql(u8, fields[0].field, "0")) return error.UnsupportedPattern;
        return .{ .name = try self.patternName(id), .by_ref = true };
    }

    fn formatArgumentType(self: *Lowerer, expr_id: ir.exprs.NodeId) anyerror!?ir.types.Type {
        if (expr_id >= self.ir.bodies.exprs.len) return null;
        const expr = self.ir.bodies.exprs[expr_id];
        switch (expr.kind) {
            .literal => |literal| switch (literal) {
                .character => return .{ .prim = .char },
                .int => |integer| if (integer.ty_suffix) |suffix| {
                    const primitive: ?ir.types.Prim =
                        if (std.mem.eql(u8, suffix, "i8")) .i8 else if (std.mem.eql(u8, suffix, "i16")) .i16 else if (std.mem.eql(u8, suffix, "i32")) .i32 else if (std.mem.eql(u8, suffix, "i64")) .i64 else if (std.mem.eql(u8, suffix, "i128")) .i128 else if (std.mem.eql(u8, suffix, "isize")) .isize else if (std.mem.eql(u8, suffix, "u8")) .u8 else if (std.mem.eql(u8, suffix, "u16")) .u16 else if (std.mem.eql(u8, suffix, "u32")) .u32 else if (std.mem.eql(u8, suffix, "u64")) .u64 else if (std.mem.eql(u8, suffix, "u128")) .u128 else if (std.mem.eql(u8, suffix, "usize")) .usize else null;
                    if (primitive) |value| return .{ .prim = value };
                },
                else => {},
            },
            else => {},
        }
        if (expr.ty) |type_id| {
            const typed = try self.typeById(type_id);
            if (typed != .unsupported) return typed;
        }
        return self.exprType(expr_id);
    }
    fn lowerFormatArgument(self: *Lowerer, expr_id: ir.exprs.NodeId) anyerror!ast.Expr {
        const lowered = try self.lowerExpr(expr_id);
        if (expr_id >= self.ir.bodies.exprs.len) return lowered;
        const kind = self.ir.bodies.exprs[expr_id].kind;
        const is_literal = switch (kind) {
            .literal => |literal| switch (literal) {
                .int, .float, .character => true,
                else => false,
            },
            else => false,
        };
        if (!is_literal) return lowered;
        const source_type = try self.formatArgumentType(expr_id) orelse return lowered;
        const primitive = switch (source_type) {
            .prim => |value| value,
            else => return lowered,
        };
        switch (primitive) {
            .i8, .i16, .i32, .i64, .i128, .isize, .u8, .u16, .u32, .u64, .u128, .usize, .f32, .f64, .char => {},
            else => return lowered,
        }
        return .{ .cast = .{
            .target = try self.lowerType(source_type),
            .operand = try self.allocExpr(lowered),
        } };
    }

    fn lowerLocalClosureCall(
        self: *Lowerer,
        closure: ir.exprs.ClosureExpr,
        closure_name: []const u8,
        arg_id: ir.exprs.NodeId,
    ) anyerror!ast.Expr {
        if (closure.params.len != 1) return error.UnsupportedExpression;
        const argument = try self.lowerExpr(arg_id);
        var previous_overrides = self.active_closure_capture_overrides;
        self.active_closure_capture_overrides = .empty;
        defer {
            self.active_closure_capture_overrides.deinit(self.alloc);
            self.active_closure_capture_overrides = previous_overrides;
        }
        var previous_iterator = previous_overrides.iterator();
        while (previous_iterator.next()) |entry| {
            try self.active_closure_capture_overrides.put(
                self.alloc,
                entry.key_ptr.*,
                entry.value_ptr.*,
            );
        }
        const snapshots = self.local_closure_snapshots.get(closure_name) orelse &.{};
        // Each owning snapshot needs its own move sites before the body lowers.
        var owned_moves: std.ArrayListUnmanaged(OwnedCaptureMove) = .empty;
        defer {
            for (owned_moves.items) |*entry| entry.sites.deinit(self.alloc);
            owned_moves.deinit(self.alloc);
        }
        for (snapshots) |snapshot| {
            try self.active_closure_capture_overrides.put(
                self.alloc,
                snapshot.source_name,
                snapshot.snapshot_name,
            );
            const payload_type = snapshot.payload_type orelse continue;
            var moves = try self.collectOwnedCaptureMovesOverBlock(.{
                .source_name = snapshot.source_name,
                .capture_name = snapshot.snapshot_name,
                .alias_name = snapshot.snapshot_name,
                .payload_type = payload_type,
            }, closure.body);
            errdefer moves.sites.deinit(self.alloc);
            try owned_moves.append(self.alloc, moves);
        }
        const previous_move = self.active_owned_capture_move;
        defer self.active_owned_capture_move = previous_move;
        self.active_owned_capture_move = .{ .entries = owned_moves.items };
        const body = try self.lowerIteratorClosureBody(closure);
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        try self.appendIteratorClosureBindings(closure.params[0], argument, &statements);
        const scoped_statements = try statements.toOwnedSlice(self.alloc);
        const block: ast.Block = .{
            .stmts = scoped_statements,
            .expr = try self.allocExpr(body),
        };
        for (scoped_statements) |*statement| {
            if (statement.* == .let_stmt and statement.let_stmt.is_mut) {
                statement.let_stmt.is_mut = try astMutatesBinding(block, statement.let_stmt.name, 0);
            }
        }
        return .{ .block = block };
    }

    /// Return the inline closure carried by `arg_id`, if any.
    fn inlineClosureArgument(
        self: *const Lowerer,
        arg_id: ir.exprs.NodeId,
    ) ?ir.exprs.ClosureExpr {
        if (arg_id >= self.ir.bodies.exprs.len) return null;
        return switch (self.ir.bodies.exprs[arg_id].kind) {
            .closure => |closure| closure,
            else => null,
        };
    }

    /// Expand `Option::map`/`and_then` and `Result::map`/`map_err` whose
    /// mapper is an inline closure into an explicit `switch` over the receiver.
    ///
    /// This AST has no first-class closure: `r2z.option.map`/`and_then` and the
    /// `r2z.Result` methods forward their mapper to `invokeMapper`, which only
    /// accepts a `fn` or a struct exposing `call`, and neither a callable struct
    /// literal nor an `if` with a payload capture is representable. Expanding
    /// the combinator textually at the call site — the same trick
    /// `lowerLocalClosureCall` uses for let-bound closures — keeps the closure
    /// body's captures lexically in scope and mirrors `.iterator_chain`, which
    /// likewise replaces closure-taking adapters with explicit control flow.
    fn lowerInlineClosureCombinator(
        self: *Lowerer,
        method: RecognizedStdMethod,
        receiver_node: ir.exprs.NodeId,
        receiver: *const ast.Expr,
        closure: ir.exprs.ClosureExpr,
    ) anyerror!ast.Expr {
        if (closure.params.len != 1) return error.UnsupportedExpression;
        const value = try self.lowerMemoryReceiver(receiver_node, receiver);

        var previous_overrides = self.active_closure_capture_overrides;
        self.active_closure_capture_overrides = .empty;
        defer {
            self.active_closure_capture_overrides.deinit(self.alloc);
            self.active_closure_capture_overrides = previous_overrides;
        }
        var previous_iterator = previous_overrides.iterator();
        while (previous_iterator.next()) |entry| {
            try self.active_closure_capture_overrides.put(
                self.alloc,
                entry.key_ptr.*,
                entry.value_ptr.*,
            );
        }

        var prologue: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prologue.deinit(self.alloc);
        var owned_moves: std.ArrayListUnmanaged(OwnedCaptureMove) = .empty;
        defer {
            for (owned_moves.items) |*entry| entry.sites.deinit(self.alloc);
            owned_moves.deinit(self.alloc);
        }
        for (closure.captures) |capture| {
            if (capture.mode != .by_value) continue;
            const source_name = self.active_closure_capture_overrides.get(capture.name) orelse
                self.currentClosureBindingName(capture.name);
            const snapshot_name = try self.iteratorTemporaryName(try std.fmt.allocPrint(
                self.alloc,
                "__r2z_capture_inline_{d}_{s}",
                .{ receiver_node, capture.name },
            ));
            if (self.current_owner_reserved) |reserved| {
                try reserved.append(self.alloc, snapshot_name);
            }
            const resolved_type = try self.closureCapturePayloadType(capture, source_name);
            if (ownedRuntimeContainerType(resolved_type)) {
                try self.appendCaptureSnapshot(
                    &prologue,
                    snapshot_name,
                    capture,
                    source_name,
                    resolved_type,
                );
                var moves = try self.collectOwnedCaptureMovesOverBlock(.{
                    .source_name = capture.name,
                    .capture_name = snapshot_name,
                    .alias_name = snapshot_name,
                    .payload_type = resolved_type,
                }, closure.body);
                errdefer moves.sites.deinit(self.alloc);
                try owned_moves.append(self.alloc, moves);
            } else {
                try prologue.append(self.alloc, .{ .let_stmt = .{
                    .name = snapshot_name,
                    .init = .{ .ident = try self.alloc.dupe(u8, source_name) },
                    .is_mut = closure.trait == .fn_mut,
                } });
            }
            try self.active_closure_capture_overrides.put(
                self.alloc,
                capture.name,
                snapshot_name,
            );
        }

        // The receiver is read twice — once to test it, once to take the
        // payload — so a receiver that is a CALL is evaluated once here.
        // `self.inner.next()` advanced twice otherwise, and the iterator
        // consumed two bytes per element.
        // `Iterator::any` steps the receiver's OWN cursor, so it decides for
        // itself whether that cursor already has a home: this binding is for
        // the arms that read a receiver twice without moving it.
        var subject: *const ast.Expr = value;
        if (method != .iterator_any and switch (value.*) {
            .ident => false,
            else => true,
        }) {
            const subject_name = try self.iteratorTemporaryName("__r2z_option_subject");
            try prologue.append(self.alloc, .{ .let_stmt = .{
                .name = subject_name,
                .init = value.*,
            } });
            subject = try self.allocExpr(.{ .ident = subject_name });
        }

        const previous_move = self.active_owned_capture_move;
        defer self.active_owned_capture_move = previous_move;
        self.active_owned_capture_move = .{ .entries = owned_moves.items };
        const body = try self.lowerIteratorClosureBody(closure);
        const param_name = try self.closurePayloadName(closure.params[0]);
        const payload_name = try self.iteratorTemporaryName(try std.fmt.allocPrint(
            self.alloc,
            "__r2z_in_{s}",
            .{param_name},
        ));

        const expanded: ast.Expr = switch (method) {
            // Zig cannot `switch` an optional, so the old `null => null,
            // else => |p|` expansion emitted `switch (value)` over a `?T`
            // and never compiled. The optional `if` carries the same two
            // cases, and `r2z.option.unwrap` is the payload read-back the
            // `match` path already uses.
            .option_map, .option_and_then => blk: {
                var mapped = try self.lowerInlineClosureBody(closure.params[0], payload_name, body);
                if (mapped != .block) return error.UnsupportedExpression;
                try self.markRuntimeImport();
                const unwrap_args = try self.alloc.alloc(ast.Expr, 1);
                unwrap_args[0] = (try self.allocExpr(subject.*)).*;
                const rebind = try self.alloc.alloc(ast.Stmt, mapped.block.stmts.len + 1);
                rebind[0] = .{ .let_stmt = .{
                    .name = try self.alloc.dupe(u8, payload_name),
                    .init = (try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = "r2z.option.unwrap" }),
                        .args = unwrap_args,
                    } })).*,
                } };
                @memcpy(rebind[1..], mapped.block.stmts);
                mapped.block.stmts = rebind;
                break :blk .{ .if_expr = .{
                    .cond = try self.allocExpr(.{ .bin_op = .{
                        .op = .not_equal,
                        .lhs = try self.allocExpr(subject.*),
                        .rhs = try self.allocExpr(.{ .lit = .null_lit }),
                    } }),
                    .then_body = try self.allocExpr(mapped),
                    .else_body = try self.allocExpr(.{ .lit = .null_lit }),
                } };
            },
            .result_map, .result_map_err => blk: {
                const maps_ok = method == .result_map;
                const mapped_tag = if (maps_ok) "Ok" else "Err";
                const passthrough_tag = if (maps_ok) "Err" else "Ok";
                // The selector slices live on `self.alloc`, NOT on this
                // frame. `arms` below is heap-allocated and escapes into the
                // returned AST, where `StdImportDemand` walks it again long
                // after this function has returned; a `&.{...}` literal here
                // would hand that later pass a slice pointing into a dead
                // stack slot, and switching on the tag read back out of it is
                // what raised `switch on corrupt value`.
                const mapped_patterns = try self.alloc.alloc(ast.Pattern, 1);
                mapped_patterns[0] = .{ .enum_literal = mapped_tag };
                const passthrough_patterns = try self.alloc.alloc(ast.Pattern, 1);
                passthrough_patterns[0] = .{ .enum_literal = passthrough_tag };
                const error_payload = try self.iteratorTemporaryName(try std.fmt.allocPrint(
                    self.alloc,
                    "__r2z_in_{s}_err",
                    .{param_name},
                ));
                const mapped_payload = if (maps_ok) payload_name else error_payload;
                const passthrough_payload = if (maps_ok) error_payload else payload_name;
                const mapped = try self.lowerInlineClosureBody(
                    closure.params[0],
                    mapped_payload,
                    body,
                );
                // A `Result` payload has to be re-wrapped, and a `struct_init`
                // with fields but no type name is not a valid AST node, so the
                // mapped combinator's own `r2z.Result(..)` type is recomputed
                // from the receiver and the closure's return type.
                const result_info = (try self.taggedResultType(receiver_node)) orelse
                    return error.UnsupportedStandardMethod;
                const mapped_ty = if (closure.return_ty) |return_ty|
                    try self.typeById(return_ty)
                else if (maps_ok) result_info.ok else result_info.err;
                const rebuilt = try self.alloc.create(ir.types.Result);
                rebuilt.* = .{
                    .ok = if (maps_ok) mapped_ty else result_info.ok,
                    .err = if (maps_ok) result_info.err else mapped_ty,
                    .is_error_unionable = false,
                };
                const passthrough_fields = try self.alloc.alloc(ast.StructInitField, 1);
                passthrough_fields[0] = .{
                    .name = passthrough_tag,
                    .expr = .{ .ident = passthrough_payload },
                };
                const arms = try self.alloc.alloc(ast.MatchArm, 2);
                arms[0] = .{
                    .patterns = mapped_patterns,
                    .capture = .{ .name = mapped_payload },
                    .body = mapped,
                };
                arms[1] = .{
                    .patterns = passthrough_patterns,
                    .capture = .{ .name = passthrough_payload },
                    .body = .{ .struct_init = .{
                        .type_name = try self.lowerType(.{ .result = rebuilt }),
                        .fields = passthrough_fields,
                    } },
                };
                break :blk .{ .match_expr = .{
                    .target = subject,
                    .arms = arms,
                } };
            },
            // `Iterator::any` walks the receiver's own cursor and stops at
            // the first element whose predicate holds. Zig has no member
            // for it — the closure is the operation — so the walk is spelled
            // out: `next` on the receiver as it stands, the predicate in the
            // loop body, and an exit that leaves the cursor exactly where
            // Rust leaves it, past the element that answered `true`.
            .iterator_any => blk: {
                const cursor: *const ast.Expr = if (exprIsAddressable(value.*))
                    // A place — a binding, a field, an index, a dereference
                    // chain — is already somewhere the walk can step, and a
                    // copy of it would answer from a fresh full range while
                    // leaving the caller's cursor where it was.
                    value
                else
                    // Anything else is evaluated once into a local of its
                    // own, which is the value a `for` input would have been
                    // hoisted into anyway.
                    local_cursor: {
                        const cursor_name = try self.iteratorTemporaryName("__r2z_any_iter");
                        if (self.current_owner_reserved) |reserved| {
                            try reserved.append(self.alloc, cursor_name);
                        }
                        try prologue.append(self.alloc, .{ .let_stmt = .{
                            .name = cursor_name,
                            .init = value.*,
                            .is_mut = true,
                        } });
                        break :local_cursor try self.allocExpr(.{ .ident = cursor_name });
                    };
                const item_name = try self.iteratorTemporaryName("__r2z_any_item");
                const found_name = try self.iteratorTemporaryName("__r2z_any_found");
                if (self.current_owner_reserved) |reserved| {
                    try reserved.appendSlice(self.alloc, &.{ item_name, found_name });
                }
                try prologue.append(self.alloc, .{ .let_stmt = .{
                    .name = found_name,
                    .init = .{ .lit = .{ .bool_lit = false } },
                    .is_mut = true,
                } });

                const hit = try self.alloc.alloc(ast.Stmt, 2);
                hit[0] = .{ .assign = .{
                    .target = .{ .ident = found_name },
                    .val = .{ .lit = .{ .bool_lit = true } },
                    .op = .assign,
                } };
                hit[1] = .{ .expr_stmt = try self.allocExpr(.{ .break_expr = .{} }) };
                const predicate = try self.lowerIteratorPredicateBody(
                    closure.params[0],
                    body,
                    item_name,
                );
                const loop_body = try self.alloc.alloc(ast.Stmt, 1);
                loop_body[0] = .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
                    .cond = try self.allocExpr(predicate),
                    .then_body = try self.allocExpr(.{ .block = .{ .stmts = hit } }),
                } }) };
                const captures = try self.alloc.alloc([]const u8, 1);
                captures[0] = item_name;
                const step = try self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .field_access = .{
                        .target = try self.allocExpr(cursor.*),
                        .field_name = "next",
                    } }),
                    .args = &.{},
                } });
                try prologue.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .while_expr = .{
                    .cond = step,
                    .captures = captures,
                    .body = .{ .stmts = loop_body },
                } }) });
                break :blk ast.Expr{ .ident = found_name };
            },
            else => return error.UnsupportedStandardMethod,
        };
        if (prologue.items.len == 0) return expanded;
        return .{ .block = .{
            .stmts = try prologue.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(expanded),
        } };
    }

    /// Bind the combinator's captured payload to its Rust parameter name and
    /// re-derive the closure body as a self-contained block, so the body can
    /// be spliced into a switch prong.
    fn lowerInlineClosureBody(
        self: *Lowerer,
        param: ir.exprs.NodeId,
        payload_name: []const u8,
        body: ast.Expr,
    ) anyerror!ast.Expr {
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        try self.appendIteratorClosureBindings(
            param,
            .{ .ident = payload_name },
            &statements,
        );
        const scoped_statements = try statements.toOwnedSlice(self.alloc);
        const block: ast.Block = .{
            .stmts = scoped_statements,
            .expr = try self.allocExpr(body),
        };
        for (scoped_statements) |*statement| {
            if (statement.* == .let_stmt and statement.let_stmt.is_mut) {
                statement.let_stmt.is_mut = try astMutatesBinding(block, statement.let_stmt.name, 0);
            }
        }
        return .{ .block = block };
    }

    /// Lower an iterator adapter's inline closure into a block the adapter
    /// can splice into one of its own branches: the parameter's pattern bound
    /// to `item`, then the closure body's own statements, with its tail
    /// expression as the block's value.
    ///
    /// The binding follows the parameter PATTERN rather than the item's type,
    /// because the pattern is where the source wrote what it wanted: `|&b|`
    /// asks for the element the iterator yields dereferenced, and `|b|`
    /// names that element as it stands. A predicate body with statements —
    /// `|&b| { seen += 1; b == b'%' }` — keeps them, so a `FnMut` capture
    /// the body assigns to is still assigned where the caller can see it.
    fn lowerIteratorPredicateBody(
        self: *Lowerer,
        param: ir.exprs.NodeId,
        body: ast.Expr,
        item: []const u8,
    ) anyerror!ast.Expr {
        // The body arrives already lowered: the adapter lowering this serves
        // needed it for its own arms, and lowering the same closure twice
        // would mint a second set of names for one set of statements.
        const nested: ?ast.Block = switch (body) {
            .block => |value| value,
            else => null,
        };
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        try self.appendIteratorClosureBindings(param, .{ .ident = item }, &statements);
        if (nested) |inner| try statements.appendSlice(self.alloc, inner.stmts);
        const owned_statements = try statements.toOwnedSlice(self.alloc);
        const block: ast.Block = .{
            .stmts = owned_statements,
            .expr = if (nested) |inner| inner.expr else try self.allocExpr(body),
        };
        for (owned_statements) |*statement| {
            if (statement.* == .let_stmt and statement.let_stmt.is_mut) {
                statement.let_stmt.is_mut = try astMutatesBinding(block, statement.let_stmt.name, 0);
            }
        }
        return .{ .block = block };
    }

    /// The `Result` payload behind a pointer-like receiver, or null when the
    /// receiver is not a `Result`.
    ///
    /// A `Result` arrives under TWO spellings and this used to answer for only
    /// one of them. The IR's own `.result` descriptor is the tagged spelling;
    /// `core::result::Result` as an `.external_nominal` is what inference
    /// produces for `String::from_utf8` (`infer.zig`'s `knownCoreCallType
    /// .string_from_utf8`), and it is the spelling most corpus crates actually
    /// carry. The peel below reached `.result` and returned null on the
    /// nominal, so `lowerInlineClosureCombinator`'s `.result_map_err` arm
    /// raised `error.UnsupportedStandardMethod` over
    /// `String::from_utf8(..).map_err(..)?` — a method the frontend RESOLVED, so
    /// no `.unsupported` marker was ever emitted and the crate's boundary just
    /// moved instead of naming itself.
    ///
    /// The question is therefore not "which spelling?" but "is this a Result?",
    /// and this file already answers THAT in one place:
    /// `canonicalExternalMethodType` maps both `core::result::Result` and
    /// `std::result::Result` onto `.result`, and `lookupRecognizedStdMethod`
    /// reads it for exactly this reason. Asking the same question the same way
    /// is what makes the two recognisers agree; the alternative — admitting a
    /// second spelling only here — would leave them disagreeing somewhere
    /// further down the same path.
    fn taggedResultType(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!?ir.types.Result {
        var current = try self.exprType(receiver_node) orelse return null;
        for (0..128) |_| {
            switch (current) {
                .reference => |reference| current = reference.pointee,
                .boxed => |boxed| current = boxed.*,
                .@"opaque" => |opaque_type| {
                    current = (opaque_type.concrete orelse return null).*;
                },
                .result => |result| return result.*,
                .external_nominal => |external| {
                    // The same two arms `lowerExternalNominal` reads, so the
                    // combinator and the type lowering cannot disagree about
                    // which nominal is a Result. `is_error_unionable` is not
                    // invented here: it is answered by the same predicate the
                    // type lowering uses, because a nominal spelling records no
                    // flag of its own and guessing `true` would turn a tagged
                    // error enum into an error union that drops its payload.
                    if (self.canonicalExternalMethodType(current) != @as(?SyntheticExternalType, .result)) return null;
                    if (external.args.len != 2) return null;
                    return .{
                        .ok = external.args[0],
                        .err = external.args[1],
                        .is_error_unionable = self.errorTypeIsZigErrorSet(external.args[1]),
                    };
                },
                else => return null,
            }
        }
        return null;
    }

    fn lowerOptionalMatchArm(
        self: *Lowerer,
        patterns: []ast.Pattern,
        body: ast.Expr,
        subject: OptionalMatchSubject,
        capture: ?ast.Capture,
    ) anyerror!ast.Expr {
        var prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prelude.deinit(self.alloc);
        const value = try self.lowerOptionalMatchArmInto(patterns, body, subject, capture, &prelude);
        if (prelude.items.len == 0) return value;
        return .{ .block = .{
            .stmts = try prelude.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(value),
        } };
    }

    /// Rewrite an optional arm's selectors and read its payload back.
    ///
    /// The read-back is a statement rather than part of the arm's value,
    /// because an ordered chain runs it ahead of the guard: the guard reads
    /// the very binding it introduces. A single switch that has no guard keeps
    /// the two together in a block of its own, which is what
    /// `lowerOptionalMatchArm` builds over this one.
    ///
    /// `capture` is this arm's reference capture, which is what separates
    /// `Some(slot)` from `Some(ref mut slot)`: the first reads the payload out,
    /// the second borrows the place it already sits in.
    fn lowerOptionalMatchArmInto(
        self: *Lowerer,
        patterns: []ast.Pattern,
        body: ast.Expr,
        subject: OptionalMatchSubject,
        capture: ?ast.Capture,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!ast.Expr {
        var binding_name: ?[]const u8 = null;
        var binds_whole_value = false;
        for (patterns) |*pattern| {
            switch (pattern.*) {
                .struct_pat => |structure| {
                    if (!std.mem.eql(u8, structure.name orelse return error.MissingPatternName, "Some") or
                        structure.fields.len != 1) return error.UnsupportedPattern;
                    switch (structure.fields[0].pat) {
                        .binding => |name| binding_name = name,
                        .wildcard => {},
                        else => return error.UnsupportedPattern,
                    }
                    pattern.* = .{ .lit = .{ .bool_lit = true } };
                },
                .enum_literal => |name| {
                    if (!std.mem.eql(u8, name, "None")) return error.UnsupportedPattern;
                    pattern.* = .{ .lit = .{ .bool_lit = false } };
                },
                .binding => |name| {
                    binding_name = name;
                    binds_whole_value = true;
                    pattern.* = .wildcard;
                },
                .wildcard => {},
                else => return error.UnsupportedPattern,
            }
        }
        const name = binding_name orelse return body;
        if (patterns.len != 1) return error.UnsupportedPattern;
        const subject_value = try self.optionalSubjectValue(subject);
        const initializer: ast.Expr = if (binds_whole_value)
            subject_value
        else if (capture != null)
            // A reference binding is not a payload read at all: it names the
            // place the optional already holds, so the arm borrows that rather
            // than a copy of it.
            try self.optionPayloadPointer(subject)
        else blk: {
            // Zig has no optional destructuring, so the `Some(v)` payload is
            // read back through the runtime. Without this the emitted file
            // names `r2z.option.unwrap` while `imports` is empty, and the
            // package fails to compile on `use of undeclared identifier
            // 'r2z'`. Only the payload path emits the runtime call — a
            // `Some(_)` arm and an irrefutable binding do not — so the mark
            // belongs here and not at the top of the function.
            try self.markRuntimeImport();
            const args = try self.alloc.alloc(ast.Expr, 1);
            args[0] = subject_value;
            break :blk .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = "r2z.option.unwrap" }),
                .args = args,
            } };
        };
        try prelude.append(self.alloc, .{
            .let_stmt = .{
                .name = name,
                .init = initializer,
                // A reference binding names a BORROW, and Rust refuses to
                // reassign the binding itself — `entry = v` is `cannot assign to a
                // borrowed place` — so nothing can ever make this local mutable.
                // Writing through it is a write to the caller's storage, which
                // `astMutatesBinding` cannot tell apart: it follows a `.deref` so
                // that `t += v` on a big integer reads as a mutation. Zig rejects a
                // `var` it never sees mutated, so a by-reference payload stays
                // `const` however the arm writes through it.
                .is_mut = if (capture == null)
                    try astMutatesBinding(body, name, 0)
                else
                    false,
            },
        });
        return body;
    }

    /// The optional an arm reads: the bound local itself, or the place behind
    /// it when the match bound the scrutinee's address rather than a copy.
    ///
    /// Reading it either way is a read of the same optional, so an arm that
    /// takes the payload by value behaves identically under both forms.
    fn optionalSubjectValue(
        self: *Lowerer,
        subject: OptionalMatchSubject,
    ) anyerror!ast.Expr {
        if (!subject.by_place) return .{ .ident = subject.name };
        return .{ .unary_op = .{
            .op = .deref,
            .operand = try self.allocExpr(.{ .ident = subject.name }),
        } };
    }

    /// The address of the payload an optional arm binds BY REFERENCE.
    ///
    /// `Some(ref mut slot)` writes through `slot` into the storage the
    /// caller's own optional holds, so the binding has to be a pointer into
    /// that optional. Reading the payload out by value — the path every
    /// by-value arm takes — answers with a copy, and a write through it lands
    /// in this frame where the source cannot see it.
    ///
    /// The pointer capture is what gives the binding its type: a mutable place
    /// answers `*T` and a shared one `*const T`, which is exactly what the two
    /// bindings ask of the same caller's storage. The dispatch has already
    /// tested the optional, so the else arm is the unreachable one rather than
    /// a second way to answer.
    fn optionPayloadPointer(
        self: *Lowerer,
        subject: OptionalMatchSubject,
    ) anyerror!ast.Expr {
        // Without a place of its own there is nothing for the borrow to name,
        // which is the same shape Rust refuses to compile.
        if (!subject.by_place) return error.UnsupportedPattern;
        const payload_name = try self.iteratorTemporaryName("__r2z_option_payload");
        return .{ .if_expr = .{
            .cond = try self.allocExpr(try self.optionalSubjectValue(subject)),
            .then_capture = .{ .name = payload_name, .by_ref = true },
            .then_body = try self.allocExpr(.{ .ident = payload_name }),
            .else_body = try self.allocExpr(.{ .unreachable_ = {} }),
        } };
    }

    /// The Zig switch subject a `match` lowers to.
    ///
    /// Every dispatch of the ordered guarded chain needs its own subject node.
    /// The AST is a tree of arena pointers, so sharing one would make it a DAG
    /// for no gain; a shallow copy is enough because nothing rewrites a
    /// lowered expression in place.
    fn matchSubject(
        self: *Lowerer,
        option: ?OptionalMatchSubject,
        scrutinee: *const ast.Expr,
    ) anyerror!*const ast.Expr {
        if (option) |subject| return self.allocExpr(.{ .bin_op = .{
            .op = .not_equal,
            .lhs = try self.allocExpr(try self.optionalSubjectValue(subject)),
            .rhs = try self.allocExpr(.{ .lit = .null_lit }),
        } });
        return self.allocExpr(scrutinee.*);
    }

    /// Whether any arm carries a guard, which is what selects the ordered chain
    /// over the single switch.
    fn matchHasGuard(arms: []const ir.exprs.MatchArm) bool {
        for (arms) |arm| {
            if (arm.guard != null) return true;
        }
        return false;
    }

    /// Whether any arm binds the subject by reference.
    ///
    /// Such an arm takes the *address* of the matched value, so a dispatch for
    /// it has to name the scrutinee's own place. Rust only allows a reference
    /// binding on a place as well — a `ref mut` over a temporary is rejected —
    /// so naming the scrutinee there evaluates nothing twice.
    fn matchCapturesByReference(self: *Lowerer, arms: []const ir.exprs.MatchArm) anyerror!bool {
        for (arms) |arm| {
            const capture = try self.referenceMatchCapture(arm.patterns);
            if (capture) |value| {
                if (value.by_ref) return true;
            }
        }
        return false;
    }

    /// Whether these lowered selectors match every value.
    ///
    /// `emit.zig` collapses such a selector list to `else`, because a wildcard
    /// or a bare binding is a catch-all and anything beside it would be an
    /// unreachable prong. A dispatch built on one must leave out its own `else`
    /// prong for the same reason.
    fn armSelectorsIrrefutable(patterns: []const ast.Pattern) bool {
        var has_wildcard = patterns.len == 0;
        var selector_count: usize = 0;
        for (patterns) |pattern| {
            switch (pattern) {
                .wildcard => has_wildcard = true,
                .binding => {},
                else => selector_count += 1,
            }
        }
        return has_wildcard or selector_count == 0;
    }

    /// Whether an arm's lowered value can carry this arm's result out of the
    /// ordered chain.
    ///
    /// A body that leaves the function or the loop is not a value, and Zig
    /// rejects a `break` with no operand beside one that has a value. A block
    /// counts by what its tail produces, exactly as `emit.zig` reads it.
    fn matchYieldCarriesValue(value: ast.Expr) bool {
        return switch (value) {
            .return_expr, .break_expr, .continue_expr, .unreachable_, .panic_ => false,
            .block => |block| if (block.expr) |tail|
                matchYieldCarriesValue(tail.*)
            else
                false,
            else => true,
        };
    }

    /// Whether `emit.zig` would destructure this struct pattern into a labeled
    /// block of its own: more than a single tuple-element binding, with at
    /// least one field bound by a pattern binding.
    fn structPatternNeedsFieldBindings(struct_pattern: ast.StructPattern) bool {
        if (struct_pattern.fields.len == 1 and
            std.mem.eql(u8, struct_pattern.fields[0].name, "0") and
            struct_pattern.fields[0].pat == .binding)
        {
            return false;
        }
        for (struct_pattern.fields) |field| {
            if (field.pat == .binding) return true;
        }
        return false;
    }

    /// Whether this struct pattern names a variant inside its payload's own
    /// pattern: `Err(IoError(e))` is two tests, not one.
    fn structPatternHasNestedPayload(struct_pattern: ast.StructPattern) bool {
        for (struct_pattern.fields) |field| {
            if (field.pat == .struct_pat) return true;
        }
        return false;
    }

    /// Read a struct pattern's fields into `prelude` and return the selectors
    /// to dispatch on.
    ///
    /// The emitter's destructure block breaks out with the arm's own value, so
    /// it cannot also hold the `break` that hands that value to the ordered
    /// chain. An arm that would get one therefore names its payload in the
    /// prong and reads the fields here, ahead of the guard and the body. Every
    /// other arm keeps its lowered selectors, and with them the shape the
    /// emitter already produces.
    ///
    /// A field that is itself a payload pattern cannot be read here: the tag it
    /// names has not been tested yet, and reading a union field that is not
    /// active is what Zig refuses. It is reported as a nested dispatch instead,
    /// which the chain builds once the labels are known.
    fn bindMatchPatternFields(
        self: *Lowerer,
        lowered_patterns: []ast.Pattern,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
        nested: *?*NestedPayloadDispatch,
    ) anyerror![]ast.Pattern {
        var rewritten: std.ArrayListUnmanaged(ast.Pattern) = .empty;
        defer rewritten.deinit(self.alloc);
        var changed = false;
        for (lowered_patterns) |pattern| {
            const struct_pattern = switch (pattern) {
                .struct_pat => |value| value,
                else => {
                    try rewritten.append(self.alloc, pattern);
                    continue;
                },
            };
            if (!structPatternNeedsFieldBindings(struct_pattern) and
                !structPatternHasNestedPayload(struct_pattern))
            {
                try rewritten.append(self.alloc, pattern);
                continue;
            }
            changed = true;
            const payload_name = try self.iteratorTemporaryName("__r2z_match_payload");
            const selector: ast.Pattern = if (struct_pattern.name) |name|
                .{ .enum_literal = name }
            else
                .wildcard;
            try rewritten.append(self.alloc, selector);
            try rewritten.append(self.alloc, .{ .binding = payload_name });
            for (struct_pattern.fields) |field| {
                switch (field.pat) {
                    .binding => |binding| {
                        try prelude.append(self.alloc, .{ .let_stmt = .{
                            .name = binding,
                            .init = .{ .field_access = .{
                                .target = try self.allocExpr(.{ .ident = payload_name }),
                                .field_name = field.name,
                            } },
                            .is_mut = false,
                        } });
                    },
                    .struct_pat => |inner_pattern| {
                        if (nested.* != null) return error.UnsupportedPattern;
                        const child = try self.alloc.create(NestedPayloadDispatch);
                        child.* = try self.buildNestedPayloadDispatch(
                            inner_pattern,
                            try self.matchPayloadField(struct_pattern, payload_name, field.name),
                            0,
                        );
                        nested.* = child;
                    },
                    .wildcard => {},
                    else => return error.UnsupportedPattern,
                }
            }
        }
        if (!changed) return lowered_patterns;
        return rewritten.toOwnedSlice(self.alloc);
    }

    /// Read a variant's tuple-one payload directly; other payloads are records.
    fn matchPayloadField(
        self: *Lowerer,
        pattern: ast.StructPattern,
        payload_name: []const u8,
        field_name: []const u8,
    ) !*const ast.Expr {
        const payload = try self.allocExpr(.{ .ident = payload_name });
        if (pattern.fields.len == 1 and std.mem.eql(u8, field_name, "0")) return payload;
        return self.allocExpr(.{ .field_access = .{
            .target = payload,
            .field_name = field_name,
        } });
    }

    fn buildNestedPayloadDispatch(
        self: *Lowerer,
        pattern: ast.StructPattern,
        subject: *const ast.Expr,
        depth: usize,
    ) anyerror!NestedPayloadDispatch {
        if (depth >= nested_pattern_depth_limit) return error.UnsupportedPattern;
        const payload_name = try self.iteratorTemporaryName("__r2z_match_payload");
        const selectors = try self.alloc.alloc(ast.Pattern, 2);
        selectors[0] = if (pattern.name) |name|
            .{ .enum_literal = name }
        else
            .wildcard;
        selectors[1] = .{ .binding = payload_name };
        var bindings: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer bindings.deinit(self.alloc);
        var inner: ?*NestedPayloadDispatch = null;
        for (pattern.fields) |field| {
            switch (field.pat) {
                .binding => |binding| {
                    try bindings.append(self.alloc, .{ .let_stmt = .{
                        .name = binding,
                        .init = (try self.matchPayloadField(pattern, payload_name, field.name)).*,
                    } });
                },
                .struct_pat => |inner_pattern| {
                    if (inner != null) return error.UnsupportedPattern;
                    const child = try self.alloc.create(NestedPayloadDispatch);
                    child.* = try self.buildNestedPayloadDispatch(
                        inner_pattern,
                        try self.matchPayloadField(pattern, payload_name, field.name),
                        depth + 1,
                    );
                    inner = child;
                },
                .wildcard => {},
                else => return error.UnsupportedPattern,
            }
        }
        return .{
            .subject = subject,
            .selectors = selectors,
            .bindings = try bindings.toOwnedSlice(self.alloc),
            .inner = inner,
        };
    }

    /// Whether this pattern names a variant inside a payload's own pattern.
    ///
    /// `Err(IoError(e))` is two tests, and Zig's switch prong carries only
    /// one: it writes the tag of a struct pattern and drops its fields. So
    /// the question is asked of the IR pattern, which is what the lowering
    /// turns into the `ast.Pattern` tree that would lose the inner tag.
    fn patternHasNestedPayload(self: *Lowerer, pat_id: ir.exprs.NodeId, depth: usize) anyerror!bool {
        if (depth >= nested_pattern_depth_limit) return false;
        if (pat_id >= self.ir.bodies.pats.len) return false;
        const fields: []const ir.exprs.FieldPat = switch (self.ir.bodies.pats[pat_id].kind) {
            .struct_pat => |structure| structure.fields,
            .external_variant => |variant| variant.fields,
            else => return false,
        };
        for (fields) |field| {
            const inner = field.pat orelse continue;
            if (self.ir.bodies.pats[inner].kind == .struct_pat) return true;
            if (try self.patternHasNestedPayload(inner, depth + 1)) return true;
        }
        return false;
    }

    /// Whether one of these arms needs the ordered chain because its pattern
    /// nests a refutable payload pattern.
    ///
    /// A whole-match switch has no place for the second test, so the arm goes
    /// to the chain, which can hold it and still fall through. An arm whose
    /// payload is captured BY REFERENCE rewrites its own selector before the
    /// chain ever sees it, so it is left exactly as it is rather than routed
    /// somewhere the nested pattern would be dropped.
    fn matchNeedsNestedPayloadChain(
        self: *Lowerer,
        arms: []const ir.exprs.MatchArm,
    ) anyerror!bool {
        for (arms) |arm| {
            if (try self.armHasBoundAlternatives(arm)) return true;
            var nested = false;
            for (arm.patterns) |pat_id| {
                if (try self.patternHasNestedPayload(pat_id, 0)) nested = true;
            }
            if (!nested) continue;
            if (try self.referenceMatchCapture(arm.patterns) != null) return false;
            return true;
        }
        return false;
    }

    /// Lower an arm's body and its guard under one shadow scope.
    ///
    /// A guard reads the bindings its own pattern introduces, so it is lowered
    /// with those names visible and lands in the same prong, beside them.
    fn lowerArmValueAndGuard(
        self: *Lowerer,
        arm: ir.exprs.MatchArm,
        shadow_names: []const []const u8,
        alias: ?OwnedCaptureAlias,
    ) anyerror!LoweredMatchArm {
        const previous_shadow_scope = self.current_shadow_scope;
        var arm_shadow_scope: ShadowScope = .{
            .names = shadow_names,
            .parent = previous_shadow_scope,
        };
        self.current_shadow_scope = &arm_shadow_scope;
        defer self.current_shadow_scope = previous_shadow_scope;
        // Body lowering restores the alias override before the guard reads
        // its original binding, which exists before the selected body runs.
        return .{
            .value = try self.lowerMatchArmBodyOverAlias(arm.body, alias),
            .guard = if (arm.guard) |guard_id|
                try self.allocExpr(try self.lowerExpr(guard_id))
            else
                null,
        };
    }

    /// Lower `arms` as one self-contained Zig switch.
    ///
    /// This is the whole-match shape and it needs no arm to carry a guard,
    /// because a Zig prong has no guard form. A match that does carry one goes
    /// to `lowerGuardedMatch` instead.
    fn lowerMatchArms(
        self: *Lowerer,
        option: ?OptionalMatchSubject,
        arms: []const ir.exprs.MatchArm,
    ) anyerror![]ast.MatchArm {
        const lowered = try self.alloc.alloc(ast.MatchArm, arms.len);
        for (arms, 0..) |arm, index| {
            const lowered_patterns = try self.lowerWholeMatchArmPatterns(arm, option);
            const capture = lowered_patterns.capture;
            // The emitter writes the payload binding itself when the arm takes
            // it by value, so the release reads the name off the pattern
            // rather than off a capture only a by-reference arm carries.
            const bound_name: ?[]const u8 = if (capture) |capture_ast|
                capture_ast.name
            else
                try self.matchArmBindingName(arm.patterns);
            const bound_by_ref = if (capture) |capture_ast| capture_ast.by_ref else false;
            // The release owns the payload through a MUTABLE ALIAS, and the arm
            // body has to read THAT alias rather than the capture: the emitter
            // writes a by-value capture as `|name|`, which Zig makes `const`, so
            // the storage a consuming helper needs in order to transfer it
            // cannot be reached through the capture at all. Redirecting the
            // binding to the alias while the body is lowered is what makes
            // `Ok(s) => Ok(s.into())` hand over a pointer it can write, and the
            // release below then finds an alias the transfer already emptied,
            // so it frees nothing a second time.
            const alias = try self.ownedCaptureAlias(arm.patterns, bound_name, bound_by_ref);
            const lowered_body = try self.lowerWholeMatchArmBody(
                arm,
                lowered_patterns.patterns,
                option,
                capture,
                alias,
            );
            lowered[index] = .{
                .patterns = lowered_patterns.patterns,
                .body = if (alias) |owned| try self.appendOwnedCaptureRelease(owned, lowered_body) else lowered_body,
                // An optional prong dispatches on a test of the subject and has
                // no payload of its own to capture; the arm's binding is the
                // statement its body lowering introduces.
                .capture = if (option == null) capture else null,
            };
        }
        return lowered;
    }

    /// The mutable alias an owned match payload is released through, or null
    /// when the arm's payload is not one this lowering releases.
    ///
    /// Every guard here is the release's own: an arm that binds nothing, one
    /// that binds BY REFERENCE (the caller's value would be released), and one
    /// whose payload is not a runtime container the allocator can release are
    /// all arms this must leave exactly as they were.
    fn ownedCaptureAlias(
        self: *Lowerer,
        patterns: []const ir.exprs.NodeId,
        bound_name: ?[]const u8,
        bound_by_ref: bool,
    ) anyerror!?OwnedCaptureAlias {
        if (!self.current_callable_is_allocating) return null;
        if (bound_by_ref) return null;
        const capture_name = bound_name orelse return null;
        const payload = self.matchCapturePayload(patterns) orelse return null;
        if (payload >= self.ir.bodies.pats.len) return null;
        const payload_kind = self.ir.bodies.pats[payload].kind;
        if (payload_kind != .binding) return null;
        const type_id = self.ir.bodies.pats[payload].ty orelse return null;
        const payload_type = try self.typeById(type_id);
        if (!ownedRuntimeContainerType(payload_type)) return null;
        // The override is keyed by the SOURCE name, which is what
        // `activeClosureCaptureOverride` looks up; the capture name the emitter
        // writes is what the alias is initialized from.
        const source_name = payload_kind.binding.name;
        if (source_name.len == 0) return null;
        // The name this arm's alias already carries is kept: it is still the
        // name that releases the payload, and a stable one keeps the emitted
        // goldens unchanged for every arm that already reached this path.
        const alias = try self.iteratorTemporaryName("__r2z_release");
        return .{
            .source_name = source_name,
            .capture_name = capture_name,
            .alias_name = alias,
            .payload_type = payload_type,
        };
    }

    /// Lower an arm's value with the payload binding redirected to its mutable
    /// alias, so every read and every in-place write the body makes reaches the
    /// owner the release is responsible for.
    fn lowerMatchArmBodyOverAlias(
        self: *Lowerer,
        body: ir.exprs.NodeId,
        alias: ?OwnedCaptureAlias,
    ) anyerror!ast.Expr {
        const owned = alias orelse return self.lowerExpr(body);
        // An enclosing match can bind the same source name, so the entry this
        // one shadows is restored rather than deleted: removing it would take
        // the outer arm's binding with it.
        const previous = self.active_closure_capture_overrides.get(owned.source_name);
        try self.active_closure_capture_overrides.put(
            self.alloc,
            owned.source_name,
            owned.alias_name,
        );
        const previous_move = self.active_owned_capture_move;
        // Collected before the restore is armed: a scan that fails must not
        // release the move set an enclosing arm is still using.
        var installed = try self.collectOwnedCaptureMoves(owned, body);
        defer {
            if (previous) |shadowed| {
                const entry = self.active_closure_capture_overrides.getPtr(owned.source_name).?;
                entry.* = shadowed;
            } else {
                _ = self.active_closure_capture_overrides.remove(owned.source_name);
            }
            installed.sites.deinit(self.alloc);
            self.active_owned_capture_move = previous_move;
        }
        const installed_entries = [_]OwnedCaptureMove{installed};
        self.active_owned_capture_move = .{ .entries = &installed_entries };
        return self.lowerExpr(body);
    }

    /// The pattern an arm's capture binds, or null when the arm binds nothing
    /// a single payload node names.
    fn matchCapturePayload(self: *const Lowerer, patterns: []const ir.exprs.NodeId) ?ir.exprs.NodeId {
        if (patterns.len != 1) return null;
        const pat_id = patterns[0];
        if (pat_id >= self.ir.bodies.pats.len) return null;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .external_variant => |variant| blk: {
                if (variant.fields.len != 1) break :blk null;
                break :blk variant.fields[0].pat orelse null;
            },
            // The tagged `Result` lowers to a struct with one field per arm,
            // and the arm that matched binds exactly one of them.
            .struct_pat => |struct_pat| blk: {
                for (struct_pat.fields) |field| {
                    const inner = field.pat orelse continue;
                    if (inner >= self.ir.bodies.pats.len) continue;
                    if (self.ir.bodies.pats[inner].kind != .binding) continue;
                    break :blk inner;
                }
                break :blk null;
            },
            else => null,
        };
    }

    /// The emitted name a whole-match arm binds from its single payload
    /// pattern, or null when the arm binds nothing.
    fn matchArmBindingName(self: *Lowerer, patterns: []const ir.exprs.NodeId) anyerror!?[]const u8 {
        const payload = self.matchCapturePayload(patterns) orelse return null;
        if (payload >= self.ir.bodies.pats.len) return null;
        return switch (self.ir.bodies.pats[payload].kind) {
            .binding => try self.patternName(payload),
            else => null,
        };
    }

    /// Whether a `match` hands the SCRUTINEE's payload to an arm, so the
    /// scrutinee is spent by the dispatch rather than read through.
    ///
    /// One arm deciding it is enough, because the dispatch picks exactly one:
    /// an arm that binds an owned payload by value takes that payload OUT of the
    /// scrutinee, and the release armed over the scrutinee has to find nothing
    /// there on that path. Every other arm binds nothing, binds a borrow, or
    /// binds a payload that owns nothing — a `Cow::Borrowed` slice is the
    /// caller's own storage — and those leave the scrutinee holding what it
    /// held, which is exactly what its release is for.
    ///
    /// The binding is judged the way `ownedCaptureAlias` judges it, from the
    /// payload pattern and its declared type, so the arm that releases this
    /// payload and the dispatch that moves it cannot disagree.
    fn matchArmTakesOwnedPayload(self: *Lowerer, arms: []const ir.exprs.MatchArm) anyerror!bool {
        for (arms) |arm| {
            if (try self.referenceMatchCapture(arm.patterns)) |capture| {
                if (capture.by_ref) continue;
            }
            if (try self.armBindsOwnedPayload(arm.patterns)) return true;
        }
        return false;
    }

    /// Whether one arm's pattern binds a runtime container the allocator owns.
    fn armBindsOwnedPayload(self: *Lowerer, patterns: []const ir.exprs.NodeId) anyerror!bool {
        const payload = self.matchCapturePayload(patterns) orelse return false;
        if (payload >= self.ir.bodies.pats.len) return false;
        if (self.ir.bodies.pats[payload].kind != .binding) return false;
        const type_id = self.ir.bodies.pats[payload].ty orelse return false;
        return ownedRuntimeContainerType(try self.typeById(type_id));
    }

    /// Release an owned payload a match arm binds when that arm's scope ends.
    ///
    /// Rust drops what a pattern binds when the arm ends, and a `Result` or
    /// `Option` payload of an owned container carries heap storage. Without
    /// the release the value the arm was handed leaks, and the test allocator
    /// reports the leak instead of the behaviour the test was written for.
    ///
    /// The release sits in a `defer` ahead of the arm's own result, so the
    /// result is computed first and the payload drops after it — the source's
    /// order, and the only one that leaves a returned value intact.
    fn appendOwnedCaptureRelease(
        self: *Lowerer,
        owned: OwnedCaptureAlias,
        body: ast.Expr,
    ) anyerror!ast.Expr {
        // The alias carries the same storage and its own mutable pointer:
        // `deinit` takes one, the capture the emitter wrote is immutable in the
        // source, and the arm body was lowered to read the alias rather than
        // the capture.
        //
        // The release is emitted UNCONDITIONALLY, because the answer to "did
        // this arm move its payload?" is a property of the PATH TAKEN, not of
        // the source: deciding it statically would either leak the branch that
        // did not move or free the branch that did. What makes the
        // unconditional form safe is that every move empties this alias IN
        // PLACE — `collectOwnedCaptureMoves` decides which reads do — so the
        // branch that moved finds nothing here and frees nothing, while every
        // branch that stayed still frees what the arm held.
        const release = try self.ownedCaptureReleaseStmts(owned);
        // The alias has to be declared where the binding it copies is IN
        // SCOPE, and AFTER it: the alias initializer is a read of that
        // binding, so a `const __r2z_release = value` placed ahead of
        // `const value = ...` names an identifier that is not declared yet.
        // An arm whose payload comes from an optional declares that binding in
        // a prelude block of its own — `const value =
        // r2z.option.unwrap(subject)` — so wrapping the arm from outside named
        // an identifier that does not exist at all, and the emitted file failed
        // to compile with `undefined identifier`. Putting the alias and its
        // release IMMEDIATELY AFTER the binding gives both the scope they need
        // and the declaration they read; the arm's own value still reads the
        // same alias, and the `defer` still runs after that value has been
        // computed, because a `defer` fires at scope exit rather than at the
        // statement it sits beside.
        const block = switch (body) {
            .block => |value| value,
            else => null,
        };
        const binding_at = if (block) |inner|
            blockBindingIndex(inner, owned.capture_name)
        else
            null;
        if (block == null or binding_at == null) {
            return .{ .block = .{
                .stmts = release,
                .expr = try self.allocExpr(body),
            } };
        }
        const inner = block.?;
        // `binding_at` is the index of the payload binding itself, so the
        // insertion point is the statement AFTER it: index `at` would put the
        // alias ahead of the declaration its initializer reads.
        const at = binding_at.? + 1;
        const stmts = try self.alloc.alloc(ast.Stmt, inner.stmts.len + release.len);
        @memcpy(stmts[0..at], inner.stmts[0..at]);
        @memcpy(stmts[at .. at + release.len], release);
        @memcpy(stmts[at + release.len ..], inner.stmts[at..]);
        return .{ .block = .{
            .label = inner.label,
            .stmts = stmts,
            .expr = inner.expr,
        } };
    }

    /// The alias an arm reads its owned payload through, and the `defer` that
    /// releases it when the arm ends.
    fn ownedCaptureReleaseStmts(
        self: *Lowerer,
        owned: OwnedCaptureAlias,
    ) anyerror![]const ast.Stmt {
        const stmts = try self.alloc.alloc(ast.Stmt, 2);
        stmts[0] = .{ .let_stmt = .{
            .name = try self.alloc.dupe(u8, owned.alias_name),
            .init = .{ .ident = try self.alloc.dupe(u8, owned.capture_name) },
            .is_mut = true,
        } };
        stmts[1] = try self.ownerReleaseStatement(
            owned.alias_name,
            ownerReleasesElements(owned.payload_type),
        );
        return stmts;
    }

    /// The statement of `block` that binds `name`, or null when it binds none.
    fn blockBindingIndex(block: ast.Block, name: []const u8) ?usize {
        for (block.stmts, 0..) |statement, index| {
            switch (statement) {
                .let_stmt => |binding| {
                    if (std.mem.eql(u8, binding.name, name)) return index;
                },
                else => {},
            }
        }
        return null;
    }

    // -------------------------------------------------------------------------
    // Handing an owned payload out of a match arm's alias
    // -------------------------------------------------------------------------

    /// Bookkeeping for one arm body's payload-transfer scan.
    const OwnedCaptureScan = struct {
        /// Expression ids that read the payload in a hand-off position.
        sites: std.AutoHashMapUnmanaged(ir.exprs.NodeId, void),
        /// `(node << 1) | transfer` entries already scanned, so a subexpression
        /// reachable from two positions is visited once per position and a
        /// self-referential node table cannot spin here.
        visited: std.AutoHashMapUnmanaged(usize, void),
    };

    /// Every read of `alias` in `body` that hands the payload ON rather than
    /// borrowing it.
    fn collectOwnedCaptureMoves(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        body: ir.exprs.NodeId,
    ) anyerror!OwnedCaptureMove {
        var scan: OwnedCaptureScan = .{ .sites = .empty, .visited = .empty };
        errdefer {
            scan.sites.deinit(self.alloc);
            scan.visited.deinit(self.alloc);
        }
        try self.scanOwnedCaptureExpr(alias, body, true, &scan);
        scan.visited.deinit(self.alloc);
        return .{ .alias = alias, .sites = scan.sites };
    }

    fn collectOwnedCaptureMovesOverBlock(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        body: ir.exprs.BlockExpr,
    ) anyerror!OwnedCaptureMove {
        var scan: OwnedCaptureScan = .{ .sites = .empty, .visited = .empty };
        errdefer {
            scan.sites.deinit(self.alloc);
            scan.visited.deinit(self.alloc);
        }
        try self.scanOwnedCaptureBlock(alias, body, true, &scan);
        scan.visited.deinit(self.alloc);
        return .{ .alias = alias, .sites = scan.sites };
    }

    /// Record `expr_id` when its value IS the payload, and keep looking
    /// through the positions that are.
    ///
    /// `transfer` says the value of this expression leaves its own place, so a
    /// bare read of the payload here moves it. Rust decides that by hand: out
    /// through a `return` or a `break`, into a call parameter it declares by
    /// value, into a new binding or an assignment, into an aggregate, or out as
    /// the value of a block, a branch or an arm. Everything else — a method
    /// receiver, a formatter argument, a slice descriptor, a length — reads
    /// what the arm's release still owns, and keeps reading the alias.
    fn scanOwnedCaptureExpr(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        expr_id: ir.exprs.NodeId,
        transfer: bool,
        scan: *OwnedCaptureScan,
    ) anyerror!void {
        if (expr_id >= self.ir.bodies.exprs.len) return;
        const key = (@as(usize, expr_id) << 1) | @intFromBool(transfer);
        if (scan.visited.contains(key)) return;
        try scan.visited.put(self.alloc, key, {});
        switch (self.ir.bodies.exprs[expr_id].kind) {
            .path => |path| {
                if (!transfer) return;
                // A turbofish turns the read into a call on the alias, which is
                // not a payload at all; leave it exactly as it was.
                if (path.generic_args.len != 0) return;
                const entity = self.ir.graph.symbol_table.get(path.def) orelse return;
                if (!std.mem.eql(u8, entity.name, alias.source_name)) return;
                try scan.sites.put(self.alloc, expr_id, {});
            },
            // A block's tail is the block's value; its statements stand alone.
            .block => |block| try self.scanOwnedCaptureBlock(alias, block, transfer, scan),
            // A branch's value is the `if`'s value whatever the `if` is used
            // for, and the condition owns nothing.
            .if_else => |branch| {
                try self.scanOwnedCaptureExpr(alias, branch.cond, false, scan);
                try self.scanOwnedCaptureBranch(alias, branch.then_, branch.@"else", scan);
            },
            .if_let => |subject| {
                try self.scanOwnedCaptureExpr(alias, subject.scrutinee, false, scan);
                try self.scanOwnedCaptureBranch(alias, subject.then_, subject.@"else", scan);
            },
            // A match on a place DESTRUCTURES that place: Rust moves the
            // payload out of the scrutinee into the arm's binding, and the
            // scrutinee itself is spent. Reading the scrutinee as a borrow
            // says the opposite, and the scope release armed over it then
            // frees storage the arm already handed on — which is how
            // `match cow { Cow::Owned(bytes) => Cow::Owned(String::from_utf8_unchecked(bytes)) }`
            // returned a value aliasing bytes its own frame freed.
            //
            // The subject is a TRANSFER for an arm that binds an owned payload
            // by value, and a plain read for one that binds nothing, binds a
            // borrow, or names a payload that owns nothing: `Cow::Borrowed`
            // names the caller's slice, so copying the union costs no storage
            // and the release still has its own bytes to free.
            .match => |subject| {
                try self.scanOwnedCaptureExpr(
                    alias,
                    subject.scrutinee,
                    try self.matchArmTakesOwnedPayload(subject.arms),
                    scan,
                );
                for (subject.arms) |nested| {
                    if (nested.guard) |guard| {
                        try self.scanOwnedCaptureExpr(alias, guard, false, scan);
                    }
                    try self.scanOwnedCaptureExpr(alias, nested.body, true, scan);
                }
            },
            .return_ => |returned| {
                if (returned.value) |value| {
                    try self.scanOwnedCaptureExpr(alias, value, true, scan);
                }
            },
            .break_ => |brk| {
                if (brk.value) |value| try self.scanOwnedCaptureExpr(alias, value, true, scan);
            },
            // The right-hand side moves into the place the left-hand names.
            .assign => |assignment| {
                try self.scanOwnedCaptureExpr(alias, assignment.target, false, scan);
                try self.scanOwnedCaptureExpr(alias, assignment.value, true, scan);
            },
            // `?` yields what it was handed, so the hand-off follows it in.
            .try_ => |inner| try self.scanOwnedCaptureExpr(alias, inner.inner, transfer, scan),
            .cast => |cast| try self.scanOwnedCaptureExpr(alias, cast.operand, transfer, scan),
            .call => |call| {
                for (call.args, 0..) |arg, index| {
                    const moves = try self.callArgumentTakesPayloadByValue(expr_id, call, index, alias);
                    try self.scanOwnedCaptureExpr(alias, arg, moves, scan);
                }
            },
            // A receiver is a hand-off only when the source declared `self` BY
            // VALUE: `&self` and `&mut self` are borrows there, and the runtime
            // reaches them through the address of the alias, in place. Each
            // argument is judged by the method's own declared parameter, the
            // same one the call's argument loop types it against.
            .method_call => |method| {
                try self.scanOwnedCaptureExpr(
                    alias,
                    method.receiver,
                    try self.methodReceiverTakesPayload(method, alias),
                    scan,
                );
                for (method.args, 0..) |arg, index| {
                    const moves = try self.methodCallArgumentTakesPayloadByValue(expr_id, method, index, alias);
                    try self.scanOwnedCaptureExpr(alias, arg, moves, scan);
                }
            },
            // An aggregate is filled by moving into each of its slots.
            .struct_lit => |literal| {
                if (literal.base) |base| try self.scanOwnedCaptureExpr(alias, base, false, scan);
                for (literal.fields) |field| {
                    try self.scanOwnedCaptureExpr(alias, field.value, true, scan);
                }
            },
            .external_variant => |variant| try self.scanOwnedCaptureFields(alias, variant, scan),
            .enum_variant => |variant| try self.scanOwnedCaptureFields(alias, variant, scan),
            .array => |array| {
                for (array.elements) |element| {
                    try self.scanOwnedCaptureExpr(alias, element, true, scan);
                }
            },
            .vec_lit => |vec| {
                for (vec.elements) |element| {
                    try self.scanOwnedCaptureExpr(alias, element, true, scan);
                }
                if (vec.repeat) |count| {
                    if (count == .expression) try self.scanOwnedCaptureExpr(alias, count.expression, false, scan);
                }
            },
            // A loop body IS walked, because everything inside it can hand the
            // payload on: a `return`, a `break value`, a by-value call, a
            // binding, a by-value receiver. Only its TAIL is not a hand-off —
            // Rust requires a loop body to be `()`, so the value there is
            // dropped rather than moved somewhere that outlives the alias.
            .loop_ => |loop_expr| try self.scanOwnedCaptureBlock(alias, loop_expr.body, false, scan),
            .while_ => |loop_expr| {
                try self.scanOwnedCaptureExpr(alias, loop_expr.cond, false, scan);
                try self.scanOwnedCaptureBlock(alias, loop_expr.body, false, scan);
            },
            .for_ => |loop_expr| {
                try self.scanOwnedCaptureExpr(alias, loop_expr.iterable, false, scan);
                switch (loop_expr.iter_kind) {
                    .range, .slice, .enumerate => {},
                    .multi => |inputs| {
                        for (inputs) |input| {
                            try self.scanOwnedCaptureExpr(alias, input, false, scan);
                        }
                    },
                    .adapter => |chain| {
                        try self.scanOwnedCaptureExpr(alias, chain.source, false, scan);
                    },
                }
                try self.scanOwnedCaptureBlock(alias, loop_expr.body, false, scan);
            },
            // Below here every position names a place or reads an operand Rust
            // only borrows. The scan still descends, because a nested call
            // keeps the signature that call declares.
            .field => |field| try self.scanOwnedCaptureExpr(alias, field.base, false, scan),
            // An element read out of a carrier in a HAND-OFF position moves
            // that element, and that is the same claim a whole-owner read
            // makes asked about the ELEMENT rather than the carrier. The base
            // is still scanned as a BORROW on purpose: emptying the carrier
            // itself is what would disarm the release that frees whatever
            // stayed standing in it.
            .index => |index| {
                if (transfer and self.placePeelsToAlias(index.base, alias)) {
                    try scan.sites.put(self.alloc, expr_id, {});
                }
                try self.scanOwnedCaptureExpr(alias, index.base, false, scan);
                try self.scanOwnedCaptureExpr(alias, index.index, false, scan);
            },
            .binary => |binary| {
                try self.scanOwnedCaptureExpr(alias, binary.lhs, false, scan);
                try self.scanOwnedCaptureExpr(alias, binary.rhs, false, scan);
            },
            .unary => |unary| try self.scanOwnedCaptureExpr(alias, unary.operand, false, scan),
            .range => |range| {
                try self.scanOwnedCaptureExpr(alias, range.start, false, scan);
                if (range.end) |end| try self.scanOwnedCaptureExpr(alias, end, false, scan);
            },
            // The formatter writes through a borrow; it is handed the argument,
            // not the ownership.
            .format_write => |format| {
                try self.scanOwnedCaptureExpr(alias, format.writer, false, scan);
                for (format.args) |arg| try self.scanOwnedCaptureExpr(alias, arg, false, scan);
            },
            .iterator_chain => |chain| {
                try self.scanOwnedCaptureExpr(alias, chain.source, false, scan);
            },
            .core_call => |call| {
                for (call.args) |arg| {
                    try self.scanOwnedCaptureExpr(alias, arg, false, scan);
                }
            },
            .literal, .unit, .core_function, .closure, .panic_, .unsupported, .continue_ => {},
        }
    }

    fn scanOwnedCaptureBlock(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        block: ir.exprs.BlockExpr,
        transfer: bool,
        scan: *OwnedCaptureScan,
    ) anyerror!void {
        for (block.statements) |statement| {
            try self.scanOwnedCaptureStatement(alias, statement, scan);
        }
        if (block.tail) |tail| {
            try self.scanOwnedCaptureExpr(alias, tail, transfer, scan);
        }
    }

    fn scanOwnedCaptureBranch(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        then_block: ir.exprs.BlockExpr,
        else_branch: ir.exprs.ElseBranch,
        scan: *OwnedCaptureScan,
    ) anyerror!void {
        try self.scanOwnedCaptureBlock(alias, then_block, true, scan);
        switch (else_branch) {
            .none => {},
            .block => |block| try self.scanOwnedCaptureBlock(alias, block, true, scan),
            .chain => |chain| try self.scanOwnedCaptureExpr(alias, chain, true, scan),
        }
    }

    fn scanOwnedCaptureStatement(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        statement: ir.exprs.NodeId,
        scan: *OwnedCaptureScan,
    ) anyerror!void {
        if (statement >= self.ir.bodies.stmts.len) return;
        switch (self.ir.bodies.stmts[statement].kind) {
            // A new binding takes its initialiser by value.
            .let => |binding| {
                if (binding.init) |initializer| {
                    try self.scanOwnedCaptureExpr(alias, initializer, true, scan);
                }
            },
            .let_else => |binding| {
                try self.scanOwnedCaptureExpr(alias, binding.init, true, scan);
                try self.scanOwnedCaptureBlock(alias, binding.else_block, true, scan);
            },
            // A statement's value is dropped, which is what the release would
            // have done to the alias anyway; only the calls inside it move.
            .expr => |expr| try self.scanOwnedCaptureExpr(alias, expr, false, scan),
            .item => {},
        }
    }

    fn scanOwnedCaptureFields(
        self: *Lowerer,
        alias: OwnedCaptureAlias,
        variant: anytype,
        scan: *OwnedCaptureScan,
    ) anyerror!void {
        for (variant.tuple_fields) |field| {
            try self.scanOwnedCaptureExpr(alias, field, true, scan);
        }
        for (variant.named_fields) |field| {
            try self.scanOwnedCaptureExpr(alias, field.value, true, scan);
        }
    }

    /// Whether the SOURCE callee of the `.call` node at `expr_id` takes its
    /// `index`th argument as this payload, BY VALUE.
    ///
    /// The verdict comes from the source's own signature, never from the shape
    /// of the lowered call. A runtime entry point that receives its operand by
    /// address — `String::from_utf8`, `CowStr::from_owned` — already empties the
    /// pointer it was handed, and moving its argument here as well would hand
    /// the same payload to two owners. Those are not reachable anyway:
    /// `String::from_utf8` is a `core_call`, and a foreign callee has no source
    /// parameter to read.
    ///
    /// A generic signature is read through THIS call's instantiation:
    /// `fn id<T>(value: T) -> T` called as `id(text)` hands a `String` over.
    fn callArgumentTakesPayloadByValue(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        call: ir.exprs.Call,
        index: usize,
        alias: OwnedCaptureAlias,
    ) anyerror!bool {
        const def = switch (call.call_kind) {
            .free => |free_def| free_def,
            .associated, .constructor => |source_def| source_def,
        };
        if (self.directFreeCallArgumentType(call.call_kind, index)) |param_type| {
            return self.declaredParameterTakesPayloadByValue(.{
                .def = def,
                .param_index = index,
                .param_args = call.args,
                .explicit = &.{},
                .expr_id = expr_id,
                .declared = param_type,
            }, alias.payload_type);
        }
        switch (call.call_kind) {
            .free => return false,
            else => {},
        }
        const method = self.structMethodForDef(def) orelse return false;
        const receiver = method.receiver;
        if (receiver == null) {
            // An associated function declares no receiver, so its parameters
            // line up with its arguments one for one.
            if (index >= method.params.len) return false;
            return self.declaredParameterTakesPayloadByValue(.{
                .def = def,
                .param_index = index,
                .param_args = call.args,
                .explicit = &.{},
                .expr_id = expr_id,
                .declared = method.params[index].ty,
            }, alias.payload_type);
        }
        // A method reached in associated position passes its receiver as the
        // FIRST argument, and `StructMethod.params` does not list it, so every
        // declared parameter sits one argument later.
        if (index == 0) {
            if (receiver.? != .owned) return false;
            if (index >= call.args.len) return false;
            const receiver_type = try self.exprType(call.args[0]);
            const known = receiver_type orelse return false;
            return typeEquals(known, alias.payload_type);
        }
        const param_index = index - 1;
        if (param_index >= method.params.len) return false;
        if (call.args.len == 0) return false;
        return self.declaredParameterTakesPayloadByValue(.{
            .def = def,
            .param_index = param_index,
            // The receiver is argument zero on the wire and absent from the
            // declaration, so the two lists are lined up once, here.
            .param_args = call.args[1..],
            .explicit = &.{},
            .expr_id = expr_id,
            .declared = method.params[param_index].ty,
        }, alias.payload_type);
    }

    /// Whether a source method call hands argument `index` this payload BY
    /// VALUE. Same question as the `.call` classifier; the node makes the
    /// difference that `MethodCall` carries its receiver separately, so params
    /// and args already line up.
    fn methodCallArgumentTakesPayloadByValue(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        call: ir.exprs.MethodCall,
        index: usize,
        alias: OwnedCaptureAlias,
    ) anyerror!bool {
        // First: a recognized standard method has no source declaration here
        // to read, and the declaration is otherwise the only witness.
        if (try self.vecPushArgumentTakesPayload(call, index, alias)) return true;
        const declared = self.methodCallArgumentType(call.method, index) orelse return false;
        return self.declaredParameterTakesPayloadByValue(.{
            .def = call.method,
            .param_index = index,
            .param_args = call.args,
            .explicit = call.generic_args,
            .expr_id = expr_id,
            .declared = declared,
        }, alias.payload_type);
    }

    /// Whether argument `index` of this call is the item a `Vec::push` takes
    /// over. `vec_push_owned` takes the item BY VALUE and owns it from that
    /// call on. The vector decides ownership: `Vec<u8>` receives bytes that own
    /// nothing, `Vec<String>` receives bytes the caller must stop holding.
    fn vecPushArgumentTakesPayload(
        self: *Lowerer,
        call: ir.exprs.MethodCall,
        index: usize,
        alias: OwnedCaptureAlias,
    ) anyerror!bool {
        if (index != 0) return false;
        const entity = self.ir.graph.symbol_table.get(call.method) orelse return false;
        const method = (try self.lookupRecognizedStdMethod(call.receiver, entity.name)) orelse
            return false;
        if (method != .vec_push) return false;
        const element = (try self.vecElementOfReceiver(call.receiver)) orelse return false;
        if (!ownedRuntimeContainerType(element)) return false;
        return typeEquals(element, alias.payload_type);
    }

    fn declaredParameterTakesPayloadByValue(
        self: *Lowerer,
        site: DeclaredParameterSite,
        payload: ir.types.Type,
    ) anyerror!bool {
        // A borrow is a borrow at every instantiation — `&T` is a reference at
        // `T = String` too — so this is settled before any lookup.
        switch (site.declared) {
            .reference, .raw_ptr => return false,
            else => {},
        }
        if (try self.callInstantiation(site)) |instantiation| {
            // Arena-backed and read by the comparison alone.
            const instantiated = try ir.types.substType(
                self.alloc,
                site.declared,
                instantiation.names,
                instantiation.args,
            );
            return typeEquals(instantiated, payload);
        }
        // Still standing on its OWN type parameter: only the value in that
        // position says what this call hands over, and never the declaration.
        if (isTypeParameterPath(site.declared) and site.param_index < site.param_args.len) {
            if (try self.exprType(site.param_args[site.param_index])) |actual| {
                return typeEquals(actual, payload);
            }
        }
        return typeEquals(site.declared, payload);
    }

    /// The source signature's type parameters paired with what THIS call
    /// filled them with.
    ///
    /// A missing answer is the answer: this decides whether a payload MOVES,
    /// and an invented instantiation would empty a handle whose owner the
    /// callee never received.
    fn callInstantiation(
        self: *Lowerer,
        site: DeclaredParameterSite,
    ) anyerror!?CallInstantiation {
        const own = self.sourceCalleeOwnParams(site.def);
        if (site.explicit.len != 0) {
            if (site.explicit.len != own.len) return null;
            return .{ .names = own, .args = site.explicit };
        }
        // A blanket impl hoists its methods still bound by its own `I`, and a
        // declared parameter is written in those terms: `Vec<I>`. The name is
        // part of the substitution, so it goes first, and only the call node's
        // own instantiation carries a value for it.
        const inherited = self.inheritedHoistParams(site.def);
        if (inherited.len != 0) {
            const produced = self.concreteExprType(site.expr_id) orelse return null;
            const inst = switch (produced) {
                .generic_inst => |value| value,
                else => return null,
            };
            if (inst.decl != site.def) return null;
            const names = try self.alloc.alloc([]const u8, inherited.len + own.len);
            @memcpy(names[0..inherited.len], inherited);
            @memcpy(names[inherited.len..], own);
            if (inst.args.params.len != names.len) return null;
            return .{ .names = names, .args = inst.args.params };
        }
        if (self.concreteExprType(site.expr_id)) |produced| {
            switch (produced) {
                .generic_inst => |inst| {
                    if (inst.decl == site.def and inst.args.params.len == own.len) {
                        return .{ .names = own, .args = inst.args.params };
                    }
                },
                else => {},
            }
        }
        if (try self.inferredCallArgs(site.def, site.param_args)) |inferred| {
            if (inferred.len == own.len) return .{ .names = own, .args = inferred };
        }
        if (try self.inferredMethodArgs(site.def, site.param_args)) |inferred| {
            if (inferred.len == own.len) return .{ .names = own, .args = inferred };
        }
        return null;
    }

    /// The type parameters a hoisted method signature carries from its impl.
    /// Empty for everything but a blanket impl, whose `impl<I: Bound> Bound for
    /// I` keeps `I` in the hoisted signature and in every declared parameter.
    fn inheritedHoistParams(self: *Lowerer, def: ir.spine.EntityId) []const []const u8 {
        const entity = self.ir.graph.symbol_table.get(def) orelse return &.{};
        const parent_id = entity.parent orelse return &.{};
        const parent = self.ir.graph.symbol_table.get(parent_id) orelse return &.{};
        const target_id = hoistTargetFor(parent) orelse return &.{};
        return self.moduleHoistGenericParams(parent, target_id);
    }

    /// Whether a method receiver is a hand-off of this payload rather than a
    /// borrow of it.
    ///
    /// The answer comes from the method's own DECLARATION, never from
    /// `MethodCall.receiver_mode`. That mode is the invocation form the call
    /// site was resolved with, and by-value is its default: `self.clone()`
    /// and `e.utf8_error()` both arrive as `.value` even though Rust declares
    /// `&self`, so reading it as proof empties an alias under a borrowed read
    /// and leaks the bytes that read was still going to use.
    ///
    /// A method the CRATE declares is judged by that declaration. A method it
    /// does not declare is judged by what the backend itself lowers it to, and
    /// there the recognised runtime accessors that consume their receiver are
    /// hand-offs even though no source declaration exists to say so.
    ///
    /// `value.unwrap()` on a `Result<String, _>` is that shape. Rust declares
    /// `Result::unwrap(self)`, so the call spends the receiver, and the runtime
    /// helper is a by-value method call that hands the payload straight back
    /// out of the copy it was given. Without this the read looks like a borrow,
    /// the alias is never emptied, and the release armed for the alias frees
    /// bytes the payload the call returned already owns.
    fn methodReceiverTakesPayload(
        self: *Lowerer,
        method: ir.exprs.MethodCall,
        alias: OwnedCaptureAlias,
    ) anyerror!bool {
        if (self.structMethodForDef(method.method)) |declared| {
            if (declared.receiver == null or declared.receiver.? != .owned) return false;
        } else if (!try self.runtimeReceiverConsumesPayload(method)) {
            return false;
        }
        const receiver_type = try self.exprType(method.receiver);
        const known = receiver_type orelse return false;
        return typeEquals(known, alias.payload_type);
    }

    /// Whether a recognised runtime accessor CONSUMES the receiver it is called
    /// on, so a read of an owner alias there is a hand-off.
    ///
    /// Every entry is one the backend already lowers to a plain by-value call
    /// that does NOT empty the receiver itself: `r2z.Result.unwrap` returns `T`
    /// out of the union it was handed, `r2z.option.unwrap` returns the payload
    /// out of the optional, and the runtime signature for each is `self` by
    /// value. Rust's own signatures agree, so the alias is spent at the call
    /// and the scope release armed over it has to find nothing there.
    ///
    /// Nothing is decided from the name alone: the receiver's TYPE is what
    /// selects the arm, so an inherent `unwrap` on a user type never reaches
    /// here. The accessors that only read, or that hand out a borrow or an
    /// address, are deliberately absent — `is_ok` and `is_err` copy, `as_ref`
    /// and `as_mut` take `&self`, `take` writes back through `&mut self` — and
    /// so are the conversions that already consume on their own: `Cow::
    /// into_owned` and `CowStr::from_owned` reach the payload through a pointer
    /// that empties it, and marking the read as well would move the same
    /// payload twice.
    fn runtimeReceiverConsumesPayload(self: *Lowerer, method: ir.exprs.MethodCall) anyerror!bool {
        const symbol = self.ir.graph.symbol_table.get(method.method) orelse return false;
        const recognized = try self.lookupRecognizedStdMethod(method.receiver, symbol.name) orelse
            return false;
        return switch (recognized) {
            .result_unwrap,
            .result_unwrap_err,
            .result_expect,
            .result_expect_err,
            .result_ok,
            .result_err,
            .option_unwrap,
            => true,
            else => false,
        };
    }

    /// The runtime transfer that hands an owned payload out of its alias, or
    /// null when this read is not one.
    ///
    /// The alias is the only mutable handle the arm has on the payload, so a
    /// read that hands the payload on goes through it: the runtime copies the
    /// owner out and empties the alias where it stands, which is what leaves
    /// the arm's release free to run unconditionally. A read that only borrows
    /// keeps naming the alias directly, so nothing is emptied and the release
    /// still has the payload to free.
    fn lowerOwnedCaptureTransfer(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        path: ir.exprs.PathExpr,
    ) anyerror!?ast.Expr {
        // Captured storage is narrower than the enclosing lexical owner.
        if (self.active_owned_capture_move) |active| {
            if (active.aliasAtSite(expr_id)) |alias| {
                const resolved = try self.lowerResolvedEntityName(path.def);
                defer self.alloc.free(resolved);
                if (std.mem.eql(u8, resolved, alias.alias_name)) {
                    return try self.ownedTransferCall(alias);
                }
            }
        }
        // A lexical owner is found by IDENTITY and not by name: two bindings may
        // share a source name in nested scopes, and only the entity says which
        // storage this read is moving. The innermost match wins, so a shadowing
        // binding empties its own handle and leaves the outer one holding what
        // it still owns.
        var owner: ?*const OwnedScopeBinding = null;
        for (self.owned_scope_bindings.items) |*candidate| {
            if (candidate.def == path.def) owner = candidate;
        }
        const binding = owner orelse return null;
        if (!binding.sites.contains(expr_id)) return null;
        return try self.ownedTransferCall(binding.alias);
    }

    /// `r2z.alloc.takeOwned(&<handle>)` — the runtime transfer that copies the
    /// owner out and empties the handle where it stands, which is what leaves
    /// the scope's release free to run unconditionally.
    fn ownedTransferCall(self: *Lowerer, alias: OwnedCaptureAlias) anyerror!ast.Expr {
        return self.ownedTransferPlaceCall(
            .{ .ident = try self.alloc.dupe(u8, alias.alias_name) },
            alias.payload_type,
        );
    }

    fn ownedTransferPlaceCall(self: *Lowerer, place: ast.Expr, payload_type: ir.types.Type) anyerror!ast.Expr {
        if (ownedMoveHasUnsupportedGenericArray(payload_type, 0))
            return error.UnsupportedOwnedGenericArrayRepresentation;
        if (try self.ownedTaggedPayloadAt(payload_type, 0, false))
            return error.UnsupportedOwnedTaggedPayload;
        try self.markRuntimeImport();
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(payload_type);
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(place),
        } };
        const transfer: ast.Expr = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.takeOwned" }),
            .generic_args = generic_args,
            .args = args,
        } };
        if (!ownedMoveHasUnknownLength(payload_type, 0)) return transfer;
        // Only a proven finite wrapper reaches this path. A const length can
        // erase its last owned field, in which case copying moves no storage.
        return .{ .if_expr = .{
            .cond = try self.allocExpr(.{ .call = .{
                .callee = try self.allocExpr(.{ .ident = "r2z.alloc.supportsOwnedMove" }),
                .generic_args = generic_args,
                .args = &.{},
            } }),
            .then_body = try self.allocExpr(transfer),
            .else_body = try self.allocExpr(place),
        } };
    }

    /// Whether `expr_id` is a recorded hand-off site of an ARMED owner.
    ///
    /// An armed owner is exactly a carrier with a release waiting on it, so
    /// this is the one question an element read has to ask before it empties a
    /// slot: a carrier nobody releases has no second release to collide with,
    /// and copying out of it is what the source wrote.
    fn ownedElementSiteIsArmed(self: *const Lowerer, expr_id: ir.exprs.NodeId) bool {
        if (self.active_owned_capture_move) |active| {
            if (active.aliasAtSite(expr_id) != null) return true;
        }
        for (self.owned_scope_bindings.items) |*candidate| {
            if (candidate.sites.contains(expr_id)) return true;
        }
        return false;
    }

    /// `r2z.alloc.takeOwned(Elem, &carrier[i])` — an element read that empties
    /// the slot it read.
    ///
    /// An element read is a PLACE, and Rust moves out of a place by value, so
    /// `let first = owners[0];` empties that slot and leaves the carrier
    /// holding only what stayed. Copying instead leaves the slot and the new
    /// binding naming ONE allocation, and the two releases that follow — the
    /// new binding's and the carrier's — both free it.
    ///
    /// The carrier's release stays ARMED, and that is not an alternative to
    /// this: it is what a PARTIAL move means. `take_first_element` empties one
    /// slot and the array still owes a release for the rest, so disarming the
    /// carrier would leak exactly what stayed. Emptying the slot and keeping
    /// the release are the same claim, not competing ones — which is why a
    /// FIELD read out of an owner base already transfers here, in
    /// `emitDestructureBinding`, and only the INDEXED read did not.
    fn lowerOwnedElementTransfer(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        ie: ir.exprs.IndexExpr,
        place: ast.Expr,
    ) anyerror!?ast.Expr {
        if (!self.ownedElementSiteIsArmed(expr_id)) return null;
        const element_type = (try self.indexExprType(ie)) orelse return null;
        if (!ownedRuntimeContainerType(element_type)) return null;
        return try self.ownedTransferPlaceCall(place, element_type);
    }

    fn lowerWholeMatchArmPatterns(
        self: *Lowerer,
        arm: ir.exprs.MatchArm,
        option: ?OptionalMatchSubject,
    ) anyerror!LoweredMatchSelectors {
        if (arm.patterns.len == 0) return error.MissingMatchPattern;
        if (arm.patterns.len > self.ir.bodies.pats.len) {
            return error.MissingPatternNode;
        }
        const lowered_patterns = try self.lowerArmPatterns(arm.patterns);
        const capture = try self.referenceMatchCapture(arm.patterns);
        if (capture != null) {
            if (option) |subject| {
                // An optional arm's payload is bound by the statement its own
                // lowering introduces, because the Zig prong dispatches on a
                // test of the subject rather than on a tagged value and has no
                // payload to capture. The struct pattern stays exactly as it
                // is, for that lowering to rewrite into the test it matches on.
                // A subject with no place of its own is a borrow the source
                // could not have written, because the temporary a call makes is
                // gone before the arms run.
                if (!subject.by_place) return error.UnsupportedPattern;
            } else {
                const selector = switch (lowered_patterns[0]) {
                    .struct_pat => |pattern| pattern.name orelse return error.MissingPatternName,
                    else => return error.UnsupportedPattern,
                };
                lowered_patterns[0] = .{ .enum_literal = selector };
            }
        }
        return .{ .patterns = lowered_patterns, .capture = capture };
    }

    fn lowerWholeMatchArmBody(
        self: *Lowerer,
        arm: ir.exprs.MatchArm,
        lowered_patterns: []ast.Pattern,
        option: ?OptionalMatchSubject,
        capture: ?ast.Capture,
        alias: ?OwnedCaptureAlias,
    ) anyerror!ast.Expr {
        var arm_shadow_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer arm_shadow_names.deinit(self.alloc);
        for (arm.patterns) |p_id| {
            try self.appendPatternBindingName(p_id, &arm_shadow_names);
        }
        const lowered_arm = try self.lowerArmValueAndGuard(arm, arm_shadow_names.items, alias);
        // This shape has no place to put a guard, and a caller that has one
        // belongs on the ordered chain instead of losing it here.
        if (lowered_arm.guard != null) return error.UnsupportedMatchGuard;
        if (option) |subject|
            return self.lowerOptionalMatchArm(lowered_patterns, lowered_arm.value, subject, capture);
        return lowered_arm.value;
    }

    /// Whether Zig can take this expression's address, so a reference capture
    /// can point into the storage the source named.
    ///
    /// An indexed place counts, and so does a dereferenced one: `values[i]` is
    /// the element the index names and `p.*` is the place `p` points at, so an
    /// alias of either reaches the same storage. The index itself is not part
    /// of the verdict — it is evaluated once, by the binding, not by the alias.
    fn exprIsAddressable(value: ast.Expr) bool {
        return switch (value) {
            .ident, .field_access => true,
            .unary_op => |unary| unary.op == .deref and exprIsAddressable(unary.operand.*),
            // `a[i]` lowers to the `index` builtin, and Zig indexes an lvalue.
            .builtin => |builtin| std.mem.eql(u8, builtin.name, "index") and
                builtin.args.len == 2 and exprIsAddressable(builtin.args[0]),
            else => false,
        };
    }

    /// Bind the scrutinee once, ahead of the chain, and return the expression
    /// every dispatch reads.
    ///
    /// A binding captures the value, so a side-effecting scrutinee runs a
    /// single time however many dispatches read it. An arm that binds the
    /// subject by reference cannot use that copy: Zig hands a `|*name|` capture
    /// the address of the value its switch reads, and a copy would point into
    /// storage the source never sees. Such an arm takes the address of the
    /// scrutinee's own place instead, which evaluates the place once and still
    /// reaches the original storage. Rust allows a reference binding only on a
    /// place, so the alias is legal wherever the capture is; a temporary has no
    /// storage to alias and keeps the copy.
    fn bindGuardChainSubject(
        self: *Lowerer,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        scrutinee: *const ast.Expr,
        option: ?OptionalMatchSubject,
        arms: []const ir.exprs.MatchArm,
    ) anyerror!*const ast.Expr {
        if (option) |subject| {
            // An optional scrutinee is bound by the caller — to the value, or to
            // its own place when an arm borrows the payload — and every dispatch
            // reads `matchSubject`'s test of it, so this chain needs no second
            // local.
            return self.allocExpr(.{ .ident = subject.name });
        }
        if (try self.matchCapturesByReference(arms) and exprIsAddressable(scrutinee.*)) {
            const place_name = try self.iteratorTemporaryName("__r2z_match_place");
            try statements.append(self.alloc, .{ .let_stmt = .{
                .name = place_name,
                .init = .{ .unary_op = .{
                    .op = .addr_of,
                    .operand = try self.allocExpr(scrutinee.*),
                } },
                .is_mut = false,
            } });
            return self.allocExpr(.{ .unary_op = .{
                .op = .deref,
                .operand = try self.allocExpr(.{ .ident = place_name }),
            } });
        }
        const subject_name = try self.iteratorTemporaryName("__r2z_match_subject");
        try statements.append(self.alloc, .{ .let_stmt = .{
            .name = subject_name,
            .init = scrutinee.*,
            .is_mut = false,
        } });
        return self.allocExpr(.{ .ident = subject_name });
    }

    fn appendArmAlternatives(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        alternatives: *std.ArrayListUnmanaged(ir.exprs.NodeId),
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .@"or" => |pattern| {
                for (pattern.alternatives) |alternative| try self.appendArmAlternatives(alternative, alternatives);
            },
            else => try alternatives.append(self.alloc, pat_id),
        }
    }

    fn patternHasBindings(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!bool {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .binding => true,
            inline .struct_pat, .external_variant => |pattern| fields: {
                for (pattern.fields) |field| {
                    if (field.shorthand) break :fields true;
                    if (field.pat) |child| {
                        if (try self.patternHasBindings(child)) break :fields true;
                    }
                }
                break :fields false;
            },
            .reference => |pattern| try self.patternHasBindings(pattern.inner),
            .tuple => |pattern| elements: {
                for (pattern.elements) |child| {
                    if (try self.patternHasBindings(child)) break :elements true;
                }
                break :elements false;
            },
            .slice => |pattern| elements: {
                for (pattern.elements) |child| {
                    if (try self.patternHasBindings(child)) break :elements true;
                }
                break :elements if (pattern.rest) |child| try self.patternHasBindings(child) else false;
            },
            .@"or" => |pattern| alternatives: {
                for (pattern.alternatives) |child| {
                    if (try self.patternHasBindings(child)) break :alternatives true;
                }
                break :alternatives false;
            },
            else => false,
        };
    }

    fn armHasBoundAlternatives(self: *Lowerer, arm: ir.exprs.MatchArm) anyerror!bool {
        var multiple = arm.patterns.len > 1;
        for (arm.patterns) |pat_id| {
            if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
            if (self.ir.bodies.pats[pat_id].kind == .@"or") multiple = true;
        }
        if (!multiple) return false;
        for (arm.patterns) |pat_id| {
            if (try self.patternHasBindings(pat_id)) return true;
        }
        return false;
    }

    /// Alternatives bind the same Rust names, even when extraction gave each a local id.
    fn claimAlternativeBindings(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        canonical: *std.StringHashMapUnmanaged([]const u8),
    ) anyerror!void {
        const names = self.current_local_binding_names orelse return;
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .binding => |binding| {
                const emitted = try names.claimPatternAlias(
                    self.alloc,
                    &self.ir.graph.symbol_table,
                    pat_id,
                    binding.name,
                    canonical.get(binding.name),
                );
                try canonical.put(self.alloc, binding.name, emitted);
            },
            inline .struct_pat, .external_variant => |pattern| {
                for (pattern.fields) |field| {
                    if (field.pat) |child| try self.claimAlternativeBindings(child, canonical);
                }
            },
            .reference => |pattern| try self.claimAlternativeBindings(pattern.inner, canonical),
            .tuple => |pattern| {
                for (pattern.elements) |child| try self.claimAlternativeBindings(child, canonical);
            },
            .slice => |pattern| {
                for (pattern.elements) |child| try self.claimAlternativeBindings(child, canonical);
                if (pattern.rest) |child| try self.claimAlternativeBindings(child, canonical);
            },
            .@"or" => |pattern| {
                for (pattern.alternatives) |child| try self.claimAlternativeBindings(child, canonical);
            },
            else => {},
        }
    }

    /// Lower one arm of the chain into the plan its dispatch is built from.
    fn planGuardChainArm(
        self: *Lowerer,
        arm: ir.exprs.MatchArm,
        option: ?OptionalMatchSubject,
    ) anyerror!GuardChainArm {
        const selectors = try self.lowerWholeMatchArmPatterns(arm, option);
        var prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prelude.deinit(self.alloc);
        var nested: ?*NestedPayloadDispatch = null;
        // Nothing here is left to destructure in either shape: an optional
        // scrutinee's own lowering turns the struct pattern into the test the
        // prong dispatches on and binds the payload itself, and a capture on
        // any other subject has already replaced its struct pattern with the
        // tag it matches on.
        const patterns = if (selectors.capture == null and option == null)
            try self.bindMatchPatternFields(selectors.patterns, &prelude, &nested)
        else
            selectors.patterns;
        var arm_shadow_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer arm_shadow_names.deinit(self.alloc);
        for (arm.patterns) |p_id| {
            try self.appendPatternBindingName(p_id, &arm_shadow_names);
        }
        const bound_name = if (selectors.capture) |capture|
            capture.name
        else
            try self.matchArmBindingName(arm.patterns);
        const bound_by_ref = if (selectors.capture) |capture| capture.by_ref else false;
        const alias = try self.ownedCaptureAlias(arm.patterns, bound_name, bound_by_ref);
        const lowered_arm = try self.lowerArmValueAndGuard(arm, arm_shadow_names.items, alias);
        // The payload read-back is a prelude statement, not part of the value:
        // the guard reads the very binding it introduces, so it has to be in
        // scope before the test runs. It is bound before the prelude is handed
        // over, because handing it over empties the list.
        const raw_value = if (option) |subject|
            try self.lowerOptionalMatchArmInto(patterns, lowered_arm.value, subject, selectors.capture, &prelude)
        else
            lowered_arm.value;
        // Only the selected body owns the payload. A false guard must leave
        // it alive for the following arm rather than release its storage.
        const value = if (alias) |owned|
            try self.appendOwnedCaptureRelease(owned, raw_value)
        else
            raw_value;
        return .{
            .patterns = patterns,
            // The dispatch's subject is a test of the optional rather than a
            // tagged value, so there is no payload here for the emitter to
            // capture; the binding is the prelude statement above.
            .capture = if (option == null) selectors.capture else null,
            .prelude = try prelude.toOwnedSlice(self.alloc),
            .guard = lowered_arm.guard,
            .value = value,
            .nested = nested,
        };
    }

    /// The expression a dispatch arm ends on: the arm's result, handed to the
    /// chain's own label.
    ///
    /// A body that already leaves the function or its loop is kept as it is.
    /// Zig rejects a `break` with no operand beside one that carries a value,
    /// and a labelled exit to a source loop is the source's own, not the
    /// chain's to rewrite.
    fn guardArmYield(self: *Lowerer, label: ?[]const u8, value: ast.Expr) anyerror!ast.Expr {
        if (!matchYieldCarriesValue(value)) return value;
        return .{
            .break_expr = .{
                .value = try self.allocExpr(value),
                // A result only ever leaves the chain through its own label, and
                // the chain is labelled exactly when an arm carries one.
                .label = label orelse return error.MissingGuardChainLabel,
            },
        };
    }

    /// Append the statements that run one arm inside a dispatch prong.
    ///
    /// The chain's block is the only labelled block an arm may contain: a value
    /// the emitter had to wrap in a block of its own would name that inner
    /// label and carry the result out of the arm instead of into the chain. So
    /// an unlabelled block is flattened into the arm, and its tail becomes the
    /// yield — where nothing guards the arm.
    ///
    /// A guarded arm is different: Rust decides the arm with the guard before
    /// its body does anything, so the whole body runs inside the test. Splicing
    /// the statements ahead of it would let a false guard leave an arm's side
    /// effects behind.
    fn appendGuardArmStatements(
        self: *Lowerer,
        out: *std.ArrayListUnmanaged(ast.Stmt),
        label: ?[]const u8,
        guard: ?*const ast.Expr,
        value: ast.Expr,
    ) anyerror!void {
        if (guard) |condition| {
            try out.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .if_expr = .{
                .cond = condition,
                .then_body = try self.allocExpr(.{ .block = .{
                    .stmts = try self.guardArmBody(label, value),
                } }),
                .else_body = null,
            } }) });
            return;
        }
        switch (value) {
            .block => |block| blk: {
                if (block.label != null) break :blk;
                try out.appendSlice(self.alloc, block.stmts);
                const tail = block.expr orelse return;
                return self.appendGuardArmStatements(out, label, null, tail.*);
            },
            else => {},
        }
        try out.append(self.alloc, try self.appendGuardYield(label, value));
    }

    /// The statements a guarded arm runs inside its test.
    ///
    /// An unlabelled block IS the arm body, so it becomes the test's body and
    /// its tail is what hands the result to the chain. Anything else is the
    /// arm's own result, wrapped so the test has a body to hold it.
    fn guardArmBody(
        self: *Lowerer,
        label: ?[]const u8,
        value: ast.Expr,
    ) anyerror![]ast.Stmt {
        switch (value) {
            .block => |block| {
                // A block that already carries a label holds its own exit, so
                // it is emitted whole: its breaks have to keep reaching that
                // label rather than the chain's.
                if (block.label != null) {
                    const whole = try self.alloc.alloc(ast.Stmt, 1);
                    whole[0] = .{ .expr_stmt = try self.allocExpr(.{ .block = block }) };
                    return whole;
                }
                const stmts = try self.alloc.alloc(ast.Stmt, block.stmts.len + 1);
                @memcpy(stmts[0..block.stmts.len], block.stmts);
                var len = block.stmts.len;
                if (block.expr) |tail| {
                    stmts[len] = try self.appendGuardYield(label, tail.*);
                    len += 1;
                }
                return stmts[0..len];
            },
            else => {},
        }
        const stmts = try self.alloc.alloc(ast.Stmt, 1);
        stmts[0] = try self.appendGuardYield(label, value);
        return stmts;
    }

    /// The one statement an arm ends on: its result handed to the chain, or the
    /// exit its own body already is.
    fn appendGuardYield(
        self: *Lowerer,
        label: ?[]const u8,
        value: ast.Expr,
    ) anyerror!ast.Stmt {
        return .{ .expr_stmt = try self.allocExpr(try self.guardArmYield(label, value)) };
    }

    /// Lower a guarded `match` as a labeled block of ordered one-arm dispatches.
    ///
    /// Zig has no guard form in a switch prong, so every arm becomes its own
    /// `switch` over the subject and a guarded arm's prong holds
    /// `if (guard) break :__r2z_match_block <arm>`. A false guard leaves the
    /// prong, so the next dispatch runs and the candidate after it gets its
    /// turn — the ordered fall-through Rust specifies. A selector that does not
    /// match never reaches its guard, so no guard runs for an arm that cannot
    /// be chosen.
    ///
    /// The carrier is a labelled block and not a loop, because the chain is not
    /// a loop: nothing repeats. An arm body that breaks or continues is source
    /// control flow, and an unlabelled one would land on the carrier — the break
    /// would leave the chain carrying the wrong value, and the continue would
    /// start the chain over and evaluate the subject a second time. Naming the
    /// carrier's label on the exits the chain generates itself keeps the two
    /// apart.
    ///
    /// Every generated exit names the block, so nothing falls off the end of it
    /// and the block ends in `unreachable`. Rust checks exhaustiveness without
    /// counting a guarded arm, so the arms up to the first unguarded catch-all
    /// already cover every value; the chain stops there instead of emitting
    /// dispatches nothing can reach, and the fall-through past an exhaustive
    /// set of literals is the `unreachable`.
    ///
    /// The result is linear in the arm count, and the scrutinee is bound once
    /// above the chain, so every dispatch reads the same value and a
    /// side-effecting scrutinee runs a single time.
    fn lowerGuardedMatch(
        self: *Lowerer,
        scrutinee: *const ast.Expr,
        option: ?OptionalMatchSubject,
        arms: []const ir.exprs.MatchArm,
    ) anyerror!ast.Expr {
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        const subject = try self.bindGuardChainSubject(&statements, scrutinee, option, arms);

        var plans: std.ArrayListUnmanaged(GuardChainArm) = .empty;
        defer plans.deinit(self.alloc);
        var covers_every_value = false;
        var yields_value = false;
        for (arms) |arm| {
            if (covers_every_value) break;
            const split = try self.armHasBoundAlternatives(arm);
            var alternatives: std.ArrayListUnmanaged(ir.exprs.NodeId) = .empty;
            defer alternatives.deinit(self.alloc);
            if (split) {
                var canonical: std.StringHashMapUnmanaged([]const u8) = .empty;
                defer canonical.deinit(self.alloc);
                for (arm.patterns) |pat_id| {
                    try self.appendArmAlternatives(pat_id, &alternatives);
                    try self.claimAlternativeBindings(pat_id, &canonical);
                }
            }
            const count = if (split) alternatives.items.len else 1;
            for (0..count) |index| {
                var selected = arm;
                if (split) selected.patterns = alternatives.items[index .. index + 1];
                const plan = try self.planGuardChainArm(selected, option);
                covers_every_value = plan.guard == null and armSelectorsIrrefutable(plan.patterns);
                yields_value = yields_value or matchYieldCarriesValue(plan.value);
                try plans.append(self.alloc, plan);
                if (covers_every_value) break;
            }
        }

        // A chain whose every arm already leaves the function or its loop
        // carries no result, and Zig reports a label that names nothing as
        // unused, so the label exists exactly when some arm hands one over.
        const label: ?[]const u8 = if (yields_value)
            try self.iteratorTemporaryName("__r2z_match_block")
        else
            null;
        for (plans.items) |plan| {
            try self.appendGuardChainDispatch(&statements, label, option, subject, plan);
        }
        if (label != null) {
            // Every value the chain can be given was already taken by an arm
            // above, so this is only reached when the last of them failed its
            // own guard — a fall-through Rust's exhaustiveness rule rules out.
            try statements.append(self.alloc, .{
                .expr_stmt = try self.allocExpr(.{ .unreachable_ = {} }),
            });
        }
        return .{ .block = .{
            .label = label,
            .stmts = try statements.toOwnedSlice(self.alloc),
        } };
    }

    /// Append one arm's dispatch to the ordered chain.
    ///
    /// A refutable selector needs an `else` prong of its own, or a subject it
    /// does not match would leave the switch instead of reaching the arms Rust
    /// lists after this one.
    ///
    /// An arm that names a variant INSIDE its payload dispatches again from
    /// its own prong, and the guard and the result move inside that second
    /// prong: the guard reads a binding the nested tag introduced, so it may
    /// only run once that tag has matched.
    fn appendGuardChainDispatch(
        self: *Lowerer,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        label: ?[]const u8,
        option: ?OptionalMatchSubject,
        subject: *const ast.Expr,
        plan: GuardChainArm,
    ) anyerror!void {
        var body: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer body.deinit(self.alloc);
        // The field bindings come first, so the guard and the body both read
        // the names this arm's own pattern introduced.
        try body.appendSlice(self.alloc, plan.prelude);
        if (plan.nested) |nested| {
            try self.appendNestedPayloadDispatch(&body, nested, label, plan.guard, plan.value);
        } else {
            try self.appendGuardArmStatements(&body, label, plan.guard, plan.value);
        }
        // The arm is a block of statements rather than a tail expression, so
        // the exit that carries the result out stays a statement inside it.
        const dispatch = try self.alloc.alloc(
            ast.MatchArm,
            if (armSelectorsIrrefutable(plan.patterns)) 1 else 2,
        );
        dispatch[0] = .{
            .patterns = plan.patterns,
            .capture = plan.capture,
            .body = .{ .block = .{ .stmts = try body.toOwnedSlice(self.alloc) } },
        };
        if (dispatch.len == 2) {
            dispatch[1] = .{
                .patterns = &.{.wildcard},
                .body = .{ .unit = {} },
            };
        }
        try statements.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .match_expr = .{
            .target = try self.matchSubject(option, subject),
            .arms = dispatch,
        } }) });
    }

    /// Append the dispatch a nested payload pattern becomes, carrying the
    /// arm's guard and result into its deepest matching prong.
    ///
    /// Each level is a `switch` over the payload the level above bound: the
    /// matching prong reads that payload's own fields and dispatches again
    /// when a deeper pattern follows, and every other prong does NOTHING. A
    /// payload of another variant therefore leaves this arm altogether and
    /// reaches the arms Rust lists after it — which is the fall-through the
    /// ordered chain gives every other way an arm declines a value, and the
    /// reason the payload's fields are read here rather than unconditionally
    /// in the outer prong.
    fn appendNestedPayloadDispatch(
        self: *Lowerer,
        out: *std.ArrayListUnmanaged(ast.Stmt),
        nested: *const NestedPayloadDispatch,
        label: ?[]const u8,
        guard: ?*const ast.Expr,
        value: ast.Expr,
    ) anyerror!void {
        var prong: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer prong.deinit(self.alloc);
        try prong.appendSlice(self.alloc, nested.bindings);
        if (nested.inner) |inner| {
            try self.appendNestedPayloadDispatch(&prong, inner, label, guard, value);
        } else {
            try self.appendGuardArmStatements(&prong, label, guard, value);
        }
        const dispatch = try self.alloc.alloc(ast.MatchArm, 2);
        dispatch[0] = .{
            .patterns = nested.selectors,
            .capture = null,
            .body = .{ .block = .{ .stmts = try prong.toOwnedSlice(self.alloc) } },
        };
        dispatch[1] = .{
            .patterns = &.{.wildcard},
            .body = .{ .unit = {} },
        };
        try out.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .match_expr = .{
            .target = nested.subject,
            .arms = dispatch,
        } }) });
    }

    /// One read applied to the payload on the way to a binding.
    const IfLetProjection = union(enum) {
        /// The Nth element of a tuple payload.
        tuple_index: u32,
        /// The pointee of a reference. A pattern that reads THROUGH one takes
        /// a copy of the place it reached; it neither moves an owner nor keeps
        /// a borrow alive.
        dereference,
    };

    /// One binding an `if let` payload pattern introduces.
    const IfLetBinding = struct {
        name: []const u8,
        /// The PATTERN this name was read out of, which is what makes it
        /// claimable: two bindings may share a spelling, and only the pattern
        /// says which local each one is.
        pat_id: ir.exprs.NodeId,
        /// The name this binding is EMITTED under, claimed through the pattern
        /// so the collector and every later reference agree on one spelling.
        emitted_name: ?[]const u8 = null,
        /// The reads applied to the payload, in the order the pattern wrote
        /// them.
        ///
        /// An order and a count are both load-bearing, which is why this is
        /// not a flag: `Some(&(a, b))` reads `payload.*[0]` and not
        /// `payload[0].*`, and `Some((&&a, b))` reads through two references.
        /// A sequence ending in `dereference` is a copy of the place reached.
        projections: []const IfLetProjection,
    };

    /// Every name an `if let` payload pattern introduces, in source order.
    ///
    /// Zig's `if` takes no pattern, so the payload is bound once to a
    /// temporary and each name is read back out of it as an ordinary `let`.
    /// `Some(v)` introduces one binding over the whole payload;
    /// `Some((&first_byte, remaining))` introduces two, the first reading
    /// through the reference its pattern wrote.
    ///
    /// Only patterns whose reads are positional are answered. An or-pattern,
    /// a range, a literal or a named-field pattern names no single place in
    /// the payload to read from, and refusing is honest where picking one
    /// would not be.
    fn collectIfLetBindings(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        projections: []const IfLetProjection,
        out: *std.ArrayListUnmanaged(IfLetBinding),
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .wildcard => {},
            .binding => |binding| {
                if (binding.name.len == 0) return error.MissingBindingName;
                const owned = try self.alloc.dupe(IfLetProjection, projections);
                errdefer self.alloc.free(owned);
                try out.append(self.alloc, .{
                    .name = try self.alloc.dupe(u8, binding.name),
                    .pat_id = pat_id,
                    .projections = owned,
                });
            },
            .reference => |reference| {
                try self.collectIfLetBindings(
                    reference.inner,
                    try self.appendIfLetProjection(projections, .dereference),
                    out,
                );
            },
            .tuple => |tp| {
                if (tp.rest) return error.UnsupportedPattern;
                for (tp.elements, 0..) |element, index| {
                    try self.collectIfLetBindings(
                        element,
                        try self.appendIfLetProjection(projections, .{
                            .tuple_index = @intCast(index),
                        }),
                        out,
                    );
                }
            },
            // A variant nested INSIDE the payload needs its own test and its
            // own unwrap — `if let Some(Some(v))` has two conditions, not one
            // — and this shape can only express the outer one. Flattening it
            // would read the inner payload unconditionally, so it is refused
            // rather than approximated. The OUTER variant is stripped once by
            // the caller, before this runs.
            .struct_pat, .external_variant => return error.UnsupportedPattern,
            else => return error.UnsupportedPattern,
        }
    }

    /// `projections` plus one more read, as a fresh slice.
    fn appendIfLetProjection(
        self: *Lowerer,
        projections: []const IfLetProjection,
        step: IfLetProjection,
    ) ![]const IfLetProjection {
        const extended = try self.alloc.alloc(IfLetProjection, projections.len + 1);
        @memcpy(extended[0..projections.len], projections);
        extended[projections.len] = step;
        return extended;
    }

    /// One binding's reads applied to `base`, in the order the pattern wrote
    /// them: a tuple index reads one element of the payload and a dereference
    /// reads the pointee it reached.
    ///
    /// The order and the count are both part of what the pattern said, so they
    /// are replayed here exactly as `collectIfLetBindings` recorded them and
    /// never reconstructed from the types: `Some(&(a, b))` reads
    /// `base.*[0]` and not `base[0].*`, and `Some((&&a, b))` reads through
    /// two references.
    fn projectionOverSource(
        self: *Lowerer,
        base: ast.Expr,
        projections: []const IfLetProjection,
    ) anyerror!ast.Expr {
        var source = base;
        for (projections) |projection| {
            switch (projection) {
                .tuple_index => |field| {
                    const index_args = try self.alloc.alloc(ast.Expr, 2);
                    index_args[0] = source;
                    index_args[1] = .{ .lit = .{ .int = field } };
                    source = .{ .builtin = .{ .name = "index", .args = index_args } };
                },
                .dereference => {
                    const pointee = try self.allocExpr(source);
                    source = .{ .unary_op = .{ .op = .deref, .operand = pointee } };
                },
            }
        }
        return source;
    }

    /// Bind every name a tuple payload's pattern writes, reading each one out
    /// of the arm's own capture.
    ///
    /// A switch prong can introduce a name only through its capture, so a tuple
    /// pattern that reached the switch without the caller's projected prelude
    /// is projected here instead. The base is the capture's own pointee, which
    /// is the by-reference contract the optional and error-union siblings bind
    /// too: the payload is read where it stands rather than copied out of the
    /// union's slot, so nothing here can duplicate an owner the subject still
    /// releases.
    fn bindTupleOverCapture(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        capture_name: []const u8,
        out: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        const payload_pat = (try self.ifLetPayloadPattern(pat_id)) orelse
            return error.UnsupportedPattern;
        var bindings: std.ArrayListUnmanaged(IfLetBinding) = .empty;
        defer {
            for (bindings.items) |binding| self.alloc.free(binding.projections);
            bindings.deinit(self.alloc);
        }
        try self.collectIfLetBindings(payload_pat, &.{}, &bindings);
        for (bindings.items) |*binding| {
            if (self.current_local_binding_names) |names| {
                binding.emitted_name = try names.claimPatternName(
                    self.alloc,
                    &self.ir.graph.symbol_table,
                    binding.pat_id,
                    binding.name,
                );
            }
            try out.append(self.alloc, .{ .let_stmt = .{
                .name = try self.alloc.dupe(u8, binding.emitted_name orelse binding.name),
                .init = try self.projectionOverSource(
                    .{ .unary_op = .{
                        .op = .deref,
                        .operand = try self.allocExpr(.{
                            .ident = try self.alloc.dupe(u8, capture_name),
                        }),
                    } },
                    binding.projections,
                ),
            } });
        }
    }

    /// The pattern the payload itself is matched against, or null when the
    /// payload was IGNORED.
    ///
    /// The variant is stripped ONCE, here, because Zig's `if` tests the option
    /// and hands over its payload already unwrapped. A wildcard payload is not
    /// written as one: the IR records `Some(_)` as a variant whose field list
    /// is EMPTY, because there is no name to bind — which says nothing about
    /// the variant's arity, and nothing here is allowed to read it as though
    /// the variant carried no payload. It is still a match; it just introduces
    /// no name, so null is the whole answer and no placeholder pattern is
    /// invented for it. `Some` and `None` are told apart by
    /// `ifLetOptionIsPresent`, not by this: a zero-field `None` means the same
    /// thing structurally and means the OPPOSITE branch.
    ///
    /// A variant that declares MORE than one field names no single payload this
    /// shape can read, and says so.
    fn ifLetPayloadPattern(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!?ir.exprs.NodeId {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .struct_pat => |sp| if (sp.fields.len == 0)
                null
            else if (sp.fields.len == 1)
                sp.fields[0].pat orelse error.UnsupportedPattern
            else
                error.UnsupportedPattern,
            .external_variant => |variant| if (variant.fields.len == 0)
                null
            else if (variant.fields.len == 1)
                variant.fields[0].pat orelse error.UnsupportedPattern
            else
                error.UnsupportedPattern,
            else => error.UnsupportedPattern,
        };
    }
    fn subjectIsOption(self: *const Lowerer, ty: ir.types.Type) bool {
        return ty == .option or self.canonicalExternalMethodType(ty) == .option;
    }

    const IfLetSubjectPlan = struct {
        subject_type: ir.types.Type,
        is_option: bool,
        is_error_union: bool,
        rvalue: bool,
        owner: ?[]const u8,
        owns_storage: bool,

        fn route(self: IfLetSubjectPlan) IfLetRoute {
            if (self.is_option) return .optional;
            if (self.is_error_union) return .error_union;
            return .tagged;
        }
    };

    fn ifLetSubjectPlan(self: *Lowerer, il: ir.exprs.IfLetExpr) anyerror!IfLetSubjectPlan {
        const subject_type = (try self.exprType(il.scrutinee)) orelse
            return error.MissingExpressionType;
        const owner = self.scopeOwnerHandleForPath(il.scrutinee);
        const rvalue = self.ifLetSubjectIsRvalue(il.scrutinee);
        return .{
            .subject_type = subject_type,
            .is_option = self.subjectIsOption(subject_type),
            .is_error_union = self.resultUsesErrorUnion(subject_type),
            .rvalue = rvalue,
            .owner = owner,
            .owns_storage = rvalue or owner != null,
        };
    }

    fn ifLetRoute(plan: IfLetSubjectPlan) IfLetRoute {
        return plan.route();
    }

    fn ifLetSubjectIsRvalue(self: *Lowerer, scrutinee_id: ir.exprs.NodeId) bool {
        if (scrutinee_id >= self.ir.bodies.exprs.len) return false;
        return switch (self.ir.bodies.exprs[scrutinee_id].kind) {
            .call, .core_call, .method_call, .struct_lit, .array, .vec_lit, .external_variant, .enum_variant, .block, .match, .if_else, .if_let, .try_ => true,
            else => false,
        };
    }

    const IfLetRoute = enum {
        optional,
        error_union,
        tagged,
    };

    fn ifLetPayloadBase(
        self: *Lowerer,
        route: IfLetRoute,
        subject_name: []const u8,
        capture_name: []const u8,
        variant_field: ?[]const u8,
    ) anyerror!ast.Expr {
        return switch (route) {
            .optional => .{ .unary_op = .{
                .op = .deref,
                .operand = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, capture_name) }),
            } },
            .error_union => if (variant_field != null and std.mem.eql(u8, variant_field.?, "Err"))
                .{ .ident = try self.alloc.dupe(u8, capture_name) }
            else
                .{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(.{ .ident = capture_name }) } },
            .tagged => .{ .field_access = .{
                .target = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, subject_name) }),
                .field_name = try self.alloc.dupe(u8, variant_field orelse return error.UnsupportedPattern),
            } },
        };
    }

    fn ifLetVariantPayloadField(self: *Lowerer, pat_id: ir.exprs.NodeId) ?[]const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return null;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .struct_pat => |structure| self.variantSingleBindingField(
                self.variantNameForDef(structure.def),
                structure.fields,
            ),
            .external_variant => |variant| self.variantSingleBindingField(
                variant.variant,
                variant.fields,
            ),
            else => null,
        };
    }

    fn variantNameForDef(self: *const Lowerer, def: ir.spine.EntityId) ?[]const u8 {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        const name = entity.renamed_to orelse entity.name;
        return if (name.len == 0) null else name;
    }

    fn variantSingleBindingField(
        self: *const Lowerer,
        name: ?[]const u8,
        fields: []const ir.exprs.FieldPat,
    ) ?[]const u8 {
        if (fields.len != 1) return null;
        const inner = fields[0].pat orelse return null;
        if (inner >= self.ir.bodies.pats.len) return null;
        return name;
    }

    fn ifLetBindsByReference(self: *const Lowerer, bindings: []const IfLetBinding) bool {
        for (bindings) |binding| {
            if (binding.pat_id >= self.ir.bodies.pats.len) continue;
            const node = self.ir.bodies.pats[binding.pat_id];
            const binding_pat = switch (node.kind) {
                .binding => |value| value,
                else => continue,
            };
            if (binding_pat.mode != .value) return true;
        }
        return false;
    }

    fn ifLetPayloadIsReachable(self: *Lowerer, il: ir.exprs.IfLetExpr, plan: IfLetSubjectPlan) bool {
        if (!plan.owns_storage) return false;
        return switch (plan.route()) {
            .optional, .error_union => true,
            .tagged => self.ifLetVariantPayloadField(il.pattern) != null,
        };
    }

    const IfLetPayloadTake = struct {
        alias: ?OwnedCaptureAlias,
        stmts: []const ast.Stmt,
    };

    fn ifLetPayloadTake(
        self: *Lowerer,
        il: ir.exprs.IfLetExpr,
        plan: IfLetSubjectPlan,
        subject_name: []const u8,
        capture_name: []const u8,
        bindings: []const IfLetBinding,
        alias: ?OwnedCaptureAlias,
    ) anyerror!?IfLetPayloadTake {
        if (bindings.len != 1) return null;
        if (bindings[0].projections.len != 0) return null;
        const binding = bindings[0];
        const payload_name = try self.alloc.dupe(u8, binding.emitted_name orelse binding.name);
        if (alias) |owned| {
            const base = try self.ifLetPayloadBase(
                plan.route(),
                subject_name,
                capture_name,
                self.ifLetVariantPayloadField(il.pattern),
            );
            const stmts = try self.alloc.alloc(ast.Stmt, 2);
            errdefer self.alloc.free(stmts);
            stmts[0] = .{ .let_stmt = .{
                .name = payload_name,
                .init = try self.ownedTransferPlaceCall(base, owned.payload_type),
                .is_mut = true,
            } };
            stmts[1] = try self.ownerReleaseStatement(
                owned.alias_name,
                ownerReleasesElements(owned.payload_type),
            );
            return .{ .alias = owned, .stmts = stmts };
        }
        const borrows = self.ifLetBindsByReference(bindings[0..1]);
        if (plan.route() == .tagged and !borrows) return null;
        const binding_init: ast.Expr = if (borrows)
            .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(try self.ifLetPayloadBase(
                plan.route(),
                subject_name,
                capture_name,
                self.ifLetVariantPayloadField(il.pattern),
            )) } }
        else switch (plan.route()) {
            .optional => blk: {
                const unwrap_args = try self.alloc.alloc(ast.Expr, 1);
                unwrap_args[0] = .{ .ident = subject_name };
                break :blk .{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.option.unwrap" }),
                    .args = unwrap_args,
                } };
            },
            .error_union => try self.ifLetPayloadBase(
                plan.route(),
                subject_name,
                capture_name,
                self.ifLetVariantPayloadField(il.pattern),
            ),
            .tagged => return error.UnsupportedPattern,
        };
        const stmts = try self.alloc.alloc(ast.Stmt, 1);
        errdefer self.alloc.free(stmts);
        stmts[0] = .{ .let_stmt = .{
            .name = payload_name,
            .init = binding_init,
        } };
        return .{ .alias = null, .stmts = stmts };
    }

    fn ifLetOwnedPayloadAlias(
        self: *Lowerer,
        il: ir.exprs.IfLetExpr,
        plan: IfLetSubjectPlan,
        bindings: []const IfLetBinding,
    ) anyerror!?OwnedCaptureAlias {
        if (!try self.ifLetBindsWholeOwnedPayload(il, plan)) return null;
        if (bindings.len != 1) return null;
        const binding = bindings[0];
        if (binding.pat_id >= self.ir.bodies.pats.len) return null;
        const payload_type = try self.ifLetSelectedPayloadType(il, plan, binding.pat_id);
        return .{
            .source_name = binding.name,
            .capture_name = binding.emitted_name orelse binding.name,
            .alias_name = binding.emitted_name orelse binding.name,
            .payload_type = payload_type,
        };
    }

    fn lowerIfLetBranchOverAlias(
        self: *Lowerer,
        owned: OwnedCaptureAlias,
        body: ir.exprs.BlockExpr,
    ) anyerror!ast.Block {
        const previous = self.active_closure_capture_overrides.get(owned.source_name);
        try self.active_closure_capture_overrides.put(
            self.alloc,
            owned.source_name,
            owned.alias_name,
        );
        const previous_move = self.active_owned_capture_move;
        defer {
            if (previous) |shadowed| {
                const entry = self.active_closure_capture_overrides.getPtr(owned.source_name).?;
                entry.* = shadowed;
            } else {
                _ = self.active_closure_capture_overrides.remove(owned.source_name);
            }
            self.active_owned_capture_move = previous_move;
        }
        var installed = try self.collectOwnedCaptureMovesOverBlock(owned, body);
        defer installed.sites.deinit(self.alloc);
        const installed_entries = [_]OwnedCaptureMove{installed};
        self.active_owned_capture_move = .{ .entries = &installed_entries };
        return self.lowerBlock(body);
    }

    fn ifLetCarrierReleaseWanted(
        self: *const Lowerer,
        subject_type: ir.types.Type,
        route: IfLetRoute,
        rvalue: bool,
        taken: bool,
    ) bool {
        _ = self;
        if (!rvalue) return false;
        if (!ownedRuntimeContainerType(subject_type)) return false;
        if (route == .tagged) return true;
        return !taken;
    }
    const IfLetProjectedClass = struct {
        payload_pat: ?ir.exprs.NodeId,
        source_type: ?ir.types.Type,
        variant_field: ?[]const u8,
        owns_any: bool,
    };

    fn ifLetProjectedClassify(
        self: *Lowerer,
        il: ir.exprs.IfLetExpr,
        route: IfLetRoute,
        plan: IfLetSubjectPlan,
    ) anyerror!?IfLetProjectedClass {
        if (!plan.owns_storage) return null;
        if (route == .optional and !try self.ifLetOptionIsPresent(il.pattern)) return null;
        const payload_pat = (try self.ifLetPayloadPattern(il.pattern)) orelse return null;
        if (payload_pat >= self.ir.bodies.pats.len) return null;
        if (self.ir.bodies.pats[payload_pat].kind == .reference) return null;
        const source_type = try self.ifLetSelectedPayloadType(il, plan, payload_pat);
        var owns_any = false;
        if (!try self.ifLetProjectedShapeQuery(payload_pat, source_type, &owns_any)) return null;
        const variant_field = switch (route) {
            .tagged => self.ifLetVariantPayloadField(il.pattern) orelse return null,
            else => null,
        };
        return .{
            .payload_pat = payload_pat,
            .source_type = source_type,
            .variant_field = variant_field,
            .owns_any = owns_any,
        };
    }

    fn ifLetSelectedPayloadType(self: *Lowerer, il: ir.exprs.IfLetExpr, plan: IfLetSubjectPlan, payload_pat: ir.exprs.NodeId) anyerror!ir.types.Type {
        return self.ifLetSelectedPayloadTypeForSubject(il, plan.subject_type, payload_pat);
    }

    fn ifLetSelectedPayloadTypeForSubject(self: *Lowerer, il: ir.exprs.IfLetExpr, subject: ir.types.Type, payload_pat: ir.exprs.NodeId) anyerror!ir.types.Type {
        if (subject == .option) return subject.option.*;
        if (self.canonicalExternalMethodType(subject)) |canonical| {
            if (canonical == .option) {
                const args = switch (subject) {
                    .generic_inst => |inst| inst.args.params,
                    .external_nominal => |external| external.args,
                    else => return error.MissingTypeId,
                };
                if (args.len != 1) return error.GenericArgumentArityMismatch;
                return args[0];
            }
        }
        if (resultDescriptorOf(subject)) |descriptor| {
            const field = self.ifLetVariantPayloadField(il.pattern) orelse return error.MissingTypeId;
            if (std.mem.eql(u8, field, "Ok")) return descriptor.ok;
            if (std.mem.eql(u8, field, "Err")) return descriptor.err;
        }
        const type_id = self.ir.bodies.pats[payload_pat].ty orelse return error.MissingTypeId;
        return self.typeById(type_id);
    }

    fn ifLetProjectedShapeQuery(
        self: *Lowerer,
        payload_pat: ir.exprs.NodeId,
        payload_type: ir.types.Type,
        owns_any: *bool,
    ) anyerror!bool {
        if (payload_pat >= self.ir.bodies.pats.len) return false;
        const fields = switch (payload_type) {
            .tuple => |tuple_fields| tuple_fields,
            else => return false,
        };
        switch (self.ir.bodies.pats[payload_pat].kind) {
            .tuple => |tp| {
                if (tp.rest) return false;
                if (tp.elements.len != fields.len) return false;
                for (tp.elements, 0..) |element, index| {
                    if (element >= self.ir.bodies.pats.len) return false;
                    const node = self.ir.bodies.pats[element];
                    const element_type = fields[index];
                    switch (node.kind) {
                        .tuple => if (!try self.ifLetProjectedShapeQuery(element, element_type, owns_any)) {
                            return false;
                        },
                        .wildcard, .reference => {},
                        .binding => |binding| {
                            if (binding.mode == .value and
                                try self.tupleFieldOwnsRuntimeStorage(element, element_type))
                            {
                                owns_any.* = true;
                            }
                        },
                        else => return false,
                    }
                }
                return true;
            },
            else => return false,
        }
    }

    fn tupleFieldOwnsRuntimeStorage(
        self: *Lowerer,
        element_pat: ir.exprs.NodeId,
        element_type: ir.types.Type,
    ) anyerror!bool {
        if (try self.ownedTaggedPayloadAt(element_type, 0, false)) return false;
        if (ownedMoveHasUnsupportedGenericArray(element_type, 0)) return false;
        if (element_pat >= self.ir.bodies.pats.len) return false;
        if (self.ir.bodies.pats[element_pat].ty) |type_id| {
            const recorded = try self.typeById(type_id);
            if (typeEquals(recorded, element_type)) return try self.patternBindsRuntimeOwner(element_pat);
        }
        return ownedRuntimeContainerType(element_type);
    }

    fn ifLetRequireClaimDefs(
        self: *Lowerer,
        projected: IfLetProjectedClass,
    ) anyerror!void {
        if (!projected.owns_any) return;
        const payload_pat = projected.payload_pat orelse return error.UnsupportedPattern;
        const tuple_pattern = switch (self.ir.bodies.pats[payload_pat].kind) {
            .tuple => |tp| tp,
            else => return error.UnsupportedPattern,
        };
        var claims: ClaimCollector = .empty;
        defer claims.deinit(self.alloc);
        const ctx = TupleDestructureCtx{
            .claims = &claims,
            .drains_carrier = true,
            .source_type = projected.source_type,
        };
        try self.requireDestructureClaimDefs(tuple_pattern, &ctx);
    }

    fn emitIfLetProjectedPrelude(
        self: *Lowerer,
        projected: IfLetProjectedClass,
        dispatch_name: []const u8,
        capture_name: []const u8,
        plan: IfLetSubjectPlan,
        then_block: ir.exprs.BlockExpr,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
        owner_mark: *?usize,
    ) anyerror!void {
        try self.ifLetRequireClaimDefs(projected);
        const payload_pat = projected.payload_pat orelse return error.UnsupportedPattern;
        const tuple_pattern = switch (self.ir.bodies.pats[payload_pat].kind) {
            .tuple => |tp| tp,
            else => return error.UnsupportedPattern,
        };
        const base = try self.ifLetPayloadBase(
            plan.route(),
            dispatch_name,
            capture_name,
            projected.variant_field,
        );
        var claims: ClaimCollector = .empty;
        defer claims.deinit(self.alloc);
        try self.emitTupleDestructure(
            tuple_pattern,
            &base,
            prelude,
            &.{ .claims = &claims, .drains_carrier = true, .source_type = projected.source_type },
        );
        owner_mark.* = self.owned_scope_bindings.items.len;
        errdefer self.releaseOwnerScopeFrom(owner_mark.*.?);
        try self.installDestructureOwnerMoves(claims.items, then_block, 0);
    }

    fn releaseOwnerScopeFrom(self: *Lowerer, mark: usize) void {
        for (self.owned_scope_bindings.items[mark..]) |*binding| {
            binding.sites.deinit(self.alloc);
        }
        self.owned_scope_bindings.shrinkRetainingCapacity(mark);
    }
    fn ifLetEmitsOwnedRelease(self: *Lowerer, il: ir.exprs.IfLetExpr) anyerror!bool {
        const subject_type = try self.exprType(il.scrutinee) orelse return false;
        if (!ownedRuntimeContainerType(subject_type)) return false;
        const route = self.ifLetMaskRoute(subject_type);
        const rvalue = self.ifLetSubjectIsRvalue(il.scrutinee);
        const payload_pat = if (route == .optional and !try self.ifLetOptionIsPresent(il.pattern)) null else try self.ifLetPayloadPattern(il.pattern);
        var taken = false;
        var projected = false;
        if (payload_pat) |pat_id| {
            const payload_type = try self.ifLetSelectedPayloadTypeForSubject(il, subject_type, pat_id);
            const pattern = self.ir.bodies.pats[pat_id];
            taken = pattern.kind == .binding and pattern.kind.binding.mode == .value and ownedRuntimeContainerType(payload_type);
            var owns_any = false;
            projected = try self.ifLetProjectedShapeQuery(pat_id, payload_type, &owns_any) and owns_any;
        }
        return self.ifLetCarrierReleaseWanted(subject_type, route, rvalue, taken) or taken or projected;
    }

    fn ifLetMaskRoute(self: *const Lowerer, subject_type: ir.types.Type) IfLetRoute {
        if (self.subjectIsOption(subject_type)) return .optional;
        if (self.resultUsesErrorUnion(subject_type)) return .error_union;
        return .tagged;
    }

    fn ifLetBindsWholeOwnedPayload(self: *Lowerer, il: ir.exprs.IfLetExpr, plan: IfLetSubjectPlan) anyerror!bool {
        if (plan.is_option and !try self.ifLetOptionIsPresent(il.pattern)) return false;
        const pat_id = try self.ifLetPayloadPattern(il.pattern) orelse return false;
        const pattern = self.ir.bodies.pats[pat_id];
        if (pattern.kind != .binding or pattern.kind.binding.mode != .value) return false;
        if (!self.ifLetPayloadIsReachable(il, plan)) return false;
        return try self.destructureFieldOwnsStorage(try self.ifLetSelectedPayloadType(il, plan, pat_id));
    }

    fn lowerErrorUnionIfLet(
        self: *Lowerer,
        subject_name: []const u8,
        capture_name: ?[]const u8,
        then_block: ast.Block,
        else_expr: ?*const ast.Expr,
        error_variant: bool,
    ) anyerror!ast.Expr {
        if (error_variant) return .{ .if_expr = .{
            .cond = try self.allocExpr(.{ .ident = subject_name }),
            .then_capture = .{ .name = "_" },
            .then_body = else_expr orelse try self.allocExpr(.{ .unit = {} }),
            .else_body = try self.allocExpr(.{ .block = then_block }),
            .else_capture = .{ .name = capture_name orelse "_" },
        } };
        return .{ .if_expr = .{
            .cond = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, subject_name) }),
            .then_capture = if (capture_name) |name|
                ast.Capture{ .name = name, .by_ref = true }
            else
                ast.Capture{ .name = "_" },
            .then_body = try self.allocExpr(.{ .block = then_block }),
            .else_body = else_expr orelse try self.allocExpr(.{ .unit = {} }),
            .else_capture = .{ .name = "_" },
        } };
    }

    /// An `if let` subject, evaluated once and ready to bind: a reference is
    /// dereferenced so the binding holds the value rather than a pointer to it.
    ///
    /// The subject is bound before anything reads it, so a side-effecting
    /// scrutinee runs exactly once however many dispatches test it. What the
    /// source's pattern is tested AGAINST is the caller's question: an optional
    /// is compared with `null`, a tagged union is switched on its tag, and
    /// this function is the part both of them share.
    fn lowerIfLetSubject(self: *Lowerer, scrutinee_id: ir.exprs.NodeId) anyerror!ast.Expr {
        const scrutinee = try self.lowerExpr(scrutinee_id);
        const subject_type = try self.exprType(scrutinee_id) orelse
            return error.MissingExpressionType;
        if (subject_type != .reference) return scrutinee;
        return .{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(scrutinee) } };
    }

    /// Whether an `if let` on an optional names the arm that HOLDS a value.
    ///
    /// `Some` and `None` reach here in the same shape — a variant, with a
    /// payload or with its payload ignored — and they take opposite branches,
    /// so the variant's own identity is what decides. It is read from the
    /// declaration the graph recorded, not from the spelling in the source:
    /// the entity must be a `variant`, and the enum that owns it must be the
    /// Option this subject is. A local `enum Option` cannot pass for one,
    /// because a value of it is not an optional and the caller never routes a
    /// non-optional subject here.
    fn ifLetOptionIsPresent(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!bool {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .struct_pat => |sp| try self.optionVariantIsPresent(sp.def),
            .path => |path_pat| try self.optionVariantIsPresent(path_pat.def),
            .external_variant => |variant| blk: {
                if (!externalPathEqual(variant.owner.path, &.{ "core", "option", "Option" }) and
                    !externalPathEqual(variant.owner.path, &.{ "std", "option", "Option" }))
                {
                    break :blk error.UnsupportedPattern;
                }
                break :blk try optionArmHoldsValue(variant.variant);
            },
            else => error.UnsupportedPattern,
        };
    }

    fn optionVariantIsPresent(self: *Lowerer, def: ir.spine.EntityId) anyerror!bool {
        const entity = self.ir.graph.symbol_table.get(def) orelse return error.MissingDefinition;
        if (entity.kind != .variant) return error.UnsupportedPattern;
        const owner = self.ir.graph.symbol_table.get(entity.parent orelse
            return error.MissingParentId) orelse return error.MissingDefinition;
        if (owner.kind != .enum_ or !std.mem.eql(u8, owner.name, "Option")) {
            return error.UnsupportedPattern;
        }
        return optionArmHoldsValue(entity.name);
    }

    /// Polarity of one arm of the Option enum, or a refusal when the name is
    /// neither. These are the only two arms an `if let` can name, and they
    /// mean opposite branches, so an arm this does not recognise is refused
    /// rather than guessed at — a wrong answer here would silently run the
    /// source's `then` where it wrote `else`.
    fn optionArmHoldsValue(name: []const u8) anyerror!bool {
        if (std.mem.eql(u8, name, "Some")) return true;
        if (std.mem.eql(u8, name, "None")) return false;
        return error.UnsupportedPattern;
    }

    /// `if let Enum::Variant(..) = e` as a `switch`: the prong that takes is
    /// the one that makes the payload's own binding, so the reads that unpack
    /// it are emitted inside that prong beside the branch body. A name bound
    /// ahead of the switch would refer to storage the switch never carried
    /// out, which is the whole difference between this and a condition.
    ///
    /// The subject was bound once, ahead of this, so a scrutinee with side
    /// effects runs exactly as the source ran it. The selectors come from
    /// `lowerArmPatterns` and the payload reads from `bindMatchPatternFields`
    /// — the same two a `match` arm goes through — so a unit variant and a
    /// struct-like variant all dispatch the way a `match` over the same value
    /// would. No optional is invented for a value that has none: a subject with
    /// no tag to switch on is a different pattern, and the subject's own type
    /// is what chose this route.
    ///
    /// A TUPLE payload is the one shape a prong cannot spell, and that is why
    /// `lowerArmPatterns` refuses one. Its names are bound by whichever of the
    /// two places that CAN bind them is in hand: the caller's prelude, which
    /// drains an owned payload slot by slot out of the selected arm, or this
    /// arm's own capture, which is the same by-reference contract the optional
    /// and error-union siblings bind. With neither in hand the refusal stands,
    /// because the prong would then declare none of the names the source wrote.
    fn lowerVariantIfLetSwitch(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        subject_name: []const u8,
        then_block: ast.Block,
        else_expr: ?*const ast.Expr,
        owned_payload: ?OwnedCaptureAlias,
        projected: bool,
        capture_name: ?[]const u8,
    ) anyerror!ast.Expr {
        const tuple_payload = try self.patternHasTupleElement(pat_id, 0);
        const names_bound_ahead = owned_payload != null or projected;
        if (tuple_payload and !names_bound_ahead and capture_name == null) {
            return error.UnsupportedPattern;
        }
        // A tuple prong carries its variant's own selector and nothing more: the
        // elements are bound by the prelude or the capture, and lowering them
        // here would redeclare those names under a form Zig cannot destructure.
        // `lowerArmPatterns` refuses that shape outright, so the tuple lowers the
        // one pattern itself into an OWNED slice: both selector routes below read
        // `[]ast.Pattern`, and the slice has to outlive this frame because
        // `bindMatchPatternFields` hands back its input when no field has to be
        // read, so a stack one-element temporary would dangle in the emitted arm.
        const lowered: []ast.Pattern = if (tuple_payload) tuple_prong: {
            const owned = try self.alloc.alloc(ast.Pattern, 1);
            owned[0] = try self.lowerPattern(pat_id);
            break :tuple_prong owned;
        } else try self.lowerArmPatterns(&.{pat_id});
        var payload_reads: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer payload_reads.deinit(self.alloc);
        var nested: ?*NestedPayloadDispatch = null;
        const selectors = if (names_bound_ahead or tuple_payload)
            try self.ifLetOwnedVariantSelectors(lowered)
        else
            try self.bindMatchPatternFields(lowered, &payload_reads, &nested);
        if (nested != null or selectors.len == 0) return error.UnsupportedPattern;
        var arm_capture: ?ast.Capture = null;
        if (tuple_payload and !names_bound_ahead) {
            const capture = capture_name.?;
            arm_capture = .{ .name = try self.alloc.dupe(u8, capture), .by_ref = true };
            try self.bindTupleOverCapture(pat_id, capture, &payload_reads);
        }
        var matched_block = then_block;
        if (payload_reads.items.len != 0) {
            const stmts = try self.alloc.alloc(ast.Stmt, payload_reads.items.len + then_block.stmts.len);
            @memcpy(stmts[0..payload_reads.items.len], payload_reads.items);
            @memcpy(stmts[payload_reads.items.len..], then_block.stmts);
            matched_block.stmts = stmts;
        }
        const otherwise = try self.alloc.alloc(ast.Pattern, 1);
        otherwise[0] = .wildcard;
        const arms = try self.alloc.alloc(ast.MatchArm, 2);
        arms[0] = .{ .patterns = selectors, .body = .{ .block = matched_block }, .capture = arm_capture };
        arms[1] = .{ .patterns = otherwise, .body = if (else_expr) |branch| branch.* else .{ .unit = {} } };
        return .{ .match_expr = .{
            .target = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, subject_name) }),
            .arms = arms,
        } };
    }

    fn ifLetOwnedVariantSelectors(self: *Lowerer, lowered: []ast.Pattern) anyerror![]ast.Pattern {
        if (lowered.len != 1) return error.UnsupportedPattern;
        const name = switch (lowered[0]) {
            .struct_pat => |structure| structure.name orelse return error.MissingPatternName,
            .enum_literal => |literal| literal,
            else => return error.UnsupportedPattern,
        };
        const selectors = try self.alloc.alloc(ast.Pattern, 1);
        selectors[0] = .{ .enum_literal = name };
        return selectors;
    }

    pub fn lowerExpr(self: *Lowerer, expr_id: ir.exprs.NodeId) anyerror!ast.Expr {
        if (expr_id >= self.ir.bodies.exprs.len) {
            return error.MissingExpressionNode;
        }

        // A context that names a trait object asks for that trait's BORROWED
        // HANDLE, so a concrete borrow arriving at one is erased here. Every
        // site that can state such a context — a declared parameter, a
        // declared binding, a payload an enclosing expression already typed —
        // reaches this one answer, and the handle points at the caller's own
        // value, so nothing is copied to perform the erasure.
        if (self.dynCoercionContext()) |handle| {
            if (!try self.exprAlreadyDynTrait(expr_id, handle)) {
                const previous_value_type = self.expected_value_type;
                const previous_argument_type = self.expected_argument_type;
                self.expected_value_type = null;
                self.expected_argument_type = null;
                const erased = self.lowerExpr(expr_id) catch |err| {
                    self.expected_value_type = previous_value_type;
                    self.expected_argument_type = previous_argument_type;
                    return err;
                };
                self.expected_value_type = previous_value_type;
                self.expected_argument_type = previous_argument_type;
                return self.buildDynTraitHandle(handle, expr_id, erased);
            }
        }

        const ir_expr = self.ir.bodies.exprs[expr_id];

        return switch (ir_expr.kind) {
            .literal => |lit| switch (lit) {
                .int => |il| ast.Expr{ .lit = .{ .int = il.value } },
                .float => |fl| ast.Expr{ .lit = .{ .float = fl.value } },
                .character => |cl| ast.Expr{ .lit = .{ .char_lit = @intCast(cl.value) } },
                .string => |sl| ast.Expr{ .lit = .{ .str = try self.alloc.dupe(u8, sl.bytes) } },
                // A Zig string literal is a `*const [N:0]u8`, so a byte string
                // that stands for a `[u8; N]` value has to be spelled as an
                // array initializer. A byte string standing for a slice keeps
                // the literal form, which is what a `&[u8; N]` argument wants.
                .byte_array => |ba| blk_bytes: {
                    const elem_ast: ?ast.Type = blk_elem: {
                        const type_id = ir_expr.ty orelse break :blk_elem null;
                        break :blk_elem switch (try self.typeById(type_id)) {
                            .array => |array| try self.lowerType(array.elem),
                            else => null,
                        };
                    };
                    const literal = ast.Expr{ .lit = .{ .str = try self.alloc.dupe(u8, ba.items) } };
                    const elem_type = elem_ast orelse break :blk_bytes literal;
                    const items = try self.alloc.alloc(ast.Expr, ba.items.len);
                    for (ba.items, 0..) |byte, i| items[i] = ast.Expr{ .lit = .{ .int = byte } };
                    break :blk_bytes ast.Expr{ .multi_array = .{
                        .type_name = elem_type,
                        .elements = items,
                    } };
                },
                .boolean => |b| ast.Expr{ .lit = .{ .bool_lit = b } },
            },
            .array => |a| blk: {
                const literal_type = try self.arrayLiteralType(expr_id, a);
                // A Rust tuple expression reaches the backend as an array
                // node carrying a tuple type. Zig spells that value
                // `.{ a, b }`; `[_]struct { A, B }{ a, b }` would be an
                // array of tuples, which is a different value entirely.
                const is_tuple = if (literal_type) |known| switch (known) {
                    .tuple => true,
                    else => false,
                } else false;
                if (a.repeat == null and is_tuple) {
                    var items = try self.alloc.alloc(ast.Expr, a.elements.len);
                    for (a.elements, 0..) |el, i| items[i] = try self.lowerExpr(el);
                    break :blk ast.Expr{ .tuple = items };
                }
                const element_type: ?ir.types.Type = if (literal_type) |known| switch (known) {
                    // A tuple has no single element type, and the tuple
                    // spelling above already returned for every shape a
                    // tuple can reach here with.
                    .tuple => null,
                    .array => |array| array.elem,
                    .slice => |slice| slice.elem,
                    else => |other| other,
                } else null;
                const elem_ast: ?ast.Type = if (element_type) |elem|
                    try self.lowerType(elem)
                else
                    null;
                // The elements are the literal's element type, so a nested
                // literal the frontend left untyped resolves from here.
                const previous_expected_type = self.expected_value_type;
                if (element_type) |elem| self.expected_value_type = elem;
                defer self.expected_value_type = previous_expected_type;
                if (a.repeat) |len| {
                    if (a.elements.len == 0) return error.MissingArrayElement;
                    const elem = try self.allocExpr(try self.lowerExpr(a.elements[0]));
                    break :blk ast.Expr{
                        .repeat = .{
                            .type_name = elem_ast,
                            .elem = elem,
                            .len = len,
                        },
                    };
                }
                // An element that OWNS storage cannot stand in the literal the
                // way an `i32` does: the elements are evaluated left to right,
                // and a `try` in a later one returns before the array value
                // exists, stranding every element already built. Each one is
                // therefore staged into its own binding that owes a release
                // while the literal is still being assembled, exactly as
                // `lowerVecLiteral` stages a `vec![]` element — and then moved
                // into the array with `takeOwned`, which empties the staged
                // handle so the array's own release is the only one left.
                if (element_type) |elem| if (ownedRuntimeContainerType(elem)) {
                    var staged = try self.alloc.alloc(ast.Expr, a.elements.len);
                    var list: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                    defer list.deinit(self.alloc);
                    for (a.elements, 0..) |el, i| {
                        const name = try self.iteratorTemporaryName("__r2z_array_item");
                        const value = try self.lowerExpr(el);
                        try list.append(self.alloc, .{ .let_stmt = .{
                            .name = name,
                            .ty = elem_ast,
                            .init = value,
                            .is_mut = true,
                        } });
                        var release = try self.ownerReleaseStatement(
                            name,
                            ownerReleasesElements(elem),
                        );
                        release.defer_stmt.is_errdefer = true;
                        try list.append(self.alloc, release);
                        staged[i] = try self.ownedTransferPlaceCall(
                            .{ .ident = try self.alloc.dupe(u8, name) },
                            elem,
                        );
                    }
                    const label = try self.iteratorTemporaryName("__r2z_array_value");
                    break :blk ast.Expr{ .block = .{
                        .label = label,
                        .stmts = try list.toOwnedSlice(self.alloc),
                        .expr = try self.allocExpr(.{ .multi_array = .{
                            .type_name = elem_ast,
                            .elements = staged,
                        } }),
                    } };
                };
                var elems = try self.alloc.alloc(ast.Expr, a.elements.len);
                for (a.elements, 0..) |el, i| elems[i] = try self.lowerExpr(el);
                break :blk ast.Expr{
                    .multi_array = .{
                        .type_name = elem_ast,
                        .elements = elems,
                    },
                };
            },
            .vec_lit => |vec| try self.lowerVecLiteral(ir_expr, vec),
            .path => |pe| blk: {
                if (try self.lowerOwnedCaptureTransfer(expr_id, pe)) |transfer| break :blk transfer;
                break :blk try self.lowerPathExpr(pe);
            },
            .block => |be| ast.Expr{ .block = try self.lowerBlock(be) },
            .unit => ast.Expr{ .unit = {} },
            .if_else => |ie| blk: {
                const cond = try self.allocExpr(try self.lowerExpr(ie.cond));
                const then_expr = try self.allocExpr(ast.Expr{ .block = try self.lowerBlock(ie.then_) });
                const else_expr: ?*const ast.Expr = switch (ie.@"else") {
                    .none => null,
                    .block => |eb| try self.allocExpr(ast.Expr{ .block = try self.lowerBlock(eb) }),
                    .chain => |chain_id| try self.allocExpr(try self.lowerExpr(chain_id)),
                };
                break :blk ast.Expr{
                    .if_expr = .{
                        .cond = cond,
                        .then_body = then_expr,
                        .else_body = else_expr,
                    },
                };
            },
            // `if let Some(v) = x` — Zig's `if` takes a `bool`, an optional or
            // an error union, never a pattern, so the subject is bound once
            // and the rest of the shape is decided from there. An OPTIONAL
            // subject is compared with `null` and its payload read back
            // through the same `r2z.option.unwrap` the `match` path uses; a
            // TAGGED UNION subject is switched on its tag, which is what
            // `if let Enum::Variant(..) = e` means. The subject's own type
            // picks the route, because both spellings arrive as the same
            // pattern shape. Each name an optional's pattern introduces
            // arrives as an ordinary `let`, since a pattern may read SEVERAL
            // places out of one payload — `Some((&first_byte, remaining))` —
            // and one capture binds the payload under exactly one name.
            .if_let => |il| blk: {
                const subject_name = try self.iteratorTemporaryName("__r2z_if_let");
                const subject_type = try self.exprType(il.scrutinee) orelse
                    return error.MissingExpressionType;
                const subject_is_option = subject_type == .option or
                    self.canonicalExternalMethodType(subject_type) == .option;
                var is_present = true;
                if (subject_is_option) {
                    is_present = try self.ifLetOptionIsPresent(il.pattern);
                }
                var bindings: std.ArrayListUnmanaged(IfLetBinding) = .empty;
                defer {
                    for (bindings.items) |binding| self.alloc.free(binding.projections);
                    bindings.deinit(self.alloc);
                }
                if (subject_is_option and !is_present) {} else if (try self.ifLetPayloadPattern(il.pattern)) |payload_pat| {
                    try self.collectIfLetBindings(payload_pat, &.{}, &bindings);
                }
                for (bindings.items) |*binding| {
                    binding.emitted_name = if (self.current_local_binding_names) |names|
                        try names.claimPatternName(
                            self.alloc,
                            &self.ir.graph.symbol_table,
                            binding.pat_id,
                            binding.name,
                        )
                    else
                        binding.name;
                }
                const subject_plan = try self.ifLetSubjectPlan(il);
                if (subject_is_option) try self.markRuntimeImport();
                const if_let_route = ifLetRoute(subject_plan);
                const whole_payload = bindings.items.len == 1 and
                    bindings.items[0].projections.len == 0;
                const payload_alias = try self.ifLetOwnedPayloadAlias(il, subject_plan, bindings.items);
                var projected: ?IfLetProjectedClass = null;
                if (!whole_payload) {
                    projected = try self.ifLetProjectedClassify(il, if_let_route, subject_plan);
                }
                const in_place = subject_plan.owner != null;
                const needs_carrier = !in_place;
                const dispatch_name: []const u8 = if (in_place)
                    subject_plan.owner.?
                else
                    subject_name;
                const binds_by_reference = self.ifLetBindsByReference(bindings.items);
                const needs_capture = payload_alias != null or projected != null or
                    binds_by_reference or (if_let_route == .error_union and bindings.items.len != 0);
                const capture_name: []const u8 = if (needs_capture)
                    try self.iteratorTemporaryName("__r2z_if_let_payload")
                else
                    "";
                const payload_take = try self.ifLetPayloadTake(
                    il,
                    subject_plan,
                    dispatch_name,
                    capture_name,
                    bindings.items,
                    payload_alias,
                );

                var prologue: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer prologue.deinit(self.alloc);
                var projected_owner_mark: ?usize = null;
                errdefer if (projected_owner_mark) |mark| self.releaseOwnerScopeFrom(mark);
                if (projected) |drain| {
                    try self.emitIfLetProjectedPrelude(
                        drain,
                        dispatch_name,
                        capture_name,
                        subject_plan,
                        il.then_,
                        &prologue,
                        &projected_owner_mark,
                    );
                }
                var then_block = if (payload_alias) |owned|
                    try self.lowerIfLetBranchOverAlias(owned, il.then_)
                else
                    try self.lowerBlock(il.then_);

                if (projected == null) {
                    if (payload_take) |take| {
                        try prologue.appendSlice(self.alloc, take.stmts);
                    } else if (bindings.items.len != 0 and if_let_route != .tagged) {
                        const payload_name = if (whole_payload)
                            try self.alloc.dupe(u8, bindings.items[0].emitted_name orelse bindings.items[0].name)
                        else
                            try self.iteratorTemporaryName("__r2z_if_let_payload");
                        const payload_init: ast.Expr = switch (if_let_route) {
                            .optional => optional_payload: {
                                const unwrap_args = try self.alloc.alloc(ast.Expr, 1);
                                unwrap_args[0] = .{ .ident = dispatch_name };
                                break :optional_payload .{ .call = .{
                                    .callee = try self.allocExpr(.{ .ident = "r2z.option.unwrap" }),
                                    .args = unwrap_args,
                                } };
                            },
                            .error_union => try self.ifLetPayloadBase(
                                if_let_route,
                                dispatch_name,
                                capture_name,
                                self.ifLetVariantPayloadField(il.pattern),
                            ),
                            .tagged => return error.UnsupportedPattern,
                        };
                        try prologue.append(self.alloc, .{ .let_stmt = .{
                            .name = payload_name,
                            .init = payload_init,
                        } });
                        if (!whole_payload) {
                            for (bindings.items) |binding| {
                                try prologue.append(self.alloc, .{ .let_stmt = .{
                                    .name = try self.alloc.dupe(u8, binding.emitted_name orelse binding.name),
                                    .init = try self.projectionOverSource(
                                        .{ .ident = try self.alloc.dupe(u8, payload_name) },
                                        binding.projections,
                                    ),
                                } });
                            }
                        }
                    }
                }

                if (prologue.items.len != 0) {
                    var merged = try self.alloc.alloc(ast.Stmt, prologue.items.len + then_block.stmts.len);
                    @memcpy(merged[0..prologue.items.len], prologue.items);
                    @memcpy(merged[prologue.items.len..], then_block.stmts);
                    then_block.stmts = merged;
                }
                if (projected_owner_mark) |mark| self.releaseOwnerScopeFrom(mark);
                projected_owner_mark = null;

                const else_expr: ?*const ast.Expr = switch (il.@"else") {
                    .none => null,
                    .block => |eb| try self.allocExpr(.{ .block = try self.lowerBlock(eb) }),
                    .chain => |chain_id| try self.allocExpr(try self.lowerExpr(chain_id)),
                };
                const carrier_release = self.ifLetCarrierReleaseWanted(
                    subject_plan.subject_type,
                    if_let_route,
                    subject_plan.rvalue,
                    payload_alias != null,
                );
                const subject_is_mut = needs_carrier and (needs_capture or carrier_release);
                const statements = try self.alloc.alloc(
                    ast.Stmt,
                    @intFromBool(needs_carrier) + @intFromBool(carrier_release),
                );
                var statement_count: usize = 0;
                if (needs_carrier) {
                    statements[statement_count] = .{ .let_stmt = .{
                        .name = try self.alloc.dupe(u8, subject_name),
                        .init = try self.lowerIfLetSubject(il.scrutinee),
                        .is_mut = subject_is_mut,
                    } };
                    statement_count += 1;
                }
                if (carrier_release) {
                    statements[statement_count] = try self.ownerReleaseStatement(
                        subject_name,
                        ownerReleasesElements(subject_type),
                    );
                    statement_count += 1;
                }
                const decision: ast.Expr = switch (if_let_route) {
                    .optional => .{ .if_expr = .{
                        .cond = try self.allocExpr(if (needs_capture)
                            .{ .ident = try self.alloc.dupe(u8, dispatch_name) }
                        else
                            .{ .bin_op = .{
                                .op = if (is_present) .not_equal else .equal,
                                .lhs = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, dispatch_name) }),
                                .rhs = try self.allocExpr(.{ .lit = .null_lit }),
                            } }),
                        .then_capture = if (needs_capture)
                            .{ .name = capture_name, .by_ref = true }
                        else
                            null,
                        .then_body = try self.allocExpr(.{ .block = then_block }),
                        .else_body = else_expr,
                    } },
                    .error_union => try self.lowerErrorUnionIfLet(
                        dispatch_name,
                        if (needs_capture) capture_name else null,
                        then_block,
                        else_expr,
                        if (self.ifLetVariantPayloadField(il.pattern)) |field| std.mem.eql(u8, field, "Err") else false,
                    ),
                    .tagged => try self.lowerVariantIfLetSwitch(
                        il.pattern,
                        dispatch_name,
                        then_block,
                        else_expr,
                        payload_alias,
                        projected != null or binds_by_reference,
                        if (needs_capture) capture_name else null,
                    ),
                };
                break :blk (try self.allocExpr(.{ .block = .{
                    .stmts = statements[0..statement_count],
                    .expr = try self.allocExpr(decision),
                } })).*;
            },
            .match => |me| blk: {
                const target = try self.allocExpr(try self.lowerExpr(me.scrutinee));
                const option: ?OptionalMatchSubject = if (try self.exprType(me.scrutinee)) |target_type|
                    if (target_type == .option or self.canonicalExternalMethodType(target_type) == .option)
                        .{
                            .name = try self.iteratorTemporaryName("__r2z_option_match"),
                            // An arm that binds the payload by reference has to
                            // borrow the storage the caller's own optional holds,
                            // and the only address of that is the scrutinee's
                            // place. Rust admits such a binding only over a
                            // place, so a scrutinee that has none keeps the copy
                            // and the arm is refused there rather than bound to
                            // storage the source never sees.
                            .by_place = try self.matchCapturesByReference(me.arms) and
                                exprIsAddressable(target.*),
                        }
                    else
                        null
                else
                    null;
                if (me.arms.len == 0) return error.MissingMatchArm;
                // The dispatch tests the subject and an arm reads its payload
                // back, so a scrutinee that is a CALL has to be evaluated
                // once. Lowering it twice advanced an iterator twice:
                // `match self.inner.next() { Some(byte) => .. }` consumed two
                // bytes per arm and encoded every other one.
                //
                // A PLACE is left alone. `values[next_index(counter)]` read
                // through a `|*v|` capture writes into the slice, and a
                // binding in front of it turned the capture's pointer into
                // one to a copy — the write landed there and the caller's
                // element never changed.
                var subject: *const ast.Expr = target;
                var subject_name: ?[]const u8 = null;
                if (option == null and target.* == .call) {
                    subject_name = try self.iteratorTemporaryName("__r2z_match_subject");
                    subject = try self.allocExpr(.{ .ident = subject_name.? });
                }
                // A guard has no place in a Zig prong, and neither has a
                // pattern that names a variant INSIDE its payload: both need
                // the ordered chain, which is the shape that can test the
                // nested tag and fall through to the arms after it.
                const lowered_match: ast.Expr = if (matchHasGuard(me.arms) or
                    (option == null and try self.matchNeedsNestedPayloadChain(me.arms)))
                    try self.lowerGuardedMatch(subject, option, me.arms)
                else
                    .{ .match_expr = .{
                        .target = try self.matchSubject(option, subject),
                        .arms = try self.lowerMatchArms(option, me.arms),
                    } };
                if (option) |option_subject| {
                    const statements = try self.alloc.alloc(ast.Stmt, 1);
                    statements[0] = .{ .let_stmt = .{
                        .name = option_subject.name,
                        .init = if (option_subject.by_place)
                            .{ .unary_op = .{
                                .op = .addr_of,
                                .operand = try self.allocExpr(target.*),
                            } }
                        else
                            target.*,
                    } };
                    break :blk .{ .block = .{
                        .stmts = statements,
                        .expr = try self.allocExpr(lowered_match),
                    } };
                }
                if (subject_name) |name| {
                    // An arm that binds the subject by reference writes
                    // THROUGH the place the dispatch reads, so the binding
                    // has to carry that mutability: a `const` copy turned the
                    // capture's pointer into `*const T` and the arm's write
                    // into `cannot assign to constant`.
                    const statements = try self.alloc.alloc(ast.Stmt, 1);
                    statements[0] = .{ .let_stmt = .{
                        .name = name,
                        .init = target.*,
                        .is_mut = try self.matchCapturesByReference(me.arms),
                    } };
                    break :blk .{ .block = .{
                        .stmts = statements,
                        .expr = try self.allocExpr(lowered_match),
                    } };
                }
                break :blk lowered_match;
            },
            .loop_ => |le| blk: {
                const cond = try self.allocExpr(ast.Expr{ .lit = .{ .bool_lit = true } });
                var body = try self.lowerBlock(le.body);
                const label = takeLoopLabel(le.body.labelled, &body);
                try takeLoopTailAsStatement(self.alloc, &body);
                break :blk ast.Expr{
                    .while_expr = .{
                        .cond = cond,
                        .body = body,
                        .label = label,
                    },
                };
            },
            .while_ => |we| blk: {
                const cond = try self.allocExpr(try self.lowerExpr(we.cond));
                const captures = if (we.capture) |cap_id|
                    try self.lowerWhileCapture(cap_id)
                else
                    null;
                const previous_shadow_scope = self.current_shadow_scope;
                var capture_shadow_scope: ShadowScope = .{
                    .names = captures orelse &.{},
                    .parent = previous_shadow_scope,
                };
                self.current_shadow_scope = &capture_shadow_scope;
                defer self.current_shadow_scope = previous_shadow_scope;
                var body = try self.lowerBlock(we.body);
                const label = takeLoopLabel(we.body.labelled, &body);
                try takeLoopTailAsStatement(self.alloc, &body);
                break :blk ast.Expr{
                    .while_expr = .{
                        .cond = cond,
                        .captures = captures,
                        .body = body,
                        .label = label,
                    },
                };
            },
            .for_ => |fe| blk: {
                var inputs: std.ArrayListUnmanaged(ast.Expr) = .empty;
                defer inputs.deinit(self.alloc);
                var captures_list: std.ArrayListUnmanaged(ast.Capture) = .empty;
                defer captures_list.deinit(self.alloc);
                var destructure: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer destructure.deinit(self.alloc);
                var loop_claims: ClaimCollector = .empty;
                defer loop_claims.deinit(self.alloc);
                var iterator_hoist: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer iterator_hoist.deinit(self.alloc);
                var iterator_items: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer iterator_items.deinit(self.alloc);
                var iterator_scope_names: std.ArrayListUnmanaged([]const u8) = .empty;
                defer iterator_scope_names.deinit(self.alloc);
                var runtime_inputs: std.ArrayListUnmanaged(RuntimeIteratorInput) = .empty;
                defer runtime_inputs.deinit(self.alloc);
                var value_capture_name: ?[]const u8 = null;
                var typed_range: ?TypedRangeFor = null;
                if (fe.pattern >= self.ir.bodies.pats.len) return error.MissingPatternNode;

                switch (fe.iter_kind) {
                    .slice => slice_input: {
                        value_capture_name = try self.valueCaptureName(fe.pattern);
                        if (try self.isRuntimeIteratorInput(fe.iterable)) {
                            // A runtime iterator is a struct, not something a
                            // Zig `for` can walk; with no sibling input it
                            // drives the loop as a `while` over its `next`.
                            try runtime_inputs.append(self.alloc, try self.appendRuntimeIteratorInput(
                                fe.iterable,
                                fe.pattern,
                                0,
                                try self.iteratorTemporaryName("__r2z_item"),
                                &iterator_hoist,
                                &iterator_items,
                                &iterator_scope_names,
                                &loop_claims,
                            ));
                            break :slice_input;
                        }
                        // A range with a matched pair of integer endpoints is
                        // driven by the typed iterator loop: a Zig `for` binds
                        // `usize` for every range, which cannot carry a
                        // signed or a narrow counter.
                        typed_range = try self.planTypedRangeFor(fe);
                        if (typed_range != null) break :slice_input;
                        const by_ref = try self.patternCapturesByReference(fe.pattern) or try self.iteratorSourceByReference(fe.iterable);
                        const drain = try self.forInputDrain(fe.iterable, fe.pattern, by_ref);
                        const iterable = try self.lowerDrainedLoopInput(fe.iterable, fe.pattern, drain, by_ref, &iterator_hoist);
                        const iterable_ty = try self.exprType(fe.iterable);
                        const exact_type = if (iterable_ty) |value|
                            isChunksExactType(value)
                        else
                            false;
                        const direct_exact = switch (self.ir.bodies.exprs[fe.iterable].kind) {
                            .method_call => exact_type,
                            else => false,
                        };
                        const user_iterator = if (iterable_ty) |value|
                            isUserIteratorType(self, value)
                        else
                            false;
                        if (user_iterator) {
                            // A user-defined `Iterator` has no Zig `for`
                            // shape; it is driven through `next()`.
                            const iterator_args = try self.alloc.alloc(ast.Expr, 1);
                            iterator_args[0] = iterable;
                            try inputs.append(self.alloc, .{ .builtin = .{
                                .name = "iteratorValue",
                                .args = iterator_args,
                            } });
                        } else if (exact_type and !direct_exact) {
                            const iterator_args = try self.alloc.alloc(ast.Expr, 1);
                            iterator_args[0] = iterable;
                            try inputs.append(self.alloc, .{ .builtin = .{
                                .name = "sliceChunksExactIterator",
                                .args = iterator_args,
                            } });
                        } else {
                            try inputs.append(self.alloc, iterable);
                        }
                        try self.appendLoopCapture(fe.pattern, try self.forInputElementType(fe.iterable), drain, by_ref, &captures_list, &destructure, &loop_claims);
                        try self.retypeRangeLoopBinding(fe, &captures_list, &destructure);
                    },

                    .range => {
                        // `0..end`; a Rust start that isn't 0 (or `..=` inclusive)
                        // was handled in the frontend (`..=` lowers to `end+1`).
                        const start = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
                        const end = try self.allocExpr(try self.lowerExpr(fe.iterable));
                        try inputs.append(self.alloc, ast.Expr{ .range = .{ .start = start, .end = end } });
                        try self.appendLoopCapture(fe.pattern, .{ .prim = .usize }, .untouched, false, &captures_list, &destructure, &loop_claims);
                    },
                    .enumerate => {
                        // Rust `for (idx, elem) in xs.enumerate()` →
                        // Zig `for (xs, 0..) |elem, idx|`.
                        const pat = self.ir.bodies.pats[fe.pattern];
                        const tuple = switch (pat.kind) {
                            .tuple => |tp| tp,
                            else => return error.InvalidLoopCapture,
                        };
                        if (tuple.elements.len != 2) return error.LoopCaptureArityMismatch;
                        const by_ref = try self.patternCapturesByReference(tuple.elements[1]) or try self.iteratorSourceByReference(fe.iterable);
                        const drain = try self.forInputDrain(fe.iterable, tuple.elements[1], by_ref);
                        const slice = try self.lowerDrainedLoopInput(fe.iterable, tuple.elements[1], drain, by_ref, &iterator_hoist);
                        const zstart = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
                        const open = try self.allocExpr(ast.Expr{ .range = .{ .start = zstart, .end = null } });
                        try inputs.append(self.alloc, slice);
                        try inputs.append(self.alloc, open.*);
                        value_capture_name = try self.valueCaptureName(tuple.elements[1]);
                        try self.appendLoopCapture(tuple.elements[1], try self.forInputElementType(fe.iterable), drain, by_ref, &captures_list, &destructure, &loop_claims);
                        try self.appendLoopCapture(tuple.elements[0], .{ .prim = .usize }, .untouched, false, &captures_list, &destructure, &loop_claims);
                    },
                    .multi => |ids| {
                        if (ids.len == 0) return error.MissingLoopInput;
                        const pat = self.ir.bodies.pats[fe.pattern];
                        const tuple = switch (pat.kind) {
                            .tuple => |tp| tp,
                            else => return error.InvalidLoopCapture,
                        };
                        if (tuple.elements.len != ids.len) return error.LoopCaptureArityMismatch;
                        // A runtime iterator cannot sit in a Zig `for` header, so
                        // plain inputs keep the loop — preserving their
                        // by-reference captures — and each iterator is hoisted
                        // and pulled with `next`. Without a plain input there
                        // is nothing to drive the loop, so the first iterator
                        // drives a `while` over its own `next` instead.
                        var has_plain_input = false;
                        for (ids) |mid| {
                            if (!try self.isRuntimeIteratorInput(mid)) {
                                has_plain_input = true;
                                break;
                            }
                        }
                        for (ids, 0..) |mid, mi| {
                            const element = tuple.elements[mi];
                            if (try self.isRuntimeIteratorInput(mid)) {
                                const driver: ?[]const u8 = if (has_plain_input or runtime_inputs.items.len != 0)
                                    null
                                else
                                    try self.iteratorTemporaryName("__r2z_item");
                                try runtime_inputs.append(self.alloc, try self.appendRuntimeIteratorInput(
                                    mid,
                                    element,
                                    mi,
                                    driver,
                                    &iterator_hoist,
                                    &iterator_items,
                                    &iterator_scope_names,
                                    &loop_claims,
                                ));
                                continue;
                            }
                            // Rust `x.iter()` yields references. The pattern
                            // may not carry a type to say so, so the source
                            // itself decides, as it does for a chain.
                            const by_ref = try self.patternCapturesByReference(element) or try self.iteratorSourceByReference(mid);
                            const drain = try self.forInputDrain(mid, element, by_ref);
                            try inputs.append(self.alloc, try self.lowerDrainedLoopInput(mid, element, drain, by_ref, &iterator_hoist));
                            try self.appendLoopCapture(element, try self.forInputElementType(mid), drain, by_ref, &captures_list, &destructure, &loop_claims);
                        }
                    },
                    .adapter => |chain| break :blk try self.lowerIteratorAdapterForBlock(
                        chain,
                        fe.pattern,
                        fe.body,
                    ),
                }

                const previous_capture_names = self.current_capture_names;
                var capture_names: ?[][]const u8 = null;
                // A runtime iterator binds its item with a `const` rather than
                // a `for` capture, so those names reach a nested closure
                // through the same scope list.
                const scope_count = captures_list.items.len + iterator_scope_names.items.len;
                if (scope_count > 0) {
                    const names = try self.alloc.alloc(
                        []const u8,
                        previous_capture_names.len + scope_count,
                    );
                    @memcpy(names[0..previous_capture_names.len], previous_capture_names);
                    for (captures_list.items, previous_capture_names.len..) |capture, index| names[index] = capture.name;
                    for (iterator_scope_names.items, previous_capture_names.len + captures_list.items.len..) |name, index| names[index] = name;
                    capture_names = names;
                    self.current_capture_names = names;
                }
                defer if (capture_names) |names| self.alloc.free(names);
                defer self.current_capture_names = previous_capture_names;

                const previous_value_capture_scopes = self.current_value_capture_scopes;
                const value_capture_scopes = try self.alloc.alloc(
                    ValueCaptureScope,
                    previous_value_capture_scopes.len + 1,
                );
                defer self.alloc.free(value_capture_scopes);

                @memcpy(
                    value_capture_scopes[0..previous_value_capture_scopes.len],
                    previous_value_capture_scopes,
                );
                value_capture_scopes[previous_value_capture_scopes.len] = .{
                    .names = if (capture_names) |names| names[previous_capture_names.len..] else &.{},
                    .value_name = value_capture_name,
                };
                self.current_value_capture_scopes = value_capture_scopes;
                defer self.current_value_capture_scopes = previous_value_capture_scopes;

                const loop_owner_mark = self.owned_scope_bindings.items.len;
                defer self.releaseOwnerScopeFrom(loop_owner_mark);
                try self.installDestructureOwnerMoves(loop_claims.items, fe.body, 0);
                var body = try self.lowerBlock(fe.body);
                const label = takeLoopLabel(fe.body.labelled, &body);
                try takeLoopTailAsStatement(self.alloc, &body);

                const prologue = destructure.items.len + iterator_items.items.len;
                if (prologue > 0) {
                    const merged = try self.alloc.alloc(ast.Stmt, prologue + body.stmts.len);
                    @memcpy(merged[0..iterator_items.items.len], iterator_items.items);
                    @memcpy(merged[iterator_items.items.len..][0..destructure.items.len], destructure.items);
                    @memcpy(merged[prologue..], body.stmts);
                    body.stmts = merged;
                }

                if (typed_range) |plan| {
                    break :blk try self.lowerTypedRangeFor(plan, body, label);
                }

                const for_inputs = try inputs.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(for_inputs);
                const captures = try captures_list.toOwnedSlice(self.alloc);
                errdefer self.alloc.free(captures);

                const loop = if (runtime_inputs.items.len == 0)
                    ast.Expr{ .for_expr = .{
                        .inputs = for_inputs,
                        .captures = captures,
                        .body = body,
                        .label = label,
                    } }
                else
                    try self.lowerRuntimeIteratorFor(
                        runtime_inputs.items,
                        for_inputs,
                        captures,
                        body,
                        label,
                    );
                if (iterator_hoist.items.len == 0) break :blk loop;
                const stmts = try self.alloc.alloc(ast.Stmt, iterator_hoist.items.len + 1);
                @memcpy(stmts[0..iterator_hoist.items.len], iterator_hoist.items);
                stmts[iterator_hoist.items.len] = .{ .expr_stmt = try self.allocExpr(loop) };
                break :blk ast.Expr{ .block = .{ .stmts = stmts } };
            },
            .break_ => |be| blk: {
                break :blk ast.Expr{ .break_expr = .{
                    .value = if (be.value) |v| try self.allocExpr(try self.lowerExpr(v)) else null,
                    .label = be.label,
                } };
            },
            // Zig's `continue` restarts the innermost loop, so a label naming
            // an outer one has to survive into the AST: dropping it would send
            // the restart to the wrong loop and answer a different question
            // with no diagnostic.
            .continue_ => |continue_expr| blk: {
                break :blk ast.Expr{ .continue_expr = .{ .label = continue_expr.label } };
            },
            .core_call => |call| try self.lowerCoreCall(expr_id, call),
            .core_function => |function| try self.lowerCoreFunction(function),
            .external_variant => |variant| try self.lowerExternalVariant(expr_id, variant),
            .call => |c| blk: {
                const callee_def: ir.spine.EntityId = switch (c.call_kind) {
                    .free => |def_id| def_id,
                    .associated => |def_id| def_id,
                    .constructor => |def_id| def_id,
                };
                const callee_entity = self.ir.graph.symbol_table.get(callee_def) orelse {
                    return error.MissingDefinition;
                };
                const callee_name = callee_entity.renamed_to orelse callee_entity.name;
                if (callee_name.len == 0) return error.MissingDefinitionName;
                if (c.call_kind == .free) {
                    const emitted_name = try self.lowerResolvedEntityName(callee_def);
                    defer self.alloc.free(emitted_name);
                    if (self.local_closures.get(emitted_name)) |closure| {
                        if (c.args.len != 1) return error.UnsupportedExpression;
                        break :blk try self.lowerLocalClosureCall(closure, emitted_name, c.args[0]);
                    }
                }

                // `io::Cursor::new(source)` is the one standard-library
                // constructor the runtime rewrites rather than names. Rust
                // takes the source BY VALUE, so the argument's own type is
                // the cursor's parameter, and the runtime cursor is built
                // from that source and a read position that starts at zero —
                // nothing is allocated and nothing is copied.
                if (c.call_kind == .associated and self.isIoCursorNew(callee_def)) {
                    if (c.args.len != 1) return error.GenericArgumentArityMismatch;
                    try self.markRuntimeImport();
                    const source_type = try self.exprType(c.args[0]) orelse
                        return error.MissingExpressionType;
                    const params = try self.alloc.alloc(ast.Type, 1);
                    params[0] = try self.lowerType(source_type);
                    // The generic argument belongs to the TYPE, not to the
                    // call: `r2z.io.Cursor(T).init(source)` is how a runtime
                    // cursor is built, and `init` is a declaration inside the
                    // type the parameter list instantiates.
                    const cursor_type = try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = "r2z.io.Cursor" }),
                        .generic_args = params,
                        .args = &.{},
                    } });
                    const call_args = try self.alloc.alloc(ast.Expr, 1);
                    call_args[0] = try self.lowerExpr(c.args[0]);
                    break :blk (try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = cursor_type,
                            .field_name = "init",
                        } }),
                        .args = call_args,
                    } })).*;
                }

                // `io::BufReader::new(source)` is the buffered counterpart of
                // the cursor constructor and rewrites the same way: Rust takes
                // the wrapped reader BY VALUE, so that argument's own type is
                // the buffer's parameter, and the runtime pair is built from
                // it beside a fixed-size buffer. The buffer belongs to the
                // value being built, so the constructor allocates nothing and
                // copies nothing out of the source.
                if (c.call_kind == .associated and self.isIoBufReaderNew(callee_def)) {
                    if (c.args.len != 1) return error.GenericArgumentArityMismatch;
                    try self.markRuntimeImport();
                    const source_type = try self.exprType(c.args[0]) orelse
                        return error.MissingExpressionType;
                    const params = try self.alloc.alloc(ast.Type, 1);
                    params[0] = try self.lowerType(source_type);
                    // The generic argument belongs to the TYPE, exactly as for
                    // the cursor: `r2z.io.BufReader(T).init(source)` names a
                    // declaration inside the type the parameter list
                    // instantiates, not a call that carries it.
                    const buffered_type = try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = "r2z.io.BufReader" }),
                        .generic_args = params,
                        .args = &.{},
                    } });
                    const call_args = try self.alloc.alloc(ast.Expr, 1);
                    call_args[0] = try self.lowerExpr(c.args[0]);
                    break :blk (try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .field_access = .{
                            .target = buffered_type,
                            .field_name = "init",
                        } }),
                        .args = call_args,
                    } })).*;
                }

                const allocates =
                    c.call_kind != .constructor and self.callPassesAllocator(callee_def);
                const fallible = c.call_kind != .constructor and self.callableFallible(callee_def);

                // Trait-associated calls like `Clone::clone(&x)` / `AsRef::as_ref(&x)`
                // lower to the receiver/copy/slice expression directly.
                if (c.call_kind == .associated and callee_entity.kind == .method_ref) {
                    if (c.args.len >= 1) {
                        const recv_ast = try self.lowerExpr(c.args[0]);
                        const recv_ptr = try self.allocExpr(recv_ast);
                        // An associated call carries no turbofish of its own, so
                        // a method that needs one (`collect`) refuses here
                        // rather than guessing an element type.
                        if (try self.lowerStdMethodCall(callee_name, c.args[0], recv_ptr, &.{}, &.{}, &.{})) |lowered| {
                            break :blk try self.lowerDirectCallResult(
                                expr_id,
                                lowered.*,
                                allocates,
                                false,
                            );
                        }
                    }
                }

                var owned_prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer owned_prelude.deinit(self.alloc);
                var owned_reserved: std.ArrayListUnmanaged([]const u8) = .empty;
                defer owned_reserved.deinit(self.alloc);
                if (self.current_owner_reserved) |reserved| {
                    try owned_reserved.appendSlice(self.alloc, reserved.items);
                }
                const previous_owner_prelude = self.current_owner_prelude;
                const previous_owner_reserved = self.current_owner_reserved;
                self.current_owner_prelude = &owned_prelude;
                self.current_owner_reserved = &owned_reserved;
                defer {
                    self.current_owner_prelude = previous_owner_prelude;
                    self.current_owner_reserved = previous_owner_reserved;
                }

                // The allocator leads the value-argument list, and the
                // declaration agrees: `lowerFnEntity` puts it ahead of every
                // value parameter — a hoisted method's `self` included —
                // while a method inside its own struct declares `self`
                // implicitly, so `self` is never one of these arguments
                // either. An associated call such as `FromHex::from_hex(hex)`
                // therefore passes it FIRST: `from_hex(T, allocator, hex)`.
                // Emitting it after the first argument produced
                // `from_hex(T, hex, allocator)`, which binds `hex` to the
                // allocator parameter and Zig rejects the type.
                var args = try self.alloc.alloc(
                    ast.Expr,
                    c.args.len + if (allocates) @as(usize, 1) else 0,
                );
                if (allocates) args[0] = .{ .ident = "allocator" };
                for (c.args, 0..) |arg_id, i| {
                    const previous_expected_type = self.expected_argument_type;
                    const previous_expected_expr_id = self.expected_argument_expr_id;
                    self.expected_argument_type = self.directFreeCallArgumentType(c.call_kind, i);
                    self.expected_argument_expr_id = if (self.expected_argument_type != null)
                        arg_id
                    else
                        null;
                    const destination_index = i + if (allocates) @as(usize, 1) else 0;
                    args[destination_index] = lowered_arg: {
                        defer {
                            self.expected_argument_type = previous_expected_type;
                            self.expected_argument_expr_id = previous_expected_expr_id;
                        }
                        const lowered_arg_value = try self.lowerExpr(arg_id);
                        // A fat borrow lowers to the value itself, and a
                        // `&mut T` parameter of a translated generic lowers to
                        // the Zig pointer `*T`. The address is what bridges the
                        // two, and only this argument needs it: one that is
                        // already a pointer is the pointer the parameter wrote.
                        break :lowered_arg if (try self.argumentTakesGenericBorrowAddress(
                            c,
                            i,
                            arg_id,
                        ))
                            (try self.allocExpr(.{
                                .unary_op = .{
                                    .op = .addr_of,
                                    .operand = try self.allocExpr(lowered_arg_value),
                                },
                            })).*
                        else
                            lowered_arg_value;
                    };
                }
                const lowered_call = if (try self.lowerSourceAssociatedTraitCall(expr_id, c, args)) |source_call|
                    source_call
                else normal_call: {
                    const callee_expr = callee: {
                        if (c.call_kind == .associated) {
                            if (try self.qualifyTraitImplMethod(callee_def)) |trait_method| {
                                break :callee trait_method;
                            }
                        }
                        const resolved_callee = try self.lowerResolvedEntity(callee_def);
                        break :callee try self.qualifyInherentMethod(callee_def, resolved_callee);
                    };
                    const generic_args = try self.lowerCallGenericArgs(expr_id, callee_def, c.args, &.{});
                    if (c.call_kind == .constructor)
                        break :normal_call try self.lowerTupleStructConstructor(callee_def, generic_args, args);
                    const call_expr = ast.Expr{ .call = .{
                        .callee = try self.allocExpr(callee_expr),
                        .generic_args = generic_args,
                        .args = args,
                    } };
                    break :normal_call try self.lowerDirectCallResult(expr_id, call_expr, allocates, fallible);
                };
                if (owned_prelude.items.len == 0) break :blk lowered_call;
                const owned_stmts = try owned_prelude.toOwnedSlice(self.alloc);
                try self.recordOwnerPrelude(owned_stmts);
                break :blk .{ .block = .{
                    .stmts = owned_stmts,
                    .expr = try self.allocExpr(lowered_call),
                } };
            },
            .method_call => |mc| blk: {
                const called_method = self.ir.graph.symbol_table.get(mc.method) orelse return error.MissingDefinition;
                if (std.mem.eql(u8, called_method.name, "contains") and
                    mc.receiver < self.ir.bodies.exprs.len and self.ir.bodies.exprs[mc.receiver].kind == .range)
                {
                    if (mc.args.len != 1) return error.UnsupportedStandardMethod;
                    const range = self.ir.bodies.exprs[mc.receiver].kind.range;
                    const end = range.end orelse return error.UnsupportedExpression;
                    const call_args = try self.alloc.alloc(ast.Expr, 4);
                    call_args[0] = try self.lowerExpr(range.start);
                    call_args[1] = try self.lowerExpr(end);
                    call_args[2] = (try self.lowerMemoryReceiver(mc.args[0], try self.allocExpr(try self.lowerExpr(mc.args[0])))).*;
                    call_args[3] = .{ .lit = .{ .bool_lit = range.inclusive } };
                    try self.markRuntimeImport();
                    break :blk .{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = "r2z.rangeContains" }),
                        .args = call_args,
                    } };
                }
                const method_entity = self.ir.graph.symbol_table.get(mc.method) orelse {
                    return error.MissingDefinition;
                };
                try self.validateMethodTopology(method_entity);
                const method_name = self.hoisted_method_names.get(mc.method) orelse
                    (method_entity.renamed_to orelse method_entity.name);
                // A blanket impl types its receiver from the impl's declared
                // bound plus the receiver's own length, and the frontend
                // leaves such a receiver untyped. Handing that answer to the
                // receiver's own lowering is what lets
                // `[0x66, ..].encode_hex::<String>()` emit a typed array
                // literal rather than the identity-less one the AST rejects.
                const previous_receiver_type = self.expected_value_type;
                defer self.expected_value_type = previous_receiver_type;
                const blanket_target = try self.blanketCallTarget(mc.method, method_name, mc.receiver);
                if (blanket_target) |target| {
                    self.expected_value_type = target.self_type;
                }
                const lowered_receiver = try self.allocExpr(try self.lowerExpr(mc.receiver));
                if (try self.lowerBoundConversion(expr_id, method_entity, lowered_receiver, mc.receiver)) |conversion| {
                    if (mc.args.len != 0) return error.UnsupportedStandardMethod;
                    break :blk conversion;
                }
                // A trait method reference carries no allocation effect of its
                // own — the effect belongs to the impl's `fn` — so the call
                // has to be resolved before its result can be known to be
                // fallible. Unresolved, the hoisted `encode_hex(..) ->
                // !r2z.alloc.String` reached the `==` in `test_to_hex` as a
                // bare error union and Zig rejected the whole comparison.
                const allocates = self.callPassesAllocator(mc.method) or
                    (if (blanket_target) |target|
                        self.callPassesAllocator(target.method_fn_id)
                    else
                        false) or try self.stdMethodTakesAllocatorArg(mc.receiver, method_name);
                const fallible = self.callableFallible(mc.method) or
                    (if (blanket_target) |target|
                        self.callableFallible(target.method_fn_id)
                    else
                        false);

                var owned_prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
                defer owned_prelude.deinit(self.alloc);
                var owned_reserved: std.ArrayListUnmanaged([]const u8) = .empty;
                defer owned_reserved.deinit(self.alloc);
                if (self.current_owner_reserved) |reserved| {
                    try owned_reserved.appendSlice(self.alloc, reserved.items);
                }
                const previous_owner_prelude = self.current_owner_prelude;
                const previous_owner_reserved = self.current_owner_reserved;
                self.current_owner_prelude = &owned_prelude;
                self.current_owner_reserved = &owned_reserved;
                defer {
                    self.current_owner_prelude = previous_owner_prelude;
                    self.current_owner_reserved = previous_owner_reserved;
                }

                // A `String` receiver that needs mutable storage binds ahead
                // of this: the source evaluates the receiver first, and the
                // argument loop below is what fills the rest of the prelude.
                const receiver_prelude_at = owned_prelude.items.len;

                // An inline closure argument cannot be lowered on its own, so
                // the closure-taking combinators are expanded whole before the
                // argument loop reaches the bare `.closure` node. Arguments
                // that are not closures keep the runtime-call path below.
                if (method_entity.kind == .method_ref and mc.args.len == 1) {
                    if (try self.lookupRecognizedStdMethod(mc.receiver, method_name)) |recognized| {
                        switch (recognized) {
                            .option_map, .option_and_then, .result_map, .result_map_err, .iterator_any => {
                                if (self.inlineClosureArgument(mc.args[0])) |closure| {
                                    break :blk try self.lowerDirectCallResult(
                                        expr_id,
                                        try self.lowerInlineClosureCombinator(
                                            recognized,
                                            mc.receiver,
                                            lowered_receiver,
                                            closure,
                                        ),
                                        allocates,
                                        false,
                                    );
                                }
                                // The expansion is the only shape there is:
                                // the predicate has to be spelled out at the
                                // call site, so a named `fn` reaching here
                                // cannot become an `r2z` iterator call.
                                if (recognized == .iterator_any) {
                                    return error.UnsupportedStandardMethod;
                                }
                            },
                            else => {},
                        }
                    }
                }

                var args = try self.alloc.alloc(ast.Expr, mc.args.len);
                for (mc.args, 0..) |arg_id, i| {
                    const previous_expected_type = self.expected_argument_type;
                    const previous_expected_expr_id = self.expected_argument_expr_id;
                    self.expected_argument_type = self.methodCallArgumentType(mc.method, i);
                    self.expected_argument_expr_id = if (self.expected_argument_type != null)
                        arg_id
                    else
                        null;
                    defer {
                        self.expected_argument_type = previous_expected_type;
                        self.expected_argument_expr_id = previous_expected_expr_id;
                    }
                    args[i] = try self.lowerExpr(arg_id);
                }
                const source_dispatch = try self.lowerGenericSourceMethodCall(expr_id, mc, lowered_receiver, args, null);
                const standard_call = if (source_dispatch != null)
                    null
                else if (method_entity.kind == .method_ref or
                    try self.dynTraitMethodReceiver(mc.receiver)) try self.lowerStdMethodCall(
                    method_name,
                    mc.receiver,
                    lowered_receiver,
                    args,
                    mc.args,
                    mc.generic_args,
                ) else null;
                // Which declaration the resolver attached decides nothing
                // here: the blanket branch is chosen by RESOLUTION, not by the
                // entity's kind. `blanketCallTarget` answers only for a
                // blanket impl's own method, whether the call reached the
                // trait's `method_ref` or the impl's `fn` — and which of the
                // two a given call carries is the resolver's business, not
                // this branch's. Gating on `.method_ref` refused the
                // `fn`-bound half, and `fn encode<T: AsRef<[u8]>>(data: T)`
                // reaching its method through the pre-existing name lookup
                // emitted `data.encode_hex(..)` as a Zig member call, which no
                // `[]const u8` has a field for.
                const blanket_call = if (source_dispatch != null) null else try self.lowerBlanketImplMethodCall(
                    expr_id,
                    mc,
                    method_name,
                    lowered_receiver.*,
                    args,
                    &owned_prelude,
                );
                // The standard runtime branch owns its own allocator threading
                // AND its own fallibility: every arm in `lowerStdMethodCall`
                // that allocates already raised `current_callable_is_allocating`
                // so the enclosing callable declares the allocator, and every
                // arm that can fail already wrapped its result in `try`.
                // Wrapping it again here — which the user-call path below
                // needs, because a user function's own body is what decides
                // whether it can fail — put a second `try` around a call that
                // had one, and around helpers that return a plain value.
                const lowered_call = if (source_dispatch) |lowered|
                    lowered
                else if (standard_call) |lowered|
                    lowered.*
                else if (blanket_call) |lowered|
                    try self.lowerDirectCallResult(expr_id, lowered, allocates, fallible)
                else blk_call: {
                    // `rev`/`count` and their siblings have no Zig member on
                    // a range or an `r2z` iterator, so the fall-through below
                    // emitted `range.count()` and Zig rejected the call with
                    // "no field or member function named 'count'". A user
                    // type's own method of the same name still goes through,
                    // so the refusal is scoped to these two receivers.
                    if (method_entity.kind == .method_ref and
                        isMissingIteratorMethod(method_name) and
                        try self.isRangeOrRuntimeIteratorReceiver(mc.receiver))
                    {
                        return error.UnsupportedStandardMethod;
                    }
                    const call_receiver = try self.bindRuntimeStringReceiver(
                        &owned_prelude,
                        receiver_prelude_at,
                        lowered_receiver,
                        mc.receiver,
                        method_name,
                    );
                    const generic_args = try self.lowerCallGenericArgs(expr_id, mc.method, mc.args, mc.generic_args);
                    // An impl whose self type is not this crate's own has no
                    // struct to hold the method, so the declaration was hoisted
                    // to module scope under a name of its own and takes the
                    // converted value as its first parameter. A member call
                    // would ask the RECEIVER's type for something its own
                    // impls never wrote; this asks the function the source
                    // actually declared.
                    const hoisted = moduleHoistedImplMethod(self, mc.method);
                    const callee = if (hoisted) |method_id|
                        try self.allocExpr(try self.lowerResolvedEntity(method_id))
                    else
                        try self.allocExpr(ast.Expr{
                            .field_access = .{
                                .target = call_receiver,
                                .field_name = try self.alloc.dupe(u8, method_name),
                            },
                        });
                    const call_args = if (hoisted) |method_id|
                        try self.hoistedSelfArguments(method_id, call_receiver, args, allocates)
                    else if (allocates) alloc_args: {
                        const result = try self.alloc.alloc(ast.Expr, args.len + 1);
                        result[0] = .{ .ident = "allocator" };
                        @memcpy(result[1..], args);
                        break :alloc_args result;
                    } else args;
                    const call_expr = ast.Expr{ .call = .{
                        .callee = callee,
                        .generic_args = generic_args,
                        .args = call_args,
                    } };
                    break :blk_call try self.lowerDirectCallResult(expr_id, call_expr, allocates, fallible);
                };
                if (owned_prelude.items.len == 0) break :blk lowered_call;
                const owned_stmts = try owned_prelude.toOwnedSlice(self.alloc);
                try self.recordOwnerPrelude(owned_stmts);
                break :blk .{ .block = .{
                    .stmts = owned_stmts,
                    .expr = try self.allocExpr(lowered_call),
                } };
            },
            .struct_lit => |sl| blk: {
                if (sl.base != null) return error.UnsupportedStructUpdate;
                const struct_entity = self.ir.graph.symbol_table.get(sl.def) orelse {
                    return error.MissingDefinition;
                };
                if (struct_entity.kind != .struct_) return error.InvalidStructDefinition;
                if (sl.def >= self.ir.bodies.bodies.len) return error.MissingBodyId;
                const struct_body = switch (self.ir.bodies.bodies[sl.def]) {
                    .struct_ => |body| body,
                    else => return error.DeclarationBodyMismatch,
                };
                var fields = try self.alloc.alloc(ast.StructInitField, sl.fields.len);
                for (sl.fields, 0..) |fi, i| {
                    var found = false;
                    for (struct_body.fields) |declared| {
                        if (std.mem.eql(u8, declared.name, fi.field)) {
                            found = true;
                            break;
                        }
                    }
                    if (!found) return error.MissingStructField;
                    const name = try self.alloc.dupe(
                        u8,
                        self.structFieldName(sl.def, fi.field),
                    );
                    errdefer self.alloc.free(name);
                    const expr = try self.lowerExpr(fi.value);

                    fields[i] = .{
                        .name = name,
                        .expr = expr,
                    };
                }

                const inferred_generic_args =
                    self.genericArgsFromExprType(expr_id, sl.def) orelse
                    try self.inferredStructLitArgs(sl.def, sl.fields);
                const lowered_generic_args = try self.lowerGenericArgs(
                    sl.def,
                    inferred_generic_args,
                );
                const struct_name = try self.lowerResolvedEntityName(sl.def);
                const type_name = if (lowered_generic_args.len > 0)
                    ast.Type{ .generic = .{
                        .name = struct_name,
                        .params = lowered_generic_args,
                    } }
                else
                    ast.Type{ .named = struct_name };

                break :blk ast.Expr{
                    .struct_init = .{
                        .type_name = type_name,
                        .fields = fields,
                    },
                };
            },
            .format_write => |format| blk: {
                try self.markRuntimeImport();
                const call_args = try self.alloc.alloc(ast.Expr, 3);
                call_args[0] = try self.lowerExpr(format.writer);
                call_args[1] = .{ .lit = .{
                    .str = try self.alloc.dupe(u8, format.template),
                } };

                var format_args = try self.alloc.alloc(ast.Expr, format.args.len);
                for (format.args, 0..) |arg_id, i| {
                    format_args[i] = try self.lowerFormatArgument(arg_id);
                }
                call_args[2] = .{ .tuple = format_args };

                break :blk .{ .call = .{
                    .callee = try self.allocExpr(.{
                        .ident = try self.alloc.dupe(u8, "r2z.format.write"),
                    }),
                    .args = call_args,
                } };
            },
            .enum_variant => |ev| blk: {
                const variant_entity = self.ir.graph.symbol_table.get(ev.def) orelse {
                    return error.MissingDefinition;
                };
                if (variant_entity.kind != .variant and variant_entity.kind != .enum_) {
                    return error.InvalidVariantDefinition;
                }
                if (ev.variant.len == 0) return error.MissingVariantName;
                if (ev.named_fields.len > 0 and ev.tuple_fields.len > 0) {
                    return error.VariantArityMismatch;
                }
                // `io::ErrorKind` is a real standard enum, so its variants
                // arrive as `enum_variant` rather than as a synthetic
                // prelude type. A unit variant IS its runtime member, under the
                // same std spelling on both sides, so it names that member
                // directly — the runtime enum the type side already maps
                // `std::io::ErrorKind` to, with no second declaration
                // generated here. A payload-carrying variant is a different
                // shape and still refuses.
                if (self.isIoErrorKindVariant(ev.def)) {
                    if (ev.tuple_fields.len != 0 or ev.named_fields.len != 0) {
                        return error.VariantArityMismatch;
                    }
                    break :blk .{ .field_access = .{
                        .target = try self.allocExpr(.{ .ident = "r2z.io.ErrorKind" }),
                        .field_name = try self.alloc.dupe(u8, ev.variant),
                    } };
                }
                if (self.syntheticExternalType(ev.def)) |synthetic_kind| {
                    switch (synthetic_kind) {
                        .option => {
                            if (std.mem.eql(u8, ev.variant, "None")) {
                                if (ev.tuple_fields.len != 0) {
                                    return error.VariantArityMismatch;
                                }
                                break :blk .{ .cast = .{
                                    .target = try self.lowerType(try self.typeById(ir_expr.ty orelse return error.MissingTypedLiteralIdentity)),
                                    .operand = try self.allocExpr(.{ .lit = .null_lit }),
                                } };
                            }
                            if (!std.mem.eql(u8, ev.variant, "Some") or
                                ev.tuple_fields.len != 1)
                            {
                                return error.VariantArityMismatch;
                            }
                            const option_type = try self.nodeType(expr_id) orelse
                                return error.MissingTypedLiteralIdentity;
                            // As with `Ok`, the `Some` node is the only place
                            // that states what its payload is.
                            const previous_expected_type = self.expected_value_type;
                            if (option_type == .option) {
                                self.expected_value_type = option_type.option.*;
                            }
                            defer self.expected_value_type = previous_expected_type;
                            break :blk .{ .cast = .{
                                .target = try self.lowerType(option_type),
                                .operand = try self.allocExpr(try self.lowerExpr(ev.tuple_fields[0])),
                            } };
                        },
                        .result => {
                            if ((!std.mem.eql(u8, ev.variant, "Ok") and
                                !std.mem.eql(u8, ev.variant, "Err")) or
                                ev.tuple_fields.len != 1)
                            {
                                return error.VariantArityMismatch;
                            }
                            // Which `Result` this constructor builds decides
                            // how it is spelled, and the node's own type — its
                            // annotation, or the context the enclosing
                            // expression established — is what says.
                            // `current_return_type` is the fallback for a node
                            // the frontend left unannotated: the frame that
                            // returns it still states what it returns, and
                            // nothing else does. Guessing the other way here
                            // is what emitted `.{ .Ok = 7 }` where a Zig error
                            // union wants the bare payload.
                            // The descriptor is read from whatever carrier the
                            // type carries, and lives in this frame: a type the
                            // lowering spells as an error union has no table
                            // entry to borrow from.
                            var node_arms_value: ir.types.Result = undefined;
                            const node_arms: ?*const ir.types.Result =
                                if ((try self.nodeType(expr_id))) |node_type|
                                    (if (resultDescriptorOf(node_type)) |descriptor| node_descriptor: {
                                        node_arms_value = descriptor;
                                        break :node_descriptor &node_arms_value;
                                    } else null)
                                else
                                    null;
                            var return_arms_value: ir.types.Result = undefined;
                            const return_arms: ?*const ir.types.Result =
                                if (self.current_return_type) |return_type|
                                    (if (resultDescriptorOf(return_type)) |descriptor| return_descriptor: {
                                        return_arms_value = descriptor;
                                        break :return_descriptor &return_arms_value;
                                    } else null)
                                else
                                    null;
                            const result: ?*const ir.types.Result = node_arms orelse return_arms;
                            const is_ok = std.mem.eql(u8, ev.variant, "Ok");
                            // Whether this `Result` is a Zig error union decides
                            // two things below: the constructor has no union to
                            // name, and its error argument is the one place an
                            // error tag belongs. Both are answered from the
                            // descriptor this node resolved — the frame's
                            // return type is the fallback for resolving that
                            // descriptor, not a substitute for it, because a
                            // callable can build a `Result` as a local value
                            // and return something else entirely.
                            const native_error_union = if (result) |arms|
                                self.resultUsesErrorUnion(.{ .result = arms })
                            else
                                false;
                            const previous_expected_type = self.expected_value_type;
                            if (result) |arms| {
                                // Nothing else in the source says what
                                // `[0x66, ..]` is inside `Ok([0x66, ..])`, and
                                // Zig needs a type name on an array literal, so
                                // this is where the frontend's missing
                                // annotation is recovered.
                                self.expected_value_type = if (is_ok) arms.ok else arms.err;
                            }
                            defer self.expected_value_type = previous_expected_type;
                            // A payload-free variant of the error enum IS the
                            // tag an error union keeps bare, so it is emitted
                            // as one here and the ordinary union member it
                            // would otherwise become is never built. Any other
                            // payload is lowered as the value it is and mapped
                            // afterwards: only the value that lands in the
                            // error slot is in error position, so a call
                            // argument or a local binding underneath keeps
                            // ordinary semantics.
                            const constant_tag: ?[]const u8 = if (result) |arms|
                                if (is_ok or !native_error_union)
                                    null
                                else
                                    self.errorTagConstant(ev.tuple_fields[0], arms.err)
                            else
                                null;
                            if (constant_tag) |tag| {
                                break :blk .{ .lit = .{ .error_tag = try self.alloc.dupe(u8, tag) } };
                            }
                            const payload = try self.lowerExpr(ev.tuple_fields[0]);
                            if (result) |arms| {
                                if (native_error_union) {
                                    // A Zig error union carries its payload
                                    // bare and its error as the error set, so
                                    // `Ok(v)` IS `v` and `Err(e)` IS `e` — the
                                    // latter's payload is the error variant
                                    // itself, which `errorTagMapping` turns
                                    // into the tag that value is. There is no
                                    // union here to name, so the tagged
                                    // initializer has nothing to say.
                                    if (is_ok) {
                                        // `Ok(v)` IS `v`, and the union already
                                        // spells the payload type, so a cast is
                                        // only what a number needs: a bare `7`
                                        // carries no type of its own. Every
                                        // other payload IS already the value
                                        // the slot takes, and a cast naming a
                                        // named type is a node the AST
                                        // validator refuses outright
                                        // (ast.zig:1226-1228) — an enum
                                        // payload reached it and the whole
                                        // translation died on it.
                                        if (isIntegerType(arms.ok) or
                                            isFloatType(arms.ok))
                                        {
                                            break :blk .{ .cast = .{
                                                .target = try self.lowerType(arms.ok),
                                                .operand = try self.allocExpr(payload),
                                            } };
                                        }
                                        break :blk payload;
                                    }
                                    break :blk try self.errorTagMapping(payload, arms.err);
                                }
                                // `r2z.Result` is a union and `.{}` is a
                                // struct literal, so the anonymous form only
                                // coerces where an expected type already
                                // reaches it. Naming the union keeps
                                // `Ok`/`Err` a `Result` in every position.
                                break :blk try self.taggedResultArm(
                                    ev.variant,
                                    payload,
                                    try self.lowerTaggedResult(arms.ok, arms.err),
                                );
                            }
                            break :blk try self.taggedResultArm(ev.variant, payload, null);
                        },
                    }
                }
                // `ev.def` names the variant when the entity graph linked it,
                // and the owning enum otherwise; the variant name is always
                // present, so resolve through whichever form the def took.
                const variant_fields = self.enumVariantFields(ev.def) orelse
                    self.enumVariantFieldsByName(ev.def, ev.variant) orelse
                    {
                        return error.MissingVariantDefinition;
                    };
                switch (variant_fields) {
                    .none => {
                        if (ev.tuple_fields.len != 0) return error.VariantArityMismatch;
                    },
                    .tuple => |fields| {
                        if (ev.tuple_fields.len != fields.len) return error.VariantArityMismatch;
                    },
                    .named => |fields| {
                        if (ev.named_fields.len != fields.len) return error.VariantArityMismatch;
                    },
                }
                const variant_name = try self.alloc.dupe(u8, ev.variant);
                // A payload-free variant is a value of its enum here, and it
                // stays one. `error.Name` is not a spelling of this
                // expression but of the error value a `Result` that lowers to
                // a Zig error union carries bare, and the `Err` constructor is
                // what knows both that the union is a native one and that its
                // argument is the value in the error slot — see
                // `errorTagConstant` and `errorTagMapping`. Deciding it here
                // from the enclosing frame's return type instead turned every
                // field-free enum in a `Result`-returning body into a tag: a
                // `Result`'s own `Ok` value, and the ordinary enum values
                // around it.
                if (ev.named_fields.len > 0) {
                    // A struct-style variant carries an anonymous struct, so the
                    // payload is a second initializer nested inside the variant
                    // field: `.{ .Variant = .{ .field = value } }`.
                    const payload_fields = try self.alloc.alloc(
                        ast.StructInitField,
                        ev.named_fields.len,
                    );
                    for (ev.named_fields, 0..) |named, index| {
                        const name = try self.alloc.dupe(u8, named.field);
                        errdefer self.alloc.free(name);
                        payload_fields[index] = .{
                            .name = name,
                            .expr = try self.lowerExpr(named.value),
                        };
                    }
                    const variant_fields_list = try self.alloc.alloc(ast.StructInitField, 1);
                    variant_fields_list[0] = .{
                        .name = variant_name,
                        .expr = .{ .struct_init = .{
                            .type_name = null,
                            .fields = payload_fields,
                        } },
                    };
                    // The initializer names the *enum*, not the variant: the
                    // variant is the single field the initializer carries.
                    break :blk ast.Expr{
                        .struct_init = .{
                            .type_name = ast.Type{ .named = try self.enumOwnerName(ev.def) },
                            .fields = variant_fields_list,
                        },
                    };
                }
                // A field-less variant is a value of its enum, and which
                // spelling that takes follows the declaration the enum's own
                // lowering picks. A data-carrying enum declares as a tagged
                // `union(enum)`, where every variant is a field and a
                // payload-free one is declared `void`: the value is then the
                // struct initializer that fills that field, and `Enum.Variant`
                // would be the union's tag enum instead, whose type is wrong
                // everywhere except the one comparison a tag happens to
                // satisfy — `FromHexError::OddLength.to_string()` handed the
                // formatter a tag and the runtime rejected it. A purely
                // field-free enum declares as a plain Zig `enum`, whose
                // members are bare tags with no field to initialize at all,
                // so the value is the tag itself.
                if (ev.tuple_fields.len == 0) {
                    const owner_name = try self.enumOwnerName(ev.def);
                    if (!self.enumDeclaresTagFields(ev.def)) {
                        break :blk ast.Expr{ .field_access = .{
                            .target = try self.allocExpr(.{ .ident = owner_name }),
                            .field_name = variant_name,
                        } };
                    }
                    const fields = try self.alloc.alloc(ast.StructInitField, 1);
                    fields[0] = .{ .name = variant_name, .expr = .{ .unit = {} } };
                    break :blk ast.Expr{ .struct_init = .{
                        .type_name = ast.Type{ .named = owner_name },
                        .fields = fields,
                    } };
                }
                const tuple_payload = try self.alloc.alloc(ast.Expr, ev.tuple_fields.len);
                errdefer self.alloc.free(tuple_payload);
                for (ev.tuple_fields, 0..) |field_id, index| {
                    tuple_payload[index] = try self.lowerExpr(field_id);
                }
                // One element is the field type itself; several form the
                // anonymous tuple struct the union field declares.
                const payload: ast.Expr = if (tuple_payload.len == 1)
                    tuple_payload[0]
                else
                    .{ .tuple = tuple_payload };
                const tuple_fields_list = try self.alloc.alloc(ast.StructInitField, 1);
                errdefer self.alloc.free(tuple_fields_list);
                tuple_fields_list[0] = .{
                    .name = variant_name,
                    .expr = payload,
                };
                break :blk ast.Expr{
                    .struct_init = .{
                        .type_name = ast.Type{ .named = try self.enumOwnerName(ev.def) },
                        .fields = tuple_fields_list,
                    },
                };
            },
            .field => |fe| blk: {
                const base = try self.allocExpr(try self.lowerExpr(fe.base));
                errdefer self.alloc.destroy(base);
                // A field that had to move because a method of the same name
                // sits on the struct keeps its source name in the IR; the
                // emitted name comes from the struct's rename table.
                var source_name = fe.field;
                if (try self.exprType(fe.base)) |base_type| {
                    if (self.structDefForType(base_type)) |struct_id| {
                        source_name = self.structFieldName(struct_id, fe.field);
                    }
                }
                const field_name = try self.alloc.dupe(u8, source_name);
                errdefer self.alloc.free(field_name);
                break :blk ast.Expr{
                    .field_access = .{
                        .target = base,
                        .field_name = field_name,
                    },
                };
            },
            .index => |ie| blk: {
                if (ie.index >= self.ir.bodies.exprs.len) {
                    return error.MissingExpressionNode;
                }
                var base = try self.allocExpr(try self.lowerExpr(ie.base));
                // A lowered `Vec` is an `ArrayListUnmanaged`; Zig indexes the
                // storage it holds, so read through `.items` before indexing.
                const base_type = try self.exprType(ie.base);
                if (needsContainerStorageProjection(base_type)) {
                    // A `Vec` produced by a call is still an error union here:
                    // `f()[0]` is lowered as a bare `f()` because Rust's `?`
                    // already propagated, and `f().items` projects a member
                    // the error union does not have. Hoisting the producer into
                    // an owned temporary needs the `try` and `defer deinit`
                    // that only statement position has, so refuse.
                    if (base_type != null and self.resultUsesErrorUnion(base_type.?) or
                        isUnpropagatedErrorUnionExpr(base.*))
                    {
                        return error.UnsupportedExpression;
                    }
                    base = try self.allocExpr(.{ .field_access = .{
                        .target = base,
                        .field_name = "items",
                    } });
                }
                // Rust's indexing auto-derefs, and `lowerType` keeps a borrow
                // of an ARRAY as the pointer it really is (`*const [N] u8`), so
                // a hoisted `static ENC_TABLE: &[u8; N]` names its storage by
                // address. The slice is taken through that address, which is
                // also what keeps the static's address identity: nothing here
                // copies the array out from under it.
                if (borrowPointsAtArray(base_type)) {
                    base = try self.allocExpr(.{ .unary_op = .{
                        .op = .deref,
                        .operand = base,
                    } });
                }
                const idx = try self.allocExpr(switch (self.ir.bodies.exprs[ie.index].kind) {
                    // A slice index is a statement position: `s[0..n]`.
                    .range => |range| try self.lowerRangeSliceExpr(range, true),
                    else => try self.lowerExpr(ie.index),
                });
                const element = try self.indexSliceExpr(base, idx);
                break :blk if (try self.lowerOwnedElementTransfer(expr_id, ie, element)) |transfer|
                    transfer
                else
                    element;
            },
            .cast => |cast| blk: {
                const target_ir = try self.typeById(cast.target);
                if (target_ir == .slice and cast.kind == .as_) {
                    break :blk .{ .cast = .{
                        .target = try self.lowerType(target_ir),
                        .source = try self.lowerType(cast.source_type),
                        .operand = try self.allocExpr(try self.lowerExpr(cast.operand)),
                    } };
                }
                if (isScalarCastSource(cast.source_type)) {
                    if (!isScalarCastType(target_ir)) return error.UnsupportedExpression;
                    switch (cast.kind) {
                        .as_ => {},
                        .primitive_from => if (!isValidPrimitiveFrom(cast.source_type, target_ir)) {
                            return error.UnsupportedExpression;
                        },
                    }
                    break :blk try self.scalarCast(
                        cast.source_type,
                        target_ir,
                        try self.lowerExpr(cast.operand),
                    );
                }

                // A From conversion exists only between unsigned scalars, so
                // anything reaching the pointer path is not a legal primitive_from.
                if (cast.kind == .primitive_from) return error.UnsupportedExpression;
                if (cast.source_type == .raw_ptr and
                    self.pointerPointeeIsSized(cast.source_type.raw_ptr.pointee) and isIntegerType(target_ir))
                {
                    const address = try self.scalarBuiltin("intFromPtr", try self.lowerExpr(cast.operand));
                    break :blk try self.scalarCast(.{ .prim = .usize }, target_ir, address);
                }
                const target_pointer = switch (target_ir) {
                    .raw_ptr => |pointer| pointer,
                    else => return error.UnsupportedExpression,
                };
                // A fat borrow is `&[T]`, `&mut [T]`, a bare `[T]` slice, or a
                // `*const [T]` / `*mut [T]`, and every one of them carries the
                // element AND the length. Casting between them re-labels the
                // fat pointer and keeps both, so the emitted `@ptrCast` sits
                // between two slices and loses neither the pointer nor the
                // length.
                //
                // The rule is the one the frontend and the validator already
                // apply, restated rather than reinvented: only a fat
                // destination can hold the length, the element types have to
                // agree, and a shared borrow cannot become a mutable pointer.
                if (self.fatBorrowElement(cast.source_type)) |source_elem| {
                    const target_elem = self.hashFatPointeeElement(target_pointer.pointee) orelse
                        return error.UnsupportedExpression;
                    if (!fatBorrowCastCompatible(
                        source_elem,
                        cast.source_type != .raw_ptr and fatBorrowIsShared(cast.source_type),
                        target_elem,
                        target_pointer.mut,
                    )) return error.UnsupportedExpression;
                    break :blk try self.fatBorrowCast(cast.source_type, target_ir, cast.operand);
                }
                const source_pointer = switch (cast.source_type) {
                    .raw_ptr => |pointer| pointer,
                    .reference => |reference| break :blk try self.referenceToRawPointerCast(
                        reference.*,
                        target_pointer.*,
                        try self.lowerExpr(cast.operand),
                    ),
                    else => return error.UnsupportedExpression,
                };
                if (!self.pointerPointeesCompatible(source_pointer.pointee, target_pointer.pointee)) {
                    return error.UnsupportedExpression;
                }
                const target = try self.lowerType(target_ir);
                const source = try self.lowerType(cast.source_type);
                if (source == .ptr and source.ptr.size == .one and source.ptr.elem.* != .array)
                    return error.UnsupportedExpression;
                var cast_operand = try self.allocExpr(try self.lowerExpr(cast.operand));
                if (!source_pointer.mut and target_pointer.mut) {
                    const const_cast_args = try self.alloc.alloc(ast.Expr, 1);
                    const_cast_args[0] = cast_operand.*;
                    cast_operand = try self.allocExpr(.{ .builtin = .{
                        .name = "constCast",
                        .args = const_cast_args,
                    } });
                }
                const ptr_cast_args = try self.alloc.alloc(ast.Expr, 1);
                ptr_cast_args[0] = cast_operand.*;
                const pointer_cast = try self.allocExpr(.{ .builtin = .{
                    .name = "ptrCast",
                    .args = ptr_cast_args,
                } });
                break :blk ast.Expr{
                    .cast = .{
                        .target = target,
                        .operand = pointer_cast,
                        .source = source,
                    },
                };
            },
            .binary => |be| blk: {
                const uses_float = self.float_context or
                    isFloatType(try self.binopResultType(be));
                const previous_float_context = self.float_context;
                self.float_context = uses_float;
                defer self.float_context = previous_float_context;
                const lhs_ty = try self.exprType(be.lhs);
                const rhs_ty = try self.exprType(be.rhs);

                const comparison = switch (be.op) {
                    .eq, .ne, .lt, .le, .gt, .ge => true,
                    else => false,
                };
                const lhs_pointer_depth = if (comparison) self.rawPointerReferenceDepth(lhs_ty) else null;
                const rhs_pointer_depth = if (comparison) self.rawPointerReferenceDepth(rhs_ty) else null;
                const lhs_dereferences = lhs_pointer_depth orelse
                    @intFromBool(binaryOperandNeedsDeref(lhs_ty, be.op));
                const rhs_dereferences = rhs_pointer_depth orelse
                    @intFromBool(binaryOperandNeedsDeref(rhs_ty, be.op));

                const expected_int = integerOperandType(lhs_ty) orelse
                    integerOperandType(rhs_ty);

                const previous_expected_type = self.expected_argument_type;
                self.expected_argument_type = expected_int;
                defer self.expected_argument_type = previous_expected_type;

                var lhs_value = try self.lowerExpr(be.lhs);
                for (0..lhs_dereferences) |_| {
                    const operand = try self.allocExpr(lhs_value);
                    lhs_value = .{ .unary_op = .{ .op = .deref, .operand = operand } };
                }

                var rhs_value = try self.lowerExpr(be.rhs);
                for (0..rhs_dereferences) |_| {
                    const operand = try self.allocExpr(rhs_value);
                    rhs_value = .{ .unary_op = .{ .op = .deref, .operand = operand } };
                }
                if (lhs_pointer_depth != null and rhs_pointer_depth != null) {
                    const left_address = try self.scalarBuiltin("intFromPtr", lhs_value);
                    const right_address = try self.scalarBuiltin("intFromPtr", rhs_value);
                    lhs_value = left_address;
                    rhs_value = right_address;
                }
                const lhs = try self.allocExpr(lhs_value);
                const lowered_rhs = try self.allocExpr(rhs_value);
                // A literal the IR typed through a local ALIAS reaches Zig as a
                // bare `comptime_int`, and every operator here is either a
                // `comptime_int`-typed shift or a generic runtime helper that
                // takes its width from the operand. Rust typed that literal
                // inside the alias's own primitive, so the width is restored
                // before either one sees it.
                const widthed_lhs = try self.lowerAliasedLiteralOperand(be.lhs, lhs, lhs_ty);
                const widthed_rhs = try self.lowerAliasedLiteralOperand(be.rhs, lowered_rhs, rhs_ty);
                if (self.requiresRuntimeComparison(be.op, lhs_ty, rhs_ty)) {
                    defer self.alloc.destroy(widthed_lhs);
                    defer self.alloc.destroy(widthed_rhs);
                    break :blk try self.lowerBorrowedComparison(be, widthed_lhs.*, widthed_rhs.*);
                }

                const is_integer_shift = !uses_float and (be.op == .shl or be.op == .shr);
                const rhs = if (is_integer_shift)
                    try self.allocExpr(try self.lowerShiftAmount(widthed_rhs.*))
                else
                    widthed_rhs;
                // Rust shifts inside the left operand's type, so the left side
                // must hold that type before the shift, not after it.
                const shifted_lhs = if (is_integer_shift)
                    try self.lowerShiftOperand(be.lhs, widthed_lhs, lhs_ty)
                else
                    widthed_lhs;
                const op_kind: ast.BinOpKind = switch (be.op) {
                    .add => if (uses_float) .add else switch (be.overflow) {
                        .checked => .add,
                        .wrapping => .add_wrap,
                        .saturating => .add_sat,
                    },
                    .sub => if (uses_float) .sub else switch (be.overflow) {
                        .checked => .sub,
                        .wrapping => .sub_wrap,
                        .saturating => .sub_sat,
                    },
                    .mul => if (uses_float) .mul else switch (be.overflow) {
                        .checked => .mul,
                        .wrapping => .mul_wrap,
                        .saturating => .add,
                    },
                    .div => .div,
                    .rem => .mod,
                    .bit_and => .bit_and,
                    .bit_or => .bit_or,
                    .bit_xor => .bit_xor,
                    .shl => .shl,
                    .shr => .shr,
                    .eq => .equal,
                    .ne => .not_equal,
                    .lt => .less_than,
                    .le => .less_than_equal,
                    .gt => .greater_than,
                    .ge => .greater_than_equal,
                    .boolean_and => .bool_and,
                    .boolean_or => .bool_or,
                };
                break :blk ast.Expr{
                    .bin_op = .{
                        .op = op_kind,
                        .lhs = shifted_lhs,
                        .rhs = rhs,
                    },
                };
            },
            .unary => |ue| blk: {
                if (ue.op == .ref) {
                    if (try self.lowerOwnedTemporaryArgument(expr_id)) |owned| {
                        break :blk owned;
                    }
                    if (self.shouldElideSliceBorrow(ue.operand)) {
                        // The borrow is the slice descriptor, but a MUTABLE
                        // one over an array the binding owns still writes that
                        // array, and the address is what says so.
                        const keep_address = switch (ue.op) {
                            .ref => |mode| mode == .mutable and
                                self.mutableBorrowWritesOwnedArray(ue.operand),
                            else => false,
                        };
                        break :blk if (keep_address)
                            try self.lowerAddressedSliceBorrow(ue.operand)
                        else
                            try self.lowerExpr(ue.operand);
                    }
                    // `&dyn Trait` IS the borrowed handle, so the address-of
                    // reifies nothing; the operand is what becomes the
                    // handle, and taking ITS address is the erase. Applied
                    // after the coercion runs on the operand, it emits the
                    // handle by value exactly as the by-value parameter is
                    // declared.
                    if (try self.borrowIsTraitObjectItself(expr_id)) {
                        break :blk try self.lowerExpr(ue.operand);
                    }
                    // `&*container` borrows the SEQUENCE the container derefs
                    // to, and that sequence is a slice in Zig, so the borrow
                    // of it IS the slice. `&*bytes` over a `Vec<u8>` names
                    // `&[u8]`; taking the address of the descriptor instead
                    // would hand the callee a pointer to a list.
                    if (try self.borrowOfContainerStorage(ue.operand)) {
                        break :blk try self.lowerExpr(ue.operand);
                    }
                }
                if (ue.op == .deref and self.shouldElideValueCaptureDeref(ue.operand)) {
                    break :blk try self.lowerExpr(ue.operand);
                }
                if (ue.op == .deref) {
                    // A runtime container's `Deref` target is its element
                    // sequence, which a lowered `Vec` holds in `items`. Zig
                    // cannot dereference a list, so `*vec` reads that slice —
                    // the same bytes the Rust deref names, in the same storage.
                    if (needsContainerStorageProjection(try self.exprType(ue.operand))) {
                        const projected = try self.allocExpr(try self.lowerExpr(ue.operand));
                        break :blk (try self.allocExpr(.{ .field_access = .{
                            .target = projected,
                            .field_name = "items",
                        } })).*;
                    }
                }
                const operand = try self.allocExpr(try self.lowerExpr(ue.operand));

                const is_int_literal = self.isIntegerLiteral(ue.operand);
                const operand_type = (try self.exprType(ue.operand)) orelse self.expected_argument_type;
                const is_int_op = is_int_literal or self.isIntegerOperand(operand_type);
                const is_bit_not = (ue.op == .bit_not) or (ue.op == .logical_not and is_int_op);

                const final_operand = if (is_bit_not and is_int_literal) blk_cast: {
                    const int_ir_type = if (isIntegerType(self.expected_argument_type))
                        self.expected_argument_type.?
                    else if (isIntegerType(operand_type))
                        operand_type.?
                    else
                        ir.types.Type{ .prim = .usize };
                    const target_type = try self.lowerType(int_ir_type);
                    break :blk_cast try self.allocExpr(ast.Expr{
                        .cast = .{
                            .target = target_type,
                            .operand = operand,
                        },
                    });
                } else operand;

                const op_kind: ast.UnaryOpKind = switch (ue.op) {
                    .negate => .negate,
                    .logical_not => if (is_int_op) .bit_not else .bool_not,
                    .bit_not => .bit_not,
                    .deref => .deref,
                    .ref => .addr_of,
                };
                // A Rust raw pointer lowers to a Zig *many-item* pointer so
                // that `ptr.add(n)` keeps working, and Zig indexes a
                // many-item pointer with `[0]`, not `.*`. Only a known raw
                // pointer is rewritten; an unknown operand type keeps the
                // ordinary dereference.
                const deref_operand_is_raw_ptr =
                    if (try self.exprType(ue.operand)) |operand_ty| operand_ty == .raw_ptr else false;
                if (ue.op == .deref and deref_operand_is_raw_ptr) {
                    const index = try self.allocExpr(.{ .lit = .{ .int = 0 } });
                    const index_args = try self.alloc.alloc(ast.Expr, 2);
                    index_args[0] = final_operand.*;
                    index_args[1] = index.*;
                    break :blk (try self.allocExpr(.{ .builtin = .{
                        .name = "index",
                        .args = index_args,
                    } })).*;
                }
                // Rust's `&T` asserts `align_of::<T>()`; a raw pointer does
                // not, so the place reached through one carries alignment 1.
                // Taking a reference to it has to re-establish the
                // alignment the reference type promises, and `@alignCast` is
                // how Zig asserts that.
                //
                // The trigger is deliberately narrow — the place must have
                // come from dereferencing a raw pointer, and the pointee must
                // be sized. A packed struct's field is a field access, not a
                // raw-pointer dereference, so it keeps its real (possibly 1)
                // alignment; and an unsized pointee (`&[u8]`, `&str`,
                // `&dyn Trait`) lowers to a Zig slice or fat value rather than
                // a pointer, so there is no alignment to assert. Putting this
                // on the address-of rather than the deref is what keeps an
                // unaligned read — `get_unaligned_chunk` — free of it.
                if (ue.op == .ref and try self.addressOfAssertsAlignment(ue.operand)) {
                    const align_args = try self.alloc.alloc(ast.Expr, 1);
                    align_args[0] = (try self.allocExpr(.{ .unary_op = .{
                        .op = .addr_of,
                        .operand = final_operand,
                    } })).*;
                    break :blk (try self.allocExpr(.{ .builtin = .{
                        .name = "alignCast",
                        .args = align_args,
                    } })).*;
                }
                break :blk ast.Expr{
                    .unary_op = .{
                        .op = op_kind,
                        .operand = final_operand,
                    },
                };
            },

            .assign => |assignment| blk: {
                const statements = try self.alloc.alloc(ast.Stmt, 1);
                errdefer self.alloc.free(statements);
                statements[0] = try self.lowerAssignmentStmt(assignment);
                const unit = try self.allocExpr(.{ .unit = {} });
                break :blk .{ .block = .{
                    .stmts = statements,
                    .expr = unit,
                } };
            },
            .try_ => |te| blk: {
                const previous_explicit_try = self.explicit_try_expr;
                self.explicit_try_expr = te.inner;
                defer self.explicit_try_expr = previous_explicit_try;
                const operand_expr = try self.lowerExpr(te.inner);
                if (try self.lowerOptionPropagation(operand_expr, te.inner)) |propagated| {
                    break :blk propagated;
                }
                if (try self.lowerTaggedResultPropagation(operand_expr, te.inner)) |propagated| {
                    break :blk propagated;
                }
                break :blk ast.Expr{
                    .unary_op = .{
                        .op = .try_op,
                        .operand = try self.allocExpr(operand_expr),
                    },
                };
            },
            .return_ => |re| blk: {
                const val = if (re.value) |v| try self.allocExpr(try self.lowerExpr(v)) else null;
                break :blk ast.Expr{ .return_expr = val };
            },
            .range => |range| try self.lowerRangeExpr(range),
            .panic_ => |panic_expr| ast.Expr{
                .panic_ = try self.alloc.dupe(u8, panic_expr.message),
            },
            .closure => return error.UnsupportedExpression,
            .iterator_chain => |chain| switch (chain.terminal) {
                .sum, .collect_vec => blk: {
                    const result_type = try self.exprType(expr_id) orelse return error.MissingExpressionType;
                    break :blk .{ .block = if (chain.terminal == .sum)
                        try self.lowerIteratorSumBlock(chain, result_type)
                    else
                        try self.lowerIteratorCollectionBlock(chain, result_type) };
                },
                else => return error.UnsupportedExpression,
            },
            .unsupported => |u| blk: {
                if (isAssertionReason(u.reason)) {
                    break :blk try self.lowerAssertionMarker(u.reason);
                }
                return error.UnsupportedExpression;
            },
        };
    }

    /// Element type of a `vec!` literal, in descending order of authority:
    /// the annotation the literal carries, then the type the enclosing
    /// expression has already established, then the first element's own type —
    /// which is what inference settles on anyway. A nested literal is
    /// unannotated, so the context is what names its element; an empty `vec![]`
    /// with neither names nothing and has no element to stand in for it, and is
    /// refused rather than guessed at.
    fn vecLiteralElementType(
        self: *Lowerer,
        ir_expr: ir.exprs.Expr,
        vec: ir.exprs.VecLit,
    ) anyerror!ir.types.Type {
        // An annotation on the literal is the source stating what it is.
        if (ir_expr.ty) |tid| {
            if (try vecElementOfContext(try self.typeById(tid))) |element| return element;
        }
        // A nested literal has no annotation of its own: the frontend leaves
        // the inner node of `vec![vec![1, 100, 2], ..]` untyped and types the
        // integer literals themselves `i32`, Rust's default for an unsuffixed
        // literal, while the context the enclosing `vec!` established is the
        // better answer — `Vec<Vec<u32>>` names the inner element `u32`, and
        // that is the type they are appended into.
        if (self.expected_value_type) |context| {
            if (try vecElementOfContext(context)) |element| return element;
        }
        if (vec.elements.len == 0) return error.MissingExpressionType;
        return (try self.exprType(vec.elements[0])) orelse error.MissingExpressionType;
    }

    /// The element type a `Vec<T>` names, or null when `context` is not one.
    fn vecElementOfContext(context: ir.types.Type) anyerror!?ir.types.Type {
        switch (context) {
            .external_nominal => |external| {
                if (!isAllocVecPath(external.path)) return null;
                if (external.args.len != 1) return error.GenericArgumentArityMismatch;
                return external.args[0];
            },
            else => return null,
        }
    }

    /// One `try <owner>.append(allocator, <element>);` statement.
    ///
    /// Every element builds its own `ast.Expr` nodes. The emitter walks a
    /// shared tree, so one call node reused across statements would print the
    /// last element at every position — `vec![(0, 1), (2, 3)]` would append
    /// `(2, 3)` twice and still compile.
    fn vecAppendStatement(self: *Lowerer, owner_name: []const u8, element: ast.Expr) anyerror!ast.Stmt {
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .ident = "allocator" };
        args[1] = element;
        return .{ .expr_stmt = try self.allocExpr(.{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(.{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = owner_name }),
                    .field_name = "append",
                } }),
                .args = args,
            } }),
        } }) };
    }

    /// Transfers one owned element and releases it if vector growth fails.
    fn vecAppendOwnedStatements(
        self: *Lowerer,
        owner_name: []const u8,
        element: ast.Expr,
        element_type: ir.types.Type,
    ) anyerror![]ast.Stmt {
        try self.markRuntimeImport();
        if (!ownedRuntimeContainerIsRuntimeMovable(element_type)) {
            const push_args = try self.alloc.alloc(ast.Expr, 3);
            push_args[0] = .{ .ident = "allocator" };
            push_args[1] = .{ .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, owner_name) }),
            } };
            push_args[2] = element;
            const push_generic_args = try self.alloc.alloc(ast.Type, 1);
            push_generic_args[0] = try self.lowerType(element_type);
            const pushed = try self.alloc.alloc(ast.Stmt, 1);
            pushed[0] = .{ .expr_stmt = try self.allocExpr(.{ .unary_op = .{
                .op = .try_op,
                .operand = try self.allocExpr(.{ .call = .{
                    .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_push_owned" }),
                    .generic_args = push_generic_args,
                    .args = push_args,
                } }),
            } }) };
            return pushed;
        }
        const slot_name = try self.iteratorTemporaryName("__r2z_vec_item");

        const reserve_args = try self.alloc.alloc(ast.Expr, 2);
        reserve_args[0] = .{ .ident = "allocator" };
        reserve_args[1] = .{ .lit = .{ .uint = 1 } };
        const reserve = try self.allocExpr(.{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(.{ .call = .{
                .callee = try self.allocExpr(.{ .field_access = .{
                    .target = try self.allocExpr(.{ .ident = owner_name }),
                    .field_name = "ensureUnusedCapacity",
                } }),
                .args = reserve_args,
            } }),
        } });

        const take_args = try self.alloc.alloc(ast.Expr, 1);
        take_args[0] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, slot_name) }),
        } };
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(element_type);
        const append_args = try self.alloc.alloc(ast.Expr, 1);
        append_args[0] = .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.alloc.takeOwned" }),
            .generic_args = generic_args,
            .args = take_args,
        } };
        const append = try self.allocExpr(.{ .call = .{
            .callee = try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(.{ .ident = owner_name }),
                .field_name = "appendAssumeCapacity",
            } }),
            .args = append_args,
        } });

        const release_args = try self.alloc.alloc(ast.Expr, 2);
        release_args[0] = .{ .ident = "allocator" };
        release_args[1] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, slot_name) }),
        } };

        const emitted = try self.alloc.alloc(ast.Stmt, 4);
        emitted[0] = .{ .let_stmt = .{
            .name = try self.alloc.dupe(u8, slot_name),
            .ty = try self.lowerType(element_type),
            .init = element,
            .is_mut = true,
        } };
        // Built where it is used: `DeferStmt.expr` holds the value, so routing
        // this through `allocExpr` would leave a node behind that nothing reads.
        emitted[1] = .{ .defer_stmt = .{
            .expr = .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = "r2z.alloc.dropTemporary" }),
                .args = release_args,
            } },
            .is_errdefer = true,
        } };
        emitted[2] = .{ .expr_stmt = reserve };
        emitted[3] = .{ .expr_stmt = append };
        return emitted;
    }

    /// The `errdefer` a partially built list runs on its way out.
    ///
    /// A list of elements that own storage has to release them before the slab
    /// that holds them, which is exactly what `r2z.alloc.dropTemporary` does for
    /// a runtime vector. It recognises the list through the same `Vec(T)` the
    /// runtime declares, and a `Vec<String>` is `ArrayListUnmanaged(String)`,
    /// which Zig 0.16 spells as one type with `ArrayList(String)`. An element
    /// that owns nothing keeps the plain `deinit(allocator)`: there is nothing
    /// to walk, and the slab is all the list ever held.
    fn vecFailureReleaseStatement(
        self: *Lowerer,
        owner_name: []const u8,
        release_elements: bool,
    ) anyerror!ast.Stmt {
        if (!release_elements) {
            return .{ .defer_stmt = .{
                .expr = .{ .call = .{
                    .callee = try self.allocExpr(.{ .field_access = .{
                        .target = try self.allocExpr(.{ .ident = owner_name }),
                        .field_name = "deinit",
                    } }),
                    .args = &.{.{ .ident = "allocator" }},
                } },
                .is_errdefer = true,
            } };
        }
        try self.markRuntimeImport();
        const args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = .{ .ident = "allocator" };
        args[1] = .{ .unary_op = .{
            .op = .addr_of,
            .operand = try self.allocExpr(.{ .ident = owner_name }),
        } };
        return .{ .defer_stmt = .{
            .expr = .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = "r2z.alloc.dropTemporary" }),
                .args = args,
            } },
            .is_errdefer = true,
        } };
    }

    /// Builds a Vec; repetition evaluates the template and count once, in order.
    fn lowerVecLiteral(
        self: *Lowerer,
        ir_expr: ir.exprs.Expr,
        vec: ir.exprs.VecLit,
    ) anyerror!ast.Expr {
        const element_type = try self.vecLiteralElementType(ir_expr, vec);
        // An element the runtime owns cannot reach the list the way an `i32`
        // does: `append` evaluates the element and only then allocates, so a
        // growth failure would strand the bytes it just built. See
        // `vecAppendOwnedStatements` for the shape that does not.
        const elements_own_storage = vecElementMayOwnRuntimeStorage(element_type);
        if (vec.repeat) |count| {
            if (vec.elements.len != 1) return error.UnsupportedExpression;
            if (elements_own_storage) {
                const previous_expected_type = self.expected_value_type;
                self.expected_value_type = element_type;
                defer self.expected_value_type = previous_expected_type;
                const arguments = try self.alloc.alloc(ast.Expr, 3);
                arguments[0] = .{ .ident = "allocator" };
                arguments[1] = try self.lowerExpr(vec.elements[0]);
                arguments[2] = try self.lowerVecRepeatCount(count);
                const generic_args = try self.alloc.alloc(ast.Type, 1);
                generic_args[0] = try self.lowerType(element_type);
                try self.markRuntimeImport();
                self.current_callable_is_allocating = true;
                const repeated: ast.Expr = .{ .unary_op = .{
                    .op = .try_op,
                    .operand = try self.allocExpr(.{ .call = .{
                        .callee = try self.allocExpr(.{ .ident = "r2z.alloc.vec_repeat_owned" }),
                        .generic_args = generic_args,
                        .args = arguments,
                    } }),
                } };
                if (count == .literal) return repeated;
                const template_name = try self.iteratorTemporaryName("__r2z_repeat_template");
                const count_name = try self.iteratorTemporaryName("__r2z_repeat_count");
                const count_label = try self.iteratorTemporaryName("__r2z_repeat_count_value");
                const count_stmts = try self.alloc.alloc(ast.Stmt, 1);
                count_stmts[0] = try self.ownerReleaseStatement(template_name, true);
                count_stmts[0].defer_stmt.is_errdefer = true;
                const staged = try self.alloc.alloc(ast.Stmt, 2);
                staged[0] = .{ .let_stmt = .{
                    .name = template_name,
                    .ty = try self.lowerType(element_type),
                    .init = arguments[1],
                    .is_mut = true,
                } };
                staged[1] = .{ .let_stmt = .{
                    .name = count_name,
                    .ty = .{ .prim = .usize },
                    .init = .{ .block = .{
                        .label = count_label,
                        .stmts = count_stmts,
                        .expr = try self.allocExpr(arguments[2]),
                    } },
                    .is_mut = false,
                } };
                arguments[1] = .{ .ident = template_name };
                arguments[2] = .{ .ident = count_name };
                return .{ .block = .{
                    .label = try self.iteratorTemporaryName("__r2z_repeat_value"),
                    .stmts = staged,
                    .expr = try self.allocExpr(repeated),
                } };
            }
        }
        const releases_elements = elements_own_storage;
        const owner_type = try self.lowerRuntimeGenericExternalType(
            "std.ArrayListUnmanaged",
            &.{element_type},
            1,
        );
        const owner_name = try self.iteratorTemporaryName("__r2z_vec");
        // The emitter's fallback numbers a value block by nesting depth, so
        // two literals in one statement list would land on the same label.
        const label = try std.fmt.allocPrint(self.alloc, "{s}_value", .{owner_name});
        const owner_type_expr: ast.Expr = switch (owner_type) {
            .named => |name| .{ .ident = name },
            .generic => |generic| .{ .call = .{
                .callee = try self.allocExpr(.{ .ident = generic.name }),
                .generic_args = generic.params,
                .args = &.{},
            } },
            else => return error.UnsupportedCollectionType,
        };

        var stmts: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer stmts.deinit(self.alloc);
        try stmts.append(self.alloc, .{ .let_stmt = .{
            .name = owner_name,
            .ty = owner_type,
            .init = .{ .field_access = .{
                .target = try self.allocExpr(owner_type_expr),
                .field_name = "empty",
            } },
            .is_mut = true,
        } });
        // `errdefer`, not `defer`: on the way out the block hands the list to
        // its caller, which owns it from then on. Only a failure while building
        // it still has to release what it holds.
        try stmts.append(
            self.alloc,
            try self.vecFailureReleaseStatement(owner_name, releases_elements),
        );

        // Every element of this list has the `Vec`'s element type, including
        // a nested literal the frontend left untyped.
        const previous_expected_type = self.expected_value_type;
        self.expected_value_type = element_type;
        defer self.expected_value_type = previous_expected_type;

        if (vec.repeat) |count| {
            if (vec.elements.len != 1) return error.UnsupportedExpression;
            const template_name = try self.iteratorTemporaryName("__r2z_repeat_value");
            try stmts.append(self.alloc, .{ .let_stmt = .{
                .name = template_name,
                .ty = try self.lowerType(element_type),
                .init = try self.lowerExpr(vec.elements[0]),
                .is_mut = false,
            } });
            const body = try self.alloc.alloc(ast.Stmt, 1);
            body[0] = try self.vecAppendStatement(
                owner_name,
                .{ .ident = template_name },
            );
            // The input slice is allocated, not `&.{ .. }`: the range holds
            // two heap-allocated endpoints, so the literal is a runtime
            // temporary and a pointer to it dangles the moment this block
            // ends. Validation reads it back after lowering and segfaulted.
            const inputs = try self.alloc.alloc(ast.Expr, 1);
            inputs[0] = .{ .range = .{
                .start = try self.allocExpr(.{ .lit = .{ .uint = 0 } }),
                .end = try self.allocExpr(try self.lowerVecRepeatCount(count)),
            } };
            const captures = try self.alloc.alloc(ast.Capture, 1);
            captures[0] = .{ .name = "_" };
            try stmts.append(self.alloc, .{ .expr_stmt = try self.allocExpr(.{ .for_expr = .{
                .inputs = inputs,
                .captures = captures,
                .body = .{ .stmts = body },
            } }) });
        } else if (releases_elements) {
            for (vec.elements) |element| {
                try stmts.appendSlice(
                    self.alloc,
                    try self.vecAppendOwnedStatements(
                        owner_name,
                        try self.lowerExpr(element),
                        element_type,
                    ),
                );
            }
        } else {
            for (vec.elements) |element| {
                try stmts.append(
                    self.alloc,
                    try self.vecAppendStatement(owner_name, try self.lowerExpr(element)),
                );
            }
        }

        return .{ .block = .{
            .label = label,
            .stmts = try stmts.toOwnedSlice(self.alloc),
            .expr = try self.allocExpr(.{ .ident = owner_name }),
        } };
    }

    fn lowerVecRepeatCount(self: *Lowerer, count: ir.exprs.VecRepeatCount) anyerror!ast.Expr {
        const previous = self.expected_value_type;
        self.expected_value_type = .{ .prim = .usize };
        defer self.expected_value_type = previous;
        return switch (count) {
            .literal => |value| .{ .lit = .{ .uint = value } },
            .expression => |node| try self.lowerExpr(node),
        };
    }
    /// Lower `operand?` when the operand is a `Result` that becomes the tagged
    /// `r2z.Result` union, and `null` when a Zig `try` is the right spelling.
    ///
    /// A Zig `try` only applies to error unions, so applying one to a tagged
    /// union is a type error. Rust's `?` converts the error through `From`;
    /// when the operand and the enclosing function already share one error
    /// type that conversion is the identity and the propagation is a switch
    /// over the two tags. A differing error type needs a conversion the
    /// backend has no faithful spelling for, and dropping it would silently
    /// change the program, so it is reported instead.
    /// What a blanket impl's method call resolves to: the hoisted function
    /// the call becomes, and the self type it is called with. Null when the
    /// method has no blanket impl, the impl declares no method by that name,
    /// or the receiver is neither a known array nor an array literal whose
    /// length the bound can type.
    const BlanketCallTarget = struct {
        method_fn_id: ir.spine.EntityId,
        self_type: ir.types.Type,
    };

    fn blanketCallTarget(
        self: *Lowerer,
        method_def: ir.spine.EntityId,
        method_name: []const u8,
        receiver: ir.exprs.NodeId,
    ) !?BlanketCallTarget {
        const impl_id = switch (self.blanketImplForMethod(method_def)) {
            .unique => |impl_id| impl_id,
            .none, .ambiguous => return null,
        };
        const method_fn_id = self.blanketImplMethod(impl_id, method_name) orelse return null;
        // Element type from the declared bound, never from the literal.
        const element = self.blanketBoundElement(impl_id) orelse return null;
        const self_type = (try self.blanketReceiverType(receiver, element)) orelse return null;
        return .{ .method_fn_id = method_fn_id, .self_type = self_type };
    }

    /// Emit a call to a blanket impl's method as a direct call to the hoisted
    /// free function.
    ///
    /// A blanket `impl<T: AsRef<[u8]>> ToHex for T` has no concrete self type,
    /// so its methods cannot live in a Zig struct. `collectHoistedMethods`
    /// emits them as free functions on the enclosing module, which
    /// `moduleHoistGenericParams` already shapes as
    /// `fn encode_hex(comptime T: type, comptime U: type, allocator, self) U`.
    /// Zig has no method dispatch, so `receiver.encode_hex(..)` — what the
    /// general path emits — is not a call at all. This produces
    /// `encode_hex(SelfType, U, ..., &receiver, ...)` instead.
    ///
    /// `SelfType` comes from the impl's DECLARED bound plus the receiver's
    /// length. It is never inferred from the magnitude of the elements: an
    /// unsuffixed literal has no type until context fixes one, and reading
    /// "the values all fit in a u8" off the literal would type a program the
    /// source never said. If the bound cannot produce a type that provably
    /// accepts the receiver, this returns null and the general path runs,
    /// refusing the call rather than guessing.
    fn lowerBlanketImplMethodCall(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        mc: ir.exprs.MethodCall,
        method_name: []const u8,
        receiver: ast.Expr,
        args: []const ast.Expr,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
    ) !?ast.Expr {
        const target = (try self.blanketCallTarget(mc.method, method_name, mc.receiver)) orelse return null;
        const method_fn_id = target.method_fn_id;
        const self_type = target.self_type;

        const takes_allocator = self.hoistedMethodTakesAllocator(method_fn_id);

        // Comptime type arguments: the impl's own `T` first, then the
        // method's own parameters, matching the declared parameter order.
        const self_type_ast = try self.lowerType(self_type);
        const method_generics = try self.lowerCallGenericArgs(expr_id, method_fn_id, mc.args, mc.generic_args);
        const generic_args = try self.alloc.alloc(ast.Type, method_generics.len + 1);
        generic_args[0] = self_type_ast;
        @memcpy(generic_args[1..], method_generics);

        // The receiver is a value; the hoisted function takes `self: *const
        // T`. Zig cannot take the address of an array literal, so a literal
        // receiver is bound to a local first.
        const receiver_ref = try self.bindReceiverForAddress(prelude, receiver, self_type_ast);

        // The hoisted declaration takes the allocator as a real parameter, so
        // the call site names one. Every other path that emits that
        // `allocator` identifier also raises `current_callable_is_allocating`,
        // which is what makes the enclosing function — or a translated
        // `#[test]` — declare a local allocator. Without it the argument
        // resolved to nothing: a test reached
        // `encode_hex([6]u8, r2z.alloc.String, allocator, &x)` with no
        // `allocator` in scope and Zig rejected it.
        if (takes_allocator) self.current_callable_is_allocating = true;
        const call_args = try self.alloc.alloc(
            ast.Expr,
            1 + @as(usize, @intFromBool(takes_allocator)) + args.len,
        );
        // The hoisted declaration puts the allocator immediately before the
        // first value parameter — `paramsWithAllocator` inserts it at the
        // method's own generic count — and the receiver is that first value
        // parameter. Emitting the allocator after the receiver called
        // `from_hex(T, hex, allocator)` against a declaration of
        // `from_hex(comptime T, allocator, hex)`.
        var at: usize = 0;
        if (takes_allocator) {
            call_args[at] = .{ .ident = "allocator" };
            at += 1;
        }
        call_args[at] = receiver_ref;
        at += 1;
        @memcpy(call_args[at..][0..args.len], args);

        return .{
            .call = .{
                // A hoisted method is declared at module scope, so a call from
                // another translated module has to name it as `root.encode_hex`.
                // `hoistedNameFor` returns the bare name; `lowerResolvedEntityName`
                // resolves the same name and adds the owning module's alias.
                .callee = try self.allocExpr(.{ .ident = try self.lowerResolvedEntityName(method_fn_id) }),
                .generic_args = generic_args,
                .args = call_args,
            },
        };
    }

    /// The `self` expression for a hoisted call, which takes a pointer. A
    /// value that already has an address is taken directly; a literal is
    /// bound to a local, because Zig has no address-of expression for one.
    fn bindReceiverForAddress(
        self: *Lowerer,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
        receiver: ast.Expr,
        self_type: ast.Type,
    ) !ast.Expr {
        const needs_local = switch (receiver) {
            .array_init, .repeat, .multi_array, .struct_init => true,
            else => false,
        };
        if (!needs_local) {
            const held = try self.allocExpr(receiver);
            return (try self.allocExpr(.{
                .unary_op = .{ .op = .addr_of, .operand = held },
            })).*;
        }
        const name = try std.fmt.allocPrint(self.alloc, "__r2z_blanket_self_{d}", .{
            prelude.items.len,
        });
        try prelude.append(self.alloc, .{ .let_stmt = .{
            .name = name,
            .ty = self_type,
            .init = receiver,
        } });
        const held = try self.allocExpr(.{ .ident = name });
        return (try self.allocExpr(.{
            .unary_op = .{ .op = .addr_of, .operand = held },
        })).*;
    }

    /// The owned `String` behind the type wrappers a receiver can carry, or
    /// null when the receiver is some other type. The wrappers are the ones
    /// `lowerMemoryReceiver` and `memoryElementType` already peel, so the
    /// answer agrees with how the receiver itself was lowered.
    fn ownedStringType(ty: ir.types.Type) ?ir.types.Type {
        var current = ty;
        for (0..128) |_| {
            if (isOwnedStringType(current)) return current;
            current = switch (current) {
                .@"opaque" => |opaque_type| (opaque_type.concrete orelse return null).*,
                .boxed => |boxed| boxed.*,
                else => return null,
            };
        }
        return null;
    }

    /// Whether `r2z.alloc.String` spells the receiver of `method_name`
    /// `self: *String` rather than `self: *const String`.
    ///
    /// Every shared view takes the shared receiver, which Zig hands over from
    /// whatever storage the call site already has. The rest need mutable
    /// storage: `into_bytes` transfers the allocation out and empties the
    /// string, `push`/`push_str`/`extend` grow it, `clear`/`reserve` reshape
    /// it, and `as_mut_str` hands out a mutable view of it.
    fn stringMethodNeedsMutableReceiver(method_name: []const u8) bool {
        const mutable_receiver_methods = [_][]const u8{
            "as_mut_str", "clear",    "extend",  "into_bytes",
            "push",       "push_str", "reserve",
        };
        for (mutable_receiver_methods) |candidate| {
            if (std.mem.eql(u8, method_name, candidate)) return true;
        }
        return false;
    }

    /// Give a `String` receiver that is a temporary the storage its method
    /// needs to be reached through `self: *String`.
    ///
    /// Zig has no address-of expression for a call result, so a receiver with
    /// no storage of its own is bound to a local — `(try r2z.alloc.String
    /// .from_str(..)).into_bytes()` is rejected with "cast discards const
    /// qualifier" otherwise. The binding goes in at `prelude_at`, ahead of
    /// whatever the call's own arguments bound there, because the receiver is
    /// what the source evaluates first. `deinit` runs when the enclosing
    /// expression ends: a consuming method leaves the string empty, so that
    /// call is a no-op rather than a second free, and a method that only
    /// mutates frees exactly what the source would have dropped.
    fn bindRuntimeStringReceiver(
        self: *Lowerer,
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
        prelude_at: usize,
        receiver_expr: *const ast.Expr,
        receiver_node: ir.exprs.NodeId,
        method_name: []const u8,
    ) !*const ast.Expr {
        if (!stringMethodNeedsMutableReceiver(method_name)) return receiver_expr;
        const receiver_type = (try self.exprType(receiver_node)) orelse return receiver_expr;
        const owned_type = ownedStringType(receiver_type) orelse return receiver_expr;
        // A PLACE already owns its storage, and Zig takes the mutable self
        // pointer straight from a place: a binding, a field, an index, or a
        // dereference. Aliasing one into a fresh local would COPY the string and
        // leave the original place still naming the allocation the transfer
        // already handed away, so the deferred release would free storage the
        // caller still owns. Only a value with no place at all — a call result,
        // the shape the existing `__r2z_string_receiver` test covers — needs one,
        // and only that copy is genuinely unaliased.
        if (exprIsAddressable(receiver_expr.*)) return receiver_expr;
        const reserved = self.current_owner_reserved orelse return receiver_expr;
        try self.appendCollectorImportAliases(reserved);
        const name = try self.collectorBindingName("__r2z_string_receiver", reserved.items);
        try reserved.append(self.alloc, name);
        try prelude.insert(self.alloc, prelude_at, .{ .let_stmt = .{
            .name = name,
            .ty = try self.lowerType(owned_type),
            .init = receiver_expr.*,
            .is_mut = true,
        } });
        const held = try self.allocExpr(.{ .ident = name });
        const deinit = try self.allocExpr(.{ .field_access = .{
            .target = held,
            .field_name = try self.alloc.dupe(u8, "deinit"),
        } });
        try prelude.insert(self.alloc, prelude_at + 1, .{ .defer_stmt = .{
            .expr = .{ .call = .{
                .callee = deinit,
                .args = &.{.{ .ident = "allocator" }},
            } },
            .is_errdefer = false,
        } });
        // `deinit` names the enclosing allocator, which is what makes the
        // callable declare one.
        self.current_callable_is_allocating = true;
        const bound_receiver = try self.allocExpr(.{ .ident = name });
        return bound_receiver;
    }

    const BlanketImplMatch = union(enum) {
        none,
        unique: ir.spine.EntityId,
        ambiguous,
    };

    /// The blanket impls declaring `method_name` for the exact `trait_id`,
    /// whose self type is a type parameter rather than a concrete declaration.
    ///
    /// Two of them name that trait method ambiguously, and a
    /// constrained receiver does not make the pair less ambiguous — nothing
    /// about the receiver's declaration says which impl its method comes from.
    /// The frontend's `lookupBlanketAsRefBytesTrait` refuses that pair rather
    /// than picking one, so this refuses it too: taking the first match would
    /// dispatch a call the resolver deliberately left unresolved, to a
    /// declaration the source never named.
    fn blanketImplFor(
        self: *const Lowerer,
        trait_id: ir.spine.EntityId,
        method_name: []const u8,
    ) BlanketImplMatch {
        var found: ?ir.spine.EntityId = null;
        const count = self.ir.graph.symbol_table.count();
        for (0..count) |idx| {
            const impl_id: ir.spine.EntityId = @intCast(idx);
            if (impl_id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            const last = lastPathSegment(trait_path.segments) orelse continue;
            if (last.id == null or last.id.? != trait_id) continue;
            if (blanketSelfTypeParam(impl_body.self_ty) == null) continue;
            if (self.blanketImplMethod(impl_id, method_name) == null) continue;
            if (found != null) return .ambiguous;
            found = impl_id;
        }
        return if (found) |impl_id| .{ .unique = impl_id } else .none;
    }

    /// The blanket impl a method call names, whether the call reached the
    /// trait's method reference or the impl's own `fn`.
    ///
    /// The two are the same declaration read from different ends, and which
    /// one a call carries depends on where it is written. At a call site the
    /// receiver is a concrete value, so the resolver attaches the trait's
    /// method reference. Inside a generic wrapper the receiver is a type
    /// parameter, and the resolver attaches the blanket impl's `fn` itself:
    /// inside `fn encode<T: AsRef<[u8]>>(data: T)`, `data.encode_hex()` has no
    /// trait method reference to name, and the trait round trip finds nothing.
    /// Walking up from the `fn` reads the same impl, so the call resolves.
    /// A method reference matches its parent trait and requested method name
    /// against generic-self impls only; unrelated traits and methods are
    /// excluded. The result distinguishes no match, one impl, and ambiguity.
    /// A direct `fn` matches only its enclosing generic-self impl.
    fn blanketImplForMethod(self: *const Lowerer, method_def: ir.spine.EntityId) BlanketImplMatch {
        const entity = self.ir.graph.symbol_table.get(method_def) orelse return .none;
        if (entity.kind == .method_ref) {
            const trait_id = entity.parent orelse return .none;
            return self.blanketImplFor(trait_id, entity.name);
        }
        if (entity.kind != .fn_) return .none;
        const parent_id = entity.parent orelse return .none;
        if (parent_id >= self.ir.bodies.bodies.len) return .none;
        const parent = switch (self.ir.bodies.bodies[parent_id]) {
            .impl_ => |body| body,
            else => return .none,
        };
        if (blanketSelfTypeParam(parent.self_ty) == null) return .none;
        return .{ .unique = parent_id };
    }

    /// The `fn` entity a blanket impl declares for `method_name`.
    fn blanketImplMethod(
        self: *const Lowerer,
        impl_id: ir.spine.EntityId,
        method_name: []const u8,
    ) ?ir.spine.EntityId {
        if (impl_id >= self.ir.bodies.bodies.len) return null;
        const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
            .impl_ => |body| body,
            else => return null,
        };
        for (impl_body.assoc_items) |item_id| {
            const entity = self.ir.graph.symbol_table.get(item_id) orelse continue;
            if (entity.kind != .fn_) continue;
            if (!std.mem.eql(u8, entity.name, method_name)) continue;
            return item_id;
        }
        return null;
    }

    /// A blanket trait method call, and the impl's `fn` its effect belongs to.
    const BlanketDispatchEdge = struct {
        /// The `.method_ref` the call names.
        reference: ir.spine.EntityId,
        /// The impl's `fn` that declaration lowering resolves the call to.
        target: ir.spine.EntityId,
    };

    /// Every blanket dispatch in the crate, resolved the way the declaration
    /// lowering resolves it.
    ///
    /// A `receiver.method(..)` call on a blanket impl names the TRAIT's
    /// `.method_ref`, while the declaration that answers it is the impl's own
    /// `fn`. `blanketCallTarget` is how a call site bridges the two before it
    /// reads an effect or a parameter list, and the effect scan — which walks
    /// the call graph the resolver already settled, without the resolver — has
    /// no such bridge. It marked neither table for the callers of
    /// `encode_hex`, and `fn encode<T: AsRef<[u8]>>(data: T) -> String` then
    /// declared an allocator its call sites never passed and no error union
    /// around a body whose `try` returns one.
    ///
    /// Resolving the same calls here, from the same tables the lowering reads,
    /// is what puts the two back in step. A receiver this shape cannot type
    /// leaves the edge unbuilt: a pass whose only power is to widen the tables
    /// must not also be able to refuse a crate that lowers today.
    fn blanketDispatchEdges(self: *Lowerer) ![]const BlanketDispatchEdge {
        var edges: std.ArrayListUnmanaged(BlanketDispatchEdge) = .empty;
        errdefer edges.deinit(self.alloc);
        for (self.ir.bodies.exprs) |expression| {
            const method_call = switch (expression.kind) {
                .method_call => |value| value,
                else => continue,
            };
            const method = self.ir.graph.symbol_table.get(method_call.method) orelse continue;
            const target = self.blanketCallTarget(
                method_call.method,
                method.renamed_to orelse method.name,
                method_call.receiver,
            ) catch continue;
            const resolved = target orelse continue;
            try edges.append(self.alloc, .{
                .reference = method_call.method,
                .target = resolved.method_fn_id,
            });
        }
        return edges.toOwnedSlice(self.alloc);
    }

    /// The Zig type for a function parameter whose declared type is a
    /// callable the frontend could not pin to a concrete type, or null when
    /// the parameter is not one.
    ///
    /// `impl FnOnce(&str) -> T` is the shape a generic test helper is written
    /// in: `fn test_hash<T: Eq + Debug>(hash_func: impl FnOnce(&str) -> T, ..)`.
    /// The IR keeps it as an opaque bound over `core::ops::FnOnce` that
    /// inference never resolved, so `lowerType` reaches its
    /// `error.UnresolvedOpaqueType` arm and the whole crate is refused over a
    /// helper the source spells plainly.
    ///
    /// What is recovered here is what the IR actually carries, and nothing
    /// else: a bound argument that is already a function pointer lowers as
    /// that pointer, so a signature the frontend did resolve is preserved
    /// exactly. A bare `Fn`/`FnMut`/`FnOnce` bound carries no signature at
    /// all, and Zig's `anytype` parameter is the honest spelling of "whatever
    /// this call site passes" — it names no arity and no result type the
    /// source did not state, and the call inside the body still has to
    /// type-check. Inventing `*const fn (?) T` instead would assert a
    /// signature nothing in the IR supports.
    fn lowerCallableParamType(self: *Lowerer, param_type: ir.types.Type) !?ast.Type {
        const opaque_type = switch (param_type) {
            .@"opaque" => |value| value,
            else => return null,
        };
        // A resolved carrier is a concrete type, not a callable signature.
        if (opaque_type.concrete != null) return null;
        var callable = false;
        var signature: ?*const ir.types.FnPtr = null;
        for (opaque_type.bounds) |bound| {
            if (!isClosureTraitPath(bound.path)) continue;
            callable = true;
            for (bound.args) |arg| {
                switch (arg) {
                    .fn_ptr => |fn_ptr| signature = fn_ptr,
                    else => {},
                }
            }
        }
        if (signature) |fn_ptr| {
            const pointer_type = try self.lowerType(.{ .fn_ptr = fn_ptr });
            return pointer_type;
        }
        return if (callable) ast.Type{ .named = "anytype" } else null;
    }

    /// Whether a trait bound path names one of Rust's three closure traits,
    /// spelled bare or through the `core::ops` prelude path it resolves to.
    fn isClosureTraitPath(path: ir.types.Path) bool {
        const segments = path.segments;
        return switch (segments.len) {
            1 => isClosureTraitName(segments[0].name),
            3 => std.mem.eql(u8, segments[0].name, "core") and
                std.mem.eql(u8, segments[1].name, "ops") and
                isClosureTraitName(segments[2].name),
            else => false,
        };
    }

    fn isClosureTraitName(name: []const u8) bool {
        return std.mem.eql(u8, name, "Fn") or
            std.mem.eql(u8, name, "FnMut") or
            std.mem.eql(u8, name, "FnOnce");
    }

    /// The type-parameter name a blanket impl's self type is written as, if
    /// the self type is a bare type parameter rather than a real type.
    fn blanketSelfTypeParam(self_ty: ir.types.Type) ?[]const u8 {
        return switch (self_ty) {
            .path => |path| blk: {
                if (path.segments.len != 1) break :blk null;
                const segment = path.segments[0];
                if (segment.id != null) break :blk null;
                break :blk segment.name;
            },
            else => null,
        };
    }

    /// The element type the impl's declared bound requires of its self type.
    ///
    /// Read from the bound the source wrote — `T: AsRef<[u8]>` gives `u8` —
    /// so the concrete self type is the one the source declared, never a
    /// guess fitted to the values at the call site.
    fn blanketBoundElement(self: *const Lowerer, impl_id: ir.spine.EntityId) ?ir.types.Type {
        if (impl_id >= self.ir.bodies.bodies.len) return null;
        const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
            .impl_ => |body| body,
            else => return null,
        };
        const self_param = blanketSelfTypeParam(impl_body.self_ty) orelse return null;
        const generics = impl_body.generics orelse return null;
        for (generics.params) |param| {
            const type_param = switch (param) {
                .type_ => |value| value,
                else => continue,
            };
            if (!std.mem.eql(u8, type_param.name, self_param)) continue;
            for (type_param.bounds) |bound| {
                for (bound.args) |arg| {
                    // `AsRef<[u8]>` and friends: the first type argument names
                    // the element type the self type must expose.
                    switch (arg) {
                        .slice => |slice| return slice.elem,
                        .array => |array| return array.elem,
                        else => {},
                    }
                }
            }
        }
        return null;
    }

    /// The concrete self type for this call site: the bound's element type
    /// with the receiver's own length.
    ///
    /// A receiver whose type is already known is checked against the bound
    /// and used as-is, so a receiver the bound does not accept is refused. A
    /// receiver that is an array literal takes its LENGTH from the literal
    /// and its ELEMENT type from the bound, whether or not inference has
    /// already written a type down for it: `exprType` answers an unsuffixed
    /// integer literal as `i32`, the fallback Rust itself applies before any
    /// context can pin it, so `[0x66, 0x6f]` arrives as `[2]i32` even though
    /// the source said nothing about `i32`. `arrayLiteralIsFallback` is what
    /// separates that default from an element type the source chose, and it
    /// is the same read for a literal the frontend left untyped.
    ///
    /// A receiver typed by a type parameter is the third accepted shape, and
    /// it is the shape a generic wrapper is written in: inside
    /// `fn encode<T: AsRef<[u8]>>(data: T)` the body says `data.encode_hex()`,
    /// where `data` is `T` and the method belongs to `impl<T: AsRef<[u8]>>
    /// ToHex for T`. There is no array to read a length from and no element
    /// type to check, but the hoisted function takes `comptime T: type`, so
    /// the parameter itself is the right self type. Refusing it left
    /// `data.encode_hex(..)` as a Zig member call on a `[]const u8`.
    fn blanketReceiverType(
        self: *Lowerer,
        receiver: ir.exprs.NodeId,
        element: ir.types.Type,
    ) !?ir.types.Type {
        if (receiver >= self.ir.bodies.exprs.len) return null;
        const receiver_expr = self.ir.bodies.exprs[receiver];
        // An untyped literal still takes its element type from the declared
        // bound, and so does one whose recorded type is only the inference
        // fallback: reconstructing it from that fallback invents i32 before
        // the bound can apply.
        const known_type = if (receiver_expr.kind == .array and
            (receiver_expr.ty == null or self.arrayLiteralIsFallback(receiver_expr.kind.array)))
            null
        else
            try self.exprType(receiver);
        if (known_type) |known| {
            if (isTypeParameterPath(known)) return known;
            const array = switch (known) {
                .array => |value| value,
                else => return null,
            };
            // A known receiver must actually match the declared bound.
            if (!sameIrType(array.elem, element)) return null;
            return known;
        }
        const literal = switch (self.ir.bodies.exprs[receiver].kind) {
            .array => |value| value,
            else => return null,
        };
        if (literal.elements.len == 0) return null;
        const array = try self.alloc.create(ir.types.Array);
        array.* = .{ .elem = element, .len = .{ .literal = literal.elements.len } };
        return .{ .array = array };
    }

    /// Whether an array literal's recorded element type is the integer
    /// literal FALLBACK rather than anything the source chose.
    ///
    /// An unsuffixed integer literal has no type until its context fixes one,
    /// and inference writes down the fallback `i32` in the meantime. That
    /// default is not the source naming an element type: `[0x66, 0x6f, 0x6f]`
    /// in a position whose bound says `AsRef<[u8]>` is `[3]u8`, and refusing
    /// the `i32` the fallback left behind left `receiver.encode_hex(..)` as a
    /// Zig member call on an array Zig has no such field of. A literal whose
    /// elements carry a suffix, or that repeats a count instead of listing
    /// elements, names its own element type and is still checked against the
    /// bound.
    fn arrayLiteralIsFallback(self: *const Lowerer, literal: ir.exprs.ArrayExpr) bool {
        if (literal.repeat != null or literal.elements.len == 0) return false;
        for (literal.elements) |element| {
            if (element >= self.ir.bodies.exprs.len) return false;
            const suffix = switch (self.ir.bodies.exprs[element].kind) {
                .literal => |value| switch (value) {
                    .int => |int| int.ty_suffix,
                    else => return false,
                },
                else => return false,
            };
            if (suffix != null) return false;
        }
        return true;
    }

    /// The type an array literal is emitted with: the surrounding context's
    /// answer when the node's own type is only the integer-literal FALLBACK,
    /// and the node's own type otherwise.
    ///
    /// Inference writes `i32` down for an unsuffixed array literal before any
    /// context can pin it, and that default is not an annotation. A blanket
    /// impl's bound types its receiver from the bound's element and the
    /// literal's own length (`blanketReceiverType`) and hands that answer
    /// here through `expected_value_type`; taking the fallback instead
    /// emitted `[3]i32{ .. }` where the call site's self type says `[3]u8`,
    /// which Zig rejects on the binding the call reads it back through. Only
    /// an array of the literal's own length is taken, so a context that means
    /// something else cannot retype the literal behind the caller's back, and
    /// a literal that named its own element type keeps it.
    fn arrayLiteralType(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
        literal: ir.exprs.ArrayExpr,
    ) anyerror!?ir.types.Type {
        const recorded = try self.nodeType(expr_id);
        if (!self.arrayLiteralIsFallback(literal)) return recorded;
        const expected = self.expected_value_type orelse return recorded;
        return switch (expected) {
            .array => |array| switch (array.len) {
                .literal => |len| if (len == literal.elements.len) expected else recorded,
                else => recorded,
            },
            else => recorded,
        };
    }

    fn sameIrType(left: ir.types.Type, right: ir.types.Type) bool {
        if (std.meta.activeTag(left) != std.meta.activeTag(right)) return false;
        return switch (left) {
            .prim => |value| value == right.prim,
            else => false,
        };
    }

    /// Whether a type names a type parameter rather than a declaration. A path
    /// segment without an entity id is how the IR spells `T`: no declaration
    /// named `T` exists, so the name binds to whatever the enclosing callable
    /// declares as a `comptime` parameter.
    fn isTypeParameterPath(ty: ir.types.Type) bool {
        const path = switch (ty) {
            .path => |value| value,
            else => return false,
        };
        if (path.segments.len != 1) return false;
        const segment = path.segments[0];
        return segment.id == null and segment.name.len != 0;
    }

    /// Whether an `AsRef`-shaped borrow of `receiver_node` is a borrow OF the
    /// value behind the receiver rather than the receiver itself.
    ///
    /// The blanket impl `impl<T: AsRef<[u8]>> ToHex for T` writes its body as
    /// `self.as_ref()` with `self: &T` and `T` the impl's own type parameter.
    /// `AsRef` is implemented for `T`, not for `&T`, so Rust's method lookup
    /// dereferences the receiver and reborrows from the value: what the call
    /// yields is `&[u8]`, never the `&T` it was written on.
    ///
    /// Only a type-parameter pointee is decided here, and it is decided by the
    /// IR rather than by a name. `self` lowers to `*const T` for a
    /// `comptime T: type` the declaration merely bounded, so handing that
    /// pointer to a `[]const u8` parameter asks Zig for a pointer-to-slice
    /// coercion and fails; the pointee is what the source wrote, and reading
    /// through the pointer keeps the borrow rather than copying the handle.
    /// A concrete pointee keeps its own path: a `&[u8]` the receiver really
    /// holds is already the slice, and dereferencing it would copy one.
    fn borrowReadsThroughGenericPointee(
        self: *Lowerer,
        receiver_node: ir.exprs.NodeId,
    ) anyerror!bool {
        const receiver_type = (try self.exprType(receiver_node)) orelse return false;
        const reference = switch (receiver_type) {
            .reference => |value| value,
            else => return false,
        };
        return isTypeParameterPath(reference.pointee);
    }

    /// Whether a hoisted blanket method takes a leading allocator, matching
    /// the parameter `lowerFnEntity` emits for an allocating callable.
    fn hoistedMethodTakesAllocator(self: *const Lowerer, method_fn_id: ir.spine.EntityId) bool {
        return self.callPassesAllocator(method_fn_id);
    }

    /// Free-function argument order: optional allocator, receiver, source arguments.
    fn hoistedSelfArguments(
        self: *Lowerer,
        method_fn_id: ir.spine.EntityId,
        receiver: *const ast.Expr,
        args: []const ast.Expr,
        allocates: bool,
    ) ![]ast.Expr {
        const receiver_index: usize = if (allocates) 1 else 0;
        const result = try self.alloc.alloc(ast.Expr, args.len + 1 + receiver_index);
        if (allocates) result[0] = .{ .ident = "allocator" };
        result[receiver_index] = if (hoistedSelfParameterIsBorrow(self, method_fn_id))
            (try self.allocExpr(.{ .unary_op = .{
                .op = .addr_of,
                .operand = try self.allocExpr(receiver.*),
            } })).*
        else
            receiver.*;
        @memcpy(result[receiver_index + 1 ..], args);
        return result;
    }

    fn iteratorPayloadReleases(
        self: *Lowerer,
        mid: ir.exprs.NodeId,
        pattern: ir.exprs.NodeId,
    ) anyerror!bool {
        if (pattern >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const carrier_ty = try self.exprType(mid) orelse return error.MissingExpressionType;
        const produced = try self.producedItemOf(carrier_ty);
        return produced.owning;
    }
    fn iteratorCarrierItemType(self: *Lowerer, ty: ir.types.Type) anyerror!?ir.types.Type {
        const external = switch (ty) {
            .external_nominal => |value| value,
            // `impl Iterator<Item = T>` is an OPAQUE, and its bound is the only
            // place the source writes down what such a value YIELDS.
            .@"opaque" => |opaque_type| return self.opaqueIteratorItemType(opaque_type),
            else => return null,
        };
        if (external.path.len != 3 or external.args.len == 0) return null;
        if (!std.mem.eql(u8, external.path[0], "core") and
            !std.mem.eql(u8, external.path[0], "std")) return null;
        if (std.mem.eql(u8, external.path[1], "slice")) {
            if (external.args.len != 1) return null;
            const mutable = if (std.mem.eql(u8, external.path[2], "IterMut"))
                true
            else if (std.mem.eql(u8, external.path[2], "Iter"))
                false
            else
                return null;
            const borrow = try self.alloc.create(ir.types.Ref);
            borrow.* = .{ .mut = mutable, .pointee = external.args[0] };
            return .{ .reference = borrow };
        }
        if (std.mem.eql(u8, external.path[1], "ops") and
            std.mem.eql(u8, external.path[2], "Range"))
        {
            if (external.args.len != 1) return null;
            return external.args[0];
        }
        if (!std.mem.eql(u8, external.path[1], "iter")) return null;
        if (std.mem.eql(u8, external.path[2], "Zip")) {
            if (external.args.len != 2) return null;
            const left = try self.iteratorCarrierItemType(external.args[0]) orelse return null;
            const right = try self.iteratorCarrierItemType(external.args[1]) orelse return null;
            const fields = try self.alloc.alloc(ir.types.Type, 2);
            fields[0] = left;
            fields[1] = right;
            return .{ .tuple = fields };
        }
        if (!isRuntimeIteratorAdapterName(external.path[2])) return null;
        if (external.args.len != 1) return null;
        const element = external.args[external.args.len - 1];
        const inner = try self.iteratorCarrierItemType(element) orelse return null;
        if (!std.mem.eql(u8, external.path[2], "Enumerate")) return inner;
        const fields = try self.alloc.alloc(ir.types.Type, 2);
        fields[0] = .{ .prim = .usize };
        fields[1] = inner;
        return .{ .tuple = fields };
    }

    /// The element type an `impl Iterator<Item = T>` receiver declares.
    ///
    /// `fn generate_iter(len: usize) -> impl Iterator<Item = (usize, usize)>`
    /// is an opaque, and the `Item` binding on its own bound is the only place
    /// the source writes down what that value YIELDS. The concrete carrier the
    /// frontend may have recovered beside the opaque describes the ADAPTER
    /// rather than its element — a `zip` over it cannot name its second half
    /// any other way — so the declared binding is read first and the concrete is
    /// only a fallback for an opaque that declares no `Item` at all.
    fn opaqueIteratorItemType(self: *Lowerer, opaque_type: ir.types.Opaque) !?ir.types.Type {
        if (self.declaredIteratorItem(opaque_type.bounds)) |item| return item;
        const concrete = opaque_type.concrete orelse return null;
        return self.iteratorCarrierItemType(concrete.*);
    }

    /// The `Item` the `core::iter::Iterator` bound among `bounds` declares.
    ///
    /// Proved the way `dynTraitBoundIs` proves a bound: the enclosing scope's
    /// own answer when a callable is in scope, and the path as written when
    /// every segment carries no entity id. A crate that declares its own
    /// `Iterator` writes the same word here and must not answer for core's.
    fn declaredIteratorItem(self: *const Lowerer, bounds: []const ir.types.Bound) ?ir.types.Type {
        const wanted = [_][]const u8{ "core", "iter", "Iterator" };
        if (self.traitBoundOwner()) |owner| {
            const object: ir.types.Type = .{ .@"opaque" = .{ .bounds = bounds } };
            if (ir.bodies.genericBound(&self.ir.graph, &self.ir.bodies, owner, object, &wanted)) |bound| {
                for (bound.associated_types) |binding| {
                    if (std.mem.eql(u8, binding.name, "Item")) return binding.ty;
                }
            }
        }
        for (bounds) |bound| {
            if (!externalBoundPathIs(bound.path, &wanted)) continue;
            for (bound.associated_types) |binding| {
                if (std.mem.eql(u8, binding.name, "Item")) return binding.ty;
            }
        }
        return null;
    }

    const ProducedItem = struct {
        ty: ir.types.Type,
        owning: bool,
    };

    fn producedItemOf(self: *Lowerer, carrier_ty: ir.types.Type) anyerror!ProducedItem {
        const ty = try self.iteratorCarrierItemType(carrier_ty) orelse
            return error.MissingExpressionType;
        return .{ .ty = ty, .owning = ownedRuntimeContainerType(ty) };
    }

    fn forInputElementType(self: *Lowerer, mid: ir.exprs.NodeId) anyerror!?ir.types.Type {
        const source = try self.forInputSource(mid);
        if (try self.memoryElementType(source)) |element| return element;
        const container = peelReceiverType(try self.exprType(source) orelse return null);
        const external = switch (container) {
            .external_nominal => |value| value,
            else => return null,
        };
        if (!isAllocVecPath(external.path)) return null;
        if (external.args.len != 1) return null;
        return external.args[0];
    }

    /// The `Option<T>` a `next()` call yields when the frontend left the node
    /// untyped.
    ///
    /// `Iterator::next` is declared to return `Option<Self::Item>`, and the
    /// carriers the runtime drives by `next` each say which `Item` they
    /// publish. A `?` on such a call is Rust's `Option` propagation, and it can
    /// only be recognised as one when the call is known to be an optional —
    /// without this the `?` falls through to a native `try` and asks an
    /// enclosing `-> Option<u8>` for an error union it does not return.
    fn iteratorNextOptionType(self: *Lowerer, operand_id: ir.exprs.NodeId) !?ir.types.Type {
        if (operand_id >= self.ir.bodies.exprs.len) return null;
        const call = switch (self.ir.bodies.exprs[operand_id].kind) {
            .method_call => |value| value,
            else => return null,
        };
        if (call.args.len != 0) return null;
        const method = self.ir.graph.symbol_table.get(call.method) orelse return null;
        if (!std.mem.eql(u8, method.name, "next")) return null;
        const receiver_type = try self.exprType(call.receiver) orelse return null;
        const carrier = peelReceiverType(receiver_type);
        if (!isNextDrivenIteratorCarrier(carrier)) return null;
        const item = try self.iteratorCarrierItemType(carrier) orelse return null;
        const option = try self.alloc.create(ir.types.Type);
        option.* = item;
        return .{ .option = option };
    }

    /// `x?` where `x` is an OPTIONAL, as Zig's own optional propagation.
    ///
    /// `try` is for error unions and an optional is not one, so `?` on an
    /// optional is Zig's `orelse`: the `None` leaves the enclosing function as
    /// its own `None`. Rust's `?` is that exact operation whenever the
    /// enclosing function returns an optional, so this is
    /// `{ const __r2z_try_optional = x; if (__r2z_try_optional) |v| v else
    /// return null; }` — one evaluation of the operand, and the value carried
    /// out of the block rather than dropped.
    ///
    /// Anything else has no `FromResidual` in the standard library to run, so
    /// this is not the shape and the answer is null.
    fn lowerOptionPropagation(
        self: *Lowerer,
        operand: ast.Expr,
        operand_id: ir.exprs.NodeId,
    ) !?ast.Expr {
        // A `next()` the inference pass never typed is still an optional: the
        // carrier's own `Item` is the answer, and without it the `?` below
        // would not be recognised as propagation at all.
        const operand_type = (try self.exprType(operand_id)) orelse
            (try self.iteratorNextOptionType(operand_id)) orelse
            return null;
        if (operand_type != .option and self.canonicalExternalMethodType(operand_type) != .option) return null;
        // A `?` inside an iterator ADAPTER body leaves the closure, which is
        // the item the chain yields; it cannot return from the function that
        // built the chain, so an adapter body whose enclosing result is the
        // collection's own is not this shape either.
        if (self.current_collector) |open| {
            if (open.result != null) return null;
        }
        const enclosing = self.current_return_type orelse return null;
        if (enclosing != .option and self.canonicalExternalMethodType(enclosing) != .option) return null;
        const subject = try self.iteratorTemporaryName("__r2z_try_optional");
        const payload = try self.iteratorTemporaryName("__r2z_try_value");
        const statements = try self.alloc.alloc(ast.Stmt, 1);
        statements[0] = .{ .let_stmt = .{
            .name = try self.alloc.dupe(u8, subject),
            .init = operand,
            .is_mut = false,
        } };
        const branch = try self.allocExpr(.{ .if_expr = .{
            .cond = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, subject) }),
            .then_capture = .{
                .name = try self.alloc.dupe(u8, payload),
                .by_ref = false,
            },
            .then_body = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, payload) }),
            .else_body = try self.allocExpr(.{ .return_expr = try self.allocExpr(.{
                .lit = .{ .null_lit = {} },
            }) }),
        } });
        return (try self.allocExpr(.{ .block = .{
            .label = null,
            .stmts = statements,
            .expr = branch,
        } })).*;
    }
    fn lowerTaggedResultPropagation(
        self: *Lowerer,
        operand: ast.Expr,
        operand_id: ir.exprs.NodeId,
    ) !?ast.Expr {
        const operand_type = (try self.exprType(operand_id)) orelse return null;
        // A native operand carries its error as a bare Zig tag, so it is
        // MATCHED rather than switched on, and that tag has to become a value
        // of the source's own error type before any `From` can take it.
        const source_native = self.resultUsesErrorUnion(operand_type);
        const operand_result = switch (operand_type) {
            .result => |value| value.*,
            else => return null,
        };
        // A `?` inside a `Result` collect's adapter body reports in the
        // collection. Rust's `?` leaves the `map` closure there, and `collect`
        // turns that into the collection's own `Err`; returning from the
        // enclosing function instead would report it in the function's result
        // and leave the function entirely, which a `collect` in let or
        // argument position cannot survive.
        const collector: ?Collector = if (self.current_collector) |open|
            (if (open.result != null) open else null)
        else
            null;
        const enclosing = if (collector) |open| open.result.? else blk: {
            const declared = self.current_return_type orelse
                return error.UnsupportedResultPropagation;
            break :blk declared;
        };
        const enclosing_result = switch (enclosing) {
            .result => |value| value.*,
            else => return error.UnsupportedResultPropagation,
        };
        // A plain `try` IS Rust's `?` in exactly one shape: the operand is
        // native, the enclosing result is native, and the two error types
        // agree, so the identity conversion needs no call and the union can be
        // propagated as it stands. Every other pairing has a conversion to
        // run, and a native operand has to be matched to reach its tag at all.
        const native_error = self.resultFieldsUseErrorUnion(enclosing_result);
        if (source_native and native_error and
            typeEquals(operand_result.err, enclosing_result.err))
        {
            return null;
        }
        const err_capture = try self.alloc.dupe(u8, "__r2z_try_err");
        // Rust's `?` runs the operand's error through `From` before it leaves
        // for the enclosing result, and a crate that hands a `Result<T,
        // io::Error>` out of a `Result<U, crate::Error>` says so in its own
        // `impl From<io::Error> for crate::Error`. That conversion is a real
        // call to a real declaration, so the Err arm runs it here rather than
        // either guessing a cast or giving up on the source that compiles.
        // Identical errors are the identity conversion, and that is the case
        // that needs no call at all.
        const source_value: ast.Expr = if (source_native)
            try self.sourceErrorValueFromTag(err_capture, operand_result.err)
        else
            .{ .ident = try self.alloc.dupe(u8, err_capture) };
        const converted_err: ?ast.Expr = if (typeEquals(
            operand_result.err,
            enclosing_result.err,
        )) null else try self.lowerResultErrorConversion(
            source_value,
            operand_result.err,
            enclosing_result.err,
        );
        // A Zig error union carries its error bare, so when the enclosing
        // result is one, the converted error IS the value the Err arm leaves
        // with: `errorTagMapping` names the tag that value is, and there is no
        // union here to build. Otherwise the arm reports into a tagged
        // `r2z.Result` and the same value goes in its `Err` slot.
        const converted: ast.Expr = if (converted_err) |value|
            value
        else
            source_value;
        const exit_err: ast.Expr = if (native_error)
            try self.errorTagMapping(converted, enclosing_result.err)
        else
            converted;
        const err_body: ast.Expr = if (collector) |open|
            try self.collectorErrorExit(open, exit_err)
        else if (native_error)
            .{ .return_expr = try self.allocExpr(exit_err) }
        else
            .{
                .return_expr = try self.allocExpr(
                    try self.taggedResultError(exit_err, enclosing_result),
                ),
            };
        // A `void` payload has nothing to bind, so the success side carries no
        // capture at all.
        const ok_capture: ?ast.Capture = if (operand_result.ok == .prim and
            operand_result.ok.prim == .unit)
            null
        else
            .{ .name = try self.alloc.dupe(u8, "__r2z_try_ok") };
        const ok_body: ast.Expr = if (ok_capture) |capture|
            .{ .ident = capture.name }
        else
            .{ .unit = {} };
        // A native operand is an error union, so its two outcomes are a
        // payload-capturing `if`: the success capture IS the Ok value and the
        // error capture IS the tag. A tagged operand keeps the two-arm switch
        // it has always had.
        if (source_native) {
            return .{ .if_expr = .{
                .cond = try self.allocExpr(operand),
                .then_capture = ok_capture,
                .then_body = try self.allocExpr(ok_body),
                .else_capture = .{ .name = err_capture },
                .else_body = try self.allocExpr(err_body),
            } };
        }
        const ok_patterns = try self.alloc.alloc(ast.Pattern, 1);
        ok_patterns[0] = .{ .enum_literal = try self.alloc.dupe(u8, "Ok") };
        const err_patterns = try self.alloc.alloc(ast.Pattern, 1);
        err_patterns[0] = .{ .enum_literal = try self.alloc.dupe(u8, "Err") };
        const arms = try self.alloc.alloc(ast.MatchArm, 2);
        arms[0] = .{ .patterns = ok_patterns, .capture = ok_capture, .body = ok_body };
        arms[1] = .{
            .patterns = err_patterns,
            .capture = .{ .name = err_capture },
            .body = err_body,
        };
        return .{ .match_expr = .{
            .target = try self.allocExpr(operand),
            .arms = arms,
        } };
    }

    /// The crate's own `From` conversion of a `?` error, or a refusal when it
    /// declares none.
    ///
    /// Rust's `?` converts the operand's error into the enclosing result's
    /// error, and the only conversion it can reach is `From`: the blanket
    /// `impl<T> From<T> for T` when the two already agree, otherwise whatever
    /// the crate declared. A crate that hands a `Result<T, io::Error>` out of a
    /// `Result<U, crate::Error>` declared `impl From<io::Error> for
    /// crate::Error>`, and THAT declaration is what gets called. The error is
    /// built by a real `fn from` with a real signature, never cast through a
    /// runtime helper that would have to guess the layout on both sides.
    ///
    /// A crate that declared no such impl has not written code that compiles,
    /// so a source that reaches here without one keeps the refusal rather than
    /// being given a conversion nobody wrote.
    fn lowerResultErrorConversion(
        self: *Lowerer,
        source_value: ast.Expr,
        source_err: ir.types.Type,
        target_err: ir.types.Type,
    ) anyerror!ast.Expr {
        const from_id = self.userFromConversion(source_err, target_err) orelse
            return error.UnsupportedResultErrorConversion;
        // The same callee spelling any other associated call gets: a `from`
        // written in a trait impl is a trait-impl member first and an
        // inherent method only when the impl declared no trait.
        const callee = if (try self.qualifyTraitImplMethod(from_id)) |trait_method|
            trait_method
        else
            try self.qualifyInherentMethod(from_id, try self.lowerResolvedEntity(from_id));
        const allocates = self.callPassesAllocator(from_id);
        // The conversion is part of the source, so an allocator it needs is one
        // the enclosing callable declares, exactly as for any other call it
        // makes.
        if (allocates) self.current_callable_is_allocating = true;
        const args = try self.alloc.alloc(ast.Expr, if (allocates) 2 else 1);
        if (allocates) args[0] = .{ .ident = "allocator" };
        args[args.len - 1] = source_value;
        const call: ast.Expr = .{ .call = .{
            .callee = try self.allocExpr(callee),
            .args = args,
        } };
        if (!self.callableFallible(from_id)) return call;
        return .{ .unary_op = .{ .op = .try_op, .operand = try self.allocExpr(call) } };
    }

    /// The source's own error value for a native error tag.
    ///
    /// A Zig error union carries its error as a bare tag, while a `From` impl
    /// is declared over the source's own error TYPE, so the tag has to become
    /// a value of that type before the conversion can take it. The runtime's
    /// `errorTagValue` is the way back: it walks the source enum's declared
    /// fields, so a tag the enum does not declare has no value there and is
    /// refused rather than reported as a failure the source never had.
    /// Reusing it keeps that property instead of growing a second mapping here.
    fn sourceErrorValueFromTag(
        self: *Lowerer,
        tag_capture: []const u8,
        source_err: ir.types.Type,
    ) anyerror!ast.Expr {
        try self.markRuntimeImport();
        const generic_args = try self.alloc.alloc(ast.Type, 1);
        generic_args[0] = try self.lowerType(source_err);
        const args = try self.alloc.alloc(ast.Expr, 1);
        args[0] = .{ .ident = try self.alloc.dupe(u8, tag_capture) };
        return .{ .call = .{
            .callee = try self.allocExpr(.{ .ident = "r2z.errorTagValue" }),
            .generic_args = generic_args,
            .args = args,
        } };
    }

    /// The enclosing tagged `r2z.Result` carrying `err_value` in its `Err`
    /// slot.
    fn taggedResultError(
        self: *Lowerer,
        err_value: ast.Expr,
        enclosing_result: ir.types.Result,
    ) anyerror!ast.Expr {
        const err_fields = try self.alloc.alloc(ast.StructInitField, 1);
        err_fields[0] = .{ .name = try self.alloc.dupe(u8, "Err"), .expr = err_value };
        const type_name = (try self.allocType(
            try self.lowerTaggedResult(enclosing_result.ok, enclosing_result.err),
        )).*;
        return .{ .struct_init = .{ .type_name = type_name, .fields = err_fields } };
    }

    /// The `fn from` a crate declared to turn `source` into `target`, or null
    /// when it declared no such conversion.
    ///
    /// The trait is `From` and the signature is `fn from(source) -> Self`,
    /// which inside `impl From<source> for target` is `target` by definition.
    /// Both are checked, and the signature is what finally decides: a crate's
    /// own conversion trait can carry a method named `from` that converts
    /// something else entirely, and a blanket `impl<T> From<T> for T` says
    /// nothing about this pair. Two impls claiming the same exact conversion is
    /// not a choice either of them, so that pair is refused rather than picked.
    fn userFromConversion(
        self: *const Lowerer,
        source: ir.types.Type,
        target: ir.types.Type,
    ) ?ir.spine.EntityId {
        const count = self.ir.graph.symbol_table.count();
        var found: ?ir.spine.EntityId = null;
        for (0..count) |index| {
            const impl_id: ir.spine.EntityId = @intCast(index);
            if (impl_id >= self.ir.bodies.bodies.len) continue;
            const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
                .impl_ => |body| body,
                else => continue,
            };
            const trait_path = impl_body.trait_path orelse continue;
            if (!self.canonicalFromTrait(impl_id, trait_path)) continue;
            // A generic impl states its conversion in terms of its own
            // parameters, so its declared types are not this pair's types even
            // when they read alike. The count is the test, not whether the
            // metadata block happens to be present.
            const generic_params: usize = if (impl_body.generics) |generics|
                generics.params.len
            else
                0;
            if (generic_params != 0) continue;
            if (!typeEquals(impl_body.self_ty, target)) continue;
            if (impl_body.trait_args.len != 1) continue;
            if (!typeEquals(impl_body.trait_args[0], source)) continue;
            const method = self.userFromMethod(impl_id, source, target) orelse continue;
            if (found != null and found.? != method) return null;
            found = method;
        }
        return found;
    }

    /// Whether an impl's trait path is exactly `core::convert::From`.
    ///
    /// This asks the pipeline's one trait-identity predicate rather than
    /// growing a second convention beside it. A name is not an identity: a
    /// crate may declare its own `trait From<E> { fn from(e: E) -> Self; }`,
    /// and that impl carries the same leaf name and can carry the same
    /// signature, so leaf-plus-signature would call a conversion the source
    /// never offered. `boundPathMatches` resolves the path the way Rust does —
    /// written out, imported by `use core::convert::From;`, or carrying that
    /// use on its first segment — and treats `std` as `core` because std
    /// re-exports it, so a root-qualified `std::convert::From` is answered too.
    fn canonicalFromTrait(
        self: *const Lowerer,
        impl_id: ir.spine.EntityId,
        path: ir.types.Path,
    ) bool {
        return ir.bodies.boundPathMatches(
            &self.ir.graph,
            impl_id,
            path,
            &.{ "core", "convert", "From" },
        );
    }

    /// The `fn from` that impl declares for exactly this pair, or null when it
    /// declares none, or declares something that is not this conversion.
    fn userFromMethod(
        self: *const Lowerer,
        impl_id: ir.spine.EntityId,
        source: ir.types.Type,
        target: ir.types.Type,
    ) ?ir.spine.EntityId {
        if (impl_id >= self.ir.bodies.bodies.len) return null;
        const impl_body = switch (self.ir.bodies.bodies[impl_id]) {
            .impl_ => |body| body,
            else => return null,
        };
        for (impl_body.assoc_items) |item_id| {
            const entity = self.ir.graph.symbol_table.get(item_id) orelse continue;
            if (entity.kind != .fn_) continue;
            if (!std.mem.eql(u8, entity.name, "from")) continue;
            if (item_id >= self.ir.bodies.bodies.len) continue;
            const function = switch (self.ir.bodies.bodies[item_id]) {
                .fn_ => |body| body,
                else => continue,
            };
            if (function.params.len != 1) continue;
            if (!typeEquals(function.params[0].ty, source)) continue;
            // `From` is written `fn from(error: E) -> Self`, and this impl's
            // self type has already been proven to BE the target, so `Self`
            // in this return position is that target by definition. The check
            // is the same recognised `Self` path every other reader in this
            // file asks `isSelfPath` about, not a second, looser way to read
            // the name. The PARAMETER stays a concrete comparison: it is the
            // source error Rust actually converts, and a `Self` there would be
            // a conversion of the target into itself, which is not this one.
            if (!typeEquals(function.ret, target) and !isSelfPath(function.ret)) continue;
            return item_id;
        }
        return null;
    }

    /// Whether taking a reference to this place must re-assert the alignment
    /// the reference type promises.
    ///
    /// The rule, stated once: a Rust raw pointer carries no alignment
    /// promise, so every place reached through one has alignment 1. Taking
    /// `&T` from such a place re-establishes `align_of::<T>()`, and that
    /// assertion is only meaningful — and only expressible — when `T` is
    /// sized. An unsized pointee (`&[u8]`, `&str`, `&dyn Trait`) is a fat
    /// pointer in Rust and a slice or fat value in Zig, so it has no pointer
    /// alignment to assert; and a packed struct's field is reached by a field
    /// access rather than a raw-pointer dereference, so it keeps whatever
    /// alignment it really has.
    ///
    /// Every case that returns false is one where an `@alignCast` would be
    /// wrong: either meaningless, or a runtime check Rust's `unsafe` code
    /// never promised — which is what would break a deliberately unaligned
    /// read.
    fn addressOfAssertsAlignment(self: *Lowerer, operand: ir.exprs.NodeId) !bool {
        const inner = switch (self.ir.bodies.exprs[operand].kind) {
            .unary => |unary| unary,
            else => return false,
        };
        if (inner.op != .deref) return false;
        const pointer = (try self.exprType(inner.operand)) orelse return false;
        const raw_pointer = switch (pointer) {
            .raw_ptr => |raw| raw,
            else => return false,
        };
        if (ir.types.isStr(raw_pointer.pointee)) return false;
        return switch (raw_pointer.pointee) {
            .slice, .dyn_trait => false,
            else => true,
        };
    }

    fn lowerAssignmentStmt(
        self: *Lowerer,
        assignment: ir.exprs.AssignExpr,
    ) anyerror!ast.Stmt {
        const target = try self.lowerExpr(assignment.target);
        var value = try self.lowerExpr(assignment.value);
        if (assignment.op != .plain and !self.shouldElideValueCaptureDeref(assignment.value)) {
            if (try self.exprType(assignment.value)) |known| {
                var value_type = known;
                for (0..128) |_| {
                    if (value_type != .reference) break;
                    const operand = try self.allocExpr(value);
                    value = .{ .unary_op = .{ .op = .deref, .operand = operand } };
                    value_type = value_type.reference.pointee;
                } else return error.InvalidTypeTraversal;
            }
        }
        // A plain assignment into a place that already OWNS runtime storage is
        // not a plain assignment: Rust drops what the place held and only then
        // moves the replacement in, and it does that in that order so a
        // failing right-hand side leaves the old owner alone. Checked after the
        // value lowered, because lowering it is what rewrites a hand-off of
        // another owner into the transfer that empties that owner's handle — and
        // a self-move has to be emptied BEFORE the old value is released.
        if (try self.lowerOwnerOverwrite(assignment, value)) |overwrite| {
            return .{ .expr_stmt = overwrite };
        }
        // DECISION — this package implements the Rust RELEASE profile, and
        // the choice is not derivable from Rust's grammar. Rust has two
        // overflow profiles and one spelling: under the default release
        // profile `overflow-checks` is off, so `a + b`, `a += b`, `-` and
        // `-=` all wrap; under debug all four panic. The binary path keys its
        // Zig operator off `BinaryExpr.overflow`, which `ts_ext.zig` fills in
        // as `.wrapping`, and `wrapping_add` and friends — which wrap under
        // BOTH profiles, so they pin the choice to release — reach the backend
        // as the same `.binary` node with the same `.wrapping`. Reading the
        // field here therefore agrees with `a + b` by construction.
        //
        // Round 2 clamped this to `.checked` on the strength of Rust having
        // no wrapping compound-assignment SPELLING (`t +%= x` does not parse).
        // That is true and irrelevant: the absence of a spelling is not the
        // absence of wrapping semantics, and the clamp left one Rust operation
        // with two behaviours — `255u8 + 1` wrapped to 0 while `x += 1` on the
        // same `u8` panicked — so the package matched neither profile.
        // Clamping the binary path instead is not available here either:
        // `ts_ext.zig` writes `.wrapping` on every `AssignExpr` and on every
        // `BinaryExpr`, so nothing in the IR distinguishes `a + b` from
        // `a.wrapping_add(b)` except the fact that only the former may be
        // re-clamped.
        const overflow = assignment.overflow;
        if (assignment.op != .plain and requiresRuntimeOperator(try self.exprType(assignment.target))) {
            const address: ast.Expr = .{ .unary_op = .{ .op = .addr_of, .operand = try self.allocExpr(target) } };
            return .{ .expr_stmt = try self.allocExpr(try self.lowerRuntimeOperator(
                "assign",
                @tagName(assignment.op),
                overflow,
                address,
                value,
            )) };
        }
        // `<<=` and `>>=` share the `u5` amount rule with the plain shifts, and
        // the runtime operator path above has already taken its own cast.
        const shift_value = if (assignment.op == .shl or assignment.op == .shr)
            try self.lowerShiftAmount(value)
        else
            value;
        // Zig spells the wrapping compound form for integers only — `f64 +%= f64`
        // does not compile — so a float target keeps the plain operator, the
        // same way `uses_float` keeps `a + b` on `.add`. Nothing else consults
        // `wraps`: `.saturating` is the one IR mode Zig cannot spell as a
        // compound assignment, `ts_ext.zig` never writes one onto an
        // `AssignExpr`, and the trapping operator is its safe fallback.
        const wraps = switch (assignment.op) {
            .add, .sub, .mul => overflow == .wrapping and
                !isFloatType(peelPointers(try self.exprType(assignment.target))),
            else => false,
        };
        const op: ast.AssignOp = switch (assignment.op) {
            .plain => .assign,
            .add => if (wraps) .add_assign_wrap else .add_assign,
            .sub => if (wraps) .sub_assign_wrap else .sub_assign,
            .mul => if (wraps) .mul_assign_wrap else .mul_assign,
            .div => .div_assign,
            .rem => .mod_assign,
            .bit_and => .bit_and_assign,
            .bit_or => .bit_or_assign,
            .bit_xor => .bit_xor_assign,
            .shl => .shl_assign,
            .shr => .shr_assign,
        };
        return .{ .assign = .{
            .target = target,
            .val = shift_value,
            .op = op,
        } };
    }

    // -------------------------------------------------------------------------
    // Statement Lowering
    // -------------------------------------------------------------------------

    pub fn lowerStmt(self: *Lowerer, stmt_id: ir.exprs.NodeId) anyerror!ast.Stmt {
        if (stmt_id >= self.ir.bodies.stmts.len) {
            return error.MissingStatementNode;
        }

        const ir_stmt = self.ir.bodies.stmts[stmt_id];

        return switch (ir_stmt.kind) {
            .let => |ls| blk: {
                if (ls.pattern >= self.ir.bodies.pats.len) return error.MissingPatternNode;
                const pat = self.ir.bodies.pats[ls.pattern];
                var tuple_field: ?[]const u8 = null;
                var pattern_target_id: ir.exprs.NodeId = ls.pattern;
                const binding = switch (pat.kind) {
                    .binding => |b| b,
                    .reference => |reference| blk_ref: {
                        if (reference.inner >= self.ir.bodies.pats.len) {
                            return error.MissingPatternNode;
                        }
                        pattern_target_id = reference.inner;
                        break :blk_ref switch (self.ir.bodies.pats[reference.inner].kind) {
                            .binding => |b| b,
                            else => return error.UnsupportedPattern,
                        };
                    },
                    .struct_pat => |struct_pat| blk_struct: {
                        if (struct_pat.fields.len != 1) return error.UnsupportedPattern;
                        const field = struct_pat.fields[0];
                        if (!std.mem.eql(u8, field.field, "0")) return error.UnsupportedPattern;
                        const inner = field.pat orelse return error.UnsupportedPattern;
                        if (inner >= self.ir.bodies.pats.len) return error.MissingPatternNode;
                        pattern_target_id = inner;
                        tuple_field = field.field;
                        break :blk_struct switch (self.ir.bodies.pats[inner].kind) {
                            .binding => |b| b,
                            else => return error.UnsupportedPattern,
                        };
                    },
                    // `let _ = EXPR;` binds nothing, but Rust still runs the
                    // initializer — that is where a macro's statement
                    // expression keeps its side effects. Zig spells the same
                    // discard `_ = EXPR;`, and a `void` or diverging
                    // initializer cannot be discarded at all, so it stays a
                    // bare statement, exactly as an expression statement
                    // does.
                    .wildcard => {
                        const discard_id = ls.init orelse return error.MissingInitializer;
                        const discarded = try self.lowerExpr(discard_id);
                        switch (discarded) {
                            .return_expr, .break_expr, .continue_expr, .unreachable_, .panic_ => {
                                break :blk ast.Stmt{ .expr_stmt = try self.allocExpr(discarded) };
                            },
                            else => {},
                        }
                        const produces_nothing = if (try self.exprType(discard_id)) |discarded_type|
                            discarded_type == .prim and
                                (discarded_type.prim == .unit or discarded_type.prim == .never)
                        else
                            false;
                        break :blk if (produces_nothing)
                            ast.Stmt{ .expr_stmt = try self.allocExpr(discarded) }
                        else
                            ast.Stmt{ .assign = .{
                                .target = .{ .ident = "_" },
                                .val = discarded,
                            } };
                    },
                    else => return error.UnsupportedPattern,
                };
                if (binding.name.len == 0) return error.MissingBindingName;
                const binding_name = if (self.current_local_binding_names) |names|
                    try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pattern_target_id, binding.name)
                else
                    binding.name;
                // `let PAT;` with no initializer is Rust's late
                // initialization: the binding is in scope from here and
                // definite assignment happens on some later path. Zig's typed
                // declaration over `undefined` is the same declaration — it
                // carries no value of its own, so it can neither read as one
                // nor stand in for one, and the source is what proved the read
                // comes after the write.
                //
                // `var` up front, because Rust lets an IMMUTABLE `let x;` be
                // assigned exactly once later and Zig's `const` rejects that.
                // `lowerBlock` walks the block it emitted and puts the binding
                // back to `const` when nothing reaches it, which is the same
                // rule every other binding already goes through.
                if (ls.init == null) {
                    // The annotation when the source wrote one, otherwise the
                    // type the producer recorded for the binding itself: there
                    // is no initializer expression here to read a type from,
                    // and Zig spells an unassigned slot against one.
                    const late_type_id = (ls.ty orelse
                        self.ir.bodies.pats[pattern_target_id].ty orelse
                        ir_stmt.ty) orelse
                        return error.UnsupportedLateBinding;
                    const late_type = try self.typeById(late_type_id);
                    // Rust drops what a binding owns when its scope ends, and
                    // this lowering releases that storage through the runtime's
                    // `deinit(allocator)`. Whether that release is correct
                    // depends on a fact Rust's own borrow checker computes and
                    // this pass cannot yet see: WHICH paths assign the binding.
                    // Releasing unconditionally frees storage nobody allocated
                    // on the paths that do not assign it; never releasing leaks
                    // the owner on the paths that do. Neither is a translation
                    // of what the source said, so a late-initialized container
                    // is refused here — BEFORE an undefined slot for it exists —
                    // rather than lowered into either. An arithmetic, boolean,
                    // pointer or blob type carries no allocation to get wrong,
                    // and the source's guarantee that every read follows a
                    // write is exactly what `undefined` means, so those lower.
                    if (ownedRuntimeContainerType(late_type)) {
                        return error.UnsupportedLateBinding;
                    }
                    break :blk ast.Stmt{ .let_stmt = .{
                        .name = try self.alloc.dupe(u8, binding_name),
                        .ty = try self.lowerType(late_type),
                        .init = .{ .lit = .undefined_lit },
                        .is_mut = true,
                    } };
                }
                const init_id = ls.init.?;
                const init_expr = if (tuple_field) |field| blk_field: {
                    const tuple_target = if (self.ir.bodies.exprs[init_id].kind == .unary and
                        self.ir.bodies.exprs[init_id].kind.unary.op == .deref)
                        try self.lowerExpr(self.ir.bodies.exprs[init_id].kind.unary.operand)
                    else
                        try self.lowerExpr(init_id);
                    const target = try self.allocExpr(tuple_target);
                    errdefer self.alloc.destroy(target);
                    const field_name = try self.alloc.dupe(u8, field);
                    errdefer self.alloc.free(field_name);
                    break :blk_field ast.Expr{ .field_access = .{
                        .target = target,
                        .field_name = field_name,
                    } };
                } else try self.lowerLetInitializer(init_id, if (ls.ty) |declared_id|
                    try self.typeById(declared_id)
                else
                    null);
                const binding_type = if (ls.ty orelse self.ir.bodies.exprs[init_id].ty) |t_id|
                    try self.typeById(t_id)
                else
                    null;
                // `let Name(binding) = value;` binds the NAME's OWN field, so
                // the field's slot is what the binding IS. `binding_type` above
                // is the type of the whole initializer, and for
                // `let FnvHasher(mut hash) = *self;` that is `FnvHasher`: the
                // single-field binding was then declared with the struct's own
                // type and emitted `var hash: root.FnvHasher = self.@"0";` over
                // a `u64` field, which Zig rejects at the initializer. The
                // initializer above already reads through `field`, so the
                // declared type has to answer the same slot.
                const binding_slot_type = if (binding_type) |container| slot: {
                    const field = tuple_field orelse break :slot container;
                    break :slot self.fieldSlotType(container, field) orelse container;
                } else null;
                const ty: ?ast.Type = if (binding_slot_type) |binding_ir_type|
                    try self.lowerType(binding_ir_type)
                else
                    null;
                // `r2z.alloc.String` reaches its mutating and consuming
                // methods through `self: *String`, so a binding that one of
                // them needs has to be `var` even where the source spelled it
                // immutable: `into_bytes` transfers the allocation out of the
                // string, and `const` storage rejects that with "cast
                // discards const qualifier". Aliasing the binding into a
                // fresh local would instead leave the original holding an
                // allocation already handed away. `lowerBlock` downgrades the
                // `var` again when nothing in the block reaches it.
                // A binding that OWNS runtime storage is mutable whether or not
                // the source wrote `mut`, because the scope's release runs on
                // this handle and `takeOwned` empties it in place on the paths
                // that hand the owner on. `const` storage rejects both with
                // "cast discards const qualifier", so a `String` worked only
                // because `into_bytes` happened to need a pointer; every other
                // owner needs one for the release itself. `lowerBlock` puts the
                // binding back to `const` when nothing in the block reaches it,
                // and `astMutatesBinding` counts the `defer` as a reach, so a
                // released owner stays `var` and nothing else does.
                // The same slot answers the ownership question: a field that
                // owns storage needs the `var` the scope release writes
                // through, and the AGGREGATE owning it is not a reason.
                const owned_string = binding_slot_type != null and
                    ownedRuntimeContainerType(binding_slot_type.?);

                break :blk ast.Stmt{
                    .let_stmt = .{
                        .name = try self.alloc.dupe(u8, binding_name),
                        .ty = ty,
                        .init = init_expr,
                        .is_mut = binding.mutable or owned_string,
                    },
                };
            },
            // `let PAT = EXPR else { .. }` only ever has a refutable pattern,
            // and none of those has the `ast.Stmt` form this branch could
            // build: the only patterns it accepts below are irrefutable, and
            // emitting one kept the binding and silently discarded
            // `else_block`, so a `let .. else { return }` would fall through
            // instead of diverging. Refuse until the else arm can be lowered.
            .let_else => |le| {
                _ = le;
                return error.UnsupportedStatement;
            },
            .expr => |e_id| blk: {
                if (e_id >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
                switch (self.ir.bodies.exprs[e_id].kind) {
                    .assign => |assignment| {
                        break :blk try self.lowerAssignmentStmt(assignment);
                    },
                    else => {
                        const lowered = try self.lowerExpr(e_id);
                        // `return`, `break`, `continue`, `unreachable` and
                        // `panic` are statements that happen to produce a
                        // type. Wrapping them in a discard is a syntax error.
                        switch (lowered) {
                            .return_expr, .break_expr, .continue_expr, .unreachable_, .panic_ => {
                                break :blk ast.Stmt{ .expr_stmt = try self.allocExpr(lowered) };
                            },
                            else => {},
                        }
                        if (try self.exprType(e_id)) |expression_type| {
                            if (expression_type != .prim or
                                (expression_type.prim != .unit and expression_type.prim != .never))
                            {
                                break :blk .{ .assign = .{
                                    .target = .{ .ident = "_" },
                                    .val = lowered,
                                } };
                            }
                        }
                        break :blk ast.Stmt{ .expr_stmt = try self.allocExpr(lowered) };
                    },
                }
            },
            .item => return error.UnsupportedStatement,
        };
    }
    fn temporaryOwnerInit(
        self: *Lowerer,
        producer: ast.Expr,
    ) !ast.Expr {
        if (producer == .unary_op and producer.unary_op.op == .try_op) {
            return producer;
        }
        return .{ .unary_op = .{
            .op = .try_op,
            .operand = try self.allocExpr(producer),
        } };
    }

    fn appendOwnedTemporaryPrelude(
        self: *Lowerer,
        plan: OwnedTemporaryPlan,
        producer: ast.Expr,
    ) !ast.Expr {
        const prelude = self.current_owner_prelude orelse return producer;
        const reserved = self.current_owner_reserved orelse return producer;
        try self.appendCollectorImportAliases(reserved);
        const owner_name = try self.collectorBindingName("owner", reserved.items);
        try reserved.append(self.alloc, owner_name);
        const owner_type = try self.lowerType(plan.return_type);
        const owner_init = try self.temporaryOwnerInit(producer);
        try prelude.append(self.alloc, .{ .let_stmt = .{
            .name = owner_name,
            .ty = owner_type,
            .init = owner_init,
            .is_mut = true,
        } });
        const owner_deinit = try self.allocExpr(.{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = owner_name }),
            .field_name = "deinit",
        } });
        try prelude.append(self.alloc, .{ .defer_stmt = .{
            .expr = .{ .call = .{
                .callee = owner_deinit,
                .args = &.{.{ .ident = "allocator" }},
            } },
            .is_errdefer = false,
        } });
        return .{ .field_access = .{
            .target = try self.allocExpr(.{ .ident = owner_name }),
            .field_name = "items",
        } };
    }

    fn lowerOwnedTemporaryArgument(
        self: *Lowerer,
        expr_id: ir.exprs.NodeId,
    ) !?ast.Expr {
        const expected_expr_id = self.expected_argument_expr_id orelse return null;
        if (expected_expr_id != expr_id) return null;
        const expected_type = self.expected_argument_type orelse return null;
        if (self.current_owner_prelude == null or self.current_owner_reserved == null) {
            return null;
        }
        const plan = (try self.matchOwnedTemporary(expr_id, expected_type)) orelse return null;
        const borrowed = switch (self.ir.bodies.exprs[expr_id].kind) {
            .unary => |unary| unary,
            else => return null,
        };
        const producer = try self.lowerExpr(borrowed.operand);
        const lowered = try self.appendOwnedTemporaryPrelude(plan, producer);
        return lowered;
    }

    // -------------------------------------------------------------------------
    // For-loop capture helpers
    // -------------------------------------------------------------------------

    /// Whether a loop pattern binds a POINTER to the item rather than the item.
    ///
    /// Rust's `&T` is a pointer only while `T` is SIZED. `&str` and `&[T]`
    /// borrow a fat pointer that already carries the element and the length,
    /// and `lowerType` spells each of them as the Zig slice it is — so the
    /// binding IS the item, and a `|*item|` capture would hand the body a
    /// pointer to the descriptor it meant to read (`formatter.writeAll(c)`
    /// with `c: *const []const u8`). A borrow of a sized pointee still lowers
    /// to a Zig pointer, and that capture is the one that is right.
    fn patternCapturesByReference(self: *const Lowerer, pat_id: ir.exprs.NodeId) !bool {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pattern = self.ir.bodies.pats[pat_id];
        if (pattern.kind != .binding) return false;
        if (pattern.kind.binding.mode != .value) return true;
        const type_id = pattern.ty orelse return false;
        const binding_type = try self.typeById(type_id);
        if (binding_type != .reference) return false;
        return !borrowLowersToFatValue(binding_type.reference.pointee);
    }

    /// The node a `for` input actually walks. `.iter()` and `.iter_mut()` are
    /// the iterator itself, and a Zig `for` walks the sequence underneath.
    fn forInputSource(self: *Lowerer, node: ir.exprs.NodeId) anyerror!ir.exprs.NodeId {
        if (node >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        if (self.ir.bodies.exprs[node].kind != .method_call) return node;
        const call = self.ir.bodies.exprs[node].kind.method_call;
        const method = self.ir.graph.symbol_table.get(call.method) orelse return error.MissingDefinition;
        if (std.mem.eql(u8, method.name, "iter") or std.mem.eql(u8, method.name, "iter_mut")) {
            if (try self.memoryElementType(call.receiver) != null) return call.receiver;
        }
        if (try self.forInputIntoOwnedSource(node)) |source| return source;
        return node;
    }
    fn forInputIntoOwnedSource(self: *Lowerer, node: ir.exprs.NodeId) anyerror!?ir.exprs.NodeId {
        if (node >= self.ir.bodies.exprs.len) return null;
        const call = switch (self.ir.bodies.exprs[node].kind) {
            .method_call => |value| value,
            else => return null,
        };
        if (call.args.len != 0 or call.generic_args.len != 0) return null;
        if (!self.canonicalIntoIteratorMethod(call.method)) return null;
        const receiver_ty = peelReceiverType(try self.exprType(call.receiver) orelse return null);
        if (isRuntimeIteratorCarrier(receiver_ty)) return null;
        if (try self.memoryElementType(call.receiver) != null) return call.receiver;
        if (needsContainerStorageProjection(receiver_ty)) return call.receiver;
        return null;
    }
    fn canonicalIntoIteratorMethod(self: *const Lowerer, method: ir.spine.EntityId) bool {
        const entity = self.ir.graph.symbol_table.get(method) orelse return false;
        if (!std.mem.eql(u8, entity.name, "into_iter")) return false;
        const owner_id = entity.parent orelse return false;
        if (owner_id >= self.ir.bodies.bodies.len) return false;
        return switch (self.ir.bodies.bodies[owner_id]) {
            .impl_ => |body| if (body.trait_path) |trait_path|
                ir.bodies.boundPathMatches(
                    &self.ir.graph,
                    owner_id,
                    trait_path,
                    &.{ "core", "iter", "IntoIterator" },
                )
            else
                false,
            .trait_ => blk: {
                if (!std.mem.eql(u8, self.ir.graph.symbol_table.get(owner_id).?.name, "IntoIterator")) {
                    break :blk false;
                }
                break :blk self.traitLivesInStdIter(owner_id);
            },
            else => false,
        };
    }

    fn traitLivesInStdIter(self: *const Lowerer, trait_id: ir.spine.EntityId) bool {
        var current: ir.spine.EntityId = trait_id;
        var module_entity: ir.spine.EntityId = trait_id;
        var found_module = false;
        var remaining: usize = self.ir.graph.symbol_table.entities.items.len;
        while (remaining != 0) : (remaining -= 1) {
            const entity = self.ir.graph.symbol_table.get(current) orelse break;
            if (entity.kind == .module) {
                module_entity = current;
                found_module = true;
                break;
            }
            current = entity.parent orelse break;
        }
        if (!found_module) return false;
        const iter_module = self.ir.graph.moduleForEntity(module_entity) orelse return false;
        if (!iter_module.is_extern) return false;
        if (!std.mem.eql(u8, iter_module.name, "iter")) return false;
        const root_id = iter_module.parent orelse return false;
        const root = self.ir.graph.moduleForEntity(root_id) orelse return false;
        if (!root.is_extern) return false;
        return std.mem.eql(u8, root.name, "core") or std.mem.eql(u8, root.name, "std");
    }
    fn forInputUnverifiedOwnedAccessor(self: *Lowerer, source: ir.exprs.NodeId) anyerror!bool {
        const call = switch (self.ir.bodies.exprs[source].kind) {
            .method_call => |value| value,
            else => return false,
        };
        if (try self.forInputIntoOwnedSource(source) != null) return false;
        if (call.args.len != 0 or call.generic_args.len != 0) return false;
        const receiver_ty = peelReceiverType(try self.exprType(call.receiver) orelse return false);
        if (ownedRuntimeContainerType(receiver_ty)) return true;
        if (try self.memoryElementType(call.receiver)) |element| {
            return ownedRuntimeContainerType(element);
        }
        return false;
    }

    fn lowerForInput(self: *Lowerer, node: ir.exprs.NodeId, by_ref: bool) anyerror!ast.Expr {
        return self.lowerForSequence(try self.forInputSource(node), null, by_ref);
    }

    fn lowerForSequence(
        self: *Lowerer,
        source: ir.exprs.NodeId,
        base: ?ast.Expr,
        by_ref: bool,
    ) anyerror!ast.Expr {
        var value = try self.allocExpr(if (base) |given| given else switch (self.ir.bodies.exprs[source].kind) {
            .range => |range| try self.lowerRangeSliceExpr(range, false),
            else => try self.lowerExpr(source),
        });
        value = try self.lowerMemoryReceiver(source, value);
        value = try self.projectForSequence(source, value);
        if (!by_ref) return value.*;
        if (self.receiverIsArray(source)) return (try self.lowerAsRef(source, value)).*;
        if (!self.receiverIsSlice(source)) return (try self.lowerAsRef(source, value)).*;
        const zero = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
        const open = try self.allocExpr(ast.Expr{ .range = .{ .start = zero, .end = null } });
        const index_args = try self.alloc.alloc(ast.Expr, 2);
        index_args[0] = value.*;
        index_args[1] = open.*;
        return (try self.allocExpr(ast.Expr{ .builtin = .{
            .name = "index",
            .args = index_args,
        } })).*;
    }

    fn projectForSequence(
        self: *Lowerer,
        source: ir.exprs.NodeId,
        value: *const ast.Expr,
    ) anyerror!*const ast.Expr {
        const source_ty = try self.exprType(source);
        if (!needsContainerStorageProjection(source_ty)) return value;
        return self.allocExpr(.{ .field_access = .{
            .target = try self.allocExpr(value.*),
            .field_name = "items",
        } });
    }

    /// A `for x in a..b` driven by the typed iterator loop instead of a Zig
    /// `for`.
    const TypedRangeFor = struct {
        range: LoweredIteratorRange,
        /// The name the loop body binds each value to, or null when the
        /// pattern is a wildcard and the source named nothing.
        item_name: ?[]const u8,
    };

    /// The integer type a range endpoint really has, or null when the source
    /// left it open.
    ///
    /// This is `iteratorRangeEndpointType` without the refusal: a `for` whose
    /// endpoints are not a matched pair of integers keeps the `usize` binding
    /// a Zig `for` gives it rather than failing the whole callable.
    fn iteratorRangeEndpointTypeOrNull(
        self: *Lowerer,
        node: ir.exprs.NodeId,
    ) ?ir.types.Type {
        if (node >= self.ir.bodies.exprs.len) return null;
        const known = self.concreteExprType(node) orelse
            (self.exprType(node) catch return null) orelse return null;
        return integerOperandType(known);
    }

    /// Whether this loop pattern names exactly one value, which is what a
    /// cursor step can hand the body.
    fn patternNamesOneValue(self: *const Lowerer, pat_id: ir.exprs.NodeId) bool {
        if (pat_id >= self.ir.bodies.pats.len) return false;
        return switch (self.ir.bodies.pats[pat_id].kind) {
            .binding, .reference, .wildcard => true,
            else => false,
        };
    }

    /// The element type `for x in a..b` really binds.
    ///
    /// The RANGE's own type is the authority when it carries one: `Range<i64>`
    /// says the loop yields `i64` whatever the two endpoints happen to be
    /// typed as, and `Range<usize>` says the Zig `for`'s own `usize` binding
    /// is already the one the source wrote. A range the frontend left
    /// untyped falls back to its endpoints, which answer only when they
    /// AGREE — two endpoints inference never reconciled are not one type, and
    /// inventing one would be a type the source never wrote.
    fn rangeLoopElementType(self: *Lowerer, range_id: ir.exprs.NodeId) ?ir.types.Type {
        if (self.concreteExprType(range_id)) |declared| {
            if (rangeNominalElement(declared)) |element| {
                return integerOperandType(element);
            }
        }
        const range = switch (self.ir.bodies.exprs[range_id].kind) {
            .range => |value| value,
            else => return null,
        };
        const end_node = range.end orelse return null;
        const start_type = self.iteratorRangeEndpointTypeOrNull(range.start) orelse return null;
        const end_type = self.iteratorRangeEndpointTypeOrNull(end_node) orelse return null;
        if (!typeEquals(start_type, end_type)) return null;
        return start_type;
    }

    /// The element type a `Range<T>` nominal names, or null when this is not
    /// one.
    fn rangeNominalElement(ty: ir.types.Type) ?ir.types.Type {
        const external = switch (ty) {
            .external_nominal => |value| value,
            else => return null,
        };
        if (external.args.len != 1) return null;
        const path = external.path;
        if (path.len != 3) return null;
        if (!std.mem.eql(u8, path[0], "core") and !std.mem.eql(u8, path[0], "std")) return null;
        if (!std.mem.eql(u8, path[1], "ops")) return null;
        if (!std.mem.eql(u8, path[2], "Range")) return null;
        return external.args[0];
    }

    /// Whether a Zig `for` over this range would bind the wrong value.
    ///
    /// A Zig `for` over a range binds `usize` whatever the range's element
    /// type says, so two ranges cannot use it. A SIGNED one arrives as a
    /// wrapped `usize` — `-513..513` starts at `usize` minus 513 and never
    /// reaches zero. An INCLUSIVE one has to be spelled `end + 1` in the `for`
    /// form, and at the element type's own maximum that sum is not a value the
    /// type can hold: `254u8..=255u8` would ask a `u8` for 256.
    ///
    /// Every other range — `0..127` as a `u8`, `0..n` as a `usize` — is a real
    /// counter the `for` already carries, and it keeps its shape.
    fn rangeForNeedsTypedLoop(element_type: ir.types.Type, inclusive: bool) bool {
        if (inclusive) return true;
        const primitive = switch (element_type) {
            .prim => |value| value,
            else => return false,
        };
        return isSignedPrimitive(primitive);
    }

    /// Plan the typed iterator loop for `for x in a..b`, or null when this
    /// loop is not one.
    ///
    /// The typed loop binds what the source wrote, which is the only shape
    /// that can carry a signed counter or an inclusive endpoint. It also
    /// stops AT the endpoint rather than past it, which is what keeps the
    /// inclusive maximum intact.
    fn planTypedRangeFor(self: *Lowerer, fe: ir.exprs.ForExpr) anyerror!?TypedRangeFor {
        if (fe.iterable >= self.ir.bodies.exprs.len) return null;
        const range = switch (self.ir.bodies.exprs[fe.iterable].kind) {
            .range => |value| value,
            else => return null,
        };
        const end_node = range.end orelse return null;
        if (fe.pattern >= self.ir.bodies.pats.len) return null;
        if (!self.patternNamesOneValue(fe.pattern)) return null;
        if (try self.patternCapturesByReference(fe.pattern)) return null;
        const element_type = self.rangeLoopElementType(fe.iterable) orelse return null;
        if (!rangeForNeedsTypedLoop(element_type, range.inclusive)) return null;
        const item_name = if (self.ir.bodies.pats[fe.pattern].kind == .wildcard)
            null
        else
            try self.patternName(fe.pattern);
        return .{
            .range = .{
                .start = try self.lowerExpr(range.start),
                .end = try self.lowerExpr(end_node),
                .item_type = try self.lowerType(element_type),
                .inclusive = range.inclusive,
            },
            .item_name = item_name,
        };
    }

    /// The typed iterator loop a planned `for x in a..b` becomes.
    ///
    /// The shared setup binds both endpoints to temporaries, so an end that is
    /// a call is evaluated once however many steps the loop takes, and the
    /// loop's own label rides on the generated `while`: a `break` or a
    /// `continue` in the body reaches THIS loop, the way it reached the `for`
    /// the source wrote.
    fn lowerTypedRangeFor(
        self: *Lowerer,
        plan: TypedRangeFor,
        body: ast.Block,
        label: ?[]const u8,
    ) anyerror!ast.Expr {
        var statements: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer statements.deinit(self.alloc);
        const range_loop = try self.appendIteratorRangeSetup(plan.range, .forward, &statements);
        var inner: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer inner.deinit(self.alloc);
        // The cursor already has the range's own element type, so the body's
        // binding is a plain read of it — nothing is cast to get here.
        if (plan.item_name) |name| {
            try inner.append(self.alloc, .{ .let_stmt = .{
                .name = name,
                .init = range_loop.item,
                .is_mut = false,
            } });
        }
        try inner.appendSlice(self.alloc, body.stmts);
        if (body.expr) |tail| try inner.append(self.alloc, .{ .expr_stmt = tail });
        try self.appendIteratorRangeLoop(range_loop, inner.items, &statements, label);
        return .{ .block = .{ .stmts = try statements.toOwnedSlice(self.alloc) } };
    }

    /// Give a `for x in a..b` binding the range's own element type.
    ///
    /// A Zig `for` over a range yields `usize`, so `for (0u8..2) |x|` binds a
    /// `usize` and every use of `x` against the `u8` the source wrote is a
    /// type error. The index the loop really produces is taken back to the
    /// element type as the first statement of the body, which is where a
    /// pattern's own binding prelude already goes.
    ///
    /// A `usize` range is left alone: its binding already has the type the
    /// loop produces, and the extra statement would cast a value to itself.
    fn retypeRangeLoopBinding(
        self: *Lowerer,
        fe: ir.exprs.ForExpr,
        captures: *std.ArrayListUnmanaged(ast.Capture),
        prelude: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!void {
        if (fe.iterable >= self.ir.bodies.exprs.len) return;
        if (captures.items.len != 1) return;
        if (captures.items[0].by_ref) return;
        if (try self.patternCapturesByReference(fe.pattern)) return;
        const range = switch (self.ir.bodies.exprs[fe.iterable].kind) {
            .range => |value| value,
            else => return,
        };
        if (range.start >= self.ir.bodies.exprs.len) return;
        const item_type = (try self.exprType(range.start)) orelse return;
        if (typeEquals(item_type, .{ .prim = .usize })) return;
        const index_name = try self.iteratorTemporaryName("__r2z_range_index");
        const binding_name = captures.items[0].name;
        captures.items[0].name = index_name;
        const cast_args = try self.alloc.alloc(ast.Expr, 1);
        cast_args[0] = (try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, index_name) })).*;
        try prelude.append(self.alloc, .{ .let_stmt = .{
            .name = try self.alloc.dupe(u8, binding_name),
            .ty = try self.lowerType(item_type),
            .init = (try self.allocExpr(.{ .builtin = .{
                .name = "intCast",
                .args = cast_args,
            } })).*,
        } });
    }

    fn valueCaptureName(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!?[]const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        if (try self.patternCapturesByReference(pat_id)) return null;
        const binding = switch (self.ir.bodies.pats[pat_id].kind) {
            .binding => |value| value,
            else => return null,
        };
        switch (binding.mode) {
            .value => {},
            else => return null,
        }

        if (binding.name.len == 0) return error.MissingBindingName;
        const binding_name = if (self.current_local_binding_names) |names|
            try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, binding.name)
        else
            binding.name;
        const name = try self.alloc.dupe(u8, binding_name);
        return name;
    }
    fn shouldElideValueCaptureDeref(
        self: *const Lowerer,
        operand_id: ir.exprs.NodeId,
    ) bool {
        if (operand_id >= self.ir.bodies.exprs.len) return false;
        const path = switch (self.ir.bodies.exprs[operand_id].kind) {
            .path => |value| value,
            else => return false,
        };
        if (path.generic_args.len != 0) return false;
        const entity = self.ir.graph.symbol_table.get(path.def) orelse return false;
        const path_name = if (self.current_local_binding_names) |names|
            names.emitted_by_entity.get(path.def) orelse entity.renamed_to orelse entity.name
        else
            entity.renamed_to orelse entity.name;
        var shadow_scope = self.current_shadow_scope;
        while (shadow_scope) |scope| {
            for (scope.names) |shadow_name| {
                if (std.mem.eql(u8, path_name, shadow_name)) return false;
            }
            shadow_scope = scope.parent;
        }

        var scope_index = self.current_value_capture_scopes.len;
        while (scope_index > 0) {
            scope_index -= 1;
            const scope = self.current_value_capture_scopes[scope_index];
            for (scope.names) |capture_name| {
                if (!std.mem.eql(u8, path_name, capture_name)) continue;
                const value_name = scope.value_name orelse return false;
                return std.mem.eql(u8, path_name, value_name);
            }
        }
        return false;
    }

    /// The Zig capture identifier for a pattern: a binding's name, `_` for a
    /// wildcard, the inner pattern's name for a reference.
    fn patternName(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror![]const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pat = self.ir.bodies.pats[pat_id];
        return switch (pat.kind) {
            .binding => |b| blk: {
                if (b.name.len == 0) return error.MissingBindingName;
                const binding_name = if (self.current_local_binding_names) |names|
                    try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, b.name)
                else
                    b.name;
                break :blk try self.alloc.dupe(u8, binding_name);
            },
            .reference => |r| self.patternName(r.inner),
            .wildcard => try self.alloc.dupe(u8, "_"),
            else => return error.UnsupportedPattern,
        };
    }

    /// The base name for the temporary that carries a closure parameter's
    /// payload.
    ///
    /// A closure parameter is usually a binding or a wildcard, which
    /// `patternName` names directly. A tuple destructuring names no single
    /// value — `|(i, pair)|` binds two — so the temporary is named after the
    /// shape and `appendIteratorClosureBindings` destructures it in place,
    /// exactly as it does for an iterator-chain source. Every other shape still
    /// goes through `patternName` and keeps its existing name and claim.
    fn closurePayloadName(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror![]const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        switch (self.ir.bodies.pats[pat_id].kind) {
            .tuple => return "tuple",
            else => return self.patternName(pat_id),
        }
    }

    const ForInputDrain = enum {
        untouched,
        owner_place,
        moved_place,
        carried,
    };

    fn forInputIsFreshValue(self: *const Lowerer, node: ir.exprs.NodeId) bool {
        if (node >= self.ir.bodies.exprs.len) return false;
        return switch (self.ir.bodies.exprs[node].kind) {
            .path, .field, .index, .unary => false,
            .cast => |cast| self.forInputIsFreshValue(cast.operand),
            .call, .core_call, .method_call, .struct_lit, .array, .vec_lit, .external_variant, .enum_variant, .block, .match, .if_else, .if_let, .try_ => true,
            else => false,
        };
    }

    fn forInputDrain(
        self: *Lowerer,
        mid: ir.exprs.NodeId,
        element: ir.exprs.NodeId,
        by_ref: bool,
    ) anyerror!ForInputDrain {
        if (by_ref) return .untouched;
        const source = try self.forInputSource(mid);
        const input_ty = try self.exprType(source) orelse return error.UnsupportedExpression;
        _ = element;
        const element_owns = if (try self.forInputElementType(source)) |element_ty|
            ownedRuntimeContainerType(element_ty)
        else
            false;
        if (try self.forInputUnverifiedOwnedAccessor(source)) return error.UnsupportedExpression;
        if (!element_owns and !ownedRuntimeContainerType(input_ty)) return .untouched;
        if (try self.inputBaseIsOwnerEntity(source)) return .owner_place;
        if (try self.placePeelsToOwnerBinding(source)) return .moved_place;
        if (self.forInputIsFreshValue(source)) return .carried;
        return error.UnsupportedExpression;
    }
    fn forInputSequenceView(
        self: *Lowerer,
        input_ty: ir.types.Type,
        base: *const ast.Expr,
    ) anyerror!ast.Expr {
        if (needsContainerStorageProjection(input_ty)) {
            return (try self.allocExpr(.{ .field_access = .{
                .target = try self.allocExpr(base.*),
                .field_name = "items",
            } })).*;
        }
        switch (input_ty) {
            .array => {},
            .slice => return (try self.allocExpr(base.*)).*,
            else => return error.UnsupportedExpression,
        }
        const zero = try self.allocExpr(ast.Expr{ .lit = .{ .int = 0 } });
        const open = try self.allocExpr(ast.Expr{ .range = .{ .start = zero, .end = null } });
        const index_args = try self.alloc.alloc(ast.Expr, 2);
        index_args[0] = base.*;
        index_args[1] = open.*;
        return (try self.allocExpr(ast.Expr{ .builtin = .{
            .name = "index",
            .args = index_args,
        } })).*;
    }

    fn lowerDrainedLoopInput(
        self: *Lowerer,
        mid: ir.exprs.NodeId,
        element: ir.exprs.NodeId,
        drain: ForInputDrain,
        by_ref: bool,
        hoist: *std.ArrayListUnmanaged(ast.Stmt),
    ) anyerror!ast.Expr {
        _ = element;
        const source = try self.forInputSource(mid);
        switch (drain) {
            .untouched => return self.lowerForInput(mid, by_ref),
            .owner_place => {
                const handle = self.scopeOwnerHandleForPath(source) orelse
                    return error.MissingLoopOwnerHandle;
                return self.lowerForSequence(
                    source,
                    .{ .ident = try self.alloc.dupe(u8, handle) },
                    true,
                );
            },
            .moved_place, .carried => {
                const input_ty = try self.exprType(source) orelse return error.UnsupportedExpression;
                try self.destructureStorageArmable(input_ty);
                const name = try self.iteratorTemporaryName("__r2z_for_input");
                const carrier_init = if (drain == .moved_place)
                    try self.ownedTransferPlaceCall(try self.lowerExpr(source), input_ty)
                else
                    try self.lowerExpr(source);

                try hoist.append(self.alloc, .{ .let_stmt = .{
                    .name = try self.alloc.dupe(u8, name),
                    .init = carrier_init,
                    .is_mut = true,
                } });
                try self.markRuntimeImport();
                try hoist.append(
                    self.alloc,
                    try self.ownerReleaseStatement(name, ownerReleasesElements(input_ty)),
                );
                const ident = try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) });
                return self.forInputSequenceView(input_ty, ident);
            },
        }
    }
    fn inputBindingIsOwnerEntity(self: *Lowerer, def: ir.spine.EntityId) anyerror!bool {
        const entity = self.ir.graph.symbol_table.get(def) orelse return false;
        if (entity.kind != .field) return false;
        const owner = entity.parent orelse return false;
        if (owner >= self.ir.bodies.bodies.len or self.ir.bodies.bodies[owner] != .fn_) return false;
        const binding_type = try self.valueEntityType(def) orelse return false;
        return ownedRuntimeContainerType(binding_type);
    }

    fn inputBaseIsOwnerEntity(self: *Lowerer, node: ir.exprs.NodeId) anyerror!bool {
        if (node >= self.ir.bodies.exprs.len) return false;
        const path = switch (self.ir.bodies.exprs[node].kind) {
            .path => |value| value,
            else => return false,
        };
        const entity = self.ir.graph.symbol_table.get(path.def) orelse return false;
        if (entity.kind != .field) return false;
        const owner = entity.parent orelse return false;
        if (owner >= self.ir.bodies.bodies.len or self.ir.bodies.bodies[owner] != .fn_) return false;
        const source_type = try self.exprType(node) orelse return false;
        return ownedRuntimeContainerType(source_type);
    }

    fn placePeelsToOwnerBinding(self: *Lowerer, node: ir.exprs.NodeId) anyerror!bool {
        var current = node;
        while (current < self.ir.bodies.exprs.len) {
            switch (self.ir.bodies.exprs[current].kind) {
                .field => |field| current = field.base,
                .index => |index| current = index.base,
                .unary => |unary| switch (unary.op) {
                    .deref, .ref => current = unary.operand,
                    else => return false,
                },
                .path => |path| return self.inputBindingIsOwnerEntity(path.def),
                else => return false,
            }
        }
        return false;
    }

    /// Whether a place peels to a read of `alias`'s own binding.
    ///
    /// The peel is the one `placePeelsToOwnerBinding` walks, and the identity
    /// is the one the `.path` case of `scanOwnedCaptureExpr` compares: the
    /// SOURCE NAME, because that is what the scan recognises a payload by. An
    /// element read reaches its carrier through the same projections a field
    /// read does, so both are asked the same question.
    fn placePeelsToAlias(self: *Lowerer, node: ir.exprs.NodeId, alias: OwnedCaptureAlias) bool {
        var current = node;
        while (current < self.ir.bodies.exprs.len) {
            switch (self.ir.bodies.exprs[current].kind) {
                .field => |field| current = field.base,
                .index => |index| current = index.base,
                .unary => |unary| switch (unary.op) {
                    .deref, .ref => current = unary.operand,
                    else => return false,
                },
                .path => |path| {
                    if (path.generic_args.len != 0) return false;
                    const entity = self.ir.graph.symbol_table.get(path.def) orelse return false;
                    return std.mem.eql(u8, entity.name, alias.source_name);
                },
                else => return false,
            }
        }
        return false;
    }

    fn appendLoopCapture(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        source_type: ?ir.types.Type,
        drain: ForInputDrain,
        by_ref: bool,
        captures: *std.ArrayListUnmanaged(ast.Capture),
        destructure: *std.ArrayListUnmanaged(ast.Stmt),
        claims: *ClaimCollector,
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pat = self.ir.bodies.pats[pat_id];
        switch (pat.kind) {
            .binding => |b| {
                if (b.name.len == 0) return error.MissingBindingName;
                const binding_name = if (self.current_local_binding_names) |names|
                    try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, b.name)
                else
                    b.name;
                const payload_type: ?ir.types.Type = if (drain != .untouched and b.mode == .value) blk: {
                    const candidate = source_type orelse return error.MissingExpressionType;
                    if (!try self.destructureFieldOwnsStorage(candidate)) break :blk null;
                    break :blk candidate;
                } else null;
                if (payload_type == null) {
                    const name = try self.alloc.dupe(u8, binding_name);
                    errdefer self.alloc.free(name);
                    try captures.append(self.alloc, .{
                        .name = name,
                        .by_ref = by_ref or b.mode != .value,
                    });
                    return;
                }
                if (try self.destructureClaimDef(pat_id) == null) return error.MissingDefinition;
                const pointer_name = try self.iteratorTemporaryName(
                    try std.fmt.allocPrint(self.alloc, "__r2z_ptr_{s}", .{binding_name}),
                );
                try captures.append(self.alloc, .{ .name = pointer_name, .by_ref = true });
                try self.emitDestructureBinding(
                    pat_id,
                    b,
                    binding_name,
                    .{ .unary_op = .{ .op = .deref, .operand = try self.allocExpr(.{ .ident = pointer_name }) } },
                    payload_type.?,
                    destructure,
                    &.{ .claims = claims, .drains_carrier = true, .source_type = source_type },
                );
            },
            // The sequence's element type is already the referent of the
            // reference yielded by `.iter()`. `&av` consumes that item borrow,
            // so its value binding captures the element, not its address.
            // Keep an explicit inner `ref` binding as a borrow of that slot;
            // do not infer another address merely because the element itself
            // has a reference type.
            .reference => |r| try self.appendLoopCapture(
                r.inner,
                source_type,
                drain,
                false,
                captures,
                destructure,
                claims,
            ),
            .wildcard => try captures.append(self.alloc, .{ .name = "_" }),
            .tuple => |tp| {
                const tmp = try self.iteratorTemporaryName("__r2z_tuple_capture");
                if (drain != .untouched) try self.requireDestructureClaimDefs(tp, &.{ .claims = claims, .drains_carrier = true, .source_type = source_type });
                const base = if (drain == .untouched and !by_ref)
                    try self.allocExpr(ast.Expr{ .ident = tmp })
                else
                    try self.allocExpr(.{ .unary_op = .{
                        .op = .deref,
                        .operand = try self.allocExpr(ast.Expr{ .ident = tmp }),
                    } });
                try captures.append(self.alloc, .{
                    .name = tmp,
                    .by_ref = drain != .untouched or by_ref,
                });
                try self.emitTupleDestructure(tp, base, destructure, &.{
                    .claims = claims,
                    .drains_carrier = drain != .untouched,
                    .source_type = source_type,
                });
            },
            else => return error.UnsupportedPattern,
        }
    }

    const DestructureOwnerClaim = struct {
        def: ir.spine.EntityId,
        alias: OwnedCaptureAlias,
    };

    const ClaimCollector = std.ArrayListUnmanaged(DestructureOwnerClaim);

    const TupleDestructureCtx = struct {
        claims: *ClaimCollector,
        drains_carrier: bool = false,
        source_type: ?ir.types.Type = null,
    };

    fn destructureFieldOwnsStorage(self: *Lowerer, ty: ir.types.Type) anyerror!bool {
        if (ownedMoveHasUnsupportedGenericArray(ty, 0))
            return error.UnsupportedOwnedGenericArrayRepresentation;
        if (try self.ownedTaggedPayloadAt(ty, 0, false))
            return error.UnsupportedOwnedTaggedPayload;
        return ownedRuntimeContainerType(ty);
    }

    fn destructureStorageArmable(self: *Lowerer, ty: ir.types.Type) anyerror!void {
        _ = try self.destructureFieldOwnsStorage(ty);
    }

    fn destructureAggregateFields(ty: ?ir.types.Type) ?[]const ir.types.Type {
        const aggregate = ty orelse return null;
        return switch (aggregate) {
            .tuple => |fields| fields,
            else => null,
        };
    }

    fn tuplePatternBindsReference(self: *Lowerer, tp: ir.exprs.TuplePat) bool {
        for (tp.elements) |el| {
            if (el >= self.ir.bodies.pats.len) return false;
            switch (self.ir.bodies.pats[el].kind) {
                .reference => return true,
                .tuple => |sub| {
                    if (self.tuplePatternBindsReference(sub)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn tuplePatternBindsMutRef(self: *Lowerer, tp: ir.exprs.TuplePat) bool {
        for (tp.elements) |el| {
            if (el >= self.ir.bodies.pats.len) return false;
            switch (self.ir.bodies.pats[el].kind) {
                .binding => |binding| if (binding.mode == .mut_ref) return true,
                .tuple => |sub| {
                    if (self.tuplePatternBindsMutRef(sub)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn destructureClaimDef(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!?ir.spine.EntityId {
        const names = self.current_local_binding_names orelse return null;
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const binding = switch (self.ir.bodies.pats[pat_id].kind) {
            .binding => |value| value,
            else => return null,
        };
        _ = try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, binding.name);
        return names.def_by_pattern.get(pat_id);
    }

    fn destructureElementOwner(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        element_type: ?ir.types.Type,
        ctx: *const TupleDestructureCtx,
    ) anyerror!?ir.types.Type {
        if (!ctx.drains_carrier) return null;
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pat = self.ir.bodies.pats[pat_id];
        if (pat.kind != .binding) return null;
        if (pat.kind.binding.mode != .value) return null;
        const slot_type = element_type orelse blk: {
            const type_id = pat.ty orelse return null;
            break :blk try self.typeById(type_id);
        };
        if (!try self.destructureFieldOwnsStorage(slot_type)) return null;
        return slot_type;
    }

    fn emitDestructureBinding(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        binding: ir.exprs.Binding,
        binding_name: []const u8,
        access: ast.Expr,
        element_type: ?ir.types.Type,
        destructure: *std.ArrayListUnmanaged(ast.Stmt),
        ctx: *const TupleDestructureCtx,
    ) anyerror!void {
        const claim_def = if (ctx.drains_carrier)
            try self.destructureClaimDef(pat_id)
        else
            null;
        const owner_type = if (claim_def != null)
            try self.destructureElementOwner(pat_id, element_type, ctx)
        else
            null;
        var binding_init = access;
        if (owner_type) |payload_type| {
            binding_init = try self.ownedTransferPlaceCall(access, payload_type);
        }
        try destructure.append(self.alloc, ast.Stmt{
            .let_stmt = .{
                .name = try self.alloc.dupe(u8, binding_name),
                .init = binding_init,
                .is_mut = binding.mutable or owner_type != null,
            },
        });
        const payload_type = owner_type orelse return;
        try destructure.append(
            self.alloc,
            try self.ownerReleaseStatement(binding_name, ownerReleasesElements(payload_type)),
        );
        try ctx.claims.append(self.alloc, .{
            .def = claim_def.?,
            .alias = .{
                .source_name = binding.name,
                .capture_name = binding_name,
                .alias_name = binding_name,
                .payload_type = payload_type,
            },
        });
    }
    fn destructureSourceType(
        self: *Lowerer,
        pattern_id: ir.exprs.NodeId,
        init_id: ir.exprs.NodeId,
    ) anyerror!?ir.types.Type {
        if (try self.exprType(init_id)) |ty| return ty;
        const type_id = self.ir.bodies.pats[pattern_id].ty orelse return null;
        return try self.typeById(type_id);
    }

    fn borrowElementInit(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        element_type: ?ir.types.Type,
        base: *const ast.Expr,
        index: usize,
    ) anyerror!ast.Expr {
        const slot = (try self.indexExpr(base, index)).*;
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pattern = self.ir.bodies.pats[pat_id];
        switch (pattern.kind) {
            .binding => |binding| switch (binding.mode) {
                .shared_ref, .mut_ref => return .{ .unary_op = .{
                    .op = .addr_of,
                    .operand = try self.allocExpr(slot),
                } },
                .value => return slot,
            },
            .reference => {
                const slot_type = element_type orelse return error.UnsupportedPattern;
                const pointee = switch (slot_type) {
                    .reference => |reference| reference.pointee,
                    .raw_ptr => |raw| raw.pointee,
                    else => return error.UnsupportedPattern,
                };
                if (borrowLowersToFatValue(pointee)) return error.UnsupportedPattern;
                return .{ .unary_op = .{
                    .op = .deref,
                    .operand = try self.allocExpr(slot),
                } };
            },
            else => return error.UnsupportedPattern,
        }
    }
    fn requireDestructureClaimDefs(
        self: *Lowerer,
        tp: ir.exprs.TuplePat,
        ctx: *const TupleDestructureCtx,
    ) anyerror!void {
        const fields = destructureAggregateFields(ctx.source_type);
        for (tp.elements, 0..) |el, i| {
            if (el >= self.ir.bodies.pats.len) return error.MissingPatternNode;
            const element_type: ?ir.types.Type = if (fields) |f|
                if (i < f.len) f[i] else null
            else
                null;
            switch (self.ir.bodies.pats[el].kind) {
                .binding => {},
                .reference => continue,
                .tuple => |sub| try self.requireDestructureClaimDefs(sub, &.{
                    .claims = ctx.claims,
                    .drains_carrier = ctx.drains_carrier,
                    .source_type = element_type,
                }),
                else => continue,
            }
            const owner_type = try self.destructureElementOwner(el, element_type, ctx);
            if (owner_type == null) continue;
            if (try self.destructureClaimDef(el) == null) return error.MissingDefinition;
        }
    }
    fn emitTupleDestructure(
        self: *Lowerer,
        tp: ir.exprs.TuplePat,
        base: *const ast.Expr,
        destructure: *std.ArrayListUnmanaged(ast.Stmt),
        ctx: *const TupleDestructureCtx,
    ) anyerror!void {
        const fields = destructureAggregateFields(ctx.source_type);
        for (tp.elements, 0..) |el, i| {
            if (el >= self.ir.bodies.pats.len) return error.MissingPatternNode;
            const el_pat = self.ir.bodies.pats[el];
            const element_type: ?ir.types.Type = if (fields) |f|
                if (i < f.len) f[i] else null
            else
                null;
            switch (el_pat.kind) {
                .binding => |b| {
                    if (b.name.len == 0) return error.MissingBindingName;
                    const binding_name = if (self.current_local_binding_names) |names|
                        try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, el, b.name)
                    else
                        b.name;
                    if (b.mode != .value) {
                        try destructure.append(self.alloc, ast.Stmt{
                            .let_stmt = .{
                                .name = try self.alloc.dupe(u8, binding_name),
                                .init = try self.borrowElementInit(el, element_type, base, i),
                                .is_mut = b.mutable,
                            },
                        });
                        continue;
                    }
                    try self.emitDestructureBinding(
                        el,
                        b,
                        binding_name,
                        (try self.indexExpr(base, i)).*,
                        element_type,
                        destructure,
                        ctx,
                    );
                },
                .reference => |r| {
                    if (r.inner >= self.ir.bodies.pats.len) return error.MissingPatternNode;
                    const rp = self.ir.bodies.pats[r.inner];
                    if (rp.kind != .binding) return error.UnsupportedPattern;
                    const rb = rp.kind.binding;
                    if (rb.name.len == 0) return error.MissingBindingName;
                    const binding_name = if (self.current_local_binding_names) |names|
                        try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, r.inner, rb.name)
                    else
                        rb.name;
                    try destructure.append(self.alloc, ast.Stmt{
                        .let_stmt = .{
                            .name = try self.alloc.dupe(u8, binding_name),
                            .init = try self.borrowElementInit(el, element_type, base, i),
                            .is_mut = rb.mutable,
                        },
                    });
                },
                .wildcard => {},
                .tuple => |sub| try self.emitTupleDestructure(
                    sub,
                    try self.indexExpr(base, i),
                    destructure,
                    &.{
                        .claims = ctx.claims,
                        .drains_carrier = ctx.drains_carrier,
                        .source_type = element_type,
                    },
                ),
                else => return error.UnsupportedPattern,
            }
        }
    }
    fn installDestructureOwnerMoves(
        self: *Lowerer,
        claims: []const DestructureOwnerClaim,
        body: ir.exprs.BlockExpr,
        from: usize,
    ) anyerror!void {
        for (claims) |claim| {
            var owner = try self.collectScopeOwnerMoves(
                claim.def,
                claim.alias,
                body.statements,
                from,
                body.tail,
            );
            errdefer owner.sites.deinit(self.alloc);
            try self.owned_scope_bindings.append(self.alloc, owner);
        }
    }
    fn patternBindsRuntimeOwner(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!bool {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const pattern = self.ir.bodies.pats[pat_id];
        switch (pattern.kind) {
            .binding => |b| {
                if (b.mode != .value) return false;
                const type_id = pattern.ty orelse return false;
                return ownedRuntimeContainerType(try self.typeById(type_id));
            },
            .reference => |reference| return self.patternBindsRuntimeOwner(reference.inner),
            .tuple => |tuple| {
                for (tuple.elements) |element| {
                    if (try self.patternBindsRuntimeOwner(element)) return true;
                }
                return false;
            },
            else => return false,
        }
    }

    /// Allocate `base[idx]` (the emitter renders `@index` with 2 args as `[ ]`).
    fn indexExpr(self: *Lowerer, base: *const ast.Expr, idx: usize) anyerror!*const ast.Expr {
        const idx_lit = try self.allocExpr(ast.Expr{ .lit = .{ .int = @intCast(idx) } });
        var args = try self.alloc.alloc(ast.Expr, 2);
        args[0] = base.*;
        args[1] = idx_lit.*;
        return self.allocExpr(ast.Expr{ .builtin = .{ .name = "index", .args = args } });
    }

    // -------------------------------------------------------------------------
    // Pattern Lowering
    // -------------------------------------------------------------------------

    fn enumVariantFields(
        self: *Lowerer,
        variant_id: ir.spine.EntityId,
    ) ?ir.items.VariantFields {
        const variant_entity = self.ir.graph.symbol_table.get(variant_id) orelse return null;

        if (variant_entity.kind == .variant) {
            if (variant_entity.parent) |enum_id| {
                if (enum_id < self.ir.bodies.bodies.len) {
                    switch (self.ir.bodies.bodies[enum_id]) {
                        .enum_ => |enum_body| {
                            for (enum_body.variants) |variant| {
                                if (std.mem.eql(u8, variant.name, variant_entity.name)) {
                                    return variant.fields;
                                }
                            }
                        },
                        else => {},
                    }
                }
            }
        }

        // Source extraction can resolve `Shape::Circle` to a local placeholder
        // before enum variant entities are linked. Use the unique variant name.
        for (self.ir.bodies.bodies) |body_kind| {
            const enum_body = switch (body_kind) {
                .enum_ => |body| body,
                else => continue,
            };
            for (enum_body.variants) |variant| {
                if (std.mem.eql(u8, variant.name, variant_entity.name)) return variant.fields;
            }
        }
        return null;
    }

    /// Field shape of a variant named `variant_name` inside the enum whose
    /// entity id is `enum_id`. Used when an `enum_variant` expression carries
    /// the owning enum rather than the linked variant entity.
    fn enumVariantFieldsByName(
        self: *Lowerer,
        enum_id: ir.spine.EntityId,
        variant_name: []const u8,
    ) ?ir.items.VariantFields {
        if (enum_id >= self.ir.bodies.bodies.len) return null;
        const enum_body = switch (self.ir.bodies.bodies[enum_id]) {
            .enum_ => |body| body,
            else => return null,
        };
        for (enum_body.variants) |variant| {
            if (std.mem.eql(u8, variant.name, variant_name)) return variant.fields;
        }
        return null;
    }
    fn enumPatternVariant(
        self: *Lowerer,
        def: ir.spine.EntityId,
        fields: []const ir.exprs.FieldPat,
    ) ?[]const u8 {
        const entity = self.ir.graph.symbol_table.get(def) orelse return null;
        if (entity.kind == .variant) return entity.name;
        if (entity.kind != .enum_ or def >= self.ir.bodies.bodies.len) return null;
        const body = switch (self.ir.bodies.bodies[def]) {
            .enum_ => |enum_body| enum_body,
            else => return null,
        };

        var match: ?[]const u8 = null;
        for (body.variants) |variant| {
            const matches = switch (variant.fields) {
                .none => fields.len == 0,
                .tuple => |tuple| fields.len == tuple.len and blk: {
                    for (fields, 0..) |field, i| {
                        var index_buf: [20]u8 = undefined;
                        const index = std.fmt.bufPrint(&index_buf, "{d}", .{i}) catch break :blk false;
                        if (!std.mem.eql(u8, field.field, index)) break :blk false;
                    }
                    break :blk true;
                },
                .named => |named| blk: {
                    if (fields.len > named.len) break :blk false;
                    for (fields) |field| {
                        var found = false;
                        for (named) |named_field| {
                            if (std.mem.eql(u8, field.field, named_field.name)) {
                                found = true;
                                break;
                            }
                        }
                        if (!found) break :blk false;
                    }
                    break :blk true;
                },
            };
            if (!matches) continue;
            if (match != null) return null;
            match = variant.name;
        }
        return match;
    }

    fn lowerExternalVariantPattern(self: *Lowerer, variant: ir.exprs.ExternalVariantPattern) anyerror!ast.Pattern {
        if (!isCowPath(variant.owner.path)) return error.UnsupportedPattern;
        if (!std.mem.eql(u8, variant.variant, "Borrowed") and
            !std.mem.eql(u8, variant.variant, "Owned")) return error.MissingVariantName;
        const fields = try self.alloc.alloc(ast.StructPatternField, variant.fields.len);
        for (variant.fields, 0..) |field, index| {
            const pattern = if (field.pat) |id|
                try self.lowerPattern(id)
            else blk: {
                const name = if (self.current_local_binding_names) |names|
                    names.claimLocalName(&self.ir.graph.symbol_table, field.field)
                else
                    field.field;
                break :blk ast.Pattern{ .binding = try self.alloc.dupe(u8, name) };
            };
            fields[index] = .{ .name = try self.alloc.dupe(u8, field.field), .pat = pattern };
        }
        return .{ .struct_pat = .{
            .name = try self.alloc.dupe(u8, variant.variant),
            .fields = fields,
        } };
    }

    pub fn lowerPattern(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror!ast.Pattern {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;

        const ir_pat = self.ir.bodies.pats[pat_id];

        return switch (ir_pat.kind) {
            .external_variant => |variant| try self.lowerExternalVariantPattern(variant),
            .wildcard => ast.Pattern.wildcard,
            .binding => |b| blk: {
                if (b.name.len == 0) return error.MissingBindingName;
                const binding_name = if (self.current_local_binding_names) |names|
                    try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, b.name)
                else
                    b.name;
                break :blk ast.Pattern{ .binding = try self.alloc.dupe(u8, binding_name) };
            },
            .literal => |l| switch (l) {
                .int => |il| ast.Pattern{ .lit = .{ .int = il.value } },
                .float => |fl| ast.Pattern{ .lit = .{ .float = fl.value } },
                .character => |cl| ast.Pattern{ .lit = .{ .char_lit = @intCast(cl.value) } },
                .string => |sl| ast.Pattern{ .lit = .{ .str = try self.alloc.dupe(u8, sl.bytes) } },
                .byte_array => |ba| ast.Pattern{ .lit = .{ .str = try self.alloc.dupe(u8, ba.items) } },
                .boolean => |b| ast.Pattern{ .lit = .{ .bool_lit = b } },
            },
            .path => |pp| blk: {
                const entity = self.ir.graph.symbol_table.get(pp.def) orelse {
                    return error.MissingDefinition;
                };
                const name = if (pp.variant) |variant| blk_name: {
                    if (variant.len == 0) return error.MissingVariantName;
                    break :blk_name variant;
                } else entity.renamed_to orelse entity.name;
                if (name.len == 0) return error.MissingVariantName;
                break :blk ast.Pattern{ .enum_literal = try self.alloc.dupe(u8, name) };
            },
            .tuple => |tp| blk: {
                var pats = try self.alloc.alloc(ast.Pattern, tp.elements.len);
                for (tp.elements, 0..) |elem_id, i| {
                    pats[i] = try self.lowerPattern(elem_id);
                }
                break :blk ast.Pattern{ .tuple = pats };
            },
            .struct_pat => |sp| blk: {
                const entity = self.ir.graph.symbol_table.get(sp.def) orelse {
                    return error.MissingDefinition;
                };
                if (entity.kind != .struct_ and entity.kind != .enum_ and entity.kind != .variant) {
                    return error.InvalidPatternDefinition;
                }
                const struct_name = if (self.enumPatternVariant(sp.def, sp.fields)) |variant_name|
                    try self.alloc.dupe(u8, variant_name)
                else if (entity.name.len > 0)
                    try self.alloc.dupe(u8, entity.name)
                else
                    return error.MissingPatternName;
                var fields = try self.alloc.alloc(ast.StructPatternField, sp.fields.len);
                for (sp.fields, 0..) |f, i| {
                    if (f.field.len == 0) return error.MissingPatternField;
                    const f_pat = if (f.pat) |p_id|
                        try self.lowerPattern(p_id)
                    else blk_shorthand: {
                        const name = if (self.current_local_binding_names) |names|
                            names.claimLocalName(&self.ir.graph.symbol_table, f.field)
                        else
                            f.field;
                        break :blk_shorthand ast.Pattern{ .binding = try self.alloc.dupe(u8, name) };
                    };
                    // The name here is the POSITION the field occupies in the
                    // variant, not the order this loop reached it: a Zig switch
                    // prong reads `payload.<position>`, and the emitter treats
                    // a lone field named `"0"` bound by name as "the payload
                    // IS that binding" and captures the payload whole. The two
                    // agree only because `sp.fields` lists every position of a
                    // tuple variant, including the ones a wildcard occupies —
                    // `Variant(_, b)` is `[_, b]`, not `[b]`. A pattern that
                    // arrived short renumbers `b` onto position 0 and binds the
                    // whole payload, so a sparse list must not reach here; that
                    // is the extractor's `tuple_struct_pattern` to keep, and
                    // this rename is where a regression in it would surface.
                    const field_name = if (self.enumVariantFields(sp.def)) |variant_fields|
                        switch (variant_fields) {
                            .tuple => try std.fmt.allocPrint(self.alloc, "{d}", .{i}),
                            else => try self.alloc.dupe(u8, f.field),
                        }
                    else
                        try self.alloc.dupe(u8, self.structFieldName(sp.def, f.field));
                    fields[i] = .{
                        .name = field_name,
                        .pat = f_pat,
                    };
                }
                break :blk ast.Pattern{
                    .struct_pat = .{
                        .name = struct_name,
                        .fields = fields,
                    },
                };
            },
            // A nested `a | b` has no `ast.Pattern` tag; match arms expand it
            // through `lowerArmPatterns` before reaching this point.
            .@"or" => return error.UnsupportedPattern,
            .range => |rp| ast.Pattern{ .range_pat = .{
                .lo = try self.lowerRangeBound(rp.lo),
                .hi = try self.lowerRangeBound(rp.hi),
                .inclusive = rp.inclusive,
            } },
            else => return error.UnsupportedPattern,
        };
    }

    /// Whether a match-arm pattern contains a tuple pattern.
    ///
    /// A Zig switch prong has no tuple form. `.{a, b}` is only a `const`
    /// destructuring pattern, so a tuple pattern in an arm emitted an invalid
    /// prong and declared none of the names it mentioned — round 1's fix H in
    /// pattern position rather than value position. Zig destructures a tuple
    /// through a value capture on the switch *subject*, which the arm
    /// lowering does not build, so the honest move is to refuse.
    fn patternHasTupleElement(self: *Lowerer, pat_id: ir.exprs.NodeId, depth: usize) anyerror!bool {
        if (depth >= 64) return error.UnsupportedPattern;
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const fields: []const ir.exprs.FieldPat = switch (self.ir.bodies.pats[pat_id].kind) {
            .tuple => return true,
            .struct_pat => |sp| sp.fields,
            .external_variant => |variant| variant.fields,
            else => return false,
        };
        for (fields) |field| {
            const inner = field.pat orelse continue;
            if (try self.patternHasTupleElement(inner, depth + 1)) return true;
        }
        return false;
    }

    /// Lower one match arm's pattern list. `ast.Pattern` has no or-pattern
    /// tag, so a top-level `a | b` becomes one `ast.Pattern` per alternative;
    /// `MatchArm.patterns` is a slice and the emitter prints those entries
    /// comma-separated inside a single Zig prong.
    fn lowerArmPatterns(self: *Lowerer, pat_ids: []const ir.exprs.NodeId) anyerror![]ast.Pattern {
        var lowered: std.ArrayListUnmanaged(ast.Pattern) = .empty;
        errdefer lowered.deinit(self.alloc);
        for (pat_ids) |pat_id| {
            if (try self.patternHasTupleElement(pat_id, 0)) return error.UnsupportedPattern;
            try self.appendLoweredArmPattern(pat_id, &lowered);
        }
        return lowered.toOwnedSlice(self.alloc);
    }

    fn appendLoweredArmPattern(
        self: *Lowerer,
        pat_id: ir.exprs.NodeId,
        lowered: *std.ArrayListUnmanaged(ast.Pattern),
    ) anyerror!void {
        if (pat_id >= self.ir.bodies.pats.len) return error.MissingPatternNode;
        const alternatives = switch (self.ir.bodies.pats[pat_id].kind) {
            .@"or" => |op| op.alternatives,
            else => return lowered.append(self.alloc, try self.lowerPattern(pat_id)),
        };
        if (alternatives.len == 0) return error.MissingPatternAlternative;
        for (alternatives) |alternative_id| try self.appendLoweredArmPattern(alternative_id, lowered);
    }

    /// Lower one range-pattern bound. Only integer and character bounds reach
    /// a Zig range prong; a null bound stays null (unbounded on that side).
    fn lowerRangeBound(self: *Lowerer, bound: ?ir.exprs.NodeId) anyerror!?ast.Literal {
        const bound_id = bound orelse return null;
        if (bound_id >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        return switch (self.ir.bodies.exprs[bound_id].kind) {
            .literal => |lit| switch (lit) {
                .int => |il| ast.Literal{ .int = il.value },
                .character => |cl| ast.Literal{ .char_lit = @intCast(cl.value) },
                else => error.UnsupportedPattern,
            },
            else => error.UnsupportedPattern,
        };
    }

    /// Extract the capture identifier(s) for a `while let` pattern. Handles
    /// `Some(v)` / `Ok(v)` (struct pattern → its single field's binding) and a
    /// plain `v` (direct binding). Returns null when there is no binding.
    fn lowerWhileCapture(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror![]const []const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return error.InvalidLoopCapture;
        const cap = try self.whileCaptureName(pat_id);
        var out = try self.alloc.alloc([]const u8, 1);
        out[0] = cap;
        return out;
    }

    fn whileCaptureName(self: *Lowerer, pat_id: ir.exprs.NodeId) anyerror![]const u8 {
        if (pat_id >= self.ir.bodies.pats.len) return error.InvalidLoopCapture;
        const pat = self.ir.bodies.pats[pat_id];
        return switch (pat.kind) {
            .binding => |b| blk: {
                if (b.name.len == 0) return error.InvalidLoopCapture;
                const binding_name = if (self.current_local_binding_names) |names|
                    try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, pat_id, b.name)
                else
                    b.name;
                break :blk try self.alloc.dupe(u8, binding_name);
            },
            .reference => |rp| try self.whileCaptureName(rp.inner),
            .struct_pat => |sp| blk: {
                if (sp.fields.len == 0) return error.InvalidLoopCapture;
                const f = sp.fields[0];
                if (f.pat) |fpid| break :blk try self.whileCaptureName(fpid);
                if (f.shorthand and f.field.len > 0) {
                    const name = if (self.current_local_binding_names) |names|
                        names.claimLocalName(&self.ir.graph.symbol_table, f.field)
                    else
                        f.field;
                    break :blk try self.alloc.dupe(u8, name);
                }
                return error.InvalidLoopCapture;
            },
            else => return error.InvalidLoopCapture,
        };
    }

    /// Lower a `let` whose PATTERN names more than one binding: a tuple
    /// (`let (a, b) = ..`) or a named struct (`let S { a, b } = ..`).
    ///
    /// One IR statement becomes several Zig statements here, which is why this
    /// runs ahead of `lowerStmt`: a plain binding is still ONE declaration and
    /// keeps the single-statement spelling that path already emits. Every shape
    /// this does not represent answers false, so the one-binding lowering
    /// refuses it exactly as it did before.
    fn lowerDestructureBindingPrelude(
        self: *Lowerer,
        stmt_id: ir.exprs.NodeId,
        out: *std.ArrayListUnmanaged(ast.Stmt),
        reserved: *std.ArrayListUnmanaged([]const u8),
        claims: *ClaimCollector,
    ) anyerror!bool {
        if (stmt_id >= self.ir.bodies.stmts.len) return error.MissingStatementNode;
        const let_stmt = switch (self.ir.bodies.stmts[stmt_id].kind) {
            .let => |value| value,
            else => return false,
        };
        const init_id = let_stmt.init orelse return false;
        if (let_stmt.pattern >= self.ir.bodies.pats.len) {
            return error.MissingPatternNode;
        }

        var pattern_id = let_stmt.pattern;
        var reference_depth: usize = 0;
        while (true) {
            const pattern = self.ir.bodies.pats[pattern_id].kind;
            switch (pattern) {
                .reference => |reference| {
                    if (reference.inner >= self.ir.bodies.pats.len) {
                        return error.MissingPatternNode;
                    }
                    pattern_id = reference.inner;
                    reference_depth += 1;
                },
                .wildcard => return false,
                .tuple => |tuple| {
                    if (tuple.rest) return false;
                    const source_owner = self.ownerScopeBinding(init_id);
                    const source_type: ?ir.types.Type = if (source_owner) |owner|
                        owner.alias.payload_type
                    else
                        try self.destructureSourceType(let_stmt.pattern, init_id);
                    if (source_type == null and self.tuplePatternBindsReference(tuple)) {
                        return error.MissingTypeId;
                    }
                    const owns_storage = if (source_type) |ty|
                        ownedRuntimeContainerType(ty)
                    else
                        false;
                    var aggregate_type = source_type;
                    for (0..reference_depth) |_| {
                        const reference_type = aggregate_type orelse return error.MissingTypeId;
                        aggregate_type = switch (reference_type) {
                            .reference => |reference| reference.pointee,
                            .raw_ptr => |pointer| pointer.pointee,
                            else => return error.UnsupportedPattern,
                        };
                    }
                    if (owns_storage) {
                        try self.destructureStorageArmable(source_type.?);
                        try self.requireDestructureClaimDefs(tuple, &.{
                            .claims = claims,
                            .drains_carrier = true,
                            .source_type = aggregate_type,
                        });
                    }
                    if (source_owner != null and !owns_storage) return error.UnsupportedExpression;
                    const handle: ?[]const u8 = if (source_owner) |owner| owner.alias.alias_name else null;
                    var carrier_name: []const u8 = "";
                    var base = if (handle) |owner_name|
                        try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, owner_name) })
                    else blk: {
                        const initializer = try self.lowerExpr(init_id);
                        const name = try self.collectorBindingName("_tuple", reserved.items);
                        try out.append(self.alloc, .{ .let_stmt = .{
                            .name = try self.alloc.dupe(u8, name),
                            .init = initializer,
                            .is_mut = owns_storage or (reference_depth == 0 and self.tuplePatternBindsMutRef(tuple)),
                        } });
                        try reserved.append(self.alloc, name);
                        carrier_name = name;
                        break :blk try self.allocExpr(.{ .ident = try self.alloc.dupe(u8, name) });
                    };
                    for (0..reference_depth) |_| {
                        base = try self.allocExpr(.{ .unary_op = .{ .op = .deref, .operand = base } });
                    }
                    try self.emitTupleDestructure(tuple, base, out, &.{
                        .claims = claims,
                        .drains_carrier = owns_storage,
                        .source_type = aggregate_type,
                    });
                    if (handle == null and owns_storage) {
                        try out.append(self.alloc, try self.ownerReleaseStatement(
                            carrier_name,
                            ownerReleasesElements(source_type.?),
                        ));
                    }
                    return true;
                },
                .struct_pat => |struct_pat| return self.lowerNamedStructPatternPrelude(
                    let_stmt,
                    init_id,
                    struct_pat,
                    reference_depth,
                    out,
                    reserved,
                    claims,
                ),
                else => return false,
            }
        }
    }

    /// Lower `let S { .. } = ..` — a NAMED struct pattern with more than the
    /// one positional field `lowerStmt` answers on its own.
    ///
    /// Each field becomes its own binding over a field access on the
    /// initializer, so `mut` is the source's own and every name is claimed
    /// exactly as a tuple element's is. The initializer is reached through ONE
    /// base: a place, when the source gave one, and a fresh local otherwise,
    /// so a right-hand side with side effects still runs exactly once — and so
    /// a move out of that base moves the ORIGINAL storage rather than a copy.
    ///
    /// A field that owns runtime storage is TRANSFERRED out of the base with
    /// `takeOwned` rather than copied, and its scope release is armed on the
    /// handle that then holds the bytes. Copying is a wrong answer here, not a
    /// slow one: the copy and the field it was read from would name one
    /// allocation, and whichever was released second would free the other's.
    fn lowerNamedStructPatternPrelude(
        self: *Lowerer,
        let_stmt: ir.exprs.LetStmt,
        init_id: ir.exprs.NodeId,
        struct_pat: ir.exprs.StructPat,
        reference_depth: usize,
        out: *std.ArrayListUnmanaged(ast.Stmt),
        reserved: *std.ArrayListUnmanaged([]const u8),
        claims: *ClaimCollector,
    ) anyerror!bool {
        // `S { a, .. }` names only some of the struct's fields, and a struct
        // pattern in VALUE position has no statement to drop the rest into, so
        // this pass cannot say which fields went unmentioned. The one-binding
        // lowering keeps it, and refuses it as it did before.
        if (struct_pat.rest) return false;
        // `let FnvHasher(mut hash) = *self;` is a single POSITIONAL field, and
        // it already lowers to one binding over `self.@"0"`.
        if (struct_pat.fields.len == 1 and
            std.mem.eql(u8, struct_pat.fields[0].field, "0")) return false;
        // A tuple struct's fields are positional and a unit struct declares
        // none, so neither is a named field list this pass can read a slot type
        // out of; and an enum variant's fields belong to a union rather than to
        // a struct. All three keep the one-binding lowering and its refusal.
        if (struct_pat.def >= self.ir.bodies.bodies.len) return false;
        const declared_body = switch (self.ir.bodies.bodies[struct_pat.def]) {
            .struct_ => |body| body,
            else => return false,
        };
        if (declared_body.layout != .named) return false;
        const declared_fields: []const ir.items.Field = declared_body.fields;
        // Every field is decided before a single statement exists: a shape this
        // pass cannot spell must leave no half-built program behind.
        for (struct_pat.fields) |field| {
            if (field.field.len == 0) return error.MissingPatternField;
            const inner = field.pat orelse return false;
            if (inner >= self.ir.bodies.pats.len) return error.MissingPatternNode;
            switch (self.ir.bodies.pats[inner].kind) {
                // `S { a: _, b }` binds nothing for `a` and leaves it exactly
                // where the source left it, which is what Rust says.
                .wildcard => {},
                .binding => |binding| {
                    if (binding.name.len == 0) return error.MissingBindingName;
                    // A reference-mode binding borrows the field instead of
                    // taking it, and this pass does not spell that.
                    if (binding.mode != .value) return false;
                    // The slot's type has to come from the declaration, not
                    // from the pattern: a field this struct does not declare
                    // has no type to move or to copy, and guessing one is how a
                    // silent owner copy gets emitted.
                    if (declaredFieldType(declared_fields, field.field) == null) return false;
                },
                // A nested pattern in field position is a shape of its own.
                else => return false,
            }
        }

        const source_type = try self.destructureSourceType(let_stmt.pattern, init_id);
        const owns_storage = if (source_type) |ty|
            ownedRuntimeContainerType(ty)
        else
            false;
        if (owns_storage) try self.destructureStorageArmable(source_type.?);
        var aggregate_type = source_type;
        for (0..reference_depth) |_| {
            const reference_type = aggregate_type orelse return error.MissingTypeId;
            aggregate_type = switch (reference_type) {
                .reference => |reference| reference.pointee,
                .raw_ptr => |pointer| pointer.pointee,
                else => return error.UnsupportedPattern,
            };
        }

        // Every field is DRAINED, whatever the aggregate itself is: the move
        // empties ONE field of the base, and whether that field owns storage is
        // the field's own question, not the aggregate's. Answering it per field
        // is what lets a struct whose own type is not an owner still hand its
        // owned fields on instead of copying them.
        const ctx = TupleDestructureCtx{
            .claims = claims,
            .drains_carrier = true,
            .source_type = aggregate_type,
        };
        // An owning field is moved, and a move is keyed on the binding's own
        // declaration so a later hand-on can find it. Asked over every field
        // BEFORE anything is emitted: asked afterwards it would have to pick
        // between a copy and a half-armed release, and a copy of an owner is
        // two handles on one allocation.
        for (struct_pat.fields) |field| {
            const inner = field.pat.?;
            if (self.ir.bodies.pats[inner].kind == .wildcard) continue;
            const slot = declaredFieldType(declared_fields, field.field).?;
            if (try self.destructureElementOwner(inner, slot, &ctx) == null) continue;
            if (try self.destructureClaimDef(inner) == null) return error.MissingDefinition;
        }

        const base_expr = try self.lowerExpr(init_id);
        var base: ast.Expr = base_expr;
        var carrier_name: ?[]const u8 = null;
        if (!exprIsAddressable(base)) {
            const name = try self.collectorBindingName("_struct", reserved.items);
            try out.append(self.alloc, .{ .let_stmt = .{
                .name = try self.alloc.dupe(u8, name),
                .ty = null,
                .init = base,
                .is_mut = owns_storage or reference_depth != 0,
            } });
            try reserved.append(self.alloc, name);
            carrier_name = name;
            base = .{ .ident = try self.alloc.dupe(u8, name) };
        }
        for (0..reference_depth) |_| {
            base = (try self.allocExpr(.{ .unary_op = .{ .op = .deref, .operand = &base } })).*;
        }

        for (struct_pat.fields) |field| {
            const inner = field.pat.?;
            if (self.ir.bodies.pats[inner].kind == .wildcard) continue;
            const binding = self.ir.bodies.pats[inner].kind.binding;
            const binding_name = if (self.current_local_binding_names) |names|
                try names.claimPatternName(self.alloc, &self.ir.graph.symbol_table, inner, binding.name)
            else
                binding.name;
            const slot = declaredFieldType(declared_fields, field.field).?;
            const access = ast.Expr{ .field_access = .{
                .target = try self.allocExpr(base),
                .field_name = try self.alloc.dupe(
                    u8,
                    self.structFieldName(struct_pat.def, field.field),
                ),
            } };
            try self.emitDestructureBinding(inner, binding, binding_name, access, slot, out, &ctx);
        }
        // The base the fields were read out of keeps whatever the pattern did
        // not name. Only a base whose OWN type is an owner has a release here;
        // one that is not released nothing, which is the same rule every other
        // user-struct binding already follows.
        if (carrier_name) |name| {
            if (owns_storage) try out.append(
                self.alloc,
                try self.ownerReleaseStatement(name, ownerReleasesElements(source_type.?)),
            );
        }
        return true;
    }

    fn currentClosureBindingName(
        self: *Lowerer,
        source_name: []const u8,
    ) []const u8 {
        if (self.current_local_binding_names) |names| {
            for (names.local_defs) |def| {
                const entity = self.ir.graph.symbol_table.get(def) orelse continue;
                const matches_renamed = if (entity.renamed_to) |renamed|
                    std.mem.eql(u8, renamed, source_name)
                else
                    false;
                if (!std.mem.eql(u8, entity.name, source_name) and !matches_renamed) continue;
                return names.emitted_by_entity.get(def) orelse source_name;
            }
        }
        return source_name;
    }

    fn registerLocalClosureStatement(
        self: *Lowerer,
        stmt_id: ir.exprs.NodeId,
        statements: *std.ArrayListUnmanaged(ast.Stmt),
        reserved: *std.ArrayListUnmanaged([]const u8),
    ) anyerror!bool {
        if (stmt_id >= self.ir.bodies.stmts.len) return error.MissingStatementNode;
        const let_stmt = switch (self.ir.bodies.stmts[stmt_id].kind) {
            .let => |value| value,
            else => return false,
        };
        const init_id = let_stmt.init orelse return false;
        if (init_id >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
        const closure = switch (self.ir.bodies.exprs[init_id].kind) {
            .closure => |value| value,
            else => return false,
        };
        const name = try self.patternName(let_stmt.pattern);
        if (std.mem.eql(u8, name, "_")) return error.UnsupportedExpression;
        var snapshots: std.ArrayListUnmanaged(LocalClosureCaptureSnapshot) = .empty;
        defer snapshots.deinit(self.alloc);
        for (closure.captures) |capture| {
            if (capture.mode != .by_value) continue;
            const source_name = self.active_closure_capture_overrides.get(capture.name) orelse
                self.currentClosureBindingName(capture.name);
            const base_name = try std.fmt.allocPrint(
                self.alloc,
                "__r2z_capture_{s}_{s}",
                .{ name, capture.name },
            );
            const snapshot_name = try self.collectorBindingName(base_name, reserved.items);
            const resolved_type = try self.closureCapturePayloadType(capture, source_name);
            const owns_runtime_storage = ownedRuntimeContainerType(resolved_type);
            const payload_type: ?ir.types.Type = if (owns_runtime_storage) resolved_type else null;
            if (owns_runtime_storage) {
                try self.appendCaptureSnapshot(
                    statements,
                    snapshot_name,
                    capture,
                    source_name,
                    resolved_type,
                );
            } else {
                try statements.append(self.alloc, .{ .let_stmt = .{
                    .name = snapshot_name,
                    .init = .{ .ident = try self.alloc.dupe(u8, source_name) },
                    .is_mut = closure.trait == .fn_mut,
                } });
            }
            try reserved.append(self.alloc, snapshot_name);
            try snapshots.append(self.alloc, .{
                .source_name = capture.name,
                .snapshot_name = snapshot_name,
                .payload_type = payload_type,
            });
        }
        try self.local_closures.put(self.alloc, name, closure);
        if (snapshots.items.len > 0) {
            try self.local_closure_snapshots.put(
                self.alloc,
                name,
                try snapshots.toOwnedSlice(self.alloc),
            );
        }
        return true;
    }

    fn currentClosureBindingDef(self: *Lowerer, source_name: []const u8) ?ir.spine.EntityId {
        const names = self.current_local_binding_names orelse return null;
        for (names.local_defs) |def| {
            const entity = self.ir.graph.symbol_table.get(def) orelse continue;
            if (std.mem.eql(u8, entity.name, source_name)) return def;
            if (entity.renamed_to) |renamed| {
                if (std.mem.eql(u8, renamed, source_name)) return def;
            }
        }
        return null;
    }

    fn closureCapturePayloadType(
        self: *Lowerer,
        capture: ir.exprs.Capture,
        source_name: []const u8,
    ) anyerror!ir.types.Type {
        if (self.typeById(capture.ty) catch null) |declared| {
            if (declared != .unsupported) return declared;
        }
        for ([_][]const u8{ capture.name, source_name }) |candidate_name| {
            const def = self.currentClosureBindingDef(candidate_name) orelse continue;
            if (try self.valueEntityType(def)) |declared| {
                if (declared != .unsupported) return declared;
            }
        }
        if (self.active_owned_capture_move) |active| {
            for (active.entries) |entry| {
                if (std.mem.eql(u8, entry.alias.source_name, capture.name) and
                    std.mem.eql(u8, entry.alias.alias_name, source_name))
                {
                    return entry.alias.payload_type;
                }
            }
        }
        for (self.owned_scope_bindings.items) |binding| {
            if (std.mem.eql(u8, binding.alias.source_name, capture.name) and
                std.mem.eql(u8, binding.alias.alias_name, source_name))
            {
                return binding.alias.payload_type;
            }
        }
        return error.UnsupportedCaptureType;
    }

    /// Whether a local closure defined in this block writes to `name` itself.
    ///
    /// A closure body is not part of the block's statement list — it is
    /// emitted at the closure's call site — so `astMutatesBinding` cannot see
    /// an assignment inside one, and the downgrade would turn a `var` the
    /// closure writes into a `const`.
    ///
    /// Only a `&mut` capture reaches the outer binding. A by-value capture is
    /// copied into a `__r2z_capture_*` snapshot where the closure was created,
    /// and the closure body mutates that copy, so the original is never
    /// assigned: counting it here kept a `var` nothing writes, and Zig rejects
    /// a `var` that is never mutated.
    fn blockCaptureWritesBinding(
        self: *Lowerer,
        statements: []const ir.exprs.NodeId,
        name: []const u8,
    ) anyerror!bool {
        for (statements) |stmt_id| {
            if (stmt_id >= self.ir.bodies.stmts.len) return error.MissingStatementNode;
            const let_stmt = switch (self.ir.bodies.stmts[stmt_id].kind) {
                .let => |value| value,
                else => continue,
            };
            const init_id = let_stmt.init orelse continue;
            if (init_id >= self.ir.bodies.exprs.len) return error.MissingExpressionNode;
            const closure = switch (self.ir.bodies.exprs[init_id].kind) {
                .closure => |value| value,
                else => continue,
            };
            for (closure.captures) |capture| {
                if (capture.mode != .by_mut_ref) continue;
                if (std.mem.eql(u8, capture.name, name)) return true;
            }
        }
        return false;
    }

    fn astMutationTarget(expression: ast.Expr, name: []const u8, depth: usize) error{InvalidAstTraversal}!bool {
        if (depth >= 256) return error.InvalidAstTraversal;
        return switch (expression) {
            .ident => |identifier| std.mem.eql(u8, identifier, name),
            .field_access => |field| astMutationTarget(field.target.*, name, depth + 1),
            .unary_op => |unary| if (unary.op == .addr_of or unary.op == .deref)
                // `r2z.ops.assign(&t, v)` reaches the target through an
                // address-of, which the old walk did not follow, so a
                // big-integer `t += v` looked unmutated.
                astMutationTarget(unary.operand.*, name, depth + 1)
            else
                false,
            .builtin => |builtin| if (std.mem.eql(u8, builtin.name, "index") and builtin.args.len > 0)
                astMutationTarget(builtin.args[0], name, depth + 1)
            else
                false,
            else => false,
        };
    }

    fn astMutatesBinding(value: anytype, name: []const u8, depth: usize) error{InvalidAstTraversal}!bool {
        if (depth >= 256) return error.InvalidAstTraversal;
        const T = @TypeOf(value);
        if (T == ast.Type) return false;
        if (T == ast.Stmt) {
            if (value == .assign and try astMutationTarget(value.assign.target, name, depth + 1)) return true;
        }
        if (T == ast.Expr) {
            if (value == .unary_op and value.unary_op.op == .addr_of and
                try astMutationTarget(value.unary_op.operand.*, name, depth + 1)) return true;
            if (value == .call and value.call.callee.* == .field_access and
                try astMutationTarget(value.call.callee.field_access.target.*, name, depth + 1)) return true;
        }
        switch (@typeInfo(T)) {
            .pointer => |pointer| {
                if (pointer.child == u8) return false;
                switch (pointer.size) {
                    .one => return astMutatesBinding(value.*, name, depth + 1),
                    .slice => for (value) |element| {
                        if (try astMutatesBinding(element, name, depth + 1)) return true;
                    },
                    else => {},
                }
            },
            .optional => if (value) |present| {
                return astMutatesBinding(present, name, depth + 1);
            },
            .@"struct" => |structure| inline for (structure.fields) |field| {
                if (try astMutatesBinding(@field(value, field.name), name, depth + 1)) return true;
            },
            .@"union" => return switch (value) {
                inline else => |payload| astMutatesBinding(payload, name, depth + 1),
            },
            .array => for (value) |element| {
                if (try astMutatesBinding(element, name, depth + 1)) return true;
            },
            else => {},
        }
        return false;
    }

    pub fn lowerBlock(self: *Lowerer, be: ir.exprs.BlockExpr) anyerror!ast.Block {
        const previous_owner_prelude = self.current_owner_prelude;
        const previous_owner_reserved = self.current_owner_reserved;
        const argument_block = self.expected_argument_expr_id != null;
        const callable_body = self.callable_body_block;
        self.callable_body_block = false;
        defer {
            self.current_owner_prelude = previous_owner_prelude;
            self.current_owner_reserved = previous_owner_reserved;
        }
        self.current_owner_prelude = null;
        self.current_owner_reserved = null;

        var stmts_list: std.ArrayListUnmanaged(ast.Stmt) = .empty;
        defer stmts_list.deinit(self.alloc);
        // Every block owns the scope of the bindings it introduces, so the
        // owner stack unwinds with this block: what this block pushed is what
        // this block releases, and an enclosing block's entries stay live for
        // the whole of it.
        const owner_scope_start = self.owned_scope_bindings.items.len;
        defer {
            for (self.owned_scope_bindings.items[owner_scope_start..]) |*binding| {
                binding.sites.deinit(self.alloc);
            }
            self.owned_scope_bindings.shrinkRetainingCapacity(owner_scope_start);
        }
        var reserved_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer reserved_names.deinit(self.alloc);
        var shadow_names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer shadow_names.deinit(self.alloc);
        var promoted_argument_tail: ?*const ast.Expr = null;
        const parent_reserved_start = if (previous_owner_reserved) |parent|
            parent.items.len
        else
            0;
        if (previous_owner_reserved) |parent| {
            try reserved_names.appendSlice(self.alloc, parent.items);
        }

        const previous_shadow_scope = self.current_shadow_scope;
        var shadow_scope: ShadowScope = .{
            .names = shadow_names.items,
            .parent = previous_shadow_scope,
        };
        self.current_shadow_scope = &shadow_scope;
        defer self.current_shadow_scope = previous_shadow_scope;
        var visible_shadow_scope = previous_shadow_scope;
        while (visible_shadow_scope) |scope| {
            for (scope.names) |name| {
                try reserved_names.append(self.alloc, name);
            }
            visible_shadow_scope = scope.parent;
        }
        if (self.current_module_id) |module_id| {
            if (self.moduleForEntity(module_id)) |module| {
                for (module.items) |item_id| {
                    if (self.ir.graph.symbol_table.get(item_id)) |item| {
                        try reserved_names.append(
                            self.alloc,
                            item.renamed_to orelse item.name,
                        );
                    }
                }
            }
        }

        for (self.current_capture_names) |capture_name| {
            try reserved_names.append(self.alloc, capture_name);
        }
        try self.appendParameterNames(&reserved_names);
        if (self.current_callable_name) |name| {
            try reserved_names.append(self.alloc, name);
        }
        try self.appendCollectorImportAliases(&reserved_names);
        try self.appendBlockBindingNames(be.statements, &reserved_names);

        for (be.statements, 0..) |stmt_id, index| {
            if (stmt_id >= self.ir.bodies.stmts.len) return error.MissingStatementNode;
            switch (self.ir.bodies.stmts[stmt_id].kind) {
                .item => |item_id| {
                    const item = self.ir.graph.symbol_table.get(item_id) orelse {
                        return error.MissingEntityId;
                    };
                    // A block-local `fn` is a DECLARATION, not a statement:
                    // Zig has no nested functions, so it is hoisted to the
                    // module beside this file's other declarations (see
                    // `appendBlockLocalFunctions`) and contributes nothing
                    // here. A parent that is a FUNCTION is what identifies it,
                    // so an impl method — which reaches this file the ordinary
                    // way — is untouched.
                    if (item.kind == .static_) continue;
                    if (item.kind == .fn_ and item.parent != null and
                        (self.ir.graph.symbol_table.get(item.parent.?) orelse continue).kind == .fn_) continue;
                },
                else => {},
            }
            if (try self.registerLocalClosureStatement(stmt_id, &stmts_list, &reserved_names)) continue;
            var statement_prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
            defer statement_prelude.deinit(self.alloc);
            var statement_reserved: std.ArrayListUnmanaged([]const u8) = .empty;
            defer statement_reserved.deinit(self.alloc);
            const reserved_start = reserved_names.items.len;
            try statement_reserved.appendSlice(self.alloc, reserved_names.items);

            var destructure_claims: ClaimCollector = .empty;
            defer destructure_claims.deinit(self.alloc);
            const destructured = try self.lowerDestructureBindingPrelude(
                stmt_id,
                &statement_prelude,
                &statement_reserved,
                &destructure_claims,
            );
            if (destructured) {
                for (statement_prelude.items) |prelude_stmt| {
                    try stmts_list.append(self.alloc, prelude_stmt);
                    try self.appendCollectorStmtIdentifiers(prelude_stmt, &statement_reserved);
                    try self.appendShadowBindingName(prelude_stmt, &shadow_names);
                }
                shadow_scope.names = shadow_names.items;
                try reserved_names.appendSlice(self.alloc, statement_reserved.items[reserved_start..]);
                try self.installDestructureOwnerMoves(destructure_claims.items, be, index + 1);
                continue;
            }

            const previous_statement_prelude = self.current_owner_prelude;
            const previous_statement_reserved = self.current_owner_reserved;
            self.current_owner_prelude = &statement_prelude;
            self.current_owner_reserved = &statement_reserved;
            const stmt = lowered_stmt: {
                defer {
                    self.current_owner_prelude = previous_statement_prelude;
                    self.current_owner_reserved = previous_statement_reserved;
                }
                break :lowered_stmt try self.lowerStmt(stmt_id);
            };

            if (argument_block) {
                switch (stmt) {
                    .expr_stmt => |expr| switch (expr.*) {
                        .unit => continue,
                        .block => |nested| {
                            // Flattened only when the block IS an owner prelude
                            // — the wrapper a call puts around the value it
                            // returns once it has had to declare a binding to
                            // return. That is an identity question, and the
                            // `let`-then-`defer` shape it used to be tested by
                            // no longer separates it from an ordinary Rust
                            // block that declares an owner and drops it at the
                            // end of its own scope: flattening THAT would move
                            // the release out of the scope that owns it.
                            if (nested.expr != null and self.isOwnerPrelude(nested.stmts)) {
                                for (nested.stmts) |nested_stmt| {
                                    try stmts_list.append(self.alloc, nested_stmt);
                                    try self.appendCollectorStmtIdentifiers(
                                        nested_stmt,
                                        &statement_reserved,
                                    );
                                }
                                if (nested.expr) |nested_expr| {
                                    if (be.tail == null and index + 1 == be.statements.len) {
                                        std.debug.assert(promoted_argument_tail == null);
                                        promoted_argument_tail = nested_expr;
                                    } else {
                                        const nested_stmt: ast.Stmt = .{
                                            .expr_stmt = nested_expr,
                                        };
                                        try stmts_list.append(self.alloc, nested_stmt);
                                        try self.appendCollectorStmtIdentifiers(
                                            nested_stmt,
                                            &statement_reserved,
                                        );
                                    }
                                }
                                try reserved_names.appendSlice(
                                    self.alloc,
                                    statement_reserved.items[reserved_start..],
                                );
                                continue;
                            }
                        },
                        else => {},
                    },
                    else => {},
                }
            }

            for (statement_prelude.items) |prelude_stmt| {
                try stmts_list.append(self.alloc, prelude_stmt);
                try self.appendCollectorStmtIdentifiers(prelude_stmt, &statement_reserved);
            }
            try stmts_list.append(self.alloc, stmt);
            // The binding has been lowered, so its emitted name is claimed. The
            // release goes in right after it and the move set goes on the stack
            // for everything this block lowers from here on — which is exactly
            // the window in which this binding can still be moved.
            try self.appendLexicalOwnerRelease(be, index, stmt_id, &stmts_list);
            try self.appendCollectorStmtIdentifiers(stmt, &statement_reserved);
            try self.appendShadowBindingName(stmt, &shadow_names);
            shadow_scope.names = shadow_names.items;
            try reserved_names.appendSlice(self.alloc, statement_reserved.items[reserved_start..]);
        }

        // The label a flattened statements-only tail carried, adopted by the
        // block its statements land in. Null unless one did.
        var flattened_tail_label: ?[]const u8 = null;
        const tail_expr = if (be.tail) |t_id| blk: {
            var tail_prelude: std.ArrayListUnmanaged(ast.Stmt) = .empty;
            defer tail_prelude.deinit(self.alloc);
            var tail_reserved: std.ArrayListUnmanaged([]const u8) = .empty;
            defer tail_reserved.deinit(self.alloc);
            const reserved_start = reserved_names.items.len;
            try tail_reserved.appendSlice(self.alloc, reserved_names.items);

            const previous_tail_prelude = self.current_owner_prelude;
            const previous_tail_reserved = self.current_owner_reserved;
            self.current_owner_prelude = &tail_prelude;
            self.current_owner_reserved = &tail_reserved;
            const lowered_tail = lowered: {
                defer {
                    self.current_owner_prelude = previous_tail_prelude;
                    self.current_owner_reserved = previous_tail_reserved;
                }
                break :lowered try self.lowerExpr(t_id);
            };
            for (tail_prelude.items) |prelude_stmt| {
                try stmts_list.append(self.alloc, prelude_stmt);
                try self.appendCollectorStmtIdentifiers(prelude_stmt, &tail_reserved);
            }
            // A tail that lowered to a body and not to a value is not a Zig tail
            // expression: a block with nothing to evaluate has no value to
            // hand back. Its statements belong to the list they were lowered
            // into, in the order they were lowered, so a synthesized unit body
            // — a `let` and the `defer` release that unwinds it — becomes a
            // canonical statement body with that release still LIFO against the
            // binding it frees. A block that DOES carry a value keeps the
            // handling above and below untouched: that is the owner-prelude
            // wrapper a call puts around the value it returns, and flattening
            // it would move the release out of the scope that owns it.
            //
            // A LABELLED tail is not that synthesized unit body, and its label
            // is not decoration. A guarded `match` lowers to a labelled value
            // block: it has no tail of its own because each arm leaves it
            // through `break :<label> <value>`, so the label and the exits stand
            // or fall together. Moving the chain's statements into the block
            // that holds them takes the label with them, and that is sound
            // exactly when the block they land in is one Zig writes a label on.
            // It is the repair `test/crates/compat`'s `or_payload` needed: the
            // chain is a branch of the conditional whose value the function
            // returns, so its label lands on that branch and every arm's exit
            // reaches a block that is actually there. Flattening without one
            // emitted `break n +% 1;` into a bare switch prong, which Zig read
            // as a break out of a loop the chain is not inside.
            //
            // Two scopes cannot take the label. One is a source block that
            // carries a label of its own: two labels and one slot, so the chain
            // keeps its own. The other is a FUNCTION BODY, which Zig writes as
            // `{ … }` with nothing in front of it — a label adopted there is a
            // label no block declares. `test/crates/guarded-owned-fallthrough`'s
            // `guarded_fallthrough` has a guarded match as its whole body, and
            // adopting the label onto the body left every arm's exit naming
            // nothing: the package emitted a bare
            // `break r2z.alloc.takeOwned(…);` and Zig rejected it as a break
            // outside any loop.
            // Both keep the chain WHOLE. A labelled block is a valid statement,
            // and it is read back off the end of the body's statement list by
            // `promoteTrailingMatch` (a free function) or `promoteGuardChainTail`
            // (a method) — which bind it to a local rather than move it into the
            // tail. `const __r2z_chain = <label>: { … }; return __r2z_chain;`
            // keeps the label on a block that IS in a position Zig writes one,
            // and hands the value back by name.
            //
            // It is NOT promoted into the tail, and the earlier comment here
            // claimed it should be: `emitFnDecl` writes that tail as
            // `return <expr>`, so promoting produced `return <label>: { … };`,
            // and a labelled block is legal in Zig only as an `if`/`else`
            // branch. It is unspellable there — and unspellable twice over,
            // because the tail is emitted through `emitExpr`, whose
            // `EmitContext` is empty, so the chain's own `break :<label>`
            // resolved against no exit scope and printed as a BARE `break`.
            //
            // The chain is still recognised by what only it has — the
            // `unreachable` that closes an ordered chain — rather than by "a
            // labelled block with no tail": a label alone does not say the
            // value can be handed back, and only a chain closes over its own
            // exits.
            var statements_only_tail = false;
            if (lowered_tail == .block and lowered_tail.block.expr == null) {
                statements_only_tail = true;
                const keep_whole = lowered_tail.block.label != null and
                    (be.labelled != null or callable_body) and
                    isGuardChainBlock(lowered_tail);
                if (keep_whole) {
                    try stmts_list.append(self.alloc, .{
                        .expr_stmt = try self.allocExpr(lowered_tail),
                    });
                } else {
                    flattened_tail_label = lowered_tail.block.label;
                    for (lowered_tail.block.stmts) |tail_stmt| {
                        try stmts_list.append(self.alloc, tail_stmt);
                        try self.appendCollectorStmtIdentifiers(tail_stmt, &tail_reserved);
                    }
                }
            }
            try reserved_names.appendSlice(self.alloc, tail_reserved.items[reserved_start..]);
            if (statements_only_tail) break :blk null;
            break :blk try self.allocExpr(lowered_tail);
        } else promoted_argument_tail;

        if (previous_owner_reserved) |parent| {
            try parent.appendSlice(self.alloc, reserved_names.items[parent_reserved_start..]);
        }

        const stmts = try stmts_list.toOwnedSlice(self.alloc);
        const label = if (be.labelled) |l| try self.alloc.dupe(u8, l) else flattened_tail_label;
        const block: ast.Block = .{ .label = label, .stmts = stmts, .expr = tail_expr };
        for (stmts) |*statement| {
            if (statement.* == .let_stmt and statement.let_stmt.is_mut and
                !try self.blockCaptureWritesBinding(be.statements, statement.let_stmt.name))
            {
                statement.let_stmt.is_mut = try astMutatesBinding(block, statement.let_stmt.name, 0);
            }
        }
        return block;
    }
};

fn expectBlanketMatchIgnoresUnrelated(comptime unrelated: enum { trait_, method }) !void {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var graph = ir.graph.CrateGraph.init(alloc);
    const Fixture = struct {
        fn entity(
            target: *ir.graph.CrateGraph,
            kind: ir.spine.EntityKind,
            name: []const u8,
            parent: ?ir.spine.EntityId,
        ) !ir.spine.EntityId {
            return target.symbol_table.add(.{
                .id = 0,
                .kind = kind,
                .name = name,
                .name_owned = false,
                .span = .{ .start_line = 1, .start_col = 1, .end_line = 1, .end_col = 2 },
                .visibility = .private,
                .parent = parent,
                .resolved = null,
                .renamed_to = null,
                .attributes = &.{},
            });
        }
    };
    const trait_id = try Fixture.entity(&graph, .trait_, "ToHex", null);
    // A homonym makes identity, rather than the trait's leaf name, decisive.
    const other_trait = try Fixture.entity(&graph, .trait_, "ToHex", null);
    const requested = try Fixture.entity(&graph, .method_ref, "encode_hex", trait_id);
    const wanted = try Fixture.entity(&graph, .impl_, "wanted", null);
    const wanted_method = try Fixture.entity(&graph, .fn_, "encode_hex", wanted);
    const rival = try Fixture.entity(&graph, .impl_, "rival", null);
    const rival_method = try Fixture.entity(
        &graph,
        .fn_,
        if (unrelated == .trait_) "encode_hex" else "decode_hex",
        rival,
    );
    const self_type: ir.types.Type = .{ .path = .{ .segments = &.{.{ .name = "U", .id = null }} } };
    const generics: ir.types.Generics = .{
        .params = &.{.{ .type_ = .{ .name = "U", .bounds = &.{} } }},
        .where_clauses = &.{},
    };
    const wanted_path = [_]ir.types.PathSegment{.{ .name = "ToHex", .id = trait_id }};
    const rival_path = [_]ir.types.PathSegment{.{
        .name = "ToHex",
        .id = if (unrelated == .trait_) other_trait else trait_id,
    }};
    const wanted_items = [_]ir.spine.EntityId{wanted_method};
    const rival_items = [_]ir.spine.EntityId{rival_method};
    const rows = try alloc.alloc(ir.bodies.BodyKind, graph.symbol_table.count());
    for (rows) |*row| row.* = .none;
    rows[wanted] = .{ .impl_ = .{
        .self_ty = self_type,
        .trait_path = .{ .segments = &wanted_path },
        .generics = generics,
        .assoc_items = &wanted_items,
    } };
    rows[rival] = .{ .impl_ = .{
        .self_ty = self_type,
        .trait_path = .{ .segments = &rival_path },
        .generics = generics,
        .assoc_items = &rival_items,
    } };
    const rust_ir: ir.RustIr = .{
        .crate_name = "blanket_method_match",
        .graph = graph,
        .bodies = .{
            .exprs = &.{},
            .stmts = &.{},
            .pats = &.{},
            .types = &.{},
            .bodies = rows,
        },
    };
    const lowerer = Lowerer.init(alloc, &rust_ir, null);
    switch (lowerer.blanketImplForMethod(requested)) {
        .unique => |selected| try std.testing.expectEqual(wanted, selected),
        .none, .ambiguous => return error.ExpectedUniqueBlanketMethodMatch,
    }
}

test "blanket method matching ignores same-name methods from another trait" {
    try expectBlanketMatchIgnoresUnrelated(.trait_);
}

test "blanket method matching ignores other associated methods of the same trait" {
    try expectBlanketMatchIgnoresUnrelated(.method);
}
